// ---- Cooperative query budget (T15 server hardening) -------------------------
//
// A thread-local, cooperatively-checked budget installed by the
// `*_with_budget` entry points in lib.rs. Checked at COARSE sites only: operator
// entry (`eval_graph_pattern`) and once per outer iteration / key group of the
// big row-producing loops — never in inner loops. Evaluation is synchronous on
// the installing thread (rayon offloads block the caller), so a thread-local
// suffices; the rayon-parallel branches use a captured `Limits` snapshot to cap
// their own work and the next on-thread check converts that into the error.
pub(crate) mod budget {
    use crate::QueryBudget;
    use sparq_core::dict::Id;
    use std::cell::Cell;
    use std::ptr::NonNull;
    use std::sync::atomic::{AtomicBool, Ordering};

    /// Copyable view of a cancellation flag owned by the installed [`QueryBudget`].
    ///
    /// The [`Guard`] lifetime keeps that budget (and therefore its `Arc<AtomicBool>`)
    /// alive until the pointer has been cleared from the thread-local state. Rayon
    /// snapshots are consumed only by scoped parallel iterators that join before the
    /// guard is dropped. The pointer is dereferenced only for atomic loads.
    #[derive(Clone, Copy)]
    struct CancelPtr(NonNull<AtomicBool>);

    // SAFETY: `AtomicBool` is `Sync`; moving this shared pointer to a worker is
    // sound because it is only dereferenced for atomic loads while `Guard` keeps
    // the owning `Arc` alive, including across scoped rayon work.
    unsafe impl Send for CancelPtr {}
    // SAFETY: `AtomicBool` is `Sync`; all shared access through `CancelPtr` is an
    // atomic load, and `Guard` keeps the allocation alive until worker joins finish.
    unsafe impl Sync for CancelPtr {}

    /// Bytes one id-level binding cell occupies in a materialised `Row`. The
    /// byte-accounted cap ([OPUS-4.8] sq-s5is) costs the id-level working set as
    /// `rows × width × BYTES_PER_ID` — a portable LOWER bound on real heap (it
    /// ignores allocator overhead / `SmallVec` inline-vs-spill), conservative in the
    /// same direction the row cap is.
    pub(crate) const BYTES_PER_ID: usize = std::mem::size_of::<Id>();

    /// The installed limits, flattened for a cheap per-check read.
    #[derive(Clone, Copy)]
    pub(crate) struct Limits {
        on: bool,
        #[cfg(not(target_arch = "wasm32"))]
        deadline: Option<std::time::Instant>,
        max_rows: usize,
        /// [OPUS-4.8] (sq-s5is) Byte ceiling on the estimated working set; `usize::MAX`
        /// when no byte cap is set. Compared against `rows × byte_width + extra_bytes`.
        max_bytes: usize,
        /// [OPUS-4.8] (sq-s5is) Bytes per row of the working set CURRENTLY being checked
        /// — `width(in ids) × BYTES_PER_ID`. Set per operator by [`set_width`] so the
        /// row-count check sites also price WIDTH (the dimension the row cap misses). A
        /// scalar/streaming path that never sets a width leaves this at `BYTES_PER_ID`
        /// (one id per "row"), so the byte cap degrades to the row cap there, never wider.
        byte_width: usize,
        /// [OPUS-4.8] (sq-s5is) Bytes of query-computed terms interned into the per-query
        /// local vocabulary (BIND / aggregate / CONSTRUCT scratch) — the NON-row dimension
        /// the row cap also misses. A running high-water sum, added to the working-set
        /// estimate on every check.
        extra_bytes: usize,
        cancel: Option<CancelPtr>,
    }

    const OFF: Limits = Limits {
        on: false,
        #[cfg(not(target_arch = "wasm32"))]
        deadline: None,
        max_rows: usize::MAX,
        max_bytes: usize::MAX,
        byte_width: BYTES_PER_ID,
        extra_bytes: 0,
        cancel: None,
    };

    impl Limits {
        /// `rows × byte_width + extra_bytes`, saturating — the estimated working-set
        /// byte size compared against `max_bytes`. [OPUS-4.8] (sq-s5is)
        #[inline]
        fn bytes(&self, rows: usize) -> usize {
            rows.saturating_mul(self.byte_width).saturating_add(self.extra_bytes)
        }

        /// WHY the limits are hit at `rows`, or `None` when they are not — the pure (no
        /// thread-local) counterpart of [`exhausted`]'s reason, for rayon closures where
        /// the installing thread's sticky flag is out of reach. The reasons are the SAME
        /// strings [`exhausted`] records, so a worker can raise EXACTLY the error
        /// [`check`] would rather than inventing one (or guessing a result). [SONNET-4.6]
        /// (sq-qk6ac)
        #[cfg_attr(not(feature = "parallel"), allow(dead_code))]
        #[inline]
        pub(crate) fn why(&self, rows: usize) -> Option<&'static str> {
            if !self.on {
                return None;
            }
            if rows > self.max_rows {
                return Some("max-rows");
            }
            if self.bytes(rows) > self.max_bytes {
                return Some("max-bytes");
            }
            #[cfg(not(target_arch = "wasm32"))]
            if self.deadline.is_some_and(|d| std::time::Instant::now() >= d) {
                return Some("timeout");
            }
            if let Some(cancel) = self.cancel {
                // SAFETY: `CancelPtr`'s invariant and the lifetime-bound `Guard`
                // keep the `AtomicBool` alive for this scoped snapshot load.
                if unsafe { cancel.0.as_ref() }.load(Ordering::Relaxed) {
                    return Some("cancelled");
                }
            }
            None
        }

        /// Pure (no thread-local) exhaustion test for rayon closures, where the
        /// installing thread's sticky flag is out of reach: a worker that sees
        /// `hit` stops producing, and the caller's next on-thread check fires
        /// (the deadline is global time; a hit row/byte cap leaves the snapshot's
        /// estimate over the limit). Only the rayon-parallel branches call this
        /// (and `snapshot`); the non-parallel (wasm) build compiles them out.
        #[cfg_attr(not(feature = "parallel"), allow(dead_code))]
        #[inline]
        pub(crate) fn hit(&self, rows: usize) -> bool {
            self.why(rows).is_some()
        }
    }

    thread_local! {
        static ACTIVE: Cell<Limits> = const { Cell::new(OFF) };
        static EXCEEDED: Cell<Option<&'static str>> = const { Cell::new(None) };
    }

    /// Clears the budget when the `*_with_budget` entry point returns (also on
    /// error/unwind, so a poisoned thread never leaks a stale budget).
    pub(crate) struct Guard<'a> {
        _budget: std::marker::PhantomData<&'a QueryBudget>,
        _not_send: std::marker::PhantomData<std::rc::Rc<()>>,
    }
    impl Drop for Guard<'_> {
        fn drop(&mut self) {
            ACTIVE.with(|a| a.set(OFF));
            EXCEEDED.with(|e| e.set(None));
        }
    }

    pub(crate) fn install(b: &QueryBudget) -> Guard<'_> {
        let cancel = b
            .cancel
            .as_ref()
            .map(|flag| CancelPtr(NonNull::from(flag.as_ref())));
        #[cfg(not(target_arch = "wasm32"))]
        let on = b.deadline.is_some()
            || b.max_rows.is_some()
            || b.max_bytes.is_some()
            || cancel.is_some();
        #[cfg(target_arch = "wasm32")]
        let on = b.max_rows.is_some() || b.max_bytes.is_some() || cancel.is_some();
        ACTIVE.with(|a| {
            a.set(Limits {
                on,
                #[cfg(not(target_arch = "wasm32"))]
                deadline: b.deadline,
                max_rows: b.max_rows.unwrap_or(usize::MAX),
                max_bytes: b.max_bytes.unwrap_or(usize::MAX),
                byte_width: BYTES_PER_ID,
                extra_bytes: 0,
                cancel,
            })
        });
        EXCEEDED.with(|e| e.set(None));
        Guard {
            _budget: std::marker::PhantomData,
            _not_send: std::marker::PhantomData,
        }
    }

    /// [OPUS-4.8] (sq-s5is) Sets the per-row byte width (= `width_in_ids ×
    /// BYTES_PER_ID`) of the working set the next row-count checks price. Called once
    /// per operator with that operator's output arity, so a check on `rows` correctly
    /// estimates `rows × width` bytes — the WIDE-row dimension the row cap misses.
    /// No-op (and no thread-local write on the unbudgeted hot path) when no budget is
    /// installed. Returns the previous width so callers can restore it.
    #[inline]
    pub(crate) fn set_width(width_in_ids: usize) -> usize {
        ACTIVE.with(|c| {
            let mut a = c.get();
            let prev = a.byte_width;
            if a.on {
                a.byte_width = width_in_ids.max(1).saturating_mul(BYTES_PER_ID);
                c.set(a);
            }
            prev
        })
    }

    /// [OPUS-4.8] (sq-s5is) Restores a byte width previously returned by [`set_width`]
    /// (cheap: one thread-local write, only while budgeted).
    #[inline]
    pub(crate) fn restore_width(prev: usize) {
        ACTIVE.with(|c| {
            let mut a = c.get();
            if a.on {
                a.byte_width = prev;
                c.set(a);
            }
        });
    }

    /// [OPUS-4.8] (sq-s5is) Adds `n` bytes of query-computed terms to the local-vocab
    /// high-water accumulator (the NON-row dimension). Trips the sticky flag immediately
    /// if it pushes the estimate over `max_bytes`, so an oversized CONSTRUCT template /
    /// aggregate scratch is caught even between row-count checks. No-op when unbudgeted.
    #[inline]
    pub(crate) fn add_bytes(n: usize) {
        ACTIVE.with(|c| {
            let mut a = c.get();
            if !a.on {
                return;
            }
            a.extra_bytes = a.extra_bytes.saturating_add(n);
            c.set(a);
            if a.extra_bytes > a.max_bytes {
                EXCEEDED.with(|e| {
                    if e.get().is_none() {
                        e.set(Some("max-bytes"));
                    }
                });
            }
        });
    }

    /// Snapshot of the installed limits, for the rayon-parallel branches.
    #[cfg_attr(not(feature = "parallel"), allow(dead_code))]
    #[inline]
    pub(crate) fn snapshot() -> Limits {
        ACTIVE.with(|a| a.get())
    }

    /// Decides whether the multi-core SELECT-JSON serializer may fan out under the
    /// CURRENTLY installed budget, returning the limit snapshot its workers re-check at
    /// each par-chunk boundary. [OPUS-4.8] (sq-7d3dj.10, roborev 1538, audit item 6)
    ///
    /// The parallel path builds every matching JSON fragment before it can know a row or
    /// byte count, so it cannot enforce a ROW / BYTE cap mid-serialize:
    ///
    /// * `Some(limits)` — fan out. Either NO budget is installed (`limits.on == false`,
    ///   making the per-chunk `hit` re-check a no-op) OR the budget is DEADLINE-ONLY
    ///   (both row and byte caps at their `usize::MAX` sentinel). Under a deadline-only
    ///   budget the per-chunk `limits.hit(0)` re-check stops launching new chunks once
    ///   the wall-clock deadline has passed, so the worst-case CPU overrun is bounded to
    ///   the chunks already in flight — approximately one per worker, a bounded constant
    ///   — not the unbounded burn an uncheckable fan-out under a row/byte cap would allow.
    /// * `None` — a row and/or byte cap is installed; the caller must take the
    ///   cooperative SERIAL loop, which cannot over-produce (it checks the sticky flag
    ///   every 1024 rows and stops early). A blanket "fan out whenever a budget is
    ///   installed" was REJECTED for exactly this reason (roborev 1538 / audit item 6).
    ///
    /// Compiled only for the `parallel` feature — the wasm/serial build never fans out.
    #[cfg(feature = "parallel")]
    #[inline]
    pub(crate) fn parallel_json_fanout() -> Option<Limits> {
        ACTIVE.with(|a| {
            let l = a.get();
            if l.on && (l.max_rows != usize::MAX || l.max_bytes != usize::MAX) {
                None // a row/byte cap the fan-out cannot enforce mid-serialize → serial loop
            } else {
                Some(l)
            }
        })
    }

    /// Time remaining until the installed wall-clock deadline, if any. [OPUS-4.8] (sq-d4p)
    ///
    /// The SERVICE HTTP transport uses this to bound a remote round-trip by the SAME
    /// budget that bounds local evaluation: a query under a 5s deadline must not block
    /// for the transport's fixed default on an unresponsive endpoint. Returns:
    /// * `None` — no deadline installed (no budget, or a row/byte-only budget); the
    ///   transport keeps its own finite default.
    /// * `Some(Duration::ZERO)` — the deadline has already passed; the caller should
    ///   refuse the remote call immediately rather than dial.
    /// * `Some(d)` — the remaining time, which the transport caps its own default to.
    ///
    /// Always compiled only off-wasm (no `Instant` there, and the `service` feature
    /// never reaches a wasm build).
    #[cfg(not(target_arch = "wasm32"))]
    #[cfg_attr(not(feature = "service"), allow(dead_code))]
    #[inline]
    pub(crate) fn remaining_timeout() -> Option<std::time::Duration> {
        ACTIVE.with(|a| {
            let lim = a.get();
            lim.deadline.map(|d| d.saturating_duration_since(std::time::Instant::now()))
        })
    }

    /// A savepoint of the local-vocab byte accumulator + the sticky exhaustion flag,
    /// taken BEFORE a speculative interning burst — a streaming SERVICE block whose
    /// rows a SILENT error must discard. [`restore_bytes`] rewinds to it so the
    /// discarded interns leave the byte budget EXACTLY as if they never happened,
    /// keeping SILENT SERVICE behaviour-neutral with the pre-streaming
    /// collect-then-intern-on-success path (which charged nothing on a swallowed
    /// remote error). [OPUS-4.8] (sq-my8wd.4)
    #[cfg(any(feature = "service", feature = "service-local"))]
    #[derive(Clone, Copy)]
    pub(crate) struct ByteSavepoint {
        extra_bytes: usize,
        exceeded: Option<&'static str>,
    }

    /// Capture the current byte accumulator + exhaustion flag. [OPUS-4.8] (sq-my8wd.4)
    #[cfg(any(feature = "service", feature = "service-local"))]
    #[inline]
    pub(crate) fn byte_savepoint() -> ByteSavepoint {
        ByteSavepoint {
            extra_bytes: ACTIVE.with(|c| c.get().extra_bytes),
            exceeded: EXCEEDED.with(|e| e.get()),
        }
    }

    /// Rewind the byte accumulator + exhaustion flag to a [`ByteSavepoint`]. Only the
    /// bytes charged (and any max-bytes exhaustion tripped) SINCE the savepoint are
    /// undone; an exhaustion that fired for an independent reason before it is
    /// preserved. Sound because the interning burst it brackets is synchronous and
    /// single-threaded — the SERVICE sink is the only writer between the savepoint and
    /// here — so the pre-burst snapshot is exactly the current state minus this burst.
    /// A deadline that elapsed during the burst is not masked: the next `exhausted`
    /// re-derives it from the wall clock. [OPUS-4.8] (sq-my8wd.4)
    #[cfg(any(feature = "service", feature = "service-local"))]
    #[inline]
    pub(crate) fn restore_bytes(sp: ByteSavepoint) {
        ACTIVE.with(|c| {
            let mut a = c.get();
            a.extra_bytes = sp.extra_bytes;
            c.set(a);
        });
        EXCEEDED.with(|e| e.set(sp.exceeded));
    }

    /// `true` once the budget is exhausted (sticky) — row-producing loops break
    /// on it; `rows` is the loop's current output size.
    #[inline]
    pub(crate) fn exhausted(rows: usize) -> bool {
        let a = ACTIVE.with(|c| c.get());
        if !a.on {
            return false;
        }
        if EXCEEDED.with(|e| e.get()).is_some() {
            return true;
        }
        if rows > a.max_rows {
            EXCEEDED.with(|e| e.set(Some("max-rows")));
            return true;
        }
        if a.bytes(rows) > a.max_bytes {
            EXCEEDED.with(|e| e.set(Some("max-bytes")));
            return true;
        }
        #[cfg(not(target_arch = "wasm32"))]
        if a.deadline.is_some_and(|d| std::time::Instant::now() >= d) {
            EXCEEDED.with(|e| e.set(Some("timeout")));
            return true;
        }
        if let Some(cancel) = a.cancel {
            // SAFETY: `CancelPtr`'s invariant and the lifetime-bound `Guard` keep
            // the `AtomicBool` alive until this thread-local pointer is cleared.
            // Relaxed is sufficient because cancellation gates control flow only;
            // it never publishes or guards a shared query buffer. If that changes,
            // the load/store pair must become Acquire/Release.
            if unsafe { cancel.0.as_ref() }.load(Ordering::Relaxed) {
                EXCEEDED.with(|e| e.set(Some("cancelled")));
                return true;
            }
        }
        false
    }

    /// Propagates an exhausted budget as the query error.
    #[inline]
    pub(crate) fn check(rows: usize) -> Result<(), String> {
        if exhausted(rows) {
            let why = EXCEEDED.with(|e| e.get()).unwrap_or("timeout");
            return Err(format!("query budget exceeded ({why})"));
        }
        Ok(())
    }

    /// Returns `true` when a budget is currently installed (even if not yet exhausted).
    /// The columnar path uses this for the I3 fallback rule: when a budget is armed the
    /// seam declines to the scalar path (the scalar debit schedule is not uniform-per-row
    /// inside `apply_filter`, so the `k = min(batch_len, budget_remaining)` prefix rule
    /// cannot be applied; the fallback is budget-armed ⇒ decline per the design record
    /// `research/vector-at-a-time-m4-completion-design.md` §1 I3). [SONNET-4.6] (sq-pntvh.5)
    #[cfg_attr(not(feature = "vectorized"), allow(dead_code))]
    #[inline]
    pub(crate) fn active() -> bool {
        ACTIVE.with(|c| c.get().on)
    }

    /// Caps a speculative `Vec` pre-allocation while a budget is active, so a
    /// budgeted cross-product cannot allocate its full (possibly astronomical)
    /// output up front before the first cooperative check fires. Honours BOTH the
    /// row cap and (via `byte_width`) the byte cap — whichever admits fewer rows.
    #[inline]
    pub(crate) fn cap_alloc(cap: usize) -> usize {
        let a = ACTIVE.with(|c| c.get());
        if !a.on {
            return cap;
        }
        // Rows the byte cap still admits, given the current width and accrued extra.
        let by_bytes = a
            .max_bytes
            .saturating_sub(a.extra_bytes)
            .checked_div(a.byte_width.max(1))
            .unwrap_or(usize::MAX)
            .saturating_add(1);
        cap.min(a.max_rows.saturating_add(1)).min(by_bytes).min(1 << 20)
    }

    /// [SONNET-4.6] (sq-qk6ac) Direct tests for `Limits::why` — the pure gate the
    /// rayon-parallel loops poll. Its contract has two load-bearing halves: it agrees
    /// with `Limits::hit`, and its reason string is EXACTLY the one `check` would raise,
    /// so a worker that abandons its share of the work reports the same error the
    /// installing thread would (never a fabricated one, and never a guessed result).
    #[cfg(test)]
    mod snapshot_reason_tests {
        use super::*;
        use std::sync::Arc;

        /// Asserts that under `budget` the snapshot reports `want` at `rows`, that `hit`
        /// agrees, and that the reason is the very string `check` puts in its error.
        fn assert_reason(budget: &QueryBudget, rows: usize, want: &'static str) {
            let _guard = install(budget);
            let snap = snapshot();
            assert_eq!(snap.why(rows), Some(want), "wrong snapshot reason for {}", want);
            assert!(snap.hit(rows), "hit must agree with why for {}", want);
            assert_eq!(
                check(rows),
                Err(format!("query budget exceeded ({})", want)),
                "the worker-visible reason must match the on-thread error for {}",
                want
            );
        }

        /// `why` and `hit` are one decision, and an unbudgeted snapshot never trips.
        #[test]
        fn unbudgeted_snapshot_has_no_reason() {
            let budget = QueryBudget::unlimited();
            let _guard = install(&budget);
            let snap = snapshot();
            assert_eq!(snap.why(0), None, "an unlimited budget must report no reason");
            assert_eq!(snap.why(usize::MAX), None, "no row cap ⇒ no reason at any row count");
            assert!(!snap.hit(usize::MAX), "hit must agree with why");
        }

        /// Each limit reports ITS OWN reason, and the string matches `check`'s message.
        #[test]
        fn each_limit_reports_the_reason_check_would_raise() {
            let rows_capped = QueryBudget { max_rows: Some(4), ..QueryBudget::unlimited() };
            assert_reason(&rows_capped, 5, "max-rows");
            let bytes_capped =
                QueryBudget { max_bytes: Some(BYTES_PER_ID), ..QueryBudget::unlimited() };
            assert_reason(&bytes_capped, 2, "max-bytes");
            let cancelled = QueryBudget::cancelled_by(Arc::new(AtomicBool::new(true)));
            assert_reason(&cancelled, 0, "cancelled");
        }

        /// The wall-clock arm (native only: `Instant` does not exist in a wasm budget).
        #[test]
        #[cfg(not(target_arch = "wasm32"))]
        fn an_elapsed_deadline_reports_timeout() {
            let budget = QueryBudget {
                deadline: Some(std::time::Instant::now() - std::time::Duration::from_secs(1)),
                ..QueryBudget::unlimited()
            };
            assert_reason(&budget, 0, "timeout");
        }

        /// The reason a limit does NOT report: an under-limit row count leaves the
        /// snapshot clean, so the gate cannot abandon work a budget still admits.
        #[test]
        fn a_limit_not_yet_crossed_reports_nothing() {
            let budget = QueryBudget { max_rows: Some(4), ..QueryBudget::unlimited() };
            let _guard = install(&budget);
            let snap = snapshot();
            assert_eq!(snap.why(4), None, "a row count AT the cap is still admitted");
            assert_eq!(snap.why(5), Some("max-rows"), "one past the cap trips");
        }

        /// The crux the parallel verdict loop depends on: a WORKER thread has no budget
        /// installed, so its thread-local poll is blind — only the captured snapshot can
        /// see the cancellation, and it names the same reason as the installing thread.
        #[test]
        fn snapshot_is_the_only_signal_a_worker_thread_can_see() {
            let flag = Arc::new(AtomicBool::new(true));
            let budget = QueryBudget::cancelled_by(Arc::clone(&flag));
            let _guard = install(&budget);
            let snap = snapshot();

            let (worker_poll, worker_reason) = std::thread::scope(|s| {
                s.spawn(|| (check(0), snap.why(0))).join().expect("worker must not panic")
            });
            assert_eq!(worker_poll, Ok(()), "the thread-local budget is invisible to a worker");
            assert_eq!(
                worker_reason,
                Some("cancelled"),
                "the captured snapshot must carry the cancellation across threads"
            );
            assert_eq!(check(0), Err("query budget exceeded (cancelled)".to_owned()));
        }
    }

    #[cfg(test)]
    mod cancel_tests {
        use super::*;
        use sparq_core::Graph;
        use std::sync::{Arc, Barrier};
        use std::time::{Duration, Instant};

        #[test]
        fn cancel_flag_zero_vs_one_trips_both_poll_paths() {
            let flag = Arc::new(AtomicBool::new(false));
            let budget = QueryBudget::unlimited().with_cancel(Arc::clone(&flag));
            let _guard = install(&budget);

            assert!(!snapshot().hit(0), "false control must not trip the rayon snapshot");
            assert_eq!(check(0), Ok(()), "false control must not trip the local poll");

            flag.store(true, Ordering::Relaxed);
            assert!(snapshot().hit(0), "true flag must trip the rayon snapshot");
            assert_eq!(check(0), Err("query budget exceeded (cancelled)".to_owned()));
            assert_eq!(EXCEEDED.with(Cell::get), Some("cancelled"));
        }

        #[test]
        fn cancel_from_another_thread_stops_large_query_promptly() {
            let mut nt = String::new();
            for i in 0..12_000 {
                nt.push_str(&format!("<http://ex/s{i}> <http://ex/p> <http://ex/o{i}> .\n"));
            }
            let graph = Graph::load_str(&nt, "ntriples").expect("test graph parses");
            let flag = Arc::new(AtomicBool::new(false));
            let budget = QueryBudget::unlimited().with_cancel(Arc::clone(&flag));
            let started = Arc::new(Barrier::new(2));
            let worker_started = Arc::clone(&started);

            let worker = std::thread::spawn(move || {
                worker_started.wait();
                crate::query_with_budget(
                    &graph,
                    "SELECT ?s ?x WHERE { ?s <http://ex/p> ?o . ?x <http://ex/p> ?y }",
                    &budget,
                )
                .map(|_| ())
            });

            started.wait();
            let cancelled_at = Instant::now();
            flag.store(true, Ordering::Relaxed);
            let result = worker.join().expect("query worker must not panic");
            assert_eq!(result, Err("query budget exceeded (cancelled)".to_owned()));
            assert!(
                cancelled_at.elapsed() < Duration::from_secs(5),
                "cancelled query did not return within the cooperative bound"
            );
        }

        #[test]
        fn cancelled_query_does_not_leak_flag_into_next_query_on_same_thread() {
            let graph = Graph::load_str("<http://ex/s> <http://ex/p> <http://ex/o> .", "ntriples")
                .expect("test graph parses");
            let cancelled = QueryBudget::cancelled_by(Arc::new(AtomicBool::new(true)));
            let query = "SELECT * WHERE { ?s ?p ?o }";

            assert_eq!(
                crate::query_with_budget(&graph, query, &cancelled).map(|_| ()),
                Err("query budget exceeded (cancelled)".to_owned())
            );
            let clean = crate::query_with_budget(&graph, query, &QueryBudget::unlimited())
                .expect("guard must clear the stale cancellation pointer");
            assert_eq!(clean.len(), 1);
        }
    }

}

// ---- EXPLAIN ANALYZE operator trace (T22) -------------------------------------
//
// A thread-local trace installed only by `explain_analyze*`: every
// `eval_graph_pattern` operator entry records a node (label, depth, output rows,
// wall time). When no trace is installed the entire mechanism is one thread-local
// `Cell<bool>` read per operator entry — the same cost class as the budget check
// that already sits there, and nothing on any per-row path.
pub(crate) mod trace {
    use std::cell::{Cell, RefCell};

    /// One traced operator (pre-order position + depth reconstruct the tree).
    pub(crate) struct Node {
        pub(crate) label: String,
        pub(crate) depth: usize,
        pub(crate) rows: usize,
        pub(crate) nanos: u64,
        /// The planner's estimated output cardinality for this operator, when the
        /// operator has a cardinality model (BGP nodes); `None` for operators whose
        /// output size the planner does not estimate. Used by the structured EXPLAIN
        /// (`explain-json`) to compute the per-operator q-error; the text trace
        /// ignores it. Present only under `explain-json` so the default trace node is
        /// byte-identical. [OPUS-4.8] sq-u4lgr
        #[cfg(feature = "explain-json")]
        pub(crate) est: Option<f64>,
    }

    thread_local! {
        static ENABLED: Cell<bool> = const { Cell::new(false) };
        static DEPTH: Cell<usize> = const { Cell::new(0) };
        static NODES: RefCell<Vec<Node>> = const { RefCell::new(Vec::new()) };
    }

    /// Disables tracing (and clears any partial trace) when the installing entry
    /// point returns — also on error/unwind, so a failed query never leaks a trace.
    pub(crate) struct Guard;
    impl Drop for Guard {
        fn drop(&mut self) {
            ENABLED.with(|e| e.set(false));
            DEPTH.with(|d| d.set(0));
            NODES.with(|n| n.borrow_mut().clear());
        }
    }

    pub(crate) fn install() -> Guard {
        ENABLED.with(|e| e.set(true));
        DEPTH.with(|d| d.set(0));
        NODES.with(|n| n.borrow_mut().clear());
        Guard
    }

    #[inline]
    pub(crate) fn enabled() -> bool {
        ENABLED.with(|e| e.get())
    }

    /// Opens a node, returning its index for [`exit`] to fill in.
    pub(crate) fn enter(label: String) -> usize {
        let depth = DEPTH.with(|d| {
            let v = d.get();
            d.set(v + 1);
            v
        });
        NODES.with(|n| {
            let mut n = n.borrow_mut();
            n.push(Node {
                label,
                depth,
                rows: 0,
                nanos: 0,
                #[cfg(feature = "explain-json")]
                est: None,
            });
            n.len() - 1
        })
    }

    pub(crate) fn exit(idx: usize, rows: usize, nanos: u64) {
        DEPTH.with(|d| d.set(d.get().saturating_sub(1)));
        NODES.with(|n| {
            if let Some(node) = n.borrow_mut().get_mut(idx) {
                node.rows = rows;
                node.nanos = nanos;
            }
        });
    }

    /// Records the planner's estimated output cardinality for the node opened at
    /// `idx` (called by `eval_graph_pattern_traced` only when the BGP estimate is
    /// computed). Separate from [`exit`] so the estimate is captured at ENTER time,
    /// before the (recursive) child evaluation runs. [OPUS-4.8] sq-u4lgr
    #[cfg(feature = "explain-json")]
    pub(crate) fn set_est(idx: usize, est: f64) {
        NODES.with(|n| {
            if let Some(node) = n.borrow_mut().get_mut(idx) {
                node.est = Some(est);
            }
        });
    }

    /// Drains the recorded nodes (pre-order). Call before the guard drops.
    pub(crate) fn take() -> Vec<Node> {
        NODES.with(|n| std::mem::take(&mut *n.borrow_mut()))
    }
}

// ---- Sideways information passing (SIP): correlated graph-pattern join (sq-7d3dj.30.3) ----
//
// [OPUS-4.8] When `Join(A, B)` is evaluated and the ALREADY-EVALUATED side `A` is
// SMALL, evaluate the big child `B` CORRELATED on A's bindings instead of cold: for
// each distinct binding of A's variables that are CERTAINLY bound in B (and bound to
// an IRI in A), substitute that IRI as a constant into B's patterns — pushing into
// UNION branches, BGP scans, property paths and filters — so the scan seeds from the
// constant, then recombine preserving MULTIPLICITY. Conservative: any scope/threshold
// condition failure returns to the existing cold path, bit-for-bit.
//
// Soundness (bag semantics): `A ⋈ B = ⊎_C (A_C ⋈ B)` where `A_C` partitions `A` by the
// pushed-variable values `C`, and `A_C ⋈ B = A_C ⋈ σ_{P=C}(B)`. Because every pushed
// variable is a CERTAIN variable of `B` (bound in every `B` solution), substituting the
// constant is exactly `σ_{P=C}(B)` with the pushed columns projected out (re-supplied by
// `A_C`). Pushed values are restricted to IRIs (term identity — no literal value-space /
// numeric-precision hazard), matching the design record (research/
// sp2bench-complex-shape-deficit.md §2.2). SP2Bench q08/q12b: the 1-row `?erdoes` side
// seeds the Union's `?document dc:creator ?erdoes` scan instead of a blind whole-corpus
// creator self-join.
pub(crate) mod sip {
    use std::cell::Cell;

    thread_local! {
        static ENABLED: Cell<bool> = const { Cell::new(true) };
        static FIRED: Cell<bool> = const { Cell::new(false) };
        static CORRELATED_ROWS: Cell<usize> = const { Cell::new(0) };
        static BINDINGS_EVALUATED: Cell<usize> = const { Cell::new(0) };
    }

    /// Whether correlated (SIP) join evaluation is enabled on this thread (default on).
    #[inline]
    pub(crate) fn enabled() -> bool {
        ENABLED.with(|e| e.get())
    }

    /// Enables/disables SIP on this thread, returning the previous value. The
    /// differential acceptance test uses it to compare correlated-on vs -off results.
    pub(crate) fn set_enabled(v: bool) -> bool {
        ENABLED.with(|e| e.replace(v))
    }

    /// Clears the per-query firing statistics (call before a measured/traced run).
    pub(crate) fn reset_stats() {
        FIRED.with(|f| f.set(false));
        CORRELATED_ROWS.with(|c| c.set(0));
        BINDINGS_EVALUATED.with(|b| b.set(0));
    }

    /// Records one fired correlated evaluation: `rows` solutions produced across
    /// `bindings` distinct pushed-value combinations.
    pub(crate) fn record(rows: usize, bindings: usize) {
        FIRED.with(|f| f.set(true));
        CORRELATED_ROWS.with(|c| c.set(c.get().saturating_add(rows)));
        BINDINGS_EVALUATED.with(|b| b.set(b.get().saturating_add(bindings)));
    }

    /// `(fired, correlated_child_rows, distinct_bindings_evaluated)` since the last
    /// [`reset_stats`]. The anti-vacuity acceptance test asserts `fired` and that the
    /// correlated child produced far fewer rows than the cold (blind) child.
    pub(crate) fn stats() -> (bool, usize, usize) {
        (
            FIRED.with(|f| f.get()),
            CORRELATED_ROWS.with(|c| c.get()),
            BINDINGS_EVALUATED.with(|b| b.get()),
        )
    }
}

// ---- Correlated (theta) anti-join for OPTIONAL+FILTER(!bound) (sq-7d3dj.30.9) ----
//
// [FABLE-5] The SPARQL negation idiom `Filter(!bound(?nb), LeftJoin(A, B, Some(F)))`
// with `?nb` CERTAIN in `B` and ABSENT from `A` is exactly an ANTI-JOIN with a theta
// condition: a left row `a` survives iff there is NO `b ∈ B` with `a` and `b`
// compatible on their shared variables AND `F(merge(a, b))` effectively TRUE.
//
// The #1735 rewrite turns the `expression: None` case into `Minus`, but declines here
// because `F` references OUTER variables (SP2Bench q06:
// `?author = ?author2 && ?yr2 < ?yr`), so the cold `left_outer_join` evaluates the
// full right side against the whole document set. This path instead:
//   (a) partitions `F` into var-to-var CORRELATION conjuncts `?outer θ ?inner` whose
//       `?inner` is certain-in-`B` and `?outer` is a left variable — where θ is value
//       `=`, `sameTerm`, or a single-variable `?a IN (?b)` membership (sq-3cmr4) — and a
//       RESIDUAL theta remainder (everything else, e.g. `?yr2 < ?yr`);
//   (b) for each distinct left correlation tuple, SEEDS the `B` scan sideways with the
//       outer IRI bound into `?inner`'s position (extending the #1741 SIP machinery to
//       the anti-join), evaluating a tiny correlated `B'` instead of the cold corpus;
//   (c) for each surviving `b ∈ B'` re-checks the FULL residual theta with verbatim
//       `eval_expr` (3-valued: an error / false does NOT match, so the left row
//       SURVIVES); the left row is dropped iff some `b` makes the whole condition true.
//
// For a very large anchor side the hash-path per-left-row probe is fanned out over
// cores under the `parallel` feature (sq-f1emb): only the boolean elimination VERDICTS
// are parallelised — the ordered output build + budget truncation stay serial — so the
// result is byte-identical to the serial probe.
//
// Soundness / semantic traps (each has a witness test):
//   * The correlation relation θ is load-bearing: value `=`, `sameTerm` and id-equality
//     are DIFFERENT relations on value-equal id-distinct literals (`"1"` vs `"01"`). A
//     value-`=` correlation (including single-var `IN`) seeds / id-probes EXACTLY only
//     when the outer value is an IRI or blank node (where `=` IS term identity); a
//     LITERAL routes through the value-correct COLD anti-join with `=` re-checked (the
//     sq-lr2ii class — a term-identity probe would miss a value-equal-but-not-identical
//     literal and SPURIOUSLY KEEP a row that must drop). A `sameTerm` correlation is
//     TERM IDENTITY for EVERY kind, so a literal key is itself id-probeable and any
//     value-correct scan re-checks with `sameTerm`, never `=`.
//   * Multiplicity: each surviving left row is emitted ONCE (with its original
//     multiplicity), never multiplied by the number of `B` matches it lacks.
//   * Output layout is the LeftJoin's: surviving left rows padded with `NO_ID` for every
//     right-only variable (they never matched), so it is drop-in for the cold plan.
//   * DECLINE is total: any shape/scope/threshold miss returns `Ok(None)` and the caller
//     runs the identical prior `Filter{LeftJoin}` plan, bit-for-bit.
pub(crate) mod theta_antijoin {
    use std::cell::Cell;

    thread_local! {
        static ENABLED: Cell<bool> = const { Cell::new(true) };
        static FIRED: Cell<bool> = const { Cell::new(false) };
        static CORRELATED_ROWS: Cell<usize> = const { Cell::new(0) };
        static BINDINGS_EVALUATED: Cell<usize> = const { Cell::new(0) };
        /// [OPUS-4.8] (sq-7d3dj.30.20) Count of anti-join shapes the STATIC early-decline
        /// gate (opt-in `antijoin-static-decline`) rejected BEFORE the mandatory left side
        /// was evaluated — i.e. the redundant left evaluations this feature saved. Test-only
        /// signal for the non-vacuity check; only ever incremented under the feature.
        #[cfg(feature = "antijoin-static-decline")]
        static EARLY_DECLINED: Cell<usize> = const { Cell::new(0) };
    }

    /// Whether the correlated theta anti-join is enabled on this thread (default on).
    #[inline]
    pub(crate) fn enabled() -> bool {
        ENABLED.with(|e| e.get())
    }

    /// Enables/disables the path on this thread, returning the previous value. The
    /// differential acceptance test uses it to compare fast-path vs cold results.
    pub(crate) fn set_enabled(v: bool) -> bool {
        ENABLED.with(|e| e.replace(v))
    }

    /// Records one STATIC early-decline (the feature saved one redundant left evaluation).
    #[cfg(feature = "antijoin-static-decline")]
    pub(crate) fn record_early_decline() {
        EARLY_DECLINED.with(|e| e.set(e.get().saturating_add(1)));
    }

    /// Number of static early-declines since the last [`reset_stats`] (feature-gated).
    #[cfg(feature = "antijoin-static-decline")]
    pub(crate) fn early_declined() -> usize {
        EARLY_DECLINED.with(|e| e.get())
    }

    /// Clears the per-query firing statistics (call before a measured/traced run).
    pub(crate) fn reset_stats() {
        FIRED.with(|f| f.set(false));
        CORRELATED_ROWS.with(|c| c.set(0));
        BINDINGS_EVALUATED.with(|b| b.set(0));
        #[cfg(feature = "antijoin-static-decline")]
        EARLY_DECLINED.with(|e| e.set(0));
    }

    /// Records one fired anti-join: `rows` right-side solutions produced across
    /// `bindings` distinct correlation tuples evaluated.
    pub(crate) fn record(rows: usize, bindings: usize) {
        FIRED.with(|f| f.set(true));
        CORRELATED_ROWS.with(|c| c.set(c.get().saturating_add(rows)));
        BINDINGS_EVALUATED.with(|b| b.set(b.get().saturating_add(bindings)));
    }

    /// `(fired, correlated_right_rows, distinct_correlations_evaluated)` since the last
    /// [`reset_stats`]. The anti-vacuity acceptance test asserts `fired` and that the
    /// correlated right side produced far fewer rows than the cold (blind) right side.
    pub(crate) fn stats() -> (bool, usize, usize) {
        (
            FIRED.with(|f| f.get()),
            CORRELATED_ROWS.with(|c| c.get()),
            BINDINGS_EVALUATED.with(|b| b.get()),
        )
    }
}

/// [OPUS-4.8] (sq-7d3dj.30.4) DISTINCT-projection loose (skip) index scan.
///
/// For `Distinct{Project{[?p]}{ BGP / Union-of-BGPs }}` the engine can enumerate the
/// DISTINCT projected values directly from an existing permutation sorted by the
/// projected column (a loose/skip scan — the general form of qlever's "pattern trick"
/// over the six permutations, NO new index) instead of materialising every full-width
/// join row and deduping post-hoc. The load-bearing invariant is DISTINCT result-SET
/// equivalence with the pushdown on vs off; the stats below back the anti-vacuity
/// acceptance test (the produced/scanned rows must COLLAPSE vs the full join size).
pub(crate) mod distinct_pushdown {
    use std::cell::Cell;

    thread_local! {
        static ENABLED: Cell<bool> = const { Cell::new(true) };
        static FIRED: Cell<bool> = const { Cell::new(false) };
        static ROWS_EMITTED: Cell<usize> = const { Cell::new(0) };
        static ROWS_SCANNED: Cell<usize> = const { Cell::new(0) };
    }

    /// Whether the DISTINCT-projection pushdown is enabled on this thread (default on).
    #[inline]
    pub(crate) fn enabled() -> bool {
        ENABLED.with(|e| e.get())
    }

    /// Enables/disables the pushdown on this thread, returning the previous value. The
    /// differential acceptance test uses it to compare pushdown-on vs -off results.
    pub(crate) fn set_enabled(v: bool) -> bool {
        ENABLED.with(|e| e.replace(v))
    }

    /// Clears the per-query pushdown statistics (call before a measured/traced run).
    pub(crate) fn reset_stats() {
        FIRED.with(|f| f.set(false));
        ROWS_EMITTED.with(|c| c.set(0));
        ROWS_SCANNED.with(|c| c.set(0));
    }

    /// Records one fired pushdown: `emitted` distinct values produced, having TOUCHED
    /// `scanned` permutation rows (the skip-scan's galloped-through rows — far fewer than
    /// the materialised join when the pushdown is non-vacuous).
    pub(crate) fn record(emitted: usize, scanned: usize) {
        FIRED.with(|f| f.set(true));
        ROWS_EMITTED.with(|c| c.set(c.get().saturating_add(emitted)));
        ROWS_SCANNED.with(|c| c.set(c.get().saturating_add(scanned)));
    }

    /// `(fired, distinct_values_emitted, permutation_rows_scanned)` since the last
    /// [`reset_stats`]. The anti-vacuity acceptance test asserts `fired` and that
    /// `permutation_rows_scanned` is far smaller than the full-join row count.
    pub(crate) fn stats() -> (bool, usize, usize) {
        (
            FIRED.with(|f| f.get()),
            ROWS_EMITTED.with(|c| c.get()),
            ROWS_SCANNED.with(|c| c.get()),
        )
    }
}

/// [FABLE-5] (sq-jnb1e) Runtime toggle + telemetry for the OPT-IN characteristic-set
/// anchor-incidence prune (the `cs-anchor-incidence` feature). Lets the differential
/// acceptance test compare the incidence-pruned block scan against the exact scan WITHIN one
/// feature-ON binary, and read whether the prune fired plus how many candidate predicates it
/// eliminated. Enabled by default when the feature is compiled in.
#[cfg(feature = "cs-anchor-incidence")]
pub(crate) mod anchor_incidence {
    use std::cell::Cell;

    thread_local! {
        static ENABLED: Cell<bool> = const { Cell::new(true) };
        static BUILT: Cell<bool> = const { Cell::new(false) };
        static PRUNED: Cell<usize> = const { Cell::new(0) };
    }

    /// Whether the incidence prune is active on this thread (default on with the feature).
    #[inline]
    pub(crate) fn enabled() -> bool {
        ENABLED.with(|e| e.get())
    }

    /// Enables/disables the prune on this thread, returning the previous value. The
    /// differential test flips it to compare pruned vs exact within one binary.
    pub(crate) fn set_enabled(v: bool) -> bool {
        ENABLED.with(|e| e.replace(v))
    }

    /// Clears the per-query incidence statistics.
    pub(crate) fn reset_stats() {
        BUILT.with(|b| b.set(false));
        PRUNED.with(|c| c.set(0));
    }

    /// Records that an incidence set was BUILT (a set was available for at least one branch).
    pub(crate) fn note_built() {
        BUILT.with(|b| b.set(true));
    }

    /// Records `n` candidate predicates pruned by the incidence set (block scan skipped).
    pub(crate) fn note_pruned(n: usize) {
        PRUNED.with(|c| c.set(c.get().saturating_add(n)));
    }

    /// `(incidence_built, predicates_pruned)` since the last [`reset_stats`]. The acceptance
    /// test asserts the set was built AND pruned the value-typed no-hit predicates.
    pub(crate) fn stats() -> (bool, usize) {
        (BUILT.with(|b| b.get()), PRUNED.with(|c| c.get()))
    }
}

/// Maximum size of the already-evaluated (small) join side for which correlated
/// evaluation of the other child is attempted; above it the cold path is used.
const SIP_MAX_SMALL_ROWS: usize = 64;

/// Certain (always-bound) REAL variables of a graph pattern — a sound
/// UNDER-approximation of the SPARQL bound set: it never adds a variable that some
/// solution may leave unbound, so any variable it reports is safe to substitute as a
/// constant. Blank-node slots are excluded (we never substitute into them).
fn certain_vars(p: &GraphPattern, out: &mut FxHashSet<Variable>) {
    use GraphPattern as G;
    // A directly-positioned (non-quoted, non-blank) query variable of a term slot.
    fn real(t: &TermPattern) -> Option<&Variable> {
        if let TermPattern::Variable(v) = t {
            Some(v)
        } else {
            None
        }
    }
    match p {
        G::Bgp { patterns } => {
            for tp in patterns {
                for v in [real(&tp.subject), nnp_var_ref(&tp.predicate), real(&tp.object)]
                    .into_iter()
                    .flatten()
                {
                    out.insert(v.clone());
                }
            }
        }
        G::Path { subject, object, .. } => {
            for v in [real(subject), real(object)].into_iter().flatten() {
                out.insert(v.clone());
            }
        }
        G::Join { left, right } => {
            certain_vars(left, out);
            certain_vars(right, out);
        }
        // Only the mandatory (left) side of an OPTIONAL / MINUS is certainly bound.
        G::LeftJoin { left, .. } | G::Minus { left, .. } => certain_vars(left, out),
        G::Filter { inner, .. }
        | G::OrderBy { inner, .. }
        | G::Distinct { inner }
        | G::Reduced { inner }
        | G::Slice { inner, .. } => certain_vars(inner, out),
        // A variable is certain in a UNION only if certain in BOTH branches.
        G::Union { left, right } => {
            let mut l = FxHashSet::default();
            let mut r = FxHashSet::default();
            certain_vars(left, &mut l);
            certain_vars(right, &mut r);
            out.extend(l.intersection(&r).cloned());
        }
        G::Graph { name, inner } => {
            if let NamedNodePattern::Variable(v) = name {
                out.insert(v.clone());
            }
            certain_vars(inner, out);
        }
        // BIND may evaluate to an error (leaving its target UNBOUND), so the extended
        // variable is NOT certain; only the inner pattern's certain vars are.
        G::Extend { inner, .. } => certain_vars(inner, out),
        G::Values { variables, bindings } => {
            for (i, v) in variables.iter().enumerate() {
                if bindings.iter().all(|row| row.get(i).is_some_and(Option::is_some)) {
                    out.insert(v.clone());
                }
            }
        }
        // Projection / grouping drop non-listed variables; keep the listed ones that
        // are certain in the inner pattern.
        G::Project { inner, variables } | G::Group { inner, variables, .. } => {
            let mut inner_c = FxHashSet::default();
            certain_vars(inner, &mut inner_c);
            for v in variables {
                if inner_c.contains(v) {
                    out.insert(v.clone());
                }
            }
        }
        // Service (and anything else): conservatively bind nothing certain.
        _ => {}
    }
}

/// [FABLE-5] (sq-7d3dj.30.11) Static term-kind analysis for the id-level FILTER fast path:
/// the REAL variables a graph pattern proves can never bind to a LITERAL — i.e. every place
/// the variable is (or could be) bound is a subject or predicate slot of a triple/path pattern.
/// Subjects are IRIs / blank nodes (or RDF 1.2 quoted triples) and predicates are always IRIs;
/// none of those is a literal. A variable is EXCLUDED the moment it appears anywhere it could
/// take a literal: an OBJECT slot, a `BIND` target, a `VALUES` column, or under any construct we
/// do not analyse (`SERVICE`, a sub-`SELECT` projecting it, …). Sound UNDER-approximation: it
/// only reports a variable when literal-binding is provably impossible, so a `=`/`!=` over two
/// reported variables (or a reported variable and a constant IRI) is exactly id (in)equality.
///
/// Implementation: collect `nonlit_positioned` (appears in a subject/predicate slot at least
/// once) and `lit_possible` (appears in a literal-capable position, or is produced by an
/// unanalysable construct), then return `nonlit_positioned \ lit_possible`.
///
/// [FABLE-5] (sq-1ivw7) The `obj_may_be_literal` classifier extends the reach to OBJECT-position
/// variables: a BGP object slot with a CONSTANT predicate whose object column is provably
/// literal-free in the CURRENT store snapshot is treated as a non-literal slot (like a subject),
/// rather than poisoned to literal-risk. `obj_may_be_literal(p)` returns `true` when predicate `p`
/// MIGHT have a literal object (the conservative default), so the object stays literal-risk. It is
/// snapshot-scoped: the caller must build it against the same `&Graph` the query executes on, and
/// the whole analysis is re-run per evaluation (see `predicate_has_literal_object`).
#[cfg(feature = "id-filter-fastpath")]
fn nonliteral_vars(p: &GraphPattern, obj_may_be_literal: &dyn Fn(&oxrdf::NamedNode) -> bool) -> FxHashSet<Variable> {
    let mut nonlit_positioned = FxHashSet::default();
    let mut lit_possible = FxHashSet::default();
    collect_kind_positions(p, &mut nonlit_positioned, &mut lit_possible, obj_may_be_literal);
    nonlit_positioned.retain(|v| !lit_possible.contains(v));
    nonlit_positioned
}

/// Walks `p`, recording each REAL variable into `nonlit` if it appears in a subject/predicate
/// slot (or a literal-free constant-predicate object slot) and into `maybe_lit` if it appears
/// anywhere it could be bound to a literal (a literal-capable object slot, a `BIND`/`VALUES`
/// binding, or any un-analysed construct that could bind it).
#[cfg(feature = "id-filter-fastpath")]
fn collect_kind_positions(
    p: &GraphPattern,
    nonlit: &mut FxHashSet<Variable>,
    maybe_lit: &mut FxHashSet<Variable>,
    obj_may_be_literal: &dyn Fn(&oxrdf::NamedNode) -> bool,
) {
    use GraphPattern as G;
    // A quoted-triple slot (`TermPattern::Triple`) recurses: its INNER object can itself be a
    // literal, so a variable appearing anywhere inside a quoted triple is treated as literal-risk.
    // Poison EVERY variable syntactically inside a term slot into `maybe_lit` — used for slots
    // that can bind a literal (object slots, path endpoints) and for quoted-triple slots whose
    // inner object can be a literal. Conservative: only ever ADDS literal-risk, never non-literal.
    fn poison_slot(t: &TermPattern, maybe_lit: &mut FxHashSet<Variable>) {
        match t {
            TermPattern::Variable(v) => {
                maybe_lit.insert(v.clone());
            }
            TermPattern::Triple(tp) => {
                poison_slot(&tp.subject, maybe_lit);
                if let NamedNodePattern::Variable(v) = &tp.predicate {
                    maybe_lit.insert(v.clone());
                }
                poison_slot(&tp.object, maybe_lit);
            }
            _ => {}
        }
    }
    // Poison every IN-SCOPE variable of an un-analysed sub-pattern (SERVICE, Lateral, …): we
    // cannot prove ANY of them non-literal, and — crucially — a variable one of these binds must
    // NOT be claimed non-literal on the strength of a subject occurrence in a sibling UNION branch.
    fn poison_all(p: &GraphPattern, maybe_lit: &mut FxHashSet<Variable>) {
        p.on_in_scope_variable(|v| {
            maybe_lit.insert(v.clone());
        });
    }
    match p {
        G::Bgp { patterns } => {
            for tp in patterns {
                // Subject / predicate slots are IRI / bnode — never a literal. A quoted-triple
                // subject can carry an inner literal, so poison it instead of crediting it.
                match &tp.subject {
                    TermPattern::Variable(v) => {
                        nonlit.insert(v.clone());
                    }
                    other => poison_slot(other, maybe_lit),
                }
                if let Some(v) = nnp_var_ref(&tp.predicate) {
                    nonlit.insert(v.clone());
                }
                // The object slot can bind a literal (directly or inside a quoted triple) — UNLESS
                // the predicate is a CONSTANT IRI proven literal-free in this snapshot, in which
                // case a plain object VARIABLE is non-literal (an IRI or bnode), like a subject.
                // [FABLE-5] (sq-1ivw7) A quoted-triple object still poisons (its inner object can be
                // a literal regardless of the outer predicate), so the credit applies only to the
                // bare `TermPattern::Variable` object form.
                match (&tp.predicate, &tp.object) {
                    (NamedNodePattern::NamedNode(pred), TermPattern::Variable(ov))
                        if !obj_may_be_literal(pred) =>
                    {
                        nonlit.insert(ov.clone());
                    }
                    _ => poison_slot(&tp.object, maybe_lit),
                }
            }
        }
        // A property-path binds subject and object, but the OBJECT end can be a literal (the final
        // step of a sequence/alternative is an ordinary object slot), and under `Reverse` or a
        // zero-length `ZeroOrMore`/`ZeroOrOne` match the SUBJECT end can equal a literal object.
        // So NEITHER endpoint is credited non-literal here — both are literal-risk. A path variable
        // is still proven non-literal if it appears in a subject/predicate slot of some BGP.
        G::Path { subject, object, .. } => {
            poison_slot(subject, maybe_lit);
            poison_slot(object, maybe_lit);
        }
        G::Join { left, right } | G::Union { left, right } => {
            collect_kind_positions(left, nonlit, maybe_lit, obj_may_be_literal);
            collect_kind_positions(right, nonlit, maybe_lit, obj_may_be_literal);
        }
        // LATERAL binds its right side correlated on the left; the right can be any construct
        // (incl. a sub-SELECT projecting a computed literal), so poison the right's in-scope vars
        // and analyse the left normally.
        G::Lateral { left, right } => {
            collect_kind_positions(left, nonlit, maybe_lit, obj_may_be_literal);
            poison_all(right, maybe_lit);
        }
        // OPTIONAL / MINUS: the right side still POSITIONS its variables, so its subject/predicate
        // occurrences remain non-literal evidence and its object occurrences remain literal-risk.
        G::LeftJoin { left, right, .. } => {
            collect_kind_positions(left, nonlit, maybe_lit, obj_may_be_literal);
            collect_kind_positions(right, nonlit, maybe_lit, obj_may_be_literal);
        }
        G::Minus { left, right } => {
            collect_kind_positions(left, nonlit, maybe_lit, obj_may_be_literal);
            collect_kind_positions(right, nonlit, maybe_lit, obj_may_be_literal);
        }
        G::Filter { inner, .. }
        | G::OrderBy { inner, .. }
        | G::Distinct { inner }
        | G::Reduced { inner }
        | G::Slice { inner, .. } => collect_kind_positions(inner, nonlit, maybe_lit, obj_may_be_literal),
        G::Graph { name, inner } => {
            // A GRAPH-name variable binds a graph IRI — non-literal.
            if let NamedNodePattern::Variable(v) = name {
                nonlit.insert(v.clone());
            }
            // [FABLE-5] (sq-1ivw7) Recurse with the ALWAYS-CONSERVATIVE classifier (`&|_| true`),
            // NOT the caller's `obj_may_be_literal`. The predicate-range object credit is scoped to
            // ONE graph's object column: `obj_may_be_literal` is built by `nonliteral_filter_cols`
            // against the graph the OUTER dispatch executes on (default graph for a FILTER sitting
            // OUTSIDE the GRAPH block), but a plain object variable inside `GRAPH <g>`/`GRAPH ?g`
            // is bound from a DIFFERENT store (the named sub-graph). Crediting it off the outer
            // graph's column would be unsound (a named-graph literal object gets id-compared for
            // `=`/`!=`). So object slots under ANY GRAPH block stay literal-risk at an outer
            // dispatch. The INSIDE-GRAPH dispatch is already correct and needs no widening here:
            // when the FILTER sits inside the block, `eval_translated` evaluates `inner` with
            // `graph = sub`, so its own `nonliteral_filter_cols` scans the right (named) store.
            collect_kind_positions(inner, nonlit, maybe_lit, &|_| true);
        }
        // A BIND target can evaluate to a literal — literal-risk.
        G::Extend { inner, variable, .. } => {
            maybe_lit.insert(variable.clone());
            collect_kind_positions(inner, nonlit, maybe_lit, obj_may_be_literal);
        }
        // Every VALUES column can carry a literal — literal-risk for all of them.
        G::Values { variables, .. } => {
            for v in variables {
                maybe_lit.insert(v.clone());
            }
        }
        // PROJECT (a sub-SELECT) only exposes its projected variables; its inner variables are NOT
        // visible to the surrounding query, so inner-only vars must contribute NEITHER non-literal
        // evidence NOR literal-risk to the outer scope. Analyse the inner into local sets and merge
        // back only the classifications for the PROJECTED variables.
        G::Project { inner, variables } => {
            let mut inner_nl = FxHashSet::default();
            let mut inner_ml = FxHashSet::default();
            collect_kind_positions(inner, &mut inner_nl, &mut inner_ml, obj_may_be_literal);
            let proj: FxHashSet<&Variable> = variables.iter().collect();
            for v in inner_nl.into_iter().filter(|v| proj.contains(v)) {
                nonlit.insert(v);
            }
            for v in inner_ml.into_iter().filter(|v| proj.contains(v)) {
                maybe_lit.insert(v);
            }
        }
        // GROUP: a grouped-by variable keeps the inner verdict; an aggregate result variable
        // (SUM/COUNT/… AS ?v) is a computed literal. Like PROJECT, only the OUTPUT columns
        // (group keys + aggregate targets) are visible, so analyse the inner locally and merge only
        // the group-key variables' verdicts; the aggregate targets are added as literal-risk.
        G::Group { inner, variables, aggregates } => {
            let mut inner_nl = FxHashSet::default();
            let mut inner_ml = FxHashSet::default();
            collect_kind_positions(inner, &mut inner_nl, &mut inner_ml, obj_may_be_literal);
            let keys: FxHashSet<&Variable> = variables.iter().collect();
            for v in inner_nl.into_iter().filter(|v| keys.contains(v)) {
                nonlit.insert(v);
            }
            for v in inner_ml.into_iter().filter(|v| keys.contains(v)) {
                maybe_lit.insert(v);
            }
            for (v, _) in aggregates {
                maybe_lit.insert(v.clone());
            }
        }
        // SERVICE and anything else un-analysed: we cannot prove ANY of its variables non-literal,
        // and — since a sibling UNION branch might position one of them as a subject — we must
        // POISON all of its in-scope variables into `maybe_lit` so no such false non-literal claim
        // survives the `nonlit \ maybe_lit` difference in `nonliteral_vars`.
        other => poison_all(other, maybe_lit),
    }
}

/// A borrow of a predicate-slot variable (predicates are never blank/quoted).
fn nnp_var_ref(p: &NamedNodePattern) -> Option<&Variable> {
    match p {
        NamedNodePattern::Variable(v) => Some(v),
        NamedNodePattern::NamedNode(_) => None,
    }
}

/// Substitutes each `var -> IRI` in `sub` throughout a graph pattern, returning `None`
/// when substitution is not clearly sound (e.g. a `SERVICE`, a sub-`SELECT`/aggregate
/// that projects a substituted variable, or a `BOUND(?v)` on a substituted variable) —
/// in which case the caller falls back to cold evaluation.
fn subst_pattern(p: &GraphPattern, sub: &FxHashMap<Variable, oxrdf::NamedNode>) -> Option<GraphPattern> {
    use GraphPattern as G;
    Some(match p {
        G::Bgp { patterns } => G::Bgp {
            patterns: patterns.iter().map(|tp| subst_triple(tp, sub)).collect::<Option<Vec<_>>>()?,
        },
        G::Path { subject, path, object } => G::Path {
            subject: subst_term(subject, sub)?,
            path: path.clone(),
            object: subst_term(object, sub)?,
        },
        G::Join { left, right } => G::Join {
            left: Box::new(subst_pattern(left, sub)?),
            right: Box::new(subst_pattern(right, sub)?),
        },
        G::LeftJoin { left, right, expression } => G::LeftJoin {
            left: Box::new(subst_pattern(left, sub)?),
            right: Box::new(subst_pattern(right, sub)?),
            expression: match expression {
                Some(e) => Some(subst_expr(e, sub)?),
                None => None,
            },
        },
        G::Filter { expr, inner } => G::Filter {
            expr: subst_expr(expr, sub)?,
            inner: Box::new(subst_pattern(inner, sub)?),
        },
        G::Union { left, right } => G::Union {
            left: Box::new(subst_pattern(left, sub)?),
            right: Box::new(subst_pattern(right, sub)?),
        },
        G::Graph { name, inner } => G::Graph {
            name: subst_nnp(name, sub),
            inner: Box::new(subst_pattern(inner, sub)?),
        },
        G::Minus { left, right } => G::Minus {
            left: Box::new(subst_pattern(left, sub)?),
            right: Box::new(subst_pattern(right, sub)?),
        },
        G::Extend { inner, variable, expression } => {
            // A BIND target that is itself a substituted variable would shadow the
            // constant — bail conservatively.
            if sub.contains_key(variable) {
                return None;
            }
            G::Extend {
                inner: Box::new(subst_pattern(inner, sub)?),
                variable: variable.clone(),
                expression: subst_expr(expression, sub)?,
            }
        }
        G::Values { variables, bindings } => {
            if variables.iter().any(|v| sub.contains_key(v)) {
                return None;
            }
            G::Values { variables: variables.clone(), bindings: bindings.clone() }
        }
        G::OrderBy { inner, expression } => G::OrderBy {
            inner: Box::new(subst_pattern(inner, sub)?),
            expression: expression.iter().map(|oe| subst_order(oe, sub)).collect::<Option<Vec<_>>>()?,
        },
        G::Distinct { inner } => G::Distinct { inner: Box::new(subst_pattern(inner, sub)?) },
        G::Reduced { inner } => G::Reduced { inner: Box::new(subst_pattern(inner, sub)?) },
        G::Slice { inner, start, length } => G::Slice {
            inner: Box::new(subst_pattern(inner, sub)?),
            start: *start,
            length: *length,
        },
        // A sub-SELECT / GROUP that projects a substituted variable would emit it
        // unbound; if it does not project any, the substitution is still sound.
        G::Project { inner, variables } => {
            if variables.iter().any(|v| sub.contains_key(v)) {
                return None;
            }
            G::Project { inner: Box::new(subst_pattern(inner, sub)?), variables: variables.clone() }
        }
        // Aggregation and everything else (Service, …): conservative bail.
        _ => return None,
    })
}

fn subst_triple(tp: &TriplePattern, sub: &FxHashMap<Variable, oxrdf::NamedNode>) -> Option<TriplePattern> {
    Some(TriplePattern {
        subject: subst_term(&tp.subject, sub)?,
        predicate: subst_nnp(&tp.predicate, sub),
        object: subst_term(&tp.object, sub)?,
    })
}

fn subst_term(t: &TermPattern, sub: &FxHashMap<Variable, oxrdf::NamedNode>) -> Option<TermPattern> {
    Some(match t {
        TermPattern::Variable(v) => match sub.get(v) {
            Some(nn) => TermPattern::NamedNode(nn.clone()),
            None => TermPattern::Variable(v.clone()),
        },
        // A quoted triple term (RDF 1.2) can embed a substituted variable — recurse.
        TermPattern::Triple(inner) => TermPattern::Triple(Box::new(subst_triple(inner, sub)?)),
        other => other.clone(),
    })
}

fn subst_nnp(p: &NamedNodePattern, sub: &FxHashMap<Variable, oxrdf::NamedNode>) -> NamedNodePattern {
    match p {
        NamedNodePattern::Variable(v) => match sub.get(v) {
            Some(nn) => NamedNodePattern::NamedNode(nn.clone()),
            None => NamedNodePattern::Variable(v.clone()),
        },
        NamedNodePattern::NamedNode(_) => p.clone(),
    }
}

fn subst_order(oe: &OrderExpression, sub: &FxHashMap<Variable, oxrdf::NamedNode>) -> Option<OrderExpression> {
    Some(match oe {
        OrderExpression::Asc(e) => OrderExpression::Asc(subst_expr(e, sub)?),
        OrderExpression::Desc(e) => OrderExpression::Desc(subst_expr(e, sub)?),
    })
}

fn subst_expr(e: &Expression, sub: &FxHashMap<Variable, oxrdf::NamedNode>) -> Option<Expression> {
    use Expression as E;
    let bx = |x: Option<Expression>| x.map(Box::new);
    Some(match e {
        E::NamedNode(_) | E::Literal(_) => e.clone(),
        E::Variable(v) => match sub.get(v) {
            Some(nn) => E::NamedNode(nn.clone()),
            None => E::Variable(v.clone()),
        },
        E::Or(a, b) => E::Or(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::And(a, b) => E::And(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::Equal(a, b) => E::Equal(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::SameTerm(a, b) => E::SameTerm(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::Greater(a, b) => E::Greater(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::GreaterOrEqual(a, b) => E::GreaterOrEqual(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::Less(a, b) => E::Less(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::LessOrEqual(a, b) => E::LessOrEqual(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::In(a, list) => E::In(
            bx(subst_expr(a, sub))?,
            list.iter().map(|x| subst_expr(x, sub)).collect::<Option<Vec<_>>>()?,
        ),
        E::Add(a, b) => E::Add(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::Subtract(a, b) => E::Subtract(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::Multiply(a, b) => E::Multiply(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::Divide(a, b) => E::Divide(bx(subst_expr(a, sub))?, bx(subst_expr(b, sub))?),
        E::UnaryPlus(a) => E::UnaryPlus(bx(subst_expr(a, sub))?),
        E::UnaryMinus(a) => E::UnaryMinus(bx(subst_expr(a, sub))?),
        E::Not(a) => E::Not(bx(subst_expr(a, sub))?),
        E::If(c, t, f) => E::If(
            bx(subst_expr(c, sub))?,
            bx(subst_expr(t, sub))?,
            bx(subst_expr(f, sub))?,
        ),
        E::Coalesce(list) => E::Coalesce(list.iter().map(|x| subst_expr(x, sub)).collect::<Option<Vec<_>>>()?),
        E::FunctionCall(f, args) => E::FunctionCall(
            f.clone(),
            args.iter().map(|x| subst_expr(x, sub)).collect::<Option<Vec<_>>>()?,
        ),
        E::Exists(gp) => E::Exists(Box::new(subst_pattern(gp, sub)?)),
        // `BOUND(?v)` on a substituted (certainly-bound) variable is always true, but
        // rewriting it changes nothing measurable here — bail conservatively rather
        // than synthesise a boolean literal.
        E::Bound(v) if sub.contains_key(v) => return None,
        E::Bound(v) => E::Bound(v.clone()),
    })
}

/// Attempts sideways-information-passing evaluation of `Join(left, right)` given the
/// already-evaluated `left`. Returns `Ok(Some(result))` when correlated evaluation
/// fired (bag-equivalent to the cold join), or `Ok(None)` to fall back to cold. See
/// the module comment for the soundness argument.
fn try_sip_join(
    graph: &Graph,
    local: &mut LocalVocab,
    left: &Bindings,
    right: &GraphPattern,
) -> Result<Option<Bindings>, String> {
    if !sip::enabled() || left.rows.is_empty() || left.rows.len() > SIP_MAX_SMALL_ROWS {
        return Ok(None);
    }
    // Variables that are certain in `right` — the only ones safe to substitute.
    let mut cert = FxHashSet::default();
    certain_vars(right, &mut cert);
    if cert.is_empty() {
        return Ok(None);
    }
    // Candidate push columns: a left variable that is certain in `right` AND bound to a
    // NamedNode (IRI) in EVERY left row (term identity keeps substitution exact).
    let mut push: Vec<(Variable, usize, Vec<oxrdf::NamedNode>)> = Vec::new();
    for (col, v) in left.vars.iter().enumerate() {
        if !cert.contains(v) {
            continue;
        }
        let mut iris: Vec<oxrdf::NamedNode> = Vec::with_capacity(left.rows.len());
        let mut ok = true;
        for row in &left.rows {
            match term_of(graph, local, row[col]) {
                Some(Term::NamedNode(n)) => iris.push(n),
                _ => {
                    ok = false;
                    break;
                }
            }
        }
        if ok {
            push.push((v.clone(), col, iris));
        }
    }
    if push.is_empty() {
        return Ok(None);
    }
    // Group left rows by their pushed-value combination `C` (dedup for EVALUATION,
    // never for the join result). `key_of` builds the ordered IRI-string key.
    let key_of = |ri: usize| -> Vec<String> {
        push.iter().map(|(_, _, iris)| iris[ri].as_str().to_string()).collect()
    };
    let mut order: Vec<Vec<String>> = Vec::new();
    let mut groups: FxHashMap<Vec<String>, Vec<usize>> = FxHashMap::default();
    for ri in 0..left.rows.len() {
        let k = key_of(ri);
        match groups.entry(k.clone()) {
            std::collections::hash_map::Entry::Occupied(mut e) => e.get_mut().push(ri),
            std::collections::hash_map::Entry::Vacant(e) => {
                order.push(k);
                e.insert(vec![ri]);
            }
        }
    }

    let mut result: Option<Bindings> = None;
    let mut total_child_rows = 0usize;
    for key in &order {
        let members = &groups[key];
        // Build the var -> IRI substitution for this C from the first member row.
        let ri0 = members[0];
        let mut smap: FxHashMap<Variable, oxrdf::NamedNode> = FxHashMap::default();
        for (v, _, iris) in &push {
            smap.insert(v.clone(), iris[ri0].clone());
        }
        // Substitute into `right`; a non-substitutable construct aborts SIP entirely
        // (fall back to the cold join for the whole operator, bit-for-bit).
        let Some(subst) = subst_pattern(right, &smap) else {
            return Ok(None);
        };
        let b_prime = eval_graph_pattern(graph, local, &subst)?;
        total_child_rows += b_prime.rows.len();
        // `A_C`: the left rows whose pushed values equal this C (multiplicity intact).
        let a_c = Bindings::unsorted(
            left.vars.clone(),
            members.iter().map(|&ri| left.rows[ri].clone()).collect(),
        );
        let joined = join_bindings(a_c, b_prime);
        result = Some(match result {
            None => joined,
            Some(acc) => union_bindings(acc, joined),
        });
    }
    sip::record(total_child_rows, order.len());
    Ok(result)
}

// ---- Extension-function registry (SPARQL 17.6) --------------------------------
//
// A thread-local registry installed by the `*_with_functions` entry points /
// `with_functions` in lib.rs, consulted ONLY in `eval_function`'s `F::Custom` arm
// after the XSD constructor-cast check misses. The registry-free entry points
// never install one, so their behaviour and hot-path cost are exactly the
// pre-registry ones (the `F::Custom` arm gains one thread-local `Option` check,
// on a path that previously always errored). Like the budget, evaluation is
// synchronous on the installing thread; the three rayon-parallel branches that
// evaluate expressions off-thread (FILTER, BIND, aggregates) snapshot the
// registry and re-install it around each worker item via [`worker_install`].
pub(crate) mod functions {
    use crate::FunctionRegistry;
    use std::cell::RefCell;
    use std::sync::Arc;

    thread_local! {
        static ACTIVE: RefCell<Option<Arc<FunctionRegistry>>> = const { RefCell::new(None) };
    }

    /// Uninstalls the registry when the installing entry point returns (also on
    /// error/unwind, so a poisoned thread never leaks a stale registry).
    pub(crate) struct Guard;
    impl Drop for Guard {
        fn drop(&mut self) {
            ACTIVE.with(|a| a.borrow_mut().take());
        }
    }

    pub(crate) fn install(fns: &FunctionRegistry) -> Guard {
        ACTIVE.with(|a| *a.borrow_mut() = Some(Arc::new(fns.clone())));
        Guard
    }

    /// Snapshot of the installed registry for the rayon-parallel branches
    /// (`None` — the overwhelmingly common case — makes [`worker_install`] free).
    // [OPUS-4.8] Only the `parallel`-gated worker branches snapshot the registry (see
    // `worker_install`, gated the same way); match the sibling `limits::snapshot` so the
    // `-D warnings` clippy gate stays clean in no-parallel/wasm builds.
    #[cfg_attr(not(feature = "parallel"), allow(dead_code))]
    pub(crate) fn snapshot() -> Option<Arc<FunctionRegistry>> {
        ACTIVE.with(|a| a.borrow().clone())
    }

    /// Scoped re-install of a snapshot inside a rayon worker item. Restores the
    /// PREVIOUS thread-local value on drop: rayon runs some items on the
    /// installing thread itself, whose registry must survive the item.
    pub(crate) struct WorkerGuard(Option<Option<Arc<FunctionRegistry>>>);
    impl Drop for WorkerGuard {
        fn drop(&mut self) {
            if let Some(prev) = self.0.take() {
                ACTIVE.with(|a| *a.borrow_mut() = prev);
            }
        }
    }

    #[cfg_attr(not(feature = "parallel"), allow(dead_code))]
    pub(crate) fn worker_install(snap: &Option<Arc<FunctionRegistry>>) -> WorkerGuard {
        match snap {
            None => WorkerGuard(None),
            Some(fns) => WorkerGuard(Some(ACTIVE.with(|a| a.borrow_mut().replace(fns.clone())))),
        }
    }

    /// The extension function registered for `iri`, if a registry is installed
    /// and contains it.
    pub(crate) fn lookup(iri: &str) -> Option<crate::ExtFn> {
        ACTIVE.with(|a| a.borrow().as_ref().and_then(|fns| fns.get(iri).cloned()))
    }
}

// ---- Local rows-returning SERVICE handlers (sq-lsp7k.2.2) ----------------------
//
// Mirrors `functions` (install guard + rayon-worker snapshot/re-install) so a
// `SERVICE <iri> { … }` nested under a `FILTER EXISTS` — which re-enters pattern
// evaluation on a rayon worker — still sees the registry. Propagation is load-bearing,
// not a nicety: a worker that MISSED the registry would fall through to the HTTP path
// and try to dial the IRI instead of answering it locally. The overwhelmingly common
// case is NO registry installed, which makes the snapshot path free. NON-DEFAULT
// `service-local` feature: when off, this module does not compile and the default build
// is byte-identical. [OPUS-5]
#[cfg(feature = "service-local")]
pub(crate) mod local_services {
    use crate::LocalServiceRegistry;
    use std::cell::RefCell;
    use std::sync::Arc;

    thread_local! {
        static ACTIVE: RefCell<Option<Arc<LocalServiceRegistry>>> = const { RefCell::new(None) };
    }

    /// Uninstalls on drop by restoring the PREVIOUS registry rather than clearing —
    /// `with_local_services` is documented as scoped RAII, so a NESTED install must
    /// hand the outer scope its own registry back when the inner one ends (clearing
    /// would silently unregister the outer handlers for the rest of the outer scope,
    /// sending a formerly-local IRI down the HTTP path). Restores on unwind too.
    /// [SONNET-4.6]
    pub(crate) struct Guard(Option<Arc<LocalServiceRegistry>>);
    impl Drop for Guard {
        fn drop(&mut self) {
            let prev = self.0.take();
            ACTIVE.with(|a| *a.borrow_mut() = prev);
        }
    }

    pub(crate) fn install(reg: &LocalServiceRegistry) -> Guard {
        Guard(ACTIVE.with(|a| a.borrow_mut().replace(Arc::new(reg.clone()))))
    }

    #[cfg_attr(not(feature = "parallel"), allow(dead_code))]
    pub(crate) fn snapshot() -> Option<Arc<LocalServiceRegistry>> {
        ACTIVE.with(|a| a.borrow().clone())
    }

    pub(crate) struct WorkerGuard(Option<Option<Arc<LocalServiceRegistry>>>);
    impl Drop for WorkerGuard {
        fn drop(&mut self) {
            if let Some(prev) = self.0.take() {
                ACTIVE.with(|a| *a.borrow_mut() = prev);
            }
        }
    }

    #[cfg_attr(not(feature = "parallel"), allow(dead_code))]
    pub(crate) fn worker_install(snap: &Option<Arc<LocalServiceRegistry>>) -> WorkerGuard {
        match snap {
            None => WorkerGuard(None),
            Some(reg) => WorkerGuard(Some(ACTIVE.with(|a| a.borrow_mut().replace(reg.clone())))),
        }
    }

    /// The local handler registered for `iri`, if a registry is installed and
    /// contains it.
    pub(crate) fn lookup(iri: &str) -> Option<crate::LocalServiceFn> {
        ACTIVE.with(|a| a.borrow().as_ref().and_then(|reg| reg.get(iri).cloned()))
    }

    /// Whether `iri` is served locally — the cheap check the SERVICE bind-join uses to
    /// DECLINE pushing a `VALUES` block at an IRI that never reaches the network.
    #[cfg_attr(not(feature = "service"), allow(dead_code))]
    pub(crate) fn handles(iri: &str) -> bool {
        ACTIVE.with(|a| a.borrow().as_ref().is_some_and(|reg| reg.contains(iri)))
    }
}

