// ---- Dataset view (L1) ---------------------------------------------------------
//
// A thread-local named-graph-subset view installed by the `*_view` entry points /
// `with_view` in lib.rs (see research/solid-access-control-design.md §5 in the
// sparq-solid worktree). Consulted at the only places a dataset is enumerated:
// `eval_graph_named` (named-graph visibility), the BGP/path entries
// (`DefaultGraphMode::Empty`) and `dataset::build_active` (FROM / FROM NAMED
// intersect with the view — restriction composes, never widens). A non-visible
// graph must be INDISTINGUISHABLE from an absent one; that is the security
// property. Like the budget/functions guards, evaluation is synchronous on the
// installing thread; the rayon-parallel expression branches (FILTER / BIND /
// aggregates — the only off-thread paths that can re-enter pattern evaluation,
// via EXISTS) snapshot the view and re-install it around each worker item.
pub(crate) mod view {
    use crate::{DatasetView, DefaultGraphMode};
    use oxrdf::Term;
    use rustc_hash::FxHashSet;
    use std::cell::RefCell;
    use std::sync::Arc;

    /// The installed view, plus the "inside GRAPH" suspend flag:
    /// `eval_graph_named` swaps evaluation to the named sub-`Graph`, whose inner
    /// patterns must NOT be empty-defaulted (only the TOP-LEVEL graph scope is).
    #[derive(Clone, Default)]
    pub(crate) struct State {
        named: Option<Arc<FxHashSet<Term>>>,
        default_empty: bool,
        suspended: bool,
    }

    thread_local! {
        static ACTIVE: RefCell<State> = RefCell::new(State::default());
    }

    /// Restores the pre-install state when the installing entry point returns
    /// (also on error/unwind, so a poisoned thread never leaks a stale view).
    pub(crate) struct Guard(State);
    impl Drop for Guard {
        fn drop(&mut self) {
            ACTIVE.with(|a| *a.borrow_mut() = std::mem::take(&mut self.0));
        }
    }

    pub(crate) fn install(v: &DatasetView) -> Guard {
        let new = State {
            named: Some(Arc::clone(&v.named)),
            default_empty: matches!(v.default, DefaultGraphMode::Empty),
            suspended: false,
        };
        Guard(ACTIVE.with(|a| std::mem::replace(&mut *a.borrow_mut(), new)))
    }

    /// Fully suspends the view (named filter AND empty default) for a scope —
    /// used by the entry points once `dataset::build_active` has folded the view
    /// into a dataset-clause ACTIVE graph: the restriction is already applied,
    /// and re-filtering would make a non-visible FROM NAMED graph behave
    /// differently from an absent one (both must be the EMPTY active graph).
    pub(crate) fn suspend_all() -> Guard {
        Guard(ACTIVE.with(|a| std::mem::take(&mut *a.borrow_mut())))
    }

    /// RAII suspension of the empty-default short-circuit only, for GRAPH scope
    /// (the named-graph visibility filter stays active). Restores the previous
    /// flag on drop, so nested scopes compose.
    pub(crate) struct GraphScope(bool);
    impl Drop for GraphScope {
        fn drop(&mut self) {
            ACTIVE.with(|a| a.borrow_mut().suspended = self.0);
        }
    }

    pub(crate) fn enter_graph() -> GraphScope {
        GraphScope(ACTIVE.with(|a| std::mem::replace(&mut a.borrow_mut().suspended, true)))
    }

    /// `true` when `name` is a visible named graph under the installed view
    /// (always true with no view installed).
    #[inline]
    pub(crate) fn allows(name: &Term) -> bool {
        ACTIVE.with(|a| a.borrow().named.as_ref().is_none_or(|s| s.contains(name)))
    }

    /// `true` when the view's default graph is EMPTY at the current scope —
    /// false with no view, under `StoreDefault`, or inside a GRAPH pattern.
    #[inline]
    pub(crate) fn default_is_empty() -> bool {
        ACTIVE.with(|a| {
            let s = a.borrow();
            s.default_empty && !s.suspended
        })
    }

    /// Snapshot of the installed view for the rayon-parallel expression branches
    /// (`None` — no view, the common case — makes [`worker_install`] free).
    #[cfg_attr(not(feature = "parallel"), allow(dead_code))]
    pub(crate) fn snapshot() -> Option<State> {
        ACTIVE.with(|a| {
            let s = a.borrow();
            (s.named.is_some() || s.default_empty).then(|| s.clone())
        })
    }

    /// Scoped re-install of a snapshot inside a rayon worker item. Restores the
    /// PREVIOUS thread-local value on drop: rayon runs some items on the
    /// installing thread itself, whose view must survive the item.
    pub(crate) struct WorkerGuard(Option<State>);
    impl Drop for WorkerGuard {
        fn drop(&mut self) {
            if let Some(prev) = self.0.take() {
                ACTIVE.with(|a| *a.borrow_mut() = prev);
            }
        }
    }

    #[cfg_attr(not(feature = "parallel"), allow(dead_code))]
    pub(crate) fn worker_install(snap: &Option<State>) -> WorkerGuard {
        match snap {
            None => WorkerGuard(None),
            Some(s) => WorkerGuard(Some(ACTIVE.with(|a| std::mem::replace(&mut *a.borrow_mut(), s.clone())))),
        }
    }
}

/// One solution row: the ids bound to each of a [`Bindings`]' variables. Inlined
/// up to 4 columns (the common case) so a join produces no heap allocation per
/// row — the dominant cost on large join results.
type Row = SmallVec<[Id; 4]>;

/// Result sizes at/above which the embarrassingly-parallel materialisation steps
/// (row building, term reconstruction) are worth handing to rayon; below it the
/// thread hand-off costs more than it saves. Native only (the wasm build has no
/// `parallel` feature, so these paths compile to the sequential loops).
#[cfg(feature = "parallel")]
const PAR_THRESHOLD: usize = 50_000;

/// Maximum `offset + limit` (row budget) for the bounded-heap ORDER BY path.
/// When the requested budget k is at most this threshold AND k < n (total rows),
/// the `Slice{...OrderBy{...}}` pattern uses bounded selection O(n + k log k)
/// instead of a full stable sort O(n log n). The threshold avoids heap overhead
/// when k is large relative to n. [SONNET-4.6] sq-7d3dj.30.2
const TOP_K_ORDER_BY_THRESHOLD: usize = 1_024;

/// A join / group key (the ids of the shared or grouping columns). Inlined up to
/// 2 columns — most joins are on one or two variables — so building a hash table
/// or probing it allocates nothing per key.
type Key = SmallVec<[Id; 2]>;

/// A hash-table posting list (row indices sharing a key). Inlined up to 2 — many
/// join keys (and almost all OPTIONAL keys) match only one or two rows — so the
/// build allocates nothing per bucket in the common case.
type Posting = SmallVec<[usize; 2]>;

/// [OPUS-4.8] sq-hknqs (epic sq-qonbz, Phase 3): the engine's cooperative-cancel hook for the
/// shared substrate join kernels. A zero-sized type whose [`exhausted`](sjoin::Budget::exhausted)
/// reads the engine's thread-local [`budget`] (the per-WHERE-solution `QueryBudget`), so a
/// capped/timed-out query truncates a join cleanly at a key-group / probe-row boundary — exactly
/// the engine's pre-move per-group `budget::exhausted(...)` check. Generic, not a trait object,
/// so the substrate kernel monomorphises the call into the same direct check it was before the
/// move (no vtable on the probe loop).
struct EngineBudget;

impl sjoin::Budget for EngineBudget {
    #[inline]
    fn exhausted(&self, rows: usize) -> bool {
        budget::exhausted(rows)
    }
}

/// [OPUS-4.8] sq-hknqs: the parallel hash-join's per-worker exhaustion snapshot. Wraps the
/// flattened [`budget::Limits`] (the installing thread's sticky flag is invisible to rayon
/// workers) so a worker that hits the limits stops adding to its accumulator; the caller's next
/// on-thread check raises the actual error. Generic ([`sjoin::BudgetSnapshot`]), so the rayon
/// fold carries no vtable.
#[cfg(feature = "parallel")]
struct EngineSnapshot(budget::Limits);

#[cfg(feature = "parallel")]
impl sjoin::BudgetSnapshot for EngineSnapshot {
    #[inline]
    fn hit(&self, rows: usize) -> bool {
        self.0.hit(rows)
    }
}

/// Ids at or above this base index into the per-query [`LocalVocab`] instead of the graph
/// dictionary. It sits ABOVE the dictionary range `[1, INLINE_BASE)` and the inline-integer
/// range `[INLINE_BASE, INLINE_BASE + 2^30)`, i.e. at `INLINE_BASE + 2^30 = 3·2^30`, leaving
/// the local vocab `[3·2^30, 2^32)` (≈1.07B query-computed terms — far more than any query).
const LOCAL_BASE: Id = dict::INLINE_BASE + (1 << 30);

#[inline]
fn is_local(id: Id) -> bool {
    id >= LOCAL_BASE
}

/// [OPUS-4.8] (sq-s5is) Estimated heap bytes of a query-computed term, for the
/// byte-accounted budget's local-vocab accounting. The struct itself plus the lexical
/// bytes of the value/IRI (+ datatype IRI / language tag for a literal). A LOWER bound
/// (ignores allocator overhead), conservative in the same direction the rest of the cap
/// is. Only ever called while a budget is installed (from `LocalVocab::intern`).
fn local_term_bytes(t: &Term) -> usize {
    let base = std::mem::size_of::<Term>();
    match t {
        Term::NamedNode(n) => base + n.as_str().len(),
        Term::BlankNode(b) => base + b.as_str().len(),
        Term::Literal(l) => {
            base + l.value().len()
                + l.datatype().as_str().len()
                + l.language().map_or(0, str::len)
        }
        // RDF 1.2 triple terms: charge the struct + each component recursively.
        other => base + format!("{other}").len(),
    }
}

/// Per-query vocabulary for terms produced during evaluation (BIND, aggregates)
/// that are not in the graph dictionary.
#[derive(Default)]
pub struct LocalVocab {
    terms: Vec<Term>,
    ids: FxHashMap<Term, Id>,
    /// Parallel to `terms`: the f64 value of each numeric local literal (NaN
    /// otherwise) — the local-vocab twin of the graph's `numerics` cache, so a
    /// FILTER/comparison over a BIND-computed numeric does not clone + re-parse
    /// the term per row.
    nums: Vec<f64>,
}

impl LocalVocab {
    /// Interns a term, returning a stable id: equal terms get the same id so
    /// DISTINCT, GROUP BY, joins and equality work on computed values.
    fn intern(&mut self, t: Term) -> Id {
        if let Some(&id) = self.ids.get(&t) {
            return id;
        }
        let id = LOCAL_BASE + self.terms.len() as Id;
        self.nums.push(match &t {
            // [FABLE-5] sq-74oy4 / sq-6b1lj: cache the DATATYPE-AWARE f64 (`numeric_cache_f64`)
            // — the SAME acceptance the graph `numeric_value` cache and the lenient `as_num`
            // seam use — so a computed (BIND/aggregate) numeric term joins/compares identically
            // to a graph term. It TRIMS (XSD `collapse` facet) and rejects a per-datatype-
            // ill-formed lexical (`"1.5"^^xsd:integer`); either folds to the NaN cache-miss
            // sentinel, deferring `=`/`<`/`>` to the exact evaluator (which type-errors it).
            Term::Literal(l) => numeric_cache_f64(l).unwrap_or(f64::NAN),
            _ => f64::NAN,
        });
        // [OPUS-4.8] (sq-s5is) Charge the byte cap for this newly-computed term (BIND /
        // aggregate / CONSTRUCT scratch) — the NON-row dimension the row cap misses. A
        // query that materialises few rows but huge string literals is now bounded. The
        // term is stored TWICE (the `terms` vec + the `ids` key), so count both.
        budget::add_bytes(2usize.saturating_mul(local_term_bytes(&t)));
        self.terms.push(t.clone());
        self.ids.insert(t, id);
        id
    }
    /// The append cursor into the local vocab, paired with [`LocalVocab::rollback_to`]
    /// to discard a speculative interning burst. [OPUS-4.8] (sq-my8wd.4)
    #[cfg(any(feature = "service", feature = "service-local"))]
    fn savepoint(&self) -> usize {
        self.terms.len()
    }
    /// Drop every term interned since `mark`, so the rows a SILENT SERVICE error
    /// discards leave the local vocab EXACTLY as if they were never interned — no
    /// retained memory. Pairs with a `budget::ByteSavepoint` (which refunds the bytes
    /// those terms charged); together they are the resource twin of dropping the
    /// discarded id rows, keeping SILENT SERVICE behaviour-neutral with the pre-streaming
    /// path. Interns BEFORE `mark` — and re-interns that returned an existing id, which
    /// pushed nothing — are untouched. [OPUS-4.8] (sq-my8wd.4)
    #[cfg(any(feature = "service", feature = "service-local"))]
    fn rollback_to(&mut self, mark: usize) {
        for t in self.terms.drain(mark..) {
            self.ids.remove(&t);
        }
        self.nums.truncate(mark);
    }
    fn term(&self, id: Id) -> &Term {
        &self.terms[(id - LOCAL_BASE) as usize]
    }
    /// The cached numeric value of a local id (`None` for a non-numeric term).
    /// For every non-NaN numeric term this is exactly what `as_num` of the
    /// materialised term returns — both parse through `parse_xsd_f64`. A genuine
    /// `xsd:double`/`float` `NaN` is the one case they differ: the cache uses NaN as
    /// its not-a-number sentinel, so it reports `None` where `as_num` returns
    /// `Some(NaN)` (a pre-existing sentinel limitation, not a parse-set disagreement).
    #[inline]
    fn numeric(&self, id: Id) -> Option<f64> {
        let v = self.nums[(id - LOCAL_BASE) as usize];
        if v.is_nan() {
            None
        } else {
            Some(v)
        }
    }
}

/// Resolves an id to its term (graph dictionary or local vocab); `NO_ID` -> None.
fn term_of(graph: &Graph, local: &LocalVocab, id: Id) -> Option<Term> {
    if id == NO_ID {
        None
    } else if is_local(id) {
        Some(local.term(id).clone())
    } else {
        Some(graph.dict.term(id))
    }
}

/// Intermediate result: rows of one id per `vars[i]` (`NO_ID` = unbound).
/// `sorted_by` records the variable the rows are sorted on (if any), enabling a
/// merge join instead of a hash table.
struct Bindings {
    vars: Vec<Variable>,
    rows: Vec<Row>,
    sorted_by: Option<Variable>,
}

impl Bindings {
    fn col(&self, v: &Variable) -> Option<usize> {
        self.vars.iter().position(|x| x == v)
    }
    fn unsorted(vars: Vec<Variable>, rows: Vec<Row>) -> Self {
        Bindings { vars, rows, sorted_by: None }
    }
}

pub fn eval_select(graph: &Graph, pattern: &GraphPattern) -> Result<QueryResult, String> {
    let mut local = LocalVocab::default();
    let bindings = eval_modified(graph, &mut local, pattern)?;
    // Final budget gate: converts a row-capped/timed-out evaluation (including the
    // uninstrumented rayon branches) into the error before the expensive term
    // materialisation below.
    budget::check(bindings.rows.len())?;

    // SELECT * exposes only real variables, never synthetic blank-node variables.
    let out_vars: Vec<Variable> = bindings
        .vars
        .iter()
        .filter(|v| !v.as_str().starts_with(BNODE_VAR_PREFIX))
        .cloned()
        .collect();

    let col_of: Vec<Option<usize>> = out_vars.iter().map(|v| bindings.col(v)).collect();
    // Materialise each solution row's terms. This reconstructs an `oxrdf::Term` (an
    // IRI/string allocation) per cell and is the dominant cost of returning a large
    // result — but every row is independent, so do it in parallel on native (the wasm
    // build has no threads and keeps the sequential path). Order is preserved.
    let materialise = |row: &Row| -> Vec<Option<Term>> {
        col_of.iter().map(|c| c.and_then(|i| term_of(graph, &local, row[i]))).collect()
    };
    #[cfg(feature = "parallel")]
    let rows: Vec<Vec<Option<Term>>> = if bindings.rows.len() >= PAR_THRESHOLD {
        use rayon::prelude::*;
        bindings.rows.par_iter().map(materialise).collect()
    } else {
        bindings.rows.iter().map(materialise).collect()
    };
    #[cfg(not(feature = "parallel"))]
    let rows: Vec<Vec<Option<Term>>> = bindings.rows.iter().map(materialise).collect();
    Ok(QueryResult { vars: out_vars, rows })
}

/// Writes one binding's JSON value directly from its id — no intermediate `oxrdf::Term`
/// for the common (dictionary) case, which is the allocator-bound cost of materialising.
#[inline]
fn write_id_json(graph: &Graph, local: &LocalVocab, id: Id, s: &mut String) {
    if dict::is_inline(id) {
        crate::json::inline_int_json(s, id - dict::INLINE_BASE);
    } else if is_local(id) {
        // Computed terms (BIND / aggregates) are rare; reconstruct just these.
        crate::json::term_to_json(s, local.term(id));
    } else {
        write_store_id_json(graph, id, s);
    }
}

/// Writes one binding value's JSON directly from a STORE id (never a local-vocab id,
/// so no `LocalVocab` needed) — for the streaming single-pattern scan path. An RDF 1.2
/// triple-term id recurses through its component ids (which are always store/inline
/// ids), producing the SPARQL 1.2 `{"type":"triple","value":{…}}` JSON encoding.
fn write_store_id_json(graph: &Graph, id: Id, s: &mut String) {
    if dict::is_inline(id) {
        crate::json::inline_int_json(s, id - dict::INLINE_BASE);
    } else {
        match graph.dict.term_parts(id) {
            dict::TermParts::Triple([ts, tp, to]) => {
                s.push_str("{\"type\":\"triple\",\"value\":{\"subject\":");
                write_store_id_json(graph, ts, s);
                s.push_str(",\"predicate\":");
                write_store_id_json(graph, tp, s);
                s.push_str(",\"object\":");
                write_store_id_json(graph, to, s);
                s.push_str("}}");
            }
            parts => crate::json::parts_to_json(s, parts),
        }
    }
}

/// Concatenates JSON chunks back into the single-string form (the non-streamed API).
fn join_chunks(mut chunks: Vec<String>) -> String {
    if chunks.len() == 1 {
        chunks.pop().expect("len checked")
    } else {
        chunks.concat()
    }
}

/// Streaming fast path: `SELECT ... WHERE { <one triple pattern> }` (optionally
/// projected) serialised straight from the index scan to SPARQL-JSON — no `Bindings`,
/// no per-row `Row`, no `Term`. Returns `None` if the query is not this shape (the
/// caller falls back to the general evaluator). The vector-at-a-time idea for the most
/// common (single-pattern) browser query. Output is a chunk sequence (see
/// [`eval_select_json_chunks`]); concatenated it is the exact JSON document.
///
/// [OPUS-4.8] (sq-7d3dj.34.2) Emit-based: hands each serialised chunk to `emit` **as it is
/// produced** instead of collecting a `Vec<String>`, so the server can begin writing the
/// results header + early solutions to the socket before the whole result is serialised
/// (TTFB streaming). `emit` returns [`ControlFlow::Break`] when the consumer has gone away
/// (the HTTP client disconnected); the scan then stops early. Returns `Some(())` when this
/// shape was handled (fell into the streaming path), `None` when the caller must use the
/// general evaluator. The concatenation of the chunks handed to `emit` is byte-identical to
/// the pre-emit `Vec<String>` output.
fn single_pattern_scan_json_emit(
    graph: &Graph,
    pattern: &GraphPattern,
    flush: Option<usize>,
    emit: &mut dyn FnMut(String) -> ControlFlow<()>,
) -> Option<()> {
    // zk-trace: this streaming path serialises straight from the scan without
    // materialising Bindings, so it never hits the scan-recording hook. Fall
    // through to the Bindings path (which records) while a recorder is armed —
    // result-equivalent, only the plan changes.
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        return None;
    }
    if view::default_is_empty() {
        return None; // empty-default view: the general path short-circuits at the BGP
    }
    let (proj, inner): (Option<&[Variable]>, &GraphPattern) = match pattern {
        GraphPattern::Project { inner, variables } => (Some(variables), inner),
        other => (None, other),
    };
    if !is_conjunctive(inner) {
        return None;
    }
    let mut patterns = Vec::new();
    let mut filters = Vec::new();
    flatten_conjunction(inner, &mut patterns, &mut filters);
    if patterns.len() != 1 {
        return None;
    }
    // Only pushed-down sargable numeric FILTER(s); a residual filter needs the general
    // expression evaluator.
    let (pat_filters, residual) = split_sargable(graph, &patterns, &filters);
    if !residual.is_empty() {
        return None;
    }
    let filt: Option<(usize, ScanCmp)> = pat_filters[0];

    let (id_pat, pos_vars, unsat) = prepare_pattern(graph, &patterns[0]).ok()?;
    if !distinct_pattern_vars(&pos_vars) {
        return None; // a repeated variable needs the consistency check — use the general path
    }
    let out_vars: Vec<Variable> = match proj {
        Some(vs) => vs.iter().filter(|v| !v.as_str().starts_with(BNODE_VAR_PREFIX)).cloned().collect(),
        None => pos_vars.iter().flatten().filter(|v| !v.as_str().starts_with(BNODE_VAR_PREFIX)).cloned().collect(),
    };
    let cols: Vec<Option<usize>> = out_vars.iter().map(|v| pos_vars.iter().position(|x| x.as_ref() == Some(v))).collect();

    let mut head = String::from("{\"head\":{\"vars\":[");
    for (i, v) in out_vars.iter().enumerate() {
        if i > 0 {
            head.push(',');
        }
        head.push('"');
        crate::json::escape_into(&mut head, v.as_str());
        head.push('"');
    }
    head.push_str("]},\"results\":{\"bindings\":[");
    if unsat {
        head.push_str("]}}");
        let _ = emit(head);
        return Some(());
    }

    let scan = match filt {
        Some((c, _)) => graph.store.scan_sorted(&id_pat, c),
        None => graph.store.scan(&id_pat),
    };
    // Range-prune an all-inline filter column (identical to scan_to_bindings) so the
    // order matches the general path exactly (byte-identical output).
    let mut scan_rows: &[[Id; 3]] = scan.rows.as_ref();
    if let Some((fpos, cmp)) = filt {
        let actual_sort = scan.perm.order().into_iter().find(|&c| id_pat[c].is_none());
        if actual_sort == Some(fpos) && scan_rows.first().is_some_and(|r| dict::is_inline(scan.to_spo(r)[fpos])) {
            scan_rows = match inline_pass_values(cmp) {
                Some((lo, hi)) => {
                    let (lo_id, hi_id) = (dict::INLINE_BASE + lo, dict::INLINE_BASE + hi);
                    let start = scan_rows.partition_point(|r| scan.to_spo(r)[fpos] < lo_id);
                    let end = scan_rows.partition_point(|r| scan.to_spo(r)[fpos] <= hi_id);
                    &scan_rows[start..end]
                }
                None => &[],
            };
        }
    }
    // Per-row check: a no-op on a fully range-pruned slice; required for a mixed-datatype
    // column where pruning was skipped.
    let passes = |row: &[Id; 3]| -> bool {
        match filt {
            Some((fpos, cmp)) => cmp.test_id(graph, scan.to_spo(row)[fpos]),
            None => true,
        }
    };
    let write_row = |row: &[Id; 3], s: &mut String| {
        let spo = scan.to_spo(row);
        s.push('{');
        let mut first = true;
        for (vi, &col) in cols.iter().enumerate() {
            let Some(c) = col else { continue };
            if !first {
                s.push(',');
            }
            first = false;
            s.push('"');
            crate::json::escape_into(s, out_vars[vi].as_str());
            s.push_str("\":");
            write_store_id_json(graph, spo[c], s);
        }
        s.push('}');
    };

    let mut s = head;
    // [OPUS-4.8] roborev 1538 / sq-7d3dj.10 (audit item 6): fan the JSON serialize out
    // across cores when the installed budget cannot be violated by doing so — NO budget,
    // or a DEADLINE-ONLY budget (the default HTTP server's 30s timeout, which has no
    // row/byte cap). The fan-out builds every matching fragment before it can know a row
    // or byte count, so a ROW / BYTE cap stays on the cooperative serial loop below
    // (which checks `budget::exhausted` every 1024 rows and stops early). A deadline-only
    // budget is admitted because the coarse `limits.hit(0)` re-check at each par-chunk
    // boundary stops launching new chunks once the wall-clock deadline passes, bounding
    // the overrun to ~one chunk per worker. A blanket !budget-active → true flip is
    // REJECTED (see `parallel_json_fanout`).
    #[cfg(feature = "parallel")]
    if scan_rows.len() >= PAR_THRESHOLD {
        if let Some(limits) = budget::parallel_json_fanout() {
            use rayon::prelude::*;
            // One string per chunk (≈ per worker), not per row — avoids one heap
            // allocation per result cell. Chunks stay in order, so on the success path
            // the bytes are identical to the serial path.
            let chunk = scan_rows.len().div_ceil(rayon::current_num_threads() * 4).max(1);
            let frags: Vec<(usize, String)> = scan_rows
                .par_chunks(chunk)
                .map(|rows| {
                    // Coarse deadline re-check at the chunk boundary: once the wall-clock
                    // deadline has passed, every later chunk produces nothing, so at most
                    // the chunks already in flight (~one per worker) run to completion.
                    // The installing thread's post-fan-out gate turns the passed deadline
                    // into the timeout error, discarding this (now partial) result — so a
                    // skipped chunk NEVER escapes as a truncated body. Under no budget / an
                    // unexpired deadline this is one non-tripping `Instant` read per chunk.
                    if limits.hit(0) {
                        return (0usize, String::new());
                    }
                    let mut n = 0usize;
                    let mut f = String::new();
                    for row in rows {
                        if !passes(row) {
                            continue;
                        }
                        if !f.is_empty() {
                            f.push(',');
                        }
                        n += 1;
                        write_row(row, &mut f);
                    }
                    (n, f)
                })
                .collect();
            // Budget gate on the installing thread over the total row count — and, for a
            // deadline-only budget, the now-past wall clock: sets the sticky flag the
            // caller's `budget::check(0)` converts into the budget error (a chunk skipped
            // above means the deadline is globally past, so this fires deterministically).
            let _ = budget::exhausted(frags.iter().map(|(n, _)| n).sum());
            // Accumulate into `pending` and hand a chunk to `emit` at each flush boundary
            // (byte-identical concatenation to the old `emit_chunk` Vec layout — only the
            // chunk *boundaries* differ, and the concat is what the byte-identity contract
            // covers). `s` already holds the head.
            let mut pending = s;
            let mut wrote = false;
            for (_, f) in frags {
                if f.is_empty() {
                    continue;
                }
                if wrote {
                    pending.push(',');
                }
                wrote = true;
                pending.push_str(&f);
                if flush.is_some_and(|n| pending.len() >= n)
                    && emit(std::mem::take(&mut pending)).is_break()
                {
                    return Some(());
                }
            }
            pending.push_str("]}}");
            let _ = emit(pending);
            return Some(());
        }
    }
    let mut written = 0usize;
    for (i, row) in scan_rows.iter().enumerate() {
        // Coarse budget check every 1024 scanned rows; the caller's sticky check
        // turns an early stop into the budget error (never a truncated result).
        if i & 1023 == 0 && budget::exhausted(written) {
            break;
        }
        if !passes(row) {
            continue;
        }
        if written > 0 {
            s.push(',');
        }
        written += 1;
        write_row(row, &mut s);
        if flush.is_some_and(|n| s.len() >= n) && emit(std::mem::take(&mut s)).is_break() {
            return Some(());
        }
    }
    let _ = budget::exhausted(written); // final row-count gate (sticky)
    s.push_str("]}}");
    let _ = emit(s);
    Some(())
}

/// Evaluates a SELECT and serialises it straight to SPARQL-JSON, skipping the
/// `QueryResult` (and its per-cell `oxrdf::Term` allocation). On native the per-row
/// fragments are built in parallel; the wasm build is sequential.
pub fn eval_select_json(graph: &Graph, pattern: &GraphPattern) -> Result<String, String> {
    Ok(join_chunks(eval_select_json_chunks(graph, pattern, None)?))
}

/// [`eval_select_json`] as an ordered chunk sequence: the concatenation of the chunks
/// is byte-identical to the single-string result. `flush = Some(n)` starts a new chunk
/// roughly every `n` serialised bytes (and hands each parallel fragment over without
/// re-copying); `flush = None` produces the single-string layout (one chunk on the
/// sequential paths, head+fragments concatenated on the parallel path — exactly the
/// old behaviour and allocation profile).
pub fn eval_select_json_chunks(graph: &Graph, pattern: &GraphPattern, flush: Option<usize>) -> Result<Vec<String>, String> {
    let mut out: Vec<String> = Vec::new();
    eval_select_json_emit(graph, pattern, flush, &mut |c| {
        out.push(c);
        ControlFlow::Continue(())
    })?;
    Ok(out)
}

/// [`eval_select_json_chunks`] driven through a per-chunk `emit` callback instead of a
/// collected `Vec<String>`.
///
/// [OPUS-4.8] (sq-7d3dj.34.2) This is the emit core both the buffered `Vec` API (above)
/// and the server's TTFB-streaming HTTP body ([`crate::query_json_stream_with_budget`])
/// share, so the byte layout is defined once. Each serialised chunk is handed to `emit`
/// **as it is produced**: on the streaming path the server writes the results header +
/// early solutions to the socket before the whole result is serialised, and — for the
/// single-pattern scan fast path — before the scan even finishes. `emit` returns
/// [`ControlFlow::Break`] to abandon the rest of the work (the HTTP client disconnected).
///
/// The concatenation of the chunks handed to `emit` is **byte-identical** to
/// [`eval_select_json`]/[`eval_select_json_chunks`] for the same `flush`; only the chunk
/// *boundaries* may differ (the byte-identity contract is over the concatenation). A
/// cooperative budget (row / byte cap or deadline) that trips is surfaced by the caller's
/// `budget::check` as an `Err` exactly as before — but note that on the streaming path
/// early chunks may already have been flushed when the trip is detected (the server maps a
/// post-first-byte trip to a truncated body, since the HTTP status is already committed).
///
/// [SONNET-4.6] (sq-yfcu2) The budget also bounds the SERIALIZE step, not just evaluation:
/// the general (multi-pattern) path re-checks it mid-serialize and gates the final chunk on
/// `budget::check`, so a deadline that falls due *while the materialised set is being
/// serialised* is reported as `Err("query budget exceeded (timeout)")` rather than answered
/// with a complete-but-late result. That is a deliberate behaviour change for late-but-
/// complete results — the budget is a bound on the whole request, and a caller that has
/// stopped waiting must not be charged for a body produced after its deadline.
pub fn eval_select_json_emit(
    graph: &Graph,
    pattern: &GraphPattern,
    flush: Option<usize>,
    emit: &mut dyn FnMut(String) -> ControlFlow<()>,
) -> Result<(), String> {
    // Streaming fast paths — no Bindings materialised at all.
    if single_pattern_scan_json_emit(graph, pattern, flush, emit).is_some() {
        budget::check(0)?; // sticky: the streaming loop may have stopped mid-scan
        return Ok(());
    }
    let mut local = LocalVocab::default();
    let bindings = eval_modified(graph, &mut local, pattern)?;
    budget::check(bindings.rows.len())?; // final gate (see eval_select)

    let out_vars: Vec<&Variable> = bindings.vars.iter().filter(|v| !v.as_str().starts_with(BNODE_VAR_PREFIX)).collect();
    let col_of: Vec<Option<usize>> = out_vars.iter().map(|v| bindings.col(v)).collect();

    let mut head = String::from("{\"head\":{\"vars\":[");
    for (i, v) in out_vars.iter().enumerate() {
        if i > 0 {
            head.push(',');
        }
        head.push('"');
        crate::json::escape_into(&mut head, v.as_str());
        head.push('"');
    }
    head.push_str("]},\"results\":{\"bindings\":[");

    let write_row = |row: &Row, s: &mut String| {
        s.push('{');
        let mut first = true;
        for (vi, &col) in col_of.iter().enumerate() {
            let Some(ci) = col else { continue };
            let id = row[ci];
            if id == NO_ID {
                continue; // unbound (e.g. OPTIONAL) — omitted from the binding
            }
            if !first {
                s.push(',');
            }
            first = false;
            s.push('"');
            crate::json::escape_into(s, out_vars[vi].as_str());
            s.push_str("\":");
            write_id_json(graph, &local, id, s);
        }
        s.push('}');
    };

    let mut s = head;
    // [SONNET-4.6] (sq-yfcu2) The serialize loops below are budget-checked too: the
    // pre-serialize `budget::check` above prices the ROW / BYTE caps exactly (the rows
    // are already materialised, so the count is known — unlike the single-pattern
    // streaming path, which is why this path may fan out under any budget), but
    // serialising a large materialised set is itself unbounded WORK, so a DEADLINE (or a
    // cancellation) can fall due *during* it. Both branches therefore re-check the budget
    // mid-serialize and gate the final chunk on `budget::check` — a late-but-complete
    // result is reported as the budget error, never returned as if it were in time.
    #[cfg(feature = "parallel")]
    if bindings.rows.len() >= PAR_THRESHOLD {
        use rayon::prelude::*;
        // Limit snapshot the workers re-check at each par-chunk boundary (the installing
        // thread's sticky flag is out of reach inside rayon).
        let limits = budget::snapshot();
        // One string per chunk (≈ per worker), not per row. Chunks stay in order → identical bytes.
        let chunk = bindings.rows.len().div_ceil(rayon::current_num_threads() * 4).max(1);
        let frags: Vec<String> = bindings
            .rows
            .par_chunks(chunk)
            .map(|rows| {
                // Coarse deadline/cancel re-check at the chunk boundary: once the budget is
                // past, every later chunk produces nothing, so at most the chunks already in
                // flight (~one per worker) run to completion. The post-fan-out gate below
                // turns that into the budget error and discards this (now partial) result —
                // a skipped chunk never escapes as a truncated body. Under no budget this is
                // one non-tripping read per chunk.
                if limits.hit(0) {
                    return String::new();
                }
                let mut f = String::new();
                for (k, row) in rows.iter().enumerate() {
                    if k > 0 {
                        f.push(',');
                    }
                    write_row(row, &mut f);
                }
                f
            })
            .collect();
        // Accumulate into `s` (which already holds the head) and hand a chunk to `emit` at
        // each flush boundary. The concatenation is byte-identical to the old `emit_chunk`
        // Vec layout; only the chunk boundaries differ. A skipped (empty) fragment is
        // dropped rather than separated by a comma; every non-skipped chunk holds at least
        // one row object, so on the untripped path the `wrote` flag is exactly `i > 0`.
        let mut wrote = false;
        for f in frags {
            if f.is_empty() {
                continue;
            }
            if wrote {
                s.push(',');
            }
            wrote = true;
            s.push_str(&f);
            if flush.is_some_and(|n| s.len() >= n) && emit(std::mem::take(&mut s)).is_break() {
                return Ok(());
            }
        }
        // Post-serialization gate: a deadline that fell due (or a cancellation raised)
        // while the fan-out ran is the query's answer, not this now-late result.
        budget::check(bindings.rows.len())?;
        s.push_str("]}}");
        let _ = emit(s);
        return Ok(());
    }
    for (i, row) in bindings.rows.iter().enumerate() {
        // Coarse re-check every 1024 serialised rows; the post-loop gate turns the early
        // stop into the budget error, so a truncated body is never returned as success.
        if i & 1023 == 0 && budget::exhausted(bindings.rows.len()) {
            break;
        }
        if i > 0 {
            s.push(',');
        }
        write_row(row, &mut s);
        if flush.is_some_and(|n| s.len() >= n) && emit(std::mem::take(&mut s)).is_break() {
            return Ok(());
        }
    }
    budget::check(bindings.rows.len())?; // post-serialization gate (sticky)
    s.push_str("]}}");
    let _ = emit(s);
    Ok(())
}

/// ASK evaluation: `true` iff `pattern` has at least one solution. ASK observes only
/// solution EXISTENCE, so the plan is first simplified shape-locally (`ask_simplify`:
/// ORDER BY / DISTINCT stripped where provably emptiness-neutral) and then wrapped in
/// a `LIMIT 1` slice so the capped paths — the early-terminating single-pattern scan
/// AND the block-driven conjunctive join chain plus the capped UNION / OPTIONAL /
/// Join arms of `try_capped` — stop at the first complete solution instead of
/// materialising the full result. Shapes without a capped path evaluate normally
/// (the row count is irrelevant — only emptiness is observed). [FABLE-5]
/// (sq-7d3dj.30.8)
pub fn eval_ask(graph: &Graph, pattern: &GraphPattern) -> Result<bool, String> {
    // Fail-closed: an armed zk-trace recorder keeps the ORIGINAL plan (its operator
    // markers reference the unsimplified tree; every capped path below already
    // declines while recording, so the recorded evaluation is the full one).
    #[cfg(feature = "zk")]
    let simplified = if crate::zk::enabled() { pattern.clone() } else { ask_simplify(pattern) };
    #[cfg(not(feature = "zk"))]
    let simplified = ask_simplify(pattern);
    // Exact-count fast path (a single-pattern BGP answers from the index).
    if let Some(n) = try_count(graph, &simplified) {
        return Ok(n > 0);
    }
    let sliced = GraphPattern::Slice { inner: Box::new(simplified), start: 0, length: Some(1) };
    let mut local = LocalVocab::default();
    let b = eval_modified(graph, &mut local, &sliced)?;
    budget::check(b.rows.len())?;
    Ok(!b.rows.is_empty())
}

/// Shape-local ASK plan simplification (sq-7d3dj.30.8): strips solution modifiers
/// that provably cannot change solution EXISTENCE, along the top "modifier spine"
/// only — `Project` / `Distinct` / `Reduced` / `OrderBy` chains and `Union`
/// branches, exactly the operators through which emptiness of the root is a function
/// of emptiness of the subtree. `ORDER BY` only reorders rows and `DISTINCT` only
/// removes duplicates, so neither turns an empty result non-empty or vice versa;
/// stripping them lets the LIMIT-1 capped evaluation stop at the first solution
/// instead of sorting / deduplicating a full result nothing observes.
///
/// Deliberately conservative — the recursion STOPS (subtree kept verbatim) at:
/// * `Slice` — OFFSET observes the inner COUNT (`DISTINCT` below an `OFFSET 2` can
///   flip the boolean) and which rows survive a slice depends on the inner order, so
///   everything below a `Slice` stays exactly as written;
/// * every non-modifier operator (`Join` / `Filter` / `Group` / …) whose output
///   depends on the actual rows. In particular aggregation / HAVING is NEVER
///   touched: an empty-group aggregate still yields a solution, so `Group` must
///   evaluate as-is.
fn ask_simplify(p: &GraphPattern) -> GraphPattern {
    match p {
        GraphPattern::OrderBy { inner, .. }
        | GraphPattern::Distinct { inner }
        | GraphPattern::Reduced { inner } => ask_simplify(inner),
        GraphPattern::Project { inner, variables } => GraphPattern::Project {
            inner: Box::new(ask_simplify(inner)),
            variables: variables.clone(),
        },
        GraphPattern::Union { left, right } => GraphPattern::Union {
            left: Box::new(ask_simplify(left)),
            right: Box::new(ask_simplify(right)),
        },
        other => other.clone(),
    }
}

/// Evaluates a SELECT but returns only the solution count. When the count can be
/// derived without materialising the result (a single-pattern scan, possibly under
/// projection / LIMIT — like QLever's lazy count) it short-circuits; otherwise it
/// evaluates and counts the rows.
pub fn count_select(graph: &Graph, pattern: &GraphPattern) -> Result<usize, String> {
    if let Some(n) = try_count(graph, pattern) {
        return Ok(n);
    }
    let mut local = LocalVocab::default();
    let bindings = eval_modified(graph, &mut local, pattern)?;
    budget::check(bindings.rows.len())?; // final gate (see eval_select)
    Ok(bindings.rows.len())
}

/// The solution count without materialising, for shapes whose count is exact from
/// the index: a single-pattern BGP (range size) under projection / OFFSET-LIMIT.
fn try_count(graph: &Graph, p: &GraphPattern) -> Option<usize> {
    // zk-trace: a count/ASK answered from the index range consumes NO
    // attributable input triples, so an armed recorder would capture an
    // empty (insufficient) witness set. Disable the pushdown while recording
    // — the result is identical via the materialising path, only the plan
    // changes (zk module docs: "result-preserving plan changes").
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        return None;
    }
    if view::default_is_empty() {
        return None; // empty-default view: the index ranges are not the active dataset
    }
    match p {
        GraphPattern::Project { inner, .. } | GraphPattern::Reduced { inner } => try_count(graph, inner),
        GraphPattern::Slice { inner, start, length } => try_count(graph, inner).map(|n| {
            let after_offset = n.saturating_sub(*start);
            length.map_or(after_offset, |l| after_offset.min(l))
        }),
        // OPTIONAL: count the left join without materialising (Σ over the join var).
        GraphPattern::LeftJoin { left, right, expression } => {
            count_leftjoin(graph, left, right, expression.as_ref())
        }
        // A single-pattern, filter-free BGP: the range size is the exact count.
        _ => count_pushdown(graph, p),
    }
}

/// The single triple pattern of a filter-free one-pattern BGP, else `None`.
fn single_pattern(p: &GraphPattern) -> Option<TriplePattern> {
    if !is_conjunctive(p) {
        return None;
    }
    let mut patterns = Vec::new();
    let mut filters = Vec::new();
    flatten_conjunction(p, &mut patterns, &mut filters);
    (patterns.len() == 1 && filters.is_empty()).then(|| patterns.pop().unwrap())
}

/// Exact solution count of `left OPTIONAL right` for the common shape — `left` and
/// `right` each a single filter-free pattern sharing exactly one variable `v`, with
/// no OPTIONAL filter — as `Σ_v c_left(v)·max(1, c_right(v))`, streamed from the
/// sorted indexes (each left binding survives, joined with its ≥1 right matches or
/// kept once with the right vars unbound). Returns `None` otherwise.
fn count_leftjoin(
    graph: &Graph,
    left: &GraphPattern,
    right: &GraphPattern,
    expression: Option<&Expression>,
) -> Option<usize> {
    if expression.is_some() {
        return None; // an OPTIONAL filter changes which right rows are compatible.
    }
    let (lp, rp) = (single_pattern(left)?, single_pattern(right)?);
    let (lip, lpv, lu) = prepare_pattern(graph, &lp).ok()?;
    if lu {
        return Some(0); // no left bindings at all.
    }
    if !distinct_pattern_vars(&lpv) {
        return None;
    }
    let (rip, rpv, ru) = prepare_pattern(graph, &rp).ok()?;
    if !distinct_pattern_vars(&rpv) {
        return None;
    }
    // Exactly one shared variable, at positions (lpos, rpos).
    let shared: Vec<(usize, usize)> = lpv
        .iter()
        .enumerate()
        .filter_map(|(i, v)| v.as_ref().and_then(|v| rpv.iter().position(|x| x.as_ref() == Some(v)).map(|j| (i, j))))
        .collect();
    let [(lpos, rpos)] = shared[..] else {
        return None;
    };
    // Σ_v c_left(v)·max(1, c_right(v)), streamed by merging the two sorted group-count
    // streams — left drives, right advances to match — so neither side is materialised.
    let mut left = GroupStream::new(graph, &lip, lpos);
    // Right unsatisfiable: every left binding is kept once with the right unbound.
    if ru {
        let mut total = 0usize;
        while let Some((_, cl)) = left.next() {
            total += cl;
        }
        return Some(total);
    }
    let mut right = GroupStream::new(graph, &rip, rpos);
    let mut rhead = right.next();
    let mut total = 0usize;
    while let Some((v, cl)) = left.next() {
        while let Some((rv, _)) = rhead {
            if rv < v {
                rhead = right.next();
            } else {
                break;
            }
        }
        let cr = match rhead {
            Some((rv, rc)) if rv == v => rc,
            _ => 0,
        };
        total += cl * cr.max(1);
    }
    Some(total)
}

// ---- Algebra dispatch ---------------------------------------------------------

fn eval_modified(graph: &Graph, local: &mut LocalVocab, p: &GraphPattern) -> Result<Bindings, String> {
    // Pin NOW() for this execution (SPARQL 1.1 §17.4.5.1). Outermost call samples
    // the clock once; the recursive / EXISTS re-entries see it active and keep the
    // outer instant (a Cell read). [FABLE-5] sq-98w7z.1
    #[cfg(not(target_arch = "wasm32"))]
    let _query_now = query_now::scope();
    match p {
        GraphPattern::Project { inner, variables } => {
            let b = eval_modified(graph, local, inner)?;
            Ok(project_bindings(b, variables))
        }
        GraphPattern::Distinct { inner } => {
            // zk-trace: the enclosed pattern inputs are the PRE-DISTINCT
            // input sets (the reduction is verifier-side; zk module docs).
            #[cfg(feature = "zk")]
            let _zk = crate::zk::op_scope(crate::zk::Op::Distinct);
            // DISTINCT-projection loose skip-scan: `Distinct{Project{[?p]}{BGP/Union}}`
            // can enumerate the DISTINCT projected values directly from a permutation
            // sorted by ?p (no full-join materialisation). Result-SET equivalent to the
            // path below; conservatively declines (→ None) on any other shape. The zk
            // recorder needs the whole PRE-distinct input set, so the pushdown is
            // suppressed while armed (checked inside `try_distinct_pushdown`).
            // [OPUS-4.8] sq-7d3dj.30.4
            if distinct_pushdown::enabled() {
                if let Some(b) = try_distinct_pushdown(graph, local, inner)? {
                    return Ok(b);
                }
            }
            let mut b = eval_modified(graph, local, inner)?;
            distinct_bindings(&mut b);
            Ok(b)
        }
        GraphPattern::Reduced { inner } => eval_modified(graph, local, inner),
        GraphPattern::Slice { inner, start, length } => {
            // LIMIT early-termination: a bare LIMIT (no ORDER BY / DISTINCT /
            // aggregation above it, which all need the full result) can stop after
            // start+length rows instead of materialising the whole relation — a
            // single-pattern scan stops mid-scan, and a conjunctive / UNION /
            // OPTIONAL / Join shape stops at the first seed blocks yielding enough
            // fully-FILTERed rows (`try_capped`, sq-7d3dj.30.8; ASK evaluates as
            // LIMIT 1 through here). LIMIT-without-ORDER-BY is order-insensitive so
            // any rows are valid.
            if let Some(len) = length {
                if let Some(cap) = start.checked_add(*len) {
                    if let Some(mut b) = try_capped(graph, local, inner, cap)? {
                        slice_bindings(&mut b, *start, *length);
                        return Ok(b);
                    }
                    // Top-k ORDER BY: when the inner pattern (possibly under Project/Reduced)
                    // contains an OrderBy and the budget k = offset + limit is within the
                    // threshold, use bounded selection instead of a full stable sort.
                    // Result is byte-identical to the full-sort+slice path. [SONNET-4.6] sq-7d3dj.30.2
                    if cap <= TOP_K_ORDER_BY_THRESHOLD {
                        if let Some(mut b) = try_topk_orderby(graph, local, inner, cap)? {
                            slice_bindings(&mut b, *start, *length);
                            return Ok(b);
                        }
                    }
                }
            }
            let mut b = eval_modified(graph, local, inner)?;
            slice_bindings(&mut b, *start, *length);
            Ok(b)
        }
        GraphPattern::OrderBy { inner, expression } => {
            let mut b = eval_modified(graph, local, inner)?;
            order_bindings(graph, local, &mut b, expression, None)?;
            Ok(b)
        }
        GraphPattern::Group { inner, variables, aggregates } => {
            // zk-trace: the enclosed pattern inputs are the PRE-AGGREGATION
            // input sets; the count pushdown below is disabled under an armed
            // recorder (inside `try_count`), so they are always captured.
            #[cfg(feature = "zk")]
            let _zk = crate::zk::op_scope(crate::zk::Op::Group);
            // COUNT(*) pushdown: a whole-dataset COUNT over a single pattern is the
            // scan range size — no need to materialise the solutions just to count
            // them (QLever counts lazily too; this is the q02-style win).
            if variables.is_empty() && aggregates.len() == 1 {
                if let (av, AggregateExpression::CountSolutions { distinct: false }) = (&aggregates[0].0, &aggregates[0].1) {
                    // COUNT(*) == the inner pattern's solution count. Use `try_count`, not
                    // just `count_pushdown`: it also covers OPTIONAL (lazy left-join count,
                    // Σ over the join var) and LIMIT/OFFSET — so `COUNT(*)` over an OPTIONAL
                    // no longer materialises the whole left-join just to count it.
                    if let Some(n) = try_count(graph, inner) {
                        let id = value_to_id(graph, local, &Value::Num(Num::Int(n as i64)));
                        let row: Row = std::iter::once(id).collect();
                        return Ok(Bindings { vars: vec![av.clone()], rows: vec![row], sorted_by: None });
                    }
                }
            }
            let b = eval_graph_pattern(graph, local, inner)?;
            group_aggregate(graph, local, b, variables, aggregates)
        }
        other => eval_graph_pattern(graph, local, other),
    }
}

/// Attempts the bounded-heap ORDER BY optimisation for a `Slice` with a known
/// row budget `k = offset + limit`.
///
/// Peeks through `Project` / `Reduced` transparent wrappers to find an `OrderBy`
/// node. When found, evaluates the pattern below the `OrderBy`, sorts using
/// `order_bindings` with the top-k hint so only `k` rows survive, applies any
/// projection, and returns `Some(Bindings)`. Returns `None` when no `OrderBy`
/// is present at the transparent-wrapper boundary — the caller falls through to
/// full `eval_modified`. [SONNET-4.6] sq-7d3dj.30.2
fn try_topk_orderby(
    graph: &Graph,
    local: &mut LocalVocab,
    inner: &GraphPattern,
    row_budget: usize,
) -> Result<Option<Bindings>, String> {
    match inner {
        GraphPattern::Project { inner: proj_inner, variables } => {
            Ok(try_topk_orderby(graph, local, proj_inner, row_budget)?
                .map(|b| project_bindings(b, variables)))
        }
        GraphPattern::Reduced { inner: red_inner } => {
            try_topk_orderby(graph, local, red_inner, row_budget)
        }
        GraphPattern::OrderBy { inner: ord_inner, expression } => {
            // [SONNET-5] (sq-artifact-keeper-topk) Try the index-ordered seed path
            // first: for the narrow "star BGP, ORDER BY a variable bound by exactly
            // one pattern's object" shape, it walks a value-sorted permutation scan
            // directly instead of materialising every matching row — see
            // `try_topk_orderby_indexed`'s doc comment for the soundness argument.
            // Declines (`Ok(None)`) for any shape/datatype it can't prove safe, in
            // which case the existing materialize-then-select path below runs
            // unchanged.
            if let Some(b) = try_topk_orderby_indexed(graph, local, ord_inner, expression, row_budget)? {
                return Ok(Some(b));
            }
            let mut b = eval_modified(graph, local, ord_inner)?;
            // Use the top-k path only when the budget is strictly less than n;
            // otherwise the heap adds overhead with no benefit.
            let use_topk = b.rows.len() > row_budget;
            order_bindings(graph, local, &mut b, expression, if use_topk { Some(row_budget) } else { None })?;
            Ok(Some(b))
        }
        // Not an OrderBy under transparent wrappers: decline so the caller
        // falls through to the regular eval_modified path.
        _ => Ok(None),
    }
}

/// [SONNET-5] (sq-artifact-keeper-topk) Attempts INDEX-ORDERED top-k evaluation for a
/// `Slice{OrderBy{BGP}}` shape whose primary sort key is bound by exactly one triple
/// pattern's OBJECT. `try_topk_orderby`'s existing bounded-heap path still calls
/// `eval_modified` to fully evaluate (and materialise) the WHOLE matching candidate
/// set before selecting the top `row_budget` rows — `O(n)` in the number of rows
/// CURRENTLY matching the BGP's equality filters, not in `row_budget`. That is fine
/// when some pattern is selective, but when every pattern matches nearly the same
/// rows (e.g. a job-queue "claim the next pending task for peer X, ordered by
/// priority" query, where `peer` + `status` don't shrink the candidate set at all),
/// there is no cheaper seed for the cardinality-based planner to pick, and the cost
/// scales with the size of the whole pending queue on every single claim — profiled
/// and confirmed via `EXPLAIN ANALYZE` (the BGP operator reports touching every
/// matching row) in the sparq/artifact-keeper migration's claim-queue throughput
/// investigation.
///
/// SOUNDNESS. Only activates for a narrow, syntactically-verified "star" shape, and
/// declines (`Ok(None)`) at the first sign of anything it cannot prove safe — the
/// caller's `eval_modified`-then-select path is always correct, just `O(n)`; this
/// function's only job is to be a provably-equivalent shortcut, never a new source
/// of results:
/// - `ord_inner` is a plain triple-pattern conjunction with NO residual FILTER and
///   no blank nodes (kept out of scope for this first cut).
/// - The FIRST order key is a bare `Variable` (secondary tie-break keys, if any,
///   are resolved by re-using `order_bindings` over the small collected set below —
///   not reimplemented here).
/// - Exactly one pattern (the "seed") binds that variable as its OBJECT, with a
///   CONSTANT predicate and a VARIABLE subject (the join "hub").
/// - Every OTHER pattern has that same hub variable as its SUBJECT and a CONSTANT
///   predicate (a star join around the hub); any object variable it introduces must
///   not appear anywhere else in the BGP. Any other shape (the hub appearing
///   elsewhere, a variable predicate, a reused object variable) declines.
/// - Every object id on the seed's sorted scan is an INLINE small integer
///   (`dict::is_inline`) — the only case where ascending dictionary-id order is
///   proven to equal ascending SPARQL `value()` order (the same guard
///   `scan_to_bindings`'s range-pruning already relies on for the same reason).
///   Checked for the WHOLE scan up front, before any result is built, so a
///   non-inline id never leaks a partially-computed (and potentially
///   wrongly-ordered) answer.
///
/// Under those conditions, walking the seed's sorted scan in the required
/// direction, testing each candidate hub value against the OTHER patterns via a
/// direct bound lookup (index-nested-loop / bind join over a per-pattern
/// subject-sorted range resolved once, not re-resolved per candidate — see the
/// `other_pats` construction below), and stopping once a COMPLETE sort-key group
/// (never split mid-tie) has produced at least `row_budget` confirmed joins
/// yields EXACTLY the rows `eval_modified` + `order_bindings` would: a candidate
/// in an unvisited group is, by construction, sort-key-worse than every
/// already-confirmed one (or sort-key-better but not yet visited, in the
/// opposite direction — either way strictly ordered relative to what's been
/// collected), so it can never enter the true top `row_budget`.
///
/// PERFORMANCE, not soundness: a single escalation block is also capped at a
/// fraction of the candidate pool (see `max_group` below) — exceeding it
/// declines (`Ok(None)`) even though continuing would still be CORRECT, because
/// past that point this function's per-candidate cost stops being cheaper than
/// the fallback's bulk join (measured; see `max_group`'s comment). This keeps
/// the function's only failure mode "sometimes it doesn't help," never
/// "sometimes it's slower than doing nothing."
fn try_topk_orderby_indexed(
    graph: &Graph,
    local: &mut LocalVocab,
    ord_inner: &GraphPattern,
    expression: &[OrderExpression],
    row_budget: usize,
) -> Result<Option<Bindings>, String> {
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        return Ok(None);
    }
    if view::default_is_empty() {
        return Ok(None);
    }
    let Some((desc, order_var)) = expression.first().and_then(|oe| match oe {
        OrderExpression::Asc(Expression::Variable(v)) => Some((false, v.clone())),
        OrderExpression::Desc(Expression::Variable(v)) => Some((true, v.clone())),
        _ => None,
    }) else {
        return Ok(None);
    };
    if !is_conjunctive(ord_inner) {
        return Ok(None);
    }
    let mut patterns = Vec::new();
    let mut filters = Vec::new();
    flatten_conjunction(ord_inner, &mut patterns, &mut filters);
    if !filters.is_empty() || patterns.is_empty() {
        return Ok(None);
    }
    // Out of scope for this first cut: blank nodes are treated as synthetic
    // variables by `prepare_pattern` (`bnode_var`) but not necessarily by
    // `collect_vars`'s header-construction — decline rather than risk a header
    // mismatch.
    let has_blank_node = patterns.iter().any(|tp| {
        matches!(tp.subject, TermPattern::BlankNode(_)) || matches!(tp.object, TermPattern::BlankNode(_))
    });
    if has_blank_node {
        return Ok(None);
    }

    // Locate the ONE seed pattern binding `order_var` as its object with a
    // constant predicate and a variable subject.
    let mut seed_idx = None;
    for (i, tp) in patterns.iter().enumerate() {
        if !matches!(&tp.object, TermPattern::Variable(v) if *v == order_var) {
            continue;
        }
        if !matches!(&tp.predicate, NamedNodePattern::NamedNode(_)) {
            return Ok(None);
        }
        if !matches!(&tp.subject, TermPattern::Variable(_)) {
            return Ok(None);
        }
        if seed_idx.is_some() {
            return Ok(None); // order_var bound by more than one pattern: not this shape
        }
        seed_idx = Some(i);
    }
    let Some(seed_idx) = seed_idx else { return Ok(None) };
    let hub_var = match &patterns[seed_idx].subject {
        TermPattern::Variable(v) => v.clone(),
        _ => unreachable!("checked above"),
    };

    // Every OTHER pattern must be `hub_var <constant predicate> (var|const)` — a
    // star around the hub — and any variable it introduces must be fresh.
    let mut other_vars: FxHashSet<Variable> = FxHashSet::default();
    for (i, tp) in patterns.iter().enumerate() {
        if i == seed_idx {
            continue;
        }
        if !matches!(&tp.subject, TermPattern::Variable(v) if *v == hub_var) {
            return Ok(None);
        }
        if !matches!(&tp.predicate, NamedNodePattern::NamedNode(_)) {
            return Ok(None);
        }
        if let TermPattern::Variable(v) = &tp.object {
            if *v == hub_var || *v == order_var || !other_vars.insert(v.clone()) {
                return Ok(None);
            }
        }
    }

    let out_vars = collect_vars(&patterns);
    if row_budget == 0 {
        return Ok(Some(Bindings::unsorted(out_vars, vec![])));
    }

    // Resolve + scan the seed pattern sorted by its OBJECT (canonical column 2).
    let (seed_id_pat, _seed_pos_vars, seed_unsat) = prepare_pattern(graph, &patterns[seed_idx])?;
    if seed_unsat {
        return Ok(Some(Bindings::unsorted(out_vars, vec![])));
    }
    let scan = graph.store.scan_sorted(&seed_id_pat, 2);
    let actual_sort = scan.perm.order().into_iter().find(|&c| seed_id_pat[c].is_none());
    if actual_sort != Some(2) {
        return Ok(None); // this store build can't give us an object-sorted scan
    }
    let rows: &[[Id; 3]] = scan.rows.as_ref();
    // Guard: EVERY object id on this scan must be an inline integer, or ascending
    // id order is not proven to be ascending value order.
    if !rows.iter().all(|r| dict::is_inline(scan.to_spo(r)[2])) {
        return Ok(None);
    }

    // Prepare the other patterns ONCE, each as a SUBJECT-sorted scan over its
    // (fixed predicate [+ fixed object]) range — not re-resolved per candidate.
    // The first cut of this function called `graph.store.scan(&probe_pat)`
    // fresh for every (candidate, other-pattern) pair, which re-runs
    // `Store::choose`'s permutation selection + bound computation every single
    // time even though the choice is IDENTICAL across all candidates for a
    // given pattern (only the subject varies). That repeated per-call setup —
    // not the underlying lookup — is what made a large tie-group lose to the
    // fallback's bulk merge-join (which resolves the permutation ONCE per
    // pattern, not once per row). Resolving it once here and binary-searching
    // the resulting sorted slice per candidate removes that repeated cost.
    struct OtherPat<'g> {
        scan: sparq_core::store::Scan<'g>,
        // Precomputed ONCE (not per candidate, not per binary-search
        // comparison step): the subject id of every row in `scan`, in the
        // SAME (subject-sorted) order. `partition_point` over this plain
        // `&[Id]` does a trivial integer compare per step; searching `scan`
        // directly would call `to_spo` (a permutation-order reconstruction)
        // on EVERY comparison, i.e. ~log(m) reconstructions per candidate per
        // pattern — measured as a real remaining cost for a long skip-prefix
        // (many candidates probed and rejected in a row): reconstructing the
        // full [S,P,O] triple just to read column 0 is wasted work when the
        // search only ever needs that one column.
        subject_ids: Vec<Id>,
        obj_var: Option<Variable>,
    }
    let mut other_pats: Vec<OtherPat> = Vec::with_capacity(patterns.len().saturating_sub(1));
    for (i, tp) in patterns.iter().enumerate() {
        if i == seed_idx {
            continue;
        }
        let (id_pat, pos_vars, unsat) = prepare_pattern(graph, tp)?;
        if unsat {
            // A constant elsewhere in the BGP absent from the dictionary makes the
            // WHOLE conjunction empty (a BGP join against an empty relation).
            return Ok(Some(Bindings::unsorted(out_vars, vec![])));
        }
        let probe_id_pat: IdPattern = [None, id_pat[1], id_pat[2]];
        let sub_scan = graph.store.scan_sorted(&probe_id_pat, 0);
        let sub_actual_sort = sub_scan.perm.order().into_iter().find(|&c| probe_id_pat[c].is_none());
        if sub_actual_sort != Some(0) {
            // This store build can't give a subject-sorted scan for this
            // pattern (e.g. no PSO permutation under `compact-index`/wasm) —
            // decline rather than binary-search an unsorted range.
            return Ok(None);
        }
        let subject_ids: Vec<Id> = sub_scan.rows.iter().map(|r| sub_scan.to_spo(r)[0]).collect();
        other_pats.push(OtherPat { scan: sub_scan, subject_ids, obj_var: pos_vars[2].clone() });
    }

    // UPFRONT cost check, before touching a single candidate: each `other_pats`
    // scan's row count is the EXACT (not estimated) global cardinality of that
    // pattern's own (predicate [+ object]) constraint. If any of them is
    // already meaningfully smaller than the seed's own scan (`rows.len()`),
    // the fallback's ordinary smallest-estimate seed selection will pick THAT
    // pattern as ITS seed and materialize only that small set — beating this
    // function's priority-ordered walk outright, with no reason to compete.
    //
    // This is exactly the realistic "claim strictly in priority order" shape:
    // as such a queue drains, `ak:status="pending"` becomes highly selective
    // while THIS function's seed (`ak:priority`, spanning the whole pool
    // including now-claimed rows) does not shrink at all. Without this check,
    // the only way to discover that is by actually walking past the
    // ever-growing already-claimed prefix, probing (and rejecting) each one —
    // real, wasted, unrecoverable cost. Measured directly: at n=1600 with
    // 1000 of 1600 already claimed (600 truly pending), that reactive
    // discovery cost ~237-272us total (wasted probes + the fallback anyway)
    // vs. this upfront check's ~172-180us (matches a clean fallback-only
    // cost, because it declines before doing ANY per-candidate work).
    let seed_card = rows.len();
    let min_other_card = other_pats.iter().map(|op| op.scan.rows.len()).min().unwrap_or(seed_card);
    if min_other_card.saturating_mul(2) < seed_card {
        return Ok(None);
    }

    // The output column list is FIXED across every candidate (hub, order, then
    // each other pattern's object variable, in pattern order) — compute it and
    // the out_vars -> column-position mapping ONCE, not per candidate.
    let mut cols: Vec<Variable> = Vec::with_capacity(2 + other_pats.len());
    cols.push(hub_var.clone());
    cols.push(order_var.clone());
    for op in &other_pats {
        if let Some(ov) = &op.obj_var {
            cols.push(ov.clone());
        }
    }
    let out_to_cols: Vec<Option<usize>> = out_vars.iter().map(|v| cols.iter().position(|c| c == v)).collect();
    let emit = |ids: &[Id], collected: &mut Vec<Row>| {
        let mut row = Row::with_capacity(out_to_cols.len());
        for pos in &out_to_cols {
            row.push(pos.map(|i| ids[i]).unwrap_or(NO_ID));
        }
        collected.push(row);
    };

    // Walk the sorted scan in the required direction, in escalating blocks aligned
    // to complete sort-key (object-id) groups, joining each candidate against the
    // other patterns via a direct bound lookup (index-nested-loop / bind join).
    //
    // `rows` is always ASCENDING by object id (the scan's actual sort order). For
    // DESC, "best first" means walking it back-to-front. Rather than slicing from
    // the front and reversing per block (which — subtly, and wrongly — visits the
    // SMALLEST values first regardless of direction, since the slice bounds
    // themselves were never flipped), define a single LOGICAL index `0..n` where
    // position 0 is always the best candidate, via `logical`, and do all
    // block/boundary arithmetic in that space. `logical` and `obj_id_at` are the
    // only direction-aware code; everything below them is direction-agnostic.
    let n = rows.len();
    let logical = |i: usize| -> usize { if desc { n - 1 - i } else { i } };
    let obj_id_at = |i: usize| -> Id { scan.to_spo(&rows[logical(i)])[2] };
    // A single escalation block is dominated by ONE large tie-group when the
    // sort key has low cardinality (e.g. a handful of discrete priority tiers:
    // "urgent/high/normal/low", not a near-unique value per row). This
    // function's per-candidate cost is roughly CONSTANT per candidate (a
    // binary search per other pattern, resolved against a scan fetched once —
    // see `other_pats` below), while the fallback's bulk merge-join cost is
    // roughly constant PER `n` regardless of tie structure (it materialises the
    // whole matching set before it can sort). So the crossover is a FRACTION of
    // `n`, not an absolute row count: measured at n=1600, a tie-group of 800
    // (half of n) still beat the fallback (~228us vs. the fallback's ~269us),
    // but a tie-group of 1600 (all of n) lost (would be ~450-700us vs. the
    // fallback's own ~269us) — and the same ~0.5-0.75 fraction held at n=8000
    // (4000 still competitive, 8000 clearly lost). `max_group` below is
    // therefore `n / 2` (with a floor for small `n`, and never below
    // `row_budget` itself) — declining past it defers to the fallback, whose
    // cost at that point is exactly its normal (tie-structure-independent)
    // cost, not a new regression.
    const MAX_INDEXED_GROUP_FLOOR: usize = 256;
    let mut collected: Vec<Row> = Vec::new();
    let mut visited_to: usize = 0;
    // Block sizes grow GEOMETRICALLY from a small multiple of `row_budget`, not
    // from `CAPPED_SEED_BLOCK` (1024): each candidate here costs a real
    // per-pattern binary search (against the scan `other_pats` already resolved
    // once, above), unlike the bulk merge-join the fallback path uses, which
    // amortises its own permutation selection over the WHOLE scan in one pass.
    // For the common case (small `row_budget`, most candidates
    // join successfully), starting near `row_budget` means the first block alone
    // usually satisfies it — starting at 1024 would pay ~1024 point-probes even for
    // `LIMIT 1`, which is worse than the bulk path it's meant to beat (measured:
    // this was the actual cause of a regression at moderate `n`, not a win).
    let max_group = (n / 2).max(MAX_INDEXED_GROUP_FLOOR).max(row_budget.saturating_mul(2));
    // Cumulative count of candidates that failed an OTHER-pattern check, across
    // ALL blocks in this call — distinct from `max_group`'s per-block width
    // check. A workload that claims strictly in priority order (the realistic
    // shape: highest priority first) leaves an ever-growing prefix of
    // ALREADY-CLAIMED, high-priority-but-no-longer-`pending` rows at the head
    // of the seed scan — each one still costs a real per-pattern probe before
    // being rejected. That prefix is made of individually DISTINCT priority
    // values, so it never forms one oversized tie-group `max_group` would
    // catch; it spreads across many small geometric-growth blocks instead. The
    // UPFRONT cost check above (comparing `other_pats`' exact cardinalities to
    // the seed's) already declines the CLEAR case — an other-pattern that's
    // globally selective enough for the fallback's own planner to prefer as
    // ITS seed — before any candidate is even touched. This counter is a
    // SAFETY NET for what that check can't see: the seed's global cardinality
    // vs. an other-pattern's global cardinality doesn't capture every
    // possible skip-prefix shape (e.g. a correlation between scan order and
    // an other-pattern's matches that isn't visible from cardinality alone).
    //
    // The budget here must stay LARGE (matching `max_group`, not a small
    // constant): every failed probe before declining is pure waste stacked ON
    // TOP OF the fallback's full cost, but a SMALL budget bails on the far
    // more common "moderate skip-prefix" case too — one that would have
    // SUCCEEDED cheaply if allowed to keep going (a candidate ~100-800
    // positions in costs only tens of us to walk to, vastly cheaper than a
    // ~100-350us fallback). Measured directly: tightening this to a small
    // constant (64) made the COMMON moderate case (already-claimed ~100-400)
    // cost ~225-275us (forced into a fallback the upfront check didn't catch
    // and completion would have avoided entirely) instead of the ~15-70us it
    // gets by simply being allowed to finish. A large budget's own worst case
    // (a skip-prefix near `n/2`, right at the edge) is bounded and modest by
    // comparison (~30-50% over a clean fallback, not multiples of it) — an
    // acceptable price for a case the upfront check should catch almost
    // always in practice anyway.
    let failure_budget = max_group;
    let mut failed_count: usize = 0;
    let mut block_target = row_budget.saturating_mul(4).max(16);
    loop {
        if visited_to >= n {
            break;
        }
        let mut end = block_target.clamp(visited_to, n);
        // Extend to the next object-id group boundary so a tie is never split
        // across blocks (the early-stop check below requires a COMPLETE group).
        if end < n && end > 0 {
            let boundary_obj = obj_id_at(end - 1);
            while end < n && obj_id_at(end) == boundary_obj {
                end += 1;
            }
        }
        if end - visited_to > max_group {
            return Ok(None);
        }
        for i in visited_to..end {
            let spo = scan.to_spo(&rows[logical(i)]);
            let hub_id = spo[0];
            let order_id = spo[2];
            // FAST PATH: assume single-valued (the realistic schema shape — a
            // task has exactly one status/priority/seq), building ONE row with
            // no heap allocation beyond the SmallVec's inline capacity. Only a
            // genuinely multi-valued predicate (rare) allocates, and only then
            // — this is what the earlier `Vec<SmallVec>`-per-candidate
            // cartesian machinery paid unconditionally, which (combined with
            // the per-candidate `cols` rebuild) was the dominant remaining
            // cost for a large tie-group after the binary-search fix alone.
            let mut row_ids: SmallVec<[Id; 8]> = SmallVec::from_slice(&[hub_id, order_id]);
            let mut fanout: Option<Vec<SmallVec<[Id; 8]>>> = None;
            let mut failed = false;
            for op in &other_pats {
                // Binary-search the PRECOMPUTED, plain-`Id` subject list for
                // this pattern (built once, above) — a trivial integer
                // compare per step, no `to_spo` reconstruction during the
                // search itself (that only happens below, per ACTUAL match,
                // not per comparison step — see `subject_ids`'s doc comment).
                let start = op.subject_ids.partition_point(|&id| id < hub_id);
                let stop = start + op.subject_ids[start..].partition_point(|&id| id == hub_id);
                if start == stop {
                    failed = true;
                    break;
                }
                let Some(_) = &op.obj_var else {
                    continue; // `obj_const` — existence-only, no column added
                };
                let op_rows: &[[Id; 3]] = op.scan.rows.as_ref();
                let match_count = stop - start;
                if let Some(rows_so_far) = fanout.as_mut() {
                    let mut next = Vec::with_capacity(rows_so_far.len() * match_count);
                    for r in rows_so_far.iter() {
                        for row in &op_rows[start..stop] {
                            let mut nr = r.clone();
                            nr.push(op.scan.to_spo(row)[2]);
                            next.push(nr);
                        }
                    }
                    *rows_so_far = next;
                } else if match_count == 1 {
                    row_ids.push(op.scan.to_spo(&op_rows[start])[2]);
                } else {
                    let mut next = Vec::with_capacity(match_count);
                    for row in &op_rows[start..stop] {
                        let mut nr = row_ids.clone();
                        nr.push(op.scan.to_spo(row)[2]);
                        next.push(nr);
                    }
                    fanout = Some(next);
                }
            }
            if failed {
                failed_count += 1;
                if failed_count > failure_budget {
                    return Ok(None);
                }
                continue;
            }
            match &fanout {
                None => emit(&row_ids, &mut collected),
                Some(rows) => {
                    for r in rows {
                        emit(r, &mut collected);
                    }
                }
            }
        }
        visited_to = end;
        if collected.len() >= row_budget {
            break; // a COMPLETE group boundary was just finished — safe to stop
        }
        block_target = block_target.saturating_mul(4).max(visited_to + 1);
    }

    let mut result = Bindings { vars: out_vars, rows: collected, sorted_by: None };
    let use_topk = result.rows.len() > row_budget;
    order_bindings(graph, local, &mut result, expression, if use_topk { Some(row_budget) } else { None })?;
    Ok(Some(result))
}

/// [OPUS-4.8] (sq-7d3dj.30.4) Attempts the DISTINCT-projection loose skip-scan for the
/// pattern under a `Distinct`.
///
/// Returns `Some(bindings)` when `inner` is `Project{[?p]}{ body }` (a SINGLE projected
/// variable) and every UNION branch of `body` is a filter-free BGP that admits direct
/// enumeration of the DISTINCT `?p` values from an existing permutation sorted by `?p`
/// (a loose/skip scan — the general form of qlever's pattern trick over the six
/// permutations, NO new index). Returns `None` on ANY other shape, so the caller falls
/// back to the full materialise-then-dedup path. Because the enumerated set is exactly
/// `{ v : ∃ a solution of the branch with ?p = v }`, unioned across branches, the result
/// is DISTINCT-set equivalent to the fallback by construction.
///
/// The zk completeness witness needs the whole PRE-distinct input set, so the pushdown
/// declines while the recorder is armed.
fn try_distinct_pushdown(
    graph: &Graph,
    _local: &mut LocalVocab,
    inner: &GraphPattern,
) -> Result<Option<Bindings>, String> {
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        return Ok(None);
    }
    // An empty-default dataset view short-circuits the BGP at eval time; stay on the
    // general path so the view semantics are applied uniformly.
    if view::default_is_empty() {
        return Ok(None);
    }
    // Shape gate: DISTINCT over a single-variable projection.
    let (pvar, body) = match inner {
        GraphPattern::Project { inner, variables } if variables.len() == 1 => {
            (&variables[0], inner.as_ref())
        }
        _ => return Ok(None),
    };

    let mut branches: Vec<&GraphPattern> = Vec::new();
    collect_union_branches(body, &mut branches);

    // Global first-seen dedup across branches — a value found in an earlier branch is
    // never re-enumerated (the "already-seen" set of the loose scan).
    let mut seen: FxHashSet<Id> = FxHashSet::default();
    let mut out_ids: Vec<Id> = Vec::new();
    let mut total_scanned = 0usize;
    // [FABLE-5] (sq-7d3dj.30.10) Cache the sorted anchor membership set across branches:
    // UNION branches frequently share the same anchor pattern (SP2Bench q09's two branches
    // both anchor on `?person rdf:type foaf:Person`), so building the ~20k-member set once
    // instead of per-branch removes the second full anchor scan+sort. Keyed by the anchor's
    // prepared id-pattern + join position, which fully determines the set.
    let mut anchor_cache: AnchorCache = FxHashMap::default();
    // [FABLE-5] (sq-jnb1e) Opt-in predicate-incidence cache: shared across branches so the two
    // q09 semijoins (subject- and object-join) each build their incidence set at most once.
    #[cfg(feature = "cs-anchor-incidence")]
    let mut incidence_cache: IncidenceCache = FxHashMap::default();

    for branch in &branches {
        match branch_distinct_values(
            graph,
            branch,
            pvar,
            &seen,
            &mut anchor_cache,
            #[cfg(feature = "cs-anchor-incidence")]
            &mut incidence_cache,
        )? {
            Some((new_ids, scanned)) => {
                total_scanned = total_scanned.saturating_add(scanned);
                for id in new_ids {
                    if seen.insert(id) {
                        out_ids.push(id);
                    }
                }
            }
            // Any branch we cannot fully enumerate → decline the whole pushdown so the
            // fallback produces the (equivalent) answer for the entire pattern.
            None => return Ok(None),
        }
    }

    distinct_pushdown::record(out_ids.len(), total_scanned);
    let rows: Vec<Row> = out_ids.iter().map(|&id| std::iter::once(id).collect()).collect();
    Ok(Some(Bindings { vars: vec![pvar.clone()], rows, sorted_by: None }))
}

/// Flattens a (possibly nested) `UNION` into its branch patterns; a non-union pattern is
/// a single branch. DISTINCT over `A UNION B` equals DISTINCT over the union of the
/// per-branch value sets, so each branch is enumerated independently.
fn collect_union_branches<'a>(p: &'a GraphPattern, out: &mut Vec<&'a GraphPattern>) {
    match p {
        GraphPattern::Union { left, right } => {
            collect_union_branches(left, out);
            collect_union_branches(right, out);
        }
        other => out.push(other),
    }
}

/// The canonical triple positions (0=subject, 1=predicate, 2=object) at which `var`
/// appears in a prepared pattern's `pos_vars`.
fn var_positions_of(pos_vars: &[Option<Variable>; 3], var: &Variable) -> Vec<usize> {
    (0..3).filter(|&i| pos_vars[i].as_ref() == Some(var)).collect()
}

/// The single query variable shared by both patterns' `pos_vars`, or `None` unless
/// EXACTLY one distinct variable is shared (the clean single-join-variable case).
fn single_shared_var<'a>(
    a: &'a [Option<Variable>; 3],
    b: &[Option<Variable>; 3],
) -> Option<&'a Variable> {
    let mut shared: Vec<&Variable> = Vec::new();
    for v in a.iter().flatten() {
        if b.iter().flatten().any(|w| w == v) && !shared.contains(&v) {
            shared.push(v);
        }
    }
    if shared.len() == 1 {
        Some(shared[0])
    } else {
        None
    }
}

/// The built permutation whose canonical column order is exactly `order`, if any.
fn perm_for_order(order: [usize; 3]) -> Option<sparq_core::store::Perm> {
    sparq_core::store::Perm::ALL.into_iter().find(|p| p.order() == order)
}

/// [FABLE-5] (sq-7d3dj.30.10) The distinct ids at canonical position `target_pos` of
/// `id_pat`'s matching triples, returned SORTED ASCENDING and deduped. The membership set
/// for a semi-join, returned as a sorted `Vec<Id>` (rather than a hash set):
/// it lets the per-predicate existence check gallop the anchor (skipping large
/// disjoint id runs on the anchor side) instead of a per-join-value hash probe, and it
/// avoids the `HashMap` rehash cost that dominated the anchor build for a 20k-member
/// anchor (SP2Bench q09 profile). When the chosen permutation already yields
/// `target_pos` as its first unbound (leading) column the rows arrive grouped, so we
/// skip-scan the distinct values directly in sorted order (no post-sort); otherwise we
/// collect then `sort_unstable`. `None` declines under budget pressure so the caller
/// falls back to the general path.
fn collect_var_ids_sorted(graph: &Graph, id_pat: &IdPattern, target_pos: usize) -> Option<Vec<Id>> {
    // A permutation sorted by `target_pos` as its first UNBOUND column yields the join
    // values already grouped and ascending — enumerate the distinct run heads directly.
    let scan = graph.store.scan_sorted(id_pat, target_pos);
    let order = scan.perm.order();
    let k = order.iter().position(|&c| c == target_pos)?;
    let rows = scan.rows.as_ref();
    if order.into_iter().find(|&c| id_pat[c].is_none()) == Some(target_pos) {
        let mut out: Vec<Id> = Vec::new();
        let mut i = 0usize;
        while i < rows.len() {
            if budget::exhausted(out.len()) {
                return None;
            }
            let v = rows[i][k];
            out.push(v);
            i += rows[i..].partition_point(|r| r[k] <= v).max(1);
        }
        // `out` is strictly increasing by construction (each pushed value exceeds the
        // previous block's) — already sorted + deduped.
        return Some(out);
    }
    // Not sorted by `target_pos`: collect then sort+dedup.
    let mut out: Vec<Id> = Vec::with_capacity(rows.len());
    for (n, r) in rows.iter().enumerate() {
        if n & 4095 == 0 && budget::exhausted(out.len()) {
            return None;
        }
        out.push(r[k]);
    }
    out.sort_unstable();
    out.dedup();
    Some(out)
}

/// [FABLE-5] (sq-7d3dj.30.10) Existence check for the loose semi-join: does the
/// join-sorted `block` (join value at column `jk`) share ANY id with `anchor`? Drives from
/// whichever side is shorter and early-exits on the first common id:
/// * anchor ≥ block: gallop the block's DISTINCT join values, O(1) hash-probe each into
///   the anchor (the original per-value probe — best when the block is short or hits fast);
/// * anchor <  block: walk the (shorter) sorted anchor, binary-searching each member into
///   the block's join column over a monotonically shrinking window (`O(|anchor|·log|block|)`
///   — best when a large no-hit block is checked against a smaller anchor).
///
/// Both strategies are exact and order-independent; the choice only affects work, never the
/// boolean. `examined` (distinct values touched) feeds the diagnostic scan counter.
fn block_intersects_anchor(block: &[[Id; 3]], jk: usize, anchor: &AnchorSet) -> (bool, usize) {
    // Cost model: the hash gallop touches ~`distinct(block)` values at O(1) each; the
    // anchor walk does `|anchor|` binary searches at O(log|block|) each. Prefer the anchor
    // walk only when it is strictly cheaper — i.e. when the anchor is small enough that
    // `|anchor|·log|block|` beats the block's distinct-value count (bounded by `block.len()`).
    // A conservative proxy: anchor smaller than `block.len() / ilog2(block.len())`.
    let block_len = block.len();
    let log_block = usize::BITS as usize - block_len.leading_zeros() as usize; // ~ceil(log2)
    let anchor_driven = block_len > 0 && anchor.sorted.len().saturating_mul(log_block.max(1)) < block_len;
    if !anchor_driven {
        // Gallop the block's distinct join values; O(1) hash membership.
        let mut examined = 0usize;
        let mut bi = 0usize;
        while bi < block.len() {
            let jv = block[bi][jk];
            examined += 1;
            if anchor.hash.contains(&jv) {
                return (true, examined);
            }
            bi += block[bi..].partition_point(|r| r[jk] <= jv).max(1);
        }
        (false, examined)
    } else {
        // Walk the shorter sorted anchor; binary-search each member into the block.
        let mut examined = 0usize;
        let mut lo = 0usize; // block window shrinks monotonically (both sorted ascending)
        for &av in &anchor.sorted {
            examined += 1;
            let rel = block[lo..].partition_point(|r| r[jk] < av);
            let at = lo + rel;
            if at < block.len() && block[at][jk] == av {
                return (true, examined);
            }
            lo = at;
            if lo >= block.len() {
                break;
            }
        }
        (false, examined)
    }
}

/// Enumerates the DISTINCT ids at canonical position `target_pos` via a loose/skip scan
/// over a permutation sorted by that column (galloping past each value's block with a
/// binary search rather than touching every row). Returns `(values, rows_touched)`, or
/// `None` when no built permutation sorts the matching range by `target_pos` (conservative
/// decline).
fn skipscan_distinct(graph: &Graph, id_pat: &IdPattern, target_pos: usize) -> Option<(Vec<Id>, usize)> {
    let scan = graph.store.scan_sorted(id_pat, target_pos);
    let order = scan.perm.order();
    // The range's rows are sorted by `target_pos` only when it is the FIRST unbound
    // column of the chosen permutation's order.
    if order.into_iter().find(|&c| id_pat[c].is_none()) != Some(target_pos) {
        return None;
    }
    let k = order.iter().position(|&c| c == target_pos)?;
    let rows = scan.rows.as_ref();
    let mut out: Vec<Id> = Vec::new();
    let mut scanned = 0usize;
    let mut i = 0usize;
    while i < rows.len() {
        if budget::exhausted(out.len()) {
            return None;
        }
        let v = rows[i][k];
        out.push(v);
        scanned += 1;
        // Gallop to the end of this value's contiguous block (all rows[i..] have
        // `col >= v`, so `col <= v` is exactly the v-block).
        let block_len = rows[i..].partition_point(|r| r[k] <= v).max(1);
        i += block_len;
    }
    Some((out, scanned))
}

/// Returns `true` when the same query variable occupies more than one of the subject,
/// predicate, or object slots in `tp` (e.g. `?x ?p ?x`). The fallback path enforces
/// positional equality for repeated variables via `build_row`; the skip-scan helpers do
/// not, so we must decline to push down any branch that contains such a pattern.
/// [SONNET-4.6]
fn has_intra_triple_repeated_var(tp: &TriplePattern) -> bool {
    let sv = if let TermPattern::Variable(v) = &tp.subject {
        Some(v)
    } else {
        None
    };
    let pv = if let NamedNodePattern::Variable(v) = &tp.predicate {
        Some(v)
    } else {
        None
    };
    let ov = if let TermPattern::Variable(v) = &tp.object {
        Some(v)
    } else {
        None
    };
    (sv.is_some() && pv.is_some() && sv == pv)
        || (sv.is_some() && ov.is_some() && sv == ov)
        || (pv.is_some() && ov.is_some() && pv == ov)
}

/// Returns `true` when `tp` carries a nested RDF 1.2 quoted-triple term (`<<s p o>>` /
/// `<<( s p o )>>`) in its subject or object slot. Such a term, when it embeds a variable, is
/// decomposed by the general BGP planner before pattern preparation; the DISTINCT skip-scan
/// path prepares the raw pattern, so `prepare_pattern` would ERROR on the embedded variable
/// instead of declining. The pushdown must decline any branch containing one (the predicate
/// slot is a `NamedNodePattern`, which cannot be a triple term, so only S/O are checked).
/// [OPUS-4.8] (sq-7d3dj.30.4)
fn has_quoted_triple_term(tp: &TriplePattern) -> bool {
    matches!(tp.subject, TermPattern::Triple(_)) || matches!(tp.object, TermPattern::Triple(_))
}

/// The DISTINCT projected-variable ids contributed by one UNION branch, together with the
/// permutation rows the skip scan touched. Returns only values NOT already in `seen`
/// (they are added there by the caller). `None` = shape the pushdown cannot enumerate.
fn branch_distinct_values(
    graph: &Graph,
    branch: &GraphPattern,
    pvar: &Variable,
    seen: &FxHashSet<Id>,
    anchor_cache: &mut AnchorCache,
    #[cfg(feature = "cs-anchor-incidence")] incidence_cache: &mut IncidenceCache,
) -> Result<Option<(Vec<Id>, usize)>, String> {
    if !is_conjunctive(branch) {
        return Ok(None);
    }
    let mut patterns: Vec<TriplePattern> = Vec::new();
    let mut filters: Vec<Expression> = Vec::new();
    flatten_conjunction(branch, &mut patterns, &mut filters);
    if !filters.is_empty() {
        return Ok(None);
    }
    // [SONNET-4.6] Decline when any pattern has a variable repeated across S/P/O positions
    // (e.g. `?x ?p ?x`). The fallback enforces positional equality via build_row; without
    // this guard the skip scan would over-approximate (include predicates that have no
    // self-loop triple). Counterexample: data {ex:a ex:knows ex:a. ex:b ex:likes ex:c.},
    // query SELECT DISTINCT ?p WHERE { ?x ?p ?x } — correct={ex:knows}, pushdown
    // (unguarded)={ex:knows, ex:likes}.
    if patterns.iter().any(has_intra_triple_repeated_var) {
        return Ok(None);
    }
    // [OPUS-4.8] (sq-7d3dj.30.4) Decline when any pattern embeds an RDF 1.2 quoted-triple
    // term (e.g. `<<?s ?p "o">> ?p2 ?z`) in a subject/object slot. A quoted term that
    // carries a variable is decomposed by the general BGP planner (`extract_quoted_constraints`
    // -> `quoted_relation`) BEFORE pattern preparation runs; the skip-scan path prepares the
    // raw pattern, so `prepare_pattern` would try to resolve the whole quoted term to one
    // ground id and ERROR ("variable where a term was expected") rather than fall back. We
    // must always DECLINE (never error) so the general path produces the equivalent answer
    // (W3C sparql12 eval-triple-terms/pattern-10). See `has_quoted_triple_term`.
    if patterns.iter().any(has_quoted_triple_term) {
        return Ok(None);
    }
    match patterns.len() {
        1 => single_pattern_distinct(graph, &patterns[0], pvar, seen),
        2 => two_pattern_distinct(
            graph,
            &patterns,
            pvar,
            seen,
            anchor_cache,
            #[cfg(feature = "cs-anchor-incidence")]
            incidence_cache,
        ),
        _ => Ok(None),
    }
}

/// Single-pattern branch: every distinct `?p` value in the pattern's range is a solution,
/// so enumerate them directly via the skip scan.
fn single_pattern_distinct(
    graph: &Graph,
    tp: &TriplePattern,
    pvar: &Variable,
    seen: &FxHashSet<Id>,
) -> Result<Option<(Vec<Id>, usize)>, String> {
    let (id_pat, pos_vars, unsat) = prepare_pattern(graph, tp)?;
    if unsat {
        return Ok(Some((Vec::new(), 0)));
    }
    let ppos = match var_positions_of(&pos_vars, pvar).as_slice() {
        [p] => *p,
        _ => return Ok(None),
    };
    let (vals, scanned) = match skipscan_distinct(graph, &id_pat, ppos) {
        Some(x) => x,
        None => return Ok(None),
    };
    let new: Vec<Id> = vals.into_iter().filter(|v| !seen.contains(v)).collect();
    Ok(Some((new, scanned)))
}

/// Two-pattern (anchor + probe) branch joined on a single variable: `?p` lives in exactly
/// one pattern (the probe); the other (the anchor) constrains the join variable. Enumerate
/// distinct `?p` from the probe and keep only those whose probe row set intersects the
/// anchor's join-variable set (a loose semi-join existence check).
fn two_pattern_distinct(
    graph: &Graph,
    patterns: &[TriplePattern],
    pvar: &Variable,
    seen: &FxHashSet<Id>,
    anchor_cache: &mut AnchorCache,
    #[cfg(feature = "cs-anchor-incidence")] incidence_cache: &mut IncidenceCache,
) -> Result<Option<(Vec<Id>, usize)>, String> {
    let (idp0, pv0, uns0) = prepare_pattern(graph, &patterns[0])?;
    let (idp1, pv1, uns1) = prepare_pattern(graph, &patterns[1])?;
    let in0 = var_positions_of(&pv0, pvar);
    let in1 = var_positions_of(&pv1, pvar);
    // `?p` must appear EXACTLY ONCE, in exactly one of the two patterns (that is the probe).
    match (in0.as_slice(), in1.as_slice()) {
        ([ppos], []) => probe_anchor_distinct(
            graph,
            (&idp0, &pv0, uns0),
            (&idp1, &pv1, uns1),
            *ppos,
            seen,
            anchor_cache,
            #[cfg(feature = "cs-anchor-incidence")]
            incidence_cache,
        ),
        ([], [ppos]) => probe_anchor_distinct(
            graph,
            (&idp1, &pv1, uns1),
            (&idp0, &pv0, uns0),
            *ppos,
            seen,
            anchor_cache,
            #[cfg(feature = "cs-anchor-incidence")]
            incidence_cache,
        ),
        _ => Ok(None),
    }
}

/// Prepared-pattern triple `(id_pat, pos_vars, unsat)` passed by reference.
type PreparedRef<'a> = (&'a IdPattern, &'a [Option<Variable>; 3], bool);

/// [FABLE-5] (sq-7d3dj.30.10) The anchor membership set, in BOTH forms needed by the
/// per-predicate existence probe: a `hash` set for O(1) membership, and the same ids
/// `sorted` ascending so a large block can be clipped to the anchor's id window and the
/// smaller side can drive a galloping intersection.
struct AnchorSet {
    hash: FxHashSet<Id>,
    sorted: Vec<Id>,
}

/// [FABLE-5] (sq-7d3dj.30.10) Per-pushdown cache of anchor membership sets, keyed by the
/// anchor's prepared id-pattern plus its join position (which together fully determine the
/// set). Shared across a DISTINCT pushdown's UNION branches so a repeated anchor
/// (e.g. SP2Bench q09's shared `?person rdf:type foaf:Person`) is materialised once.
type AnchorCache = FxHashMap<(IdPattern, usize), std::rc::Rc<AnchorSet>>;

/// The anchor membership set for `(anchor_ip, anchor_jpos)`, memoised in `cache`. Returns
/// `None` under budget pressure (the pushdown then declines). The set is wrapped in `Rc`
/// so a cache hit is a cheap clone, not a re-materialisation.
fn cached_anchor_ids(
    graph: &Graph,
    anchor_ip: &IdPattern,
    anchor_jpos: usize,
    cache: &mut AnchorCache,
) -> Option<std::rc::Rc<AnchorSet>> {
    let key = (*anchor_ip, anchor_jpos);
    if let Some(v) = cache.get(&key) {
        return Some(v.clone());
    }
    let sorted = collect_var_ids_sorted(graph, anchor_ip, anchor_jpos)?;
    let hash: FxHashSet<Id> = sorted.iter().copied().collect();
    let set = std::rc::Rc::new(AnchorSet { hash, sorted });
    cache.insert(key, set.clone());
    Some(set)
}

/// [FABLE-5] (sq-jnb1e) Per-pushdown cache of anchor PREDICATE-INCIDENCE sets, keyed by the
/// anchor membership set (identified by the anchor's prepared id-pattern + join position) and
/// the probe's canonical JOIN position (0=subject, 2=object; a predicate never joins). The
/// value is `Some(set)` where `set` is exactly the predicates that relate SOME anchor member
/// at that position, or `None` when the set could not be computed (budget / overlay / no built
/// permutation) — cached so the two q09 branches never recompute the same incidence.
#[cfg(feature = "cs-anchor-incidence")]
type IncidenceCache = FxHashMap<(IdPattern, usize, usize), Option<std::rc::Rc<FxHashSet<Id>>>>;

/// [FABLE-5] (sq-jnb1e) The set of predicates that relate ANY anchor member at the probe's
/// canonical join position `probe_jpos` (0=subject or 2=object) — a characteristic-set-style
/// incidence summary. Computed by ONE range-restricted scan over the anchor's id window: the
/// permutation sorted by `probe_jpos` groups triples by that column, so restricting to
/// `[a_min, a_max]` (every anchor member lies in that window) and, for each row whose join
/// value is an actual anchor member, recording its predicate, yields exactly
/// `{ predicate(t) : t is a triple with t[probe_jpos] ∈ anchor }`.
///
/// SOUNDNESS. This set is EXACT on the base index: a predicate P is in it iff some triple uses
/// P with an anchor member at `probe_jpos`, i.e. iff the (anchor ⋈ probe-on-P) branch is
/// non-empty. So `P ∉ set` ⇒ that branch contributes no solution ⇒ P can be pruned WITHOUT
/// scanning P's block, and `P ∈ set` still takes the exact per-block scan. Pruning only
/// provably-empty checks makes the DISTINCT answer identical to the block-scan path.
///
/// Returns `None` (caller keeps the exact block scan for every P) when:
/// * the graph carries a pending-update overlay — the derived set is built against the base
///   index only, and incremental maintenance is out of scope, so we DECLINE conservatively
///   rather than risk a stale prune;
/// * `probe_jpos` is the predicate slot (1) — a predicate never joins to the anchor here;
/// * no permutation sorted by `probe_jpos` is built (e.g. the compact wasm index);
/// * the scan exceeds the query budget.
#[cfg(feature = "cs-anchor-incidence")]
fn anchor_probe_incidence(
    graph: &Graph,
    anchor: &AnchorSet,
    probe_jpos: usize,
) -> Option<FxHashSet<Id>> {
    // Conservative invalidation: a delta-overlay means the base-index incidence may be stale
    // (an inserted triple could add a predicate; a deleted one could remove the last member
    // relation). We do not maintain the set incrementally, so decline and let the exact scan
    // (which reads the overlay-merged rows) answer every candidate.
    if graph.store.has_overlay() {
        return None;
    }
    if probe_jpos == 1 || anchor.sorted.is_empty() {
        return None;
    }
    let (a_min, a_max) = (anchor.sorted[0], anchor.sorted[anchor.sorted.len() - 1]);
    // A permutation whose FIRST column is `probe_jpos` so the anchor id window is one
    // contiguous range and the predicate sits at a fixed column. Bind nothing; sort by the
    // join column. `scan_sorted` picks such a perm when built; if the chosen perm is not
    // actually led by `probe_jpos`, we cannot range-restrict soundly — decline.
    let all_unbound: IdPattern = [None, None, None];
    let scan = graph.store.scan_sorted(&all_unbound, probe_jpos);
    let order = scan.perm.order();
    if order[0] != probe_jpos {
        return None;
    }
    // Predicate lives at whichever column of this perm is canonical position 1.
    let pk = order.iter().position(|&c| c == 1)?;
    let jk = 0usize; // join column is the leading column (== probe_jpos)
    let rows = scan.rows.as_ref();
    // Restrict to the anchor id window `[a_min, a_max]` with two binary searches: rows outside
    // it can never carry an anchor member at the join column, so they cannot contribute a
    // predicate to the incidence set.
    let lo = rows.partition_point(|r| r[jk] < a_min);
    let hi = rows.partition_point(|r| r[jk] <= a_max);
    let window = &rows[lo..hi];
    let mut inc: FxHashSet<Id> = FxHashSet::default();
    for (n, r) in window.iter().enumerate() {
        if n & 4095 == 0 && budget::exhausted(inc.len()) {
            return None;
        }
        // Only rows whose join value is an ACTUAL anchor member contribute (the window can
        // include non-member ids that merely fall inside `[a_min, a_max]`).
        if anchor.hash.contains(&r[jk]) {
            inc.insert(r[pk]);
        }
    }
    Some(inc)
}

/// [FABLE-5] (sq-jnb1e) The predicate-incidence set for `(anchor, probe_jpos)`, memoised in
/// `cache`. Keyed by the anchor identity (`anchor_ip` + `anchor_jpos`) and the probe join
/// position, so q09's two branches share one computation per position. The cached value is an
/// `Option` (a computed-and-failed decline is cached too, so a second branch on the same
/// position does not retry a scan that already declined).
#[cfg(feature = "cs-anchor-incidence")]
fn cached_incidence(
    graph: &Graph,
    anchor_ip: &IdPattern,
    anchor_jpos: usize,
    anchor: &AnchorSet,
    probe_jpos: usize,
    cache: &mut IncidenceCache,
) -> Option<std::rc::Rc<FxHashSet<Id>>> {
    let key = (*anchor_ip, anchor_jpos, probe_jpos);
    if let Some(v) = cache.get(&key) {
        return v.clone();
    }
    let computed = anchor_probe_incidence(graph, anchor, probe_jpos).map(std::rc::Rc::new);
    cache.insert(key, computed.clone());
    computed
}

/// [FABLE-5] (sq-7d3dj.30.10) The "pattern-trick" strategy for the loose semi-join: iterate
/// the ANCHOR members and, for each member `m`, enumerate the distinct `?p` (at `ppos`) on
/// probe triples whose join column (`jpos`) equals `m` — accumulating a running result set
/// that terminates the instant it covers the whole `?p` UNIVERSE (the distinct `?p` in the
/// probe's range ignoring the join, a superset the answer can never exceed). Returns the new
/// `?p` values (those not already in `seen`) plus a diagnostic touched-row count, or `None`
/// to DECLINE — in which case the caller falls back to the per-`?p`-block existence scan.
///
/// Correctness: the union over all anchor members `m` of `{ ?p : ∃ probe triple with
/// jpos=m }` is EXACTLY `{ ?p : ∃ a solution of the (anchor ⋈ probe) branch }` — binding the
/// join column to each anchor member and taking the union is the definition of the semi-join
/// projected onto `?p`. The universe early-exit is sound because the collected set is
/// monotonically growing and bounded above by the universe, so once they are equal no further
/// member can add a value. Declines when the required per-member permutation is not built or
/// when a per-member scan cannot skip-enumerate `?p` (so the general block scan answers it).
fn maybe_anchor_driven(
    graph: &Graph,
    probe_ip: &IdPattern,
    ppos: usize,
    jpos: usize,
    anchor: &AnchorSet,
    seen: &FxHashSet<Id>,
) -> Result<Option<(Vec<Id>, usize)>, String> {
    // COST GATE: the per-member scan touches only the anchor's incident probe triples, so it
    // is a clear win when the anchor is SMALL — then we sweep a handful of members instead of
    // every candidate `?p`-block. For a LARGE anchor (q09's 20,602 persons) the per-member
    // machinery dominates, so we decline here and let the caller's cost-aware block scan run.
    // The threshold is a strategy choice only — either path returns the identical `?p` set.
    if anchor.sorted.len() > ANCHOR_DRIVEN_MAX {
        return Ok(None);
    }
    anchor_driven_distinct(graph, probe_ip, ppos, jpos, anchor, seen)
}

/// The largest anchor cardinality for which the per-member ("pattern trick") enumeration is
/// preferred over the per-`?p`-block existence scan. Above it, sweeping every anchor member
/// costs more than the block scan (measured: SP2Bench q09's 20k-person anchor is faster on
/// the block scan). A strategy threshold only — never affects the computed answer.
const ANCHOR_DRIVEN_MAX: usize = 256;

/// Per-member ("pattern trick") enumeration: for each anchor member `m`, bind the join column
/// to `m` and skip-enumerate the distinct `?p`, unioning across members and stopping once the
/// `?p` universe is covered. Declines (→ block-scan fallback) when a per-member scan cannot
/// skip-enumerate `?p` for the bound join position.
fn anchor_driven_distinct(
    graph: &Graph,
    probe_ip: &IdPattern,
    ppos: usize,
    jpos: usize,
    anchor: &AnchorSet,
    seen: &FxHashSet<Id>,
) -> Result<Option<(Vec<Id>, usize)>, String> {
    // The `?p` universe (distinct `?p` in the probe range, ignoring the join) — a cheap
    // superset the answer can never exceed, so once we have collected it we can stop reading.
    let (universe_vals, _) = match skipscan_distinct(graph, probe_ip, ppos) {
        Some(x) => x,
        None => return Ok(None),
    };
    let universe_len = universe_vals.len();
    if universe_len == 0 {
        return Ok(Some((Vec::new(), 0)));
    }
    let mut found: FxHashSet<Id> = FxHashSet::default();
    let mut out: Vec<Id> = Vec::new();
    let mut scanned = 0usize;
    for (idx, &m) in anchor.sorted.iter().enumerate() {
        if idx & 63 == 0 && budget::exhausted(out.len()) {
            return Ok(None);
        }
        // Bind the join column to this anchor member; keep the probe's other positions.
        let mut member_pat = *probe_ip;
        member_pat[jpos] = Some(m);
        let (vals, s) = match skipscan_distinct(graph, &member_pat, ppos) {
            Some(x) => x,
            None => return Ok(None),
        };
        scanned = scanned.saturating_add(s);
        for v in vals {
            if found.insert(v) {
                if !seen.contains(&v) {
                    out.push(v);
                }
                // Whole `?p` universe covered → no later member can add anything. Stop.
                if found.len() == universe_len {
                    return Ok(Some((out, scanned)));
                }
            }
        }
    }
    Ok(Some((out, scanned)))
}

/// The loose semi-join for `{ anchor, probe }`: `probe` binds `?p` (at `ppos`) and the
/// join variable; `anchor` constrains the join variable. Enumerates distinct `?p` from a
/// permutation ordered `[.., P, J, ..]` (so each `?p`-block is sorted by the join variable)
/// and keeps a `?p` iff its block contains a join-variable id present in the anchor set.
fn probe_anchor_distinct(
    graph: &Graph,
    probe: PreparedRef<'_>,
    anchor: PreparedRef<'_>,
    ppos: usize,
    seen: &FxHashSet<Id>,
    anchor_cache: &mut AnchorCache,
    #[cfg(feature = "cs-anchor-incidence")] incidence_cache: &mut IncidenceCache,
) -> Result<Option<(Vec<Id>, usize)>, String> {
    let (probe_ip, probe_pv, probe_uns) = probe;
    let (anchor_ip, anchor_pv, anchor_uns) = anchor;
    if probe_uns || anchor_uns {
        return Ok(Some((Vec::new(), 0)));
    }
    // Exactly one shared (join) variable, which must not be the projected variable.
    let jvar = match single_shared_var(probe_pv, anchor_pv) {
        Some(v) => v,
        None => return Ok(None),
    };
    let jpos = match var_positions_of(probe_pv, jvar).as_slice() {
        [p] => *p,
        _ => return Ok(None),
    };
    let anchor_jpos = match var_positions_of(anchor_pv, jvar).first() {
        Some(&p) => p,
        None => return Ok(None),
    };
    if jpos == ppos {
        return Ok(None);
    }
    // The anchor's join-variable membership set (hash + sorted), shared across the
    // pushdown's UNION branches (SP2Bench q09's two branches share the same anchor).
    let a = match cached_anchor_ids(graph, anchor_ip, anchor_jpos, anchor_cache) {
        Some(s) => s,
        None => return Ok(None),
    };
    if a.sorted.is_empty() {
        // Empty anchor → the join is empty → no `?p` qualifies.
        return Ok(Some((Vec::new(), 0)));
    }
    // [FABLE-5] (sq-7d3dj.30.10) ANCHOR-DRIVEN predicate enumeration (the "pattern trick"):
    // walk the probe range grouped by join value and only descend into the ANCHOR blocks'
    // `?p` values, terminating once the `?p` universe is covered. This wins when the join
    // axis is LOW-cardinality (few distinct join values → few blocks to skip): a bound anchor
    // member set is then cheaper to sweep than the candidate `?p`-blocks. It is NOT a
    // universal win — when the distinct join values are as numerous as the `?p`-blocks
    // (SP2Bench q09: ~tens of thousands of distinct subjects/objects) walking every join
    // block costs as much as the block existence scan — so we gate it on the join axis being
    // low-cardinality relative to the `?p` universe, else fall through to the (cost-aware,
    // clipped) block scan below. Both paths return the identical `?p` set.
    if let Some((new, scanned)) = maybe_anchor_driven(graph, probe_ip, ppos, jpos, &a, seen)? {
        return Ok(Some((new, scanned)));
    }
    // We need a permutation ordered `[.., P, J, third]` so a `?p`-block is sorted by the
    // join variable (bounding the per-block existence scan). `scan_sorted(ppos)` only
    // pins the FIRST unbound column, so choose the exact permutation ourselves.
    let third = 3 - ppos - jpos;
    let want = perm_for_order([ppos, jpos, third]).ok_or("no such permutation")?;
    let scan = match graph.store.scan_perm(probe_ip, want) {
        Some(s) => s,
        // Permutation not built (e.g. the compact wasm index) or the pattern's bound
        // positions are not a prefix in it → decline (fall back to the full path).
        None => return Ok(None),
    };
    // `want.order() == [ppos, jpos, third]`, so P is column 0 and J is column 1, but only
    // when every bound position precedes them; `scan_perm` guarantees the bound prefix, and
    // both P and J are variables here, so this holds.
    let (kp, jk) = (0usize, 1usize);
    debug_assert_eq!(scan.perm.order()[kp], ppos);
    debug_assert_eq!(scan.perm.order()[jk], jpos);
    let rows = scan.rows.as_ref();
    // [FABLE-5] (sq-jnb1e) OPT-IN characteristic-set anchor-incidence prune. When the probe
    // pattern constrains ONLY the projected predicate and the join variable (every other
    // position free — the q09 shape `?subject ?predicate ?person` / `?person ?predicate
    // ?object`), a candidate predicate `pv_id` qualifies iff it relates SOME anchor member at
    // the join position — exactly the precomputed incidence set. A `pv_id` NOT in that set is
    // pruned by an O(1) membership test instead of the clip+gallop block scan. The prune is
    // sound ONLY when the probe has no OTHER bound position (else a predicate could relate an
    // anchor member on a DIFFERENT triple than the one satisfying the bound constraint); we
    // decline the incidence set otherwise and every candidate takes the exact scan.
    #[cfg(feature = "cs-anchor-incidence")]
    let incidence: Option<std::rc::Rc<FxHashSet<Id>>> = {
        // "Bound only P and J" ⇔ the probe id-pattern binds no position (both P and J are
        // variables, so a bound slot would be the third position).
        let probe_only_pj = probe_ip.iter().all(|s| s.is_none());
        if anchor_incidence::enabled() && probe_only_pj {
            let inc = cached_incidence(graph, anchor_ip, anchor_jpos, &a, jpos, incidence_cache);
            if inc.is_some() {
                anchor_incidence::note_built();
            }
            inc
        } else {
            None
        }
    };
    let mut out: Vec<Id> = Vec::new();
    let mut scanned = 0usize;
    let mut i = 0usize;
    // `a.sorted` is non-empty (checked above) and sorted, so min/max are its ends.
    let (a_min, a_max) = (a.sorted[0], a.sorted[a.sorted.len() - 1]);
    while i < rows.len() {
        if budget::exhausted(out.len()) {
            return Ok(None);
        }
        let pv_id = rows[i][kp];
        let block_len = rows[i..].partition_point(|r| r[kp] <= pv_id).max(1);
        let block = &rows[i..i + block_len];
        i += block_len;
        // Already emitted by an earlier branch — no re-check needed.
        if seen.contains(&pv_id) {
            continue;
        }
        // [FABLE-5] (sq-jnb1e) Incidence prune: when the precomputed set is available and does
        // NOT contain this predicate, the (anchor ⋈ probe-on-`pv_id`) branch is provably empty
        // — skip the whole block WITHOUT the clip+gallop scan (one metadata consultation counts
        // as one unit of examination). A `pv_id` IN the set falls through to the exact block
        // scan below, so the emitted answer is bit-for-bit identical to the feature-off path.
        #[cfg(feature = "cs-anchor-incidence")]
        if let Some(inc) = incidence.as_ref() {
            if !inc.contains(&pv_id) {
                scanned += 1;
                anchor_incidence::note_pruned(1);
                continue;
            }
        }
        // The block is join-variable-sorted, so its join range is [first, last]. When that
        // range is DISJOINT from the anchor set's id range, no anchor member can occur in
        // it — reject the whole `?p` in O(1) (the common loose-scan win for value-typed
        // predicates whose objects never overlap the entity id range).
        let (bmin, bmax) = (block[0][jk], block[block.len() - 1][jk]);
        scanned += 1;
        if bmax < a_min || bmin > a_max {
            continue;
        }
        // [FABLE-5] (sq-7d3dj.30.10) CLIP the join-sorted block to the anchor's id window
        // `[a_min, a_max]` with two binary searches: every anchor member lies in that
        // window, so no join value OUTSIDE it can be a hit — dropping them cannot change
        // the answer. When the anchor entities occupy a narrow id band this discards the
        // bulk of a large no-hit block in O(log n); when they do not it is two cheap
        // binary searches and the full gallop below still runs.
        let cs = block.partition_point(|r| r[jk] < a_min);
        let ce = block.partition_point(|r| r[jk] <= a_max);
        let clipped = &block[cs..ce];
        // Existence: does any join value in the clipped block belong to the anchor set?
        // Drive from whichever side is shorter: gallop the clipped block's distinct values
        // with an O(1) hash probe when the block (post-clip) is the shorter side; otherwise
        // walk the sorted anchor and binary-search each member into the block. Early-exit
        // on the first common id. [FABLE-5] (sq-7d3dj.30.10)
        let (hit, examined) = block_intersects_anchor(clipped, jk, &a);
        scanned += examined;
        if hit {
            out.push(pv_id);
        }
    }
    Ok(Some((out, scanned)))
}

/// Evaluates a pattern with an early-termination row cap, when that is safe. The
/// contract every arm preserves (and the `Slice` caller relies on): the returned
/// rows are a sub-multiset of the full result, and a return of FEWER than `cap`
/// rows is the COMPLETE result. Under that contract a caller that observes only
/// `min(cap, ·)` rows (LIMIT) or emptiness (ASK evaluates as `LIMIT 1`) gets the
/// same answer as full evaluation — differentially asserted by
/// `tests/ask_early_exit.rs`. [FABLE-5] (sq-7d3dj.30.8)
///
/// Covered shapes: a single-pattern scan (optionally with a pushed-down sargable
/// numeric filter) under projection — the scan itself stops at `cap` rows; a
/// conjunctive multi-pattern BGP (+ FILTERs) — the block-driven join chain
/// (`eval_bgp_binary_capped`); UNION — left branch first, the right branch is not
/// evaluated when the left already satisfies the cap; OPTIONAL — capping the LEFT
/// side caps the output, since no left row is ever dropped; Join — a capped-left
/// probe joined through the SIP correlated path, declining when the probe misses;
/// BIND — row-count preserving. Everything else returns `None` and the caller falls
/// back to full evaluation — in particular DISTINCT / ORDER BY / aggregation need
/// the full result, and a bare FILTER over a non-conjunctive inner cannot count
/// capped rows soundly (a row may only count once it has passed every filter).
fn try_capped(
    graph: &Graph,
    local: &mut LocalVocab,
    inner: &GraphPattern,
    cap: usize,
) -> Result<Option<Bindings>, String> {
    // zk-trace: early termination would consume only part of each scan range,
    // recording a TRUNCATED input set — but the completeness witness (the
    // linear-sweep circuit) must see the whole scan range. Disable the cap
    // while recording; the full path is result-equivalent (LIMIT is
    // order-insensitive without ORDER BY).
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        return Ok(None);
    }
    if view::default_is_empty() {
        return Ok(None); // empty-default view: the general path short-circuits at the BGP
    }
    match inner {
        GraphPattern::Project { inner, variables } => {
            Ok(try_capped(graph, local, inner, cap)?.map(|b| project_bindings(b, variables)))
        }
        GraphPattern::Reduced { inner } => try_capped(graph, local, inner, cap),
        p if is_conjunctive(p) => {
            let mut patterns = Vec::new();
            let mut filters = Vec::new();
            flatten_conjunction(p, &mut patterns, &mut filters);
            if patterns.is_empty() {
                return Ok(None); // the unit relation: nothing to cap
            }
            if patterns.len() == 1 {
                let (pat_filters, residual) = split_sargable(graph, &patterns, &filters);
                if residual.is_empty() {
                    // Single pattern, every FILTER pushed into the scan: stop the
                    // SCAN itself at `cap` rows (the cheapest capped form).
                    let (id_pat, pos_vars, unsat) = prepare_pattern(graph, &patterns[0])?;
                    if unsat {
                        return Ok(Some(Bindings::unsorted(collect_vars(&patterns), vec![])));
                    }
                    let filt = pat_filters[0];
                    let sort_col = filt.map(|(c, _)| c);
                    return Ok(Some(scan_to_bindings(
                        graph,
                        &id_pat,
                        &pos_vars,
                        sort_col,
                        filt,
                        Some(cap),
                        #[cfg(feature = "semijoin-bitmap")]
                        None,
                    )));
                }
            }
            // Multi-pattern (or residual-FILTER) conjunctive shape: the block-driven
            // capped join chain.
            eval_bgp_binary_capped(graph, local, &patterns, &filters, cap)
        }
        GraphPattern::Union { left, right } => {
            // Left branch first; the right branch is only touched when the left did
            // not already satisfy the cap (the ASK short-circuit: a non-empty left
            // branch answers the query alone).
            let l = match try_capped(graph, local, left, cap)? {
                Some(b) => b,
                None => eval_graph_pattern(graph, local, left)?,
            };
            if l.rows.len() >= cap {
                // The rows are genuine union solutions (right-only variables are
                // unbound); align the header with the un-evaluated right branch's
                // in-scope variables, exactly as `union_bindings` would have.
                return Ok(Some(union_bindings(l, Bindings::unsorted(in_scope_vars(right), vec![]))));
            }
            // Fewer than `cap` rows ⇒ `l` is the COMPLETE left result (the
            // contract): the union needs only `cap - |l|` further rows.
            let r = match try_capped(graph, local, right, cap - l.rows.len())? {
                Some(b) => b,
                None => eval_graph_pattern(graph, local, right)?,
            };
            Ok(Some(union_bindings(l, r)))
        }
        GraphPattern::Join { left, right } => {
            let l = match try_capped(graph, local, left, cap)? {
                Some(b) => b,
                None => return Ok(None),
            };
            // Fewer than `cap` rows ⇒ the COMPLETE left result (the contract); the
            // join below is then the full join. Otherwise `l` is a first-rows PROBE.
            let l_complete = l.rows.len() < cap;
            if l.rows.is_empty() {
                // Empty complete left: the full join is empty.
                return Ok(Some(union_bindings(l, Bindings::unsorted(in_scope_vars(right), vec![]))));
            }
            // Correlated (SIP) evaluation of the right child seeded from the capped
            // left — the same machinery as the full Join arm (sq-7d3dj.30.3). Joins
            // are per-left-row local, so the joined rows are exactly the full join's
            // rows originating from `l`'s rows.
            let joined = match try_sip_join(graph, local, &l, right)? {
                Some(j) => j,
                None => {
                    let r = eval_graph_pattern(graph, local, right)?;
                    join_bindings(l, r)
                }
            };
            if l_complete || joined.rows.len() >= cap {
                return Ok(Some(joined));
            }
            // The capped-left probe joined to fewer than `cap` rows, but more left
            // rows might join: decline, the caller runs the full path.
            Ok(None)
        }
        GraphPattern::LeftJoin { left, right, expression } => {
            // OPTIONAL never drops a left row (each yields >= 1 output row, joined
            // or kept with the right unbound), so capping the LEFT side caps the
            // output. The right side is still evaluated in full so every emitted row
            // is a genuine LeftJoin solution (v1 boundary: no correlated OPTIONAL).
            let l = match try_capped(graph, local, left, cap)? {
                Some(b) => b,
                None => return Ok(None),
            };
            let r = eval_graph_pattern(graph, local, right)?;
            Ok(Some(left_outer_join(graph, local, l, r, expression.as_ref())?))
        }
        GraphPattern::Extend { inner, variable, expression } => {
            // BIND is row-count preserving (an expression error leaves the variable
            // unbound, the row is kept), so extending a capped subset is sound.
            let b = match try_capped(graph, local, inner, cap)? {
                Some(b) => b,
                None => return Ok(None),
            };
            Ok(Some(extend_bindings(graph, local, b, variable, expression)?))
        }
        _ => Ok(None),
    }
}

/// The syntactic in-scope variables of a pattern (spargebra's authoritative
/// `on_in_scope_variable` set, first-occurrence order, deduplicated) — used by the
/// capped UNION / Join arms to shape a header whose right branch was never evaluated.
fn in_scope_vars(p: &GraphPattern) -> Vec<Variable> {
    let mut vars: Vec<Variable> = Vec::new();
    p.on_in_scope_variable(|v| {
        if !vars.contains(v) {
            vars.push(v.clone());
        }
    });
    vars
}

/// First seed block of the capped conjunctive chain: small enough that an ASK /
/// LIMIT-1 hit in the first block costs a fraction of the full join, large enough
/// to amortise the per-block chain setup.
const CAPPED_SEED_BLOCK: usize = 1024;
/// Second-tier block: one escalation before the remainder is processed whole, so a
/// first-block miss still avoids the full chain when a solution lives within the
/// first ~64k seed rows. Exactly two escalations bound the per-step rhs re-scan
/// overhead of a NO-solution (ASK false) query at 3x the single-pass scans.
const CAPPED_SEED_BLOCK_2: usize = 65_536;

/// Capped conjunctive (BGP + FILTER) evaluation — the ASK / LIMIT-k first-solutions
/// short-circuit THROUGH JOINS (sq-7d3dj.30.8). Runs the same greedy (GOO) binary
/// join chain as `eval_bgp_binary`, but drives it from at most three geometrically
/// growing SLICES of the seed scan (`CAPPED_SEED_BLOCK` rows, then up to
/// `CAPPED_SEED_BLOCK_2`, then the remainder), applying the residual FILTERs per
/// block and stopping as soon as `cap` fully-FILTERed rows exist.
///
/// SOUNDNESS. Every chain step is per-seed-row local — a join (bind / merge / hash /
/// cross) or a row-wise FILTER over a seed subset yields exactly the full result's
/// rows that originate from that subset — so the blocks are disjoint, their
/// concatenation over the whole seed IS the full result, and stopping early only
/// truncates it (the `try_capped` contract). A row counts toward `cap` only after
/// the WHOLE chain including every residual FILTER, so a first candidate eliminated
/// by a late FILTER never satisfies the cap. The join ORDER is re-derived per block
/// from the planner estimates (a block's size can change the bind-join admission),
/// which affects row order only — the contract is multiset-level and a BGP join is
/// order-independent.
///
/// Returns `None` (caller falls back to full evaluation) for the shapes the binary
/// chain does not cover: cyclic (WCOJ / LFTJ) BGPs and quoted-triple (RDF 1.2)
/// constraint decompositions.
fn eval_bgp_binary_capped(
    graph: &Graph,
    local: &mut LocalVocab,
    patterns: &[TriplePattern],
    filters: &[Expression],
    cap: usize,
) -> Result<Option<Bindings>, String> {
    if !bgp_uses_binary(patterns) {
        return Ok(None); // cyclic -> LFTJ: no capped variant (v1 boundary)
    }
    let (_, constraints) = extract_quoted_constraints(patterns);
    if !constraints.is_empty() {
        return Ok(None); // triple-term decomposition: keep the full path
    }
    let (pat_filters, residual) = split_sargable(graph, patterns, filters);
    let pfilter = |i: usize| -> Option<(usize, ScanCmp)> { pat_filters.get(i).copied().flatten() };
    let prepared = prepare_bgp(graph, patterns)?;
    if prepared.iter().any(|p| p.unsatisfiable) {
        return Ok(Some(Bindings::unsorted(collect_vars(patterns), vec![])));
    }
    if cap == 0 {
        // Zero rows requested: an empty partial answer is valid under the contract
        // (`|result| >= cap` — the caller's slice truncates to nothing either way).
        return Ok(Some(Bindings::unsorted(collect_vars(patterns), vec![])));
    }
    let seed = goo_seed(&prepared);
    let seed_sort_col = goo_seed_sort(&prepared, seed, pfilter(seed).map(|(c, _)| c));
    let seed_all = scan_to_bindings(
        graph,
        &prepared[seed].id_pat,
        &prepared[seed].pos_vars,
        seed_sort_col,
        pfilter(seed),
        None,
        #[cfg(feature = "semijoin-bitmap")]
        None,
    );

    let mut acc: Option<Bindings> = None;
    let mut start = 0usize;
    while start < seed_all.rows.len() {
        let end = if start == 0 {
            CAPPED_SEED_BLOCK.min(seed_all.rows.len())
        } else if start == CAPPED_SEED_BLOCK {
            CAPPED_SEED_BLOCK_2.min(seed_all.rows.len())
        } else {
            seed_all.rows.len()
        };
        // One seed slice through the whole chain. A contiguous slice of a sorted
        // scan stays sorted, so merge-join eligibility is preserved.
        let mut result = Bindings {
            vars: seed_all.vars.clone(),
            rows: seed_all.rows[start..end].to_vec(),
            sorted_by: seed_all.sorted_by.clone(),
        };
        let mut cs_ctx = CsCtx::new(&prepared);
        let mut done = vec![false; prepared.len()];
        done[seed] = true;
        cs_ctx.note_done(seed);
        let mut cur_card = prepared[seed].est as f64;
        let mut var_ndv: FxHashMap<Variable, f64> = FxHashMap::default();
        record_pattern_ndv(graph, &prepared, seed, cur_card, &mut var_ndv, &cs_ctx);
        for _ in 1..prepared.len() {
            let (i, new_card, _connected) = goo_pick(graph, &prepared, &done, &var_ndv, cur_card, &cs_ctx);
            cur_card = new_card;
            done[i] = true;
            cs_ctx.note_done(i);
            // Same step selection as `eval_bgp_binary`: bind-join when the running
            // block is much smaller than the pattern; else merge / hash / cross.
            let connecting: Vec<Variable> =
                result.vars.iter().filter(|v| prepared[i].var_pos(v).is_some()).cloned().collect();
            if connecting.len() == 1
                && distinct_pattern_vars(&prepared[i].pos_vars)
                && result.rows.len().saturating_mul(8) < prepared[i].est
            {
                let jv = &connecting[0];
                let rk = result.col(jv).unwrap();
                let pp = prepared[i].var_pos(jv).unwrap();
                result = bind_join(graph, result, &prepared[i].id_pat, &prepared[i].pos_vars, rk, pp, pfilter(i));
            } else {
                let filt = pfilter(i);
                let merge_var = result.sorted_by.clone().filter(|sv| prepared[i].var_pos(sv).is_some());
                let scan_sort = filt.map(|(c, _)| c).or_else(|| merge_var.as_ref().map(|jv| prepared[i].var_pos(jv).unwrap()));
                let rhs = scan_to_bindings(
                    graph,
                    &prepared[i].id_pat,
                    &prepared[i].pos_vars,
                    scan_sort,
                    filt,
                    None,
                    #[cfg(feature = "semijoin-bitmap")]
                    None,
                );
                let connected = prepared[i].pos_vars.iter().flatten().any(|v| result.vars.contains(v));
                if let Some(jv) = merge_var.filter(|jv| rhs.sorted_by.as_ref() == Some(jv)) {
                    result = merge_join(result, rhs, &jv);
                } else if connected {
                    result = hash_join(result, rhs);
                } else {
                    result = cross_product(result, rhs);
                }
            }
            record_pattern_ndv(graph, &prepared, i, cur_card, &mut var_ndv, &cs_ctx);
            if result.rows.is_empty() {
                break;
            }
        }
        // Residual FILTERs per block — a row only counts toward the cap once it has
        // passed EVERY filter (the late-FILTER safety property: a partial solution
        // never fires the early exit).
        // [FABLE-5] (sq-1ivw7) Install the snapshot-aware non-literal column set (indexing THIS
        // block's `result` layout — the BGP variables) so the id fast path fires on capped fused
        // BGP+FILTER shapes too. Drain-safe as in `eval_flat_conjunctive`.
        #[cfg(feature = "id-filter-fastpath")]
        let idfast_cols = {
            let bgp = GraphPattern::Bgp { patterns: patterns.to_vec() };
            nonliteral_filter_cols(graph, &bgp, &result)
        };
        for f in &residual {
            if result.rows.is_empty() {
                break;
            }
            #[cfg(feature = "id-filter-fastpath")]
            with_idfast_nonlit_cols(idfast_cols.clone(), || apply_filter(graph, local, &mut result, f))?;
            #[cfg(not(feature = "id-filter-fastpath"))]
            apply_filter(graph, local, &mut result, f)?;
        }
        let merged = match acc.take() {
            None => result,
            Some(a) => union_bindings(a, result),
        };
        budget::check(merged.rows.len())?;
        let satisfied = merged.rows.len() >= cap;
        acc = Some(merged);
        if satisfied {
            break;
        }
        start = end;
    }
    Ok(Some(acc.unwrap_or_else(|| Bindings::unsorted(collect_vars(patterns), vec![]))))
}

/// Distinct (non-repeated) variable positions of a prepared pattern, or `None` if
/// a variable repeats (e.g. `?x p ?x`), which would make range counts over-count.
pub(crate) fn distinct_pattern_vars(pos_vars: &[Option<Variable>; 3]) -> bool {
    let vars: Vec<&Variable> = pos_vars.iter().flatten().collect();
    let mut sorted = vars.clone();
    sorted.sort();
    sorted.dedup();
    sorted.len() == vars.len()
}

/// A lazy stream of `(value, group-size)` pairs ascending by value, for the group
/// column `v_pos` of a pattern — the streaming form of [`group_counts`]. When the chosen
/// permutation already delivers `v_pos` order (the 6-perm case) it run-length-groups
/// directly over the borrowed scan rows, materialising NOTHING; otherwise it collects +
/// sorts the column once (reduced-permutation fallback). Lets a multi-pattern star COUNT
/// be summed by k-way merge with O(k) memory instead of one group vector per pattern.
struct GroupStream<'a> {
    scan: sparq_core::store::Scan<'a>,
    /// The STORED column (into the permutation's row layout) holding the group value —
    /// precomputed so the hot loop reads `row[col]` directly instead of rebuilding the
    /// canonical triple per row.
    col: usize,
    i: usize,
    sorted_vals: Option<Vec<Id>>,
}

impl<'a> GroupStream<'a> {
    fn new(graph: &'a Graph, id_pat: &IdPattern, v_pos: usize) -> Self {
        let scan = graph.store.scan_sorted(id_pat, v_pos);
        let order = scan.perm.order();
        // Canonical column `v_pos` is stored at this position in the permutation's rows.
        let col = order.iter().position(|&c| c == v_pos).unwrap();
        let sorted = order.into_iter().find(|&c| id_pat[c].is_none()) == Some(v_pos);
        let sorted_vals = (!sorted).then(|| {
            let mut v: Vec<Id> = scan.rows.iter().map(|r| r[col]).collect();
            v.sort_unstable();
            v
        });
        GroupStream { scan, col, i: 0, sorted_vals }
    }

    /// The next `(value, run-length)` in ascending value order, or `None` at the end.
    fn next(&mut self) -> Option<(Id, usize)> {
        let (slice, col): (&[[Id; 3]], usize) = match &self.sorted_vals {
            // The fallback stores bare values in column 0 of a 1-wide logical view; reuse
            // the same run-length code by treating the Vec as the source.
            Some(vals) => {
                if self.i >= vals.len() {
                    return None;
                }
                let v = vals[self.i];
                let mut c = 0;
                while self.i < vals.len() && vals[self.i] == v {
                    self.i += 1;
                    c += 1;
                }
                return Some((v, c));
            }
            None => (&self.scan.rows, self.col),
        };
        if self.i >= slice.len() {
            return None;
        }
        let v = slice[self.i][col];
        let mut c = 0;
        while self.i < slice.len() && slice[self.i][col] == v {
            self.i += 1;
            c += 1;
        }
        Some((v, c))
    }
}

/// Counts the solutions of a single triple pattern constrained by sargable numeric
/// FILTER(s), WITHOUT materialising a row per solution. Returns `None` (fall back) if
/// any filter is not a sargable numeric comparison on a variable of the pattern.
fn count_single_filtered(
    graph: &Graph,
    id_pat: &IdPattern,
    pos_vars: &[Option<Variable>; 3],
    filters: &[Expression],
) -> Option<usize> {
    // Resolve every filter to (canonical position, comparison); all must be sargable.
    let mut cmps: Vec<(usize, ScanCmp)> = Vec::with_capacity(filters.len());
    for f in filters {
        let (var, cmp) = extract_sargable(graph, f)?;
        let pos = pos_vars.iter().position(|v| v.as_ref() == Some(&var))?;
        cmps.push((pos, cmp));
    }

    // Fast path: one filter on an all-inline column -> binary-searched range size
    // (the same value-sorted slice range-pruning uses, but we only need its length).
    // Requires the scan to be ACTUALLY sorted by the filter column (a reduced
    // permutation set may not deliver that order, in which case we fall through to the
    // count-scan below).
    if let [(fpos, cmp)] = cmps[..] {
        let scan = graph.store.scan_sorted(id_pat, fpos);
        let sorted_by_f = scan.perm.order().into_iter().find(|&c| id_pat[c].is_none()) == Some(fpos);
        if sorted_by_f && scan.rows.first().is_some_and(|r| dict::is_inline(scan.to_spo(r)[fpos])) {
            return Some(match inline_pass_values(cmp) {
                Some((lo, hi)) => {
                    let (lo_id, hi_id) = (dict::INLINE_BASE + lo, dict::INLINE_BASE + hi);
                    let start = scan.rows.partition_point(|r| scan.to_spo(r)[fpos] < lo_id);
                    let end = scan.rows.partition_point(|r| scan.to_spo(r)[fpos] <= hi_id);
                    end - start
                }
                None => 0,
            });
        }
    }

    // General: scan once, count rows passing ALL comparisons via the value caches.
    // No solution row is built. The single-comparison shapes are specialised so the
    // per-row test is a direct cache probe with no predicate-kind dispatch (this loop
    // is the COUNT-mode hot path for cached-numeric FILTERs).
    let scan = graph.store.scan(id_pat);
    let total = match cmps[..] {
        [(pos, ScanCmp::Num(cmp))] => scan
            .rows
            .iter()
            .filter(|row| graph.numeric_value(scan.to_spo(row)[pos]).is_some_and(|x| cmp.test(x)))
            .count(),
        [(pos, ScanCmp::Temp(op, t))] => scan
            .rows
            .iter()
            .filter(|row| {
                graph
                    .temporal_value(scan.to_spo(row)[pos])
                    .and_then(|v| Temporal::cmp_t(v, t))
                    .is_some_and(|o| op.eval(o))
            })
            .count(),
        _ => scan
            .rows
            .iter()
            .filter(|row| {
                let spo = scan.to_spo(row);
                cmps.iter().all(|(pos, cmp)| cmp.test_id(graph, spo[*pos]))
            })
            .count(),
    };
    Some(total)
}

/// Exact solution count of a filter-free conjunctive BGP without materialising the
/// result, for two shapes: a single pattern (index range size) and an N-pattern STAR
/// — every pattern sharing one common variable `v*`, with every other variable local
/// to a single pattern — counted as `Σ_v Π_i c_i(v)` over per-pattern group sizes,
/// streamed from the sorted indexes. Returns `None` (fall back to full evaluation)
/// for non-star shapes (e.g. 3+-pattern chains, where the product formula overcounts).
fn count_pushdown(graph: &Graph, inner: &GraphPattern) -> Option<usize> {
    if !is_conjunctive(inner) {
        return None;
    }
    let mut patterns = Vec::new();
    let mut filters = Vec::new();
    flatten_conjunction(inner, &mut patterns, &mut filters);

    if patterns.len() == 1 {
        let (id_pat, pos_vars, unsat) = prepare_pattern(graph, &patterns[0]).ok()?;
        if unsat {
            return Some(0);
        }
        if !distinct_pattern_vars(&pos_vars) {
            return None;
        }
        if filters.is_empty() {
            return Some(graph.store.estimate(&id_pat));
        }
        // Single pattern + sargable numeric FILTER(s): count the passing rows without
        // materialising — a binary-searched range size on an all-inline column, else a
        // count-scan (still no Row built per solution).
        return count_single_filtered(graph, &id_pat, &pos_vars, &filters);
    }

    // Multi-pattern star count is filter-free (a pushed filter changes the per-value
    // group counts; leave that to full evaluation).
    if !filters.is_empty() {
        return None;
    }

    // Prepare every pattern; each must have distinct in-pattern vars (no repeated var,
    // so a group-count per value is well defined).
    let mut prepared: Vec<(IdPattern, [Option<Variable>; 3])> = Vec::with_capacity(patterns.len());
    for p in &patterns {
        let (ip, pv, unsat) = prepare_pattern(graph, p).ok()?;
        if unsat {
            return Some(0);
        }
        if !distinct_pattern_vars(&pv) {
            return None;
        }
        prepared.push((ip, pv));
    }

    // Star test: find a variable in EVERY pattern; require every OTHER variable to
    // occur in exactly one pattern (so the only join is on the centre — otherwise the
    // product formula would overcount a second shared variable).
    let mut occ: FxHashMap<&Variable, usize> = FxHashMap::default();
    for (_, pv) in &prepared {
        for v in pv.iter().flatten() {
            *occ.entry(v).or_insert(0) += 1;
        }
    }
    let center = *occ.iter().find(|(_, &n)| n == prepared.len()).map(|(v, _)| v)?;
    if occ.iter().any(|(v, &n)| *v != center && n != 1) {
        return None;
    }

    // Σ_v Π_i c_i(v) over the centre value v, computed by k-way INTERSECTION MERGE of the
    // per-pattern group-count streams — only values present in EVERY pattern contribute.
    // O(k) memory: no per-pattern group vector is materialised (the dominant memory of a
    // star COUNT at scale), just one cursor per pattern.
    let mut streams: Vec<GroupStream> = Vec::with_capacity(prepared.len());
    for (ip, pv) in &prepared {
        let cpos = pv.iter().position(|v| v.as_ref() == Some(center))?;
        streams.push(GroupStream::new(graph, ip, cpos));
    }
    let mut heads: Vec<(Id, usize)> = Vec::with_capacity(streams.len());
    for s in &mut streams {
        match s.next() {
            Some(h) => heads.push(h),
            None => return Some(0), // a pattern with no rows → empty intersection.
        }
    }
    let mut total = 0usize;
    loop {
        let max_v = heads.iter().map(|(v, _)| *v).max().unwrap();
        // Advance every cursor up to `max_v`; track whether all reach exactly it.
        let mut all_equal = true;
        for (i, head) in heads.iter_mut().enumerate() {
            while head.0 < max_v {
                match streams[i].next() {
                    Some(h) => *head = h,
                    None => return Some(total), // this pattern exhausted → done.
                }
            }
            if head.0 != max_v {
                all_equal = false;
            }
        }
        if all_equal {
            let prod: usize = heads.iter().map(|(_, c)| *c).product();
            total += prod;
            for (i, head) in heads.iter_mut().enumerate() {
                match streams[i].next() {
                    Some(h) => *head = h,
                    None => return Some(total),
                }
            }
        }
    }
}

/// Evaluate `GRAPH <name> { inner }`. Each named graph is a self-contained sub-`Graph` with its own
/// dictionary, so we evaluate `inner` against it and then TRANSLATE the result ids into the outer
/// graph's id space (materialise each term in the sub-graph, re-intern in the outer dict / local
/// vocab) — so the bindings join and serialise correctly. `GRAPH ?g { … }` unions over every named
/// graph, prepending the graph-name binding.
fn eval_graph_named(
    graph: &Graph,
    local: &mut LocalVocab,
    name: &NamedNodePattern,
    inner: &GraphPattern,
) -> Result<Bindings, String> {
    eval_graph_named_pref(graph, local, name, inner, None)
}

/// [OPUS-4.8] (sq-zz8z, gh-51) Extracts a SOUND graph-IRI prefix from a FILTER expression scoping
/// the graph variable `gv`, when the filter is — or AND-contains — `STRSTARTS(STR(?gv), "lit")`
/// with a SIMPLE / `xsd:string` constant `"lit"`. Returns the prefix the named-graph enumeration
/// can range-scan on; `None` if no such conjunct exists (the engine then falls back to the full
/// scan, so this is purely an optimisation hint and never affects correctness).
///
/// SOUNDNESS: the range scan keeps exactly the graphs whose `STR(?g)` starts with `"lit"`, which
/// is precisely what `STRSTARTS(STR(?g), "lit")` keeps — AND the original FILTER still runs
/// afterwards, so even if this recogniser were over-eager the result would be unchanged. We only
/// recognise a constant SIMPLE/`xsd:string` second argument (a lang-tagged or typed non-string
/// literal would make `STRSTARTS` itself a type error, so no prefix is meaningful there) and only
/// pull a prefix out of a top-level conjunction (`a && b`), never a disjunction/negation.
fn recognise_graph_prefix(expr: &Expression, gv: &Variable) -> Option<String> {
    use spargebra::algebra::Function;
    match expr {
        // STRSTARTS(STR(?gv), "lit")
        Expression::FunctionCall(Function::StrStarts, args) if args.len() == 2 => {
            // arg0 must be STR(?gv)
            let is_str_of_gv = matches!(
                &args[0],
                Expression::FunctionCall(Function::Str, inner)
                    if inner.len() == 1 && matches!(&inner[0], Expression::Variable(v) if v == gv)
            );
            if !is_str_of_gv {
                return None;
            }
            // arg1 must be a constant simple / xsd:string literal.
            match &args[1] {
                Expression::Literal(l) if l.language().is_none() && l.datatype() == oxrdf::vocab::xsd::STRING => {
                    Some(l.value().to_string())
                }
                _ => None,
            }
        }
        // A top-level conjunction: a prefix from EITHER side is sound (the other conjunct is
        // still enforced by the surviving FILTER). Prefer the left, else the right.
        Expression::And(l, r) => recognise_graph_prefix(l, gv).or_else(|| recognise_graph_prefix(r, gv)),
        _ => None,
    }
}

/// [OPUS-4.8] (sq-zz8z, gh-51) `eval_graph_named` with an optional graph-IRI PREFIX restriction
/// for the `GRAPH ?g` (variable) case: when `Some(prefix)`, only named graphs whose `STR(?g)`
/// starts with `prefix` are enumerated — via the sorted prefix index's RANGE SCAN
/// ([`Graph::for_named_graphs_with_prefix`]) rather than a full O(graphs) scan. This is purely an
/// enumeration restriction equivalent to a `FILTER(STRSTARTS(STR(?g), prefix))` applied to the
/// result (the caller's residual filter, if any, still runs and is then a no-op on the same rows),
/// so results are IDENTICAL to the unindexed path; the prefix only shrinks how many graphs are
/// visited. `None` (and the concrete-IRI case) keeps the original full enumeration.
fn eval_graph_named_pref(
    graph: &Graph,
    local: &mut LocalVocab,
    name: &NamedNodePattern,
    inner: &GraphPattern,
    prefix: Option<&str>,
) -> Result<Bindings, String> {
    fn eval_translated(
        graph: &Graph,
        local: &mut LocalVocab,
        sub: &Graph,
        #[cfg(feature = "zk")] gname: &Term,
        inner: &GraphPattern,
    ) -> Result<Bindings, String> {
        // Inside GRAPH the evaluation graph IS the named sub-graph: suspend a
        // view's empty-default short-circuit for the inner pattern (L1 view).
        let _scope = view::enter_graph();
        // zk-trace: tag the enclosed scans/filters with the named graph (the
        // sub-graph has its own dictionary; terms are materialized at record
        // time against it, so the tag is what attributes them). The `gname`
        // parameter is cfg'd out entirely when the feature is off, so the
        // default (wasm) build is byte-identical.
        #[cfg(feature = "zk")]
        let _zk = crate::zk::graph_scope(gname);
        let mut sub_local = LocalVocab::default();
        let b = eval_graph_pattern(sub, &mut sub_local, inner)?;
        let rows: Vec<Row> = b
            .rows
            .iter()
            .map(|r| {
                r.iter()
                    .map(|&id| match term_of(sub, &sub_local, id) {
                        Some(t) => value_to_id(graph, local, &Value::Term(t)),
                        None => NO_ID,
                    })
                    .collect()
            })
            .collect();
        Ok(Bindings::unsorted(b.vars, rows))
    }
    match name {
        NamedNodePattern::NamedNode(n) => {
            let target = Term::NamedNode(n.clone());
            // A graph outside an installed dataset view takes the absent-graph
            // branch below: non-visible must be INDISTINGUISHABLE from absent
            // (the L1 view's security property).
            let sub = if view::allows(&target) {
                graph.named.iter().find(|(t, _)| *t == target).map(|(_, sub)| sub)
            } else {
                None
            };
            match sub {
                Some(sub) => eval_translated(
                    graph,
                    local,
                    sub,
                    #[cfg(feature = "zk")]
                    &target,
                    inner,
                ),
                // The named graph is absent → ZERO solutions (even for `GRAPH <g> {}`,
                // which must NOT yield the unit row), but with `inner`'s variable
                // schema — evaluate against an empty graph for the columns, then drop
                // any rows (an empty group pattern would otherwise produce one).
                None => {
                    let _scope = view::enter_graph(); // schema eval matches the present-graph path
                    // zk-trace: an absent graph still records the operator
                    // boundary + (empty) pattern input sets under its name.
                    #[cfg(feature = "zk")]
                    let _zk = crate::zk::graph_scope(&target);
                    let empty = Graph::load_str("", "ntriples").map_err(|e| e.to_string())?;
                    let mut el = LocalVocab::default();
                    let mut b = eval_graph_pattern(&empty, &mut el, inner)?;
                    b.rows.clear();
                    Ok(b)
                }
            }
        }
        NamedNodePattern::Variable(v) => {
            // [OPUS-4.8] (sq-zz8z) Accumulate the per-graph relations into ONE flat row buffer in
            // a stable column schema (`?g` first, then the inner pattern's columns) rather than
            // folding with `union_bindings` once per graph. The old fold re-copied the WHOLE
            // accumulated relation on every graph, making `GRAPH ?g` over G graphs O(G²); a single
            // shared schema makes it O(total rows). The `?g`-first schema matches the old
            // `None`-branch insert order, so projected results are unchanged.
            let mut out_vars: Option<Vec<Variable>> = None;
            let mut out_rows: Vec<Row> = Vec::new();
            let mut per_graph = |graph: &Graph, local: &mut LocalVocab, gname: &Term, sub: &Graph| -> Result<(), String> {
                // zk-trace: each iteration of `GRAPH ?g` tags the enclosed scans/filters with the
                // iteration's named graph — the scope is installed INSIDE eval_translated (one
                // place), so the operator boundary stream is not double-nested.
                let mut b = eval_translated(
                    graph,
                    local,
                    sub,
                    #[cfg(feature = "zk")]
                    gname,
                    inner,
                )?;
                let gid = value_to_id(graph, local, &Value::Term(gname.clone()));
                // Resolve this graph's columns into the shared `?g`-first schema (set on the first
                // graph; every named sub-graph yields the same `inner` schema, so it is stable).
                let schema = out_vars.get_or_insert_with(|| {
                    let mut s = Vec::with_capacity(b.vars.len() + 1);
                    s.push(v.clone());
                    for var in &b.vars {
                        if var != v {
                            s.push(var.clone());
                        }
                    }
                    s
                });
                match b.col(v) {
                    // The inner pattern itself binds the graph variable (e.g.
                    // `GRAPH ?g { ?g :p ?o }` or a VALUES/OPTIONAL inside): JOIN with
                    // the active graph name — keep rows already bound to this graph,
                    // fill unbound cells, drop conflicting rows.
                    Some(c) => {
                        b.rows.retain_mut(|row| {
                            if row[c] == NO_ID {
                                row[c] = gid;
                                true
                            } else {
                                row[c] == gid
                            }
                        });
                    }
                    None => {
                        b.vars.insert(0, v.clone());
                        for row in &mut b.rows {
                            row.insert(0, gid);
                        }
                    }
                }
                // Map each row into the shared schema (column positions can differ per graph only
                // if the inner schema ever reordered — it does not — so this is a cheap permute).
                // Precompute schema-column -> position-in-`b.vars` ONCE per binding-set (instead of
                // an O(vars) linear `position(..)` search per (row, var) cell — an O(rows·vars²)
                // hotspot on large `GRAPH ?g` scans), then map each row with O(1) indexed lookups.
                let col_map: Vec<Option<usize>> = schema
                    .iter()
                    .map(|var| b.vars.iter().position(|x| x == var))
                    .collect();
                for row in &b.rows {
                    out_rows.push(
                        col_map
                            .iter()
                            .map(|&pos| pos.map(|i| row[i]).unwrap_or(NO_ID))
                            .collect(),
                    );
                }
                Ok(())
            };
            match prefix {
                // Indexed range scan over only the prefix-matching graphs (O(log G + matches)).
                // The view-visibility (L1) check stays — a non-visible graph is still skipped.
                Some(pref) => {
                    let mut err: Option<String> = None;
                    graph.for_named_graphs_with_prefix(pref, |gname, sub| {
                        if err.is_some() || !view::allows(gname) {
                            return;
                        }
                        if let Err(e) = per_graph(graph, local, gname, sub) {
                            err = Some(e);
                        }
                    });
                    if let Some(e) = err {
                        return Err(e);
                    }
                }
                // Full enumeration (no prefix restriction).
                None => {
                    for (gname, sub) in &graph.named {
                        if !view::allows(gname) {
                            continue; // not visible under the installed dataset view (L1)
                        }
                        per_graph(graph, local, gname, sub)?;
                    }
                }
            }
            let vars = out_vars.unwrap_or_else(|| vec![v.clone()]);
            Ok(Bindings::unsorted(vars, out_rows))
        }
    }
}

/// Operator-entry dispatcher. When an EXPLAIN ANALYZE trace is installed (T22) it
/// routes through the `#[cold]` timing wrapper; otherwise it is a direct call into
/// the evaluator — the only cost on the normal path is one thread-local flag read
/// per *operator* (the same class of check `budget::check` already does here).
fn eval_graph_pattern(graph: &Graph, local: &mut LocalVocab, p: &GraphPattern) -> Result<Bindings, String> {
    let b = if trace::enabled() {
        eval_graph_pattern_traced(graph, local, p)?
    } else {
        eval_graph_pattern_inner(graph, local, p)?
    };
    // [OPUS-4.8] (sq-s5is) Byte-accounted cap: price THIS operator's output at its true
    // WIDTH (`vars × BYTES_PER_ID`), the dimension the row cap misses. The operator
    // dispatcher is the single cooperative chokepoint every materialised intermediate
    // flows back through, so one width-aware check here bounds the widest intermediate.
    // No-op (one thread-local read) when no budget is installed.
    let prev = budget::set_width(b.vars.len());
    let r = budget::check(b.rows.len());
    budget::restore_width(prev);
    r?;
    Ok(b)
}

/// EXPLAIN ANALYZE wrapper: records one trace node per operator with its output
/// row count and wall time. `#[cold]` keeps it (and the `Instant` plumbing) off
/// the normal path entirely.
#[cold]
fn eval_graph_pattern_traced(graph: &Graph, local: &mut LocalVocab, p: &GraphPattern) -> Result<Bindings, String> {
    let idx = trace::enter(trace_label(p));
    // Structured EXPLAIN (`explain-json`): attach the planner's estimated output
    // cardinality to conjunctive (BGP) nodes so the q-error compares the engine's own
    // estimate against the ANALYZE actual. Only BGP nodes carry a cardinality model;
    // an estimate failure (e.g. an unresolvable constant) just leaves `est = None`.
    // [OPUS-4.8] sq-u4lgr
    #[cfg(feature = "explain-json")]
    if is_conjunctive(p) {
        if let Ok(est) = bgp_estimate(graph, p) {
            trace::set_est(idx, est);
        }
    }
    #[cfg(not(target_arch = "wasm32"))]
    let start = std::time::Instant::now();
    let r = eval_graph_pattern_inner(graph, local, p);
    #[cfg(not(target_arch = "wasm32"))]
    let nanos = start.elapsed().as_nanos() as u64;
    // `Instant` is unusable on wasm32-unknown-unknown (it panics): rows only there.
    #[cfg(target_arch = "wasm32")]
    let nanos = 0u64;
    trace::exit(idx, r.as_ref().map_or(0, |b| b.rows.len()), nanos);
    r
}

/// Crate-internal accessor for [`trace_label`], used by the structured EXPLAIN
/// (`explain-json`) to label planning-only tree nodes with the SAME operator labels
/// the text ANALYZE trace prints. [OPUS-4.8] sq-u4lgr
#[cfg(feature = "explain-json")]
pub(crate) fn trace_label_pub(p: &GraphPattern) -> String {
    trace_label(p)
}

/// The operator label an EXPLAIN ANALYZE trace node carries (only built while tracing).
fn trace_label(p: &GraphPattern) -> String {
    if is_conjunctive(p) {
        let mut patterns = Vec::new();
        let mut filters = Vec::new();
        flatten_conjunction(p, &mut patterns, &mut filters);
        let plan = if bgp_uses_binary(&patterns) { "binary GOO" } else { "worst-case-optimal (LFTJ)" };
        return format!("BGP [{plan}] ({} patterns, {} filters)", patterns.len(), filters.len());
    }
    match p {
        GraphPattern::Bgp { patterns } => format!("BGP ({} patterns)", patterns.len()),
        GraphPattern::Filter { .. } => "Filter".into(),
        GraphPattern::Join { .. } => "Join".into(),
        GraphPattern::LeftJoin { .. } => "LeftJoin (OPTIONAL)".into(),
        GraphPattern::Union { .. } => "Union".into(),
        GraphPattern::Extend { variable, .. } => format!("Extend (BIND ?{})", variable.as_str()),
        GraphPattern::Minus { .. } => "Minus".into(),
        GraphPattern::Values { .. } => "Values".into(),
        GraphPattern::Path { .. } => "PropertyPath".into(),
        GraphPattern::Graph { .. } => "Graph".into(),
        GraphPattern::Project { .. } => "Project (sub-select)".into(),
        GraphPattern::Distinct { .. } => "Distinct".into(),
        GraphPattern::Reduced { .. } => "Reduced".into(),
        GraphPattern::Slice { .. } => "Slice".into(),
        GraphPattern::OrderBy { .. } => "OrderBy".into(),
        GraphPattern::Group { .. } => "Group".into(),
        _ => "Other".into(),
    }
}

fn eval_graph_pattern_inner(graph: &Graph, local: &mut LocalVocab, p: &GraphPattern) -> Result<Bindings, String> {
    budget::check(0)?; // coarse cooperative cancellation: once per operator entry
    if is_conjunctive(p) {
        let mut patterns = Vec::new();
        let mut filters = Vec::new();
        flatten_conjunction(p, &mut patterns, &mut filters);
        // [FABLE-5] (sq-7d3dj.30.7) Equality-FILTER → value-join unification (opt-in
        // `value-join` feature): a `FILTER(?a = ?b)` whose operands come from otherwise
        // DISCONNECTED components of the pattern set executes as a value-keyed hash join
        // between the components instead of a cross-product-then-filter. Any shape not
        // provably safe declines (`Ok(None)`) to the verbatim path below — see the
        // `eqjoin` module docs for the eligibility conditions and the soundness argument.
        #[cfg(feature = "value-join")]
        if let Some(b) = eqjoin::try_eq_component_join(graph, local, &patterns, &filters)? {
            return Ok(b);
        }
        return eval_flat_conjunctive(graph, local, &patterns, filters);
    }
    match p {
        GraphPattern::Bgp { patterns } => eval_bgp(graph, patterns),
        GraphPattern::Filter { expr, inner } => {
            // [OPUS-4.8] (sq-zz8z, gh-51) Prefix-scoped-aggregate fast path: a
            // `GRAPH ?g { … } FILTER(STRSTARTS(STR(?g), "prefix"))` (the PSS multi-tenant
            // `usage(prefix)` shape) only needs the named graphs whose IRI starts with `prefix`.
            // Push the prefix into the graph enumeration so it RANGE-SCANS the sorted graph-IRI
            // index (O(log G + matches)) instead of enumerating all G graphs. The FILTER below
            // STILL runs and is exact, so the result is unchanged — the pushdown only restricts
            // which graphs are visited.
            if let GraphPattern::Graph { name: NamedNodePattern::Variable(gv), inner: ginner } = inner.as_ref() {
                if let Some(prefix) = recognise_graph_prefix(expr, gv) {
                    let mut b = eval_graph_named_pref(
                        graph,
                        local,
                        &NamedNodePattern::Variable(gv.clone()),
                        ginner,
                        Some(&prefix),
                    )?;
                    // [FABLE-5] (sq-7d3dj.30.11) Install the static non-literal column set for the
                    // id-level FILTER fast path, scoped to this one dispatch.
                    #[cfg(feature = "id-filter-fastpath")]
                    {
                        let cols = nonliteral_filter_cols(graph, inner, &b);
                        with_idfast_nonlit_cols(cols, || apply_filter(graph, local, &mut b, expr))?;
                    }
                    #[cfg(not(feature = "id-filter-fastpath"))]
                    apply_filter(graph, local, &mut b, expr)?;
                    return Ok(b);
                }
            }
            // [FABLE-5] (sq-7d3dj.30.9) Correlated (theta) anti-join: the negation idiom
            // `Filter(!bound(?nb), LeftJoin(A, B, Some(F)))` with an OPTIONAL condition
            // that references OUTER variables (SP2Bench q06) — the #1735 rewrite declines
            // it (it needs `expression: None`). This recognises the shape, seeds the right
            // scan sideways with the outer correlation IRI, and evaluates a correlated
            // anti-join with the residual theta re-checked verbatim. Any miss returns
            // `None` and falls through to the identical cold `Filter{LeftJoin}` plan below.
            if let Some(b) = try_theta_antijoin(graph, local, expr, inner)? {
                return Ok(b);
            }
            let mut b = eval_graph_pattern(graph, local, inner)?;
            #[cfg(feature = "id-filter-fastpath")]
            {
                let cols = nonliteral_filter_cols(graph, inner, &b);
                with_idfast_nonlit_cols(cols, || apply_filter(graph, local, &mut b, expr))?;
            }
            #[cfg(not(feature = "id-filter-fastpath"))]
            apply_filter(graph, local, &mut b, expr)?;
            Ok(b)
        }
        GraphPattern::Join { left, right } => {
            let l = eval_graph_pattern(graph, local, left)?;
            // Bind-join pushdown: if the RIGHT side is a SERVICE and the left has
            // already bound its join variables, push those bindings to the remote as a
            // VALUES block instead of materialising the whole remote relation. Join is
            // symmetric, so try either side as the SERVICE. [OPUS-4.8] (sq-sjkj)
            #[cfg(feature = "service")]
            {
                if let Some(r) = try_bound_join_service(graph, local, &l, right)? {
                    return Ok(join_bindings(l, r));
                }
                // Symmetric: SERVICE on the left, bindings produced by the right.
                if matches!(left.as_ref(), GraphPattern::Service { .. }) {
                    let r = eval_graph_pattern(graph, local, right)?;
                    if let Some(sl) = try_bound_join_service(graph, local, &r, left)? {
                        return Ok(join_bindings(r, sl));
                    }
                    // Fall through with the already-evaluated right; recompute left verbatim.
                    let l2 = eval_graph_pattern(graph, local, left)?;
                    return Ok(join_bindings(l2, r));
                }
            }
            // Sideways information passing (SIP): when the already-evaluated `l` is
            // SMALL, evaluate the big `right` child CORRELATED on it — seeding scans
            // (incl. inside UNION branches) from `l`'s bound IRIs instead of cold.
            // Conservative: any scope/threshold condition failure returns `None` and
            // we fall through to the cold join below, bit-for-bit. [OPUS-4.8] (sq-7d3dj.30.3)
            if let Some(joined) = try_sip_join(graph, local, &l, right)? {
                return Ok(joined);
            }
            let r = eval_graph_pattern(graph, local, right)?;
            Ok(join_bindings(l, r))
        }
        GraphPattern::LeftJoin { left, right, expression } => {
            // zk-trace: operator boundary marker (one thread-local read; the
            // scope is a no-op when the recorder is disarmed). NOTE: the
            // embedded OPTIONAL condition is evaluated inside the join and is
            // NOT recorded as a FilterObligation (see zk module docs).
            #[cfg(feature = "zk")]
            let _zk = crate::zk::op_scope(crate::zk::Op::Optional);
            let l = eval_graph_pattern(graph, local, left)?;
            // Bind-join pushdown for `… OPTIONAL { SERVICE { … } }`: the SERVICE may
            // only be the RIGHT (preserved) side of a left join — pushing the left's
            // bound join vars restricts the remote relation, then the SAME
            // `left_outer_join` reattaches it, so OPTIONAL semantics are unchanged
            // (a left row with no remote match still survives, unbound). [OPUS-4.8] (sq-sjkj)
            #[cfg(feature = "service")]
            if let Some(r) = try_bound_join_service(graph, local, &l, right)? {
                return left_outer_join(graph, local, l, r, expression.as_ref());
            }
            let r = eval_graph_pattern(graph, local, right)?;
            left_outer_join(graph, local, l, r, expression.as_ref())
        }
        GraphPattern::Union { left, right } => {
            #[cfg(feature = "zk")]
            let _zk = crate::zk::op_scope(crate::zk::Op::Union);
            let l = eval_graph_pattern(graph, local, left)?;
            let r = eval_graph_pattern(graph, local, right)?;
            Ok(union_bindings(l, r))
        }
        GraphPattern::Extend { inner, variable, expression } => {
            let b = eval_graph_pattern(graph, local, inner)?;
            extend_bindings(graph, local, b, variable, expression)
        }
        GraphPattern::Minus { left, right } => {
            #[cfg(feature = "zk")]
            let _zk = crate::zk::op_scope(crate::zk::Op::Minus);
            let l = eval_graph_pattern(graph, local, left)?;
            let r = eval_graph_pattern(graph, local, right)?;
            Ok(minus_bindings(l, r))
        }
        GraphPattern::Values { variables, bindings } => Ok(values_bindings(graph, local, variables, bindings)),
        GraphPattern::Path { subject, path, object } => {
            // zk-trace: property-path expansion scans the store without
            // per-pattern attribution — record an Op::Path marker so a
            // consumer fails closed (ZkTrace::first_uncaptured) rather than
            // building an insufficient witness set.
            #[cfg(feature = "zk")]
            let _zk = crate::zk::op_scope(crate::zk::Op::Path);
            eval_path(graph, local, subject, path, object)
        }
        GraphPattern::Graph { name, inner } => eval_graph_named(graph, local, name, inner),
        // SPARQL 1.1 federated query. Behind the NON-DEFAULT `service` feature; when
        // off this falls through to the generic "unsupported" error below (and never
        // compiles the HTTP stack). [OPUS-4.8]
        #[cfg(feature = "service")]
        GraphPattern::Service { name, inner, silent } => {
            // [OPUS-5] (sq-lsp7k.2.2) A registered LOCAL handler intercepts the IRI
            // BEFORE the transport is reached. A miss returns `None` and the HTTP path
            // below runs unchanged (egress allowlist and all). Compiled out entirely
            // when `service-local` is off.
            #[cfg(feature = "service-local")]
            if let Some(b) = try_local_service(graph, local, name, inner, *silent)? {
                return Ok(b);
            }
            eval_service(graph, local, name, inner, *silent)
        }
        // [OPUS-5] (sq-lsp7k.2.2) `service-local` WITHOUT `service`: local handlers are
        // usable on their own — no HTTP/TLS stack is compiled, and an IRI with no
        // handler keeps exactly the "unsupported" outcome the feature-off build gives
        // it (under SILENT, the join identity, matching how the HTTP path degrades).
        #[cfg(all(feature = "service-local", not(feature = "service")))]
        GraphPattern::Service { name, inner, silent } => {
            match try_local_service(graph, local, name, inner, *silent)? {
                Some(b) => Ok(b),
                None if *silent => Ok(Bindings::unsorted(Vec::new(), vec![Row::new()])),
                None => Err(format!("unsupported graph pattern: {:?}", p)),
            }
        }
        GraphPattern::Project { .. }
        | GraphPattern::Distinct { .. }
        | GraphPattern::Reduced { .. }
        | GraphPattern::Slice { .. }
        | GraphPattern::OrderBy { .. }
        | GraphPattern::Group { .. } => eval_modified(graph, local, p),
        other => Err(format!("unsupported graph pattern: {other:?}")),
    }
}

/// Evaluates a flattened conjunctive group (triple `patterns` + group `filters`).
///
/// Extracted VERBATIM from the `is_conjunctive` arm of [`eval_graph_pattern_inner`]
/// (sq-7d3dj.30.7) so the `value-join` component path can evaluate each connected
/// component through EXACTLY the machinery the whole group would have used; with the
/// feature off this is simply the old inline body. Sargable numeric FILTERs are pushed
/// down into the binary-plan scans (the WCOJ path applies them afterwards); the rest
/// run as residual filters over the joined result. [FABLE-5]
fn eval_flat_conjunctive(
    graph: &Graph,
    local: &mut LocalVocab,
    patterns: &[TriplePattern],
    filters: Vec<Expression>,
) -> Result<Bindings, String> {
    let (mut b, residual) = if bgp_uses_binary(patterns) {
        let (pat_filters, residual) = split_sargable(graph, patterns, &filters);
        // [OPUS-4.8] (sq-5zf8i / §A4) Acyclic BGP: run the Yannakakis full-semijoin
        // prepass before the binary join when the opt-in `yannakakis` feature is on
        // (it internally cost-gates + falls back to `eval_bgp_binary`, threading the
        // same pushed-down `pat_filters` through the materialising scans so the result
        // — and the FILTER semantics — are identical). OFF by default => the next line
        // is the only code that compiles, byte-identical to before.
        #[cfg(feature = "yannakakis")]
        let bound = eval_bgp_yannakakis(graph, patterns, &pat_filters)?;
        #[cfg(not(feature = "yannakakis"))]
        let bound = eval_bgp_binary(graph, patterns, &pat_filters)?;
        (bound, residual)
    } else {
        (eval_bgp(graph, patterns)?, filters)
    };
    // [FABLE-5] (sq-1ivw7) The non-literal column set for the residual FILTERs of THIS fused BGP.
    // Its columns index `b`'s layout (the BGP variables); an object of a literal-free constant
    // predicate is proven non-literal by the snapshot-aware analysis, unblocking the id fast path
    // for flat BGP+FILTER shapes too (previously only the wrapped `Filter` dispatch installed a
    // set). Drain-safe: `with_idfast_nonlit_cols` drains on the first consuming `apply_filter`, so
    // a nested EXISTS on a different layout sees the empty default. Built once (cheap) and reused.
    #[cfg(feature = "id-filter-fastpath")]
    let idfast_cols = {
        let bgp = GraphPattern::Bgp { patterns: patterns.to_vec() };
        nonliteral_filter_cols(graph, &bgp, &b)
    };
    for f in &residual {
        // Spatial pushdown (sq-mg9): if this residual FILTER is a pushable geof:
        // predicate and a SpatialProvider is installed, pre-restrict the rows to the
        // index's candidate superset over the geometry variable. The FILTER below
        // STILL runs and does the exact refinement, so the result is unchanged — the
        // pushdown only shrinks how many rows the exact `geof:` check examines.
        if let Some(pd) = recognise_spatial(f) {
            // [FABLE-5] (sq-lk3aw.4) EXACT-candidate pushdown first: when the provider
            // CERTIFIES the exact indexed answer set AND every surviving row is
            // certified, the residual `geof:` FILTER is provably an identity on `b` —
            // skip it (the `continue`). Any other outcome keeps the residual FILTER:
            // `Partial` already restricted the rows (the residual judges the remaining
            // not-indexed bindings), `Declined` falls back to the superset pushdown,
            // unchanged. Soundness argument: see `apply_spatial_pushdown_exact`.
            #[cfg(feature = "spatial-exact-pushdown")]
            match apply_spatial_pushdown_exact(graph, &mut b, &pd) {
                ExactPushdown::AllCertified => continue,
                ExactPushdown::Partial => {}
                ExactPushdown::Declined => {
                    apply_spatial_pushdown(graph, &mut b, &pd);
                }
            }
            #[cfg(not(feature = "spatial-exact-pushdown"))]
            apply_spatial_pushdown(graph, &mut b, &pd);
        }
        #[cfg(feature = "id-filter-fastpath")]
        with_idfast_nonlit_cols(idfast_cols.clone(), || apply_filter(graph, local, &mut b, f))?;
        #[cfg(not(feature = "id-filter-fastpath"))]
        apply_filter(graph, local, &mut b, f)?;
    }
    Ok(b)
}

/// SPARQL 1.1 federated query (`SERVICE`) — the VERBATIM path. [OPUS-4.8]
///
/// Forwards `SELECT * WHERE { <inner> }` to the remote `endpoint`, parses the
/// SPARQL-Results-JSON response (see the `sparq-engine-service` crate) and turns it into a
/// [`Bindings`] relation interned against this query's dictionaries — exactly as
/// `VALUES` does — so the caller joins it with the surrounding group via the normal
/// `join_bindings` path.
///
/// This is the fallback path: when the SERVICE is the right side of a join whose join
/// vars are already bound, [`try_bound_join_service`] instead pushes those bindings as
/// a `VALUES` block (the bind-join, bead sq-sjkj) and this verbatim forward is skipped.
/// A VARIABLE endpoint that the surrounding query binds is likewise handled there
/// (per-endpoint dispatch, bead sq-d4p). `eval_service` still runs for a top-level /
/// unbound SERVICE and for every case the bind-join declines (no bound join var,
/// blank-node join key, or a variable endpoint with nothing to bind it).
///
/// * `name` is a `NamedNodePattern`: a concrete IRI endpoint is evaluated; a
///   `?var` (variable) endpoint reaching THIS path has no surrounding binding to supply
///   the endpoint IRI (a top-level `SERVICE ?ep`), so there is nothing to call — it
///   errors, or, under SILENT, yields the join identity. (A bindable variable endpoint
///   never reaches here; it is dispatched by [`try_bound_join_service`].)
/// * `silent`: on ANY failure (variable endpoint, DNS/connect error, non-2xx,
///   malformed body), produce a single empty solution (the identity for join) so the
///   surrounding query keeps its bindings and does not fail.
#[cfg(feature = "service")]
fn eval_service(
    graph: &Graph,
    local: &mut LocalVocab,
    name: &NamedNodePattern,
    inner: &GraphPattern,
    silent: bool,
) -> Result<Bindings, String> {
    // The join identity: one row with zero columns. Joining it leaves the other
    // side unchanged (it is `{ {} }`, the single empty mapping). This is the
    // SILENT-failure fallback AND the result of an empty remote relation under the
    // standard's evalService when the pattern binds nothing.
    let identity = || Bindings::unsorted(Vec::new(), vec![Row::new()]);

    // The variables the inner pattern can bind (their textual names drive the row
    // layout we build from the SRJ `head.vars`).
    let endpoint = match name {
        NamedNodePattern::NamedNode(n) => n.as_str().to_string(),
        NamedNodePattern::Variable(_) => {
            // `SERVICE ?endpoint { … }` — not supported (would need a remote call per
            // binding of ?endpoint). Documented scope-out.
            if silent {
                return Ok(identity());
            }
            return Err(
                "SERVICE with a variable endpoint (`SERVICE ?var { … }`) is not supported".into(),
            );
        }
    };

    // Render the inner algebra back to SPARQL syntax and wrap as a SELECT *. spargebra's
    // Display round-trips algebra → concrete syntax, so OPTIONAL/FILTER/UNION/sub-SELECT
    // inside the SERVICE block are all forwarded verbatim.
    let query = format!("SELECT * WHERE {{ {inner} }}");

    // [FABLE-5] (sq-my8wd.4) STREAMING consumption: each remote row is interned to a
    // compact id-level `Row` AS IT IS PARSED (the owned terms are dropped immediately)
    // instead of collecting the whole remote relation as `Term`s first. Result-identical
    // to the collect-then-intern path — same rows, multiplicity and order (pinned by the
    // service.rs `streaming_equivalence` tests) — but the per-response peak memory is
    // the response body plus the id-level relation the join needs anyway, not a
    // whole-document DOM plus a second term-level copy.
    //
    // [OPUS-4.8] (sq-my8wd.5) READER-SEAM: use `eval_remote_into_read` so the HTTP body
    // is consumed as a STREAM (never buffered as a full `String`). Peak memory now stays
    // BELOW the response body size (not just O(body)) — the body String is eliminated.
    // Test transports are wrapped via `TransportAsReader` so all existing tests pass.
    let mut id_rows: Vec<Row> = Vec::new();
    // [OPUS-4.8] (sq-my8wd.4) Savepoint the local vocab + byte budget BEFORE streaming so
    // a SILENT error can roll the partially-interned rows back out — see the SILENT arm.
    let vocab_mark = local.savepoint();
    let byte_mark = budget::byte_savepoint();
    let fetched = service_reader_transport::with(|t| {
        sparq_engine_service::service::eval_remote_into_read(t, &endpoint, &query, &mut |row| {
            id_rows.push(intern_remote_row(graph, local, &row));
            Ok(())
        })
    });
    match fetched {
        Ok(vars) => Ok(Bindings::unsorted(vars, id_rows)),
        Err(e) if silent => {
            // SILENT: swallow the error, keep the surrounding bindings. Rows already
            // interned from a partially-parsed response are discarded with `id_rows` —
            // and, so the discard is behaviour-NEUTRAL with the pre-streaming
            // collect-then-intern-on-success path (which interned nothing on a swallowed
            // error), we ROLL the interned terms out of the local vocab and REFUND the
            // byte budget they charged. Without this a partial stream would retain memory
            // and could trip `max_bytes`, turning a query the old path answered into a
            // "query budget exceeded" error. [OPUS-4.8] (sq-my8wd.4)
            let _ = e;
            id_rows.clear();
            local.rollback_to(vocab_mark);
            budget::restore_bytes(byte_mark);
            Ok(identity())
        }
        Err(e) => Err(e),
    }
}

/// Answer `SERVICE <iri> { inner }` from a LOCAL in-process handler, if one is
/// registered for `iri`. [OPUS-5] (sq-lsp7k.2.2)
///
/// Returns:
/// * `Ok(Some(rel))` — a handler served the IRI; `rel` is its rows interned against
///   this query's dictionaries (exactly as `VALUES` and the remote SERVICE relation
///   are), ready for the caller's ordinary join.
/// * `Ok(None)` — no handler applies (a variable endpoint, or an IRI absent from the
///   registry / no registry installed). The caller proceeds EXACTLY as it did before
///   this feature existed: the `service` HTTP path, egress allowlist included.
/// * `Err(_)` — a non-SILENT handler failure (a returned `Err`, or a violation of the
///   [`crate::LocalServiceRows`] header/arity contract, or a returned column that is
///   NOT in scope in the SERVICE group).
///
/// ## Why an out-of-scope column is rejected
///
/// The relation must be one the SERVICE group itself could have produced: a remote
/// endpoint answering `SELECT * WHERE { … }` can only ever return the group's in-scope
/// variables. A handler returning some OTHER variable would silently join against an
/// identically-named variable of the SURROUNDING query — `VALUES ?x { 1 } SERVICE <h>
/// { ?s ?p ?o }` with a returned `?x = 2` would drop the outer row — which is neither
/// the SERVICE group's semantics nor the remote path's. It is a handler bug, so it is
/// reported like any other invalid relation rather than projected away silently.
///
/// ## Why the intercept sits here
///
/// This is upstream of `eval_service`, so a handled SERVICE never constructs a
/// transport and never consults the egress policy — there is no request to police. The
/// registry can therefore only REMOVE outbound reach, never grant it; the SSRF
/// default-deny filter still guards every IRI that misses.
///
/// SILENT is honoured identically to the remote path: the failure is swallowed and the
/// join identity (one zero-column row) is returned so the surrounding solutions
/// survive. As on that path, terms interned before the failure are rolled back out of
/// the local vocab and their byte-budget charge refunded, so a swallowed failure is
/// resource-neutral.
#[cfg(feature = "service-local")]
fn try_local_service(
    graph: &Graph,
    local: &mut LocalVocab,
    name: &NamedNodePattern,
    inner: &GraphPattern,
    silent: bool,
) -> Result<Option<Bindings>, String> {
    // Only a CONCRETE endpoint is dispatched locally — `SERVICE ?ep { … }` keeps its
    // existing behaviour exactly (documented scope-out, see the module docs).
    let NamedNodePattern::NamedNode(iri) = name else {
        return Ok(None);
    };
    let Some(handler) = local_services::lookup(iri.as_str()) else {
        return Ok(None);
    };

    // The in-scope variables of the SERVICE group, first-occurrence order — the same
    // set the bind-join computes for its VALUES head.
    let mut vars: Vec<Variable> = Vec::new();
    inner.on_in_scope_variable(|v| {
        if !vars.contains(v) {
            vars.push(v.clone());
        }
    });
    // Byte-for-byte the string the HTTP transport would have sent for this SERVICE.
    let query = format!("SELECT * WHERE {{ {} }}", inner);
    let patterns = local_service_patterns(inner);
    let req = crate::LocalServiceRequest {
        service: iri.as_str(),
        query: &query,
        vars: &vars,
        patterns: &patterns,
    };

    let vocab_mark = local.savepoint();
    let byte_mark = budget::byte_savepoint();
    let produced = handler(&req).and_then(|rows| {
        rows.validate()
            .and_then(|()| {
                // The returned relation may only name columns the SERVICE group itself
                // puts in scope (see the doc comment): anything else would join with a
                // same-named variable OUTSIDE the group. [SONNET-4.6]
                match rows.vars.iter().find(|v| !vars.contains(v)) {
                    Some(v) => Err(format!(
                        "variable ?{} is not in scope in the SERVICE group",
                        v.as_str()
                    )),
                    None => Ok(()),
                }
            })
            .map_err(|e| {
                format!("local SERVICE <{}> returned an invalid relation: {}", iri.as_str(), e)
            })?;
        let id_rows: Vec<Row> =
            rows.rows.iter().map(|r| intern_remote_row(graph, local, r)).collect();
        budget::check(id_rows.len())?;
        Ok(Bindings::unsorted(rows.vars, id_rows))
    });
    match produced {
        Ok(b) => Ok(Some(b)),
        Err(e) if silent => {
            let _ = e;
            local.rollback_to(vocab_mark);
            budget::restore_bytes(byte_mark);
            Ok(Some(Bindings::unsorted(Vec::new(), vec![Row::new()])))
        }
        Err(e) => Err(e),
    }
}

/// Decompose a SERVICE group into the neutral triple-pattern view handed to a local
/// handler — the table-function argument channel. ALL-OR-NOTHING on purpose: only a
/// FLAT basic graph pattern decomposes; any richer group (OPTIONAL / UNION / FILTER /
/// sub-SELECT / paths) yields an EMPTY vec so a handler can never mistake a partial
/// view for the whole group and answer as though it had understood it. Such a handler
/// works from [`crate::LocalServiceRequest::query`] instead. [OPUS-5] (sq-lsp7k.2.2)
#[cfg(feature = "service-local")]
fn local_service_patterns(inner: &GraphPattern) -> Vec<crate::LocalServicePattern> {
    use crate::{LocalServicePattern, LocalServiceSlot as S};
    let GraphPattern::Bgp { patterns } = inner else {
        return Vec::new();
    };
    // An RDF 1.2 quoted-triple slot may itself contain variables, so it is neither a
    // `Term` nor a `Variable`: decline the whole decomposition rather than flatten it.
    let term_slot = |t: &TermPattern| match t {
        TermPattern::NamedNode(n) => Some(S::Term(Term::from(n.clone()))),
        TermPattern::BlankNode(b) => Some(S::Term(Term::from(b.clone()))),
        TermPattern::Literal(l) => Some(S::Term(Term::from(l.clone()))),
        TermPattern::Variable(v) => Some(S::Var(v.clone())),
        TermPattern::Triple(_) => None,
    };
    let mut out: Vec<LocalServicePattern> = Vec::with_capacity(patterns.len());
    for tp in patterns {
        let (Some(subject), Some(object)) = (term_slot(&tp.subject), term_slot(&tp.object)) else {
            return Vec::new();
        };
        out.push(LocalServicePattern {
            subject,
            predicate: match &tp.predicate {
                NamedNodePattern::NamedNode(n) => S::Term(Term::from(n.clone())),
                NamedNodePattern::Variable(v) => S::Var(v.clone()),
            },
            object,
        });
    }
    out
}

/// Intern ONE remote solution row into an id-level [`Row`] against this query's
/// dictionaries — exactly as `VALUES` does — so it joins with local BGP results: each
/// term resolves against the graph dictionary first, else the query-local vocab.
/// Shared by the verbatim and bound-join paths, which feed it row-by-row from the
/// streaming SERVICE parser rather than materialising the remote relation first.
/// [FABLE-5] (sq-my8wd.4; formerly the whole-relation `service_relation_to_bindings`,
/// sq-sjkj)
#[cfg(any(feature = "service", feature = "service-local"))]
fn intern_remote_row(graph: &Graph, local: &mut LocalVocab, row: &[Option<Term>]) -> Row {
    row.iter()
        .map(|cell| match cell {
            None => NO_ID,
            Some(t) => graph.id_of(t).unwrap_or_else(|| local.intern(t.clone())),
        })
        .collect()
}

/// Attempt a bind-join (`VALUES` pushdown) of a SERVICE sub-query against the
/// already-evaluated `left` bindings. [OPUS-4.8] (sq-sjkj — research candidate C1)
///
/// Returns:
/// * `Ok(Some(service_bindings))` — the bound-join applied: a remote relation
///   restricted to `left`'s bound join-key tuples, ready for the caller to join (or
///   left-outer-join) with `left` exactly as it would the verbatim relation. The
///   answer is identical to the unbound-then-local-join path.
/// * `Ok(None)` — the pushdown does NOT apply (the right side is not a concrete-IRI
///   SERVICE, there is no shared bound join var, a join key is bound to a blank node,
///   or the left side is empty). The caller falls back to the verbatim SERVICE path.
/// * `Err(_)` — a non-SILENT remote failure (propagated, same as the verbatim path).
///
/// ## Why it preserves semantics
///
/// Injecting `VALUES (?j…) { (v…)… }` for the join variables restricts the remote
/// pattern to exactly the tuples `left` already binds (SPARQL 1.1 §10.2.1 inner-joins
/// the VALUES relation with the pattern). The remote therefore returns a SUBSET of
/// the unbound relation — precisely the rows that can survive the local join — and we
/// reattach them with the SAME `join_bindings` / `left_outer_join`. For a left-outer
/// join, a left row whose key has no remote match simply finds no compatible remote
/// row and survives unbound, identical to the verbatim path. SILENT is honoured: a
/// failed block degrades to the join identity (empty remote relation) so the
/// surrounding bindings are kept, exactly as the verbatim SILENT path does.
#[cfg(feature = "service")]
fn try_bound_join_service(
    graph: &Graph,
    local: &mut LocalVocab,
    left: &Bindings,
    right: &GraphPattern,
) -> Result<Option<Bindings>, String> {
    let GraphPattern::Service { name, inner, silent } = right else {
        return Ok(None);
    };
    let silent = *silent;

    // The endpoint is either a concrete IRI (the original bind-join) or a VARIABLE
    // (`SERVICE ?ep { … }`, bead sq-d4p). A variable endpoint is dispatched per
    // distinct endpoint IRI bound by `left`: see `bound_join_variable_endpoint`.
    let endpoint = match name {
        NamedNodePattern::NamedNode(n) => n.as_str().to_string(),
        NamedNodePattern::Variable(ep_var) => {
            return bound_join_variable_endpoint(graph, local, left, ep_var, inner, silent);
        }
    };

    bound_join_to_endpoint(graph, local, left, &endpoint, inner, silent)
}

/// Bind-join the SERVICE sub-`inner` against one CONCRETE `endpoint` over the `left`
/// bindings, returning the interned remote relation (see [`try_bound_join_service`] for
/// the contract). Factored out so the variable-endpoint path
/// ([`bound_join_variable_endpoint`]) can call it once per distinct endpoint IRI.
/// [OPUS-4.8] (sq-sjkj / sq-d4p)
#[cfg(feature = "service")]
fn bound_join_to_endpoint(
    graph: &Graph,
    local: &mut LocalVocab,
    left: &Bindings,
    endpoint: &str,
    inner: &GraphPattern,
    silent: bool,
) -> Result<Option<Bindings>, String> {
    // [OPUS-5] (sq-lsp7k.2.2) A locally-handled IRI never reaches the network, so there
    // is nothing to push a `VALUES` block AT. Decline, and the caller falls back to the
    // verbatim path — where `try_local_service` answers it and the outer join happens
    // locally. (This also covers `SERVICE ?ep` whose endpoint resolves to a handled
    // IRI: that endpoint's sub-join declines, which abandons the whole variable-endpoint
    // pushdown, matching the documented "concrete IRIs only" scope-out.)
    #[cfg(feature = "service-local")]
    if local_services::handles(endpoint) {
        return Ok(None);
    }
    // The remote pattern's in-scope variables; the join keys are the ones ALSO bound
    // by `left`. We must intersect with `left.vars` (textual) so the VALUES we push
    // names variables the remote pattern actually mentions.
    let mut inner_vars: Vec<Variable> = Vec::new();
    inner.on_in_scope_variable(|v| {
        if !inner_vars.contains(v) {
            inner_vars.push(v.clone());
        }
    });
    // Join keys: variables shared between the left relation and the remote pattern,
    // in `left`-column order (so we can read each left row's tuple positionally).
    let join_vars: Vec<Variable> = left
        .vars
        .iter()
        .filter(|v| inner_vars.contains(v))
        .cloned()
        .collect();
    if join_vars.is_empty() {
        // No bound join variable to push — the verbatim path is the correct (and only)
        // evaluation.
        return Ok(None);
    }
    if left.rows.is_empty() {
        // Nothing to push. An empty left makes the whole join empty anyway, but the
        // verbatim path also handles SILENT/error uniformly, so defer to it.
        return Ok(None);
    }

    // Column indices of the join vars in the left relation.
    let key_cols: Vec<usize> = join_vars.iter().map(|v| left.col(v).expect("join var is a left var")).collect();

    // Collect the DISTINCT, fully-bound, pushable join-key tuples from the left side.
    // A row with any unbound (`NO_ID`) join key, or a key bound to a non-pushable
    // term (blank node / triple term), means we cannot faithfully constrain the
    // remote — abandon the pushdown for the verbatim path to keep exact semantics.
    let mut seen: FxHashSet<Row> = FxHashSet::default();
    let mut tuples: Vec<Vec<Term>> = Vec::new();
    for row in &left.rows {
        let mut key: Row = SmallVec::new();
        for &c in &key_cols {
            key.push(row[c]);
        }
        if key.contains(&NO_ID) {
            return Ok(None); // an unbound join key — wildcard; cannot push.
        }
        if !seen.insert(key.clone()) {
            continue; // already pushed this tuple
        }
        let mut terms: Vec<Term> = Vec::with_capacity(key.len());
        for &id in &key {
            match term_of(graph, local, id) {
                Some(t) if sparq_engine_service::service::pushable_term(&t) => terms.push(t),
                _ => return Ok(None), // blank node / triple term / missing — fall back.
            }
        }
        tuples.push(terms);
    }
    if tuples.is_empty() {
        return Ok(None);
    }

    // Render the inner pattern once; each block re-uses it with a fresh VALUES head.
    let inner_sparql = format!("{inner}");
    let block = sparq_engine_service::service::bind_block_size();

    // Accumulate the union of the per-block remote relations, interning each row to the
    // id level AS IT ARRIVES from the streaming parser ([FABLE-5] sq-my8wd.4) — no
    // block's relation is ever held as owned `Term` rows. All blocks share the remote
    // `head.vars`, so we keep the first block's var list and concatenate rows
    // positionally: the same accumulation, and the same row order, as the previous
    // collect-then-intern path.
    let mut acc_vars: Option<Vec<Variable>> = None;
    let mut acc_rows: Vec<Row> = Vec::new();
    // [OPUS-4.8] (sq-my8wd.4) Savepoint the local vocab + byte budget BEFORE the first
    // block so a SILENT failure in ANY block can roll EVERY block's interns back out —
    // a SILENT failure discards all blocks' rows together (see the SILENT arm), so the
    // interns must all be rolled back too, or the discarded stream would retain memory
    // and charge `max_bytes`.
    let vocab_mark = local.savepoint();
    let byte_mark = budget::byte_savepoint();

    for chunk in tuples.chunks(block) {
        let values = sparq_engine_service::service::render_values_block(&join_vars, chunk);
        // Inject the VALUES inside the SELECT * group, alongside the inner pattern, so
        // the remote inner-joins the pushed bindings with its pattern.
        let query = format!("SELECT * WHERE {{ {values} {inner_sparql} }}");
        // [OPUS-4.8] (sq-my8wd.5) Use the reader seam here too: the bound-join path
        // fetches one block per VALUES chunk; each block's body is streamed, not buffered.
        let fetched = service_reader_transport::with(|t| {
            sparq_engine_service::service::eval_remote_into_read(t, endpoint, &query, &mut |row| {
                acc_rows.push(intern_remote_row(graph, local, &row));
                Ok(())
            })
        });
        match fetched {
            Ok(vars) => {
                if acc_vars.is_none() {
                    acc_vars = Some(vars);
                }
            }
            // SILENT: a failed block means the SERVICE as a whole must behave EXACTLY
            // as the verbatim single-request SILENT path — which yields the JOIN
            // IDENTITY (a single empty solution) so the surrounding bindings are KEPT
            // unchanged. We therefore discard any partial block results and hand the
            // caller the identity relation (one zero-column row); joining / left-outer
            // joining `left` with it leaves `left` exactly as it was. This matches the
            // unbound-then-local-join path's SILENT semantics precisely. [OPUS-4.8]
            // (Rows already interned from earlier blocks — or a partially-parsed
            // failing block — are ROLLED BACK out of the local vocab below, and their
            // byte-budget charge refunded, so no stray entry or `max_bytes` charge
            // survives the discard. [OPUS-4.8] sq-my8wd.4)
            Err(_) if silent => {
                acc_rows.clear();
                local.rollback_to(vocab_mark);
                budget::restore_bytes(byte_mark);
                return Ok(Some(Bindings::unsorted(Vec::new(), vec![Row::new()])));
            }
            Err(e) => return Err(e),
        }
    }

    // Vars: a non-empty `tuples` always produced at least one successful block above
    // (failures returned early), so `acc_vars` is set unless every block returned an
    // EMPTY result with no head — in which case the join vars are a safe head (the
    // relation has zero rows, so the var list only names columns that, being the join
    // keys, always exist on both sides). [OPUS-4.8]
    let vars = acc_vars.unwrap_or_else(|| join_vars.clone());
    Ok(Some(Bindings::unsorted(vars, acc_rows)))
}

/// Evaluate `SERVICE ?ep { inner }` — a VARIABLE endpoint — against the `left`
/// bindings, by dispatching one bind-join PER DISTINCT endpoint IRI that `left` binds
/// to `ep_var`. [OPUS-4.8] (sq-d4p)
///
/// SPARQL 1.1 federated query evaluates `SERVICE ?ep { P }` per in-scope solution μ:
/// substitute μ(?ep) for ?ep and evaluate `SERVICE μ(?ep) { P }`. The `left` relation
/// IS those in-scope solutions, so we partition `left` by its `?ep` binding and run the
/// existing bind-join ([`bound_join_to_endpoint`]) once per endpoint, then TAG every
/// remote row with `?ep = <that endpoint IRI>` so the surrounding join re-attaches the
/// remote rows to exactly the left rows that named that endpoint. The union of the
/// per-endpoint relations is the SERVICE result.
///
/// Returns:
/// * `Ok(Some(rel))` — the per-endpoint dispatch applied; `rel` carries `?ep` plus the
///   remote variables, ready for the caller's `join_bindings` / `left_outer_join`.
/// * `Ok(None)` — cannot dispatch (the endpoint variable is not bound by `left`, or the
///   bind-join declined for every endpoint — e.g. no shared join variable); the caller
///   falls back to the verbatim `eval_service`, which reports the documented
///   variable-endpoint error (or, under SILENT, the join identity).
/// * `Err(_)` — a non-SILENT remote failure (propagated).
///
/// A left row whose `?ep` is UNBOUND or not an IRI names no valid endpoint, so it
/// contributes no remote solution (it simply finds no `?ep`-tagged remote row to join
/// with) — matching per-solution `evalService`, where substituting a non-IRI yields no
/// federated answer for that solution.
#[cfg(feature = "service")]
fn bound_join_variable_endpoint(
    graph: &Graph,
    local: &mut LocalVocab,
    left: &Bindings,
    ep_var: &Variable,
    inner: &GraphPattern,
    silent: bool,
) -> Result<Option<Bindings>, String> {
    // The endpoint variable must be a left column (bound by the surrounding query);
    // otherwise there is nothing to dispatch on — defer to the verbatim path.
    let Some(ep_col) = left.col(ep_var) else {
        return Ok(None);
    };
    if left.rows.is_empty() {
        return Ok(None);
    }

    // Partition the left rows by their endpoint id, preserving first-seen order so the
    // dispatch (and the resulting row order) is deterministic. A row whose `?ep` is
    // unbound or a non-IRI term is dropped from dispatch (it names no endpoint).
    let mut order: Vec<Id> = Vec::new();
    let mut groups: FxHashMap<Id, Vec<Row>> = FxHashMap::default();
    for row in &left.rows {
        let id = row[ep_col];
        if id == NO_ID {
            continue; // unbound endpoint — no remote call for this solution.
        }
        match term_of(graph, local, id) {
            Some(Term::NamedNode(_)) => {}
            _ => continue, // a non-IRI ?ep is not a valid endpoint — skip.
        }
        // The sub-left for an endpoint reuses the FULL left layout (same `vars`), so the
        // recursive bind-join reads join-key columns positionally exactly as before.
        groups
            .entry(id)
            .or_insert_with(|| {
                order.push(id);
                Vec::new()
            })
            .push(row.clone());
    }
    if order.is_empty() {
        // No left row binds `?ep` to a concrete endpoint IRI: nothing to dispatch, and
        // (for an inner join) the result is empty. Defer to the verbatim path so SILENT
        // vs error is decided uniformly.
        return Ok(None);
    }

    // [OPUS-4.8] (sq-b93pv) PRE-DISPATCH remote-request cap. `order` is the set of
    // DISTINCT endpoint IRIs this `SERVICE ?ep` would dial — known now, before any
    // socket is opened — so a high-cardinality `?ep` (an endpoint var bound to many
    // distinct IRIs) is BOUNDED HERE rather than after the requests have gone out. The
    // refusal is a hard, typed error (the `SERVICE_REMOTE_CAP_MARKER` substring) and is
    // NOT swallowed by SILENT: SILENT masks an endpoint being unreachable, not a
    // deliberate resource-policy refusal (the same stance `budget::check` takes). When no
    // cap is installed (the default) this is a single thread-local read and a no-op.
    if let Some(cap) = sparq_engine_service::service::remote_request_cap() {
        if order.len() > cap {
            return Err(format!(
                "{}: SERVICE ?{} would dispatch to {} distinct endpoints (cap {})",
                sparq_engine_service::service::SERVICE_REMOTE_CAP_MARKER,
                ep_var.as_str(),
                order.len(),
                cap,
            ));
        }
    }

    // Resolve the endpoint IRI strings once (id -> "http://…").
    let mut acc_vars: Vec<Variable> = vec![ep_var.clone()];
    let mut acc_rows: Vec<Row> = Vec::new();
    // Whether at least one endpoint's bind-join actually applied. If EVERY endpoint
    // declined (e.g. no shared join var), there is no faithful pushdown — defer wholly
    // to the verbatim path rather than returning a partial/empty result.
    let mut any_applied = false;

    for id in order {
        let sub_rows = groups.remove(&id).expect("group for ordered id");
        let endpoint = match term_of(graph, local, id) {
            Some(Term::NamedNode(n)) => n.into_string(),
            _ => continue, // unreachable: filtered above.
        };
        let sub_left = Bindings::unsorted(left.vars.clone(), sub_rows);
        let Some(rel) = bound_join_to_endpoint(graph, local, &sub_left, &endpoint, inner, silent)?
        else {
            // This endpoint's sub-join declined the pushdown (no shared join var, an
            // unbound/blank join key, …). For correctness we cannot mix a pushed
            // endpoint with a verbatim one, so abandon the whole variable-endpoint
            // pushdown and let the verbatim path handle it.
            return Ok(None);
        };
        any_applied = true;
        // Tag every remote row with `?ep = <endpoint>` (its first column) and align the
        // remaining columns to the accumulated header, extending `acc_vars` with any new
        // remote variable as it first appears.
        for v in &rel.vars {
            if !acc_vars.contains(v) {
                acc_vars.push(v.clone());
            }
        }
        // Column index of each accumulated var within THIS endpoint's relation (skip
        // `?ep`, which the remote relation does not carry).
        let src_col: Vec<Option<usize>> = acc_vars
            .iter()
            .map(|v| if v == ep_var { None } else { rel.col(v) })
            .collect();
        for r in &rel.rows {
            let mut out: Row = SmallVec::with_capacity(acc_vars.len());
            for (i, c) in src_col.iter().enumerate() {
                if i == 0 {
                    out.push(id); // the `?ep` column.
                } else {
                    out.push(c.map(|j| r[j]).unwrap_or(NO_ID));
                }
            }
            acc_rows.push(out);
        }
    }

    if !any_applied {
        return Ok(None);
    }

    // Normalise every row to the final header width (a later endpoint may have added a
    // variable absent from an earlier one; those earlier rows get `NO_ID` in the new
    // column).
    let width = acc_vars.len();
    for r in &mut acc_rows {
        while r.len() < width {
            r.push(NO_ID);
        }
    }
    Ok(Some(Bindings::unsorted(acc_vars, acc_rows)))
}

/// Test/embedder seam for the SERVICE HTTP transport. By default `with` runs the
/// closure against the production `sparq_engine_service::service::HttpTransport`; tests install a
/// fake (loopback / canned) transport for the duration of a scope so SERVICE can be
/// exercised without a public-network dependency. [OPUS-4.8]
#[cfg(feature = "service")]
pub(crate) mod service_transport {
    use sparq_engine_service::service::Transport;
    use std::cell::RefCell;

    thread_local! {
        // A boxed trait object so a test can install any `Transport`. `None` => use
        // the real HTTP client.
        static ACTIVE: RefCell<Option<Box<dyn Transport>>> = const { RefCell::new(None) };
    }

    /// RAII install of a test transport; restores the previous value on drop.
    pub(crate) struct Guard(Option<Box<dyn Transport>>);
    impl Drop for Guard {
        fn drop(&mut self) {
            ACTIVE.with(|a| *a.borrow_mut() = self.0.take());
        }
    }

    /// Install a transport for the current thread/scope (used by tests).
    #[cfg_attr(not(test), allow(dead_code))]
    pub(crate) fn install(t: Box<dyn Transport>) -> Guard {
        Guard(ACTIVE.with(|a| a.borrow_mut().replace(t)))
    }

    /// Run `f` with the optional installed test transport (`None` = no override, use
    /// the production HTTP client). Used by `service_reader_transport` to share the
    /// same `ACTIVE` cell without re-exposing its private `RefCell`. [OPUS-4.8]
    pub(crate) fn with_opt<R>(f: impl FnOnce(Option<&dyn Transport>) -> R) -> R {
        ACTIVE.with(|a| f(a.borrow().as_deref()))
    }
}

/// Reader-seam transport dispatcher: analogous to `service_transport` but uses the
/// `ReaderTransport` seam so the HTTP body is NEVER buffered into a full `String`.
/// (bead sq-my8wd.5) [OPUS-4.8]
///
/// When a test `Transport` is installed via `service_transport::install`, it is
/// wrapped in `TransportAsReader` so it satisfies `ReaderTransport` — tests continue
/// to work unchanged. The production path (`None` installed) uses `HttpTransport`
/// directly as `ReaderTransport`, which streams the body via ureq's `into_reader()`.
#[cfg(feature = "service")]
pub(crate) mod service_reader_transport {
    use sparq_engine_service::service::{ReaderTransport, TransportAsReader};

    /// Run `f` with the active reader transport — wrapping any installed test
    /// `Transport` as a `ReaderTransport`, or using `HttpTransport` directly.
    pub(crate) fn with<R>(f: impl FnOnce(&dyn ReaderTransport) -> R) -> R {
        super::service_transport::with_opt(|opt| match opt {
            Some(t) => f(&TransportAsReader(t)),
            None => {
                #[cfg(not(target_arch = "wasm32"))]
                {
                    f(&sparq_engine_service::service::HttpTransport::with_budget(
                        super::budget::remaining_timeout(),
                    ))
                }
                #[cfg(target_arch = "wasm32")]
                {
                    let _ = f;
                    unreachable!("SERVICE has no HTTP transport on wasm")
                }
            }
        })
    }
}

pub(crate) fn is_conjunctive(p: &GraphPattern) -> bool {
    match p {
        GraphPattern::Bgp { .. } => true,
        // A FILTER may only be flattened into the enclosing conjunction when every
        // variable it mentions is bound INSIDE its own group — otherwise hoisting it
        // changes scope (`{ :x :p ?v . { FILTER(?v = 1) } }` must see ?v UNBOUND).
        // EXISTS is conservatively never flattened (it evaluates against the group's
        // in-scope bindings).
        GraphPattern::Filter { inner, expr } => {
            if !is_conjunctive(inner) {
                return false;
            }
            let mut inner_vars: FxHashSet<Variable> = FxHashSet::default();
            collect_pattern_vars(inner, &mut inner_vars);
            filter_scope_ok(expr, &inner_vars)
        }
        GraphPattern::Join { left, right } => is_conjunctive(left) && is_conjunctive(right),
        _ => false,
    }
}

/// All variables bound by the triple patterns of a conjunctive subtree.
fn collect_pattern_vars(p: &GraphPattern, out: &mut FxHashSet<Variable>) {
    match p {
        GraphPattern::Bgp { patterns } => {
            for tp in patterns {
                for v in [tp_var(&tp.subject), nnp_var(&tp.predicate), tp_var(&tp.object)].into_iter().flatten() {
                    out.insert(v);
                }
            }
        }
        GraphPattern::Filter { inner, .. } => collect_pattern_vars(inner, out),
        GraphPattern::Join { left, right } => {
            collect_pattern_vars(left, out);
            collect_pattern_vars(right, out);
        }
        _ => {}
    }
}

/// `true` if a filter expression's variables are all in `bound` (and it has no
/// EXISTS), so applying it at the top of the flattened conjunction is equivalent.
fn filter_scope_ok(e: &Expression, bound: &FxHashSet<Variable>) -> bool {
    use Expression::*;
    match e {
        NamedNode(_) | Literal(_) => true,
        Variable(v) | Bound(v) => bound.contains(v),
        UnaryPlus(a) | UnaryMinus(a) | Not(a) => filter_scope_ok(a, bound),
        And(a, b) | Or(a, b) | Equal(a, b) | SameTerm(a, b) | Greater(a, b) | GreaterOrEqual(a, b) | Less(a, b)
        | LessOrEqual(a, b) | Add(a, b) | Subtract(a, b) | Multiply(a, b) | Divide(a, b) => {
            filter_scope_ok(a, bound) && filter_scope_ok(b, bound)
        }
        In(a, list) => filter_scope_ok(a, bound) && list.iter().all(|c| filter_scope_ok(c, bound)),
        If(c, t, f) => filter_scope_ok(c, bound) && filter_scope_ok(t, bound) && filter_scope_ok(f, bound),
        Coalesce(es) => es.iter().all(|c| filter_scope_ok(c, bound)),
        FunctionCall(_, args) => args.iter().all(|c| filter_scope_ok(c, bound)),
        Exists(_) => false,
    }
}

pub(crate) fn flatten_conjunction(p: &GraphPattern, patterns: &mut Vec<TriplePattern>, filters: &mut Vec<Expression>) {
    match p {
        GraphPattern::Bgp { patterns: tps } => patterns.extend(tps.iter().cloned()),
        GraphPattern::Join { left, right } => {
            flatten_conjunction(left, patterns, filters);
            flatten_conjunction(right, patterns, filters);
        }
        GraphPattern::Filter { expr, inner } => {
            flatten_conjunction(inner, patterns, filters);
            filters.push(expr.clone());
        }
        _ => unreachable!(),
    }
}

// ---- Sargable numeric filters (pushed into the scan) -------------------------

/// A numeric comparison `value OP threshold` that can be pushed down into a
/// pattern scan (FILTER predicate evaluated inline, in the column's sorted order,
/// so the numeric access is sequential rather than a random dictionary gather —
/// the layout fix the hardware research measured as an 8–15× win).
#[derive(Clone, Copy)]
pub(crate) enum NumCmp {
    Gt(f64),
    Ge(f64),
    Lt(f64),
    Le(f64),
    Eq(f64),
}

impl NumCmp {
    /// Human-readable comparison for EXPLAIN output, e.g. `> 28`.
    pub(crate) fn render(&self) -> String {
        match *self {
            NumCmp::Gt(t) => format!("> {t}"),
            NumCmp::Ge(t) => format!(">= {t}"),
            NumCmp::Lt(t) => format!("< {t}"),
            NumCmp::Le(t) => format!("<= {t}"),
            NumCmp::Eq(t) => format!("= {t}"),
        }
    }

    #[inline]
    fn test(&self, x: f64) -> bool {
        match *self {
            NumCmp::Gt(t) => x > t,
            NumCmp::Ge(t) => x >= t,
            NumCmp::Lt(t) => x < t,
            NumCmp::Le(t) => x <= t,
            NumCmp::Eq(t) => x == t,
        }
    }
}

/// A comparison operator, for the temporal pushed-down predicate.
#[derive(Clone, Copy)]
pub(crate) enum CmpOp {
    Gt,
    Ge,
    Lt,
    Le,
    Eq,
}

impl CmpOp {
    #[inline]
    fn eval(self, o: Ordering) -> bool {
        match self {
            CmpOp::Gt => o == Ordering::Greater,
            CmpOp::Ge => o != Ordering::Less,
            CmpOp::Lt => o == Ordering::Less,
            CmpOp::Le => o != Ordering::Greater,
            CmpOp::Eq => o == Ordering::Equal,
        }
    }

    fn render(self) -> &'static str {
        match self {
            CmpOp::Gt => ">",
            CmpOp::Ge => ">=",
            CmpOp::Lt => "<",
            CmpOp::Le => "<=",
            CmpOp::Eq => "=",
        }
    }
}

/// A sargable FILTER predicate pushed down into a pattern scan: numeric (via the f64
/// `numerics` cache) or temporal (via the `temporals` cache — dateTime/date vs a
/// temporal constant).
#[derive(Clone, Copy)]
pub(crate) enum ScanCmp {
    Num(NumCmp),
    /// `value OP temporal-constant`. A row passes when the comparison is DECIDABLE and
    /// satisfies the operator; an indeterminate (mixed-timezone window), cross-family
    /// (dateTime vs date) or non-temporal operand is a FILTER type error — the row is
    /// excluded, which `false` reproduces exactly. (For `=`, cross-family is "known
    /// different" rather than an error — also excluded, also `false`.)
    Temp(CmpOp, Temporal),
}

impl ScanCmp {
    /// Human-readable comparison for EXPLAIN output, e.g. `> 28`.
    pub(crate) fn render(&self) -> String {
        match *self {
            ScanCmp::Num(c) => c.render(),
            ScanCmp::Temp(op, t) => format!("{} temporal(instant {})", op.render(), t.instant),
        }
    }

    /// Evaluates the pushed-down predicate against one scanned column id, through the
    /// graph's numeric / temporal value cache — O(1), no term materialised.
    #[inline]
    fn test_id(&self, graph: &Graph, id: Id) -> bool {
        match *self {
            ScanCmp::Num(c) => graph.numeric_value(id).is_some_and(|x| c.test(x)),
            ScanCmp::Temp(op, t) => {
                graph.temporal_value(id).and_then(|v| Temporal::cmp_t(v, t)).is_some_and(|o| op.eval(o))
            }
        }
    }
}

/// The inclusive range of inline-integer *values* `[lo, hi]` (within `[0, INLINE_MAX]`)
/// that satisfy the comparison, or `None` if no integer can. Used to range-prune a
/// scan whose filter column holds inline integers (which sort by value). A TEMPORAL
/// predicate over an all-inline (integer) column is a type error on every row —
/// `None`, the empty range.
fn inline_pass_values(cmp: ScanCmp) -> Option<(u32, u32)> {
    let cmp = match cmp {
        ScanCmp::Num(c) => c,
        ScanCmp::Temp(..) => return None,
    };
    let max = (dict::INLINE_BASE - 1) as i64;
    let (lo, hi): (i64, i64) = match cmp {
        NumCmp::Gt(t) => (t.floor() as i64 + 1, max),
        NumCmp::Ge(t) => (t.ceil() as i64, max),
        NumCmp::Lt(t) => (0, t.ceil() as i64 - 1),
        NumCmp::Le(t) => (0, t.floor() as i64),
        NumCmp::Eq(t) => {
            if t.fract() != 0.0 || t < 0.0 || t > max as f64 {
                return None;
            }
            let v = t as i64;
            (v, v)
        }
    };
    let (lo, hi) = (lo.max(0), hi.min(max));
    (lo <= hi).then_some((lo as u32, hi as u32))
}

/// Recognises a FILTER of the form `?v OP constant` (or the symmetric
/// `constant OP ?v`) over a numeric or temporal constant, returning the variable
/// and the comparison to push down.
///
/// [OPUS-4.8] (sq-lr2ii) A NUMERIC comparison is DECLINED (returns `None`) when the graph
/// holds an f64-inexact decimal ([`Graph::has_high_precision_decimal`]): the f64 `numerics`
/// cache the scan probes could then decide `=`/`<`/`>`/`<=`/`>=` wrongly for that value (e.g.
/// `"1.000000000000000001"^^xsd:decimal` collapses onto the f64 `1.0`), so such comparisons
/// fall back to the exact general evaluator instead. Temporal pushdown is unaffected, and a
/// graph with no f64-inexact decimal keeps the numeric fast path.
fn extract_sargable(graph: &Graph, e: &Expression) -> Option<(Variable, ScanCmp)> {
    fn lit_num(e: &Expression) -> Option<f64> {
        match e {
            Expression::Literal(l) if is_numeric_dt(l) => {
                // [FABLE-5] sq-6b1lj: datatype-aware/trimmed constant (`numeric_cache_f64`).
                // A datatype-ill-formed threshold (`"1.5"^^xsd:integer`) yields `None`, so
                // `extract_sargable` DECLINES the numeric fast path and the FILTER takes the
                // exact general comparison — which type-errors the ill-formed constant,
                // matching the reference semantics (a sargable f64 threshold would instead
                // compare against it, over-including).
                let v: f64 = numeric_cache_f64(l)?;
                // A threshold f64 can't represent precisely (> 15 significant digits —
                // large integers or high-precision decimals) makes the sargable f64 scan
                // unsafe; decline so the filter takes the exact general comparison path.
                if sig_digits(l.value()) > 15 {
                    None
                } else {
                    Some(v)
                }
            }
            _ => None,
        }
    }
    // A well-formed dateTime/dateTimeStamp/date constant: its cached-comparable value.
    // (The runtime compare through the cache is bit-identical to the per-row parse, so
    // no precision guard is needed — unlike the f64 numeric threshold above.)
    fn lit_temp(e: &Expression) -> Option<Temporal> {
        match e {
            Expression::Literal(l) => temporal_of_lit(l),
            _ => None,
        }
    }
    fn var_of(e: &Expression) -> Option<Variable> {
        match e {
            Expression::Variable(v) => Some(v.clone()),
            _ => None,
        }
    }
    // (left, right, op-if-var-on-left, op-if-var-on-right)
    let (l, r, on_left, on_right): (&Expression, &Expression, CmpOp, CmpOp) = match e {
        Expression::Greater(l, r) => (l, r, CmpOp::Gt, CmpOp::Lt),
        Expression::GreaterOrEqual(l, r) => (l, r, CmpOp::Ge, CmpOp::Le),
        Expression::Less(l, r) => (l, r, CmpOp::Lt, CmpOp::Gt),
        Expression::LessOrEqual(l, r) => (l, r, CmpOp::Le, CmpOp::Ge),
        Expression::Equal(l, r) => (l, r, CmpOp::Eq, CmpOp::Eq),
        _ => return None,
    };
    let num_cmp = |op: CmpOp, t: f64| -> ScanCmp {
        ScanCmp::Num(match op {
            CmpOp::Gt => NumCmp::Gt(t),
            CmpOp::Ge => NumCmp::Ge(t),
            CmpOp::Lt => NumCmp::Lt(t),
            CmpOp::Le => NumCmp::Le(t),
            CmpOp::Eq => NumCmp::Eq(t),
        })
    };
    for (var, konst, op) in [(l, r, on_left), (r, l, on_right)] {
        let Some(v) = var_of(var) else { continue };
        if let Some(c) = lit_num(konst) {
            // sq-lr2ii: decline the f64 numeric fast path when the graph holds an f64-inexact
            // decimal — the scan's per-row f64 compare could be wrong for it. A numeric
            // constant is never also a temporal one, so declining here yields `None` for this
            // orientation; the exact general evaluator handles the residual FILTER correctly.
            if !graph.has_high_precision_decimal() {
                return Some((v, num_cmp(op, c)));
            }
            continue;
        }
        if let Some(t) = lit_temp(konst) {
            return Some((v, ScanCmp::Temp(op, t)));
        }
    }
    None
}

/// The canonical position (0=subject, 1=predicate, 2=object) of a variable in a
/// triple pattern, if it occurs there.
fn pattern_var_pos(tp: &TriplePattern, var: &Variable) -> Option<usize> {
    if matches!(&tp.subject, TermPattern::Variable(v) if v == var) {
        return Some(0);
    }
    if matches!(&tp.predicate, NamedNodePattern::Variable(v) if v == var) {
        return Some(1);
    }
    if matches!(&tp.object, TermPattern::Variable(v) if v == var) {
        return Some(2);
    }
    None
}

/// Splits FILTERs into per-pattern sargable numeric predicates (pushed into the
/// scan of the first pattern that binds the variable) and the residual filters
/// (applied normally afterwards).
pub(crate) fn split_sargable(graph: &Graph, patterns: &[TriplePattern], filters: &[Expression]) -> (Vec<Option<(usize, ScanCmp)>>, Vec<Expression>) {
    // zk-trace: a sargable FILTER pushed into the scan would make the scan
    // record only the POST-filter rows (the rows that PASSED), losing the
    // FILTER obligation and under-capturing the input set — the proof must
    // witness the operand of every filtered row and the rows it excluded.
    // Keep every filter residual while recording, so it flows through
    // apply_filter (one FilterObligation) over the FULL unfiltered scan set.
    // Result-equivalent; only the plan changes (zk module docs).
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        return (vec![None; patterns.len()], filters.to_vec());
    }
    let mut pat_filters: Vec<Option<(usize, ScanCmp)>> = vec![None; patterns.len()];
    let mut residual = Vec::new();
    for f in filters {
        if let Some((var, cmp)) = extract_sargable(graph, f) {
            if let Some((i, pos)) = patterns
                .iter()
                .enumerate()
                .find_map(|(i, tp)| pattern_var_pos(tp, &var).filter(|_| pat_filters[i].is_none()).map(|pos| (i, pos)))
            {
                pat_filters[i] = Some((pos, cmp));
                continue;
            }
        }
        residual.push(f.clone());
    }
    (pat_filters, residual)
}

// ---- Spatial FILTER pushdown (sq-mg9) ------------------------------------------
//
// Recognise a `geof:` spatial FILTER over an indexed geometry variable and, when a
// SpatialProvider is installed, pre-restrict the bindings to the index's candidate
// SUPERSET before the exact `geof:` refinement runs in `apply_filter`. The engine
// stays geometry-free: it only lifts the geometry variable and the CONSTANT operands
// out of the algebra and forwards them to the provider; all geometry math is the
// provider's (sparq-geo's). Correctness is by construction — the candidate set is a
// superset, the residual `geof:` FILTER is NOT removed, so the result is identical to
// the post-hoc path. [OPUS-4.8]

/// The geof: IRIs the planner can push down. (The engine cannot depend on
/// sparq-geo's `vocab`, so the IRIs are mirrored here; they are W3C-fixed.)
const GEOF_DISTANCE: &str = "http://www.opengis.net/def/function/geosparql/distance";
const GEOF_SF_WITHIN: &str = "http://www.opengis.net/def/function/geosparql/sfWithin";
const GEOF_SF_INTERSECTS: &str = "http://www.opengis.net/def/function/geosparql/sfIntersects";
#[cfg(feature = "spatial-exact-pushdown")]
const GEOF_SF_CONTAINS: &str = "http://www.opengis.net/def/function/geosparql/sfContains";

/// A recognised pushable spatial FILTER: the geometry variable to restrict, plus an
/// OWNED description of the index query (so it outlives the borrowed algebra). The
/// `SpatialQuery` handed to the provider borrows from the owned strings here.
struct SpatialPushdown {
    geo_var: Variable,
    kind: SpatialKind,
}

enum SpatialKind {
    DistanceWithin { point_wkt: String, radius: f64, unit_iri: String, inclusive: bool },
    BboxIntersects {
        arg_wkt: String,
        /// [FABLE-5] (sq-lk3aw.4) `true` iff the recognised FILTER is the
        /// WITHIN-REGION orientation — `geof:sfWithin(?g, REGION)` or its Simple
        /// Features converse `geof:sfContains(REGION, ?g)` — the one predicate an
        /// installed provider may certify EXACTLY via
        /// [`SpatialProvider::candidates_exact`](crate::SpatialProvider::candidates_exact).
        /// `false` (sfIntersects) keeps the superset + residual-FILTER path.
        #[cfg(feature = "spatial-exact-pushdown")]
        within_region: bool,
    },
}

/// The `geo:wktLiteral` lexical form of a constant operand, if it is one. (The engine
/// does not validate the WKT — the provider parses it and declines on failure.)
fn wkt_const(e: &Expression) -> Option<&str> {
    const WKT_LITERAL: &str = "http://www.opengis.net/ont/geosparql#wktLiteral";
    match e {
        Expression::Literal(l) if l.datatype().as_str() == WKT_LITERAL => Some(l.value()),
        _ => None,
    }
}

/// A `geof:distance(?g, point[, unit])` call → `(geo_var, point_wkt, unit_iri)`, with
/// `?g` the geometry variable and the OTHER geometry operand a constant wktLiteral. The
/// unit defaults to metre when omitted (GeoSPARQL `geof:distance` is arity-3, but be
/// lenient). Symmetric in the two geometry args.
fn match_geof_distance(args: &[Expression]) -> Option<(Variable, String, String)> {
    const UOM_METRE: &str = "http://www.opengis.net/def/uom/OGC/1.0/metre";
    if args.len() != 2 && args.len() != 3 {
        return None;
    }
    let unit = if args.len() == 3 {
        match &args[2] {
            Expression::NamedNode(nn) => nn.as_str().to_string(),
            _ => return None,
        }
    } else {
        UOM_METRE.to_string()
    };
    let var_of = |e: &Expression| match e {
        Expression::Variable(v) => Some(v.clone()),
        _ => None,
    };
    // (?g, point) or (point, ?g): the geometry var on either side.
    for (a, b) in [(&args[0], &args[1]), (&args[1], &args[0])] {
        if let (Some(v), Some(pt)) = (var_of(a), wkt_const(b)) {
            return Some((v, pt.to_string(), unit));
        }
    }
    None
}

/// Recognises a pushable spatial FILTER. Two shapes:
///
/// * `geof:distance(?g, point, unit) OP radius` with `OP ∈ {<, <=}` (the bound on the
///   non-constant side) → a distance-within window;
/// * `geof:sfWithin(?g, box)` / `geof:sfIntersects(?g, box)` used directly as the FILTER
///   → a bbox/window scan.
///
/// `geof:sfContains/Overlaps/Touches/Crosses/Equals/Disjoint` and distance with `>`/`>=`
/// (an unbounded EXTERIOR, no finite window) stay post-hoc — see the report.
fn recognise_spatial(e: &Expression) -> Option<SpatialPushdown> {
    use spargebra::algebra::Function;
    // distance(...) OP radius — match the comparison, then the distance call inside.
    let distance_cmp = |call: &Expression, radius: &Expression, inclusive: bool| -> Option<SpatialPushdown> {
        let Expression::FunctionCall(Function::Custom(nn), cargs) = call else { return None };
        if nn.as_str() != GEOF_DISTANCE {
            return None;
        }
        let r = match radius {
            Expression::Literal(l) => l.value().parse::<f64>().ok()?,
            _ => return None,
        };
        if !r.is_finite() || r < 0.0 {
            return None;
        }
        let (geo_var, point_wkt, unit_iri) = match_geof_distance(cargs)?;
        Some(SpatialPushdown { geo_var, kind: SpatialKind::DistanceWithin { point_wkt, radius: r, unit_iri, inclusive } })
    };
    match e {
        // A finite within-window needs distance on the SMALLER side: `distance(...) < r`
        // or the mirror `r > distance(...)`. The opposite orientation (`r < distance` /
        // `distance > r`) is an unbounded EXTERIOR — NOT pushable — so each arm matches
        // exactly ONE operand orientation (asymmetric on purpose; the earlier symmetric
        // `.or_else` wrongly recognised the exterior as a within-window). [OPUS-4.8]
        Expression::Less(l, r) => distance_cmp(l, r, false), // distance(...) < r
        Expression::LessOrEqual(l, r) => distance_cmp(l, r, true), // distance(...) <= r
        Expression::Greater(l, r) => distance_cmp(r, l, false), // r > distance(...)
        Expression::GreaterOrEqual(l, r) => distance_cmp(r, l, true), // r >= distance(...)
        // geof:sfWithin(?g, box) / geof:sfIntersects(?g, box) as the whole FILTER.
        Expression::FunctionCall(Function::Custom(nn), cargs) => {
            let iri = nn.as_str();
            if (iri == GEOF_SF_WITHIN || iri == GEOF_SF_INTERSECTS) && cargs.len() == 2 {
                if let (Expression::Variable(v), Some(arg)) = (&cargs[0], wkt_const(&cargs[1])) {
                    return Some(SpatialPushdown {
                        geo_var: v.clone(),
                        kind: SpatialKind::BboxIntersects {
                            arg_wkt: arg.to_string(),
                            #[cfg(feature = "spatial-exact-pushdown")]
                            within_region: iri == GEOF_SF_WITHIN,
                        },
                    });
                }
            }
            // [FABLE-5] (sq-lk3aw.4) `geof:sfContains(REGION, ?g)` — the constant-region-
            // FIRST operand order. Simple Features defines `contains(a, b) ⇔ within(b, a)`,
            // so this is the SAME within-region pushdown as `sfWithin(?g, REGION)` with the
            // operands swapped: `within(?g, REGION) ⟹ intersects(?g, REGION) ⟹ their AABBs
            // intersect`, hence the bbox candidate superset is valid for it too. Previously
            // this orientation was never recognised and never pushed down at all.
            #[cfg(feature = "spatial-exact-pushdown")]
            if iri == GEOF_SF_CONTAINS && cargs.len() == 2 {
                if let (Some(arg), Expression::Variable(v)) = (wkt_const(&cargs[0]), &cargs[1]) {
                    return Some(SpatialPushdown {
                        geo_var: v.clone(),
                        kind: SpatialKind::BboxIntersects {
                            arg_wkt: arg.to_string(),
                            within_region: true,
                        },
                    });
                }
            }
            None
        }
        _ => None,
    }
}

/// If `b` binds the recognised geometry variable, restrict its rows to the provider's
/// candidate superset over that variable, in place. Returns `true` when the pushdown
/// fired (an index was installed AND served candidates) so the caller knows the residual
/// FILTER still refines a SMALLER input set. A miss (no index, declined, or unbound var)
/// is a no-op returning `false` — the residual FILTER then scans every row, unchanged.
fn apply_spatial_pushdown(graph: &Graph, b: &mut Bindings, pd: &SpatialPushdown) -> bool {
    use crate::SpatialQuery;
    let Some(col) = b.col(&pd.geo_var) else { return false };
    let Some(idx) = spatial::active() else { return false };
    let query = match &pd.kind {
        SpatialKind::DistanceWithin { point_wkt, radius, unit_iri, inclusive } => {
            SpatialQuery::DistanceWithin { point_wkt, radius: *radius, unit_iri, inclusive: *inclusive }
        }
        SpatialKind::BboxIntersects { arg_wkt, .. } => SpatialQuery::BboxIntersects { arg_wkt },
    };
    let Some(cands) = idx.candidates(&query) else { return false };
    // Map the candidate TERMS to dictionary ids for an O(1) membership test on the
    // scanned column. A candidate term absent from the dict can never bind here, so
    // dropping it from the id-set is safe (and keeps the set a superset of the matches).
    let cand_ids: FxHashSet<Id> = cands.iter().filter_map(|t| graph.id_of(t)).collect();
    // The keep predicate (both branches below are IDENTICAL): keep a row when its
    // binding is a candidate (an indexed match) OR the index has NO opinion on it (NOT
    // indexed — e.g. bound via a non-`geo:asWKT` predicate, a non-geographic CRS, or a
    // different graph). The residual `geof:` FILTER then judges every kept row, so a
    // geometry the index never saw is NEVER silently dropped. This makes the result
    // identical to the post-hoc path no matter which subset the index covers.
    //
    // FAST PATH: when the provider can give the ID-LEVEL indexed universe resolved
    // against THIS graph's dict (freshness matched), `is_indexed(id)` is a pure
    // `FxHashSet<Id>` lookup — ZERO per-row `Term` materialisation. `indexed.contains(&id)`
    // equals `is_indexed(&graph.dict.term(id))` by the provider's contract, so the verdict
    // is unchanged. [OPUS-4.8]
    let dict_ptr = std::ptr::from_ref(&graph.dict) as usize;
    if let Some(indexed) = idx.indexed_ids(dict_ptr) {
        b.rows.retain(|row| {
            let id = row[col];
            // candidate (indexed match) OR not in the indexed universe -> keep.
            cand_ids.contains(&id) || !indexed.contains(&id)
        });
        return true;
    }
    // SLOW FALLBACK (no fresh id-level universe): memoise the per-id not-indexed check to
    // avoid re-materialising a term per row. Produces the SAME keep verdict as the fast path.
    let mut verdict: FxHashMap<Id, bool> = FxHashMap::default();
    b.rows.retain(|row| {
        let id = row[col];
        if cand_ids.contains(&id) {
            return true; // an indexed candidate (kept; exact FILTER refines)
        }
        *verdict.entry(id).or_insert_with(|| {
            // Keep iff the index is NOT authoritative over this binding.
            match term_of_id(graph, id) {
                Some(t) => !idx.is_indexed(&t),
                None => true, // no term (synthetic / unbound) — index can't rule it out
            }
        })
    });
    true
}

/// [FABLE-5] (sq-lk3aw.4) Outcome of the EXACT-candidate spatial pushdown attempt.
#[cfg(feature = "spatial-exact-pushdown")]
enum ExactPushdown {
    /// No exact certification happened (not the within-region shape, no provider,
    /// unbound variable, or the provider declined): NOTHING was touched — the caller
    /// runs the superset pushdown + residual FILTER exactly as before.
    Declined,
    /// Rows were restricted to `certified-exact ∪ not-indexed`, but at least one
    /// surviving row's binding is NOT certified (outside the indexed universe): the
    /// residual FILTER MUST still run — it is an identity on the certified rows and
    /// the SOLE judge of the not-indexed ones.
    Partial,
    /// Every surviving row's binding is in the provider's certified-exact set: the
    /// residual FILTER is provably an identity and may be skipped.
    AllCertified,
}

/// [FABLE-5] (sq-lk3aw.4) EXACT-candidate spatial pushdown: for a recognised
/// WITHIN-REGION FILTER (`geof:sfWithin(?g, REGION)` / `geof:sfContains(REGION, ?g)`),
/// restrict `b`'s rows to the provider's CERTIFIED-EXACT answer set (keeping every
/// not-indexed binding) and report whether the residual `geof:` FILTER may be skipped.
///
/// EXACTNESS / SOUNDNESS ARGUMENT — why skipping the residual FILTER is safe, and
/// ONLY on [`ExactPushdown::AllCertified`]:
///
/// * [`SpatialProvider::candidates_exact`](crate::SpatialProvider::candidates_exact)
///   returning `Some(v)` CERTIFIES that `v` is EXACTLY the set of INDEXED geometry
///   bindings for which the recognised predicate evaluates to `true` — no false
///   positives and no false negatives, but ONLY over the indexed universe
///   ([`SpatialProvider::is_indexed`](crate::SpatialProvider::is_indexed)). The
///   certificate says NOTHING about a binding the index never saw.
/// * The retain below keeps a row iff its binding is (a) in the certified set — an
///   indexed TRUE row the residual FILTER would also keep — or (b) NOT indexed — a
///   row the certificate does not cover, kept for the residual FILTER to judge,
///   exactly as the superset path keeps it. An indexed row NOT in the certified set
///   is an indexed FALSE row the residual FILTER would drop: dropping it here is the
///   same verdict, taken earlier.
/// * If every surviving row entered via (a), the residual FILTER would keep each of
///   them (all certified TRUE), so running it cannot change the multiset — it is an
///   IDENTITY and skipping it is result-identical (`AllCertified`). This includes the
///   empty relation.
/// * If ANY surviving row entered via (b), skipping the residual FILTER could admit a
///   false positive (a not-indexed binding that does NOT satisfy the predicate) — a
///   SOUNDNESS bug. So the residual runs (`Partial`): an identity on the (a)-rows and
///   the judge of the (b)-rows, keeping the result byte-identical to the post-hoc
///   plan while the exact restriction still shrank the residual's input.
///
/// The certificate is trusted the same way `candidates`' superset contract is: the
/// provider asserts its exact refinement agrees with the registered `geof:` function
/// semantics (sparq-geo pins that equivalence in its `topology_index` tests).
#[cfg(feature = "spatial-exact-pushdown")]
fn apply_spatial_pushdown_exact(graph: &Graph, b: &mut Bindings, pd: &SpatialPushdown) -> ExactPushdown {
    let SpatialKind::BboxIntersects { arg_wkt, within_region: true } = &pd.kind else {
        return ExactPushdown::Declined;
    };
    let Some(col) = b.col(&pd.geo_var) else { return ExactPushdown::Declined };
    let Some(idx) = spatial::active() else { return ExactPushdown::Declined };
    let query = crate::SpatialExactQuery::WithinRegion { region_wkt: arg_wkt };
    let Some(exact) = idx.candidates_exact(&query) else { return ExactPushdown::Declined };
    // A certified term absent from the graph dict can never bind here, so dropping it
    // keeps `exact_ids` exactly the certified answers that can appear in `b` (mirrors
    // the superset path's `cand_ids` mapping).
    let exact_ids: FxHashSet<Id> = exact.iter().filter_map(|t| graph.id_of(t)).collect();
    let mut all_certified = true;
    // Same two retain branches as `apply_spatial_pushdown` (id-level fast path when the
    // provider vouches its id universe is fresh for THIS dict, per-row fallback
    // otherwise), same keep verdict in both: certified (a) or not-indexed (b).
    let dict_ptr = std::ptr::from_ref(&graph.dict) as usize;
    if let Some(indexed) = idx.indexed_ids(dict_ptr) {
        b.rows.retain(|row| {
            let id = row[col];
            if exact_ids.contains(&id) {
                return true; // (a) certified TRUE — the residual FILTER would keep it too
            }
            let keep = !indexed.contains(&id); // (b) keep not-indexed for the residual FILTER
            all_certified &= !keep;
            keep
        });
    } else {
        let mut verdict: FxHashMap<Id, bool> = FxHashMap::default();
        b.rows.retain(|row| {
            let id = row[col];
            if exact_ids.contains(&id) {
                return true;
            }
            let keep = *verdict.entry(id).or_insert_with(|| match term_of_id(graph, id) {
                Some(t) => !idx.is_indexed(&t),
                None => true, // no term (synthetic / unbound) — the index can't rule it out
            });
            all_certified &= !keep;
            keep
        });
    }
    if all_certified { ExactPushdown::AllCertified } else { ExactPushdown::Partial }
}

/// The graph-dictionary term for `id`, if any. (A standalone helper so the spatial
/// pushdown can resolve a binding without a `LocalVocab`; bindings reaching a pushable
/// scan-bound geometry FILTER are graph-dict ids.) [OPUS-4.8]
fn term_of_id(graph: &Graph, id: Id) -> Option<Term> {
    (id != NO_ID && !dict::is_inline(id)).then(|| graph.dict.term(id))
}

// ---- BGP evaluation ----------------------------------------------------------

/// Evaluates a basic graph pattern, dispatching between a binary join plan and a
/// worst-case-optimal (Leapfrog Triejoin) plan. Cyclic BGPs — where binary plans
/// can blow up to an intermediate result far larger than the final answer (e.g.
/// triangles) — go to WCOJ, which runs in time `Õ(AGM bound)` and so is provably
/// optimal in the worst case. Acyclic (tree-shaped) BGPs use binary joins, which
/// are optimal for them and avoid LFTJ's per-tuple overhead. Both paths are
/// differentially tested to produce identical results.
/// Evaluate a SPARQL property path `subject <path> object` into bindings over its endpoint
/// variables. Computes the path's (start,end) id-pair relation recursively — transitive `+`/`*`
/// via BFS, zero-length `*`/`?` add identity over the graph's nodes — then constrains it by any
/// bound or repeated endpoint. Bound endpoints are PUSHED DOWN into the relation computation
/// ([`PathEnds`]): a bound subject turns `+`/`*` into a single-source directed BFS over sorted
/// range scans, a bound object traverses in reverse, and both-bound is a reachability test with
/// early exit — so `:s p+ ?x` costs `O(edges reachable)`, not the all-pairs closure. The
/// post-filter below stays as the correctness backstop (the pushdown contract allows supersets).
fn eval_path(
    graph: &Graph,
    local: &mut LocalVocab,
    subject: &TermPattern,
    path: &PropertyPathExpression,
    object: &TermPattern,
) -> Result<Bindings, String> {
    enum End {
        Var(Variable),
        Bound(Id),
        /// A concrete term ABSENT from the dictionary — unsatisfiable for ordinary
        /// paths, but still the start of a zero-length solution for `p*` / `p?`.
        Missing(Term),
    }
    let resolve = |t: &TermPattern| -> Result<End, String> {
        Ok(match t {
            TermPattern::Variable(v) => End::Var(v.clone()),
            TermPattern::BlankNode(b) => End::Var(bnode_var(b)),
            other => {
                let term = term_pattern_to_term(other)?;
                match graph.id_of(&term) {
                    Some(id) => End::Bound(id),
                    None => End::Missing(term),
                }
            }
        })
    };
    let (s_end, o_end) = (resolve(subject)?, resolve(object)?);
    // Paths that admit the ZERO-LENGTH solution connect every term to itself — even
    // terms that do not occur in the data (a constant endpoint on an empty graph).
    let zero_len = matches!(path, PropertyPathExpression::ZeroOrMore(_) | PropertyPathExpression::ZeroOrOne(_));

    let s_var = if let End::Var(v) = &s_end { Some(v.clone()) } else { None };
    let o_var = if let End::Var(v) = &o_end { Some(v.clone()) } else { None };
    let same_var = matches!((&s_var, &o_var), (Some(a), Some(b)) if a == b);
    let mut vars: Vec<Variable> = Vec::new();
    if let Some(v) = &s_var {
        vars.push(v.clone());
    }
    if let Some(v) = &o_var {
        if !same_var {
            vars.push(v.clone());
        }
    }
    // A concrete-but-absent endpoint makes the pattern unsatisfiable — unless the
    // path has a zero-length solution, handled below.
    if !zero_len && (matches!(s_end, End::Missing(_)) || matches!(o_end, End::Missing(_))) {
        return Ok(Bindings::unsorted(vars, Vec::new()));
    }
    let s_bound = if let End::Bound(id) = &s_end { Some(*id) } else { None };
    let o_bound = if let End::Bound(id) = &o_end { Some(*id) } else { None };

    let mut rows: Vec<Row> = Vec::new();
    let mut seen: FxHashSet<Row> = FxHashSet::default();
    // DefaultGraphMode::Empty (L1 dataset view): no data pairs at top-level graph
    // scope — exactly the empty-graph evaluation. The zero-length constant
    // solutions below still apply (`<s> p* <s>` holds even on an empty graph).
    if !(view::default_is_empty() || matches!(s_end, End::Missing(_)) || matches!(o_end, End::Missing(_))) {
        let ends = PathEnds { s: s_bound, o: o_bound };
        // `?x p ?x` (same variable at both ends — necessarily both unbound): only
        // diagonal pairs survive the filter, and for the recursive operators the
        // diagonal is computable WITHOUT the all-pairs closure: the zero-length
        // operators' diagonal is exactly the node domain, and `p+`'s diagonal is
        // the set of nodes on a directed cycle (SCC size >= 2, or a self-loop).
        let pairs: FxHashSet<(Id, Id)> = if same_var {
            match path {
                PropertyPathExpression::ZeroOrMore(_) | PropertyPathExpression::ZeroOrOne(_) => {
                    graph_nodes(graph).into_iter().map(|n| (n, n)).collect()
                }
                PropertyPathExpression::OneOrMore(a) => {
                    cyclic_nodes(graph, a)?.into_iter().map(|n| (n, n)).collect()
                }
                _ => path_pairs(graph, path, ends)?,
            }
        } else {
            path_pairs(graph, path, ends)?
        };
        for (s, o) in pairs {
            if s_bound.is_some_and(|b| s != b) || o_bound.is_some_and(|b| o != b) || (same_var && s != o) {
                continue;
            }
            let mut row: Row = SmallVec::new();
            if s_var.is_some() {
                row.push(s);
            }
            if o_var.is_some() && !same_var {
                row.push(o);
            }
            if seen.insert(row.clone()) {
                rows.push(row); // property-path solutions are a set (DISTINCT)
            }
        }
    }
    if zero_len {
        // The zero-length solution for a CONSTANT endpoint: `<s> p* ?x` yields
        // {?x -> <s>} even on the empty graph (interning the absent term locally);
        // `<s> p* <s>` yields the unit solution. (Variable–variable zero-length
        // solutions over the graph's nodes come from `path_pairs` above.)
        let const_id = |e: &End, local: &mut LocalVocab| match e {
            End::Bound(id) => Some(*id),
            End::Missing(t) => Some(local.intern(t.clone())),
            End::Var(_) => None,
        };
        let zrow: Option<Row> = match (&s_end, &o_end) {
            (End::Var(_), End::Var(_)) => None,
            (s_c, End::Var(_)) => const_id(s_c, local).map(|id| std::iter::once(id).collect()),
            (End::Var(_), o_c) => const_id(o_c, local).map(|id| std::iter::once(id).collect()),
            (s_c, o_c) => {
                let (a, b) = (const_id(s_c, local), const_id(o_c, local));
                (a == b).then(SmallVec::new)
            }
        };
        if let Some(row) = zrow {
            if seen.insert(row.clone()) {
                rows.push(row);
            }
        }
    }
    Ok(Bindings::unsorted(vars, rows))
}

/// Endpoint constraints pushed down into a path-relation computation (`None` =
/// that end is unbound). CONTRACT: `path_pairs(graph, path, ends)` returns a
/// SUBSET of the path's full (start,end) relation that contains EVERY pair
/// satisfying the bounds. A sub-evaluation is free to IGNORE the hint and
/// return extra relation pairs (callers always post-filter), but must never
/// invent pairs outside the relation — so the pushdown is purely an
/// optimisation and the post-filter in `eval_path` is the correctness backstop.
#[derive(Clone, Copy, Default)]
struct PathEnds {
    s: Option<Id>,
    o: Option<Id>,
}

impl PathEnds {
    const NONE: PathEnds = PathEnds { s: None, o: None };
    /// The constraint seen through `^path` (endpoints exchange roles).
    #[inline]
    fn swapped(self) -> PathEnds {
        PathEnds { s: self.o, o: self.s }
    }
}

/// When a `Sequence` has a bound outer endpoint, the midpoints reached by the
/// near hop are pushed one at a time into the far hop — but only while the
/// fan-out stays below this limit. Above it, the per-midpoint sub-evaluations
/// (each at least a binary search; a whole traversal for a recursive hop)
/// can exceed the single bulk evaluation they replace, so the far hop then
/// DELIBERATELY gets only the outer endpoint pushed and the midpoints meet in
/// the hash join instead.
const SEQ_MIDPOINT_FANOUT_LIMIT: usize = 1024;

/// All `(subject, object)` id pairs connected by a property path expression,
/// narrowed by any bound endpoints (see [`PathEnds`] for the exact contract).
/// Bound endpoints reach the leaves as range-scan prefixes and turn the
/// recursive operators into single-source directed traversals.
fn path_pairs(graph: &Graph, path: &PropertyPathExpression, ends: PathEnds) -> Result<FxHashSet<(Id, Id)>, String> {
    use PropertyPathExpression as P;
    Ok(match path {
        P::NamedNode(p) => predicate_pairs(graph, p, ends),
        P::Reverse(a) => path_pairs(graph, a, ends.swapped())?.into_iter().map(|(s, o)| (o, s)).collect(),
        P::Sequence(a, c) => {
            if let Some(s) = ends.s {
                // Bound start: evaluate the near hop from `s` only, then push each
                // reached midpoint into the far hop (which also receives the bound
                // object, enabling early exit deeper down).
                let av = path_pairs(graph, a, PathEnds { s: Some(s), o: None })?;
                let mids: FxHashSet<Id> = av.iter().filter(|&&(x, _)| x == s).map(|&(_, m)| m).collect();
                if mids.len() <= SEQ_MIDPOINT_FANOUT_LIMIT {
                    let mut out = FxHashSet::default();
                    for &m in &mids {
                        for (m2, o) in path_pairs(graph, c, PathEnds { s: Some(m), o: ends.o })? {
                            if m2 == m {
                                out.insert((s, o));
                            }
                        }
                    }
                    out
                } else {
                    // Fan-out too large for per-midpoint pushes: the far hop gets
                    // only the outer bound endpoint.
                    join_seq(av, path_pairs(graph, c, PathEnds { s: None, o: ends.o })?)
                }
            } else if let Some(o) = ends.o {
                // Bound object only: mirror image — far hop backwards from `o`,
                // midpoints pushed into the near hop as bound objects.
                let cv = path_pairs(graph, c, PathEnds { s: None, o: Some(o) })?;
                let mids: FxHashSet<Id> = cv.iter().filter(|&&(_, y)| y == o).map(|&(m, _)| m).collect();
                if mids.len() <= SEQ_MIDPOINT_FANOUT_LIMIT {
                    let mut out = FxHashSet::default();
                    for &m in &mids {
                        for (s, m2) in path_pairs(graph, a, PathEnds { s: None, o: Some(m) })? {
                            if m2 == m {
                                out.insert((s, o));
                            }
                        }
                    }
                    out
                } else {
                    join_seq(path_pairs(graph, a, PathEnds::NONE)?, cv)
                }
            } else {
                join_seq(path_pairs(graph, a, PathEnds::NONE)?, path_pairs(graph, c, PathEnds::NONE)?)
            }
        }
        // Endpoints push into BOTH branches of an alternative unchanged.
        P::Alternative(a, c) => {
            let mut s = path_pairs(graph, a, ends)?;
            s.extend(path_pairs(graph, c, ends)?);
            s
        }
        P::OneOrMore(a) => match (ends.s, ends.o) {
            (Some(s), _) => directed_reach(graph, a, s, ends.o, Dir::Fwd)?.into_iter().map(|r| (s, r)).collect(),
            (None, Some(o)) => directed_reach(graph, a, o, None, Dir::Rev)?.into_iter().map(|r| (r, o)).collect(),
            (None, None) => transitive_closure_pairs(path_pairs(graph, a, PathEnds::NONE)?),
        },
        P::ZeroOrMore(a) => match (ends.s, ends.o) {
            // A bound endpoint needs only ITS reflexive pair, not the whole node
            // domain (`<s> p* <s>` holds for any term, see the zero-length rules).
            (Some(s), _) => {
                let mut c: FxHashSet<(Id, Id)> =
                    directed_reach(graph, a, s, ends.o, Dir::Fwd)?.into_iter().map(|r| (s, r)).collect();
                c.insert((s, s));
                c
            }
            (None, Some(o)) => {
                let mut c: FxHashSet<(Id, Id)> =
                    directed_reach(graph, a, o, None, Dir::Rev)?.into_iter().map(|r| (r, o)).collect();
                c.insert((o, o));
                c
            }
            (None, None) => {
                let mut c = transitive_closure_pairs(path_pairs(graph, a, PathEnds::NONE)?);
                c.extend(graph_nodes(graph).into_iter().map(|n| (n, n)));
                c
            }
        },
        P::ZeroOrOne(a) => {
            let mut s = path_pairs(graph, a, ends)?;
            match (ends.s, ends.o) {
                // Bound endpoint: only its own reflexive pair (no full-store node scan).
                (Some(x), None) | (None, Some(x)) => {
                    s.insert((x, x));
                }
                (Some(x), Some(y)) => {
                    if x == y {
                        s.insert((x, x));
                    }
                }
                (None, None) => s.extend(graph_nodes(graph).into_iter().map(|n| (n, n))),
            }
            s
        }
        P::NegatedPropertySet(props) => negated_property_pairs(graph, props, ends),
    })
}

/// Hash join of two path relations on the shared midpoint (`a.end == c.start`).
fn join_seq(av: FxHashSet<(Id, Id)>, cv: FxHashSet<(Id, Id)>) -> FxHashSet<(Id, Id)> {
    let mut by_start: FxHashMap<Id, Vec<Id>> = FxHashMap::default();
    for (m, o) in cv {
        by_start.entry(m).or_default().push(o);
    }
    let mut out = FxHashSet::default();
    for (s, m) in av {
        if let Some(os) = by_start.get(&m) {
            for &o in os {
                out.insert((s, o));
            }
        }
    }
    out
}

/// Traversal direction for [`directed_reach`]: forward follows the sub-path
/// from a bound SUBJECT; reverse walks it backwards from a bound OBJECT (the
/// O-leading permutations answer the reversed leaf scans).
#[derive(Clone, Copy, PartialEq)]
enum Dir {
    Fwd,
    Rev,
}

/// Single-source reachability (one or more steps) from `start` under the
/// sub-path: a budget-checked BFS whose frontier expansion is a bounded
/// sub-evaluation — for a plain-predicate sub-path, one sorted range scan
/// (`[Some(n), Some(p), None]`, or `[None, Some(p), Some(n)]` reversed) per
/// node. With `target` bound the walk is a reachability TEST and stops as soon
/// as the target is reached.
fn directed_reach(
    graph: &Graph,
    sub: &PropertyPathExpression,
    start: Id,
    target: Option<Id>,
    dir: Dir,
) -> Result<FxHashSet<Id>, String> {
    // Plain-predicate fast path: successors come straight from a range scan
    // (no per-node relation set). `Some(None)` = predicate not in the
    // dictionary, hence no edges at all.
    let pid: Option<Option<Id>> = match sub {
        PropertyPathExpression::NamedNode(p) => Some(graph.id_of(&Term::NamedNode(p.clone()))),
        _ => None,
    };
    let step = |node: Id, out: &mut Vec<Id>| -> Result<(), String> {
        match pid {
            Some(None) => {}
            Some(Some(pid)) => {
                let pat: IdPattern = match dir {
                    Dir::Fwd => [Some(node), Some(pid), None],
                    Dir::Rev => [None, Some(pid), Some(node)],
                };
                let scan = graph.store.scan(&pat);
                let col = match dir {
                    Dir::Fwd => 2,
                    Dir::Rev => 0,
                };
                out.extend(scan.rows.iter().map(|r| scan.to_spo(r)[col]));
            }
            // Composite sub-path: one bounded sub-evaluation per node (its own
            // endpoints push recursively). The filter enforces the contract's
            // "may return extra relation pairs" clause.
            None => {
                let ends = match dir {
                    Dir::Fwd => PathEnds { s: Some(node), o: None },
                    Dir::Rev => PathEnds { s: None, o: Some(node) },
                };
                for (s, o) in path_pairs(graph, sub, ends)? {
                    match dir {
                        Dir::Fwd if s == node => out.push(o),
                        Dir::Rev if o == node => out.push(s),
                        _ => {}
                    }
                }
            }
        }
        Ok(())
    };
    let mut seen: FxHashSet<Id> = FxHashSet::default();
    let mut stack: Vec<Id> = Vec::new();
    step(start, &mut stack)?;
    let mut pops = 0usize;
    while let Some(n) = stack.pop() {
        // Budget granularity: check INSIDE the walk (every 1024 pops), so one
        // runaway traversal respects the budget promptly.
        pops += 1;
        if pops & 0x3FF == 0 {
            budget::check(seen.len())?;
        }
        if seen.insert(n) {
            if target == Some(n) {
                break;
            }
            step(n, &mut stack)?;
        }
    }
    Ok(seen)
}

/// The nodes lying on a directed cycle of the sub-path's relation — exactly the
/// solutions of `?x p+ ?x` — via Kosaraju SCC over the base relation: every
/// member of an SCC of size >= 2, plus self-loop nodes. `O(V + E)` instead of
/// the all-pairs closure's `O(V·E)`.
fn cyclic_nodes(graph: &Graph, sub: &PropertyPathExpression) -> Result<FxHashSet<Id>, String> {
    let base = path_pairs(graph, sub, PathEnds::NONE)?;
    let mut adj: FxHashMap<Id, Vec<Id>> = FxHashMap::default();
    let mut radj: FxHashMap<Id, Vec<Id>> = FxHashMap::default();
    let mut cyclic: FxHashSet<Id> = FxHashSet::default();
    for &(s, o) in &base {
        if s == o {
            cyclic.insert(s); // self-loop: a 1-cycle
        }
        adj.entry(s).or_default().push(o);
        radj.entry(o).or_default().push(s);
    }
    // Pass 1: iterative DFS post-order (every node with an out-edge is a root
    // candidate; sinks are reached as children — a cycle member always has an
    // out-edge, so coverage is complete).
    let mut order: Vec<Id> = Vec::new();
    let mut visited: FxHashSet<Id> = FxHashSet::default();
    let mut steps = 0usize;
    let roots: Vec<Id> = adj.keys().copied().collect();
    for &root in &roots {
        if !visited.insert(root) {
            continue;
        }
        let mut stack: Vec<(Id, usize)> = vec![(root, 0)];
        while let Some(frame) = stack.last_mut() {
            steps += 1;
            if steps & 0x3FF == 0 {
                budget::check(order.len())?;
            }
            let (n, i) = *frame;
            match adj.get(&n).and_then(|v| v.get(i).copied()) {
                Some(m) => {
                    frame.1 += 1;
                    if visited.insert(m) {
                        stack.push((m, 0));
                    }
                }
                None => {
                    order.push(n);
                    stack.pop();
                }
            }
        }
    }
    // Pass 2: components of the TRANSPOSE graph, roots taken in reverse
    // post-order; a component of >= 2 members is a cycle through all of them.
    let mut assigned: FxHashSet<Id> = FxHashSet::default();
    for &root in order.iter().rev() {
        if !assigned.insert(root) {
            continue;
        }
        let mut members: Vec<Id> = vec![root];
        let mut stack: Vec<Id> = vec![root];
        while let Some(n) = stack.pop() {
            steps += 1;
            if steps & 0x3FF == 0 {
                budget::check(members.len())?;
            }
            if let Some(ps) = radj.get(&n) {
                for &m in ps {
                    if assigned.insert(m) {
                        members.push(m);
                        stack.push(m);
                    }
                }
            }
        }
        if members.len() >= 2 {
            cyclic.extend(members);
        }
    }
    Ok(cyclic)
}

/// All `(s, o)` for a single predicate IRI (empty if the predicate isn't in the
/// graph), narrowed by any bound endpoints — `[s?, p, o?]` is always a single
/// contiguous range in some built permutation.
fn predicate_pairs(graph: &Graph, p: &oxrdf::NamedNode, ends: PathEnds) -> FxHashSet<(Id, Id)> {
    match graph.id_of(&Term::NamedNode(p.clone())) {
        None => FxHashSet::default(),
        Some(pid) => {
            let pat: IdPattern = [ends.s, Some(pid), ends.o];
            let scan = graph.store.scan(&pat);
            scan.rows
                .iter()
                .map(|r| {
                    let t = scan.to_spo(r);
                    (t[0], t[2])
                })
                .collect()
        }
    }
}

/// `!(...)` — every edge whose predicate is NOT in the excluded set. A bound
/// endpoint narrows the scan to that one node's triples; the fully-unbound case
/// walks a P-leading permutation and skips each excluded predicate's contiguous
/// block wholesale (binary search to the block end — no per-triple set probe
/// over the excluded mass).
fn negated_property_pairs(graph: &Graph, props: &[oxrdf::NamedNode], ends: PathEnds) -> FxHashSet<(Id, Id)> {
    let excluded: FxHashSet<Id> = props.iter().filter_map(|p| graph.id_of(&Term::NamedNode(p.clone()))).collect();
    if ends.s.is_some() || ends.o.is_some() {
        let pat: IdPattern = [ends.s, None, ends.o];
        let scan = graph.store.scan(&pat);
        return scan
            .rows
            .iter()
            .filter_map(|r| {
                let t = scan.to_spo(r);
                (!excluded.contains(&t[1])).then_some((t[0], t[2]))
            })
            .collect();
    }
    // Both BUILT index sets contain a P-leading permutation (PSO full / POS
    // compact), so `scan_sorted` finds one; the fallback filter-scan defends
    // against a future index set where it doesn't.
    let scan = graph.store.scan_sorted(&[None, None, None], 1);
    let rows = &scan.rows[..];
    let mut out = FxHashSet::default();
    if scan.perm.order()[0] == 1 {
        let mut i = 0;
        while i < rows.len() {
            let p = rows[i][0];
            let j = i + rows[i..].partition_point(|r| r[0] == p);
            if !excluded.contains(&p) {
                for r in &rows[i..j] {
                    let t = scan.to_spo(r);
                    out.insert((t[0], t[2]));
                }
            }
            i = j;
        }
    } else {
        for r in rows {
            let t = scan.to_spo(r);
            if !excluded.contains(&t[1]) {
                out.insert((t[0], t[2]));
            }
        }
    }
    out
}

/// Every id that appears as a subject or object (the domain of zero-length path matches).
fn graph_nodes(graph: &Graph) -> FxHashSet<Id> {
    let pat: IdPattern = [None, None, None];
    let scan = graph.store.scan(&pat);
    let mut s = FxHashSet::default();
    for r in scan.rows.iter() {
        let t = scan.to_spo(r);
        s.insert(t[0]);
        s.insert(t[2]);
    }
    s
}

/// Transitive (NOT reflexive) closure of a pair relation — BFS of reachability from each start.
fn transitive_closure_pairs(pairs: FxHashSet<(Id, Id)>) -> FxHashSet<(Id, Id)> {
    let mut adj: FxHashMap<Id, Vec<Id>> = FxHashMap::default();
    for (s, o) in &pairs {
        adj.entry(*s).or_default().push(*o);
    }
    let mut out: FxHashSet<(Id, Id)> = FxHashSet::default();
    let starts: Vec<Id> = adj.keys().copied().collect();
    let mut pops = 0usize;
    for start in starts {
        // Budget check per BFS start node (sticky; the caller's next check
        // raises the error)…
        if budget::exhausted(out.len()) {
            break;
        }
        let mut seen: FxHashSet<Id> = FxHashSet::default();
        let mut stack: Vec<Id> = adj.get(&start).cloned().unwrap_or_default();
        while let Some(n) = stack.pop() {
            // …and every 1024 expansions INSIDE the walk, so one runaway start
            // node cannot overshoot the budget by a whole graph traversal.
            pops += 1;
            if pops & 0x3FF == 0 && budget::exhausted(out.len()) {
                return out;
            }
            if seen.insert(n) {
                out.insert((start, n));
                if let Some(nexts) = adj.get(&n) {
                    stack.extend(nexts.iter().copied());
                }
            }
        }
    }
    out
}

fn eval_bgp(graph: &Graph, patterns: &[TriplePattern]) -> Result<Bindings, String> {
    if patterns.is_empty() {
        return Ok(Bindings { vars: vec![], rows: vec![Row::new()], sorted_by: None });
    }
    // DefaultGraphMode::Empty (L1 dataset view): a non-empty BGP at top-level
    // graph scope has ZERO rows, with its normal variable schema (the empty BGP
    // above keeps its unit row; GRAPH scope suspends the flag).
    if view::default_is_empty() {
        return Ok(Bindings::unsorted(collect_vars(patterns), vec![]));
    }
    // RDF 1.2 triple-term patterns with variables decompose into synthetic-variable
    // slots + structural-unification relations, joined by the ordinary machinery (F14).
    let (rewritten, constraints) = extract_quoted_constraints(patterns);
    if !constraints.is_empty() {
        // zk-trace: structural-unification relations scan the store without
        // per-pattern attribution — mark Op::QuotedTriples so a consumer
        // fails closed (ZkTrace::first_uncaptured).
        #[cfg(feature = "zk")]
        let _zk = crate::zk::op_scope(crate::zk::Op::QuotedTriples);
        let mut b = eval_bgp(graph, &rewritten)?;
        for c in &constraints {
            b = join_bindings(b, quoted_relation(graph, c));
        }
        return Ok(b);
    }
    if patterns.len() >= 3 && bgp_is_cyclic(patterns) {
        return eval_bgp_wcoj(graph, patterns);
    }
    // [OPUS-4.8] (sq-5zf8i / §A4) Acyclic BGP: optionally run the Yannakakis bottom-up
    // full-semijoin PREPASS before the binary join (opt-in `yannakakis` feature, OFF by
    // default). Routed here, on the SAME acyclic branch that already chooses the binary
    // plan over LFTJ — so cyclic BGPs (handled above) keep the existing LFTJ unchanged.
    // The prepass internally cost-gates and falls back to `eval_bgp_binary` when there is
    // nothing to gain; its result is identical to the binary plan (semijoin reduction is
    // answer-preserving), so with the feature OFF this is byte-identical to before.
    #[cfg(feature = "yannakakis")]
    if patterns.len() >= 2 {
        return eval_bgp_yannakakis(graph, patterns, &[]);
    }
    eval_bgp_binary(graph, patterns, &[])
}

// ---- RDF 1.2 triple-term patterns with variables (F14) ----------------------

/// Prefix for the synthetic variables standing in for a triple-term pattern slot
/// (like [`BNODE_VAR_PREFIX`], `#` cannot appear in a SPARQL VARNAME).
const QT_VAR_PREFIX: &str = "#qt#";

/// One BGP slot that held a triple-term pattern CONTAINING VARIABLES, replaced by a
/// synthetic variable. Its relation enumerates every stored triple term and unifies it
/// structurally against the triple-term pattern, binding the inner variables.
struct QuotedConstraint {
    var: Variable,
    pattern: TriplePattern,
}

/// `true` when a triple-term pattern has a variable / blank node anywhere inside
/// (such a pattern cannot resolve to a single dictionary id).
fn quoted_has_var(t: &TriplePattern) -> bool {
    fn slot(tp: &TermPattern) -> bool {
        match tp {
            TermPattern::Variable(_) | TermPattern::BlankNode(_) => true,
            TermPattern::Triple(inner) => quoted_has_var(inner),
            _ => false,
        }
    }
    slot(&t.subject) || matches!(t.predicate, NamedNodePattern::Variable(_)) || slot(&t.object)
}

/// Rewrites the BGP: every subject/object slot holding a variable-carrying triple-term
/// pattern becomes a fresh synthetic variable, with the triple-term pattern recorded as a
/// [`QuotedConstraint`]. Ground triple terms are untouched (they resolve to one id).
fn extract_quoted_constraints(patterns: &[TriplePattern]) -> (Vec<TriplePattern>, Vec<QuotedConstraint>) {
    let mut out = Vec::with_capacity(patterns.len());
    let mut constraints: Vec<QuotedConstraint> = Vec::new();
    for tp in patterns {
        let mut tp = tp.clone();
        for s in [&mut tp.subject, &mut tp.object] {
            if let TermPattern::Triple(t) = s {
                if quoted_has_var(t) {
                    let var = Variable::new_unchecked(format!("{QT_VAR_PREFIX}{}", constraints.len()));
                    constraints.push(QuotedConstraint { var: var.clone(), pattern: (**t).clone() });
                    *s = TermPattern::Variable(var);
                }
            }
        }
        out.push(tp);
    }
    (out, constraints)
}

/// The variables of a triple-term pattern in first-occurrence order (blank nodes as
/// their synthetic existential variables), appended to `out` without duplicates.
fn collect_quoted_vars(t: &TriplePattern, out: &mut Vec<Variable>) {
    fn push(out: &mut Vec<Variable>, v: Variable) {
        if !out.contains(&v) {
            out.push(v);
        }
    }
    fn slot(tp: &TermPattern, out: &mut Vec<Variable>) {
        match tp {
            TermPattern::Variable(v) => push(out, v.clone()),
            TermPattern::BlankNode(b) => push(out, bnode_var(b)),
            TermPattern::Triple(inner) => collect_quoted_vars(inner, out),
            _ => {}
        }
    }
    slot(&t.subject, out);
    if let NamedNodePattern::Variable(v) = &t.predicate {
        push(out, v.clone());
    }
    slot(&t.object, out);
}

/// Builds the constraint's relation: one row per stored triple term that structurally
/// unifies with the quoted pattern — columns are the synthetic slot variable (bound to
/// the triple term's own id) followed by the quoted pattern's inner variables.
///
/// Enumeration scans the dictionary for `TermParts::Triple` records: triple terms are a
/// vanishing fraction of real dictionaries and the scan only runs for queries that quote
/// variables, so no ordinary query pays for it. (A persistent side index of triple-term
/// ids is the obvious upgrade if quoted-pattern workloads ever matter at scale.)
fn quoted_relation(graph: &Graph, c: &QuotedConstraint) -> Bindings {
    let mut vars = vec![c.var.clone()];
    collect_quoted_vars(&c.pattern, &mut vars);
    let mut rows: Vec<Row> = Vec::new();
    for id in 1..=graph.dict.len() as Id {
        let dict::TermParts::Triple(comps) = graph.dict.term_parts(id) else {
            continue;
        };
        let mut binds: Row = std::iter::repeat_n(NO_ID, vars.len()).collect();
        binds[0] = id;
        if unify_quoted(graph, &c.pattern, comps, &vars, &mut binds) {
            rows.push(binds);
        }
    }
    Bindings::unsorted(vars, rows)
}

/// Binds `v` to `id`, or checks consistency when the variable is already bound
/// (the same variable repeated inside a quoted pattern must match the same id).
fn bind_quoted_var(v: &Variable, id: Id, vars: &[Variable], binds: &mut [Id]) -> bool {
    let i = vars.iter().position(|x| x == v).expect("quoted var collected");
    if binds[i] == NO_ID {
        binds[i] = id;
        true
    } else {
        binds[i] == id
    }
}

/// Structurally unifies a triple-term pattern against a stored triple term's
/// component ids, recursing through nested triple-term patterns.
fn unify_quoted(graph: &Graph, pat: &TriplePattern, comps: [Id; 3], vars: &[Variable], binds: &mut [Id]) -> bool {
    fn slot(graph: &Graph, tp: &TermPattern, id: Id, vars: &[Variable], binds: &mut [Id]) -> bool {
        match tp {
            TermPattern::Variable(v) => bind_quoted_var(v, id, vars, binds),
            TermPattern::BlankNode(b) => bind_quoted_var(&bnode_var(b), id, vars, binds),
            TermPattern::Triple(inner) => {
                if dict::is_inline(id) {
                    return false;
                }
                match graph.dict.term_parts(id) {
                    dict::TermParts::Triple(c) => unify_quoted(graph, inner, c, vars, binds),
                    _ => false,
                }
            }
            // A ground component: term-identity match (same as ordinary BGP slots).
            other => match term_pattern_to_term(other) {
                Ok(t) => graph.id_of(&t) == Some(id),
                Err(_) => false,
            },
        }
    }
    if !slot(graph, &pat.subject, comps[0], vars, binds) {
        return false;
    }
    match &pat.predicate {
        NamedNodePattern::NamedNode(n) => {
            if graph.id_of(&Term::NamedNode(n.clone())) != Some(comps[1]) {
                return false;
            }
        }
        NamedNodePattern::Variable(v) => {
            if !bind_quoted_var(v, comps[1], vars, binds) {
                return false;
            }
        }
    }
    slot(graph, &pat.object, comps[2], vars, binds)
}

/// Whether this conjunctive BGP would be routed to the worst-case-optimal plan
/// (so the caller knows whether sargable-filter pushdown into the binary scan
/// applies).
pub(crate) fn bgp_uses_binary(patterns: &[TriplePattern]) -> bool {
    !(patterns.len() >= 3 && bgp_is_cyclic(patterns))
}

/// Binary-join BGP plan: greedy cardinality ordering with sort-merge joins on the
/// current sort variable (falling back to hash, then cross product). `pat_filters`
/// holds an optional pushed-down numeric FILTER per pattern (by original index).
fn eval_bgp_binary(graph: &Graph, patterns: &[TriplePattern], pat_filters: &[Option<(usize, ScanCmp)>]) -> Result<Bindings, String> {
    if patterns.is_empty() {
        return Ok(Bindings { vars: vec![], rows: vec![Row::new()], sorted_by: None });
    }
    // L1 dataset view: the conjunctive-flattening path calls this directly
    // (bypassing eval_bgp), so the empty-default short-circuit must be here too.
    if view::default_is_empty() {
        return Ok(Bindings::unsorted(collect_vars(patterns), vec![]));
    }
    // Triple-term patterns with variables (F14): the conjunctive-flattening path calls
    // this directly (bypassing eval_bgp), so the decomposition must happen here too.
    // The rewrite preserves pattern count/order, so `pat_filters` indexes stay aligned.
    let (rewritten, constraints) = extract_quoted_constraints(patterns);
    if !constraints.is_empty() {
        #[cfg(feature = "zk")]
        let _zk = crate::zk::op_scope(crate::zk::Op::QuotedTriples);
        let mut b = eval_bgp_binary(graph, &rewritten, pat_filters)?;
        for c in &constraints {
            b = join_bindings(b, quoted_relation(graph, c));
        }
        return Ok(b);
    }
    let pfilter = |i: usize| -> Option<(usize, ScanCmp)> { pat_filters.get(i).copied().flatten() };

    let prepared = prepare_bgp(graph, patterns)?;
    if prepared.iter().any(|p| p.unsatisfiable) {
        // zk-trace: an unsatisfiable constant (a term absent from the
        // dictionary) is a PROVABLY-EMPTY input set — the per-property proof
        // must witness "no such triple exists". Record ONLY the patterns that
        // are provably empty; a satisfiable SIBLING was never consumed (the
        // join short-circuits), so claiming it empty would over-state the
        // trace.
        #[cfg(feature = "zk")]
        if crate::zk::enabled() {
            for (tp, prep) in patterns.iter().zip(&prepared) {
                if prep.unsatisfiable {
                    crate::zk::record_empty_pattern(crate::zk::key_of_algebra_pattern(tp));
                }
            }
        }
        return Ok(Bindings::unsorted(collect_vars(patterns), vec![]));
    }

    // [OPUS-4.8] (sq-iywur) Optional DP join-order planner path. When the `dp-planner`
    // feature is compiled AND a planner is installed on this thread (`with_dp_planner`*),
    // enumerate connected-subgraph-complement pairs (DPccp) for a Cout-optimal BUSHY join
    // tree and evaluate that, instead of the greedy GOO order below. Falls back to greedy
    // (returns `None`) when no planner is installed, the BGP join graph is disconnected /
    // has an all-constant pattern (no single connected plan), or the connected-subgraph
    // count exceeds the budget. A BGP is a commutative/associative natural join, so the DP
    // tree yields the SAME rows as greedy (differentially tested); the default build
    // (feature off) is byte-identical — this whole block compiles away.
    #[cfg(feature = "dp-planner")]
    if let Some(cfg) = crate::dp::active() {
        if let Some(bindings) = eval_bgp_dp(graph, &prepared, pat_filters, cfg) {
            return Ok(bindings);
        }
    }

    // [FABLE-5] (sq-7d3dj.30.14) Membership-cluster pre-materialisation (opt-in
    // `cluster-materialize`). When the BGP has the SP2Bench-q07 shape — one
    // unbound-predicate container-membership pattern + a small bound-predicate anchor
    // sharing exactly one variable — evaluate that {anchor, membership} pair STANDALONE
    // (bounding the shared variable from the small anchor) and natural-join it to the
    // rest, instead of letting greedy GOO bind-join the wide membership relation per
    // driver binding. A BGP is a commutative/associative natural join, so partitioning
    // into two connected sub-BGPs and joining yields the SAME rows as any greedy order
    // (differentially tested, tests/cluster_materialize_differential.rs). `detect`
    // DECLINES (returns None → unchanged greedy plan) on any non-matching shape. The
    // whole block compiles away when the feature is off (default + wasm byte-identical).
    #[cfg(feature = "cluster-materialize")]
    if let Some(plan) = crate::cluster::detect(&prepared, crate::cluster::active_thresholds(), |i| pfilter(i).is_some()) {
        return eval_bgp_cluster(graph, patterns, pat_filters, &plan);
    }

    let var_pos = |i: usize, v: &Variable| -> Option<usize> { prepared[i].var_pos(v) };

    // Cost-based greedy (GOO): seed with the smallest single-pattern cardinality,
    // then repeatedly add the connected pattern that yields the smallest *estimated
    // join result*, using the per-predicate characteristic stats (distinct
    // subjects/objects) to estimate join selectivity. The join order only affects
    // performance (the result is identical for any order — differentially tested).
    // The decision logic lives in `goo_seed` / `goo_seed_sort` / `goo_pick` /
    // `record_pattern_ndv`, shared verbatim with the T22 EXPLAIN dry-run planner.
    let mut cs_ctx = CsCtx::new(&prepared);
    let seed = goo_seed(&prepared);
    let seed_sort_col = goo_seed_sort(&prepared, seed, pfilter(seed).map(|(c, _)| c));

    let mut result = scan_to_bindings(
        graph,
        &prepared[seed].id_pat,
        &prepared[seed].pos_vars,
        seed_sort_col,
        pfilter(seed),
        None,
        // The seed is the FIRST scan — there is no materialised side to build a
        // semi-join prefilter from yet.
        #[cfg(feature = "semijoin-bitmap")]
        None,
    );
    let mut done = vec![false; prepared.len()];
    done[seed] = true;
    cs_ctx.note_done(seed);

    // Running estimate of the result cardinality and the per-variable distinct
    // count (ndv), used to score the next join.
    let mut cur_card = prepared[seed].est as f64;
    let mut var_ndv: FxHashMap<Variable, f64> = FxHashMap::default();
    record_pattern_ndv(graph, &prepared, seed, cur_card, &mut var_ndv, &cs_ctx);

    for _ in 1..prepared.len() {
        // Pick the connected candidate with the smallest estimated output.
        let (i, new_card, _connected) = goo_pick(graph, &prepared, &done, &var_ndv, cur_card, &cs_ctx);
        cur_card = new_card;
        done[i] = true;
        cs_ctx.note_done(i);

        // Index-nested-loop (bind) join: when the running result is MUCH smaller than
        // the next pattern and exactly one variable connects them, look up each result
        // join value in the pattern's index (a bound scan) instead of scanning the whole
        // (large) relation and merge/hash-joining. This is the win on a selective join —
        // e.g. a chain whose far end is selective — where the merge would scan millions
        // of rows to match a few thousand. Same result, validated differentially.
        let connecting: Vec<Variable> = result.vars.iter().filter(|v| var_pos(i, v).is_some()).cloned().collect();
        if connecting.len() == 1
            && distinct_pattern_vars(&prepared[i].pos_vars)
            && result.rows.len().saturating_mul(8) < prepared[i].est
        {
            let jv = &connecting[0];
            let rk = result.col(jv).unwrap();
            let pp = var_pos(i, jv).unwrap();
            result = bind_join(graph, result, &prepared[i].id_pat, &prepared[i].pos_vars, rk, pp, pfilter(i));
            record_pattern_ndv(graph, &prepared, i, cur_card, &mut var_ndv, &cs_ctx);
            if result.rows.is_empty() {
                break;
            }
            continue;
        }

        // Execute: a pushed-down filter forces the scan into its own column order
        // (and filters inline); otherwise sort by the join variable for a merge.
        let filt = pfilter(i);
        let merge_var = result.sorted_by.clone().filter(|sv| var_pos(i, sv).is_some());
        let scan_sort = filt.map(|(c, _)| c).or_else(|| merge_var.as_ref().map(|jv| var_pos(i, jv).unwrap()));

        // [OPUS-4.8] (sq-gr8mb / §A3) Semi-join prefilter: build a membership filter over
        // ONE connecting variable's ids from the already-materialised `result`, and pass
        // it to the scan so rows that cannot survive the join are dropped before they are
        // built/joined. A row survives the downstream join only if it matches on EVERY
        // shared variable, so filtering on one of them removes only rows that would fail
        // anyway — the result is identical, just fewer rows scanned. Built only when a
        // single-column membership test is well-defined: a connecting variable that does
        // not repeat in the pattern (a repeat is handled by `build_row`'s consistency
        // check; the prefilter checks the variable's first canonical position).
        #[cfg(feature = "semijoin-bitmap")]
        let prefilter_keys = result
            .vars
            .iter()
            .find_map(|v| var_pos(i, v).map(|pos| (v.clone(), pos)))
            .and_then(|(v, pos)| {
                let rk = result.col(&v)?;
                crate::semijoin::KeyFilter::build(result.rows.iter().map(|r| r[rk])).map(|kf| (pos, kf))
            });
        #[cfg(feature = "semijoin-bitmap")]
        let prefilter = prefilter_keys.as_ref().map(|(pos, kf)| (*pos, kf));

        let rhs = scan_to_bindings(
            graph,
            &prepared[i].id_pat,
            &prepared[i].pos_vars,
            scan_sort,
            filt,
            None,
            #[cfg(feature = "semijoin-bitmap")]
            prefilter,
        );
        let connected = prepared[i].pos_vars.iter().flatten().any(|v| result.vars.contains(v));
        // Merge only when both sides are sorted on the join variable (a filter may
        // have forced the scan into a different order).
        if let Some(jv) = merge_var.filter(|jv| rhs.sorted_by.as_ref() == Some(jv)) {
            result = merge_join(result, rhs, &jv);
        } else if connected {
            result = hash_join(result, rhs);
        } else {
            result = cross_product(result, rhs);
        }
        record_pattern_ndv(graph, &prepared, i, cur_card, &mut var_ndv, &cs_ctx);

        if result.rows.is_empty() {
            break;
        }
    }
    Ok(result)
}

// ---- [OPUS-4.8] (sq-5zf8i / survey §A4) Yannakakis full-semijoin prepass -------
//
// research/codebase-improvement-opportunities-2026-06-23.md §A4 +
// research/optimization-techniques.md §1.1/§2(a2): for an ACYCLIC BGP, run a bottom-up
// then top-down FULL-SEMIJOIN sweep over the join tree BEFORE the main join, so the join
// never materialises a tuple that joins with nothing (a "dangling" tuple). This cuts the
// intermediate-result blow-up that is the materialising evaluator's #1 cost.
//
// REUSE of the A3 machinery: the membership test that drives each semijoin is the same
// exact `semijoin::KeyFilter` (bitmap on dense dictionary ids, exact set on sparse+huge
// keys) the A3 reducer uses; the cyclic/acyclic routing is the same `bgp_is_cyclic` /
// `bgp_uses_binary` GYO test the executor already has. The final join over the reduced
// relations reuses the executor's generic conjunctive `join_bindings`.
//
// CORRECTNESS (load-bearing). A semijoin is a pure FILTER — it removes only rows the
// final join would itself drop — so the reduced relations produce the SAME join result as
// the unreduced ones, for any join order. The feature is OFF by default; when off none of
// this compiles and the executor path is byte-identical. The on==off result equivalence
// is asserted by tests/yannakakis_differential.rs (NOT feature-gated: runs in BOTH states,
// each query checked against an independent brute-force reference).

/// One materialised relation in the prepass: the pattern's scanned rows, plus the
/// canonical *column index* of each JOIN variable (a variable shared with at least one
/// OTHER pattern) — those are the only columns a semijoin ever filters on.
#[cfg(feature = "yannakakis")]
struct SjRelation {
    bindings: Bindings,
    /// `(variable, column index in `bindings.vars`)` for each join variable this relation
    /// binds. Non-join (private) variables are excluded — they never connect two relations.
    join_cols: Vec<(Variable, usize)>,
}

/// Below this estimated max single-pattern cardinality, the intermediate results cannot
/// blow up enough for the prepass to pay for itself, so the executor skips the prepass and
/// uses the ordinary binary plan (pure-overhead guard). Tuned conservatively: the prepass
/// only ever helps when at least one relation is large. (Never affects RESULTS — only
/// whether the reduction runs.)
#[cfg(feature = "yannakakis")]
const YANNAKAKIS_MIN_REL: usize = 4_096;

/// Acyclic-BGP executor with the Yannakakis full-semijoin prepass (opt-in `yannakakis`).
///
/// Plan: cost-gate on the planner estimates; if worth it, materialise each pattern once,
/// run a bottom-up (leaf → root) then top-down (root → leaf) semijoin sweep over the join
/// tree, then join the REDUCED relations with the existing conjunctive join. The result is
/// identical to `eval_bgp_binary` (semijoin reduction is answer-preserving).
#[cfg(feature = "yannakakis")]
fn eval_bgp_yannakakis(
    graph: &Graph,
    patterns: &[TriplePattern],
    pat_filters: &[Option<(usize, ScanCmp)>],
) -> Result<Bindings, String> {
    let pfilter = |i: usize| -> Option<(usize, ScanCmp)> { pat_filters.get(i).copied().flatten() };
    // The prepass only helps a MULTI-pattern join. An empty BGP (`{}` → the unit row) and a
    // single pattern (no join to reduce) have nothing to reduce and their edge cases (unit
    // row, empty-default view, unsatisfiable constant) are handled precisely by the binary
    // executor — defer to it so the prepass never has to replicate that logic.
    if patterns.len() < 2 {
        return eval_bgp_binary(graph, patterns, pat_filters);
    }
    // zk-trace: when the per-obligation recorder is ARMED, the prover needs the established
    // executor's exact per-pattern matched-triple input sets and join order; the prepass
    // reduces relations and re-orders the join, which would change the recorded witness.
    // Defer to the binary plan while recording so the zk witness is unchanged (the prepass
    // is a perf-only optimisation; the un-reduced trace is the canonical one).
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        return eval_bgp_binary(graph, patterns, pat_filters);
    }
    // The conjunctive-flattening / triple-term / empty-view short-circuits and the
    // unsatisfiable-constant short-circuit all live in `eval_bgp_binary`; defer to it for
    // those so the prepass only ever sees a plain, satisfiable, materialisable BGP. Every
    // fallback forwards `pat_filters` so pushed-down FILTER semantics are preserved.
    if view::default_is_empty() {
        return Ok(Bindings::unsorted(collect_vars(patterns), vec![]));
    }
    let (_rewritten, constraints) = extract_quoted_constraints(patterns);
    if !constraints.is_empty() {
        // Triple-term decomposition is a binary-plan concern; let the binary executor
        // handle the rewrite + structural-unification joins (no prepass over synthetics).
        return eval_bgp_binary(graph, patterns, pat_filters);
    }

    let prepared = prepare_bgp(graph, patterns)?;
    if prepared.iter().any(|p| p.unsatisfiable) {
        // An absent constant makes the BGP provably empty; reuse the binary path's
        // short-circuit (it also records the zk-trace empties).
        return eval_bgp_binary(graph, patterns, pat_filters);
    }

    // Cost-gate (pure-overhead guard): unless at least one relation is estimated large,
    // the intermediates are already tiny and the prepass is pure overhead — use the plain
    // binary plan. This never affects results, only whether the reduction runs.
    let max_est = prepared.iter().map(|p| p.est).max().unwrap_or(0);
    if max_est < YANNAKAKIS_MIN_REL {
        return eval_bgp_binary(graph, patterns, pat_filters);
    }

    // Identify the join variables: a variable mentioned by ≥2 patterns. Only these connect
    // relations and are ever semijoined; a variable private to one pattern is irrelevant to
    // the reduction. Count the NUMBER OF PATTERNS mentioning each variable (a variable
    // repeated within a single pattern counts once for that pattern).
    let all_vars = collect_vars(patterns);
    let mut var_degree: FxHashMap<Variable, usize> = FxHashMap::default();
    for p in &prepared {
        let mut seen: FxHashSet<&Variable> = FxHashSet::default();
        for v in p.pos_vars.iter().flatten() {
            seen.insert(v);
        }
        for v in seen {
            *var_degree.entry(v.clone()).or_default() += 1;
        }
    }
    let is_join_var = |v: &Variable| var_degree.get(v).copied().unwrap_or(0) >= 2;

    // If NO variable is shared, the BGP is a pure cross product — there is nothing to
    // reduce. Defer to the binary plan (which builds the cross product directly).
    if !all_vars.iter().any(is_join_var) {
        return eval_bgp_binary(graph, patterns, pat_filters);
    }

    // Materialise each pattern's relation once (ordinary scan, no prefilter — the prepass
    // computes its own, sharper, multi-edge reduction). Then record each relation's
    // join-variable columns for the sweep, and assign each join variable a dense id for the
    // pure tree builder.
    let mut var_id: FxHashMap<Variable, u32> = FxHashMap::default();
    let mut relations: Vec<SjRelation> = Vec::with_capacity(prepared.len());
    for (idx, p) in prepared.iter().enumerate() {
        // A pushed-down sargable FILTER on this pattern is applied during materialisation
        // (its own column order for range-pruning), exactly as the binary plan does — so a
        // FILTERed pattern feeds only its passing rows into the reduction and the join.
        let filt = pfilter(idx);
        let sort_col = filt.map(|(c, _)| c);
        let bindings = scan_to_bindings(
            graph,
            &p.id_pat,
            &p.pos_vars,
            sort_col,
            filt,
            None,
            #[cfg(feature = "semijoin-bitmap")]
            None,
        );
        // An empty relation makes the whole acyclic BGP empty (every join is inner).
        if bindings.rows.is_empty() {
            return Ok(Bindings::unsorted(all_vars, vec![]));
        }
        let mut join_cols: Vec<(Variable, usize)> = Vec::new();
        for (col, v) in bindings.vars.iter().enumerate() {
            if is_join_var(v) {
                join_cols.push((v.clone(), col));
                let next = var_id.len() as u32;
                var_id.entry(v.clone()).or_insert(next);
            }
        }
        relations.push(SjRelation { bindings, join_cols });
    }

    // Build the join tree over the relations' join-variable id sets (pure topology).
    let rel_vars: Vec<Vec<u32>> = relations
        .iter()
        .map(|r| r.join_cols.iter().map(|(v, _)| var_id[v]).collect())
        .collect();
    let tree = crate::semijoin::build_join_tree(&rel_vars);

    // BOTTOM-UP sweep (children before parents): the tree nodes are in pre-order, so
    // iterating in REVERSE visits each child before its parent. Semijoin each parent with
    // each of its children on the shared join variables — drops parent rows with no child
    // partner. After this pass the root holds only rows that survive every downstream join.
    for ni in (0..tree.len()).rev() {
        let node = tree[ni];
        if node.is_root() {
            continue;
        }
        let parent_rel = tree[node.parent].rel;
        semijoin_reduce(&mut relations, parent_rel, node.rel);
        if relations[parent_rel].bindings.rows.is_empty() {
            return Ok(Bindings::unsorted(all_vars, vec![]));
        }
    }

    // TOP-DOWN sweep (parents before children): iterate FORWARD; semijoin each child with
    // its (already fully-reduced) parent. After this pass EVERY relation holds only rows
    // that participate in the final answer — no dangling tuples remain.
    for &node in &tree {
        if node.is_root() {
            continue;
        }
        let parent_rel = tree[node.parent].rel;
        semijoin_reduce(&mut relations, node.rel, parent_rel);
        if relations[node.rel].bindings.rows.is_empty() {
            return Ok(Bindings::unsorted(all_vars, vec![]));
        }
    }

    // Join the reduced relations. Order by the tree (parent before child) so each join has
    // a shared variable with the accumulated result whenever the component is connected;
    // the generic `join_bindings` handles the shared-variable merge/hash and the
    // cross-product across disconnected components. The result equals the binary plan's.
    let mut order: Vec<usize> = tree.iter().map(|n| n.rel).collect();
    // De-dup defensively (tree places each rel once, but keep the invariant explicit).
    order.dedup();
    let mut iter = order.into_iter();
    let first = iter.next().expect("≥2 relations on this path");
    let mut acc = std::mem::replace(
        &mut relations[first].bindings,
        Bindings::unsorted(vec![], vec![]),
    );
    for ri in iter {
        let rhs = std::mem::replace(
            &mut relations[ri].bindings,
            Bindings::unsorted(vec![], vec![]),
        );
        acc = join_bindings(acc, rhs);
        if acc.rows.is_empty() {
            break;
        }
    }
    Ok(acc)
}

/// Semijoin `relations[target] ⋉ relations[source]` IN PLACE: keep only the `target` rows
/// whose join-key values (on the variables `target` and `source` SHARE) appear in
/// `source`. Uses the exact `semijoin::KeyFilter` membership test (reused from A3) on each
/// shared variable; a row survives iff it passes on EVERY shared variable. Pure filter —
/// removes only rows that would fail the join, so the answer is unchanged.
#[cfg(feature = "yannakakis")]
fn semijoin_reduce(relations: &mut [SjRelation], target: usize, source: usize) {
    // Shared join variables and their (target_col, source_col) positions.
    let shared: Vec<(usize, usize)> = relations[target]
        .join_cols
        .iter()
        .filter_map(|(v, tcol)| {
            relations[source]
                .join_cols
                .iter()
                .find(|(sv, _)| sv == v)
                .map(|(_, scol)| (*tcol, *scol))
        })
        .collect();
    if shared.is_empty() {
        return; // not actually adjacent (disconnected component edge) — nothing to reduce.
    }
    // Build one exact membership filter per shared variable over the SOURCE's distinct key
    // values at that column. `KeyFilter::build` returns `None` only for an empty source —
    // but an empty relation short-circuits the whole BGP before we get here, so a present
    // source always yields a filter.
    let filters: Vec<(usize, crate::semijoin::KeyFilter)> = shared
        .iter()
        .filter_map(|&(tcol, scol)| {
            crate::semijoin::KeyFilter::build(relations[source].bindings.rows.iter().map(|r| r[scol]))
                .map(|kf| (tcol, kf))
        })
        .collect();
    if filters.len() != shared.len() {
        return; // defensive: a degenerate empty source — leave target unchanged.
    }
    relations[target]
        .bindings
        .rows
        .retain(|row| filters.iter().all(|(tcol, kf)| kf.contains(row[*tcol])));
    // A retain can break a previously-recorded sort order only by REMOVING rows, which
    // preserves the order of the survivors — so `sorted_by` (if any) stays valid. No reset
    // needed; the generic join re-derives sortedness as required.
}

// ---- Shared GOO planning decisions (executor + T22 EXPLAIN dry run) -----------
//
// The greedy-ordering decisions of `eval_bgp_binary` are factored into the small
// pure helpers below so EXPLAIN can REPLAY the planner without executing anything
// and without duplicating the logic (no drift): the executor calls them on its hot
// path (inlined, zero extra cost), the explain module replays them symbolically.

/// One BGP triple pattern prepared for planning: resolved constant ids, the
/// variable at each canonical position, and the index-range cardinality estimate.
pub(crate) struct Prepared {
    pub(crate) id_pat: IdPattern,
    pub(crate) pos_vars: [Option<Variable>; 3],
    pub(crate) est: usize,
    pub(crate) unsatisfiable: bool,
}

impl Prepared {
    /// Canonical position (0=s, 1=p, 2=o) of `v` in this pattern, if present.
    #[inline]
    pub(crate) fn var_pos(&self, v: &Variable) -> Option<usize> {
        self.pos_vars.iter().position(|pv| pv.as_ref() == Some(v))
    }
}

/// Prepares every pattern of a BGP for planning (constant resolution + estimates).
pub(crate) fn prepare_bgp(graph: &Graph, patterns: &[TriplePattern]) -> Result<Vec<Prepared>, String> {
    let mut prepared: Vec<Prepared> = Vec::with_capacity(patterns.len());
    for tp in patterns {
        let (id_pat, pos_vars, unsat) = prepare_pattern(graph, tp)?;
        let est = if unsat { 0 } else { graph.store.estimate(&id_pat) };
        prepared.push(Prepared { id_pat, pos_vars, est, unsatisfiable: unsat });
    }
    Ok(prepared)
}

/// The planner's estimated FINAL output cardinality of a conjunctive (BGP) subtree —
/// the same number the EXPLAIN dry-run prints as the last `est N rows`, computed by
/// REPLAYING the GOO loop (`goo_seed` → `goo_pick`) without executing anything. Used
/// only by the structured EXPLAIN (`explain-json`) to attach the BGP node's estimate
/// next to its ANALYZE actual-row count so the q-error is the engine's own estimate
/// vs reality (not a re-derived number). Returns `0.0` for an empty/unsatisfiable BGP.
/// [OPUS-4.8] sq-u4lgr
#[cfg(feature = "explain-json")]
pub(crate) fn bgp_estimate(graph: &Graph, p: &GraphPattern) -> Result<f64, String> {
    let mut patterns = Vec::new();
    let mut filters = Vec::new();
    flatten_conjunction(p, &mut patterns, &mut filters);
    let _ = &filters; // selectivity of post-join filters is not modelled (matches the dry run).
    if patterns.is_empty() {
        return Ok(0.0);
    }
    let prepared = prepare_bgp(graph, &patterns)?;
    if prepared.iter().any(|p| p.unsatisfiable) {
        return Ok(0.0);
    }
    if !bgp_uses_binary(&patterns) {
        // WCOJ (cyclic) path: the dry run does not print a single final estimate, so
        // approximate with the smallest single-pattern estimate (a conservative lower
        // bound the q-error treats like any other estimate).
        return Ok(prepared.iter().map(|p| p.est).min().unwrap_or(0) as f64);
    }
    let mut cs_ctx = CsCtx::new(&prepared);
    let seed = goo_seed(&prepared);
    let mut cur_card = prepared[seed].est as f64;
    let mut var_ndv: FxHashMap<Variable, f64> = FxHashMap::default();
    let mut done = vec![false; prepared.len()];
    done[seed] = true;
    cs_ctx.note_done(seed);
    record_pattern_ndv(graph, &prepared, seed, cur_card, &mut var_ndv, &cs_ctx);
    for _ in 2..=prepared.len() {
        let (i, new_card, _connected) = goo_pick(graph, &prepared, &done, &var_ndv, cur_card, &cs_ctx);
        cur_card = new_card;
        done[i] = true;
        cs_ctx.note_done(i);
        record_pattern_ndv(graph, &prepared, i, cur_card, &mut var_ndv, &cs_ctx);
    }
    Ok(cur_card.max(0.0))
}

/// GOO seed choice: the pattern with the smallest single-pattern cardinality.
pub(crate) fn goo_seed(prepared: &[Prepared]) -> usize {
    (0..prepared.len()).min_by_key(|&i| prepared[i].est).unwrap()
}

/// The seed scan's requested sort column: a pushed-down filter scans in its own
/// column's order (sequential numeric access); otherwise sort by the first seed
/// variable shared with another pattern, to enable a merge join.
pub(crate) fn goo_seed_sort(prepared: &[Prepared], seed: usize, filter_col: Option<usize>) -> Option<usize> {
    if filter_col.is_some() {
        return filter_col;
    }
    prepared[seed]
        .pos_vars
        .iter()
        .flatten()
        .find(|v| (0..prepared.len()).any(|j| j != seed && prepared[j].var_pos(v).is_some()))
        .and_then(|v| prepared[seed].var_pos(v))
}

/// The characteristic-set planning context (the opt-in `cs-planner` feature) the
/// GOO helpers consult for STAR joins: with a `crate::cs::CsTable` installed
/// (see [`crate::with_cs_table`]), candidate scoring and subject-variable ndv for
/// patterns of the star shape `?s <p> ?o` come from the CS table instead of the
/// per-predicate independence model. Without the feature this is a zero-sized
/// no-op; without an installed table every method is `None` and the `PredStat`
/// path runs unchanged. Either way, only JOIN ORDER is affected — never results.
pub(crate) struct CsCtx {
    #[cfg(feature = "cs-planner")]
    inner: Option<crate::cs::StarCtx>,
}

impl CsCtx {
    pub(crate) fn new(prepared: &[Prepared]) -> CsCtx {
        #[cfg(feature = "cs-planner")]
        {
            let inner = crate::cs::active().map(|table| {
                crate::cs::StarCtx::new(
                    table,
                    prepared.iter().map(|p| match (&p.pos_vars[0], p.id_pat) {
                        // The star shape: subject VARIABLE, bound predicate, unbound object.
                        (Some(v), [None, Some(pid), None]) => Some((v.clone(), pid)),
                        _ => None,
                    }),
                )
            });
            CsCtx { inner }
        }
        #[cfg(not(feature = "cs-planner"))]
        {
            let _ = prepared;
            CsCtx {}
        }
    }

    /// Marks pattern `i` joined, so later star estimates condition on it.
    #[inline]
    pub(crate) fn note_done(&mut self, i: usize) {
        #[cfg(feature = "cs-planner")]
        if let Some(s) = &mut self.inner {
            s.note_done(i);
        }
        #[cfg(not(feature = "cs-planner"))]
        let _ = i;
    }

    /// CS-based candidate output estimate (see `cs::StarCtx::pick_score`).
    #[inline]
    fn pick_score(&self, i: usize, cur_card: f64) -> Option<f64> {
        #[cfg(feature = "cs-planner")]
        {
            self.inner.as_ref().and_then(|s| s.pick_score(i, cur_card))
        }
        #[cfg(not(feature = "cs-planner"))]
        {
            let _ = (i, cur_card);
            None
        }
    }

    /// CS-based subject-variable ndv (see `cs::StarCtx::subject_ndv`).
    #[inline]
    fn subject_ndv(&self, i: usize) -> Option<f64> {
        #[cfg(feature = "cs-planner")]
        {
            self.inner.as_ref().and_then(|s| s.subject_ndv(i))
        }
        #[cfg(not(feature = "cs-planner"))]
        {
            let _ = i;
            None
        }
    }
}

/// Folds pattern `i`'s per-variable distinct-value estimates into the running
/// `var_ndv` map (each variable keeps its smallest — most selective — estimate,
/// capped by the running result cardinality). With a CS table installed, a star
/// pattern's SUBJECT variable uses the table's `Σ_{C ⊇ Q} count(C)` over the star
/// joined so far (call after `CsCtx::note_done`) instead of the `PredStat` marginal.
pub(crate) fn record_pattern_ndv(
    graph: &Graph,
    prepared: &[Prepared],
    i: usize,
    cur_card: f64,
    var_ndv: &mut FxHashMap<Variable, f64>,
    cs: &CsCtx,
) {
    let p = &prepared[i];
    for (pos, ov) in p.pos_vars.iter().enumerate() {
        if let Some(v) = ov {
            let raw = match pos {
                0 => cs.subject_ndv(i).unwrap_or_else(|| pattern_var_ndv(graph, &p.id_pat, pos, p.est)),
                _ => pattern_var_ndv(graph, &p.id_pat, pos, p.est),
            };
            let ndv = raw.min(cur_card.max(1.0));
            let e = var_ndv.entry(v.clone()).or_insert(ndv);
            *e = e.min(ndv);
        }
    }
}

/// One GOO step: the connected not-yet-joined pattern with the smallest estimated
/// join output (`|R| · |P| / max(ndv)` per shared variable), or — when nothing
/// connects — the smallest remaining pattern (cross product). Returns the chosen
/// pattern index, the updated result-cardinality estimate, and whether it was
/// connected. With a CS table installed, a star candidate's subject-variable
/// contribution is the table's conditional expansion `star(Q ∪ {p}) / star(Q)`
/// (predicate-correlation-aware) instead of the independence product; selectivity
/// over any OTHER shared variables keeps the independence model.
pub(crate) fn goo_pick(
    graph: &Graph,
    prepared: &[Prepared],
    done: &[bool],
    var_ndv: &FxHashMap<Variable, f64>,
    cur_card: f64,
    cs: &CsCtx,
) -> (usize, f64, bool) {
    let mut best: Option<(usize, f64)> = None;
    for i in 0..prepared.len() {
        if done[i] {
            continue;
        }
        let cs_score = cs.pick_score(i, cur_card);
        let mut sel = 1.0f64;
        let mut shared = cs_score.is_some();
        for (pos, ov) in prepared[i].pos_vars.iter().enumerate() {
            if let Some(v) = ov {
                // The subject variable of a CS-scored star candidate is already
                // accounted for by the conditional star estimate.
                if pos == 0 && cs_score.is_some() {
                    continue;
                }
                if let Some(&rndv) = var_ndv.get(v) {
                    shared = true;
                    let pndv = pattern_var_ndv(graph, &prepared[i].id_pat, pos, prepared[i].est);
                    sel /= rndv.max(pndv).max(1.0);
                }
            }
        }
        if !shared {
            continue;
        }
        let out = match cs_score {
            Some(star) => star * sel,
            None => cur_card * prepared[i].est as f64 * sel,
        };
        if best.is_none_or(|(_, bc)| out < bc) {
            best = Some((i, out));
        }
    }
    match best {
        Some((i, out)) => (i, out.max(0.0), true),
        None => {
            // Disconnected: smallest-cardinality remaining (cross product).
            let i = (0..prepared.len()).filter(|&j| !done[j]).min_by_key(|&j| prepared[j].est).unwrap();
            (i, cur_card * prepared[i].est as f64, false)
        }
    }
}

/// Estimated number of distinct values of the variable at canonical position
/// `pos` in a pattern, from the per-predicate characteristic stats. Falls back to
/// the pattern's cardinality (an upper bound) when the predicate is unbound or the
/// other terminal is bound (so the column is effectively keyed).
fn pattern_var_ndv(graph: &Graph, id_pat: &IdPattern, pos: usize, est: usize) -> f64 {
    let est = (est as f64).max(1.0);
    #[cfg(feature = "persistent-stats")]
    if let Some(ndv) = id_pat[1].and_then(|pid| crate::stats::predicate_ndv(pid, pos)) {
        return (ndv as f64).clamp(1.0, est);
    }
    let stat = id_pat[1].and_then(|pid| graph.store.pred_stat(pid));
    match (pos, stat) {
        // subject var, predicate bound, object unbound -> distinct subjects of P
        (0, Some(s)) if id_pat[2].is_none() => (s.ndv_subj as f64).clamp(1.0, est),
        // object var, predicate bound, subject unbound -> distinct objects of P
        (2, Some(s)) if id_pat[0].is_none() => (s.ndv_obj as f64).clamp(1.0, est),
        _ => est,
    }
}

// ---- [OPUS-4.8] (sq-iywur) DP join-order planner bridge -----------------------
//
// Builds the DP planner's `crate::dp::QueryGraph` from the prepared BGP patterns
// (reusing the SAME `pattern_var_ndv` estimator the greedy planner consumes), runs
// the DPccp enumerator, and evaluates the chosen bushy join tree. Both functions are
// only compiled under the opt-in `dp-planner` feature and are reached only when a
// planner is installed with `with_dp_planner`; the default build never sees them.

/// Plans and evaluates a BGP with the DP enumerator, or returns `None` to fall back
/// to greedy GOO (see `crate::dp::plan` for the fall-back conditions). The prepared
/// patterns are assumed already satisfiable (the caller short-circuits an
/// unsatisfiable BGP before this point).
#[cfg(feature = "dp-planner")]
fn eval_bgp_dp(
    graph: &Graph,
    prepared: &[Prepared],
    pat_filters: &[Option<(usize, ScanCmp)>],
    cfg: crate::dp::DpConfig,
) -> Option<Bindings> {
    let n = prepared.len();
    if !(2..=63).contains(&n) {
        return None;
    }
    // Dense-index every variable; record its pattern bitmask and per-pattern
    // distinct-value estimate (the join-selectivity input the greedy planner uses).
    let mut var_idx: FxHashMap<Variable, usize> = FxHashMap::default();
    let mut var_pats: Vec<u64> = Vec::new();
    let mut var_ndv: Vec<Vec<(usize, f64)>> = Vec::new();
    for (p, prep) in prepared.iter().enumerate() {
        for (pos, ov) in prep.pos_vars.iter().enumerate() {
            if let Some(v) = ov {
                let ndv = pattern_var_ndv(graph, &prep.id_pat, pos, prep.est);
                let k = *var_idx.entry(v.clone()).or_insert_with(|| {
                    var_pats.push(0);
                    var_ndv.push(Vec::new());
                    var_pats.len() - 1
                });
                var_pats[k] |= 1u64 << p;
                // A variable can appear at several positions of one pattern — keep its
                // most selective (smallest) per-pattern estimate.
                if let Some(e) = var_ndv[k].iter_mut().find(|(pp, _)| *pp == p) {
                    e.1 = e.1.min(ndv);
                } else {
                    var_ndv[k].push((p, ndv));
                }
            }
        }
    }
    let est: Vec<f64> = prepared.iter().map(|p| p.est as f64).collect();
    let qg = crate::dp::QueryGraph::build(est, var_pats, var_ndv);
    let tree = crate::dp::plan(&qg, cfg.max_subgraphs)?;
    Some(eval_join_tree(graph, prepared, &tree, pat_filters))
}

// ---- [FABLE-5] (sq-7d3dj.30.14) membership-cluster pre-materialisation ---------
//
// Given a `crate::cluster::ClusterPlan` partition of the BGP, evaluate the two
// sub-BGPs (the standalone {anchor, membership} cluster and the driver `rest`)
// INDEPENDENTLY with the ordinary greedy `eval_bgp_binary`, then NATURAL-JOIN them
// with the shared `join_bindings`. Both sides are evaluated UNCORRELATED, so the
// materialised cluster is the full union-compatible relation greedy would also have
// produced — there is no cross-site sideways-information hazard (there is only one
// evaluation of the cluster). A BGP is a commutative/associative natural join, so the
// result bag is IDENTICAL to the flat greedy plan for any partition — the win is
// purely that bounding the shared variable from the small anchor avoids driving the
// wide unbound-predicate relation per `rest` binding. Only compiled under the opt-in
// `cluster-materialize` feature.
//
// `pat_filters[i]` is a (COLUMN-position, cmp) pushed-down sargable filter for pattern
// `i`; the column position is intrinsic to the pattern (not a BGP-relative index), so
// re-slicing per sub-BGP needs no remapping. `detect` has already declined any cluster
// pattern that carries a filter, so a cluster pattern's slot is always `None` here; the
// `rest` slots carry through verbatim.
#[cfg(feature = "cluster-materialize")]
fn eval_bgp_cluster(
    graph: &Graph,
    patterns: &[TriplePattern],
    pat_filters: &[Option<(usize, ScanCmp)>],
    plan: &crate::cluster::ClusterPlan,
) -> Result<Bindings, String> {
    let sub = |idxs: &[usize]| -> (Vec<TriplePattern>, Vec<Option<(usize, ScanCmp)>>) {
        (
            idxs.iter().map(|&i| patterns[i].clone()).collect(),
            idxs.iter().map(|&i| pat_filters.get(i).copied().flatten()).collect(),
        )
    };
    let (cluster_pats, cluster_filts) = sub(&plan.cluster);
    let (rest_pats, rest_filts) = sub(&plan.rest);
    let cluster = eval_bgp_binary(graph, &cluster_pats, &cluster_filts)?;
    // An empty cluster makes the whole (inner) BGP empty — short-circuit like the
    // greedy loop does when a bind join empties the running result.
    if cluster.rows.is_empty() {
        return Ok(Bindings::unsorted(collect_vars(patterns), vec![]));
    }
    let rest = eval_bgp_binary(graph, &rest_pats, &rest_filts)?;
    Ok(join_bindings(cluster, rest))
}

/// Evaluates a DP `JoinTree`: a `Leaf` scans its pattern (applying any pushed-down
/// sargable filter, exactly like the greedy seed scan), a `Join` natural-joins the
/// two sub-results with the shared `join_bindings` (merge / hash / compatibility
/// nested-loop). The tree is bushy; `join_bindings` builds on the smaller side.
#[cfg(feature = "dp-planner")]
fn eval_join_tree(
    graph: &Graph,
    prepared: &[Prepared],
    tree: &crate::dp::JoinTree,
    pat_filters: &[Option<(usize, ScanCmp)>],
) -> Bindings {
    match tree {
        crate::dp::JoinTree::Leaf(i) => {
            let p = &prepared[*i];
            scan_to_bindings(
                graph,
                &p.id_pat,
                &p.pos_vars,
                None,
                pat_filters.get(*i).copied().flatten(),
                None,
                #[cfg(feature = "semijoin-bitmap")]
                None,
            )
        }
        crate::dp::JoinTree::Join(l, r) => {
            let left = eval_join_tree(graph, prepared, l, pat_filters);
            let right = eval_join_tree(graph, prepared, r, pat_filters);
            join_bindings(left, right)
        }
    }
}

pub(crate) fn collect_vars(patterns: &[TriplePattern]) -> Vec<Variable> {
    let mut vars = Vec::new();
    for tp in patterns {
        for v in [tp_var(&tp.subject), nnp_var(&tp.predicate), tp_var(&tp.object)].into_iter().flatten() {
            if !vars.contains(&v) {
                vars.push(v);
            }
        }
    }
    vars
}

// ---- Worst-case-optimal join: Leapfrog Triejoin ------------------------------
//
// LFTJ (Veldhuizen 2014) evaluates a BGP one *variable* at a time in a fixed
// global order. At each variable it intersects, via the "leapfrog" galloping
// search, the sorted value streams of every pattern that mentions that variable,
// then recurses. Each pattern is a trie of its variable columns (projected from a
// permutation index, sorted in the global variable order). The total work is
// bounded by the AGM fractional-edge-cover bound on the BGP, so for cyclic
// queries it cannot produce the asymptotically-large intermediates a binary plan
// would. See research/ARCHITECTURE.md §4.

// [OPUS-4.8] sq-hknqs (epic sq-qonbz, Phase 3): the LFTJ NAVIGATION — the `Trie`/`TrieIter`
// cursor (open-on-entry, galloping `seek`, binary-search `run_end`), the `Leapfrog`
// intersection and `lftj_recurse` — now lives in the shared substrate
// (`sparq_substrate::join::{Trie, TrieIter, lftj_recurse}`). The engine keeps only
// `build_trie` below (which OWNS the store scan + the zk-trace hook + the global-order
// projection) and `eval_bgp_wcoj`, which drives the substrate cursor with the engine's
// budget. The probe loop is monomorphic over `Id`/`Row` with no `Box<dyn>`.

/// Builds a pattern's trie of projected variable tuples, plus the global levels
/// of those variables (sorted ascending). Repeated-variable patterns keep only
/// rows where all positions of a variable agree.
fn build_trie(
    graph: &Graph,
    id_pat: &IdPattern,
    pos_vars: &[Option<Variable>; 3],
    var_levels: &FxHashMap<Variable, usize>,
) -> (sjoin::Trie, Vec<usize>) {
    let mut var_positions: Vec<(Variable, Vec<usize>)> = Vec::new();
    for (pos, ov) in pos_vars.iter().enumerate() {
        if let Some(v) = ov {
            if let Some(e) = var_positions.iter_mut().find(|(x, _)| x == v) {
                e.1.push(pos);
            } else {
                var_positions.push((v.clone(), vec![pos]));
            }
        }
    }
    var_positions.sort_by_key(|(v, _)| var_levels[v]);
    let levels: Vec<usize> = var_positions.iter().map(|(v, _)| var_levels[v]).collect();

    let scan = graph.store.scan(id_pat);
    let mut tuples: Vec<Vec<Id>> = Vec::with_capacity(scan.rows.len());
    // zk-trace hook: the WCOJ path's per-pattern input set is the trie's
    // source scan (the consistency-passing rows), recorded pre-projection.
    #[cfg(feature = "zk")]
    let mut zk_matched: Vec<[Id; 3]> = Vec::new();
    for row in scan.rows.iter() {
        let spo = scan.to_spo(row);
        let mut tup = Vec::with_capacity(var_positions.len());
        let mut ok = true;
        for (_, positions) in &var_positions {
            let v0 = spo[positions[0]];
            if positions.iter().any(|&p| spo[p] != v0) {
                ok = false;
                break;
            }
            tup.push(v0);
        }
        if ok {
            #[cfg(feature = "zk")]
            if crate::zk::enabled() {
                zk_matched.push(spo);
            }
            tuples.push(tup);
        }
    }
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        crate::zk::record_scan_ids(graph, id_pat, pos_vars, &zk_matched, false);
    }
    tuples.sort_unstable();
    tuples.dedup();
    (sjoin::Trie { tuples }, levels)
}

fn eval_bgp_wcoj(graph: &Graph, patterns: &[TriplePattern]) -> Result<Bindings, String> {
    // Prepare patterns; an unsatisfiable constant makes the whole BGP empty.
    let mut prepared: Vec<(IdPattern, [Option<Variable>; 3])> = Vec::with_capacity(patterns.len());
    for tp in patterns {
        let (id_pat, pos_vars, unsat) = prepare_pattern(graph, tp)?;
        if unsat {
            // zk-trace: record ONLY this provably-empty pattern (see the
            // binary path) — siblings are not proven empty here.
            #[cfg(feature = "zk")]
            if crate::zk::enabled() {
                crate::zk::record_empty_pattern(crate::zk::key_of_algebra_pattern(tp));
            }
            return Ok(Bindings::unsorted(collect_vars(patterns), vec![]));
        }
        prepared.push((id_pat, pos_vars));
    }

    // Global variable order: most-constrained first (highest degree, then most
    // selective). Constant-only patterns contribute no variables but must match.
    // (Shared with the T22 EXPLAIN dry run.)
    let order_vars = wcoj_global_order(graph, patterns, &prepared);
    let n_levels = order_vars.len();

    let var_levels: FxHashMap<Variable, usize> =
        order_vars.iter().enumerate().map(|(i, v)| (v.clone(), i)).collect();

    // Build a trie per pattern that has variables; check constant-only patterns
    // for existence (empty range => empty BGP).
    let mut tries: Vec<sjoin::Trie> = Vec::new();
    let mut trie_levels: Vec<Vec<usize>> = Vec::new();
    for (id_pat, pos_vars) in &prepared {
        if pos_vars.iter().all(|v| v.is_none()) {
            if graph.store.estimate(id_pat) == 0 {
                return Ok(Bindings::unsorted(order_vars, vec![]));
            }
            continue;
        }
        let (trie, levels) = build_trie(graph, id_pat, pos_vars, &var_levels);
        if trie.tuples.is_empty() {
            return Ok(Bindings::unsorted(order_vars, vec![]));
        }
        tries.push(trie);
        trie_levels.push(levels);
    }

    // No variables: BGP is a ground check that already succeeded.
    if n_levels == 0 {
        return Ok(Bindings { vars: vec![], rows: vec![Row::new()], sorted_by: None });
    }

    // Participating tries per global level.
    let mut parts_at_level: Vec<Vec<usize>> = vec![Vec::new(); n_levels];
    for (ti, levels) in trie_levels.iter().enumerate() {
        for &lvl in levels {
            parts_at_level[lvl].push(ti);
        }
    }

    // The LFTJ navigation (cursor + leapfrog intersection + recursion) is the shared substrate's
    // (sq-hknqs); the engine supplies the built tries, the per-level participation, and its
    // thread-local budget as the generic cooperative-cancel hook.
    let mut iters: Vec<sjoin::TrieIter> = tries.iter().map(sjoin::TrieIter::new).collect();
    let mut out: Vec<Row> = Vec::new();
    let mut current = vec![NO_ID; n_levels];
    sjoin::lftj_recurse(&mut iters, &parts_at_level, 0, n_levels, &mut current, &EngineBudget, &mut out);

    // Output rows are produced in global-order lexicographic order.
    let sorted_by = order_vars.first().cloned();
    Ok(Bindings { vars: order_vars, rows: out, sorted_by })
}

/// The Leapfrog-Triejoin global variable order: most-constrained variables first
/// (highest pattern degree, ties broken by the smallest estimate among the
/// patterns mentioning the variable). Shared by `eval_bgp_wcoj` and EXPLAIN.
pub(crate) fn wcoj_global_order(
    graph: &Graph,
    patterns: &[TriplePattern],
    prepared: &[(IdPattern, [Option<Variable>; 3])],
) -> Vec<Variable> {
    let degree = |v: &Variable| prepared.iter().filter(|(_, pv)| pv.iter().flatten().any(|x| x == v)).count();
    let min_est = |v: &Variable| {
        prepared
            .iter()
            .filter(|(_, pv)| pv.iter().flatten().any(|x| x == v))
            .map(|(ip, _)| graph.store.estimate(ip))
            .min()
            .unwrap_or(usize::MAX)
    };
    let mut order_vars = collect_vars(patterns);
    order_vars.sort_by(|a, b| degree(b).cmp(&degree(a)).then(min_est(a).cmp(&min_est(b))));
    order_vars
}

/// α-acyclicity test via GYO reduction: repeatedly drop variables that occur in
/// only one pattern and patterns whose variable set is contained in another.
/// A BGP is cyclic iff anything remains. Cyclic BGPs benefit from WCOJ.
fn bgp_is_cyclic(patterns: &[TriplePattern]) -> bool {
    let mut next_id = 0u32;
    let mut ids: FxHashMap<Variable, u32> = FxHashMap::default();
    let mut edges: Vec<std::collections::HashSet<u32>> = Vec::new();
    for tp in patterns {
        let mut e = std::collections::HashSet::new();
        for v in [tp_var(&tp.subject), nnp_var(&tp.predicate), tp_var(&tp.object)].into_iter().flatten() {
            let id = *ids.entry(v).or_insert_with(|| {
                let id = next_id;
                next_id += 1;
                id
            });
            e.insert(id);
        }
        if !e.is_empty() {
            edges.push(e);
        }
    }

    loop {
        let mut changed = false;

        // Drop variables occurring in exactly one edge.
        let mut count: FxHashMap<u32, usize> = FxHashMap::default();
        for e in &edges {
            for &v in e {
                *count.entry(v).or_default() += 1;
            }
        }
        for e in edges.iter_mut() {
            let before = e.len();
            e.retain(|v| count[v] > 1);
            if e.len() != before {
                changed = true;
            }
        }
        let before = edges.len();
        edges.retain(|e| !e.is_empty());
        if edges.len() != before {
            changed = true;
        }

        // Drop an edge contained in a distinct edge (also removes duplicates).
        let mut removed = None;
        'outer: for i in 0..edges.len() {
            for j in 0..edges.len() {
                if i != j && edges[i].is_subset(&edges[j]) {
                    removed = Some(i);
                    break 'outer;
                }
            }
        }
        if let Some(i) = removed {
            edges.remove(i);
            changed = true;
        }

        if !changed {
            break;
        }
    }

    !edges.is_empty()
}

fn prepare_pattern(graph: &Graph, tp: &TriplePattern) -> Result<(IdPattern, [Option<Variable>; 3], bool), String> {
    let mut id_pat: IdPattern = [None, None, None];
    let mut pos_vars: [Option<Variable>; 3] = [None, None, None];
    let mut unsat = false;

    // Resolves one (subject/object) position: variable -> pos_vars; blank node ->
    // synthetic variable; concrete term -> dictionary id (absent term => unsat).
    let mut bind_term = |slot: usize, tp: &TermPattern| -> Result<(), String> {
        match tp {
            TermPattern::Variable(v) => pos_vars[slot] = Some(v.clone()),
            TermPattern::BlankNode(b) => pos_vars[slot] = Some(bnode_var(b)),
            other => match graph.id_of(&term_pattern_to_term(other)?) {
                Some(id) => id_pat[slot] = Some(id),
                None => unsat = true,
            },
        }
        Ok(())
    };
    bind_term(0, &tp.subject)?;
    bind_term(2, &tp.object)?;

    match &tp.predicate {
        NamedNodePattern::Variable(v) => pos_vars[1] = Some(v.clone()),
        NamedNodePattern::NamedNode(n) => match graph.id_of(&Term::NamedNode(n.clone())) {
            Some(id) => id_pat[1] = Some(id),
            None => unsat = true,
        },
    }
    Ok((id_pat, pos_vars, unsat))
}

fn scan_to_bindings(
    graph: &Graph,
    id_pat: &IdPattern,
    pos_vars: &[Option<Variable>; 3],
    sort_col: Option<usize>,
    filter: Option<(usize, ScanCmp)>,
    limit: Option<usize>,
    // [OPUS-4.8] (sq-gr8mb / §A3) Optional semi-join prefilter: `(canonical position of
    // the connecting variable, membership filter over the other side's join keys)`. A
    // scanned row whose key at that position is ABSENT from the filter cannot match the
    // downstream join, so it is dropped before projection. The filter is membership-exact
    // (no false positives), so this never changes the RESULT — only fewer rows are kept.
    // Only present under the opt-in `semijoin-bitmap` feature, so the default build's
    // signature and per-row path are byte-identical.
    #[cfg(feature = "semijoin-bitmap")] prefilter: Option<(usize, &crate::semijoin::KeyFilter)>,
) -> Bindings {
    let mut vars: Vec<Variable> = Vec::new();
    let mut var_positions: Vec<Vec<usize>> = Vec::new();
    for (pos, v) in pos_vars.iter().enumerate() {
        if let Some(v) = v {
            if let Some(idx) = vars.iter().position(|x| x == v) {
                var_positions[idx].push(pos);
            } else {
                vars.push(v.clone());
                var_positions.push(vec![pos]);
            }
        }
    }
    let scan = match sort_col {
        Some(c) => graph.store.scan_sorted(id_pat, c),
        None => graph.store.scan(id_pat),
    };
    // The TRUE sort column is the first unbound canonical column in the chosen
    // permutation's order — NOT necessarily the requested `sort_col`: with fewer than
    // six permutations the store may not have the requested order, in which case the
    // engine must report the real one so merge joins fall back to hash and range-
    // pruning is skipped (both keyed off the truthful `sorted_by` / `actual_sort`).
    let actual_sort = scan.perm.order().into_iter().find(|&c| id_pat[c].is_none());
    let sorted_by = actual_sort.and_then(|c| pos_vars[c].clone());

    // Range-pruning: when the pushed-down filter is on the scan's ACTUAL sort column and
    // that column holds inline integers (which sort by value), binary-search to the
    // passing value range instead of scanning + filtering the whole relation. Safe
    // only when EVERY value in the column is inline (so no dictionary-encoded
    // numeric in another datatype, scattered below INLINE_BASE, is skipped).
    let mut scan_rows: &[[Id; 3]] = scan.rows.as_ref();
    if let Some((fpos, cmp)) = filter {
        if actual_sort == Some(fpos) && scan_rows.first().is_some_and(|r| dict::is_inline(scan.to_spo(r)[fpos])) {
            scan_rows = match inline_pass_values(cmp) {
                Some((lo, hi)) => {
                    let (lo_id, hi_id) = (dict::INLINE_BASE + lo, dict::INLINE_BASE + hi);
                    let start = scan_rows.partition_point(|r| scan.to_spo(r)[fpos] < lo_id);
                    let end = scan_rows.partition_point(|r| scan.to_spo(r)[fpos] <= hi_id);
                    &scan_rows[start..end]
                }
                None => &[],
            };
        }
    }

    // Per-row builder: apply the semi-join prefilter (if any) and the pushed-down
    // filter, then project (with the repeated-variable consistency check); `None`
    // drops the row.
    let build_row = |row: &[Id; 3]| -> Option<Row> {
        let spo = scan.to_spo(row);
        // [OPUS-4.8] (sq-gr8mb / §A3) Semi-join prefilter: drop a row whose connecting-
        // variable id is absent from the other side's join-key set — it cannot survive the
        // downstream join. EXACT membership, so the result is unchanged (only this wasted
        // row is skipped before projection). Checked first: it is the cheapest reject.
        #[cfg(feature = "semijoin-bitmap")]
        if let Some((jpos, kf)) = prefilter {
            if !kf.contains(spo[jpos]) {
                return None;
            }
        }
        if let Some((fpos, cmp)) = filter {
            if !cmp.test_id(graph, spo[fpos]) {
                return None;
            }
        }
        let mut out = Row::with_capacity(vars.len());
        for positions in &var_positions {
            let v0 = spo[positions[0]];
            if positions.iter().any(|&p| spo[p] != v0) {
                return None;
            }
            out.push(v0);
        }
        Some(out)
    };

    // zk-trace hook (feature `zk`, armed recorder only): record the matched
    // triples of this pattern scan — the rows `build_row` keeps, BEFORE
    // projection (the witness needs whole triples, not just variable columns).
    // One `enabled()` check per scan; zero per-row cost when disarmed.
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        let kept: Vec<[Id; 3]> = scan_rows
            .iter()
            .filter(|r| build_row(r).is_some())
            .map(|r| scan.to_spo(r))
            .collect();
        crate::zk::record_scan_ids(graph, id_pat, pos_vars, &kept, false);
    }

    // No LIMIT and a large relation: build the rows in parallel (order-preserving).
    #[cfg(feature = "parallel")]
    if limit.is_none() && scan_rows.len() >= PAR_THRESHOLD {
        use rayon::prelude::*;
        let rows: Vec<Row> = scan_rows.par_iter().filter_map(build_row).collect();
        return Bindings { vars, rows, sorted_by };
    }

    // Reserve only up to the LIMIT so a small LIMIT over a huge scan does not
    // allocate for the whole relation (the point of early termination).
    let cap = limit.map_or(scan_rows.len(), |n| n.min(scan_rows.len()));
    let mut rows: Vec<Row> = Vec::with_capacity(budget::cap_alloc(cap));
    for (i, row) in scan_rows.iter().enumerate() {
        // Coarse budget check every 4096 scanned rows.
        if i & 4095 == 0 && budget::exhausted(rows.len()) {
            break;
        }
        if let Some(out) = build_row(row) {
            rows.push(out);
            // LIMIT early-termination: stop scanning once we have enough rows.
            if let Some(n) = limit {
                if rows.len() >= n {
                    break;
                }
            }
        }
    }
    Bindings { vars, rows, sorted_by }
}

fn merge_join(left: Bindings, right: Bindings, jv: &Variable) -> Bindings {
    let lk = left.col(jv).unwrap();
    let rk = right.col(jv).unwrap();
    let mut out_vars = left.vars.clone();
    let mut right_only: Vec<usize> = Vec::new();
    let mut extra_shared: Vec<(usize, usize)> = Vec::new();
    for (ri, v) in right.vars.iter().enumerate() {
        match left.col(v) {
            Some(li) if v != jv => extra_shared.push((li, ri)),
            Some(_) => {}
            None => {
                out_vars.push(v.clone());
                right_only.push(ri);
            }
        }
    }
    // The sorted-merge probe loop lives in the shared substrate (sq-hknqs); the engine supplies
    // the `Bindings`-derived key columns + its thread-local query budget, monomorphically.
    let mut rows = Vec::new();
    sjoin::merge_join(&left.rows, lk, &right.rows, rk, &extra_shared, &right_only, &EngineBudget, &mut rows);
    Bindings { vars: out_vars, rows, sorted_by: Some(jv.clone()) }
}

/// Layout for combining two bindings: shared (left col, right col) pairs and the
/// right-only columns appended after left's vars.
fn join_layout(left: &Bindings, right: &Bindings) -> (Vec<Variable>, Vec<(usize, usize)>, Vec<usize>) {
    let mut out_vars = left.vars.clone();
    let mut shared = Vec::new();
    let mut right_only = Vec::new();
    for (ri, v) in right.vars.iter().enumerate() {
        match left.col(v) {
            Some(li) => shared.push((li, ri)),
            None => {
                out_vars.push(v.clone());
                right_only.push(ri);
            }
        }
    }
    (out_vars, shared, right_only)
}

// [OPUS-4.8] sq-hknqs (epic sq-qonbz, Phase 3): the id-tuple combine/compatibility helpers
// (`compatible` / `merge_rows` / `any_unbound`) now live in the shared substrate
// (`sparq_substrate::join`). The engine's OPTIONAL / UNION / MINUS / VALUES-UNDEF nested-loop
// fallbacks and the hash-join build/probe call them under these private aliases, so every
// existing `Bindings`-side call site is unchanged.
use sjoin::{any_unbound, compatible, merge_rows};
// The join hash (`key_hash` / `JOIN_PARTS`) is only reached by the radix-partitioned PARALLEL
// hash-join build (native only); the wasm / serial build computes the table without them.
#[cfg(feature = "parallel")]
use sjoin::{key_hash, JOIN_PARTS};

fn hash_join(left: Bindings, right: Bindings) -> Bindings {
    // Build the hash table on the smaller side.
    let (build, probe) = if left.rows.len() <= right.rows.len() {
        (left, right)
    } else {
        (right, left)
    };
    // Shared vars relative to (build, probe).
    let shared: Vec<(usize, usize)> = build
        .vars
        .iter()
        .enumerate()
        .filter_map(|(bi, v)| probe.col(v).map(|pi| (bi, pi)))
        .collect();
    let mut out_vars = build.vars.clone();
    let probe_only: Vec<usize> = probe
        .vars
        .iter()
        .enumerate()
        .filter(|(_, v)| !build.vars.contains(v))
        .map(|(i, v)| {
            out_vars.push(v.clone());
            i
        })
        .collect();
    // The join column layout for the shared substrate kernel: `key_cols` are the (build, probe)
    // shared-variable index pairs (the equi-join key); the probe-only columns are appended after
    // the build row. The build/probe phases below are the substrate's `build_*` / `probe_emit`
    // (sq-hknqs) — the engine only supplies this `Bindings`-derived layout and its budget.
    let keys = sjoin::JoinKeys { key_cols: shared.clone(), right_only: Vec::new() };
    // Build phase. Above PAR_THRESHOLD the build is radix-partitioned (Tier-1 #5 of
    // research/parallelism-scaling.md): rows are tagged with their key-hash partition in
    // parallel, then each partition builds its private map lock-free. Within a partition rows
    // are scanned in ascending index, so each posting list stays in ascending build-row order —
    // exactly the serial build — and the probe output is byte-identical.
    // JoinTable = hashbrown::HashMap<Key, Posting, FxBuildHasher>; the type inference here
    // avoids a dependency on rustc_hash::FxHashMap in the type annotation. [SONNET-4.6] sq-7d3dj.19
    #[cfg(feature = "parallel")]
    let tables = if build.rows.len() >= PAR_THRESHOLD {
        use rayon::prelude::*;
        let parts: Vec<u8> = build
            .rows
            .par_iter()
            .map(|row| (key_hash(&keys.left_key(row)) % JOIN_PARTS as u64) as u8)
            .collect();
        sjoin::build_partitioned(&build.rows, &keys, &parts)
    } else {
        vec![sjoin::build_table(&build.rows, &keys)]
    };
    #[cfg(not(feature = "parallel"))]
    let tables = vec![sjoin::build_table(&build.rows, &keys)];
    // The probe is read-only over the (partitioned) table, so for a large probe side build the
    // output in parallel on native.
    #[cfg(feature = "parallel")]
    if probe.rows.len() >= PAR_THRESHOLD {
        use rayon::prelude::*;
        // Budget snapshot for the workers (the installing thread's thread-local is
        // invisible to them): a worker that hits the limits stops adding to its own
        // accumulator; the caller's next on-thread check raises the actual error.
        let snap = EngineSnapshot(budget::snapshot());
        let rows: Vec<Row> = probe
            .rows
            .par_iter()
            .fold(Vec::new, |mut acc, prow| {
                if !sjoin::BudgetSnapshot::hit(&snap, acc.len()) {
                    sjoin::probe_emit(prow, &keys, &build.rows, &tables, &probe_only, &mut acc);
                }
                acc
            })
            .reduce(Vec::new, |mut a, mut b| {
                a.append(&mut b);
                a
            });
        let _ = budget::exhausted(rows.len()); // sticky gate on the combined size
        return Bindings::unsorted(out_vars, rows);
    }
    let mut rows = Vec::new();
    sjoin::hash_probe_serial(&probe.rows, &keys, &build.rows, &tables, &probe_only, &EngineBudget, &mut rows);
    Bindings::unsorted(out_vars, rows)
}

/// Index-nested-loop join of a (small) `result` with a single triple pattern on one
/// shared variable: groups the result by the join value, and for each distinct value
/// looks up the pattern's matches with that variable BOUND (a binary-search range on a
/// permutation index) — so a large, selective pattern is never fully scanned. The
/// pattern must have distinct variables; a pushed-down sargable filter is applied inline.
fn bind_join(
    graph: &Graph,
    result: Bindings,
    id_pat: &IdPattern,
    pos_vars: &[Option<Variable>; 3],
    rk: usize,
    pp: usize,
    filt: Option<(usize, ScanCmp)>,
) -> Bindings {
    // The pattern's NEW variable columns (every variable position except the join one;
    // the only shared variable is the join variable, so the rest are new).
    let new_positions: Vec<usize> = (0..3).filter(|&p| p != pp && pos_vars[p].is_some()).collect();
    let mut out_vars = result.vars.clone();
    for &p in &new_positions {
        out_vars.push(pos_vars[p].clone().unwrap());
    }

    // [GPT-6-ASTRA] Verify metadata candidates without allocating: stale sortedness
    // must not split a key across runs and repeat scans (or accumulate duplicate zk
    // matches). Unsorted bags keep the existing hash grouping. The identity index
    // vector keeps the shared, monomorphic slice-based combine API simple while
    // avoiding a separate Vec allocation for every already-sorted distinct key.
    let nrows = result.rows.len();
    let presorted = result.sorted_by.as_ref().is_some_and(|sv| result.vars.get(rk) == Some(sv))
        && result.rows.windows(2).all(|pair| pair[0][rk] <= pair[1][rk]);
    #[cfg(test)]
    bind_join_run_grouping::observe_strategy(presorted);
    let order: Vec<usize> = if presorted { (0..nrows).collect() } else { Vec::new() };
    let mut groups: FxHashMap<Id, Vec<usize>> = FxHashMap::default();
    if !presorted {
        for (ri, row) in result.rows.iter().enumerate() {
            groups.entry(row[rk]).or_default().push(ri);
        }
    }

    debug_assert!(order.is_empty() || groups.is_empty());
    // Cow lets both strategies share the same scan/filter/budget body without copying
    // run slices or retaining owned hash-group vectors after their iteration.
    let mut start = 0usize;
    let runs = std::iter::from_fn(|| {
        if start == order.len() {
            return None;
        }
        let val = result.rows[order[start]][rk];
        let mut end = start + 1;
        while end < order.len() && result.rows[order[end]][rk] == val {
            end += 1;
        }
        let ris = &order[start..end];
        start = end;
        Some((val, std::borrow::Cow::Borrowed(ris)))
    });
    let hashed = groups.into_iter().map(|(val, ris)| (val, std::borrow::Cow::Owned(ris)));

    let mut out_rows: Vec<Row> = Vec::new();
    // zk-trace hook: accumulate the matched triples across all bound rescans
    // of this pattern (recorded once, under the pattern's ORIGINAL key, so
    // the input set merges with any full scans of the same pattern).
    #[cfg(feature = "zk")]
    let mut zk_matched: Vec<[Id; 3]> = Vec::new();
    for (val, ris) in runs.chain(hashed) {
        // Coarse budget check once per distinct join value.
        if budget::exhausted(out_rows.len()) {
            break;
        }
        let mut bound = *id_pat;
        bound[pp] = Some(val);
        #[cfg(test)]
        bind_join_run_grouping::observe_scan();
        let scan = graph.store.scan(&bound);
        for prow in scan.rows.iter() {
            let pspo = scan.to_spo(prow);
            if let Some((fpos, cmp)) = filt {
                if !cmp.test_id(graph, pspo[fpos]) {
                    continue;
                }
            }
            #[cfg(feature = "zk")]
            if crate::zk::enabled() {
                zk_matched.push(pspo);
            }
            let new_vals: SmallVec<[Id; 4]> = new_positions.iter().map(|&p| pspo[p]).collect();
            // The per-(result-row, match) combine is the shared substrate's `bind_combine`
            // (sq-hknqs): the scan + filter pushdown above stay engine-private (they own the
            // store + `ScanCmp`); only the id-tuple combine is shared.
            sjoin::bind_combine(&result.rows, &ris, &new_vals, &mut out_rows);
        }
    }
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        crate::zk::record_scan_ids(graph, id_pat, pos_vars, &zk_matched, true);
    }
    Bindings::unsorted(out_vars, out_rows)
}

/// Bag equivalence, bounded per-key scans, and real-query reachability for bind-join
/// grouping. Test-only counters observe the chosen path without depending on hash-map
/// iteration order; the randomized oracle is independent of either grouping strategy.
/// [SONNET-4.6] [GPT-6-ASTRA]
#[cfg(test)]
mod bind_join_run_grouping {
    use super::*;
    use oxrdf::NamedNode;

    // Thread-local observation keeps parallel tests independent and compiles out of
    // production. Small reachability fixtures execute on the calling thread.
    std::thread_local! {
        static OBSERVED: std::cell::Cell<(usize, usize, usize)> = const {
            std::cell::Cell::new((0, 0, 0))
        };
    }

    pub(super) fn observe_strategy(presorted: bool) {
        OBSERVED.with(|state| {
            let (runs, hashed, scans) = state.get();
            state.set((runs + usize::from(presorted), hashed + usize::from(!presorted), scans));
        });
    }

    pub(super) fn observe_scan() {
        OBSERVED.with(|state| {
            let (runs, hashed, scans) = state.get();
            state.set((runs, hashed, scans + 1));
        });
    }

    fn take_observed() -> (usize, usize, usize) {
        OBSERVED.with(|state| state.replace((0, 0, 0)))
    }

    /// `ex:n2` carries TWO ages, so one run must fan out to two matches.
    const TTL: &str = "@prefix ex: <http://ex/> .\n\
        ex:n1 ex:age 10 .\n\
        ex:n2 ex:age 20 .\n\
        ex:n2 ex:age 21 .\n\
        ex:n3 ex:age 30 .\n";

    fn id(g: &Graph, iri: &str) -> Id {
        g.dict.lookup(&Term::NamedNode(NamedNode::new(iri).unwrap()))
    }

    /// Runs `bind_join` of `result` (one column `?k`, subject position) with
    /// `?k ex:age ?v`, returning the output `(k, v)` pairs in emission order.
    fn run(g: &Graph, rows: Vec<Row>, sorted_by: Option<Variable>) -> Vec<(Id, Id)> {
        let k = Variable::new("k").unwrap();
        let v = Variable::new("v").unwrap();
        let result = Bindings { vars: vec![k.clone()], rows, sorted_by };
        let id_pat: IdPattern = [None, Some(id(g, "http://ex/age")), None];
        let pos_vars = [Some(k), None, Some(v)];
        let out = bind_join(g, result, &id_pat, &pos_vars, 0, 0, None);
        assert_eq!(out.vars.len(), 2, "join var + the new object var");
        assert!(out.sorted_by.is_none(), "preserve the existing output metadata contract");
        out.rows.iter().map(|r| (r[0], r[1])).collect()
    }

    /// The expected bag: every result row paired with every `ex:age` object of its subject.
    fn expected(g: &Graph, subjects: &[Id]) -> Vec<(Id, Id)> {
        let ages: Vec<(Id, Id)> = ["http://ex/n1", "http://ex/n2", "http://ex/n2", "http://ex/n3"]
            .iter()
            .zip(["10", "20", "21", "30"])
            .map(|(s, a)| {
                (id(g, s), g.dict.lookup_lit(a, "http://www.w3.org/2001/XMLSchema#integer", None))
            })
            .collect();
        let mut out: Vec<(Id, Id)> =
            subjects.iter().flat_map(|&s| ages.iter().filter(move |(a, _)| *a == s).copied()).collect();
        out.sort_unstable();
        out
    }

    #[test]
    fn scrambled_result_hash_grouping_preserves_the_bag() {
        let g = Graph::load_str(TTL, "turtle").unwrap();
        // Scrambled join values, with `n1` DUPLICATED: the duplicate must be emitted twice
        // (one group, two result rows) — this is the multiplicity a bag join owes.
        let subjects = [id(&g, "http://ex/n3"), id(&g, "http://ex/n1"), id(&g, "http://ex/n2"), id(&g, "http://ex/n1")];
        let rows: Vec<Row> = subjects.iter().map(|&s| Row::from_slice(&[s])).collect();
        take_observed();
        let got = run(&g, rows, None);
        assert_eq!(take_observed(), (0, 1, 3));

        assert_eq!(got.len(), 5, "n1 twice, n2 twice (two ages), n3 once: {:?}", got);
        let mut sorted = got.clone();
        sorted.sort_unstable();
        assert_eq!(sorted, expected(&g, &subjects), "output bag must match the per-row expansion");

    }

    #[test]
    fn presorted_result_takes_the_no_sort_path_with_the_same_bag() {
        let g = Graph::load_str(TTL, "turtle").unwrap();
        // Verified ascending on `?k`: run grouping must preserve the same bag.
        let mut subjects = [id(&g, "http://ex/n3"), id(&g, "http://ex/n1"), id(&g, "http://ex/n2"), id(&g, "http://ex/n1")];
        subjects.sort_unstable();
        let rows: Vec<Row> = subjects.iter().map(|&s| Row::from_slice(&[s])).collect();
        take_observed();
        let got = run(&g, rows, Some(Variable::new("k").unwrap()));
        assert_eq!(take_observed(), (1, 0, 3));

        let mut sorted = got.clone();
        sorted.sort_unstable();
        assert_eq!(sorted, expected(&g, &subjects));
        assert!(got.windows(2).all(|w| w[0].0 <= w[1].0), "{:?}", got);
    }

    #[test]
    fn stale_sorted_by_uses_hash_grouping_and_scans_each_key_once() {
        let g = Graph::load_str(TTL, "turtle").unwrap();
        let mut keys = [id(&g, "http://ex/n1"), id(&g, "http://ex/n2")];
        keys.sort_unstable();
        // Alternation guarantees stale metadata regardless of dictionary-id assignment.
        // Repeated matches must not be accumulated once per split run by zk tracing.
        let subjects: Vec<Id> = (0..128).map(|i| keys[i % 2]).collect();
        let rows = subjects.iter().map(|&s| Row::from_slice(&[s])).collect();
        take_observed();
        let mut got = run(&g, rows, Some(Variable::new("k").unwrap()));
        assert_eq!(take_observed(), (0, 1, 2));
        got.sort_unstable();
        assert_eq!(got, expected(&g, &subjects));
    }

    const SORTED_QUERY: &str = "PREFIX ex: <http://ex/> SELECT ?key ?rank ?value WHERE {
        ?key ex:seed ?rank . ?key ex:payload ?value . }";
    const HASH_QUERY: &str = "PREFIX ex: <http://ex/> SELECT ?key ?rank ?value WHERE {
        ?key ex:seed ?rank . ?key ex:payload ?value . FILTER(?rank >= 0) }";

    fn query_graph() -> Graph {
        let mut ttl = String::from("@prefix ex: <http://ex/> .\n");
        for key in 0..1024 {
            ttl.push_str(&format!("ex:k{key} ex:payload {}, {} .\n", 2 * key, 2 * key + 1));
            if key < 32 {
                // Rank order differs from key order; the filter chooses the rank scan.
                ttl.push_str(&format!("ex:k{key} ex:seed {} .\n", 31 - key));
            }
        }
        Graph::load_str(&ttl, "turtle").unwrap()
    }

    fn query_bag(result: crate::QueryResult) -> Vec<String> {
        let mut bag: Vec<String> = result.rows.iter().map(|row| format!("{row:?}")).collect();
        bag.sort_unstable();
        bag
    }

    #[test]
    fn sparql_seed_scan_reaches_verified_runs_and_filter_scan_reaches_hash_fallback() {
        let g = query_graph();
        take_observed();
        let sorted = crate::query(&g, SORTED_QUERY).unwrap();
        assert_eq!(take_observed(), (1, 0, 32), "shared-key seed scan must reach run grouping");
        assert_eq!(sorted.rows.len(), 64, "each seed has two payload matches");
        take_observed();
        let hashed = crate::query(&g, HASH_QUERY).unwrap();
        assert_eq!(take_observed(), (0, 1, 32), "rank-filter seed scan must reach hash grouping");
        assert_eq!(query_bag(sorted), query_bag(hashed));
    }

    #[test]
    fn sparql_join_budget_fails_instead_of_returning_a_partial_bag() {
        let g = query_graph();
        let limit = crate::QueryBudget { max_rows: Some(40), ..crate::QueryBudget::unlimited() };
        for (query, expected_path) in [(SORTED_QUERY, (1, 0)), (HASH_QUERY, (0, 1))] {
            take_observed();
            let err = crate::query_with_budget(&g, query, &limit).unwrap_err();
            assert_eq!(err, "query budget exceeded (max-rows)");
            let (runs, hashed, _) = take_observed();
            assert_eq!((runs, hashed), expected_path, "the seed fits; join fan-out trips the budget");
            assert_eq!(crate::query(&g, query).unwrap().rows.len(), 64, "budget state must not leak");
        }
    }

    // ---------------------------------------------------------------------------------
    // Randomized differential vs a grouping-free reference join.
    // ---------------------------------------------------------------------------------

    /// Which output the faulty reference drops. Each variant is a way the run grouping
    /// could silently lose bag cardinality, and the differential MUST go red against it —
    /// otherwise the comparison below proves nothing.
    #[derive(Clone, Copy)]
    enum Fault {
        /// Honest reference.
        None,
        /// Emit a join value's matches for its FIRST result row only — loses the
        /// multiplicity a duplicated result row owes.
        DropDuplicateRows,
        /// Skip one whole join value — loses a group.
        DropOneGroup,
        /// Keep one match per result row — loses the multi-match fan-out.
        DropExtraMatches,
    }

    /// Reference join with NEITHER grouping strategy: one full scan of the pattern, then a
    /// nested loop over the result rows. Independent of both the old `FxHashMap` grouping
    /// and the new sorted-run walk, so agreement with it is real evidence about the bag. It
    /// also reaches the store differently — ONE unbound-subject scan, against `bind_join`'s
    /// per-value BOUND binary-search ranges — so that probe is cross-checked as well.
    /// Rows are `[payload, k, v]`, returned sorted so callers compare MULTISETS rather than
    /// emission order.
    fn naive_bind_join(g: &Graph, rows: &[Row], age: Id, fault: Fault) -> Vec<[Id; 3]> {
        let pat: IdPattern = [None, Some(age), None];
        let scan = g.store.scan(&pat);
        let triples: Vec<[Id; 3]> = scan.rows.iter().map(|r| scan.to_spo(r)).collect();
        let mut out: Vec<[Id; 3]> = Vec::new();
        let mut emitted_keys: Vec<Id> = Vec::new();
        let mut victim: Option<Id> = None;
        for row in rows {
            let key = row[1];
            let mut objs: Vec<Id> =
                triples.iter().filter(|t| t[0] == key).map(|t| t[2]).collect();
            if objs.is_empty() {
                continue;
            }
            match fault {
                Fault::None => {}
                Fault::DropDuplicateRows => {
                    if emitted_keys.contains(&key) {
                        continue;
                    }
                    emitted_keys.push(key);
                }
                Fault::DropOneGroup => {
                    if *victim.get_or_insert(key) == key {
                        continue;
                    }
                }
                Fault::DropExtraMatches => objs.truncate(1),
            }
            objs.sort_unstable();
            out.extend(objs.into_iter().map(|v| [row[0], key, v]));
        }
        out.sort_unstable();
        out
    }

    /// `bind_join` of a two-column result `(?p, ?k)` — the join column is NOT column 0, so
    /// the run walk's index arithmetic is exercised too — with `?k ex:age ?v`. Returns the
    /// output rows sorted, for multiset comparison.
    fn run_multiset(g: &Graph, rows: Vec<Row>, age: Id, sorted: bool) -> Vec<[Id; 3]> {
        let p = Variable::new("p").unwrap();
        let k = Variable::new("k").unwrap();
        let v = Variable::new("v").unwrap();
        let sorted_by = sorted.then(|| k.clone());
        let result = Bindings { vars: vec![p, k.clone()], rows, sorted_by };
        let id_pat: IdPattern = [None, Some(age), None];
        let pos_vars = [Some(k), None, Some(v)];
        let out = bind_join(g, result, &id_pat, &pos_vars, 1, 0, None);
        let mut got: Vec<[Id; 3]> = out.rows.iter().map(|r| [r[0], r[1], r[2]]).collect();
        got.sort_unstable();
        got
    }

    /// xorshift64 — a deterministic generator, so a failure reproduces from its seed
    /// (the workspace has no test-only `rand` dependency, and CI must not flake).
    struct Rng(u64);

    impl Rng {
        fn below(&mut self, n: u64) -> u64 {
            self.0 ^= self.0 << 13;
            self.0 ^= self.0 >> 7;
            self.0 ^= self.0 << 17;
            self.0 % n
        }
    }

    /// The result-equivalence obligation for the run-grouping rewrite: over randomized
    /// graphs and result bags, `bind_join` must agree as a MULTISET with the grouping-free
    /// reference — on the hash fallback branch (`sorted_by: None`) and on the presorted branch
    /// (truthfully sorted rows plus matching `sorted_by`) alike.
    ///
    /// The generated domain spans what the finding asks for: empty graphs and empty result
    /// bags; subjects with 0 / 1 / 2-3 `ex:age` objects (no match, singleton, multi-match
    /// fan-out); a payload column drawn from a tiny pool so IDENTICAL duplicate rows occur
    /// and their multiplicity is checked; mostly-singleton high-NDV groups; real subject ids
    /// that have no `ex:age` triple; and `NO_ID` join values from rows naming a subject the
    /// graph never mentions.
    #[test]
    fn randomized_differential_vs_naive_reference() {
        // Per-fault detection counts: a control that never fires would make the
        // differential vacuous, so each must be exercised at least once.
        let mut caught = [0usize; 3];
        let mut total_out = 0usize;
        let mut stale_cases = 0usize;
        for seed in 1u64..=64 {
            let mut rng = Rng(seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1);
            let n_subj = rng.below(12) as usize; // 0 → an empty graph
            let mut ttl = String::from("@prefix ex: <http://ex/> .\n");
            for s in 0..n_subj {
                // 0 ages → a real id with no match; 2-3 → the multi-match fan-out.
                for a in 0..rng.below(4) {
                    ttl.push_str(&format!("ex:n{} ex:age {} .\n", s, 100 * s as u64 + a));
                }
                // Keeps `ex:n{s}` in the dictionary even with zero ages.
                ttl.push_str(&format!("ex:n{} ex:name \"n{}\" .\n", s, s));
            }
            let g = Graph::load_str(&ttl, "turtle").unwrap();
            let age = id(&g, "http://ex/age");

            let n_rows = rng.below(20) as usize; // 0 → an empty result bag
            let pool = (n_subj + 3) as u64; // the last 3 are absent → NO_ID join values
            let mut rows: Vec<Row> = Vec::new();
            for _ in 0..n_rows {
                let s = rng.below(pool);
                let key = id(&g, &format!("http://ex/n{}", s));
                // Payload from a 3-value pool, so identical rows repeat.
                rows.push(Row::from_slice(&[rng.below(3) as Id + 1, key]));
            }

            let want = naive_bind_join(&g, &rows, age, Fault::None);
            total_out += want.len();

            // The hash fallback branch: scrambled rows, no sortedness claimed.
            let got = run_multiset(&g, rows.clone(), age, false);
            assert_eq!(got, want, "hash branch, seed {}", seed);

            // Claimed sortedness over the original random bag must be checked. Stale
            // candidates fall back and still scan each distinct key only once.
            let is_sorted = rows.windows(2).all(|pair| pair[0][1] <= pair[1][1]);
            let distinct = rows.iter().map(|row| row[1]).collect::<std::collections::BTreeSet<_>>().len();
            take_observed();
            assert_eq!(run_multiset(&g, rows.clone(), age, true), want, "claimed-sorted branch, seed {}", seed);
            assert_eq!(take_observed(), (usize::from(is_sorted), usize::from(!is_sorted), distinct));
            stale_cases += usize::from(!is_sorted);

            // The no-sort branch: truthfully sorted rows WITH matching metadata. The
            // reference is row-order-independent, so the same `want` applies.
            let mut asc = rows.clone();
            asc.sort_by_key(|r| r[1]);
            assert_eq!(run_multiset(&g, asc, age, true), want, "presorted branch, seed {}", seed);

            // Controls: a reference that drops a duplicate row, a group, or an extra match
            // must be REJECTED by the very comparison that just passed.
            for (i, fault) in
                [Fault::DropDuplicateRows, Fault::DropOneGroup, Fault::DropExtraMatches]
                    .into_iter()
                    .enumerate()
            {
                let faulty = naive_bind_join(&g, &rows, age, fault);
                if faulty != want {
                    assert_ne!(got, faulty, "differential must reject fault {}, seed {}", i, seed);
                    caught[i] += 1;
                }
            }
        }
        assert!(total_out > 0, "the generated corpus produced no output rows at all");
        assert!(stale_cases > 0, "the randomized corpus must exercise stale metadata");
        for (i, n) in caught.iter().enumerate() {
            assert!(*n > 0, "control fault {} never fired — the differential is vacuous", i);
        }
    }
}

fn cross_product(left: Bindings, right: Bindings) -> Bindings {
    let mut out_vars = left.vars.clone();
    out_vars.extend(right.vars.iter().cloned());
    let mut rows = Vec::with_capacity(budget::cap_alloc(left.rows.len().saturating_mul(right.rows.len())));
    for l in &left.rows {
        // Coarse budget check once per left row.
        if budget::exhausted(rows.len()) {
            break;
        }
        for r in &right.rows {
            let mut row = l.clone();
            row.extend_from_slice(r);
            rows.push(row);
        }
    }
    Bindings::unsorted(out_vars, rows)
}

/// Generic join used for Join of non-conjunctive sub-results. With fully-bound
/// shared columns it takes the fast path (merge if both are sorted on the join
/// var, else hash); when a shared column can be unbound (from OPTIONAL / UNION /
/// VALUES UNDEF), it falls back to a correct solution-compatibility nested loop.
fn join_bindings(left: Bindings, right: Bindings) -> Bindings {
    let (out_vars, shared, right_only) = join_layout(&left, &right);
    if shared.is_empty() {
        return cross_product(left, right);
    }
    let lcols: Vec<usize> = shared.iter().map(|&(lc, _)| lc).collect();
    let rcols: Vec<usize> = shared.iter().map(|&(_, rc)| rc).collect();
    if !any_unbound(&left.rows, &lcols) && !any_unbound(&right.rows, &rcols) {
        if let (Some(lv), Some(rv)) = (&left.sorted_by, &right.sorted_by) {
            if lv == rv && right.col(lv).is_some() {
                let jv = lv.clone();
                return merge_join(left, right, &jv);
            }
        }
        return hash_join(left, right);
    }
    let mut rows = Vec::new();
    for lrow in &left.rows {
        // Coarse budget check once per left row.
        if budget::exhausted(rows.len()) {
            break;
        }
        for rrow in &right.rows {
            if compatible(lrow, rrow, &shared) {
                rows.push(merge_rows(lrow, rrow, &shared, &right_only));
            }
        }
    }
    Bindings::unsorted(out_vars, rows)
}

// ---- OPTIONAL / UNION / MINUS / VALUES / BIND --------------------------------

fn left_outer_join(graph: &Graph, local: &mut LocalVocab, left: Bindings, right: Bindings, expr: Option<&Expression>) -> Result<Bindings, String> {
    let (out_vars, shared, right_only) = join_layout(&left, &right);
    let n_right_only = right_only.len();

    // Sort-merge left outer join for the common case — exactly one shared variable,
    // fully bound on both sides (the typical `?s p ?o OPTIONAL { ?s q ?r }`). It
    // avoids building a hash table over the entire right side (which dominates on
    // large OPTIONALs); QLever uses the same sorted-merge strategy here.
    if shared.len() == 1 {
        let (lk, rk) = shared[0];
        if !any_unbound(&left.rows, &[lk]) && !any_unbound(&right.rows, &[rk]) {
            return left_outer_merge(graph, local, left, right, lk, rk, &shared, &right_only, n_right_only, out_vars, expr);
        }
    }

    // Hash the right side by its shared-variable key when those columns are fully
    // bound; otherwise fall back to a compatibility scan (shared vars may be
    // unbound, in which case they act as wildcards).
    let lcols: Vec<usize> = shared.iter().map(|&(lc, _)| lc).collect();
    let rcols: Vec<usize> = shared.iter().map(|&(_, rc)| rc).collect();
    let table: Option<FxHashMap<Key, Posting>> =
        if !shared.is_empty() && !any_unbound(&left.rows, &lcols) && !any_unbound(&right.rows, &rcols) {
            let mut t: FxHashMap<Key, Posting> = FxHashMap::default();
            for (ri, row) in right.rows.iter().enumerate() {
                t.entry(rcols.iter().map(|&c| row[c]).collect()).or_default().push(ri);
            }
            Some(t)
        } else {
            None
        };

    let mut rows = Vec::new();
    for lrow in &left.rows {
        // Coarse budget check once per left row.
        if budget::exhausted(rows.len()) {
            break;
        }
        // Inline (no heap alloc per left row): an OPTIONAL key usually has 0–1
        // matches. The hashed branch copies the matching indices by value rather
        // than cloning the table's Vec.
        let candidates: SmallVec<[usize; 4]> = match &table {
            Some(t) => {
                let key: Key = lcols.iter().map(|&c| lrow[c]).collect();
                t.get(&key).map(|v| v.iter().copied().collect()).unwrap_or_default()
            }
            None => (0..right.rows.len()).filter(|&ri| compatible(lrow, &right.rows[ri], &shared)).collect(),
        };
        let mut matched = false;
        for ri in candidates {
            let combined = merge_rows(lrow, &right.rows[ri], &shared, &right_only);
            // OPTIONAL's filter is part of the join condition (evaluated on the
            // combined row); a row that fails it does not count as a match.
            let keep = match expr {
                None => true,
                Some(e) => {
                    let tmp = Bindings { vars: out_vars.clone(), rows: vec![], sorted_by: None };
                    effective_boolean(&eval_expr(graph, local, &tmp, &combined, e)?)
                }
            };
            if keep {
                rows.push(combined);
                matched = true;
            }
        }
        if !matched {
            let mut combined = lrow.clone();
            combined.extend(std::iter::repeat_n(NO_ID, n_right_only));
            rows.push(combined);
        }
    }
    Ok(Bindings::unsorted(out_vars, rows))
}

/// Sort-merge left outer join on a single shared variable (`lk`/`rk` columns).
#[allow(clippy::too_many_arguments)]
fn left_outer_merge(
    graph: &Graph,
    local: &mut LocalVocab,
    mut left: Bindings,
    mut right: Bindings,
    lk: usize,
    rk: usize,
    shared: &[(usize, usize)],
    right_only: &[usize],
    n_right_only: usize,
    out_vars: Vec<Variable>,
    expr: Option<&Expression>,
) -> Result<Bindings, String> {
    // Both sides come from index scans that are usually already key-sorted, so
    // these sorts are near-linear (pattern-defeating quicksort detects sortedness).
    left.rows.sort_unstable_by_key(|r| r[lk]);
    right.rows.sort_unstable_by_key(|r| r[rk]);
    let (l, r) = (&left.rows, &right.rows);
    let mut rows: Vec<Row> = Vec::with_capacity(l.len());
    let mut j = 0usize;
    let mut i = 0usize;
    while i < l.len() {
        // Coarse budget check once per key group.
        if budget::exhausted(rows.len()) {
            break;
        }
        let key = l[i][lk];
        let mut i2 = i + 1;
        while i2 < l.len() && l[i2][lk] == key {
            i2 += 1;
        }
        while j < r.len() && r[j][rk] < key {
            j += 1;
        }
        let mut j2 = j;
        while j2 < r.len() && r[j2][rk] == key {
            j2 += 1;
        }
        for lrow in l.iter().take(i2).skip(i) {
            let mut matched = false;
            for rrow in r.iter().take(j2).skip(j) {
                let combined = merge_rows(lrow, rrow, shared, right_only);
                let keep = match expr {
                    None => true,
                    Some(e) => {
                        let tmp = Bindings { vars: out_vars.clone(), rows: vec![], sorted_by: None };
                        effective_boolean(&eval_expr(graph, local, &tmp, &combined, e)?)
                    }
                };
                if keep {
                    rows.push(combined);
                    matched = true;
                }
            }
            if !matched {
                let mut combined = lrow.clone();
                combined.extend(std::iter::repeat_n(NO_ID, n_right_only));
                rows.push(combined);
            }
        }
        i = i2;
        j = j2;
    }
    // Output is ordered by the join variable (at column lk of out_vars).
    let sorted_by = out_vars.get(lk).cloned();
    Ok(Bindings { vars: out_vars, rows, sorted_by })
}

// ---- Correlated (theta) anti-join (sq-7d3dj.30.9) --------------------------------
// [FABLE-5] See the `theta_antijoin` module comment near the top of this file for the
// shape, the SIP seeding, and the full soundness argument.

/// Which equality RELATION a correlation conjunct expresses. This is load-bearing for
/// soundness: value `=`, `sameTerm`, and id-equality are DIFFERENT relations on RDF
/// literals (a value-equal but id-distinct pair of literals exists), so the id-bucket
/// probe eligibility AND the per-candidate re-check expression differ by kind. [FABLE-5]
/// (sq-3cmr4)
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum CorrKind {
    /// SPARQL value equality `?outer = ?inner` (also the desugaring of a single-variable
    /// `?outer IN (?inner)`). Value-equality (sq-lr2ii): an id-bucket probe is exact ONLY
    /// when the correlation value is a NamedNode/BlankNode (where `=` coincides with term
    /// identity); a LITERAL key must take the value-correct scan with `=` re-checked.
    Eq,
    /// SPARQL `sameTerm(?outer, ?inner)` — TERM IDENTITY. Two terms are `sameTerm` iff
    /// identical (same IRI / same blank id / same lexical+datatype+language literal),
    /// which under dictionary interning is EXACTLY id-equality — for EVERY term kind,
    /// literals included. So an id-bucket probe is exact even for a literal key, and the
    /// per-candidate re-check (when a scan is taken) must be `sameTerm`, never `=`.
    SameTerm,
}

/// One correlation conjunct `?outer θ ?inner` extracted from the OPTIONAL condition,
/// where `?inner` is certain-in-`B` and `?outer` is a left variable and `θ` is the
/// relation named by `kind`. The remaining conjuncts (residual theta) are re-checked
/// verbatim per candidate right row.
struct Correlation {
    /// Column of `?outer` in the LEFT bindings.
    left_col: usize,
    /// The certain-in-`B` variable `?inner` seeded sideways into the right scan.
    inner_var: Variable,
    /// The equality relation `θ` this conjunct expresses (`=` or `sameTerm`). [FABLE-5]
    kind: CorrKind,
}

/// Attempts the correlated theta anti-join for `Filter(!bound(?nb), LeftJoin(A, B, F))`.
///
/// Returns `Ok(Some(result))` when the shape matched AND the path fired (result is
/// bag-equivalent to the cold `Filter{LeftJoin}` plan), or `Ok(None)` to DECLINE — in
/// which case the caller runs the identical prior plan.
fn try_theta_antijoin(
    graph: &Graph,
    local: &mut LocalVocab,
    filter_expr: &Expression,
    inner: &GraphPattern,
) -> Result<Option<Bindings>, String> {
    if !theta_antijoin::enabled() {
        return Ok(None);
    }
    // Shape: outer filter is exactly `!bound(?nb)` over a `LeftJoin` WITH a condition.
    let Some(nb) = as_not_bound_var(filter_expr) else { return Ok(None) };
    let GraphPattern::LeftJoin { left, right, expression: Some(cond) } = inner else {
        return Ok(None);
    };

    // `?nb` must be a right-only anti-join witness: certain in `B` (so the LeftJoin
    // binds it on EVERY match, hence `!bound` selects exactly the non-matches) and
    // ABSENT from `A` (else `!bound(?nb)` is not the anti-join predicate — decline).
    let mut b_certain = FxHashSet::default();
    certain_vars(right, &mut b_certain);
    if !b_certain.contains(&nb) || pattern_has_var(left, &nb) {
        return Ok(None);
    }

    // [OPUS-4.8] (sq-7d3dj.30.20) Static early-decline: this path exists ONLY to SEED the
    // right scan sideways from a var-to-var correlation in the OPTIONAL condition. If no
    // conjunct of `cond` can be such a seedable correlation — decided PURELY STATICALLY from
    // the left/right variable SETS, no graph access — the path would evaluate the mandatory
    // left side and then decline (`correlations.is_empty()` below), forcing the cold
    // `Filter{LeftJoin}` fallback to RE-EVALUATE that same left side. SP2Bench q07 is exactly
    // this case (its OPTIONAL condition is a bare `!bound(?doc4)`), and its left side is the
    // dominant ~30ms outer BGP — so the redundant second evaluation is the query's residual.
    // Declining HERE, before the left side is touched, removes the wasted evaluation. This is a
    // pure evaluation-ORDERING change: it declines exactly the same shapes the
    // `correlations.is_empty()` check below would (that check is total over `cond` and does not
    // depend on any left ROW), and a decline always yields the identical cold-plan result, so it
    // is BAG-RESULT-EQUIVALENT to the feature-off build. OPT-IN; when off, byte-identical.
    #[cfg(feature = "antijoin-static-decline")]
    if !cond_has_seedable_correlation(cond, left, &b_certain) {
        theta_antijoin::record_early_decline();
        return Ok(None);
    }

    // Evaluate the mandatory left side once.
    let left_b = eval_graph_pattern(graph, local, left)?;

    // Output layout, computed STATICALLY (never evaluate `B` cold — that is exactly
    // what this path avoids): the LeftJoin's variables = left's vars, then each
    // in-scope right variable not already present. Surviving rows carry only left
    // values + `NO_ID` padding for the right-only columns.
    let right_scope = in_scope_vars(right);
    let mut out_vars = left_b.vars.clone();
    for v in &right_scope {
        if !out_vars.contains(v) {
            out_vars.push(v.clone());
        }
    }
    let n_right_only = out_vars.len() - left_b.vars.len();
    if left_b.rows.is_empty() {
        return Ok(Some(Bindings::unsorted(out_vars, Vec::new())));
    }

    // Partition the OPTIONAL condition into correlation conjuncts and a residual.
    // A correlation conjunct is a var-to-var equality `?outer θ ?inner` (either
    // orientation) with `?inner` certain in `B` and `?outer` a LEFT variable, where θ is
    // value `=`, `sameTerm`, OR a single-variable `?a IN (?b)` membership (which
    // desugars to `?a = ?b`). Everything else — a constant, a multi-element `IN`, a
    // non-var operand, an inequality — is residual theta, re-checked VERBATIM on the
    // merged row (always sound). A `?a IN (const, …)` list with no in/outer variable is
    // NOT a correlation (nothing to seed sideways). [FABLE-5] (sq-3cmr4)
    let conjuncts = split_and(cond);
    let mut correlations: Vec<Correlation> = Vec::new();
    let mut residual: Vec<&Expression> = Vec::new();
    for c in &conjuncts {
        if let Some((va, vb, kind)) = as_correlation_pair(c) {
            // Orient: the certain-in-B side is `?inner`, the left side is `?outer`.
            let (outer, inner_var) = if b_certain.contains(&vb) && left_b.col(&va).is_some() {
                (va.clone(), vb.clone())
            } else if b_certain.contains(&va) && left_b.col(&vb).is_some() {
                (vb.clone(), va.clone())
            } else {
                residual.push(c);
                continue;
            };
            // `?inner` must not also be a left variable (that would be a shared join
            // var handled by compatibility, not a seedable correlation) and the outer
            // must be resolvable to a column.
            if left_b.col(&inner_var).is_some() {
                residual.push(c);
                continue;
            }
            let Some(left_col) = left_b.col(&outer) else {
                residual.push(c);
                continue;
            };
            correlations.push(Correlation { left_col, inner_var, kind });
        } else {
            residual.push(c);
        }
    }
    // No correlation to seed sideways → the SIP win is absent; decline so the cold
    // plan runs (this path exists to seed the right scan, not to reimplement it).
    if correlations.is_empty() {
        return Ok(None);
    }

    // Distinct correlation tuples on the LEFT (dedup for evaluation planning only).
    let mut order: Vec<Vec<Id>> = Vec::new();
    let mut groups: FxHashMap<Vec<Id>, Vec<usize>> = FxHashMap::default();
    for (ri, row) in left_b.rows.iter().enumerate() {
        let key: Vec<Id> = correlations.iter().map(|c| row[c.left_col]).collect();
        match groups.entry(key.clone()) {
            std::collections::hash_map::Entry::Occupied(mut e) => e.get_mut().push(ri),
            std::collections::hash_map::Entry::Vacant(e) => {
                order.push(key);
                e.insert(vec![ri]);
            }
        }
    }

    // The residual theta, evaluated on the merged (A-row ⊕ B-row) tuple via full SPARQL
    // 3-valued semantics; a conjunct that is not effectively-true (false OR error OR
    // unbound) means this `b` does NOT match, so the left row is NOT eliminated by it.
    let residual_owned: Vec<Expression> = residual.into_iter().cloned().collect();

    // STRATEGY SELECTION.
    //  * Large correlation cardinality → HASH ANTI-JOIN: evaluate `B` ONCE cold,
    //    partition its rows by the `?inner` id tuple, then probe each left row's bucket
    //    for a theta match. One `B` scan, O(|A| + |B|) — the q06 win. A left row whose
    //    correlation values are all IRIs id-probes its bucket EXACTLY (IRI value-
    //    equality IS id-equality); a left row with a non-IRI (literal) correlation value
    //    can NOT be id-probed (the sq-lr2ii value-equality class), so it takes a
    //    VALUE-CORRECT full scan over `B` with the correlation `=` re-checked verbatim.
    //  * Small correlation cardinality (≤ SIP_MAX_SMALL_ROWS) → SIP-SEED: evaluate a
    //    tiny correlated `B'` per distinct correlation (few evals amortise well, and
    //    seeding restricts each scan).
    let use_hash = order.len() > SIP_MAX_SMALL_ROWS;

    let mut result_rows: Vec<Row> = Vec::with_capacity(left_b.rows.len());
    let mut total_child_rows = 0usize;

    if use_hash {
        // ---- Hash anti-join (evaluate B once, partition by ?inner id) ----
        let b_all = eval_graph_pattern(graph, local, right)?;
        total_child_rows += b_all.rows.len();
        // `?inner` id columns in `b_all` (certain in B ⇒ present and bound).
        let inner_cols: Option<Vec<usize>> =
            correlations.iter().map(|c| b_all.col(&c.inner_var)).collect();
        let Some(inner_cols) = inner_cols else {
            // A correlation `?inner` unexpectedly missing from B's header — decline.
            return Ok(None);
        };
        // Partition B rows by their ?inner id tuple (exact for IRI keys).
        let mut buckets: FxHashMap<Vec<Id>, Vec<usize>> = FxHashMap::default();
        for (bi, brow) in b_all.rows.iter().enumerate() {
            let key: Vec<Id> = inner_cols.iter().map(|&c| brow[c]).collect();
            buckets.entry(key).or_default().push(bi);
        }
        let all_b: Vec<usize> = (0..b_all.rows.len()).collect();
        let (out_src, tmp_vars) = merged_row_plan(&out_vars, &left_b, &b_all);
        let shared: Vec<(usize, usize)> = left_b
            .vars
            .iter()
            .enumerate()
            .filter_map(|(lc, v)| b_all.col(v).map(|bc| (lc, bc)))
            .collect();
        // The correlation re-checks, for the value-correct scan of a NON-id-probeable
        // left row (an id-probeable row's correlation is already exact via the id bucket).
        // Each conjunct uses ITS OWN relation: `=` for a value-equality correlation, but
        // `sameTerm` for a sameTerm correlation (they DIFFER on value-equal id-distinct
        // literals). [FABLE-5] (sq-3cmr4)
        let corr_checks: Vec<Expression> =
            correlations.iter().map(|c| corr_recheck_expr(c, &out_vars)).collect();
        let mut value_checks: Vec<Expression> = corr_checks.clone();
        value_checks.extend(residual_owned.iter().cloned());

        // Per-left-row elimination verdict: `true` iff SOME right row eliminates `lrow`
        // (so the row does NOT survive the anti-join). Every input it reads — `graph`,
        // `local` (immutable), the buckets, the checks — is shared read-only, so this is
        // safe to evaluate in parallel across left rows. `local` is `&LocalVocab` here
        // (never mutated inside the probe): a probe interns nothing, so no per-row id
        // divergence. [FABLE-5] (sq-3cmr4 / sq-f1emb)
        let eliminated = |lrow: &Row| -> Result<bool, String> {
            // Every correlation value id-bucket-probeable? Then an exact id-bucket probe
            // is sound (see `corr_id_probeable` for the per-kind argument): for a value
            // `=` correlation the value must be a NamedNode/BlankNode (where `=` coincides
            // with term identity — per SPARQL 1.1 §17.4.1.7 `=` on two DISTINCT non-literal
            // terms is FALSE, and FALSE/error both mean NO MATCH, which an id-bucket
            // non-match reproduces); a LITERAL under `=` is the sq-lr2ii value-equality
            // hazard → value-correct scan. For a `sameTerm` correlation EVERY kind is
            // id-probeable (id-equality IS sameTerm for all term kinds, literals included).
            // [FABLE-5] (sq-3cmr4)
            let id_hashable = correlations
                .iter()
                .all(|c| corr_id_probeable(c.kind, term_of(graph, local, lrow[c.left_col]).as_ref()));
            if id_hashable {
                let key: Vec<Id> = correlations.iter().map(|c| lrow[c.left_col]).collect();
                match buckets.get(&key) {
                    None => Ok(false),
                    Some(cands) => antijoin_row_matches(
                        graph, local, lrow, &b_all, cands, &shared, &out_src, &tmp_vars,
                        &residual_owned,
                    ),
                }
            } else {
                // Literal-keyed left row: value-correct full scan with the correlation
                // relation re-checked (`=` or `sameTerm` per kind).
                antijoin_row_matches(
                    graph, local, lrow, &b_all, &all_b, &shared, &out_src, &tmp_vars,
                    &value_checks,
                )
            }
        };

        // [FABLE-5] (sq-f1emb) For a VERY LARGE anchor side, the per-left-row probe is
        // embarrassingly parallel (each verdict reads only shared read-only state).
        // Mirror the parallel hash-join / BIND threshold (`PAR_THRESHOLD`): fan the
        // VERDICT computation out over cores, collecting one `bool` per row IN ORDER, then
        // build + budget-truncate the surviving output rows SERIALLY in the identical left
        // order. Because only the verdicts are parallelised (never the ordered output
        // build, never `local` interning), the result is byte-identical to the serial
        // probe — the order-preserving `collect` + serial truncation reproduce exactly the
        // serial loop's early-`break`-on-budget survivor prefix. The EXISTS residual re-
        // enters the thread-local function / view / spatial state, so each worker installs
        // the snapshot exactly like the FILTER / BIND parallel paths.
        //
        // [SONNET-4.6] (sq-qk6ac) An exhausted budget must block the VERDICT loop, not
        // just the output build: one verdict is a whole probe of `B` (a bucket scan plus
        // 3-valued expression evaluation — a WHOLE-`B` scan for a literal-keyed row), so a
        // timed-out / cancelled query used to grind every remaining left row only for the
        // build below to discard the lot on its FIRST `budget::exhausted` check. A rayon
        // worker cannot see the installing thread's sticky flag, so it re-checks a
        // captured `Limits` snapshot (the parallel hash-join / JSON-serialize pattern) and,
        // when hit, returns the CANONICAL budget error — `collect` into `Result`
        // short-circuits, so the queued probes are abandoned. Raising the error rather
        // than guessing a placeholder verdict also means a skipped row can never escape as
        // a silently truncated result, and it is behaviour-identical on the observable
        // path: today the build truncates to nothing and the caller's operator-exit
        // `budget::check` raises this same message, just after the wasted work.
        #[cfg(feature = "parallel")]
        if left_b.rows.len() >= PAR_THRESHOLD {
            use rayon::prelude::*;
            let limits = budget::snapshot();
            let fns = functions::snapshot();
            let vw = view::snapshot();
            let spx = spatial::snapshot();
            // [OPUS-5] (sq-lsp7k.2.2) Keep LOCAL SERVICE handlers visible on the worker too:
            // a worker that missed the registry would dial the IRI instead of answering it.
            #[cfg(feature = "service-local")]
            let lsv = local_services::snapshot();
            #[cfg(not(target_arch = "wasm32"))]
            let qn = query_now::snapshot(); // sq-98w7z.1: keep NOW() pinned on workers
            let verdicts: Vec<bool> = left_b
                .rows
                .par_iter()
                .map(|lrow| {
                    // One non-tripping `Instant` read per row under a deadline budget, and
                    // a single `on` test when no budget is installed.
                    if let Some(why) = limits.why(0) {
                        return Err(format!("query budget exceeded ({})", why));
                    }
                    let _fns = functions::worker_install(&fns);
                    let _vw = view::worker_install(&vw);
                    let _spx = spatial::worker_install(&spx);
                    #[cfg(feature = "service-local")]
                    let _lsv = local_services::worker_install(&lsv);
                    #[cfg(not(target_arch = "wasm32"))]
                    let _qn = query_now::worker_install(qn);
                    eliminated(lrow)
                })
                .collect::<Result<Vec<bool>, String>>()?;

            // Serial ordered build + budget truncation: identical to the serial probe
            // loop's `if !matched { push } ; break on budget` — the survivor prefix and
            // its order are reproduced exactly whether the verdicts were computed
            // serially or in parallel.
            for (lrow, &elim) in left_b.rows.iter().zip(&verdicts) {
                if budget::exhausted(result_rows.len()) {
                    break;
                }
                if !elim {
                    let mut combined: Row = lrow.clone();
                    combined.extend(std::iter::repeat_n(NO_ID, n_right_only));
                    result_rows.push(combined);
                }
            }
            theta_antijoin::record(total_child_rows, order.len());
            return Ok(Some(Bindings::unsorted(out_vars, result_rows)));
        }

        // Serial probe loop: the verdict is computed INSIDE the cooperative build loop, so
        // an exhausted budget stops probing at exactly the row it stops emitting — the
        // loop the parallel branch above is documented to reproduce. [SONNET-4.6]
        // (sq-qk6ac)
        for lrow in &left_b.rows {
            if budget::exhausted(result_rows.len()) {
                break;
            }
            if !eliminated(lrow)? {
                let mut combined: Row = lrow.clone();
                combined.extend(std::iter::repeat_n(NO_ID, n_right_only));
                result_rows.push(combined);
            }
        }
        theta_antijoin::record(total_child_rows, order.len());
        return Ok(Some(Bindings::unsorted(out_vars, result_rows)));
    }

    // ---- SIP-seed anti-join (small correlation cardinality / literal keys) ----
    let mut fired = false;
    for key in &order {
        let members = &groups[key];
        let ri0 = members[0];

        // Seed iff every correlation value in this group is an IRI (`=` IS term
        // identity for IRIs). A literal value routes to the cold `B` + value `=` recheck.
        let mut smap: FxHashMap<Variable, oxrdf::NamedNode> = FxHashMap::default();
        let mut all_iri = true;
        for c in &correlations {
            match term_of(graph, local, left_b.rows[ri0][c.left_col]) {
                Some(Term::NamedNode(n)) => {
                    smap.insert(c.inner_var.clone(), n);
                }
                _ => {
                    all_iri = false;
                    break;
                }
            }
        }
        let (b_prime, seeded) = if all_iri {
            match subst_pattern(right, &smap) {
                Some(subst) => (eval_graph_pattern(graph, local, &subst)?, true),
                None => (eval_graph_pattern(graph, local, right)?, false),
            }
        } else {
            (eval_graph_pattern(graph, local, right)?, false)
        };
        total_child_rows += b_prime.rows.len();
        fired = true;

        let (mut out_src, tmp_vars) = merged_row_plan(&out_vars, &left_b, &b_prime);
        // When seeded, `?inner` was folded to a constant inside `B`, so `b_prime` no
        // longer binds it — re-materialise its id so a residual referencing `?inner`
        // still sees the seeded value on the merged row.
        if seeded {
            for c in &correlations {
                if let Some(nn) = smap.get(&c.inner_var) {
                    if let Some(oi) = out_vars.iter().position(|v| v == &c.inner_var) {
                        if matches!(out_src[oi], MergeSrc::Unbound) {
                            let t = Term::NamedNode(nn.clone());
                            let id = graph.id_of(&t).unwrap_or_else(|| local.intern(t));
                            out_src[oi] = MergeSrc::Const(id);
                        }
                    }
                }
            }
        }
        let shared: Vec<(usize, usize)> = left_b
            .vars
            .iter()
            .enumerate()
            .filter_map(|(lc, v)| b_prime.col(v).map(|bc| (lc, bc)))
            .collect();
        // When NOT seeded, the correlation equalities were not enforced by substitution
        // — prepend them to the theta so they are re-checked with their FULL relation
        // (`=` for a value-equality correlation, `sameTerm` for a sameTerm correlation:
        // they differ on value-equal id-distinct literals). [FABLE-5] (sq-3cmr4)
        let mut checks: Vec<Expression> = Vec::new();
        if !seeded {
            for c in &correlations {
                checks.push(corr_recheck_expr(c, &out_vars));
            }
        }
        checks.extend(residual_owned.iter().cloned());

        let all_cands: Vec<usize> = (0..b_prime.rows.len()).collect();
        for &ri in members {
            let lrow = &left_b.rows[ri];
            if budget::exhausted(result_rows.len()) {
                break;
            }
            let matched = antijoin_row_matches(
                graph, local, lrow, &b_prime, &all_cands, &shared, &out_src, &tmp_vars, &checks,
            )?;
            if !matched {
                let mut combined: Row = lrow.clone();
                combined.extend(std::iter::repeat_n(NO_ID, n_right_only));
                result_rows.push(combined);
            }
        }
    }

    if fired {
        theta_antijoin::record(total_child_rows, order.len());
    }
    Ok(Some(Bindings::unsorted(out_vars, result_rows)))
}

/// How to fill each `out_vars` slot in a merged (left ⊕ right) candidate row.
enum MergeSrc {
    Left(usize),
    Right(usize),
    /// A SHARED column: take the left cell, but fall through to the right cell when the
    /// left is `NO_ID`. This mirrors `merge_rows` (sparq-substrate `join.rs`) EXACTLY,
    /// so the anti-join's condition-evaluation row matches the cold `left_outer_join`'s
    /// even when `A` binds the shared var only partially (e.g. an OPTIONAL/UNION inside
    /// `A`). Without the fall-through a left-unbound shared cell stayed `NO_ID`, the
    /// residual saw UNBOUND → error → no match, and the left row spuriously survived
    /// (the reviewer's counterexample). [FABLE-5]
    LeftThenRight(usize, usize),
    /// A seeded `?inner` constant (its id) that the right side no longer binds.
    Const(Id),
    Unbound,
}

/// Builds the per-`(left, right)` merge plan for the static `out_vars` layout: how to
/// source each output column, plus the `tmp_vars` header for `eval_expr`.
fn merged_row_plan(
    out_vars: &[Variable],
    left: &Bindings,
    right: &Bindings,
) -> (Vec<MergeSrc>, Vec<Variable>) {
    let out_src = out_vars
        .iter()
        .map(|v| match (left.col(v), right.col(v)) {
            // Shared column: mirror `merge_rows` — left, falling through to right when
            // the left cell is unbound. [FABLE-5]
            (Some(lc), Some(bc)) => MergeSrc::LeftThenRight(lc, bc),
            (Some(lc), None) => MergeSrc::Left(lc),
            (None, Some(bc)) => MergeSrc::Right(bc),
            (None, None) => MergeSrc::Unbound,
        })
        .collect();
    (out_src, out_vars.to_vec())
}

/// `true` iff SOME candidate right row (`cands` = indices into `b.rows`) is compatible
/// with `lrow` on the shared columns AND makes every `checks` conjunct effectively-true
/// (correlation `=` re-checks — when present — and the residual theta), evaluated on the
/// merged row in `out_vars` order. This is the anti-join elimination test: a `true`
/// result DROPS the left row. Multiplicity: the caller emits each surviving row once.
#[allow(clippy::too_many_arguments)]
fn antijoin_row_matches(
    graph: &Graph,
    local: &LocalVocab,
    lrow: &[Id],
    b: &Bindings,
    cands: &[usize],
    shared: &[(usize, usize)],
    out_src: &[MergeSrc],
    tmp_vars: &[Variable],
    checks: &[Expression],
) -> Result<bool, String> {
    let tmp = Bindings { vars: tmp_vars.to_vec(), rows: vec![], sorted_by: None };
    for &bi in cands {
        let rrow = &b.rows[bi];
        if !compatible(lrow, rrow, shared) {
            continue;
        }
        let combined: Row = out_src
            .iter()
            .map(|s| match s {
                MergeSrc::Left(lc) => lrow[*lc],
                MergeSrc::Right(bc) => rrow[*bc],
                MergeSrc::LeftThenRight(lc, bc) => {
                    if lrow[*lc] == NO_ID {
                        rrow[*bc]
                    } else {
                        lrow[*lc]
                    }
                }
                MergeSrc::Const(id) => *id,
                MergeSrc::Unbound => NO_ID,
            })
            .collect();
        let mut ok = true;
        for e in checks {
            if !effective_boolean(&eval_expr(graph, local, &tmp, &combined, e)?) {
                ok = false;
                break;
            }
        }
        if ok {
            return Ok(true); // one match eliminates the left row.
        }
    }
    Ok(false)
}

/// Does `var` occur ANYWHERE in `p` (any triple position, any expression including
/// `EXISTS` sub-patterns)? A SOUND OVER-approximation for the anti-join scope guard:
/// reporting a spurious occurrence only makes the rewrite DECLINE (safe); missing a
/// real one would be unsound, so every node kind recurses fully. [FABLE-5]
fn pattern_has_var(p: &GraphPattern, var: &Variable) -> bool {
    use GraphPattern as G;
    let te = |t: &TermPattern| term_pattern_has_var(t, var);
    let ne = |n: &NamedNodePattern| matches!(n, NamedNodePattern::Variable(v) if v == var);
    match p {
        G::Bgp { patterns } => patterns
            .iter()
            .any(|tp| te(&tp.subject) || ne(&tp.predicate) || te(&tp.object)),
        G::Path { subject, object, .. } => te(subject) || te(object),
        G::Join { left, right } | G::Union { left, right } | G::Minus { left, right } | G::Lateral { left, right } => {
            pattern_has_var(left, var) || pattern_has_var(right, var)
        }
        G::LeftJoin { left, right, expression } => {
            pattern_has_var(left, var)
                || pattern_has_var(right, var)
                || expression.as_ref().is_some_and(|e| expr_has_var(e, var))
        }
        G::Filter { expr, inner } => expr_has_var(expr, var) || pattern_has_var(inner, var),
        G::Graph { name, inner } => ne(name) || pattern_has_var(inner, var),
        G::Extend { inner, variable, expression } => {
            variable == var || expr_has_var(expression, var) || pattern_has_var(inner, var)
        }
        G::Values { variables, .. } => variables.iter().any(|v| v == var),
        G::OrderBy { inner, expression } => {
            pattern_has_var(inner, var)
                || expression.iter().any(|o| match o {
                    OrderExpression::Asc(e) | OrderExpression::Desc(e) => expr_has_var(e, var),
                })
        }
        G::Project { inner, variables } | G::Group { inner, variables, .. } => {
            variables.iter().any(|v| v == var) || pattern_has_var(inner, var)
        }
        G::Distinct { inner } | G::Reduced { inner } | G::Slice { inner, .. } => {
            pattern_has_var(inner, var)
        }
        G::Service { name, inner, .. } => ne(name) || pattern_has_var(inner, var),
    }
}

fn term_pattern_has_var(t: &TermPattern, var: &Variable) -> bool {
    match t {
        TermPattern::Variable(v) => v == var,
        TermPattern::Triple(inner) => {
            term_pattern_has_var(&inner.subject, var)
                || matches!(&inner.predicate, NamedNodePattern::Variable(v) if v == var)
                || term_pattern_has_var(&inner.object, var)
        }
        _ => false,
    }
}

/// Does `var` occur anywhere in expression `e` (including `EXISTS` sub-patterns)?
/// Over-approximation for the scope guard (spurious `true` only declines). [FABLE-5]
fn expr_has_var(e: &Expression, var: &Variable) -> bool {
    use Expression as E;
    match e {
        E::Variable(v) | E::Bound(v) => v == var,
        E::NamedNode(_) | E::Literal(_) => false,
        E::Or(a, b)
        | E::And(a, b)
        | E::Equal(a, b)
        | E::SameTerm(a, b)
        | E::Greater(a, b)
        | E::GreaterOrEqual(a, b)
        | E::Less(a, b)
        | E::LessOrEqual(a, b)
        | E::Add(a, b)
        | E::Subtract(a, b)
        | E::Multiply(a, b)
        | E::Divide(a, b) => expr_has_var(a, var) || expr_has_var(b, var),
        E::In(a, list) => expr_has_var(a, var) || list.iter().any(|x| expr_has_var(x, var)),
        E::UnaryPlus(i) | E::UnaryMinus(i) | E::Not(i) => expr_has_var(i, var),
        E::If(a, b, c) => expr_has_var(a, var) || expr_has_var(b, var) || expr_has_var(c, var),
        E::Coalesce(list) | E::FunctionCall(_, list) => list.iter().any(|x| expr_has_var(x, var)),
        E::Exists(p) => pattern_has_var(p, var),
    }
}

/// `Some(v)` iff `e` is exactly `!BOUND(?v)` (`Not(Bound(v))`) — the anti-join
/// filter predicate.
fn as_not_bound_var(e: &Expression) -> Option<Variable> {
    match e {
        Expression::Not(inner) => match inner.as_ref() {
            Expression::Bound(v) => Some(v.clone()),
            _ => None,
        },
        _ => None,
    }
}

/// [OPUS-4.8] (sq-7d3dj.30.20) STATIC over-approximation of "does the OPTIONAL condition
/// `cond` contain at least one conjunct the theta anti-join could seed sideways?", decided
/// from the left-side variable SET and the certain-in-`B` set — WITHOUT evaluating either
/// side (no graph access). Used by [`try_theta_antijoin`]'s early-decline gate (opt-in
/// `antijoin-static-decline`) so it never pays to evaluate the mandatory left side only to
/// discard it on the `correlations.is_empty()` decline.
///
/// A conjunct is a SEEDABLE correlation exactly when the runtime partition (in
/// `try_theta_antijoin`) would place it in `correlations` rather than `residual`: it is a
/// var-to-var pair (`?a = ?b` / `sameTerm(?a, ?b)` / `?a IN (?b)`) with ONE side certain in
/// `B` and the OTHER a LEFT variable, and the certain-in-`B` side (the `?inner`) NOT also a
/// left variable. This mirrors that logic with `left_vars` standing in for the runtime
/// `left_b.col(v).is_some()` test — SOUND because for the conjunctive/BGP left sides this path
/// runs over, `left_b.vars` equals `left`'s in-scope variables. The over-approximation
/// direction is SAFE regardless: if this returns `true` when no correlation actually seeds, the
/// gate simply does NOT decline early and the unchanged runtime partition declines instead
/// (same result, one extra left evaluation — i.e. exactly the pre-feature behaviour). It only
/// ever declines early when the runtime would ALSO have found `correlations.is_empty()`.
#[cfg(feature = "antijoin-static-decline")]
fn cond_has_seedable_correlation(
    cond: &Expression,
    left: &GraphPattern,
    b_certain: &FxHashSet<Variable>,
) -> bool {
    let left_vars: FxHashSet<Variable> = in_scope_vars(left).into_iter().collect();
    split_and(cond).into_iter().any(|c| {
        let Some((va, vb, _)) = as_correlation_pair(c) else { return false };
        // Same orientation choice as the runtime partition: pick the certain-in-B side as
        // `inner` and the left side as `outer`; a seedable correlation additionally requires
        // the chosen `inner` NOT to be a left variable.
        if b_certain.contains(&vb) && left_vars.contains(&va) {
            !left_vars.contains(&vb)
        } else if b_certain.contains(&va) && left_vars.contains(&vb) {
            !left_vars.contains(&va)
        } else {
            false
        }
    })
}

/// `Some((a, b, kind))` iff `e` is a VAR-TO-VAR correlation conjunct the theta anti-join
/// can seed sideways: `?a = ?b` (`CorrKind::Eq`), `sameTerm(?a, ?b)` (`CorrKind::SameTerm`),
/// or a SINGLE-variable membership `?a IN (?b)` (which desugars to `?a = ?b`, so `Eq`).
/// Returns `None` for a constant operand, an inequality, or a multi-element / constant
/// `IN` list — those stay in the residual (always sound). Orientation (which is inner /
/// outer) is decided by the caller from the certain-in-B / left-column sets. [FABLE-5]
/// (sq-3cmr4)
fn as_correlation_pair(e: &Expression) -> Option<(Variable, Variable, CorrKind)> {
    match e {
        Expression::Equal(a, b) => match (a.as_ref(), b.as_ref()) {
            (Expression::Variable(va), Expression::Variable(vb)) => {
                Some((va.clone(), vb.clone(), CorrKind::Eq))
            }
            _ => None,
        },
        Expression::SameTerm(a, b) => match (a.as_ref(), b.as_ref()) {
            (Expression::Variable(va), Expression::Variable(vb)) => {
                Some((va.clone(), vb.clone(), CorrKind::SameTerm))
            }
            _ => None,
        },
        // `?a IN (?b)` is exactly `?a = ?b` (SPARQL 1.1 §17.4.1.9): a single-variable
        // membership. A list with a constant element, more than one element, or a
        // non-variable target is NOT this seedable shape — decline (residual, sound).
        Expression::In(target, list) => match (target.as_ref(), list.as_slice()) {
            (Expression::Variable(va), [Expression::Variable(vb)]) => {
                Some((va.clone(), vb.clone(), CorrKind::Eq))
            }
            _ => None,
        },
        _ => None,
    }
}

/// The per-candidate re-check expression for a correlation, in `out_vars` order: `=`
/// for a value-equality correlation, `sameTerm` for a sameTerm correlation. These are
/// DIFFERENT relations on value-equal id-distinct literals, so the kind is load-bearing
/// for soundness whenever a value-correct scan is taken (a non-id-probeable key, or the
/// un-seeded SIP path). [FABLE-5] (sq-3cmr4)
fn corr_recheck_expr(c: &Correlation, out_vars: &[Variable]) -> Expression {
    let lhs = Box::new(Expression::Variable(out_vars[c.left_col].clone()));
    let rhs = Box::new(Expression::Variable(c.inner_var.clone()));
    match c.kind {
        CorrKind::Eq => Expression::Equal(lhs, rhs),
        CorrKind::SameTerm => Expression::SameTerm(lhs, rhs),
    }
}

/// Is a left-row correlation value of the given `term` id-bucket-probeable under `kind`?
///
/// * `SameTerm` — YES for every term kind (a dictionary id equality IS `sameTerm`: two
///   terms share an id iff identical). An `Unbound` (`None`) key is NOT probeable — an
///   unbound operand makes `sameTerm` error, so route it through the scan where the
///   3-valued residual decides (defensive: a correlation column is certain-in-A, so this
///   is unreachable in practice).
/// * `Eq` — YES only for a NamedNode/BlankNode (`=` coincides with term identity there);
///   a literal is the sq-lr2ii value-equality hazard and an unbound is unprobeable.
///
/// [FABLE-5] (sq-3cmr4)
fn corr_id_probeable(kind: CorrKind, term: Option<&Term>) -> bool {
    match kind {
        CorrKind::SameTerm => term.is_some(),
        CorrKind::Eq => matches!(term, Some(Term::NamedNode(_) | Term::BlankNode(_))),
    }
}

/// Flattens a top-level `&&` (`Expression::And`) tree into its conjuncts, left to
/// right (single-element for a non-`And`).
fn split_and(e: &Expression) -> Vec<&Expression> {
    fn go<'a>(e: &'a Expression, out: &mut Vec<&'a Expression>) {
        match e {
            Expression::And(a, b) => {
                go(a, out);
                go(b, out);
            }
            other => out.push(other),
        }
    }
    let mut v = Vec::new();
    go(e, &mut v);
    v
}

fn union_bindings(left: Bindings, right: Bindings) -> Bindings {
    let mut out_vars = left.vars.clone();
    for v in &right.vars {
        if !out_vars.contains(v) {
            out_vars.push(v.clone());
        }
    }
    let mut rows: Vec<Row> = Vec::with_capacity(left.rows.len() + right.rows.len());
    let map_row = |src_vars: &[Variable], row: &[Id], out_vars: &[Variable]| -> Row {
        out_vars
            .iter()
            .map(|v| src_vars.iter().position(|x| x == v).map(|i| row[i]).unwrap_or(NO_ID))
            .collect()
    };
    for row in &left.rows {
        rows.push(map_row(&left.vars, row, &out_vars));
    }
    for row in &right.rows {
        rows.push(map_row(&right.vars, row, &out_vars));
    }
    Bindings::unsorted(out_vars, rows)
}

fn minus_bindings(left: Bindings, right: Bindings) -> Bindings {
    // SPARQL MINUS: drop a left row iff some right row is *compatible* with it AND
    // their bound domains overlap on at least one shared variable. (Disjoint
    // domains never remove anything.)
    let shared: Vec<(usize, usize)> = left
        .vars
        .iter()
        .enumerate()
        .filter_map(|(li, v)| right.col(v).map(|ri| (li, ri)))
        .collect();
    if shared.is_empty() {
        return left; // disjoint domains -> MINUS removes nothing
    }
    let lcols: Vec<usize> = shared.iter().map(|&(lc, _)| lc).collect();
    let rcols: Vec<usize> = shared.iter().map(|&(_, rc)| rc).collect();

    // Fast path: shared columns fully bound -> compatibility is exact-key equality
    // and the domains always overlap, so membership in a hash set suffices.
    if !any_unbound(&left.rows, &lcols) && !any_unbound(&right.rows, &rcols) {
        let mut table: FxHashMap<Key, ()> = FxHashMap::default();
        for row in &right.rows {
            table.insert(rcols.iter().map(|&c| row[c]).collect(), ());
        }
        let rows: Vec<Row> = left
            .rows
            .into_iter()
            .filter(|row| !table.contains_key(&lcols.iter().map(|&c| row[c]).collect::<Key>()))
            .collect();
        return Bindings { vars: left.vars, rows, sorted_by: left.sorted_by };
    }

    // General path: per-row compatibility with a bound-domain-overlap check.
    let keep = |lrow: &Row| -> bool {
        !right.rows.iter().any(|rrow| {
            let mut overlap = false;
            for &(lc, rc) in &shared {
                let (a, b) = (lrow[lc], rrow[rc]);
                if a != NO_ID && b != NO_ID {
                    if a != b {
                        return false; // incompatible
                    }
                    overlap = true;
                }
            }
            overlap
        })
    };
    let rows: Vec<Row> = left.rows.iter().filter(|r| keep(r)).cloned().collect();
    Bindings { vars: left.vars, rows, sorted_by: left.sorted_by }
}

fn values_bindings(graph: &Graph, local: &mut LocalVocab, variables: &[Variable], bindings: &[Vec<Option<GroundTerm>>]) -> Bindings {
    let rows = bindings
        .iter()
        .map(|row| {
            row.iter()
                .map(|cell| match cell {
                    None => NO_ID,
                    Some(gt) => {
                        // Resolve against the graph dictionary so the id joins with
                        // BGP results; a term absent from the graph gets a local id
                        // (it can only match other VALUES, never the data).
                        let t = ground_to_term(gt);
                        graph.id_of(&t).unwrap_or_else(|| local.intern(t))
                    }
                })
                .collect()
        })
        .collect();
    Bindings::unsorted(variables.to_vec(), rows)
}

fn extend_bindings(graph: &Graph, local: &mut LocalVocab, mut b: Bindings, var: &Variable, expr: &Expression) -> Result<Bindings, String> {
    // Pre-resolve Variable → column index once before the row loop. [OPUS-4.8] sq-7d3dj.4.
    let compiled = compile_expr(expr, &b);
    // BIND was fully serial because each row's computed value was interned immediately. Split it
    // (T1.0b): a PARALLEL pass evaluates the expression (read-only) and resolves the value to an
    // id read-only (inline / graph-dict / already-local); only genuinely new terms fall through to
    // the serial intern below, applied in row order → ids byte-identical to the serial path.
    // (Safe to parallelise: rows reference only ids created by EARLIER operators, never ids
    // created within this BIND loop.)
    // Row identity for BNODE(str)'s per-solution scoping (see ROW_SCOPE).
    let scope = b.rows.as_ptr() as usize;
    #[cfg(feature = "parallel")]
    let resolved: Vec<Result<Id, Term>> = if b.rows.len() >= PAR_THRESHOLD {
        use rayon::prelude::*;
        let lv: &LocalVocab = local;
        let bref = &b;
        // Thread-local extension-function registry and dataset view: snapshot +
        // per-item re-install (free when neither is installed) — see the FILTER
        // branch (the view matters here via EXISTS in the expression).
        let fns = functions::snapshot();
        let vw = view::snapshot();
        let spx = spatial::snapshot(); // sq-mg9: keep the spatial index visible under EXISTS re-entry.
        // [OPUS-5] (sq-lsp7k.2.2) Keep LOCAL SERVICE handlers visible on the worker too:
        // a worker that missed the registry would dial the IRI instead of answering it.
        #[cfg(feature = "service-local")]
        let lsv = local_services::snapshot();
        #[cfg(not(target_arch = "wasm32"))]
        let qn = query_now::snapshot(); // sq-98w7z.1: keep NOW() pinned on workers
        b.rows
            .par_iter()
            .enumerate()
            .map(|(i, row)| {
                let _fns = functions::worker_install(&fns);
                let _vw = view::worker_install(&vw);
                let _spx = spatial::worker_install(&spx);
                #[cfg(feature = "service-local")]
                let _lsv = local_services::worker_install(&lsv);
                #[cfg(not(target_arch = "wasm32"))]
                let _qn = query_now::worker_install(qn);
                ROW_SCOPE.set((scope, i));
                let v = eval_compiled(graph, lv, bref, row, &compiled)?;
                Ok(value_to_id_readonly(graph, lv, &v))
            })
            .collect::<Result<Vec<_>, String>>()?
    } else {
        let mut out = Vec::with_capacity(b.rows.len());
        for (i, row) in b.rows.iter().enumerate() {
            ROW_SCOPE.set((scope, i));
            let v = eval_compiled(graph, local, &b, row, &compiled)?;
            out.push(value_to_id_readonly(graph, local, &v));
        }
        out
    };
    #[cfg(not(feature = "parallel"))]
    let resolved: Vec<Result<Id, Term>> = {
        let mut out = Vec::with_capacity(b.rows.len());
        for (i, row) in b.rows.iter().enumerate() {
            ROW_SCOPE.set((scope, i));
            let v = eval_compiled(graph, local, &b, row, &compiled)?;
            out.push(value_to_id_readonly(graph, local, &v));
        }
        out
    };
    let col: Vec<Id> = resolved
        .into_iter()
        .map(|r| match r {
            Ok(id) => id,
            Err(term) => local.intern(term),
        })
        .collect();
    b.vars.push(var.clone());
    for (row, id) in b.rows.iter_mut().zip(col) {
        row.push(id);
    }
    b.sorted_by = None;
    Ok(b)
}

// ---- Aggregation --------------------------------------------------------------

/// Group row indexes by their group-key, preserving FIRST-SEEN order: `order[i]` is the i-th
/// distinct key in row order and `members[i]` its row indexes (ascending). Above PAR_THRESHOLD the
/// build is radix-partitioned (Tier-1 of research/parallelism-scaling.md): a parallel pass tags
/// each row with its key-hash partition, each partition then builds its private map lock-free
/// (within a partition rows are scanned in ascending index, so a group's first row IS its min),
/// and the global first-seen order is re-imposed by sorting groups on min row index — exactly the
/// serial first-seen order, so output stays byte-identical.
/// `key_cols[i]` is the bindings column for the i-th GROUP BY variable, or `None` when that
/// variable is never bound (no column) — its key id is then `NO_ID` (unbound) for every row.
fn build_groups(b: &Bindings, key_cols: &[Option<usize>]) -> (Vec<Key>, Vec<Vec<usize>>) {
    #[cfg(feature = "parallel")]
    if b.rows.len() >= PAR_THRESHOLD {
        use rayon::prelude::*;
        use std::hash::{Hash, Hasher};
        const P: usize = 64;
        // Pass 1 (parallel): partition tag per row.
        let parts: Vec<u8> = b
            .rows
            .par_iter()
            .map(|row| {
                let mut h = rustc_hash::FxHasher::default();
                for &c in key_cols {
                    c.map(|i| row[i]).unwrap_or(NO_ID).hash(&mut h);
                }
                (h.finish() % P as u64) as u8
            })
            .collect();
        // Pass 2 (parallel over partitions): private per-partition group builds. Each partition
        // scans the cheap tag vector and only constructs keys for its own rows.
        let per: Vec<Vec<(Key, usize, Vec<usize>)>> = (0..P)
            .into_par_iter()
            .map(|p| {
                let mut idx: FxHashMap<Key, usize> = FxHashMap::default();
                let mut out: Vec<(Key, usize, Vec<usize>)> = Vec::new(); // (key, min_ri, members)
                for (ri, row) in b.rows.iter().enumerate() {
                    if parts[ri] as usize != p {
                        continue;
                    }
                    let key: Key = key_cols.iter().map(|&c| c.map(|i| row[i]).unwrap_or(NO_ID)).collect();
                    match idx.get(&key) {
                        Some(&i) => out[i].2.push(ri),
                        None => {
                            idx.insert(key.clone(), out.len());
                            out.push((key, ri, vec![ri]));
                        }
                    }
                }
                out
            })
            .collect();
        // Pass 3: merge + re-impose the global first-seen order via min row index.
        let mut all: Vec<(Key, usize, Vec<usize>)> = per.into_iter().flatten().collect();
        all.par_sort_unstable_by_key(|&(_, min_ri, _)| min_ri);
        return all.into_iter().map(|(k, _, m)| (k, m)).unzip();
    }
    let mut idx: FxHashMap<Key, usize> = FxHashMap::default();
    let mut order: Vec<Key> = Vec::new();
    let mut members: Vec<Vec<usize>> = Vec::new();
    for (ri, row) in b.rows.iter().enumerate() {
        let key: Key = key_cols.iter().map(|&c| c.map(|i| row[i]).unwrap_or(NO_ID)).collect();
        match idx.get(&key) {
            Some(&i) => members[i].push(ri),
            None => {
                idx.insert(key.clone(), order.len());
                order.push(key);
                members.push(vec![ri]);
            }
        }
    }
    (order, members)
}

fn group_aggregate(
    graph: &Graph,
    local: &mut LocalVocab,
    b: Bindings,
    group_vars: &[Variable],
    aggregates: &[(Variable, AggregateExpression)],
) -> Result<Bindings, String> {
    // A GROUP BY variable that is never bound anywhere in the WHERE clause has no column in
    // `b`. Per SPARQL 1.1 §11.1 the group key for such a variable evaluates to unbound for every
    // solution, so all rows share the same (unbound) key on that position — they collapse into one
    // group and the variable is unbound in the output. We model the missing column as `None` and
    // feed `NO_ID` (unbound) for it, rather than panicking. (Regression: bead sq-vymy4.) [OPUS-4.8]
    let key_cols: Vec<Option<usize>> = group_vars.iter().map(|v| b.col(v)).collect();

    // Group rows by the group-key id tuple, preserving first-seen order (parallel ≥ threshold).
    let (mut order, mut members) = build_groups(&b, &key_cols);
    // Whole-dataset aggregate with no GROUP BY: one (empty) group, even if input is empty.
    if group_vars.is_empty() && order.is_empty() {
        order.push(Key::new());
        members.push(Vec::new());
    }

    let mut out_vars: Vec<Variable> = group_vars.to_vec();
    for (v, _) in aggregates {
        out_vars.push(v.clone());
    }

    // [SONNET-4.6] (sq-pntvh.4) M4 Phase 4 columnar reducer seam (Seam B): for an eligible
    // aggregate (no DISTINCT, bare-variable argument, all-inline-integer column, supported
    // function), fold each group's ids with a tight integer reducer — no `eval_expr` dispatch
    // per member, no term materialisation, byte-identical output to the scalar path.
    // Declines (→ scalar path below) for anything not provably identical.
    #[cfg(feature = "vectorized")]
    if let Some(rows) = columnar_aggregate(graph, local, &b, group_vars, aggregates, &order, &members, &out_vars) {
        return Ok(Bindings::unsorted(out_vars, rows));
    }

    // Evaluate each group's aggregates (the expensive part — `eval_expr` over every member of
    // every group), then intern the result and build the output row, in first-seen `order`.
    // Interning needs `&mut LocalVocab` and so stays SERIAL and in order, making the ids
    // byte-identical regardless of how evaluation is scheduled.
    let mut rows: Vec<Row> = Vec::with_capacity(order.len());

    // [OPUS-4.8] roborev 1429 (Med): bound peak memory. The previous implementation
    // materialised the aggregate `Value`s (and then their resolved ids) for EVERY group at
    // once before building any row — for many-group / large GROUP_CONCAT queries that holds
    // all aggregate output in memory simultaneously. We now process in bounded BATCHES (and,
    // in the sequential path, one group at a time), interning and pushing each batch's rows
    // before evaluating the next, so only a bounded slice of `Value`s is live.
    #[cfg(feature = "parallel")]
    let parallel_eval = b.rows.len() >= PAR_THRESHOLD;
    #[cfg(not(feature = "parallel"))]
    let parallel_eval = false;

    #[cfg(feature = "parallel")]
    if parallel_eval {
        use rayon::prelude::*;
        // Thread-local extension-function registry and dataset view: snapshot +
        // per-item re-install (free when neither is installed) — see the FILTER branch.
        let fns = functions::snapshot();
        let vw = view::snapshot();
        let spx = spatial::snapshot(); // sq-mg9: keep the spatial index visible under EXISTS re-entry.
        // [OPUS-5] (sq-lsp7k.2.2) Keep LOCAL SERVICE handlers visible on the worker too:
        // a worker that missed the registry would dial the IRI instead of answering it.
        #[cfg(feature = "service-local")]
        let lsv = local_services::snapshot();
        // [OPUS-4.8] (sq-5qz9) keep a custom-aggregate registry visible off-thread, like `fns`.
        // (`self::` because the `aggregates` *parameter* below shadows the module name.)
        #[cfg(feature = "window-functions")]
        let aggs = self::aggregates::snapshot();
        #[cfg(not(target_arch = "wasm32"))]
        let qn = query_now::snapshot(); // sq-98w7z.1: keep NOW() pinned on workers
        // Process `members`/`order` in PAR_THRESHOLD-sized batches: evaluate + read-only
        // resolve each batch in parallel, then serially intern only that batch's genuinely
        // new terms and emit its rows. Peak `Value` footprint is one batch, not all groups.
        for (key_chunk, member_chunk) in order.chunks(PAR_THRESHOLD).zip(members.chunks(PAR_THRESHOLD)) {
            let lv: &LocalVocab = local; // immutable reborrow for the read-only parallel phase
            let bref = &b;
            let resolved: Vec<Vec<Result<Id, Term>>> = member_chunk
                .par_iter()
                .map(|members| {
                    let _fns = functions::worker_install(&fns);
                    let _vw = view::worker_install(&vw);
                    let _spx = spatial::worker_install(&spx);
                    #[cfg(feature = "service-local")]
                    let _lsv = local_services::worker_install(&lsv);
                    #[cfg(feature = "window-functions")]
                    let _aggs = self::aggregates::worker_install(&aggs);
                    #[cfg(not(target_arch = "wasm32"))]
                    let _qn = query_now::worker_install(qn);
                    aggregates
                        .iter()
                        .map(|(_, agg)| eval_aggregate(graph, lv, bref, members, agg).map(|v| value_to_id_readonly(graph, lv, &v)))
                        .collect::<Result<Vec<_>, String>>()
                })
                .collect::<Result<Vec<_>, String>>()?;
            for (key, res) in key_chunk.iter().zip(resolved) {
                let mut row = Row::from_slice(key);
                for r in res {
                    row.push(match r {
                        Ok(id) => id,
                        Err(term) => local.intern(term),
                    });
                }
                rows.push(row);
            }
        }
    }

    if !parallel_eval {
        // Sequential STREAMING path: eval + intern + push per group, dropping each group's
        // `Value`s before moving to the next, so peak memory is a single group's aggregates.
        for (key, members) in order.iter().zip(&members) {
            let mut row = Row::from_slice(key);
            for (_, agg) in aggregates {
                let v = eval_aggregate(graph, local, &b, members, agg)?;
                let id = value_to_id(graph, local, &v);
                row.push(id);
            }
            rows.push(row);
        }
    }

    Ok(Bindings::unsorted(out_vars, rows))
}

/// [OPUS-4.8] (sq-v411r, survey §B2) Reserved IRI the vendored spargebra parser emits for the
/// zero-arg `MULTIPLICITY()` extension builtin (as a `Function::Custom`, to keep the shared
/// `Function` enum byte-compatible with downstream exhaustive matchers). The engine recognises
/// it in aggregate evaluation and function dispatch; it is never a user-registrable IRI.
pub(crate) const MULTIPLICITY_FN_IRI: &str = "urn:sparq:fn:multiplicity";

/// [OPUS-4.8] (sq-v411r, survey §B2) The DISTINCT solutions of a group paired with each
/// one's bag cardinality (`multiplicity(μ|Ω)`): `(ri, card)` is a representative row index
/// for a distinct solution mapping and how many rows in `members` are byte-identical to it,
/// in first-seen order. Returns `None` (and does NO work) unless `expr` actually calls
/// `MULTIPLICITY()`, so an aggregate that never references it pays nothing and folds the
/// full bag exactly as before.
///
/// The collapse to distinct members is load-bearing for correctness, NOT an optimisation:
/// the SPARQL algebra's Set Functions are defined over the multiset by iterating its
/// DISTINCT elements weighted by `multiplicity`, so `SUM(?x * MULTIPLICITY())` must visit
/// `?x=10` once (with multiplicity 3), not three times — otherwise a value occurring `k`
/// times would contribute `k²·x` instead of `k·x`. With this collapse the standard identity
/// `SUM(?x * MULTIPLICITY()) == SUM(?x)` (over the bag) holds. Solution identity is the
/// whole row, matching `COUNT(DISTINCT *)`; BGP matching is bag semantics, so duplicate
/// solutions are preserved as repeated rows up to this point.
fn group_multiplicities(b: &Bindings, members: &[usize], expr: &Expression) -> Option<Vec<(usize, u64)>> {
    if !expr_uses_multiplicity(expr) {
        return None;
    }
    // Count identical rows, keeping a first-seen representative index for each distinct row.
    let mut counts: FxHashMap<&Row, (usize, u64)> = FxHashMap::default();
    let mut order: Vec<&Row> = Vec::new();
    for &ri in members {
        match counts.get_mut(&b.rows[ri]) {
            Some(entry) => entry.1 += 1,
            None => {
                counts.insert(&b.rows[ri], (ri, 1));
                order.push(&b.rows[ri]);
            }
        }
    }
    Some(order.into_iter().map(|row| counts[row]).collect())
}

/// Whether `expr` contains a `MULTIPLICITY()` call anywhere in its tree. An `Exists`
/// sub-pattern is NOT descended into: a `MULTIPLICITY()` there belongs to that
/// (un-aggregated) sub-query's scope, not this aggregate's member — and would
/// correctly evaluate against the thread-local's restored (absent) context.
fn expr_uses_multiplicity(expr: &Expression) -> bool {
    use Expression as E;
    match expr {
        // `MULTIPLICITY()` is parsed as a `Function::Custom` with the reserved IRI
        // (see `MULTIPLICITY_FN_IRI`) so the shared `Function` enum stays byte-compatible
        // with downstream exhaustive matchers (sparopt/spareval).
        E::FunctionCall(spargebra::algebra::Function::Custom(nn), args)
            if args.is_empty() && nn.as_str() == MULTIPLICITY_FN_IRI =>
        {
            true
        }
        E::NamedNode(_) | E::Literal(_) | E::Variable(_) | E::Bound(_) | E::Exists(_) => false,
        E::Or(a, c)
        | E::And(a, c)
        | E::Equal(a, c)
        | E::SameTerm(a, c)
        | E::Greater(a, c)
        | E::GreaterOrEqual(a, c)
        | E::Less(a, c)
        | E::LessOrEqual(a, c)
        | E::Add(a, c)
        | E::Subtract(a, c)
        | E::Multiply(a, c)
        | E::Divide(a, c) => expr_uses_multiplicity(a) || expr_uses_multiplicity(c),
        E::UnaryPlus(a) | E::UnaryMinus(a) | E::Not(a) => expr_uses_multiplicity(a),
        E::If(a, c, d) => {
            expr_uses_multiplicity(a) || expr_uses_multiplicity(c) || expr_uses_multiplicity(d)
        }
        E::In(a, list) => expr_uses_multiplicity(a) || list.iter().any(expr_uses_multiplicity),
        E::Coalesce(list) | E::FunctionCall(_, list) => list.iter().any(expr_uses_multiplicity),
    }
}

fn eval_aggregate(graph: &Graph, local: &LocalVocab, b: &Bindings, members: &[usize], agg: &AggregateExpression) -> Result<Value, String> {
    match agg {
        AggregateExpression::CountSolutions { distinct } => {
            let n = if *distinct {
                let mut seen = std::collections::HashSet::new();
                members.iter().filter(|&&ri| seen.insert(b.rows[ri].clone())).count()
            } else {
                members.len()
            };
            Ok(Value::Num(Num::Int(n as i64)))
        }
        AggregateExpression::FunctionCall { name, expr, distinct } => {
            // MIN/MAX over an all-temporal column: fold at the ID level through the
            // temporals cache — no term materialised, no per-comparison lexical
            // re-parse. Falls through to the general path on any non-temporal member.
            if let AggregateFunction::Min | AggregateFunction::Max = name {
                let is_min = matches!(name, AggregateFunction::Min);
                if let Some(v) = minmax_temporal(graph, local, b, members, expr, *distinct, is_min) {
                    return Ok(v);
                }
            }
            // [OPUS-4.8] (sq-5qz9) A declared custom aggregate IRI: fold the group's
            // per-member values through the installed registry. Unlike the builtins,
            // the user aggregate sees the FULL member sequence (an unbound member is
            // passed as `None`, not skipped) so it can implement count-style or
            // unbound-sensitive aggregates; DISTINCT de-duplicates the materialised
            // member terms first (treating two unbound members as equal). The closure
            // works in `oxrdf::Term`, so the per-member value is materialised to a term.
            #[cfg(feature = "window-functions")]
            if let AggregateFunction::Custom(iri) = name {
                return eval_custom_aggregate(graph, local, b, members, expr, *distinct, iri.as_str());
            }
            // Collect the per-member values of `expr`. [OPUS-4.8] An UNBOUND member (a variable
            // with no binding in that row, e.g. an OPTIONAL one) is SKIPPED for every aggregate,
            // matching SPARQL "aggregate over the bound values": SUM/AVG over an OPTIONAL column
            // must still sum the rows that do have a value, not collapse to unbound. Only a
            // genuine expression ERROR (`Value::Error`, e.g. a type error inside `expr`) is fatal
            // for SUM/AVG. A BOUND but non-numeric member is pushed into `vals` and turns SUM/AVG
            // into a type error downstream (`as_numeric` -> None), per agg-err-01.
            let mut vals: Vec<Value> = Vec::with_capacity(members.len());
            let mut errored = false;
            // [OPUS-4.8] (sq-v411r, §B2) Only build the multiplicity table when the argument
            // actually calls `MULTIPLICITY()` — the overwhelmingly common aggregate pays
            // nothing (no table, no thread-local write) and folds the full bag below. When
            // present, fold the DISTINCT solutions instead, each weighted by its bag
            // cardinality via the thread-local, per the Set-Function algebra (see
            // `group_multiplicities`).
            match group_multiplicities(b, members, expr) {
                None => {
                    for &ri in members {
                        let v = eval_expr(graph, local, b, &b.rows[ri], expr)?;
                        match v {
                            Value::Unbound => {}             // skip: aggregate ignores unbound rows
                            Value::Error => errored = true,  // fatal for SUM/AVG (-> unbound aggregate)
                            _ => vals.push(v),
                        }
                    }
                }
                Some(distinct) => {
                    for (ri, card) in distinct {
                        let _mg = multiplicity::set(card);
                        let v = eval_expr(graph, local, b, &b.rows[ri], expr)?;
                        match v {
                            Value::Unbound => {}
                            Value::Error => errored = true,
                            _ => vals.push(v),
                        }
                    }
                }
            }
            if *distinct {
                dedup_values(&mut vals);
            }
            match name {
                AggregateFunction::Count => Ok(Value::Num(Num::Int(vals.len() as i64))),
                // SUM/AVG with operand-type promotion: int+int stays integer, decimals
                // stay decimal (exact), floats/doubles promote. Any non-numeric or
                // errored member makes the whole aggregate a type error (-> unbound).
                AggregateFunction::Sum => Ok(sum_values(&vals, errored).map(num_canonical_term).unwrap_or(Value::Error)),
                AggregateFunction::Avg => {
                    if vals.is_empty() && !errored {
                        return Ok(Value::Num(Num::Int(0))); // AVG({}) = 0 per SPARQL
                    }
                    Ok(sum_values(&vals, errored)
                        .and_then(|s| s.binop(Num::Int(vals.len() as i64), ArithOp::Div))
                        .map(Value::Num)
                        .unwrap_or(Value::Error))
                }
                // MIN/MAX over an all-numeric group return the typed VALUE (promoted,
                // canonically serialised — "2.0E-1"^^xsd:double); mixed groups keep the
                // lenient term path.
                AggregateFunction::Min => Ok(minmax_values(vals, Ordering::Less)),
                AggregateFunction::Max => Ok(minmax_values(vals, Ordering::Greater)),
                AggregateFunction::GroupConcat { separator } => {
                    let sep = separator.clone().unwrap_or_else(|| " ".to_string());
                    let joined = vals.iter().filter_map(value_str).collect::<Vec<_>>().join(&sep);
                    Ok(Value::Term(Term::Literal(Literal::new_simple_literal(joined))))
                }
                AggregateFunction::Sample => Ok(vals.into_iter().next().unwrap_or(Value::Unbound)),
                _ => Err("M2: unsupported aggregate".into()),
            }
        }
    }
}

/// [OPUS-4.8] (sq-5qz9) Evaluate a declared custom aggregate IRI against the
/// installed [`crate::CustomAggregateRegistry`]. Materialises each group member's
/// value of `expr` to an `Option<Term>` (`None` ≡ unbound for that member —
/// passed THROUGH, not skipped, so a user count-style aggregate can see it),
/// applies DISTINCT over the materialised members, then folds via the closure.
/// A missing registry / unregistered IRI is the same hard error the registry-free
/// path raises; a closure `Err` is a SPARQL expression error (→ unbound result).
#[cfg(feature = "window-functions")]
fn eval_custom_aggregate(
    graph: &Graph,
    local: &LocalVocab,
    b: &Bindings,
    members: &[usize],
    expr: &Expression,
    distinct: bool,
    iri: &str,
) -> Result<Value, String> {
    let Some(f) = aggregates::lookup(iri) else {
        return Err(format!("unsupported SPARQL function: no custom aggregate registered for <{iri}>"));
    };
    let mut args: Vec<Option<Term>> = Vec::with_capacity(members.len());
    // [OPUS-4.8] (sq-v411r) `MULTIPLICITY()` works inside a custom aggregate's argument too:
    // when it appears, fold the DISTINCT solutions weighted by each one's bag cardinality
    // (same algebra as the builtins); otherwise fold the full bag exactly as before.
    let mults = group_multiplicities(b, members, expr);
    let iter: Vec<(usize, Option<u64>)> = match &mults {
        None => members.iter().map(|&ri| (ri, None)).collect(),
        Some(distinct) => distinct.iter().map(|&(ri, card)| (ri, Some(card))).collect(),
    };
    for (ri, card) in iter {
        let _mg = card.map(multiplicity::set);
        let v = eval_expr(graph, local, b, &b.rows[ri], expr)?;
        // A genuine expression error inside the argument makes the aggregate a
        // SPARQL error (→ unbound), mirroring SUM/AVG; an unbound member is a
        // first-class `None` argument the user aggregate decides how to treat.
        if matches!(v, Value::Error) {
            return Ok(Value::Error);
        }
        args.push(value_as_term(&v));
    }
    if distinct {
        let mut seen: FxHashSet<Option<Term>> = FxHashSet::default();
        args.retain(|t| seen.insert(t.clone()));
    }
    match f(&args) {
        Ok(Some(t)) => Ok(Value::Term(t)),
        Ok(None) => Ok(Value::Unbound),
        Err(_) => Ok(Value::Error), // expression error → unbound aggregate (builtin discipline)
    }
}

/// Typed SUM with XPath promotion; `None` (a type error) if any member was non-numeric
/// or errored. The empty sum is `"0"^^xsd:integer`.
fn sum_values(vals: &[Value], errored: bool) -> Option<Num> {
    if errored {
        return None;
    }
    let mut acc = Num::Int(0);
    for v in vals {
        acc = acc.binop(as_numeric(v)?, ArithOp::Add)?;
    }
    Some(acc)
}

/// MIN/MAX: an all-numeric group compares by VALUE (exact for int/decimal) and returns
/// the typed value; any non-numeric member falls back to the lenient total-order term
/// comparison (which must order across types for the SPARQL MIN/MAX-over-anything case).
fn minmax_values(vals: Vec<Value>, keep: Ordering) -> Value {
    if vals.is_empty() {
        return Value::Unbound;
    }
    let nums: Option<Vec<Num>> = vals.iter().map(as_numeric).collect();
    match nums {
        Some(nums) => {
            let mut best = nums[0];
            for &n in &nums[1..] {
                if num_compare(n, best) == Some(keep) {
                    best = n;
                }
            }
            num_canonical_term(best)
        }
        None => {
            let cmp = |a: &Value, c: &Value| compare_values(a, c).unwrap_or(Ordering::Equal);
            match keep {
                Ordering::Less => vals.into_iter().min_by(cmp).unwrap(),
                _ => vals.into_iter().max_by(cmp).unwrap(),
            }
        }
    }
}

/// MIN/MAX over a variable whose group members are ALL well-formed temporal
/// (dateTime/date) graph terms, folded at the id level through the temporals cache.
/// `None` falls back to the general (materialise + compare_values) path: any unbound
/// member is skipped (as the general path skips it), but a local-vocab or
/// non-temporal member aborts the fast path entirely.
///
/// Tie semantics replicate `minmax_values` exactly: the comparator is
/// `compare_values(..).unwrap_or(Equal)` — which for two temporals IS
/// `Temporal::cmp_t_total` (kind-first, then the timeline order extended over the
/// indeterminate mixed-timezone window) — with MIN keeping the FIRST of
/// equal members (`Iterator::min_by`) and MAX the LAST (`Iterator::max_by`); DISTINCT
/// drops later duplicate terms first (same term ⇔ same id for graph terms), which can
/// change which of two equal-VALUED but distinct terms MAX returns, exactly as the
/// general path's `dedup_values` does.
fn minmax_temporal(
    graph: &Graph,
    local: &LocalVocab,
    b: &Bindings,
    members: &[usize],
    expr: &Expression,
    distinct: bool,
    is_min: bool,
) -> Option<Value> {
    let Expression::Variable(v) = expr else { return None };
    let col = b.col(v)?;
    let mut seen: FxHashSet<Id> = FxHashSet::default();
    let mut best: Option<(Temporal, Id)> = None;
    for &ri in members {
        let id = b.rows[ri][col];
        if id == NO_ID {
            continue; // unbound member: MIN/MAX skips it
        }
        if is_local(id) {
            return None; // computed term: general path
        }
        let t = graph.temporal_value(id)?; // non-temporal/ill-formed: general path
        if distinct && !seen.insert(id) {
            continue;
        }
        best = Some(match best {
            None => (t, id),
            Some((bt, bid)) => {
                // [FABLE-5] sq-wjl8i KIND-FIRST + [SONNET-4.6] sq-2k5py, both now in the
                // shared `Temporal::cmp_t_total`, so this fold cannot drift from
                // `compare_values`: a cross-kind (dateTime vs date) pair ranks by
                // `LiteralKind` (DateTime < Date), never lexically, and within a kind the
                // timeline order is TOTAL (instant, then timezone presence) — the former
                // lexical fallback for the indeterminate window was intransitive.
                let ord = Temporal::cmp_t_total(t, bt);
                let replace = if is_min { ord == Ordering::Less } else { ord != Ordering::Less };
                if replace {
                    (t, id)
                } else {
                    (bt, bid)
                }
            }
        });
    }
    Some(match best {
        Some((_, id)) => Value::Term(term_of(graph, local, id).expect("aggregate member id resolves")),
        None => Value::Unbound, // no bound members
    })
}

/// Value comparison of two typed numerics: exact when both are int/decimal, f64 otherwise.
fn num_compare(a: Num, c: Num) -> Option<Ordering> {
    if let (Some(x), Some(y)) = (a.to_dec(), c.to_dec()) {
        if let Some(o) = x.cmp(y) {
            return Some(o);
        }
    }
    a.f64().partial_cmp(&c.f64())
}

fn dedup_values(vals: &mut Vec<Value>) {
    let mut seen = std::collections::HashSet::new();
    vals.retain(|v| seen.insert(value_key(v)));
}

fn value_key(v: &Value) -> String {
    match v {
        Value::Term(t) => format!("T{t}"),
        Value::Num(n) => format!("N{}^^{}", n.lexical(), n.datatype().as_str()),
        Value::Bool(b) => format!("B{b}"),
        Value::Unbound => "U".to_string(),
        Value::Error => "E".to_string(),
    }
}

// ---- Modifiers ----------------------------------------------------------------

fn project_bindings(b: Bindings, vars: &[Variable]) -> Bindings {
    let cols: Vec<Option<usize>> = vars.iter().map(|v| b.col(v)).collect();
    let rows = b
        .rows
        .iter()
        .map(|row| cols.iter().map(|c| c.map(|i| row[i]).unwrap_or(NO_ID)).collect())
        .collect();
    let sorted_by = b.sorted_by.filter(|sv| vars.contains(sv));
    Bindings { vars: vars.to_vec(), rows, sorted_by }
}

fn distinct_bindings(b: &mut Bindings) {
    let mut seen = std::collections::HashSet::new();
    b.rows.retain(|r| seen.insert(r.clone()));
}

fn slice_bindings(b: &mut Bindings, start: usize, length: Option<usize>) {
    if start > 0 {
        b.rows.drain(0..start.min(b.rows.len()));
    }
    if let Some(l) = length {
        b.rows.truncate(l);
    }
}

/// One precomputed ORDER BY key cell. A temporal (dateTime/date) graph term keeps only
/// its CACHED comparison value + id — no term materialised, no per-comparison lexical
/// re-parse (the q09-class fix: ORDER BY dateTime was re-parsing both lexicals on every
/// comparison of the sort). Everything else keeps the identity-preserving `Value`.
enum SortCell {
    Temp { t: Temporal, id: Id },
    /// A numeric GRAPH term: the cached f64 for the fast compare PLUS its dictionary id, so
    /// an f64 TIE can be rechecked EXACTLY from the id's exact lexical — distinct integers
    /// beyond 2^53 / high-precision decimals that share one f64 (the numerics cache stores
    /// only f64, so the fast path alone collapses them). This makes `ORDER BY ?v` over a
    /// numeric column agree with the relational `<` (`cmp_expr`) and MIN/MAX, which already
    /// recheck. [OPUS-4.8] sq-rikm7
    Num { f: f64, id: Id },
    /// A named-node (IRI) GRAPH term: the IRI string precomputed once at key-build time,
    /// eliminating per-comparison `term_of` materialisation and `value_str` allocation for
    /// IRI-typed ORDER BY columns (the SP2Bench q11 case: all ?ee values are IRIs, so
    /// every comparison calls into `compare_terms` which allocates the string twice).
    /// `cmp_sort_cells` can then directly compare two `&str` slices — no allocation.
    /// [SONNET-4.6] sq-7d3dj.30.2
    Iri(Box<str>),
    /// [FABLE-5] sq-7d3dj.30.21 — a PLAIN `xsd:string` LITERAL GRAPH term carried as its
    /// DICTIONARY ID only, deferring the value materialisation the eager [`SortCell::Val`] arm
    /// does at construction time (a `reconstruct_ref` `Literal` alloc + a `value_str`
    /// collation-key alloc per input row). Under the `topk-lazy-strkey` feature the top-k
    /// ORDER BY key build emits this instead of `Val{..}` for a plain-string column, so an
    /// ORDER-BY on such a column over N input rows does ZERO key allocation up front (the
    /// SP2Bench q11 residual: only k of the 17663 keyed rows survive). `cmp_sort_cells`
    /// compares two `StrId` cells by their ZERO-COPY `Dict::term_parts` `value` bytes, which is
    /// BYTE-IDENTICAL to comparing the two eager `value_str` keys (a plain string orders by its
    /// `value()` lexical bytes — the sq-7d3dj.30.12 differential test proves it). Cross-kind /
    /// cross-class comparisons use the fixed `String`-kind / `Literal`-class ranks (a plain
    /// string literal is always Literal-class, String-kind), so those arms need no
    /// materialisation either.
    #[cfg(feature = "topk-lazy-strkey")]
    StrId(Id),
    /// Any other key value (a plain / typed / language-tagged literal, a blank node, a
    /// quoted triple term, a computed value, or an unbound / error). Extends the `Iri`
    /// fast-path idea to EVERY `SortCell` kind (bead sq-7d3dj.30.12): the SPARQL
    /// total-order dispatch is HOISTED to cell-CONSTRUCTION time so a heap comparison is
    /// an integer / byte-slice compare, never a per-comparison `lit_kind` +
    /// `is_numeric_dt` + `value_str`-allocation re-derivation.
    ///
    /// - `class` — the [`TermClass`] rank (cross-class compares reduce to `class.cmp`).
    /// - `kind` — the within-Literal [`LiteralKind`] rank (cross-kind compares reduce to
    ///   `kind.cmp`); a fixed filler for non-literal classes (never consulted there).
    /// - `key` — the PRECOMPUTED lexical collation key (`value_str`), present for exactly
    ///   the kinds whose within-kind order IS the lexical `value()` order — the `String`,
    ///   `Lang` and `Other` literal kinds and the `Blank` class (see `cmp_sort_cells`'s
    ///   `(Val, Val)` arm for why this reproduces `compare_terms` exactly there). `None`
    ///   for the VALUE-ordered kinds (numeric exact-tie / boolean / temporal timeline) and
    ///   for triple terms, which keep `v`'s full `compare_values` semantics.
    /// - `v` — retained so a value-ordered same-kind pair (and the triple-term recursion)
    ///   stays byte-identical to `compare_terms`.
    ///
    /// All ranks + the key are taken ONCE, from the very `CompareTerm` observations
    /// `compare_terms` would otherwise recompute on every comparison. [FABLE-5] sq-7d3dj.30.12
    Val { class: u8, kind: u8, key: Option<Box<str>>, v: Value },
}

/// Builds a `SortCell::Val`, precomputing its `(TermClass, LiteralKind)` collation ranks
/// AND — for the lexically-ordered kinds only — the `value_str` collation key, from the
/// SAME `CompareTerm` observations `compare_terms` reads. So a `Val`↔`Val` comparison is
/// an integer rank compare (cross-class / cross-kind) or a precomputed byte-slice compare
/// (same lexical kind), never a per-comparison `lit_kind` / `is_numeric_dt` /
/// `value_str`-allocation re-derivation. [FABLE-5] sq-7d3dj.30.12
#[inline]
fn sort_cell_val(v: Value) -> SortCell {
    let class = v.term_class() as u8;
    // Only the literal class consults the kind rank; skip the (cheap but non-trivial)
    // `lit_kind` dispatch entirely for the non-literal classes.
    let kind = if class == TermClass::Literal as u8 { v.literal_kind() as u8 } else { 0 };
    // Precompute the lexical key for EXACTLY the kinds whose within-kind (and, for the
    // literal kinds, same-KIND) order is the `value_str` lexical order — so a same-kind
    // compare is a direct slice compare with NO per-comparison allocation, reproducing
    // `compare_terms`' within-kind result (proven byte-identical by the differential test):
    //   • String / Lang / Other literal kinds — `compare_terms`' `strict_cmp` arm (where it
    //     decides: same-tag / same-other-XSD) yields the SAME `value()` order as its
    //     `value_str` fallback (cross-tag / cross-other-XSD), so the whole kind orders by
    //     `value_str` (`value()`);
    //   • the Blank class — `compare_terms` orders blanks by their `value_str` label.
    // Numeric (exact-tie recheck), Boolean and the temporal kinds are VALUE-ordered, and
    // triple terms recurse — those keep `None` and defer to `compare_values`.
    let key = if class == TermClass::Blank as u8
        || (class == TermClass::Literal as u8
            && (kind == LiteralKind::String as u8
                || kind == LiteralKind::Lang as u8
                || kind == LiteralKind::Other as u8))
    {
        value_str(&v).map(String::into_boxed_str)
    } else {
        None
    };
    SortCell::Val { class, kind, key, v }
}

/// Compares two ORDER BY key cells under the lenient total order, reproducing
/// `compare_values` exactly: two temporals by `Temporal::cmp_t_total` (kind-first, then
/// the timeline order extended over the indeterminate mixed-timezone window — the same
/// definition `compare_values` reaches through `CompareTerm::strict_cmp`); a temporal
/// against any other key materialises the term lazily (rare: only mixed-type columns)
/// and defers to `compare_values` itself.
#[inline]
fn cmp_sort_cells(graph: &Graph, local: &LocalVocab, a: &SortCell, c: &SortCell) -> Ordering {
    match (a, c) {
        (SortCell::Temp { t: ta, .. }, SortCell::Temp { t: tb, .. }) => {
            // [FABLE-5] sq-wjl8i KIND-FIRST + [SONNET-4.6] sq-2k5py: both now live in the
            // shared `Temporal::cmp_t_total` — a dateTime never value-compares against a
            // date (`LiteralKind::DateTime < Date`), and within one kind the timeline order
            // is TOTAL (instant, then timezone presence). The former lexical fallback for
            // the indeterminate window is gone: it mixed timeline-decided and
            // lexical-decided pairs inside one kind, which is intransitive. Ill-formed
            // temporals never enter the cache, so both cells here are well-formed.
            Temporal::cmp_t_total(*ta, *tb)
        }
        // Two numeric graph terms: f64 fast compare, with the EXACT tie recheck below.
        (SortCell::Num { f: fa, id: ia }, SortCell::Num { f: fb, id: ib }) => {
            cmp_sort_num(graph, *fa, *ia, *fb, *ib)
        }
        (SortCell::Temp { id, .. }, SortCell::Val { v, .. }) => {
            compare_values(&sort_cell_term(graph, local, *id), v).unwrap_or(Ordering::Equal)
        }
        (SortCell::Val { v, .. }, SortCell::Temp { id, .. }) => {
            compare_values(v, &sort_cell_term(graph, local, *id)).unwrap_or(Ordering::Equal)
        }
        // A numeric cell against a temporal or a general Value (a MIXED-type column, cold):
        // reconstruct the pre-change `Val(Num::Double)` representation and defer to the shared
        // `compare_values`, so the mixed-column order stays byte-identical to pre-change — only
        // the same-numeric-column (`Num`, `Num`) arm above adds the exact f64-tie recheck.
        (SortCell::Num { f, .. }, SortCell::Temp { id, .. }) => {
            compare_values(&Value::Num(Num::Double(*f)), &sort_cell_term(graph, local, *id)).unwrap_or(Ordering::Equal)
        }
        (SortCell::Temp { id, .. }, SortCell::Num { f, .. }) => {
            compare_values(&sort_cell_term(graph, local, *id), &Value::Num(Num::Double(*f))).unwrap_or(Ordering::Equal)
        }
        (SortCell::Num { f, .. }, SortCell::Val { v, .. }) => {
            compare_values(&Value::Num(Num::Double(*f)), v).unwrap_or(Ordering::Equal)
        }
        (SortCell::Val { v, .. }, SortCell::Num { f, .. }) => {
            compare_values(v, &Value::Num(Num::Double(*f))).unwrap_or(Ordering::Equal)
        }
        // Two IRI sort cells: direct string comparison — no allocation, no term_class
        // dispatch. [SONNET-4.6] sq-7d3dj.30.2
        (SortCell::Iri(a), SortCell::Iri(b)) => a.as_ref().cmp(b.as_ref()),
        // IRI against a Num/Temp cell (a MIXED-type column): IRIs are term-class Iri
        // (rank 2 in the SPARQL total order), literals are Literal (rank 3) — so IRIs
        // always sort before any literal, regardless of numeric or temporal subtype.
        (SortCell::Iri(_), SortCell::Num { .. }) => Ordering::Less,
        (SortCell::Num { .. }, SortCell::Iri(_)) => Ordering::Greater,
        (SortCell::Iri(_), SortCell::Temp { .. }) => Ordering::Less,
        (SortCell::Temp { .. }, SortCell::Iri(_)) => Ordering::Greater,
        // IRI against a generic Val: dispatch on the Val variant to determine rank.
        // Val can hold Unbound (rank 0), BlankNode (rank 1), NamedNode/IRI (rank 2),
        // Literal/Num/Bool (rank 3), Triple (rank 4).
        (SortCell::Iri(a), SortCell::Val { v, .. }) => match v {
            Value::Unbound | Value::Error => Ordering::Greater, // IRI after unbound
            Value::Term(Term::BlankNode(_)) => Ordering::Greater, // IRI after blank node
            Value::Term(Term::NamedNode(n)) => a.as_ref().cmp(n.as_str()), // same class
            _ => Ordering::Less, // IRI before literals and triple terms
        },
        (SortCell::Val { v, .. }, SortCell::Iri(a)) => match v {
            Value::Unbound | Value::Error => Ordering::Less,
            Value::Term(Term::BlankNode(_)) => Ordering::Less,
            Value::Term(Term::NamedNode(n)) => n.as_str().cmp(a.as_ref()),
            _ => Ordering::Greater,
        },
        // [FABLE-5] sq-7d3dj.30.21 — LAZY plain-string-literal cells. `StrId(id)` denotes a
        // plain `xsd:string` literal: TermClass::Literal (rank 3), LiteralKind::String (rank
        // 4), value = the literal's `value` slice (via `Dict::term_parts`). Every arm below
        // reproduces the order the eager `Val{class:3, kind:4, key:Some(value)}` cell would
        // give BYTE-IDENTICALLY, with no per-row `value_str` allocation. The homogeneous
        // `(StrId, StrId)` arm is the hot q11 comparator; the cross-type arms cover a mixed key
        // column (an ORDER BY expression that yields plain strings on some rows and other terms
        // on others).
        #[cfg(feature = "topk-lazy-strkey")]
        (SortCell::StrId(a), SortCell::StrId(b)) => {
            // Same class (Literal) + same kind (String) → lexical value-byte order, exactly
            // the eager `(Some(la), Some(lb)) => la.cmp(lb)` `Val` arm.
            str_id_value(graph, *a).cmp(str_id_value(graph, *b))
        }
        // String literal (Literal-class rank 3) vs an IRI (rank 2): the literal sorts AFTER the
        // IRI — regardless of value.
        #[cfg(feature = "topk-lazy-strkey")]
        (SortCell::StrId(_), SortCell::Iri(_)) => Ordering::Greater,
        #[cfg(feature = "topk-lazy-strkey")]
        (SortCell::Iri(_), SortCell::StrId(_)) => Ordering::Less,
        // String literal (kind String rank 4) vs a numeric (kind Numeric rank 0) or temporal
        // (kind DateTime rank 2 / Date rank 3) — all Literal-class, and String's kind rank is
        // strictly greater than every one of those, so the string sorts AFTER, by kind rank.
        #[cfg(feature = "topk-lazy-strkey")]
        (SortCell::StrId(_), SortCell::Num { .. }) => Ordering::Greater,
        #[cfg(feature = "topk-lazy-strkey")]
        (SortCell::Num { .. }, SortCell::StrId(_)) => Ordering::Less,
        #[cfg(feature = "topk-lazy-strkey")]
        (SortCell::StrId(_), SortCell::Temp { .. }) => Ordering::Greater,
        #[cfg(feature = "topk-lazy-strkey")]
        (SortCell::Temp { .. }, SortCell::StrId(_)) => Ordering::Less,
        // String literal vs a generic Val — mirror the eager `Val` dispatch by the OTHER cell's
        // precomputed class/kind ranks against the fixed (Literal=3, String=4) ranks of a plain
        // string, then compare value bytes for the same-class-same-kind (String) case.
        #[cfg(feature = "topk-lazy-strkey")]
        (SortCell::StrId(a), SortCell::Val { class: cb, kind: kb, key: kb_key, v: cv }) => {
            cmp_strid_val(graph, *a, *cb, *kb, kb_key.as_deref(), cv)
        }
        #[cfg(feature = "topk-lazy-strkey")]
        (SortCell::Val { class: ca, kind: ka, key: ka_key, v: av }, SortCell::StrId(b)) => {
            cmp_strid_val(graph, *b, *ca, *ka, ka_key.as_deref(), av).reverse()
        }
        // Two generic key values: compare the PRECOMPUTED class rank, then (within the
        // literal class) the PRECOMPUTED kind rank — both integer compares, no per-comparison
        // `lit_kind` / `is_numeric_dt` re-derivation. Only when the ranks tie (same class,
        // and same literal kind if literal) do we fall through to `compare_values` for the
        // within-kind value order — which, given equal class+kind, reaches EXACTLY the same
        // within-kind arm `compare_terms` would (the numeric exact-tie recheck, the
        // timeline / strict compare, or the lexical fallback). So the total order is
        // byte-identical to `compare_values(av, cv)`, just with the cross-class / cross-kind
        // dispatch hoisted to construction time. [FABLE-5] sq-7d3dj.30.12
        (
            SortCell::Val { class: ca, kind: ka, key: ka_key, v: av },
            SortCell::Val { class: cb, kind: kb, key: kb_key, v: cv },
        ) => match ca.cmp(cb) {
            Ordering::Equal => {
                // Same class. Within the literal class, rank by kind first; other classes
                // (blank / IRI / triple / error-or-unbound) have no kind split.
                if *ca == TermClass::Literal as u8 && ka != kb {
                    return ka.cmp(kb);
                }
                // Same class (and same literal kind, if literal). When BOTH cells carry a
                // precomputed lexical key — the `String` / `Lang` / `Other` literal kinds
                // and the `Blank` class — the within-kind order IS the `value_str` (lexical
                // `value()`) order, so compare the precomputed slices directly: no
                // per-comparison `value_str` allocation, no re-dispatch. This is byte-
                // identical to `compare_values(av, cv)` for those kinds (the differential
                // test proves it). Anything else (numeric exact-tie, boolean, temporal,
                // triple, error/unbound) keeps `None` and defers to the shared comparator.
                match (ka_key, kb_key) {
                    (Some(la), Some(lb)) => la.cmp(lb),
                    _ => compare_values(av, cv).unwrap_or(Ordering::Equal),
                }
            }
            ord => ord,
        },
    }
}

/// Compares two numeric ORDER BY sort cells by f64, rechecking EXACTLY on an f64 tie.
/// [OPUS-4.8] sq-rikm7: f64 rounding is MONOTONIC, so it only ever collapses distinct
/// numeric values to Equal — so on (and only on) an f64 tie, disambiguate via the ids'
/// exact lexicals (`exact_numeric_lexical` + `cmp_decimal_str`, the SAME exact path the
/// relational `cmp_expr` uses). [FABLE-5] sq-wjl8i extends the recheck to the MIXED
/// exact/inexact tie: a float/double id has no exact lexical but its VALUE is exactly
/// the tied f64, so the exact side compares against the f64's exact decimal expansion —
/// mirroring `compare_values`' `Num::cmp_total` recheck, so the numeric fast path and
/// the general path order identically. Perf-neutral: the allocations happen only on a
/// tie, never on the fast path.
#[inline]
fn cmp_sort_num(graph: &Graph, fa: f64, ia: Id, fb: f64, ib: Id) -> Ordering {
    match fa.partial_cmp(&fb) {
        Some(Ordering::Equal) => {
            // Same dictionary id ⇒ identical value: skip the two lexical allocations.
            // In a numeric ORDER BY column with repeated values this is the common f64
            // tie (a sort compares equal-id rows often). [OPUS-4.8] sq-rikm7
            if ia == ib {
                return Ordering::Equal;
            }
            match (graph.exact_numeric_lexical(ia), graph.exact_numeric_lexical(ib)) {
                (Some(la), Some(lb)) => cmp_decimal_str(&la, &lb).unwrap_or(Ordering::Equal),
                (Some(la), None) => cmp_exact_lex_f64(&la, fb),
                (None, Some(lb)) => cmp_exact_lex_f64(&lb, fa).reverse(),
                // Both float/double: the value IS the tied f64 — a true tie.
                (None, None) => Ordering::Equal,
            }
        }
        Some(o) => o,
        // NaN. Unreachable from ORDER BY sort cells today (the numerics cache uses NaN
        // as its "not numeric" sentinel, so a NaN literal never becomes a `SortCell::Num`
        // and routes through `compare_values` instead) — kept in lock-step with the
        // total order's NaN-first rule so the fast path can never diverge. [FABLE-5] sq-wjl8i
        None => match (fa.is_nan(), fb.is_nan()) {
            (true, false) => Ordering::Less,
            (false, true) => Ordering::Greater,
            _ => Ordering::Equal,
        },
    }
}

/// The mixed exact/inexact leg of the f64-tie recheck: an exact int/decimal LEXICAL
/// against a (finite, non-NaN) f64's exact decimal expansion — string arithmetic
/// throughout, arbitrary precision. An infinite f64 image (a numeric lexical beyond
/// f64's finite range collapsed onto ±INF) bounds every finite exact value directly.
/// [FABLE-5] sq-wjl8i
#[cold]
fn cmp_exact_lex_f64(lex: &str, f: f64) -> Ordering {
    if f == f64::INFINITY {
        return Ordering::Less;
    }
    if f == f64::NEG_INFINITY {
        return Ordering::Greater;
    }
    match f64_exact_decimal(f) {
        Some(exp) => cmp_decimal_str(lex, &exp).unwrap_or(Ordering::Equal),
        None => Ordering::Equal, // NaN: handled by the caller's NaN rule
    }
}

// [SONNET-4.6] sq-2k5py: the lexical-form fallback for temporal sort cells (`cmp_sort_cells_lex`)
// is GONE — `Temporal::cmp_t_total` decides every temporal pair by value now, and a lexical
// fallback inside one temporal kind is exactly the intransitivity this bead removed.

/// Materialises a temporal sort cell's term for the (rare) mixed-type-column
/// comparison against a non-temporal key.
#[cold]
fn sort_cell_term(graph: &Graph, local: &LocalVocab, id: Id) -> Value {
    Value::Term(term_of(graph, local, id).expect("sort key id resolves"))
}

/// [FABLE-5] sq-7d3dj.30.21 — the ZERO-COPY value `&str` of a plain-string-literal dictionary
/// id, borrowed straight from the record store (no allocation). Only called on ids `cell_of`
/// already proved are plain `xsd:string` literals (`Dict::plain_string_value` returned `Some`),
/// so the non-plain-string arm is unreachable; it returns the empty slice as a safe
/// placeholder rather than panic.
#[cfg(feature = "topk-lazy-strkey")]
#[inline]
fn str_id_value(graph: &Graph, id: Id) -> &str {
    graph.dict.plain_string_value(id).unwrap_or("")
}

/// [FABLE-5] sq-7d3dj.30.21 — order a lazy plain-string-literal cell (`StrId(a)`: fixed
/// `TermClass::Literal` rank 3, `LiteralKind::String` rank 4, value = the literal's `value`
/// slice) against an EAGER `Val` cell carrying its own precomputed `(class, kind, key, v)`.
/// This is byte-identical to the `(Val, Val)` arm of [`cmp_sort_cells`] with the string's fixed
/// ranks: compare class ranks first; within the Literal class compare kind ranks; only when
/// BOTH are Literal-class String-kind (the string's kind) do we compare value bytes — the
/// eager String-kind `Val` always carries `key = Some(value_str)` (see `sort_cell_val`), which
/// for a plain string IS the `value()` bytes, so a direct slice compare against
/// `str_id_value(a)` reproduces the eager `(Some, Some) => la.cmp(lb)` order exactly.
#[cfg(feature = "topk-lazy-strkey")]
#[inline]
fn cmp_strid_val(graph: &Graph, a: Id, vclass: u8, vkind: u8, vkey: Option<&str>, v: &Value) -> Ordering {
    let str_class = TermClass::Literal as u8;
    let str_kind = LiteralKind::String as u8;
    match str_class.cmp(&vclass) {
        Ordering::Equal => {
            // Both Literal-class. Rank by kind first (String vs the Val's kind).
            if str_kind != vkind {
                return str_kind.cmp(&vkind);
            }
            // Both Literal-class String-kind: value-byte order. A String-kind `Val` always
            // carries a precomputed lexical key; fall back to `value_str` only if (unexpectedly)
            // absent, so the comparison never silently mis-orders.
            match vkey {
                Some(lb) => str_id_value(graph, a).cmp(lb),
                None => match value_str(v) {
                    Some(lb) => str_id_value(graph, a).cmp(lb.as_str()),
                    None => Ordering::Equal,
                },
            }
        }
        ord => ord,
    }
}

/// Sort or bounded-select the bindings according to `exprs`.
///
/// When `row_budget` is `Some(k)` AND `k < b.rows.len()`, uses bounded selection
/// (quickselect O(n) + sort O(k log k)) instead of a full stable sort O(n log n).
/// The top-k path uses `input_idx` as a tiebreaker to reproduce the stable sort's
/// tie behaviour EXACTLY — byte-identical to `order_bindings(…, None)` + slice
/// `[0..k]` for any k. When `row_budget` is `None` or `k >= n`, uses the full
/// stable sort (unchanged). [SONNET-4.6] sq-7d3dj.30.2
///
/// Each ORDER expression is compiled ONCE up front (`compile_expr`) so the
/// Variable → column-index resolution is hoisted out of the per-row loop; both the
/// bounded-selection and full-sort paths share the same `key_of`/`cell_of`, so the
/// hoist and the top-k bound compose without either path re-resolving columns per
/// row. [OPUS-4.8] sq-7d3dj.4
fn order_bindings(
    graph: &Graph,
    local: &LocalVocab,
    b: &mut Bindings,
    exprs: &[OrderExpression],
    row_budget: Option<usize>,
) -> Result<(), String> {
    // Pre-resolve Variable → column index once for each ORDER expression. [OPUS-4.8] sq-7d3dj.4.
    let compiled_order: Vec<(bool, CompiledExpr)> = exprs
        .iter()
        .map(|oe| match oe {
            OrderExpression::Asc(e) => (false, compile_expr(e, b)),
            OrderExpression::Desc(e) => (true, compile_expr(e, b)),
        })
        .collect();

    // The sort key cell for one compiled ORDER expression of one row. Numeric keys use the
    // numerics cache and temporal keys the temporals cache (no per-comparison reparse); IRI
    // terms precompute the IRI string once (SortCell::Iri) — eliminating per-comparison
    // term_of materialisation + value_str allocation for IRI ORDER BY columns; other
    // expressions fall back to identity-preserving evaluation. The plain-variable case is
    // unpacked here so the column lookup and the cache probes happen exactly once per row
    // (column index was pre-resolved above). [OPUS-4.8] sq-7d3dj.4 / [SONNET-4.6] sq-7d3dj.30.2 (Iri).
    let cell_of = |row: &Row, e: &CompiledExpr| -> Result<SortCell, String> {
        if let CompiledExpr::Var(Some(c)) = e {
            let id = row[*c];
            if id != NO_ID && !is_local(id) {
                if let Some(n) = graph.numeric_value(id) {
                    // [OPUS-4.8] sq-rikm7: keep the id so an f64 TIE can be rechecked
                    // exactly (integers > 2^53 / high-precision decimals sharing one f64).
                    return Ok(SortCell::Num { f: n, id });
                }
                if let Some(t) = graph.temporal_value(id) {
                    return Ok(SortCell::Temp { t, id });
                }
                // [FABLE-5] sq-7d3dj.30.21 — LAZY STRING-LITERAL key: a plain `xsd:string`
                // store-literal becomes a zero-allocation `SortCell::StrId(id)` (compared via
                // the literal's ZERO-COPY `Dict::term_parts` `value` bytes) instead of eagerly
                // reconstructing a `Literal` (`term_of`) AND allocating a `value_str` collation
                // key (`sort_cell_val`) for every input row. `plain_string_value` is a single
                // record probe that returns `Some` for EXACTLY the `LiteralKind::String` set
                // (datatype `xsd:string`, no lang tag), so the SPARQL value-order is preserved.
                // The eager `Val{..}` key remains the feature-OFF path (byte-identical order).
                // This targets the SP2Bench q11 residual: N=17663 keyed, k=60 survive.
                #[cfg(feature = "topk-lazy-strkey")]
                if graph.dict.plain_string_value(id).is_some() {
                    return Ok(SortCell::StrId(id));
                }
                // Neither numeric nor temporal: materialise the term once. For IRI terms,
                // store the IRI string in SortCell::Iri so comparisons are direct &str
                // comparisons with no per-comparison allocation. [SONNET-4.6] sq-7d3dj.30.2
                let term = term_of(graph, local, id).expect("bound id resolves");
                if let Term::NamedNode(n) = &term {
                    return Ok(SortCell::Iri(n.as_str().into()));
                }
                return Ok(sort_cell_val(Value::Term(term)));
            }
        }
        Ok(match eval_compiled_numeric(graph, local, row, e) {
            Some(n) => sort_cell_val(Value::Num(Num::Double(n))),
            None => sort_cell_val(eval_compiled(graph, local, b, row, e)?),
        })
    };
    // The sort key (vector of (descending, SortCell)) for one row.
    let key_of = |row: &Row| -> Result<Vec<(bool, SortCell)>, String> {
        let mut key = Vec::with_capacity(compiled_order.len());
        for (desc, ce) in &compiled_order {
            key.push((*desc, cell_of(row, ce)?));
        }
        Ok(key)
    };

    let n = b.rows.len();

    // Top-k bounded-selection path: O(n + k log k) instead of O(n log n).
    // Activated when the caller supplies a row_budget k < n. The comparator
    // adds `input_idx` as a tiebreaker so the partition and final sort reproduce
    // the stable-sort tie semantics exactly (smaller input_idx appears first).
    // [SONNET-4.6] sq-7d3dj.30.2
    if let Some(k) = row_budget {
        // LIMIT 0 (k == 0) is legal SPARQL and is exercised by the W3C conformance
        // suite. The result is empty regardless of order, so short-circuit here:
        // `select_nth_unstable_by(k - 1)` below would underflow `k - 1` to
        // `usize::MAX` and abort the process (SIGABRT). [OPUS-4.8] sq-7d3dj.30.2
        if k == 0 {
            b.rows.clear();
            b.sorted_by = None;
            return Ok(());
        }
        // Invariant for the bounded-selection path below: 0 < k < n, so
        // `k - 1 < n = keyed.len()` and `select_nth_unstable_by(k - 1)` is in range.
        if k < n {
            // Build (key, input_idx) — parallel for large sets. INDEX-CARRY: the keyed
            // vector holds only the sort key + the original `b.rows` index, NOT a cloned
            // `Row`. `key_of` borrows each row read-only (via `cell_of`, which touches
            // `graph`/`local` but never `b.rows`), so `b.rows` is still owned + intact
            // after this build; only the k surviving rows are cloned when we gather the
            // output below. This eliminates the n up-front `Row::clone`s of the previous
            // `(key, input_idx, Row)` tuple — only k clones happen (n=17663 → k=60 on the
            // SP2Bench q11 residual). Byte-identical output: the tuple index reproduces the
            // same stable-sort tie order, and the gathered row is `b.rows[i]` unchanged.
            // [SONNET-4.6] sq-7d3dj.30.23
            // Use Vec<_> to avoid the clippy::type_complexity lint on the explicit type.
            #[cfg(feature = "parallel")]
            let mut keyed: Vec<_> = if n >= PAR_THRESHOLD {
                use rayon::prelude::*;
                // sq-6aefu: mirror FILTER/BIND worker_install pattern — key_of -> eval_compiled
                // can re-enter EXISTS / custom extension functions / spatial expressions on rayon
                // workers; without the snapshot+reinstall the workers see NO view (named-graph
                // leak) and NO function registry (spurious error). [SONNET-4.6]
                let fns = functions::snapshot();
                let vw = view::snapshot();
                let spx = spatial::snapshot();
                // [OPUS-5] (sq-lsp7k.2.2) Keep LOCAL SERVICE handlers visible on the worker too:
                // a worker that missed the registry would dial the IRI instead of answering it.
                #[cfg(feature = "service-local")]
                let lsv = local_services::snapshot();
                #[cfg(not(target_arch = "wasm32"))]
                let qn = query_now::snapshot(); // sq-98w7z.1: keep NOW() pinned on workers
                b.rows
                    .par_iter()
                    .enumerate()
                    .map(|(i, row)| {
                        let _fns = functions::worker_install(&fns);
                        let _vw = view::worker_install(&vw);
                        let _spx = spatial::worker_install(&spx);
                        #[cfg(feature = "service-local")]
                        let _lsv = local_services::worker_install(&lsv);
                        #[cfg(not(target_arch = "wasm32"))]
                        let _qn = query_now::worker_install(qn);
                        Ok((key_of(row)?, i))
                    })
                    .collect::<Result<Vec<_>, String>>()?
            } else {
                b.rows
                    .iter()
                    .enumerate()
                    .map(|(i, row)| Ok((key_of(row)?, i)))
                    .collect::<Result<Vec<_>, String>>()?
            };
            #[cfg(not(feature = "parallel"))]
            let mut keyed: Vec<_> = b
                .rows
                .iter()
                .enumerate()
                .map(|(i, row)| Ok((key_of(row)?, i)))
                .collect::<Result<_, String>>()?;

            // Strict total-order comparator: sort key first (descending as flagged),
            // then input_idx as tiebreaker (smaller index = appears earlier in the
            // stable sort, so it sorts LESS here — reproduces the stable sort exactly).
            let cmp_total = |a: &(Vec<(bool, SortCell)>, usize), c: &(Vec<(bool, SortCell)>, usize)| {
                for ((desc, av), (_, cv)) in a.0.iter().zip(c.0.iter()) {
                    let ord = cmp_sort_cells(graph, local, av, cv);
                    let ord = if *desc { ord.reverse() } else { ord };
                    if ord != Ordering::Equal {
                        return ord;
                    }
                }
                // Tiebreak: smaller input_idx wins (matches stable sort input order).
                a.1.cmp(&c.1)
            };

            // Partition: after select_nth_unstable_by(k-1), keyed[..k] holds the k
            // smallest elements by cmp_total (not yet sorted within that prefix).
            // select_nth_unstable_by requires k > 0 and k-1 < len, both guaranteed here.
            debug_assert!(k > 0 && k <= keyed.len());
            keyed.select_nth_unstable_by(k - 1, |a, c| cmp_total(a, c));

            // Sort the selected prefix into the correct final order.
            keyed[..k].sort_by(|a, c| cmp_total(a, c));

            // Gather the k surviving rows by index — the ONLY `Row::clone`s in this path.
            // `keyed[..k]` is now in final sorted order, so the gathered rows land in that
            // exact order. [SONNET-4.6] sq-7d3dj.30.23
            b.rows = keyed[..k].iter().map(|(_, i)| b.rows[*i].clone()).collect();
            b.sorted_by = None;
            return Ok(());
        }
        // k >= n: top-k budget covers all rows, fall through to full stable sort.
    }

    // Full stable sort path (unchanged). Precompute the keys (independent, read-only)
    // — in parallel for large result sets.
    #[cfg(feature = "parallel")]
    let mut keyed: Vec<(Vec<(bool, SortCell)>, Row)> = if n >= PAR_THRESHOLD {
        use rayon::prelude::*;
        // sq-6aefu: mirror FILTER/BIND worker_install pattern — same rationale as the
        // top-k path above: key_of -> eval_compiled can re-enter EXISTS / custom
        // extension functions / spatial on rayon workers. [SONNET-4.6]
        let fns = functions::snapshot();
        let vw = view::snapshot();
        let spx = spatial::snapshot();
        // [OPUS-5] (sq-lsp7k.2.2) Keep LOCAL SERVICE handlers visible on the worker too:
        // a worker that missed the registry would dial the IRI instead of answering it.
        #[cfg(feature = "service-local")]
        let lsv = local_services::snapshot();
        #[cfg(not(target_arch = "wasm32"))]
        let qn = query_now::snapshot(); // sq-98w7z.1: keep NOW() pinned on workers
        b.rows
            .par_iter()
            .map(|row| {
                let _fns = functions::worker_install(&fns);
                let _vw = view::worker_install(&vw);
                let _spx = spatial::worker_install(&spx);
                #[cfg(feature = "service-local")]
                let _lsv = local_services::worker_install(&lsv);
                #[cfg(not(target_arch = "wasm32"))]
                let _qn = query_now::worker_install(qn);
                Ok((key_of(row)?, row.clone()))
            })
            .collect::<Result<_, String>>()?
    } else {
        b.rows.iter().map(|row| Ok((key_of(row)?, row.clone()))).collect::<Result<_, String>>()?
    };
    #[cfg(not(feature = "parallel"))]
    let mut keyed: Vec<(Vec<(bool, SortCell)>, Row)> =
        b.rows.iter().map(|row| Ok((key_of(row)?, row.clone()))).collect::<Result<_, String>>()?;

    let cmp = |a: &(Vec<(bool, SortCell)>, Row), c: &(Vec<(bool, SortCell)>, Row)| {
        for ((desc, av), (_, cv)) in a.0.iter().zip(c.0.iter()) {
            let ord = cmp_sort_cells(graph, local, av, cv);
            let ord = if *desc { ord.reverse() } else { ord };
            if ord != Ordering::Equal {
                return ord;
            }
        }
        Ordering::Equal
    };
    // ORDER BY tie handling [OPUS-4.8]: `cmp` returns `Ordering::Equal` only for rows that
    // tie on *every* ORDER BY key (no secondary tie-breaker), and SPARQL leaves the relative
    // order of ORDER BY-tied solutions unspecified, so any tie order is conformant. We still
    // keep it *deterministic at a fixed thread count*: both branches use a STABLE sort
    // (`rayon::par_sort_by` is a stable parallel merge sort, same guarantee as `slice::sort_by`),
    // so ties retain their `b.rows` (scan) input order rather than being shuffled by the
    // parallel partitioning. The only residual cross-thread-count variation is that `b.rows`
    // itself is in dict-id (scan) order, which is thread-count-dependent — that is the
    // umbrella dict-id-order property (research/dict-id-order-determinism-audit.md), not a
    // tie-break defect in this sort. So no total-order tie-breaker is added: it would cost a
    // term materialisation per tied row for an order the spec does not constrain.
    #[cfg(feature = "parallel")]
    if keyed.len() >= PAR_THRESHOLD {
        use rayon::prelude::*;
        keyed.par_sort_by(cmp);
    } else {
        keyed.sort_by(cmp);
    }
    #[cfg(not(feature = "parallel"))]
    keyed.sort_by(cmp);

    b.rows = keyed.into_iter().map(|(_, r)| r).collect();
    b.sorted_by = None;
    Ok(())
}

/// [FABLE-5] sq-7d3dj.30.12 — DIFFERENTIAL property test for the precomputed sort-collation
/// keys. The `SortCell::Val` arm of `cmp_sort_cells` now hoists the SPARQL total-order class
/// / literal-kind dispatch to cell-CONSTRUCTION time (`val_ranks`) and only falls back to the
/// full `compare_values` within a tied class+kind. This suite pins the load-bearing
/// invariant: for EVERY pair of key values, the precomputed-key ordering equals the current
/// comparator's ordering EXACTLY — including the sq-lr2ii f64-collision trap (high-precision
/// decimals / integers past 2^53 that share one f64 image), NaN/INF spellings, and mixed
/// kinds. A wrong rank, or a fall-through that reordered a within-kind tie, goes red here.
#[cfg(test)]
mod sort_collation_key_differential {
    use super::*;
    use oxrdf::{vocab::xsd, BlankNode, Literal, NamedNode, NamedNodeRef};

    /// A `Value::Term(Literal)` of the given lexical + datatype IRI.
    fn typed(lex: &str, dt: NamedNodeRef<'_>) -> Value {
        Value::Term(Term::Literal(Literal::new_typed_literal(lex, dt)))
    }
    fn lang(lex: &str, tag: &str) -> Value {
        Value::Term(Term::Literal(Literal::new_language_tagged_literal(lex, tag).unwrap()))
    }
    fn iri(s: &str) -> Value {
        Value::Term(Term::NamedNode(NamedNode::new(s).unwrap()))
    }
    fn bnode(s: &str) -> Value {
        Value::Term(Term::BlankNode(BlankNode::new(s).unwrap()))
    }

    /// A curated corpus spanning EVERY total-order class and literal kind, plus the exact
    /// adversarial pairs the sq-lr2ii / sq-rikm7 / sq-wjl8i traps care about.
    fn corpus() -> Vec<Value> {
        let mut v = vec![
            Value::Unbound,
            Value::Error,
            bnode("b0"),
            bnode("b1"),
            iri("http://ex/a"),
            iri("http://ex/b"),
            // Numeric kind — computed and lexical, across the tower.
            Value::Num(Num::Double(1.0)),
            Value::Num(Num::Double(f64::NAN)),
            Value::Num(Num::Double(f64::INFINITY)),
            Value::Num(Num::Double(f64::NEG_INFINITY)),
            typed("0", xsd::INTEGER),
            typed("1", xsd::INTEGER),
            typed("-5", xsd::INTEGER),
            typed("1.5", xsd::DECIMAL),
            typed("1.50", xsd::DECIMAL),
            typed("NaN", xsd::DOUBLE),
            typed("INF", xsd::DOUBLE),
            typed("-INF", xsd::DOUBLE),
            typed("1.0E0", xsd::DOUBLE),
            // The sq-lr2ii f64-COLLISION trap: distinct exact values that share one f64.
            typed("9007199254740992", xsd::INTEGER), // 2^53
            typed("9007199254740993", xsd::INTEGER), // 2^53+1 — collapses onto 2^53 as f64
            typed("9007199254740993", xsd::DECIMAL),
            // High-precision decimals differing past f64 mantissa resolution.
            typed("0.100000000000000005", xsd::DECIMAL),
            typed("0.100000000000000006", xsd::DECIMAL),
            // Ill-formed numeric lexical → LiteralKind::Other, orders lexically.
            typed("notanumber", xsd::INTEGER),
            // Boolean kind.
            Value::Bool(false),
            Value::Bool(true),
            typed("true", xsd::BOOLEAN),
            typed("0", xsd::BOOLEAN),
            // Temporal kinds.
            typed("2020-01-01T00:00:00Z", xsd::DATE_TIME),
            typed("2020-01-02T00:00:00Z", xsd::DATE_TIME),
            typed("2020-01-01", xsd::DATE),
            typed("2020-06-15", xsd::DATE),
            typed("garbage", xsd::DATE_TIME), // ill-formed temporal → Other
            // String kind.
            typed("apple", xsd::STRING),
            typed("banana", xsd::STRING),
            typed("10", xsd::STRING), // lexical "10" < "2" (the sq-wjl8i witness domain)
            typed("2", xsd::STRING),
            // Language-tagged.
            lang("hello", "en"),
            lang("hello", "fr"),
            lang("world", "en"),
            // Other XSD + unknown datatype.
            typed("PT1H", xsd::DURATION),
            typed("PT2H", xsd::DURATION),
            Value::Term(Term::Literal(Literal::new_typed_literal(
                "x",
                NamedNode::new("http://ex/customdt").unwrap(),
            ))),
        ];
        // A few RDF-1.2 triple terms (sort after literals, component-wise).
        v.push(Value::Term(Term::Triple(Box::new(oxrdf::Triple::new(
            NamedNode::new("http://ex/s").unwrap(),
            NamedNode::new("http://ex/p").unwrap(),
            Literal::new_typed_literal("1", xsd::INTEGER),
        )))));
        v.push(Value::Term(Term::Triple(Box::new(oxrdf::Triple::new(
            NamedNode::new("http://ex/s").unwrap(),
            NamedNode::new("http://ex/p").unwrap(),
            Literal::new_typed_literal("2", xsd::INTEGER),
        )))));
        v
    }

    /// The reference ordering: the pre-existing comparator over raw `Value`s.
    fn reference(a: &Value, c: &Value) -> Ordering {
        compare_values(a, c).unwrap_or(Ordering::Equal)
    }

    /// The precomputed-key ordering: build `SortCell::Val` cells (ranks precomputed) and
    /// compare via `cmp_sort_cells`' `(Val, Val)` arm. The graph / local are never consulted
    /// by that arm, so an empty graph is sufficient.
    fn keyed(a: &Value, c: &Value, g: &Graph, l: &LocalVocab) -> Ordering {
        let ca = sort_cell_val(a.clone());
        let cc = sort_cell_val(c.clone());
        cmp_sort_cells(g, l, &ca, &cc)
    }

    #[test]
    fn precomputed_key_order_equals_comparator_on_every_pair() {
        let g = Graph::load_str("", "turtle").unwrap();
        let l = LocalVocab::default();
        let vs = corpus();
        for a in &vs {
            for c in &vs {
                let want = reference(a, c);
                let got = keyed(a, c, &g, &l);
                assert_eq!(
                    got, want,
                    "precomputed-key order diverged from comparator for ({}, {}): got {:?} want {:?}",
                    value_key(a),
                    value_key(c),
                    got,
                    want
                );
            }
        }
    }

    #[test]
    fn precomputed_key_reproduces_antisymmetry_and_reflexivity() {
        let g = Graph::load_str("", "turtle").unwrap();
        let l = LocalVocab::default();
        let vs = corpus();
        for a in &vs {
            assert_eq!(keyed(a, a, &g, &l), Ordering::Equal, "reflexivity: {}", value_key(a));
            for c in &vs {
                let ac = keyed(a, c, &g, &l);
                let ca = keyed(c, a, &g, &l);
                assert_eq!(ac, ca.reverse(), "antisymmetry ({}, {})", value_key(a), value_key(c));
            }
        }
    }

    /// A deterministic pseudo-random fuzz over randomly-generated numeric lexicals — the
    /// class the sq-lr2ii trap lives in — asserting the precomputed key never disagrees with
    /// the comparator on any generated pair (including f64-colliding and NaN/INF spellings).
    #[test]
    fn precomputed_key_matches_comparator_on_random_numeric_lexicals() {
        let g = Graph::load_str("", "turtle").unwrap();
        let l = LocalVocab::default();
        // A tiny LCG — no external rand dep, fully deterministic.
        let mut state: u64 = 0x9E3779B97F4A7C15;
        let mut next = || {
            state = state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            state >> 11
        };
        let dts = [xsd::INTEGER, xsd::DECIMAL, xsd::DOUBLE, xsd::FLOAT];
        let specials = ["NaN", "INF", "-INF", "0", "-0", "0.0"];
        let mk = |n: &mut dyn FnMut() -> u64| -> Value {
            let choice = n() % 10;
            let dt = dts[(n() % dts.len() as u64) as usize];
            if choice == 0 {
                // A special spelling (some ill-formed for INTEGER → Other kind).
                return typed(specials[(n() % specials.len() as u64) as usize], dt);
            }
            // Values near the 2^53 f64-collapse boundary + high-precision decimals.
            let base = 9007199254740990u64 + (n() % 8);
            let frac = n() % 1_000_000_000;
            let lex = if choice.is_multiple_of(2) {
                format!("{}", base)
            } else {
                format!("{}.{:018}", base, frac)
            };
            typed(&lex, dt)
        };
        for _ in 0..4000 {
            let a = mk(&mut next);
            let c = mk(&mut next);
            let want = reference(&a, &c);
            let got = keyed(&a, &c, &g, &l);
            assert_eq!(
                got, want,
                "random numeric divergence ({}, {}): got {:?} want {:?}",
                value_key(&a),
                value_key(&c),
                got,
                want
            );
        }
    }
}

/// [FABLE-5] sq-7d3dj.30.21 — DIFFERENTIAL test for the LAZY plain-string-literal sort cell
/// (`topk-lazy-strkey`). It pins the load-bearing invariant of the feature: a `SortCell::StrId`
/// (an interned plain `xsd:string` literal carried as a dict id, compared via the ZERO-COPY
/// `plain_string_value` bytes) orders BYTE-IDENTICALLY to the eager `SortCell::Val` cell the
/// feature-OFF path builds for the SAME literal — for EVERY pair, both string-vs-string (the
/// hot q11 case, incl. the `"10" < "2"` / empty-string ties) and string-vs-every-other-kind
/// (the mixed-column cross-type arms). A wrong class/kind rank, a mis-read value slice, or a
/// mis-ordered fall-through goes red here. If it agreed with itself but not with the eager
/// path, the top-k output under the feature would silently differ.
#[cfg(all(test, feature = "topk-lazy-strkey"))]
mod lazy_strkey_differential {
    use super::*;
    use oxrdf::{vocab::xsd, BlankNode, Literal, NamedNode};

    fn typed(lex: &str, dt: oxrdf::NamedNodeRef<'_>) -> Term {
        Term::Literal(Literal::new_typed_literal(lex, dt))
    }

    /// The plain-`xsd:string` literals the lazy path handles — including the adversarial
    /// lexical-order cases (`"10" < "2"`), the empty string, and duplicates (ties).
    fn strings() -> Vec<Term> {
        ["apple", "banana", "zebra", "", "10", "2", "apple", "Apple", "aardvark", "http://x/y"]
            .iter()
            .map(|s| Term::Literal(Literal::new_simple_literal(*s)))
            .collect()
    }

    /// Non-string terms spanning every OTHER class + literal kind, to exercise the cross-type
    /// arms (`StrId` vs `Iri` / `Num` / `Temp` / `Val`).
    fn others() -> Vec<Term> {
        vec![
            Term::BlankNode(BlankNode::new("b0").unwrap()),
            Term::NamedNode(NamedNode::new("http://ex/a").unwrap()),
            Term::NamedNode(NamedNode::new("http://x/y").unwrap()), // same lexical as a string
            typed("42", xsd::INTEGER),
            typed("3.14", xsd::DOUBLE),
            typed("true", xsd::BOOLEAN),
            typed("2020-01-01T00:00:00Z", xsd::DATE_TIME),
            typed("2020-06-15", xsd::DATE),
            Term::Literal(Literal::new_language_tagged_literal("apple", "en").unwrap()),
            typed("PT1H", xsd::DURATION),
            Term::Literal(Literal::new_typed_literal(
                "x",
                NamedNode::new("http://ex/customdt").unwrap(),
            )),
        ]
    }

    /// Build a graph interning every corpus term (as the object of a triple) so each has a real
    /// dictionary id; return the graph plus the `(term, id)` list.
    fn graph_with(terms: &[Term]) -> (Graph, Vec<(Term, Id)>) {
        let mut ttl = String::from("@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n");
        for (i, t) in terms.iter().enumerate() {
            // Serialise each object term inline; plain strings, langs, typed literals, IRIs,
            // blanks all have a canonical Turtle form via oxrdf's Display.
            let obj = match t {
                Term::BlankNode(_) => format!("[ <http://ex/tag> {} ]", i), // fresh blank
                other => other.to_string(),
            };
            ttl.push_str(&format!("<http://ex/s{}> <http://ex/v> {} .\n", i, obj));
        }
        let g = Graph::load_str(&ttl, "turtle").expect("corpus graph");
        // Resolve each NON-blank term to its id via id_of; blanks get their own fresh id per
        // row so we look them up positionally by re-querying is skipped — blanks are only used
        // to exercise the class-rank arm, and any blank id works for that.
        let mut ided = Vec::new();
        for t in terms {
            if let Term::BlankNode(_) = t {
                continue; // handled separately below
            }
            let id = g.id_of(t).unwrap_or_else(|| panic!("term interned: {t}"));
            ided.push((t.clone(), id));
        }
        (g, ided)
    }

    /// The eager cell the feature-OFF path builds for a term.
    fn eager(t: &Term) -> SortCell {
        sort_cell_val(Value::Term(t.clone()))
    }

    #[test]
    fn strid_orders_identically_to_eager_val_on_every_pair() {
        let all: Vec<Term> = strings().into_iter().chain(others()).collect();
        let (g, ided) = graph_with(&all);
        let l = LocalVocab::default();

        // For each interned term decide its lazy cell: a plain string → StrId(id); anything
        // else → the same eager Val cell the feature-off path uses (only the string arm is
        // lazy). Then assert lazy-vs-lazy == eager-vs-eager for EVERY ordered pair.
        let lazy_cell = |t: &Term, id: Id| -> SortCell {
            if g.dict.plain_string_value(id).is_some() {
                SortCell::StrId(id)
            } else {
                eager(t)
            }
        };

        for (ta, ida) in &ided {
            // Reflexivity of the lazy cell.
            let la = lazy_cell(ta, *ida);
            assert_eq!(
                cmp_sort_cells(&g, &l, &la, &la),
                Ordering::Equal,
                "lazy reflexivity failed for {ta}"
            );
            for (tc, idc) in &ided {
                let want = cmp_sort_cells(&g, &l, &eager(ta), &eager(tc));
                let lc = lazy_cell(tc, *idc);
                let got = cmp_sort_cells(&g, &l, &la, &lc);
                assert_eq!(
                    got, want,
                    "lazy StrId order diverged from eager Val for ({ta}, {tc}): got {got:?} want {want:?}"
                );
                // Antisymmetry across the lazy path.
                let got_rev = cmp_sort_cells(&g, &l, &lc, &la);
                assert_eq!(got, got_rev.reverse(), "lazy antisymmetry ({ta}, {tc})");
            }
        }
    }

    #[test]
    fn plain_string_value_matches_exactly_the_string_kind_set() {
        // The lazy eligibility predicate must be `Some` for EXACTLY the plain xsd:string
        // literals and `None` for everything else (lang-tagged, typed non-string, IRI, blank,
        // numeric) — otherwise a non-string would take the string-ordered lazy arm.
        let all: Vec<Term> = strings().into_iter().chain(others()).collect();
        let (g, ided) = graph_with(&all);
        for (t, id) in &ided {
            let is_plain_string = matches!(t, Term::Literal(l)
                if l.language().is_none() && l.datatype() == xsd::STRING);
            assert_eq!(
                g.dict.plain_string_value(*id).is_some(),
                is_plain_string,
                "plain_string_value eligibility mismatch for {t}"
            );
            if is_plain_string {
                if let Term::Literal(l) = t {
                    assert_eq!(g.dict.plain_string_value(*id), Some(l.value()), "value slice for {t}");
                }
            }
        }
    }
}

// ---- FILTER + expression evaluation ------------------------------------------

/// FILTER application. When the opt-in `vectorized` feature is on and the residual filter is
/// eligible (see `columnar_filter`), a columnar vector-at-a-time path runs and the row loop is
/// skipped; otherwise the scalar row path (`apply_filter_scalar`) runs verbatim. When the
/// feature is OFF this compiles to exactly the scalar body — byte-identical, zero overhead.
fn apply_filter(graph: &Graph, local: &LocalVocab, b: &mut Bindings, expr: &Expression) -> Result<(), String> {
    // [SONNET-4.6] (sq-pntvh.5, M4 Phase 5 / sq-y5ew5, M4 hybrid tri-mask) Dispatcher-gated
    // columnar residual-FILTER seam (Seam A): the `columnar_filter` helper runs through the
    // shared `vec_dispatch` eligibility gate (VEC_MIN_BATCH threshold, I2/I3 checks) and
    // executes morsel-by-morsel (VEC_MORSEL rows per decode buffer), now with tri-mask
    // delegation for tie/unknown lanes. Declines (→ scalar path) for anything not provably
    // byte-identical to `apply_filter_scalar`. I5 probe counters updated on each call.
    #[cfg(feature = "vectorized")]
    if let Some(rows) = columnar_filter(graph, local, b, expr)? {
        b.rows = rows;
        return Ok(());
    }
    apply_filter_scalar(graph, local, b, expr)
}

/// [FABLE-5] (sq-7d3dj.30.11) The set of `b` column indices proven NON-LITERAL by the static
/// term-kind analysis over the FILTER's inner pattern (the id-level fast-path enabler). Empty
/// when the feature is off. Called once at the FILTER dispatch, before the row loop.
///
/// [FABLE-5] (sq-1ivw7) The analysis is SNAPSHOT-AWARE: it also credits an OBJECT-position variable
/// of a constant-predicate BGP triple as non-literal when that predicate's object column is proven
/// literal-free in the CURRENT store snapshot (`graph.predicate_has_literal_object` is false). This
/// is what unblocks q08/q12b-shaped FILTERs (`?author`/`?erdoes` appear only as `dc:creator`
/// objects, an IRI-only column). The classifier reads the LIVE `graph` handed to THIS eval, so an
/// UPDATE that inserted a literal object publishes a new snapshot the next eval re-checks — the
/// verdict never outlives its snapshot. A per-predicate memo caches the (early-exit) scan so a
/// predicate probed by several object slots of the same FILTER is scanned at most once.
#[cfg(feature = "id-filter-fastpath")]
fn nonliteral_filter_cols(graph: &Graph, inner: &GraphPattern, b: &Bindings) -> FxHashSet<usize> {
    let memo = std::cell::RefCell::new(FxHashMap::<oxrdf::NamedNode, bool>::default());
    let obj_may_be_literal = |pred: &oxrdf::NamedNode| -> bool {
        if let Some(&v) = memo.borrow().get(pred) {
            return v;
        }
        // Conservative default when the predicate IRI is absent from the dictionary: it matches no
        // triple, so the object variable is unbound — treating it as literal-risk simply declines
        // the fast path (safe, and correct: an unbound operand is a type error, not id equality).
        let has_lit = match graph.id_of(&oxrdf::Term::NamedNode(pred.clone())) {
            Some(pid) => graph.predicate_has_literal_object(pid),
            None => true,
        };
        memo.borrow_mut().insert(pred.clone(), has_lit);
        has_lit
    };
    let vars = nonliteral_vars(inner, &obj_may_be_literal);
    vars.iter().filter_map(|v| b.col(v)).collect()
}

/// The columnar residual-FILTER attempt (M4 Phase 5 / sq-y5ew5 hybrid tri-mask, Seam A).
///
/// Returns `Ok(Some(new_rows))` (the surviving rows, in the scalar path's order) when the
/// dispatcher admits the operator invocation, `Ok(None)` to fall through to
/// `apply_filter_scalar`, or `Err(e)` if scalar delegation on a tie/unknown lane fails.
/// The returned rows are **byte-identical** to `apply_filter_scalar`'s output.
///
/// ## Decline hierarchy (I1–I5, owned by `vec_dispatch`)
///
/// Checks are applied in this order; any failing check falls through to the scalar path
/// with a `vec_dispatch::record_decline()` increment (I1: decline is total, silent-safe):
///
/// 1. **I2 (zk-decline):** when the `zk` proof-trace is armed the seam declines so the
///    scalar path records the complete per-row FILTER obligation set.
/// 2. **I3 (budget parity — fallback rule):** when a query budget is installed, the seam
///    declines. The scalar `apply_filter` debit schedule is NOT uniform-per-row (budget is
///    checked at operator entry, not inside the row loop), so the `k = min(batch, remaining)`
///    prefix rule cannot be applied without a scalar-side budget-tracking refactor. The
///    fallback is: budget-armed ⇒ decline. This is zero-risk; revisit when budget tracking
///    is uniform-per-row.
/// 3. **Operator shape:** only a single sargable `NUMERIC` comparison `?v OP const` (temporal
///    comparisons have no vector kernel yet). A NaN threshold (e.g. from an XSD double `NaN`
///    literal constant) is also declined: a NaN threshold makes all lanes Unknown, producing
///    a delegated fraction of 100% with no columnar benefit.
/// 4. **`VEC_MIN_BATCH`:** the batch must have at least `vec_dispatch::VEC_MIN_BATCH`
///    rows. Smaller batches are cheaper on the scalar path.
///
/// ## Execution (hybrid tri-mask, morsel-by-morsel, single-column extract)
///
/// For eligible invocations the function iterates morsels of `VEC_MORSEL` rows. Each morsel:
/// - Extracts only the filter column (O(morsel × 1), not a full-width transpose).
/// - Decodes to a contiguous `f64` column via `decode_numeric_column`.
/// - Runs `chunk_select::tri_mask_select` to split lanes into Confident and Delegated.
/// - Delegated (Tie + Unknown) lanes are evaluated by the full scalar `eval_expr` per row.
/// - Confident-passes and delegated-passes are merged (ascending) for this morsel.
/// - Records the morsel via `vec_dispatch::record_chunk` and delegated count via
///   `vec_dispatch::record_delegated`.
///
/// After all morsels, survivors are gathered from the original `b.rows` (order-preserving).
///
/// ## Byte-identity argument (§3 of the completion-design record, by construction)
///
/// - Confident lanes: the scalar predicate on the same row sees the same two f64 values;
///   no exact-lexical recheck applies (non-tie), so `cmp.test(x)` gives the correct answer.
/// - Tie / Unknown lanes: the hybrid's verdict IS the scalar predicate's verdict.
/// - Order: both index lists are ascending; the merge is ascending; `apply_selection` is
///   order-preserving.
///
/// **ZK coupling (soundness-relevant):** see I2 above and `research/vector-at-a-time-m4.md`
/// §3.2. [SONNET-4.6] (sq-y5ew5)
#[cfg(feature = "vectorized")]
fn columnar_filter(
    graph: &Graph,
    local: &LocalVocab,
    b: &Bindings,
    expr: &Expression,
) -> Result<Option<Vec<Row>>, String> {
    use crate::chunk::{DataChunk, VecCmp};
    use crate::chunk_select;
    use crate::vec_dispatch;

    // I2: ZK trace armed ⇒ decline so the scalar path records the FILTER obligation set.
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        vec_dispatch::record_decline();
        return Ok(None);
    }

    // I3: budget armed ⇒ decline (fallback rule — debit schedule is not uniform-per-row).
    if budget::active() {
        vec_dispatch::record_decline();
        return Ok(None);
    }

    // Operator-shape check: only a single sargable NUMERIC comparison is eligible.
    // NOTE: do NOT use `extract_sargable(graph, expr)?` — the `?` operator returns None without
    // recording the decline, making the I5 counter miss non-sargable expressions. [SONNET-4.6]
    let (var, cmp) = match extract_sargable(graph, expr) {
        None => {
            vec_dispatch::record_decline();
            return Ok(None);
        }
        Some((v, ScanCmp::Num(c))) => (v, c),
        Some((_, ScanCmp::Temp(..))) => {
            vec_dispatch::record_decline();
            return Ok(None);
        }
    };

    // Decline a NaN threshold: all lanes would be Unknown → 100% delegation, no benefit.
    // Also ensures the tri-mask tie check (x == c) is well-defined (NaN == anything is false).
    let veccmp = match cmp {
        NumCmp::Gt(t) if t.is_nan() => { vec_dispatch::record_decline(); return Ok(None); }
        NumCmp::Ge(t) if t.is_nan() => { vec_dispatch::record_decline(); return Ok(None); }
        NumCmp::Lt(t) if t.is_nan() => { vec_dispatch::record_decline(); return Ok(None); }
        NumCmp::Le(t) if t.is_nan() => { vec_dispatch::record_decline(); return Ok(None); }
        NumCmp::Eq(t) if t.is_nan() => { vec_dispatch::record_decline(); return Ok(None); }
        NumCmp::Gt(t) => VecCmp::Gt(t),
        NumCmp::Ge(t) => VecCmp::Ge(t),
        NumCmp::Lt(t) => VecCmp::Lt(t),
        NumCmp::Le(t) => VecCmp::Le(t),
        NumCmp::Eq(t) => VecCmp::Eq(t),
    };

    let col_idx = match b.col(&var) {
        Some(col) => col,
        None => {
            vec_dispatch::record_decline();
            return Ok(None);
        }
    };

    // VEC_MIN_BATCH: batches below the threshold are cheaper on the scalar path.
    if b.rows.len() < vec_dispatch::VEC_MIN_BATCH {
        vec_dispatch::record_decline();
        return Ok(None);
    }

    // Morsel-by-morsel execution: extract only the filter column (not a full-width
    // transpose), decode it, run the tri-mask, delegate tie/unknown lanes to scalar,
    // and merge the passing indices.
    let morsel_size = vec_dispatch::VEC_MORSEL;
    let mut survivor_indices: Vec<usize> = Vec::new();
    let rows = &b.rows;

    for start in (0..rows.len()).step_by(morsel_size) {
        let end = (start + morsel_size).min(rows.len());
        let morsel_len = end - start;

        // Extract just the filter column for this morsel (O(morsel × 1), not O(morsel × width)).
        let col: Vec<sparq_core::dict::Id> = rows[start..end].iter().map(|r| r[col_idx]).collect();
        let morsel_chunk = match DataChunk::from_columns(vec![col], morsel_len) {
            Some(mc) => mc,
            None => {
                // Should not happen: col.len() == morsel_len by construction.
                vec_dispatch::record_decline();
                return Ok(None);
            }
        };

        // Decode the column once (gather-free fast path for all-inline columns, general
        // path for mixed columns — NaN sentinel for non-numeric / local-vocab / unbound ids).
        let decoded = morsel_chunk.decode_numeric_column(graph, 0);

        // Tri-mask pass: classify each lane as Confident (unambiguous f64 verdict) or
        // Delegated (tie or unknown). Returns confident-passes and delegated indices
        // in ascending order.
        let tri = chunk_select::tri_mask_select(&decoded, veccmp);

        // Record I5 counters for this morsel.
        vec_dispatch::record_chunk(morsel_len);
        vec_dispatch::record_delegated(tri.delegated.len());

        // Evaluate the full scalar predicate for each delegated (tie / unknown) lane.
        // The scalar predicate handles the exact-lexical recheck for ties and the
        // type-error path for unknowns — byte-identical to `apply_filter_scalar`.
        let mut delegated_passes: Vec<usize> = Vec::with_capacity(tri.delegated.len());
        for &local_idx in &tri.delegated {
            let global_idx = start + local_idx;
            let row = &rows[global_idx];
            let val = eval_expr(graph, local, b, row.as_ref(), expr)?;
            if effective_boolean(&val) {
                delegated_passes.push(local_idx);
            }
        }

        // Merge confident-passes and delegated-passes (both ascending) for this morsel,
        // then translate to global row indices.
        let morsel_sel = chunk_select::merge_ascending(&tri.confident_passes, &delegated_passes);
        survivor_indices.extend(morsel_sel.iter().map(|&i| start + i));
    }

    // Materialise survivors from the original rows (order-preserving, full-width).
    let result: Vec<Row> = survivor_indices.iter().map(|&r| Row::from_slice(rows[r].as_ref())).collect();
    Ok(Some(result))
}

/// The columnar per-group aggregate attempt (M4 Phase 4, `sq-pntvh.4`). Returns `Some(rows)`
/// (the output rows, byte-identical to the scalar path in first-seen group order) when ALL
/// aggregates are columnar-eligible, or `None` to fall back to the scalar group fold.
///
/// **Eligibility (conservative — decline is always safe, I1):**
/// - `vectorized` feature ON (compile-gate only, not checked here)
/// - ZK trace NOT armed (I2, checked below)
/// - Budget NOT armed (I3, checked below — fallback rule, same as `columnar_filter`)
/// - `VEC_MIN_BATCH` rows or more in the input (dispatcher threshold)
/// - No DISTINCT aggregate
/// - Only `SUM / COUNT / AVG / MIN / MAX` aggregate functions and `COUNT(*)`
/// - Aggregate argument is a bare variable `?v` (not an expression)
/// - The variable `?v` is a present column in `b`
/// - Every row in `b` has an inline-integer id in that column (all-inline gate)
///   This ensures byte-identity: see `research/vector-at-a-time-m4-completion-design.md` §2.
///
/// When there are multiple aggregates, ALL must be eligible and use the SAME column (or
/// `COUNT(*)` which needs no column). If any aggregate uses a different column, decline.
/// [SONNET-4.6] (sq-pntvh.4 / sq-pntvh.5 dispatcher hook)
#[cfg(feature = "vectorized")]
#[allow(clippy::too_many_arguments)]
fn columnar_aggregate(
    graph: &Graph,
    local: &mut LocalVocab,
    b: &Bindings,
    _group_vars: &[Variable],
    aggregates: &[(Variable, AggregateExpression)],
    order: &[Key],
    members: &[Vec<usize>],
    _out_vars: &[Variable],
) -> Option<Vec<Row>> {
    use crate::reduce::{reduce_count, reduce_max_id, reduce_min_id, reduce_sum};
    use crate::vec_dispatch;

    // I2: ZK trace armed → decline so the scalar path records the aggregate obligations.
    #[cfg(feature = "zk")]
    if crate::zk::enabled() {
        vec_dispatch::record_decline();
        return None;
    }

    // I3: budget armed ⇒ decline (same fallback rule as columnar_filter). [SONNET-4.6]
    if budget::active() {
        vec_dispatch::record_decline();
        return None;
    }

    // VEC_MIN_BATCH dispatcher threshold: small inputs are cheaper on the scalar path.
    if b.rows.len() < vec_dispatch::VEC_MIN_BATCH {
        vec_dispatch::record_decline();
        return None;
    }

    // ── Eligibility pass ──────────────────────────────────────────────────────────────────
    // Walk all aggregates to determine whether they are columnar-eligible and which
    // column (if any) the non-COUNT(*) aggregates operate on.
    let mut agg_col: Option<usize> = None; // the single eligible column index

    for (_, agg) in aggregates {
        match agg {
            AggregateExpression::CountSolutions { distinct } => {
                if *distinct {
                    vec_dispatch::record_decline();
                    return None; // DISTINCT COUNT(*) requires full row dedup
                }
                // CountSolutions needs no column — always eligible.
            }
            AggregateExpression::FunctionCall { name, expr, distinct } => {
                if *distinct {
                    vec_dispatch::record_decline();
                    return None; // DISTINCT requires per-group value dedup
                }
                // Only the five standard numeric aggregates are supported.
                match name {
                    AggregateFunction::Sum
                    | AggregateFunction::Count
                    | AggregateFunction::Avg
                    | AggregateFunction::Min
                    | AggregateFunction::Max => {}
                    _ => {
                        vec_dispatch::record_decline();
                        return None;
                    }
                }
                // Argument must be a bare variable (not an expression).
                let v = match expr {
                    Expression::Variable(v) => v,
                    _ => {
                        vec_dispatch::record_decline();
                        return None;
                    }
                };
                // The variable must have a column in the input bindings.
                let c = match b.col(v) {
                    Some(ci) => ci,
                    None => {
                        vec_dispatch::record_decline();
                        return None;
                    }
                };
                // All column-dependent aggregates must reference the SAME column.
                match agg_col {
                    None => agg_col = Some(c),
                    Some(existing) if existing == c => {}
                    _ => {
                        vec_dispatch::record_decline();
                        return None;
                    }
                }
            }
        }
    }

    // ── All-inline gate ───────────────────────────────────────────────────────────────────
    // For every row in `b`, the aggregate column must hold an inline-integer id.
    // This is the byte-identity invariant: inline-int ids encode their value directly,
    // so the reducer sees the exact same integer the scalar eval_expr would materialise.
    if let Some(c) = agg_col {
        if !b.rows.iter().all(|r| dict::is_inline(r[c])) {
            vec_dispatch::record_decline();
            return None;
        }
    }

    // ── Per-group reduction ───────────────────────────────────────────────────────────────
    let mut rows: Vec<Row> = Vec::with_capacity(order.len());

    for (key, member_indices) in order.iter().zip(members.iter()) {
        // Gather the per-group inline ids for the aggregate column (if any).
        let group_ids: Vec<Id> = if let Some(c) = agg_col {
            member_indices.iter().map(|&ri| b.rows[ri][c]).collect()
        } else {
            Vec::new()
        };

        let mut row = Row::from_slice(key);

        for (_, agg) in aggregates {
            let id: Id = match agg {
                AggregateExpression::CountSolutions { .. } => {
                    // Non-distinct COUNT(*) = number of solutions in this group.
                    // Mirrors scalar: Value::Num(Num::Int(members.len() as i64)).
                    let n = member_indices.len() as i64;
                    value_to_id(graph, local, &Value::Num(Num::Int(n)))
                }
                AggregateExpression::FunctionCall { name, .. } => {
                    match name {
                        AggregateFunction::Count => {
                            // COUNT(?v) over an all-inline group = group size (no NULLs).
                            let n = reduce_count(&group_ids) as i64;
                            value_to_id(graph, local, &Value::Num(Num::Int(n)))
                        }
                        AggregateFunction::Sum => {
                            // SUM({}) = 0 per SPARQL; for non-empty, reduce_sum is exact i128.
                            let sum_i128 = reduce_sum(&group_ids)?;
                            // Guard the i128→i64 narrowing: group cardinality is unbounded so
                            // the sum CAN exceed i64::MAX. Decline to scalar on overflow; the
                            // scalar path promotes via Num::Double, matching scalar semantics.
                            // [SONNET-4.6] (C1-fix sq-pntvh.4 adversarial review)
                            let sum_i64 = crate::reduce::narrow_sum_to_i64(sum_i128)?;
                            // Mirrors scalar: sum_values → num_canonical_term → value_to_id.
                            value_to_id(graph, local, &Value::Num(Num::Int(sum_i64)))
                        }
                        AggregateFunction::Avg => {
                            if group_ids.is_empty() {
                                // AVG({}) = 0 per SPARQL (mirrors scalar path line ~6378).
                                value_to_id(graph, local, &Value::Num(Num::Int(0)))
                            } else {
                                let sum_i128 = reduce_sum(&group_ids)?;
                                let count_i64 = group_ids.len() as i64;
                                // Guard the i128→i64 narrowing (same as SUM).
                                // [SONNET-4.6] (C1-fix sq-pntvh.4 adversarial review)
                                let sum_i64 = crate::reduce::narrow_sum_to_i64(sum_i128)?;
                                // integer / integer → Decimal (SPARQL §17.4.4.3).
                                // Mirrors: sum_values → binop(Div) → value_to_id.
                                let result = Num::Int(sum_i64).binop(Num::Int(count_i64), ArithOp::Div)?;
                                value_to_id(graph, local, &Value::Num(result))
                            }
                        }
                        AggregateFunction::Min => {
                            if group_ids.is_empty() {
                                NO_ID // unbound — mirrors scalar minmax_values([]) = Value::Unbound
                            } else {
                                // reduce_min_id returns None only if a non-inline id slipped
                                // through the all-inline gate (should not happen; decline safely).
                                reduce_min_id(&group_ids)?
                            }
                        }
                        AggregateFunction::Max => {
                            if group_ids.is_empty() {
                                NO_ID // unbound
                            } else {
                                reduce_max_id(&group_ids)?
                            }
                        }
                        _ => return None, // unreachable given the eligibility check above
                    }
                }
            };
            row.push(id);
        }

        rows.push(row);
    }

    // I5: record one "chunk" for the aggregate seam (the whole group-table counts as one pass).
    // [SONNET-4.6] (sq-pntvh.5 dispatcher hook)
    vec_dispatch::record_chunk(b.rows.len());
    Some(rows)
}

// [FABLE-5] (sq-7d3dj.30.11) The columns the FILTER dispatch proved non-literal, handed to
// `apply_filter_scalar` for the id-level fast-path rewrite. Set (and cleared) around the single
// `apply_filter` call on the DISPATCHING thread, read once before the row loop — rayon workers
// evaluate the already-rewritten expression, so they never read this. A missing/empty value
// means "no static non-literal columns known" (every other FILTER caller), so the rewrite is a
// no-op there and the exact path is unchanged.
#[cfg(feature = "id-filter-fastpath")]
thread_local! {
    static IDFAST_NONLIT_COLS: std::cell::RefCell<FxHashSet<usize>> =
        std::cell::RefCell::new(FxHashSet::default());
}

/// Runs `f` with the id-fast non-literal column set installed, restoring the previous set after
/// (also on unwind). Only wraps the FILTER dispatch that computed a set from its inner pattern.
#[cfg(feature = "id-filter-fastpath")]
fn with_idfast_nonlit_cols<R>(cols: FxHashSet<usize>, f: impl FnOnce() -> R) -> R {
    let prev = IDFAST_NONLIT_COLS.with(|c| c.replace(cols));
    struct Restore(FxHashSet<usize>);
    impl Drop for Restore {
        fn drop(&mut self) {
            IDFAST_NONLIT_COLS.with(|c| *c.borrow_mut() = std::mem::take(&mut self.0));
        }
    }
    let _restore = Restore(prev);
    f()
}

fn apply_filter_scalar(graph: &Graph, local: &LocalVocab, b: &mut Bindings, expr: &Expression) -> Result<(), String> {
    // Pre-resolve Variable → column index once before the row loop. [OPUS-4.8] sq-7d3dj.4.
    #[cfg_attr(not(feature = "id-filter-fastpath"), allow(unused_mut))]
    let mut compiled = compile_expr(expr, b);
    // [FABLE-5] (sq-7d3dj.30.11) Rewrite eligible `=` nodes into the id-level fast path using the
    // non-literal columns the FILTER dispatch computed for THIS operator (empty for every other
    // caller → no-op). Done ONCE, before the row loop; rayon workers see the rewritten program.
    // TAKE (drain) the installed set: it is valid ONLY for THIS `Bindings` layout, and this
    // consuming call is the one the wrapping FILTER dispatch installed it for. Draining to empty
    // means a nested FILTER re-entered during row evaluation (an `EXISTS` inner, whose columns
    // index a DIFFERENT `Bindings`) — or any later unwrapped `apply_filter` on this thread — sees
    // the empty default and rewrites nothing, so it can never apply the outer pattern's column
    // indices to a mismatched layout. [FABLE-5] (sq-7d3dj.30.11, PR #1785 review).
    #[cfg(feature = "id-filter-fastpath")]
    {
        let cols = IDFAST_NONLIT_COLS.with(|cols| std::mem::take(&mut *cols.borrow_mut()));
        if !cols.is_empty() {
            idfast_rewrite(&mut compiled, &cols);
        }
    }
    // Per-row FILTER evaluation is independent and read-only over the graph/bindings, so a
    // large residual (non-pushed-down) filter is evaluated in parallel on native.
    // Row identity for BNODE(str)'s per-solution scoping (see ROW_SCOPE).
    let scope = b.rows.as_ptr() as usize;
    #[cfg(feature = "parallel")]
    let keep: Vec<bool> = if b.rows.len() >= PAR_THRESHOLD {
        use rayon::prelude::*;
        // The extension-function registry and the dataset view are thread-local:
        // snapshot them here and re-install per worker item (free when neither is
        // installed). The view matters because a FILTER can re-enter pattern
        // evaluation via EXISTS — without the re-install it would silently
        // evaluate UNRESTRICTED on a rayon worker.
        let fns = functions::snapshot();
        let vw = view::snapshot();
        let spx = spatial::snapshot(); // sq-mg9: keep the spatial index visible under EXISTS re-entry.
        // [OPUS-5] (sq-lsp7k.2.2) Keep LOCAL SERVICE handlers visible on the worker too:
        // a worker that missed the registry would dial the IRI instead of answering it.
        #[cfg(feature = "service-local")]
        let lsv = local_services::snapshot();
        #[cfg(not(target_arch = "wasm32"))]
        let qn = query_now::snapshot(); // sq-98w7z.1: keep NOW() pinned on workers
        b.rows
            .par_iter()
            .enumerate()
            .map(|(i, row)| {
                let _fns = functions::worker_install(&fns);
                let _vw = view::worker_install(&vw);
                let _spx = spatial::worker_install(&spx);
                #[cfg(feature = "service-local")]
                let _lsv = local_services::worker_install(&lsv);
                #[cfg(not(target_arch = "wasm32"))]
                let _qn = query_now::worker_install(qn);
                ROW_SCOPE.set((scope, i));
                Ok(effective_boolean(&eval_compiled(graph, local, b, row, &compiled)?))
            })
            .collect::<Result<Vec<bool>, String>>()?
    } else {
        let mut keep = Vec::with_capacity(b.rows.len());
        for (i, row) in b.rows.iter().enumerate() {
            ROW_SCOPE.set((scope, i));
            keep.push(effective_boolean(&eval_compiled(graph, local, b, row, &compiled)?));
        }
        keep
    };
    #[cfg(not(feature = "parallel"))]
    let keep: Vec<bool> = {
        let mut keep = Vec::with_capacity(b.rows.len());
        for (i, row) in b.rows.iter().enumerate() {
            ROW_SCOPE.set((scope, i));
            keep.push(effective_boolean(&eval_compiled(graph, local, b, row, &compiled)?));
        }
        keep
    };
    // zk-trace hook: record the FILTER obligation — expression, in-scope
    // variables, and per-row operand bindings with the verdict (the witness
    // builder needs the operands of every hidden-filter application). The
    // per-row path records OPERAND-TABLE INDICES (one memo probe per cell);
    // terms are materialized once per distinct operand id. Suppressed inside
    // EXISTS (per-row re-evaluation would flood the obligation list; EXISTS
    // is outside the stage-1 fragment).
    #[cfg(feature = "zk")]
    if crate::zk::enabled() && !crate::zk::in_exists() {
        let mut memo = crate::zk::OperandMemo::new();
        let rows: Vec<(Vec<u32>, bool)> = b
            .rows
            .iter()
            .zip(keep.iter())
            .map(|(row, &k)| {
                let cells = (0..b.vars.len())
                    .map(|c| memo.index(row[c], |id| term_of(graph, local, id)))
                    .collect();
                (cells, k)
            })
            .collect();
        crate::zk::record_filter(format!("{expr:?}"), &b.vars, memo.operands, rows);
    }
    let mut i = 0;
    b.rows.retain(|_| {
        let k = keep[i];
        i += 1;
        k
    });
    Ok(())
}

#[derive(Clone, Debug)]
enum Value {
    Bool(bool),
    Num(Num),
    Term(Term),
    Unbound,
    /// A SPARQL type error (e.g. an ordering comparison between incompatible
    /// types). Its effective boolean value is false, it propagates through the
    /// logical operators by the SPARQL 3-valued rules, and a BIND of it is unbound.
    Error,
}

// ── Expression compilation (sq-7d3dj.4) ──────────────────────────────────────────────────
//
// Walk each `Expression` tree ONCE per operator (before the row loop), resolving every
// `Variable`/`Bound` node to its column index in the operator's `Bindings`.  The per-row
// eval then uses `row[c]` directly, eliminating the per-row `b.col(v)` linear scan.
// This is also the substrate the flat compiled-expression program (sq-7d3dj.11) builds on.
// [OPUS-4.8] sq-7d3dj.4

/// Expression with all `Variable` / `Bound` nodes pre-resolved to column indices in the
/// operator's `Bindings`. Built once before the row loop by [`compile_expr`]; evaluated
/// per-row by [`eval_compiled`] without any per-row `Bindings` column-map scan.
#[derive(Clone, Debug)]
enum CompiledExpr {
    /// Pre-resolved column: `Some(c)` → `row[c]`; `None` → variable not in scope (always unbound).
    Var(Option<usize>),
    /// `BOUND(?v)`: `Some(c)` → `row[c] != NO_ID`; `None` → always `false`.
    BoundCol(Option<usize>),
    NamedNode(oxrdf::NamedNode),
    Literal(Literal),
    And(Box<Self>, Box<Self>),
    Or(Box<Self>, Box<Self>),
    Not(Box<Self>),
    Equal(Box<Self>, Box<Self>),
    /// [FABLE-5] (sq-7d3dj.30.11) `=` where BOTH operands are statically proven non-literal (a
    /// column bound only in subject/predicate positions, or a constant IRI). Evaluated by RAW-ID
    /// (in)equality — skips the per-row term materialisation the general `Equal` arm performs.
    /// Result-identical to `Equal` for these operands (canonicalising dict: IRI/bnode `=` is id
    /// equality; unbound operand is a type error). Only produced under `id-filter-fastpath`.
    #[cfg(feature = "id-filter-fastpath")]
    IdEqNonLit(IdOperand, IdOperand),
    SameTerm(Box<Self>, Box<Self>),
    Greater(Box<Self>, Box<Self>),
    GreaterOrEqual(Box<Self>, Box<Self>),
    Less(Box<Self>, Box<Self>),
    LessOrEqual(Box<Self>, Box<Self>),
    Add(Box<Self>, Box<Self>),
    Subtract(Box<Self>, Box<Self>),
    Multiply(Box<Self>, Box<Self>),
    Divide(Box<Self>, Box<Self>),
    UnaryPlus(Box<Self>),
    UnaryMinus(Box<Self>),
    If(Box<Self>, Box<Self>, Box<Self>),
    Coalesce(Vec<Self>),
    In(Box<Self>, Vec<Self>),
    FunctionCall(spargebra::algebra::Function, Vec<Self>),
    /// `EXISTS` is kept uncompiled: it re-evaluates the inner graph pattern per row.
    Exists(Box<GraphPattern>),
}

/// [FABLE-5] (sq-7d3dj.30.11) A `=`/`!=` operand resolved to a single RAW ID at eval time:
/// a bound column, or a constant IRI (resolved once against the graph dictionary). Both forms
/// are statically non-literal (columns proven so by `nonliteral_vars`; a NamedNode is an IRI).
#[cfg(feature = "id-filter-fastpath")]
#[derive(Clone, Debug)]
enum IdOperand {
    /// `row[c]` — a column proven non-literal by the static analysis.
    Col(usize),
    /// A constant IRI. Its raw id (or `NO_ID` if the IRI is absent from the dictionary, in which
    /// case it can never equal any bound id) is resolved once at rewrite time.
    ConstIri(oxrdf::NamedNode),
}

/// Rewrites eligible `Equal(a, c)` nodes of a compiled FILTER expression into the id-level
/// [`CompiledExpr::IdEqNonLit`] fast path, in place. A node is eligible iff BOTH operands are
/// statically non-literal — a `Var(Some(c))` whose column `c` is in `nonlit_cols`, or a constant
/// `NamedNode` (always an IRI). `!=` is `Not(Equal(..))`, so rewriting the inner `Equal` covers it.
/// Everything else (numeric / temporal / possibly-literal operands, unresolved columns) is left
/// untouched and takes the existing exact path. [FABLE-5] (sq-7d3dj.30.11).
#[cfg(feature = "id-filter-fastpath")]
fn idfast_rewrite(e: &mut CompiledExpr, nonlit_cols: &FxHashSet<usize>) {
    use CompiledExpr as C;
    // A non-literal operand descriptor, or `None` if the operand could be a literal / is not a
    // single-id term (arithmetic, function call, …).
    fn nonlit_operand(e: &CompiledExpr, nonlit_cols: &FxHashSet<usize>) -> Option<IdOperand> {
        match e {
            C::Var(Some(c)) if nonlit_cols.contains(c) => Some(IdOperand::Col(*c)),
            C::NamedNode(n) => Some(IdOperand::ConstIri(n.clone())),
            _ => None,
        }
    }
    match e {
        C::Equal(a, c) => {
            // Recurse first so nested Equals inside operands are handled uniformly (operands of an
            // Equal are never themselves the (in)equality we fast-path, but keep the walk total).
            idfast_rewrite(a, nonlit_cols);
            idfast_rewrite(c, nonlit_cols);
            if let (Some(l), Some(r)) =
                (nonlit_operand(a, nonlit_cols), nonlit_operand(c, nonlit_cols))
            {
                *e = C::IdEqNonLit(l, r);
            }
        }
        C::And(a, c)
        | C::Or(a, c)
        | C::Greater(a, c)
        | C::GreaterOrEqual(a, c)
        | C::Less(a, c)
        | C::LessOrEqual(a, c)
        | C::Add(a, c)
        | C::Subtract(a, c)
        | C::Multiply(a, c)
        | C::Divide(a, c)
        | C::SameTerm(a, c) => {
            idfast_rewrite(a, nonlit_cols);
            idfast_rewrite(c, nonlit_cols);
        }
        C::Not(a) | C::UnaryPlus(a) | C::UnaryMinus(a) => idfast_rewrite(a, nonlit_cols),
        C::If(a, b, c) => {
            idfast_rewrite(a, nonlit_cols);
            idfast_rewrite(b, nonlit_cols);
            idfast_rewrite(c, nonlit_cols);
        }
        C::Coalesce(es) | C::In(_, es) | C::FunctionCall(_, es) => {
            // `In(a, list)` keeps `a` unchanged (its top-level shape is not an Equal), but its list
            // items are ordinary expressions; only the list items recurse here (a is not rewritten
            // because `IN` is not an `=`; leaving it exact is correct and simplest).
            for x in es {
                idfast_rewrite(x, nonlit_cols);
            }
        }
        C::IdEqNonLit(..)
        | C::Var(_)
        | C::BoundCol(_)
        | C::NamedNode(_)
        | C::Literal(_)
        | C::Exists(_) => {}
    }
}

/// Walk `e` once, resolving all `Variable`/`Bound` nodes to column indices. [OPUS-4.8] sq-7d3dj.4.
fn compile_expr(e: &Expression, b: &Bindings) -> CompiledExpr {
    use Expression::*;
    match e {
        Variable(v) => CompiledExpr::Var(b.col(v)),
        Bound(v) => CompiledExpr::BoundCol(b.col(v)),
        NamedNode(n) => CompiledExpr::NamedNode(n.clone()),
        Literal(l) => CompiledExpr::Literal(l.clone()),
        And(a, d) => CompiledExpr::And(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b))),
        Or(a, d) => CompiledExpr::Or(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b))),
        Not(a) => CompiledExpr::Not(Box::new(compile_expr(a, b))),
        Equal(a, d) => CompiledExpr::Equal(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b))),
        SameTerm(a, d) => CompiledExpr::SameTerm(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b))),
        Greater(a, d) => CompiledExpr::Greater(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b))),
        GreaterOrEqual(a, d) => {
            CompiledExpr::GreaterOrEqual(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b)))
        }
        Less(a, d) => CompiledExpr::Less(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b))),
        LessOrEqual(a, d) => {
            CompiledExpr::LessOrEqual(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b)))
        }
        Add(a, d) => CompiledExpr::Add(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b))),
        Subtract(a, d) => CompiledExpr::Subtract(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b))),
        Multiply(a, d) => CompiledExpr::Multiply(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b))),
        Divide(a, d) => CompiledExpr::Divide(Box::new(compile_expr(a, b)), Box::new(compile_expr(d, b))),
        UnaryPlus(a) => CompiledExpr::UnaryPlus(Box::new(compile_expr(a, b))),
        UnaryMinus(a) => CompiledExpr::UnaryMinus(Box::new(compile_expr(a, b))),
        If(cond, t, f) => CompiledExpr::If(
            Box::new(compile_expr(cond, b)),
            Box::new(compile_expr(t, b)),
            Box::new(compile_expr(f, b)),
        ),
        Coalesce(es) => CompiledExpr::Coalesce(es.iter().map(|ce| compile_expr(ce, b)).collect()),
        In(a, list) => {
            CompiledExpr::In(Box::new(compile_expr(a, b)), list.iter().map(|ce| compile_expr(ce, b)).collect())
        }
        FunctionCall(f, args) => {
            CompiledExpr::FunctionCall(f.clone(), args.iter().map(|ce| compile_expr(ce, b)).collect())
        }
        Exists(inner) => CompiledExpr::Exists(inner.clone()),
    }
}

/// Whether a compiled expression contains an arithmetic sub-expression (`+ - *`). [OPUS-4.8] sq-7d3dj.4.
fn compiled_expr_has_arith(e: &CompiledExpr) -> bool {
    use CompiledExpr::*;
    match e {
        Add(..) | Subtract(..) | Multiply(..) => true,
        UnaryPlus(a) | UnaryMinus(a) => compiled_expr_has_arith(a),
        _ => false,
    }
}

// [OPUS-4.8] sq-ev41x: `Num` / `Dec` / `ArithOp` / `RoundMode` and the XSD lexical helpers
// (`apply_f64`, `parse_xsd_f64`, `parse_xsd_f32`, `fmt_xsd_double`) MOVED to
// `sparq_substrate::numeric` (imported at the top of this file). The only `Num` operation
// that produced an engine-private `Value` — `canonical_term` — stays here as a free helper,
// since the substrate must not know about the engine's `Value`/`Term`. Everything else is
// the substrate's `Num` verbatim, so behaviour is unchanged.

/// The numeric value as a TERM in strict canonical form (see [`Num::canonical_lexical`]).
/// Engine-side because it constructs the engine's `Value`; the value/lexical logic lives in
/// the shared substrate.
fn num_canonical_term(n: Num) -> Value {
    Value::Term(Term::Literal(Literal::new_typed_literal(n.canonical_lexical(), n.datatype())))
}

fn effective_boolean(v: &Value) -> bool {
    ebv(v) == Some(true)
}

/// SPARQL effective boolean value, three-valued: `None` is a TYPE ERROR (unbound,
/// non-literal terms, literals of unknown datatypes, ill-formed boolean / numeric
/// lexicals) — it matters because `!error` must stay an error, not become true.
fn ebv(v: &Value) -> Option<bool> {
    match v {
        Value::Bool(b) => Some(*b),
        Value::Num(n) => Some(!n.is_zero() && !n.is_nan()),
        Value::Unbound | Value::Error => None,
        Value::Term(Term::Literal(l)) => {
            if l.language().is_some() {
                // rdf:langString / rdf:dirLangString is NOT xsd:string: its EBV is a
                // type error per SPARQL (1.2 `expression/not-not` pins this down).
                return None;
            }
            let dt = l.datatype().as_str();
            if dt == xsd::BOOLEAN.as_str() {
                match l.value() {
                    "true" | "1" => Some(true),
                    "false" | "0" => Some(false),
                    _ => None,
                }
            } else if is_numeric_dt(l) {
                // [OPUS-4.8] sq-rkzhr: XSD acceptance set (via `parse_xsd_f64`) — a
                // numeric-typed literal with an ill-formed lexical is a type error (`None`),
                // matching `as_num` rather than silently swallowing Rust-only spellings.
                parse_xsd_f64(l.value()).map(|n| n != 0.0 && !n.is_nan())
            } else if dt == xsd::STRING.as_str() {
                Some(!l.value().is_empty())
            } else {
                None
            }
        }
        Value::Term(_) => None,
    }
}

fn eval_expr(graph: &Graph, local: &LocalVocab, b: &Bindings, row: &[Id], e: &Expression) -> Result<Value, String> {
    use Expression::*;
    match e {
        Variable(v) => match b.col(v) {
            // Always return the original term so term identity is preserved
            // (sameTerm, BIND passthrough, STR, etc.). The numeric fast path that
            // skips this materialisation lives in `eval_numeric`, used only by the
            // arithmetic / comparison operators where only the value matters.
            Some(c) if row[c] != NO_ID => Ok(Value::Term(term_of(graph, local, row[c]).unwrap())),
            _ => Ok(Value::Unbound),
        },
        NamedNode(n) => Ok(Value::Term(Term::NamedNode(n.clone()))),
        Literal(l) => Ok(Value::Term(Term::Literal(l.clone()))),
        And(a, c) => {
            // SPARQL 3-valued logic, short-circuiting: false dominates, so once the
            // left is false we return false WITHOUT evaluating the right (which may be
            // an error or an unsupported expression that would otherwise abort).
            let x = ebv3(&eval_expr(graph, local, b, row, a)?);
            if x == Some(false) {
                return Ok(Value::Bool(false));
            }
            let y = ebv3(&eval_expr(graph, local, b, row, c)?);
            Ok(and3(x, y))
        }
        Or(a, c) => {
            // SPARQL 3-valued logic, short-circuiting: true dominates.
            let x = ebv3(&eval_expr(graph, local, b, row, a)?);
            if x == Some(true) {
                return Ok(Value::Bool(true));
            }
            let y = ebv3(&eval_expr(graph, local, b, row, c)?);
            Ok(or3(x, y))
        }
        Not(a) => Ok(match ebv3(&eval_expr(graph, local, b, row, a)?) {
            Some(v) => Value::Bool(!v),
            None => Value::Error, // !error = error
        }),
        Equal(a, c) => equal_expr(graph, local, b, row, a, c),
        SameTerm(a, c) => {
            let (x, y) = (eval_expr(graph, local, b, row, a)?, eval_expr(graph, local, b, row, c)?);
            Ok(Value::Bool(matches!((&x, &y), (Value::Term(p), Value::Term(q)) if p == q)))
        }
        Greater(a, c) => cmp_expr(graph, local, b, row, a, c, |o| o == Ordering::Greater),
        GreaterOrEqual(a, c) => cmp_expr(graph, local, b, row, a, c, |o| o != Ordering::Less),
        Less(a, c) => cmp_expr(graph, local, b, row, a, c, |o| o == Ordering::Less),
        LessOrEqual(a, c) => cmp_expr(graph, local, b, row, a, c, |o| o != Ordering::Greater),
        Add(a, c) => arith(graph, local, b, row, a, c, ArithOp::Add),
        Subtract(a, c) => arith(graph, local, b, row, a, c, ArithOp::Sub),
        Multiply(a, c) => arith(graph, local, b, row, a, c, ArithOp::Mul),
        Divide(a, c) => arith(graph, local, b, row, a, c, ArithOp::Div),
        UnaryPlus(a) => eval_expr(graph, local, b, row, a),
        UnaryMinus(a) => {
            // Typed negation: the result keeps the argument's (promoted) numeric
            // datatype; a non-numeric operand is a type error.
            let v = eval_expr(graph, local, b, row, a)?;
            Ok(as_numeric(&v).map(|n| Value::Num(n.neg())).unwrap_or(Value::Error))
        }
        Bound(v) => Ok(Value::Bool(b.col(v).map(|c| row[c] != NO_ID).unwrap_or(false))),
        If(cond, t, f) => {
            // A type error in the condition propagates (it does NOT silently select
            // the else branch).
            match ebv3(&eval_expr(graph, local, b, row, cond)?) {
                Some(true) => eval_expr(graph, local, b, row, t),
                Some(false) => eval_expr(graph, local, b, row, f),
                None => Ok(Value::Error),
            }
        }
        Coalesce(es) => {
            // Returns the first argument that evaluates without error (unbound and
            // type errors are both skipped).
            for e in es {
                let v = eval_expr(graph, local, b, row, e)?;
                if !matches!(v, Value::Unbound | Value::Error) {
                    return Ok(v);
                }
            }
            Ok(Value::Unbound)
        }
        In(a, list) => {
            // `?x IN (..)` is the disjunction of `?x = e` under SPARQL `=` semantics:
            // true on the first match; otherwise a type error if ANY comparison
            // errored (e.g. an unbound operand), else false. Preserving the error
            // matters outside a plain FILTER (BIND, COALESCE).
            let x = eval_expr(graph, local, b, row, a)?;
            let mut errored = false;
            for c in list {
                let y = eval_expr(graph, local, b, row, c)?;
                match values_equal(&x, &y) {
                    Some(true) => return Ok(Value::Bool(true)),
                    Some(false) => {}
                    None => errored = true,
                }
            }
            Ok(if errored { Value::Error } else { Value::Bool(false) })
        }
        FunctionCall(f, args) => eval_function(graph, local, b, row, f, args),
        Exists(inner) => Ok(Value::Bool(eval_exists(graph, local, b, row, inner)?)),
    }
}

/// Correlated `EXISTS { inner }` for one outer solution row: evaluate `inner` and
/// test whether any of its solutions is join-compatible with the row on the
/// variables they share (same term, or unbound on the inner side). Working at the
/// id/term level — rather than substituting the row's terms into the pattern AST —
/// keeps blank-node-valued bindings expressible (spargebra has no ground blank-node
/// term pattern).
///
/// The inner pattern is evaluated against `graph`, which inside `GRAPH <g> { … }`
/// is the active named graph — so an EXISTS nested in a GRAPH pattern sees the same
/// dataset as its surrounding group, per the spec.
///
/// Note: the inner evaluation is re-run per outer row (the expression evaluator is
/// read-only, so there is no per-FILTER place to memoise the inner bindings). Fine
/// for correctness and small/mid results; a shared cache is a follow-up optimisation.
///
/// [OPUS-4.8] sq-rd2 early-exit: when the inner pattern shares NO in-scope variable
/// with a BOUND outer cell, the row's compatibility test is vacuous — EXISTS is true
/// iff the inner has ANY solution. That uncorrelated case routes through the same
/// first-solution-stop path as ASK (`Slice { LIMIT 1 }`, which the single-pattern
/// scan / count pushdown answers without materialising the whole relation) instead
/// of building every inner solution just to call `.any()` on it.
fn eval_exists(graph: &Graph, local: &LocalVocab, b: &Bindings, row: &[Id], inner: &GraphPattern) -> Result<bool, String> {
    // [FABLE-5] (sq-7d3dj.30.11, PR #1785 review) Defence-in-depth against the id-fast column set
    // leaking into EXISTS re-entry: install an EMPTY set for the whole inner evaluation, so a
    // nested FILTER computes its OWN set against its OWN `Bindings` (via the wrapped dispatch) and
    // never inherits the outer pattern's column indices — which index a DIFFERENT layout. (The
    // consuming `apply_filter_scalar` already drains the set before the row loop, so by the time
    // this per-row re-entry runs the thread-local is empty anyway; this guard makes the invariant
    // hold regardless of future changes to WHEN the drain happens.)
    #[cfg(feature = "id-filter-fastpath")]
    return with_idfast_nonlit_cols(FxHashSet::default(), || {
        eval_exists_inner(graph, local, b, row, inner)
    });
    #[cfg(not(feature = "id-filter-fastpath"))]
    eval_exists_inner(graph, local, b, row, inner)
}

fn eval_exists_inner(graph: &Graph, local: &LocalVocab, b: &Bindings, row: &[Id], inner: &GraphPattern) -> Result<bool, String> {
    // zk-trace: the inner pattern is re-run per outer row; tag its scans
    // `in_exists` and suppress their steps / filter obligations (EXISTS is
    // outside the stage-1 verifiable fragment — sparq-zk::verify rejects it;
    // the tag is for forensics, not proofs).
    #[cfg(feature = "zk")]
    let _zk = crate::zk::exists_scope();

    // Uncorrelated EXISTS: no in-scope inner variable is also a BOUND outer column,
    // so no inner solution can be ruled out by compatibility — existence alone
    // decides it. `on_in_scope_variable` is spargebra's authoritative in-scope set
    // (exactly the columns `eval_graph_pattern` would expose), so this never misses a
    // genuinely-shared variable (which would make an early `true` unsound).
    let mut correlated = false;
    inner.on_in_scope_variable(|v| {
        if b.col(v).is_some_and(|oc| row[oc] != NO_ID) {
            correlated = true;
        }
    });
    if !correlated {
        // First-solution stop, reusing the ASK machinery (count pushdown / capped
        // single-pattern scan). zk-trace stays armed inside via the scope above.
        let sliced = GraphPattern::Slice { inner: Box::new(inner.clone()), start: 0, length: Some(1) };
        let mut inner_local = LocalVocab::default();
        let b1 = eval_modified(graph, &mut inner_local, &sliced)?;
        budget::check(b1.rows.len())?;
        return Ok(!b1.rows.is_empty());
    }

    let mut inner_local = LocalVocab::default();
    let inner_b = eval_graph_pattern(graph, &mut inner_local, inner)?;
    budget::check(inner_b.rows.len())?;
    // Columns shared between the inner solutions and the (bound part of the) outer row.
    let shared: Vec<(usize, usize)> = inner_b
        .vars
        .iter()
        .enumerate()
        .filter_map(|(ic, v)| b.col(v).map(|oc| (oc, ic)))
        .filter(|&(oc, _)| row[oc] != NO_ID)
        .collect();
    Ok(inner_b.rows.iter().any(|irow| {
        shared
            .iter()
            .all(|&(oc, ic)| exists_compatible(graph, local, row[oc], &inner_local, irow[ic]))
    }))
}

/// Join-compatibility of an outer cell with an inner EXISTS cell, where the two rows
/// were produced against different local vocabs: unbound inner is compatible; ids in
/// the shared spaces (graph dictionary / inline integers) compare directly; anything
/// involving a local id falls back to term equality.
fn exists_compatible(graph: &Graph, outer_local: &LocalVocab, o: Id, inner_local: &LocalVocab, i: Id) -> bool {
    if i == NO_ID {
        return true;
    }
    if !is_local(o) && !is_local(i) {
        return o == i;
    }
    term_of(graph, outer_local, o) == term_of(graph, inner_local, i)
}


/// Fast numeric evaluation that never materialises a term: a numeric variable
/// resolves to its value via the dictionary cache, a numeric literal via one
/// parse, and arithmetic recurses. Returns `None` for anything non-numeric, so
/// the caller falls back to the full (identity-preserving) `eval_expr` path.
/// Used only where the value — not the term — matters (comparison / arithmetic).
fn eval_numeric(graph: &Graph, local: &LocalVocab, b: &Bindings, row: &[Id], e: &Expression) -> Option<f64> {
    use Expression::*;
    match e {
        Variable(v) => {
            let c = b.col(v)?;
            let id = row[c];
            if id == NO_ID {
                None
            } else if is_local(id) {
                // Computed values resolve through the local vocab's numeric cache
                // (no term clone, no per-row lexical re-parse).
                local.numeric(id)
            } else {
                graph.numeric_value(id)
            }
        }
        // [FABLE-5] sq-6b1lj: the CONSTANT operand is datatype-aware/trimmed too
        // (`numeric_cache_f64`), so a datatype-ill-formed literal constant (`"1.5"^^xsd:integer`)
        // is a type error on this fast comparison path exactly as the graph-term side is.
        Literal(l) => numeric_cache_f64(l),
        Add(a, c) => Some(eval_numeric(graph, local, b, row, a)? + eval_numeric(graph, local, b, row, c)?),
        Subtract(a, c) => Some(eval_numeric(graph, local, b, row, a)? - eval_numeric(graph, local, b, row, c)?),
        Multiply(a, c) => Some(eval_numeric(graph, local, b, row, a)? * eval_numeric(graph, local, b, row, c)?),
        Divide(a, c) => Some(eval_numeric(graph, local, b, row, a)? / eval_numeric(graph, local, b, row, c)?),
        UnaryPlus(a) => eval_numeric(graph, local, b, row, a),
        UnaryMinus(a) => Some(-eval_numeric(graph, local, b, row, a)?),
        _ => None,
    }
}

/// Fast temporal (xsd:dateTime / xsd:dateTimeStamp / xsd:date) evaluation that never
/// materialises a term: a variable bound to a graph term resolves through the
/// load-time `temporals` cache (O(1), no lexical re-parse); a constant literal and a
/// BIND-computed (local-vocab) term parse once here. Returns `None` for anything
/// non-temporal or ill-formed, so the caller falls back to the general path (which
/// yields the exact type-error semantics). Used only where the VALUE matters
/// (comparison operators); term identity is never needed there.
fn eval_temporal(graph: &Graph, local: &LocalVocab, b: &Bindings, row: &[Id], e: &Expression) -> Option<Temporal> {
    use Expression::*;
    match e {
        Variable(v) => {
            let c = b.col(v)?;
            let id = row[c];
            if id == NO_ID {
                None
            } else if is_local(id) {
                // Computed values are rare; parse through the local vocab term.
                temporal_of_term(local.term(id))
            } else {
                graph.temporal_value(id)
            }
        }
        Literal(l) => temporal_of_lit(l),
        _ => None,
    }
}

/// The temporal value of a term, if it is a well-formed dateTime/date literal.
fn temporal_of_term(t: &Term) -> Option<Temporal> {
    match t {
        Term::Literal(l) => temporal_of_lit(l),
        _ => None,
    }
}

fn temporal_of_lit(l: &Literal) -> Option<Temporal> {
    if l.language().is_some() {
        return None;
    }
    Temporal::of_lit(l.value(), l.datatype().as_str())
}

/// The lexical form of an expression IF it is an exact-valued numeric operand (an
/// integer subtype or xsd:decimal — NOT float/double). Used to re-check comparisons that
/// the f64 fast path collapsed (integers > 2^53, high-precision decimals). Only reached
/// when the f64 comparison was equal, so the allocation is rare.
fn eval_exact_lexical(graph: &Graph, local: &LocalVocab, b: &Bindings, row: &[Id], e: &Expression) -> Option<String> {
    use Expression::*;
    match e {
        Variable(v) => {
            let id = row[b.col(v)?];
            if id == NO_ID {
                None
            } else if is_local(id) {
                exact_lexical_of_term(local.term(id))
            } else {
                graph.exact_numeric_lexical(id)
            }
        }
        Literal(_) => exact_lexical_of_term(&eval_expr(graph, local, b, row, e).ok().and_then(|v| match v {
            Value::Term(t) => Some(t),
            _ => None,
        })?),
        UnaryPlus(a) => eval_exact_lexical(graph, local, b, row, a),
        UnaryMinus(a) => eval_exact_lexical(graph, local, b, row, a).map(|s| match s.strip_prefix('-') {
            Some(r) => r.to_string(),
            None => format!("-{s}"),
        }),
        _ => None,
    }
}

fn exact_lexical_of_term(t: &Term) -> Option<String> {
    match t {
        Term::Literal(l)
            if l.language().is_none()
                && (sparq_core::is_integer_datatype(l.datatype().as_str()) || l.datatype() == xsd::DECIMAL) =>
        {
            Some(l.value().to_string())
        }
        _ => None,
    }
}

// ── Compiled-expression helpers (sq-7d3dj.4) ─────────────────────────────────────────────
// Mirror of `eval_numeric` / `eval_temporal` / `eval_dec` / `eval_exact_lexical` for
// [`CompiledExpr`]: no `Bindings` look-up per row — `Var(c)` uses `row[c]` directly.
// [OPUS-4.8] sq-7d3dj.4

/// Fast numeric evaluation on a pre-compiled expression. Mirrors [`eval_numeric`]. [OPUS-4.8] sq-7d3dj.4.
fn eval_compiled_numeric(graph: &Graph, local: &LocalVocab, row: &[Id], e: &CompiledExpr) -> Option<f64> {
    use CompiledExpr::*;
    match e {
        Var(col) => {
            let c = (*col)?;
            let id = row[c];
            if id == NO_ID { None } else if is_local(id) { local.numeric(id) } else { graph.numeric_value(id) }
        }
        // [FABLE-5] sq-6b1lj: datatype-aware/trimmed constant, matching `eval_numeric`.
        Literal(l) => numeric_cache_f64(l),
        Add(a, d) => Some(eval_compiled_numeric(graph, local, row, a)? + eval_compiled_numeric(graph, local, row, d)?),
        Subtract(a, d) => {
            Some(eval_compiled_numeric(graph, local, row, a)? - eval_compiled_numeric(graph, local, row, d)?)
        }
        Multiply(a, d) => {
            Some(eval_compiled_numeric(graph, local, row, a)? * eval_compiled_numeric(graph, local, row, d)?)
        }
        Divide(a, d) => {
            Some(eval_compiled_numeric(graph, local, row, a)? / eval_compiled_numeric(graph, local, row, d)?)
        }
        UnaryPlus(a) => eval_compiled_numeric(graph, local, row, a),
        UnaryMinus(a) => Some(-eval_compiled_numeric(graph, local, row, a)?),
        _ => None,
    }
}

/// Fast temporal evaluation on a pre-compiled expression. Mirrors [`eval_temporal`]. [OPUS-4.8] sq-7d3dj.4.
fn eval_compiled_temporal(graph: &Graph, local: &LocalVocab, row: &[Id], e: &CompiledExpr) -> Option<Temporal> {
    use CompiledExpr::*;
    match e {
        Var(col) => {
            let c = (*col)?;
            let id = row[c];
            if id == NO_ID {
                None
            } else if is_local(id) {
                temporal_of_term(local.term(id))
            } else {
                graph.temporal_value(id)
            }
        }
        Literal(l) => temporal_of_lit(l),
        _ => None,
    }
}

/// Exact decimal evaluation on a pre-compiled expression. Mirrors [`eval_dec`]. [OPUS-4.8] sq-7d3dj.4.
fn eval_compiled_dec(graph: &Graph, local: &LocalVocab, row: &[Id], e: &CompiledExpr) -> Option<Dec> {
    use CompiledExpr::*;
    match e {
        Var(col) => {
            let c = (*col)?;
            let id = row[c];
            if id == NO_ID {
                None
            } else if is_local(id) {
                exact_lexical_of_term(local.term(id)).and_then(|s| Dec::parse(&s))
            } else {
                Dec::parse(&graph.exact_numeric_lexical(id)?)
            }
        }
        Literal(l) if sparq_core::is_integer_datatype(l.datatype().as_str()) || l.datatype() == xsd::DECIMAL => {
            Dec::parse(l.value())
        }
        Add(a, d) => eval_compiled_dec(graph, local, row, a)?.checked_add(eval_compiled_dec(graph, local, row, d)?),
        Subtract(a, d) => {
            eval_compiled_dec(graph, local, row, a)?.checked_sub(eval_compiled_dec(graph, local, row, d)?)
        }
        Multiply(a, d) => {
            eval_compiled_dec(graph, local, row, a)?.checked_mul(eval_compiled_dec(graph, local, row, d)?)
        }
        UnaryPlus(a) => eval_compiled_dec(graph, local, row, a),
        UnaryMinus(a) => {
            let d = eval_compiled_dec(graph, local, row, a)?;
            Some(Dec { mant: d.mant.checked_neg()?, scale: d.scale })
        }
        _ => None,
    }
}

/// Exact lexical form for precise decimal/integer comparison. Mirrors [`eval_exact_lexical`]. [OPUS-4.8] sq-7d3dj.4.
fn eval_compiled_exact_lexical(graph: &Graph, local: &LocalVocab, row: &[Id], e: &CompiledExpr) -> Option<String> {
    use CompiledExpr::*;
    match e {
        Var(col) => {
            let c = (*col)?;
            let id = row[c];
            if id == NO_ID {
                None
            } else if is_local(id) {
                exact_lexical_of_term(local.term(id))
            } else {
                graph.exact_numeric_lexical(id)
            }
        }
        Literal(l) => {
            // Avoid a `Term` allocation: check directly whether the literal has an exact
            // integer/decimal lexical form (same condition as `exact_lexical_of_term`).
            if l.language().is_none()
                && (sparq_core::is_integer_datatype(l.datatype().as_str()) || l.datatype() == xsd::DECIMAL)
            {
                Some(l.value().to_string())
            } else {
                None
            }
        }
        UnaryPlus(a) => eval_compiled_exact_lexical(graph, local, row, a),
        UnaryMinus(a) => eval_compiled_exact_lexical(graph, local, row, a).map(|s| match s.strip_prefix('-') {
            Some(r) => r.to_string(),
            None => format!("-{}", s),
        }),
        _ => None,
    }
}

/// Exact comparison of two `xsd:decimal` / integer lexical forms (no f64). `None` if
/// either is not a well-formed decimal. Integers are decimals with an empty fraction.
fn cmp_decimal_str(a: &str, b: &str) -> Option<Ordering> {
    let (na, ia, fa) = split_decimal(a)?;
    let (nb, ib, fb) = split_decimal(b)?;
    let a_zero = ia.is_empty() && fa.is_empty();
    let b_zero = nb_is_zero(ib, fb);
    if a_zero && b_zero {
        return Some(Ordering::Equal);
    }
    let mag = ia
        .len()
        .cmp(&ib.len())
        .then_with(|| ia.cmp(ib))
        .then_with(|| {
            let n = fa.len().max(fb.len());
            // Compare fractional digits with implicit trailing-zero padding.
            (0..n)
                .map(|i| (fa.as_bytes().get(i).copied().unwrap_or(b'0'), fb.as_bytes().get(i).copied().unwrap_or(b'0')))
                .find_map(|(x, y)| (x != y).then(|| x.cmp(&y)))
                .unwrap_or(Ordering::Equal)
        });
    let neg_a = na && !a_zero;
    let neg_b = nb && !b_zero;
    Some(match (neg_a, neg_b) {
        (true, false) => Ordering::Less,
        (false, true) => Ordering::Greater,
        (false, false) => mag,
        (true, true) => mag.reverse(),
    })
}

fn nb_is_zero(int: &str, frac: &str) -> bool {
    int.is_empty() && frac.is_empty()
}

/// Significant decimal digits in a numeric lexical — used to decide whether the f64
/// sargable path is precision-safe (<= 15 digits round-trips through f64 unambiguously).
fn sig_digits(s: &str) -> usize {
    let (_, int, frac) = match split_decimal(s) {
        Some(p) => p,
        None => return usize::MAX,
    };
    if int.is_empty() {
        // 0.00123 -> significant digits start at the first non-zero fraction digit.
        frac.trim_start_matches('0').len()
    } else {
        int.len() + frac.len()
    }
}

/// `true` if the expression performs arithmetic (`+ - *` / unary sign), so a comparison
/// over it must be evaluated EXACTLY rather than via f64 — the only case where f64 can
/// produce a wrong ordering for integer/decimal data (value comparison is monotonic;
/// arithmetic introduces flippable rounding error).
fn expr_has_arith(e: &Expression) -> bool {
    use Expression::*;
    match e {
        Add(..) | Subtract(..) | Multiply(..) => true,
        UnaryPlus(a) | UnaryMinus(a) => expr_has_arith(a),
        _ => false,
    }
}

/// Evaluates an expression EXACTLY as a fixed-point decimal, for integer/decimal operands
/// and `+ - *`. `None` for anything not exactly representable this way (division, doubles,
/// non-numeric operands, overflow) — the caller then uses the f64 path.
fn eval_dec(graph: &Graph, local: &LocalVocab, b: &Bindings, row: &[Id], e: &Expression) -> Option<Dec> {
    use Expression::*;
    match e {
        Variable(v) => {
            let id = row[b.col(v)?];
            if id == NO_ID {
                None
            } else if is_local(id) {
                exact_lexical_of_term(local.term(id)).and_then(|s| Dec::parse(&s))
            } else {
                Dec::parse(&graph.exact_numeric_lexical(id)?)
            }
        }
        Literal(l) if sparq_core::is_integer_datatype(l.datatype().as_str()) || l.datatype() == xsd::DECIMAL => {
            Dec::parse(l.value())
        }
        Add(a, c) => eval_dec(graph, local, b, row, a)?.checked_add(eval_dec(graph, local, b, row, c)?),
        Subtract(a, c) => eval_dec(graph, local, b, row, a)?.checked_sub(eval_dec(graph, local, b, row, c)?),
        Multiply(a, c) => eval_dec(graph, local, b, row, a)?.checked_mul(eval_dec(graph, local, b, row, c)?),
        UnaryPlus(a) => eval_dec(graph, local, b, row, a),
        UnaryMinus(a) => {
            let d = eval_dec(graph, local, b, row, a)?;
            Some(Dec { mant: d.mant.checked_neg()?, scale: d.scale })
        }
        _ => None,
    }
}

/// An ORDERING comparison (`<`, `>`, `<=`, `>=`). SPARQL only orders operands of
/// compatible types (numeric vs numeric, boolean vs boolean, or two literals of the
/// same datatype); anything else is a TYPE ERROR (`Value::Error`), which a FILTER
/// turns into "excluded". (Distinct from the lenient total order `compare_values`
/// used by ORDER BY / MIN / MAX, which must order across every type.)
fn cmp_expr(graph: &Graph, local: &LocalVocab, b: &Bindings, row: &[Id], a: &Expression, c: &Expression, f: impl Fn(Ordering) -> bool) -> Result<Value, String> {
    // EXACT path: integer/decimal arithmetic (`+ - *`) must not round through f64, which
    // can flip an ordering (`0.1 + 0.2` < `0.3` in f64). Only attempted when arithmetic is
    // present (the common, arithmetic-free comparison keeps the f64 fast path below).
    if expr_has_arith(a) || expr_has_arith(c) {
        if let (Some(da), Some(db)) = (eval_dec(graph, local, b, row, a), eval_dec(graph, local, b, row, c)) {
            if let Some(o) = da.cmp(db) {
                return Ok(Value::Bool(f(o)));
            }
        }
    }
    // Fast path: both sides numeric -> compare f64 directly, no term materialised.
    // Reaching here means BOTH operands are numeric, so a `None` partial_cmp is a
    // NaN value (op:numeric ordering of NaN is false) — NOT a cross-type error.
    if let (Some(x), Some(y)) = (eval_numeric(graph, local, b, row, a), eval_numeric(graph, local, b, row, c)) {
        // f64 rounding is monotonic — it only ever COLLAPSES distinct values to equal,
        // never flips an ordering. So re-check exactly ONLY when f64 says equal (catches
        // integers > 2^53 and high-precision decimals that share an f64).
        if x == y {
            if let (Some(la), Some(lb)) = (eval_exact_lexical(graph, local, b, row, a), eval_exact_lexical(graph, local, b, row, c)) {
                if let Some(ord) = cmp_decimal_str(&la, &lb) {
                    return Ok(Value::Bool(f(ord)));
                }
            }
        }
        return Ok(Value::Bool(x.partial_cmp(&y).map(&f).unwrap_or(false)));
    }
    // Fast path: both sides temporal -> compare cached/parsed timeline values, no term
    // materialised. `None` from `cmp_t` is exactly the strict path's type-error cases
    // (cross-family dateTime vs date, or mixed timezone presence inside the ±14h window).
    if let (Some(ta), Some(tb)) = (eval_temporal(graph, local, b, row, a), eval_temporal(graph, local, b, row, c)) {
        return Ok(match Temporal::cmp_t(ta, tb) {
            Some(o) => Value::Bool(f(o)),
            None => Value::Error,
        });
    }
    let (x, y) = (eval_expr(graph, local, b, row, a)?, eval_expr(graph, local, b, row, c)?);
    Ok(match value_compare_strict(&x, &y) {
        Some(o) => Value::Bool(f(o)),
        None => Value::Error,
    })
}

/// SPARQL `=` (and, negated, `!=`). See [`values_equal`].
fn equal_expr(graph: &Graph, local: &LocalVocab, b: &Bindings, row: &[Id], a: &Expression, c: &Expression) -> Result<Value, String> {
    // EXACT integer/decimal arithmetic equality (see `cmp_expr`) — `0.1 + 0.2 = 0.3`.
    if expr_has_arith(a) || expr_has_arith(c) {
        if let (Some(da), Some(db)) = (eval_dec(graph, local, b, row, a), eval_dec(graph, local, b, row, c)) {
            if let Some(o) = da.cmp(db) {
                return Ok(Value::Bool(o == Ordering::Equal));
            }
        }
    }
    // Fast path: both numeric (NaN == NaN is false, matching op:numeric-equal).
    if let (Some(x), Some(y)) = (eval_numeric(graph, local, b, row, a), eval_numeric(graph, local, b, row, c)) {
        // Re-check exactly when f64 says equal (see `cmp_expr`): distinct integers > 2^53
        // or high-precision decimals can share an f64 and must not be reported equal.
        if x == y {
            if let (Some(la), Some(lb)) = (eval_exact_lexical(graph, local, b, row, a), eval_exact_lexical(graph, local, b, row, c)) {
                if let Some(ord) = cmp_decimal_str(&la, &lb) {
                    return Ok(Value::Bool(ord == Ordering::Equal));
                }
            }
        }
        return Ok(Value::Bool(x == y));
    }
    // Fast path: both temporal. Same-family operands decide by timeline (`None` =
    // the indeterminate mixed-timezone window -> type error); dateTime and date are
    // DISJOINT value spaces -> known different (matching `values_equal`).
    if let (Some(ta), Some(tb)) = (eval_temporal(graph, local, b, row, a), eval_temporal(graph, local, b, row, c)) {
        if ta.kind != tb.kind {
            return Ok(Value::Bool(false));
        }
        return Ok(match Temporal::cmp_t(ta, tb) {
            Some(o) => Value::Bool(o == Ordering::Equal),
            None => Value::Error,
        });
    }
    let (x, y) = (eval_expr(graph, local, b, row, a)?, eval_expr(graph, local, b, row, c)?);
    Ok(match values_equal(&x, &y) {
        Some(eq) => Value::Bool(eq),
        None => Value::Error,
    })
}

/// Datatype family of a literal-valued operand, the basis for OPEN-WORLD `=` and
/// the ordering operators: only operands within a comparable family decide; unknown
/// datatypes and ill-formed lexicals are type errors unless the terms are identical.
enum LitKind<'a> {
    /// A numeric-datatype operand; `None` = ill-formed lexical.
    Num(Option<Num>),
    Str(&'a str),
    /// A boolean-datatype operand; `None` = ill-formed lexical.
    Bool(Option<bool>),
    /// xsd:dateTime / xsd:dateTimeStamp on the timeline; `None` = ill-formed.
    DateTime(Option<Timeline>),
    /// xsd:date on the timeline (midnight); `None` = ill-formed.
    Date(Option<Timeline>),
    /// Another XSD datatype (time, duration, gYear, …): (datatype IRI, lexical).
    OtherXsd(&'a str, &'a str),
    /// Language-tagged: (lowercased tag, value).
    Lang(String, &'a str),
    /// A literal of a NON-XSD (unknown) datatype: open-world, never decidable.
    Unknown,
    NotLiteral,
}

fn lit_kind(v: &Value) -> LitKind<'_> {
    match v {
        Value::Num(n) => LitKind::Num(Some(*n)),
        Value::Bool(b) => LitKind::Bool(Some(*b)),
        Value::Term(Term::Literal(l)) => {
            if let Some(tag) = l.language() {
                return LitKind::Lang(tag.to_ascii_lowercase(), l.value());
            }
            let dt = l.datatype();
            if is_numeric_dt(l) {
                LitKind::Num(Num::of_literal(l))
            } else if dt == xsd::STRING {
                LitKind::Str(l.value())
            } else if dt == xsd::BOOLEAN {
                LitKind::Bool(as_bool_val(v))
            } else if dt == xsd::DATE_TIME || dt == xsd::DATE_TIME_STAMP {
                LitKind::DateTime(Timeline::parse_datetime(l.value()))
            } else if dt == xsd::DATE {
                LitKind::Date(Timeline::parse_date(l.value()))
            } else if dt.as_str().starts_with("http://www.w3.org/2001/XMLSchema#") {
                LitKind::OtherXsd(dt.as_str(), l.value())
            } else {
                LitKind::Unknown
            }
        }
        _ => LitKind::NotLiteral,
    }
}

// `Timeline` (the parsed xsd:date/dateTime value) and its comparison rules live in
// `sparq_core::temporal`, shared with the graph's load-time `temporals` cache.

/// SPARQL `=` (and, negated, `!=`) as a three-valued result: `Some(true/false)` for a
/// decided comparison, `None` for a type error. OPEN-WORLD rules: identical terms are
/// equal regardless of datatype; non-literal terms decide by identity; within a
/// comparable literal family the VALUES decide; a language-tagged literal is KNOWN
/// different from any non-language literal; everything else — unknown datatypes,
/// ill-formed lexicals, cross-family pairs — is a TYPE ERROR (`"a"^^ex:dt != "b"^^ex:other`
/// filters the row out rather than evaluating to true).
fn values_equal(x: &Value, y: &Value) -> Option<bool> {
    if matches!(x, Value::Unbound | Value::Error) || matches!(y, Value::Unbound | Value::Error) {
        return None;
    }
    if let (Value::Term(p), Value::Term(q)) = (x, y) {
        if p == q {
            return Some(true); // sameTerm decides even for unknown datatypes
        }
        // RDF 1.2 triple terms compare componentwise, with VALUE equality on the
        // objects (`<<(:a :b 01)>> = <<(:a :b 1)>>` is true, errors propagate).
        if let (Term::Triple(a), Term::Triple(b)) = (p, q) {
            if a.subject != b.subject || a.predicate != b.predicate {
                return Some(false);
            }
            return values_equal(&Value::Term(a.object.clone()), &Value::Term(b.object.clone()));
        }
        if !matches!(p, Term::Literal(_)) || !matches!(q, Term::Literal(_)) {
            return Some(false); // IRI / bnode: identity decides
        }
    }
    let (ka, kb) = (lit_kind(x), lit_kind(y));
    if matches!(ka, LitKind::NotLiteral) || matches!(kb, LitKind::NotLiteral) {
        return Some(false); // computed literal vs non-literal term
    }
    use LitKind::*;
    match (ka, kb) {
        (Num(Some(a)), Num(Some(b))) => Some(num_compare(a, b) == Some(Ordering::Equal)),
        (Num(_), Num(_)) => None, // ill-formed numeric (and not sameTerm)
        (Str(a), Str(b)) => Some(a == b),
        (Bool(Some(a)), Bool(Some(b))) => Some(a == b),
        (Bool(_), Bool(_)) => None,
        (DateTime(Some(a)), DateTime(Some(b))) => Timeline::cmp_tl(a, b).map(|o| o == Ordering::Equal),
        (Date(Some(a)), Date(Some(b))) => Timeline::cmp_tl(a, b).map(|o| o == Ordering::Equal),
        (DateTime(_), DateTime(_)) | (Date(_), Date(_)) => None,
        // date and dateTime values are disjoint -> known different.
        (DateTime(_), Date(_)) | (Date(_), DateTime(_)) => Some(false),
        // A language-tagged literal equals only a literal with the same (ci) tag.
        (Lang(t1, v1), Lang(t2, v2)) => Some(t1 == t2 && v1 == v2),
        (Lang(..), _) | (_, Lang(..)) => Some(false),
        (OtherXsd(d1, l1), OtherXsd(d2, l2)) if d1 == d2 => Some(l1 == l2),
        // Cross-family, unknown datatypes, unknown XSD pairings: open world -> error.
        _ => None,
    }
}

/// Strict SPARQL value comparison for relational operators: `Some(ordering)` only
/// when the operands are value-comparable (same family per [`lit_kind`]), else
/// `None` (a type error).
fn value_compare_strict(x: &Value, y: &Value) -> Option<Ordering> {
    use LitKind::*;
    match (lit_kind(x), lit_kind(y)) {
        (Num(Some(a)), Num(Some(b))) => num_compare(a, b),
        (Str(a), Str(b)) => Some(a.cmp(b)),
        (Bool(Some(a)), Bool(Some(b))) => Some(a.cmp(&b)),
        (DateTime(Some(a)), DateTime(Some(b))) => Timeline::cmp_tl(a, b),
        (Date(Some(a)), Date(Some(b))) => Timeline::cmp_tl(a, b),
        // Same language tag: compare values (the suites' lenient extension).
        (Lang(t1, v1), Lang(t2, v2)) if t1 == t2 => Some(v1.cmp(v2)),
        // Same other-XSD datatype: lexical order (correct for time, gYear, …).
        (OtherXsd(d1, l1), OtherXsd(d2, l2)) if d1 == d2 => Some(l1.cmp(l2)),
        _ => None,
    }
}

/// The TOTAL-order verdict for a same-family temporal pair `value_compare_strict` left
/// indeterminate (the mixed-timezone ±14h window) — `None` for every other pair, which
/// keeps the caller's own fallback. Reached ONLY from the `CompareTerm` total order, never
/// from a relational operator. [SONNET-4.6] sq-2k5py
#[cold]
fn temporal_total_cmp(x: &Value, y: &Value) -> Option<Ordering> {
    match (lit_kind(x), lit_kind(y)) {
        (LitKind::DateTime(Some(a)), LitKind::DateTime(Some(b)))
        | (LitKind::Date(Some(a)), LitKind::Date(Some(b))) => Some(Timeline::cmp_tl_total(a, b)),
        _ => None,
    }
}

fn as_bool_val(v: &Value) -> Option<bool> {
    match v {
        Value::Bool(b) => Some(*b),
        Value::Term(Term::Literal(l)) if l.datatype() == xsd::BOOLEAN => match l.value() {
            "true" | "1" => Some(true),
            "false" | "0" => Some(false),
            _ => None,
        },
        _ => None,
    }
}

/// Three-valued effective boolean: `None` is a SPARQL error (type error or unbound),
/// used by the logical operators to implement SPARQL's 3-valued `&&` / `||` / `!`.
fn ebv3(v: &Value) -> Option<bool> {
    ebv(v)
}

fn and3(x: Option<bool>, y: Option<bool>) -> Value {
    match (x, y) {
        (Some(false), _) | (_, Some(false)) => Value::Bool(false),
        (Some(true), Some(true)) => Value::Bool(true),
        _ => Value::Error,
    }
}

fn or3(x: Option<bool>, y: Option<bool>) -> Value {
    match (x, y) {
        (Some(true), _) | (_, Some(true)) => Value::Bool(true),
        (Some(false), Some(false)) => Value::Bool(false),
        _ => Value::Error,
    }
}

/// TYPED arithmetic with XPath operand promotion: the result carries the promoted
/// datatype (int+int→int, decimal involved→decimal, …, int/int→decimal) and exact
/// int/decimal value. Used for RESULT CONSTRUCTION (BIND / SELECT expressions /
/// aggregates) — the comparison operators keep their f64 fast path (`eval_numeric`),
/// where only the value matters.
fn arith(graph: &Graph, local: &LocalVocab, b: &Bindings, row: &[Id], a: &Expression, c: &Expression, op: ArithOp) -> Result<Value, String> {
    let (x, y) = (eval_expr(graph, local, b, row, a)?, eval_expr(graph, local, b, row, c)?);
    Ok(match (as_numeric(&x), as_numeric(&y)) {
        (Some(p), Some(q)) => p.binop(q, op).map(Value::Num).unwrap_or(Value::Error),
        _ => Value::Error,
    })
}

/// The TYPED numeric value of an evaluated operand: a computed numeric as-is, a
/// numeric literal parsed per its datatype. `None` for non-numerics AND for
/// ill-formed numeric literals (both are SPARQL type errors in arithmetic).
fn as_numeric(v: &Value) -> Option<Num> {
    match v {
        Value::Num(n) => Some(*n),
        Value::Term(Term::Literal(l)) => Num::of_literal(l),
        _ => None,
    }
}

fn as_num(v: &Value) -> Option<f64> {
    match v {
        Value::Num(n) => Some(n.f64()),
        Value::Bool(b) => Some(if *b { 1.0 } else { 0.0 }),
        // [FABLE-5] sq-74oy4 / sq-6b1lj: route the lexical→f64 arm through the DATATYPE-AWARE
        // `numeric_cache_f64` — the SAME acceptance the graph `numeric_value` cache and
        // `LocalVocab::intern` use. This keeps the lenient relational `<`/`>` seam in lock-step
        // with the equality reference `Num::of_literal` on BOTH residuals sq-9781x left open:
        // (a) whitespace — the value is TRIMMED (XSD `collapse` facet), so a padded
        // `" 1"^^xsd:integer` is value-1 on `<`/`>` exactly as it is on `=` (was: type-error
        // on `<`/`>`, cache-miss, but value-1 on `=` via the trimming cache); (b) per-datatype
        // well-formedness — a lexical ill-formed FOR its datatype (`"1.5"^^xsd:integer`,
        // `"1E2"^^xsd:decimal`, an i128-overflow decimal) is `None` here, a type error on
        // `<`/`>` matching `of_literal` (was: compared as f64). The XSD f64 SPELLINGS
        // (INF/+INF/-INF/NaN yes; Rust-only inf/infinity/nan no) are still enforced by the
        // underlying `parse_xsd_f64` image.
        Value::Term(Term::Literal(l)) => numeric_cache_f64(l),
        _ => None,
    }
}

fn is_numeric_dt(l: &Literal) -> bool {
    let dt = l.datatype().as_str();
    sparq_core::is_integer_datatype(dt)
        || dt == xsd::DECIMAL.as_str()
        || dt == xsd::DOUBLE.as_str()
        || dt == xsd::FLOAT.as_str()
}

/// The DATATYPE-AWARE cached/lenient f64 of a numeric literal, matching the graph's
/// `Graph::numeric_value` cache acceptance (sparq-core `cached_numeric_f64`): `Some` iff the
/// lexical is well-formed FOR ITS DATATYPE (`Num::of_literal` accepts it), imaged by the
/// shared `parse_xsd_f64` on the TRIMMED lexical so the value is bit-identical to what the
/// graph cache and `LocalVocab::intern` store for the same term. `None` (a datatype-ill-formed
/// lexical like `"1.5"^^xsd:integer`, or a non-numeric) is a SPARQL type error.
///
/// [FABLE-5] (sq-74oy4 / sq-6b1lj) This is the single acceptance the lenient relational seam
/// (`as_num`/`as_f64`), the local-vocab numeric cache (`LocalVocab::intern`), and the graph
/// cache now all share — closing the pre-fix asymmetry where `as_num`/`intern` parsed
/// datatype-agnostically (and un-trimmed) while `Num::of_literal` (the equality reference)
/// did not, so a padded or per-datatype-ill-formed lexical compared numerically on `<`/`>`
/// yet type-errored on `=`. Acceptance is gated on `Num::of_literal` (the strictest, so the
/// datatype rules can never drift); the f64 image is `parse_xsd_f64` (every lexical
/// `of_literal` accepts, `parse_xsd_f64` also accepts, for the same value).
#[inline]
fn numeric_cache_f64(l: &Literal) -> Option<f64> {
    if is_numeric_dt(l) && Num::of_literal(l).is_some() {
        parse_xsd_f64(l.value().trim())
    } else {
        None
    }
}

// [OPUS-4.8] sq-vezew (epic sq-qonbz, Phase 4): the engine implements the substrate's
// `CompareTerm` trait for its `Value` — a set of ZERO-COST wrappers over the existing
// `value_str` / `as_num` / `value_compare_strict` helpers — so the shared
// `compare::compare_terms` total-order algorithm can drive the engine's `Value` with no vtable.
// The class ranks, the within-class string / numeric / strict arms, and the recursive
// triple-term order all live in the substrate now; this impl only surfaces the observations.
impl CompareTerm for Value {
    #[inline]
    fn term_class(&self) -> TermClass {
        match self {
            Value::Unbound | Value::Error => TermClass::ErrorOrUnbound,
            Value::Term(Term::BlankNode(_)) => TermClass::Blank,
            Value::Term(Term::NamedNode(_)) => TermClass::Iri,
            // SPARQL 1.2 total-order extension: triple terms sort AFTER literals.
            Value::Term(Term::Triple(_)) => TermClass::Triple,
            _ => TermClass::Literal, // literals, incl. computed numerics / booleans
        }
    }
    #[inline]
    fn literal_kind(&self) -> LiteralKind {
        // [FABLE-5] sq-wjl8i / sq-74oy4: the kind-first rank of the total order. Numeric
        // tracks the `as_num` membership (the same set the numeric arm compares), which is
        // now DATATYPE-AWARE (sq-74oy4): a lexical ill-formed FOR its datatype (e.g.
        // "1.5"^^xsd:integer) is NOT numeric here and classifies as Other (lexical order) —
        // matching `of_literal` and keeping the Numeric kind purely value-ordered (a kind
        // mixing value-ordered and type-error pairs is intransitive — the very bug this rank
        // removes; pre-sq-74oy4 the lenient `as_num` wrongly kept such a lexical Numeric).
        // A computed boolean (whose f64 view is 0.0/1.0) classifies as Boolean, keeping it in
        // one kind with boolean LITERALS (both order `false < true` via `strict_cmp`).
        match lit_kind(self) {
            LitKind::Bool(_) => LiteralKind::Boolean,
            LitKind::Num(_) if as_num(self).is_some() => LiteralKind::Numeric,
            LitKind::Str(_) => LiteralKind::String,
            LitKind::Lang(..) => LiteralKind::Lang,
            LitKind::DateTime(Some(_)) => LiteralKind::DateTime,
            LitKind::Date(Some(_)) => LiteralKind::Date,
            // Ill-formed numerics/temporals, other-XSD, unknown datatypes (and the
            // unreachable non-literal case — `compare_terms` gates on the class).
            _ => LiteralKind::Other,
        }
    }
    #[inline]
    fn value_str(&self) -> Option<String> {
        value_str(self)
    }
    #[inline]
    fn as_f64(&self) -> Option<f64> {
        as_num(self)
    }
    #[inline]
    fn exact_cmp(&self, other: &Self) -> Option<Ordering> {
        // [OPUS-4.8] sq-rikm7 / [FABLE-5] sq-wjl8i: f64-collapse recheck — when the
        // lenient `as_num` arm reports two numeric literals EQUAL, the pair rechecks
        // under `Num::cmp_total`, the EXACT-RATIONAL total order: exact via the decimal
        // tower for int/decimal pairs, exact against the double's exact decimal
        // expansion for the MIXED exact/inexact pair (the pre-fix `num_compare`
        // fallback kept the collapsed f64 verdict there, which made the order
        // intransitive at the 2^53 collapse — witness 1 of sq-wjl8i). The relational
        // `<`/`=` (`cmp_expr`) and MIN/MAX (`minmax_values`) deliberately KEEP the
        // XPath promoted semantics via `num_compare`; this total order refines only
        // their ties. `None` (a lexical beyond the exact tower) keeps the tie.
        match (as_numeric(self), as_numeric(other)) {
            (Some(a), Some(b)) => Some(a.cmp_total(b)),
            _ => None,
        }
    }
    #[inline]
    fn strict_cmp(&self, other: &Self) -> Option<Ordering> {
        // dateTime/date by timeline, same-tag / same-other-XSD lexically — when comparable.
        // [SONNET-4.6] sq-2k5py: `value_compare_strict` is the RELATIONAL comparison, so it
        // leaves the mixed-timezone window indeterminate; for the TOTAL order that `None`
        // would drop the pair to `compare_terms`' lexical fallback INSIDE the DateTime kind,
        // which is intransitive (`Timeline::cmp_tl_total`'s witness). Only on that `None` —
        // so the decided path costs nothing — re-decide a same-family temporal pair under
        // the total-order extension. Relational `<`/`>`/`=` keep the type error.
        value_compare_strict(self, other).or_else(|| temporal_total_cmp(self, other))
    }
    #[inline]
    fn triple_parts(&self) -> Option<[Self; 3]> {
        let Value::Term(Term::Triple(t)) = self else {
            return None;
        };
        // The subject (named-or-blank) and predicate (always an IRI) are lifted to `Value`s so
        // the generic recursion classifies + compares them by exactly the rules `compare_values`
        // applied inline: the subject by blank/IRI string, the predicate by IRI string (== its
        // `as_str().cmp(..)`), the object under the full order.
        let subject = Value::Term(match &t.subject {
            NamedOrBlankNode::NamedNode(n) => Term::NamedNode(n.clone()),
            NamedOrBlankNode::BlankNode(b) => Term::BlankNode(b.clone()),
        });
        let predicate = Value::Term(Term::NamedNode(t.predicate.clone()));
        let object = Value::Term(t.object.clone());
        Some([subject, predicate, object])
    }
}

/// The TOTAL order for ORDER BY (and the MIN/MAX fallback): SPARQL orders
/// unbound < blank nodes < IRIs < literals (< triple terms), then literals KIND-FIRST —
/// a fixed `LiteralKind` rank between literal kinds (numeric < boolean < dateTime <
/// date < string < language-tagged < other), value order only WITHIN a kind (numerics
/// by exact value with NaN first, dateTimes by timeline, else lexically).
///
/// [OPUS-4.8] sq-vezew: the algorithm lives in `sparq_substrate::compare::compare_terms`,
/// generic over the `CompareTerm` trait the engine implements for `Value` above — a thin
/// monomorphised call into the shared substrate. [FABLE-5] sq-wjl8i: the order is
/// deliberately NOT the pre-move lexical-fallback body — cross-kind lexical fallback,
/// collapsed mixed-tier f64 ties and NaN partiality made it intransitive (three
/// machine-checked witnesses; see the substrate module docs for what is spec-mandated
/// vs a documented extension). Relational `<` / `=` semantics are UNTOUCHED.
#[inline]
fn compare_values(x: &Value, y: &Value) -> Option<Ordering> {
    compare_terms(x, y)
}

/// SPARQL built-in function calls (`STR`, `LANG`, `CONCAT`, `SUBSTR`, type tests, numeric, …).
/// Unsupported functions (hashes, dateTime, REGEX, BNODE/RAND/UUID) return a clear error rather
/// than a silent wrong answer. SPARQL type errors map to `Value::Error` (EBV false; unbound on BIND).
///
/// Inner body of SPARQL function evaluation, generic over the per-argument evaluator `ev`.
/// Called both from [`eval_function`] (with `eval_expr` as evaluator) and from [`eval_compiled`]
/// (with `eval_compiled` as evaluator). [OPUS-4.8] sq-7d3dj.4.
fn eval_function_inner<E: Fn(usize) -> Result<Value, String>>(
    f: &spargebra::algebra::Function,
    nargs: usize,
    ev: E,
) -> Result<Value, String> {
    use spargebra::algebra::Function as F;
    let simple = |s: String| Value::Term(Term::Literal(Literal::new_simple_literal(s)));
    // Both operands as ARGUMENT-COMPATIBLE string literals (second simple/xsd:string,
    // or same language tag as the first), else `Value::Error`.
    let str_compat2 = |a: &Value, c: &Value, g: &dyn Fn(&str, &str) -> bool| match (str_lit(a), str_lit(c)) {
        (Some((x, lx)), Some((y, ly))) if ly.is_none() || ly == lx => Value::Bool(g(&x, &y)),
        _ => Value::Error,
    };
    Ok(match f {
        // [FABLE-5] (sq-qeltv) STR is defined over LITERALS and IRIs only, per SPARQL 1.1
        // §17.4.2.5 (`simple literal STR(literal ltrl)` / `simple literal STR(IRI rsrc)`).
        // A blank-node operand is a TYPE ERROR — the old `value_str` coercion leaked the
        // ENGINE-INTERNAL bnode label (not a principled §17.3.1 extension: the label is
        // dictionary-private and unstable). Unbound / errored / triple-term operands stay
        // errors as before; computed numerics/booleans are literal values, so they pass.
        // Differential (bead): Oxigraph errors here too; rdflib leniently returns ITS
        // internal label — divergent-by-engine, exactly why the label must not leak.
        F::Str => match ev(0)? {
            Value::Term(Term::NamedNode(n)) => simple(n.as_str().to_string()),
            Value::Term(Term::Literal(l)) => simple(l.value().to_string()),
            Value::Num(n) => simple(n.lexical()),
            Value::Bool(b) => simple(b.to_string()),
            _ => Value::Error,
        },
        // [OPUS-4.8] STRLEN's operand is a STRING LITERAL (simple / lang-tagged /
        // xsd:string), per SPARQL 1.1 §17.4.3.2 `xsd:integer STRLEN(string literal)`.
        // An IRI / number / boolean is a TYPE ERROR — NOT its STR() length (the old
        // `value_str` coercion wrongly returned `STRLEN(<iri>)` = the IRI's length).
        F::StrLen => str_lit(&ev(0)?).map(|(s, _)| Value::Num(Num::Int(s.chars().count() as i64))).unwrap_or(Value::Error),
        // UCASE/LCASE/SUBSTR operate on string literals and preserve the language tag
        // of the argument (simple in, simple out; "bar"@en in, "BAR"@en out).
        F::UCase => match str_lit(&ev(0)?) {
            Some((s, lang)) => lit_with_lang(s.to_uppercase(), lang.as_deref()),
            None => Value::Error,
        },
        F::LCase => match str_lit(&ev(0)?) {
            Some((s, lang)) => lit_with_lang(s.to_lowercase(), lang.as_deref()),
            None => Value::Error,
        },
        F::Lang => match ev(0)? {
            Value::Term(Term::Literal(l)) => simple(l.language().unwrap_or("").to_string()),
            Value::Num(_) | Value::Bool(_) => simple(String::new()),
            _ => Value::Error,
        },
        F::Datatype => match ev(0)? {
            Value::Term(Term::Literal(l)) => Value::Term(Term::NamedNode(l.datatype().into_owned())),
            // A computed numeric knows its promoted XSD type (the type-promotion suite
            // checks `datatype(?l + ?r)` across the whole tower).
            Value::Num(n) => Value::Term(Term::NamedNode(n.datatype().into_owned())),
            Value::Bool(_) => Value::Term(Term::NamedNode(xsd::BOOLEAN.into_owned())),
            _ => Value::Error,
        },
        // CONCAT: all operands must be string literals. The result carries a language
        // tag only when every operand has the SAME tag; otherwise it is simple.
        F::Concat => {
            let mut s = String::new();
            let mut lang: Option<Option<String>> = None; // common-tag accumulator
            for i in 0..nargs {
                match str_lit(&ev(i)?) {
                    Some((p, l)) => {
                        s.push_str(&p);
                        lang = Some(match lang {
                            None => l,
                            Some(prev) if prev == l => prev,
                            Some(_) => None,
                        });
                    }
                    None => return Ok(Value::Error),
                }
            }
            lit_with_lang(s, lang.flatten().as_deref())
        }
        F::Contains => str_compat2(&ev(0)?, &ev(1)?, &|a, c| a.contains(c)),
        F::StrStarts => str_compat2(&ev(0)?, &ev(1)?, &|a, c| a.starts_with(c)),
        F::StrEnds => str_compat2(&ev(0)?, &ev(1)?, &|a, c| a.ends_with(c)),
        // STRBEFORE/STRAFTER: arguments must be compatible (second simple/xsd:string,
        // or same language tag). On a match the result carries the FIRST argument's
        // language tag; no match gives the empty simple literal.
        F::StrBefore => match (str_lit(&ev(0)?), str_lit(&ev(1)?)) {
            (Some((a, la)), Some((c, lc))) if lc.is_none() || lc == la => match a.find(&c) {
                Some(i) => lit_with_lang(a[..i].to_string(), la.as_deref()),
                None => simple(String::new()),
            },
            _ => Value::Error,
        },
        F::StrAfter => match (str_lit(&ev(0)?), str_lit(&ev(1)?)) {
            (Some((a, la)), Some((c, lc))) if lc.is_none() || lc == la => match a.find(&c) {
                Some(i) => lit_with_lang(a[i + c.len()..].to_string(), la.as_deref()),
                None => simple(String::new()),
            },
            _ => Value::Error,
        },
        F::SubStr => {
            let (s, lang) = match str_lit(&ev(0)?) {
                Some(x) => x,
                None => return Ok(Value::Error),
            };
            let start = match as_num(&ev(1)?) {
                Some(n) => n as i64,
                None => return Ok(Value::Error),
            };
            let chars: Vec<char> = s.chars().collect();
            let from = (start.max(1) - 1) as usize; // SPARQL SUBSTR is 1-indexed by codepoint
            let out: String = if nargs >= 3 {
                let len = match as_num(&ev(2)?) {
                    Some(n) => n.max(0.0) as usize,
                    None => return Ok(Value::Error),
                };
                chars.iter().skip(from).take(len).collect()
            } else {
                chars.iter().skip(from).collect()
            };
            lit_with_lang(out, lang.as_deref())
        }
        // [OPUS-4.8] ENCODE_FOR_URI's operand is a STRING LITERAL, per SPARQL 1.1
        // §17.4.3.12 `simple literal ENCODE_FOR_URI(string literal)`. A number / IRI /
        // boolean is a TYPE ERROR — the old `value_str` coercion wrongly encoded e.g.
        // `ENCODE_FOR_URI(123)` to the simple literal "123".
        F::EncodeForUri => str_lit(&ev(0)?).map(|(s, _)| simple(encode_for_uri(&s))).unwrap_or(Value::Error),
        F::Iri => match ev(0)? {
            // An IRI argument passes through unchanged.
            Value::Term(Term::NamedNode(n)) => Value::Term(Term::NamedNode(n)),
            v => match str_lit(&v) {
                // String literal: absolute IRIs pass; relative ones resolve against BASE.
                Some((s, None)) => resolve_iri(&s).map(|n| Value::Term(Term::NamedNode(n))).unwrap_or(Value::Error),
                _ => Value::Error,
            },
        },
        // [FABLE-5] (sq-qeltv) The type-test builtins take an RDF TERM: an unbound (or
        // already-errored) operand is a TYPE ERROR per SPARQL 1.1 §17.2 — so
        // `FILTER(!isIRI(?unbound))` DROPS the row (`!error` = error), where the old
        // `false` leniency kept it. Mirrors the `IsTriple` / `HasLang` arms below;
        // differential (bead): Oxigraph AND rdflib both drop the row.
        F::IsIri => match ev(0)? {
            Value::Unbound | Value::Error => Value::Error,
            v => Value::Bool(matches!(v, Value::Term(Term::NamedNode(_)))),
        },
        F::IsBlank => match ev(0)? {
            Value::Unbound | Value::Error => Value::Error,
            v => Value::Bool(matches!(v, Value::Term(Term::BlankNode(_)))),
        },
        F::IsLiteral => match ev(0)? {
            Value::Unbound | Value::Error => Value::Error,
            v => Value::Bool(matches!(v, Value::Term(Term::Literal(_)) | Value::Num(_) | Value::Bool(_))),
        },
        F::IsNumeric => match ev(0)? {
            Value::Unbound | Value::Error => Value::Error,
            Value::Num(_) => Value::Bool(true),
            Value::Term(Term::Literal(l)) => Value::Bool(is_numeric_dt(&l)),
            _ => Value::Bool(false),
        },
        // ABS/CEIL/FLOOR/ROUND preserve the argument's numeric DATATYPE
        // (CEIL("2.5"^^xsd:decimal) is "3"^^xsd:decimal, not xsd:integer).
        F::Abs => as_numeric(&ev(0)?).map(|n| Value::Num(n.abs())).unwrap_or(Value::Error),
        F::Ceil => as_numeric(&ev(0)?).map(|n| Value::Num(n.ceil())).unwrap_or(Value::Error),
        F::Floor => as_numeric(&ev(0)?).map(|n| Value::Num(n.floor())).unwrap_or(Value::Error),
        F::Round => as_numeric(&ev(0)?).map(|n| Value::Num(n.round())).unwrap_or(Value::Error),
        // STRDT(lexical, datatypeIRI) -> typed literal. The first argument must be a
        // SIMPLE literal (= xsd:string in RDF 1.1) — lang-tagged / typed input errors.
        F::StrDt => match (str_lit(&ev(0)?), ev(1)?) {
            (Some((lex, None)), Value::Term(Term::NamedNode(dt))) => {
                Value::Term(Term::Literal(Literal::new_typed_literal(lex, dt)))
            }
            _ => Value::Error,
        },
        // STRLANG(lexical, langTag) -> language-tagged literal; both arguments must be
        // simple literals.
        F::StrLang => match (str_lit(&ev(0)?), str_lit(&ev(1)?)) {
            (Some((lex, None)), Some((lang, None))) => match Literal::new_language_tagged_literal(lex, lang) {
                Ok(l) => Value::Term(Term::Literal(l)),
                Err(_) => Value::Error,
            },
            _ => Value::Error,
        },
        // LANGMATCHES(tag, range) — RFC 4647 basic filtering (`*` matches any non-empty tag).
        // [OPUS-4.8] Both operands are STRING LITERALS, per SPARQL 1.1 §17.4.3.15
        // `xsd:boolean langMatches(simple literal, simple literal)`. A number / IRI /
        // boolean operand is a TYPE ERROR — the old `value_str` coercion wrongly
        // stringified e.g. `LANGMATCHES(123, "en")` to "123" and returned `false`
        // (a value) instead of an error.
        F::LangMatches => match (str_lit(&ev(0)?), str_lit(&ev(1)?)) {
            (Some((tag, _)), Some((range, _))) => {
                let (tag, range) = (tag.to_ascii_lowercase(), range.to_ascii_lowercase());
                let m = if range == "*" {
                    !tag.is_empty()
                } else {
                    tag == range || tag.starts_with(&format!("{range}-"))
                };
                Value::Bool(m)
            }
            _ => Value::Error,
        },
        // Hash builtins: operand must be a simple literal / xsd:string; lowercase hex out.
        #[cfg(feature = "digest")]
        F::Md5 => digest_hex::<md5::Md5>(&ev(0)?),
        #[cfg(feature = "digest")]
        F::Sha1 => digest_hex::<sha1::Sha1>(&ev(0)?),
        #[cfg(feature = "digest")]
        F::Sha256 => digest_hex::<sha2::Sha256>(&ev(0)?),
        #[cfg(feature = "digest")]
        F::Sha384 => digest_hex::<sha2::Sha384>(&ev(0)?),
        #[cfg(feature = "digest")]
        F::Sha512 => digest_hex::<sha2::Sha512>(&ev(0)?),
        // TZ(xsd:dateTime) -> the timezone part of the lexical form as a simple
        // literal ("Z", "±hh:mm", or "" when absent).
        F::Tz => datetime_arg_tz(&ev(0)?).map(simple).unwrap_or(Value::Error),
        // TIMEZONE(xsd:dateTime) -> xsd:dayTimeDuration; no timezone is a type error.
        F::Timezone => match datetime_arg_tz(&ev(0)?).as_deref().and_then(tz_to_duration) {
            Some(d) => Value::Term(Term::Literal(Literal::new_typed_literal(d, xsd::DAY_TIME_DURATION))),
            None => Value::Error,
        },
        F::BNode => {
            if nargs == 0 {
                // BNODE(): a fresh blank node per call.
                static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
                let n = NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                Value::Term(Term::BlankNode(BlankNode::new_unchecked(format!("fnb{n}"))))
            } else {
                // BNODE(str): the label is derived from (solution-row scope, argument),
                // so equal arguments within ONE solution map to the same blank node and
                // everything else stays distinct (see ROW_SCOPE).
                match string_literal(&ev(0)?) {
                    Some(s) => {
                        let (scope, idx) = ROW_SCOPE.get();
                        Value::Term(Term::BlankNode(BlankNode::new_unchecked(format!(
                            "fnb{scope:x}r{idx}h{:016x}",
                            fx64(&s)
                        ))))
                    }
                    None => Value::Error,
                }
            }
        }
        // ---- Builtin memoisation policy (sq-98w7z.1) [FABLE-5] ----------------------
        // ALLOW (memoised, keyed on the argument VALUES — pure, so a hit is
        //   result-identical to a fresh evaluation): the REGEX()/REPLACE() compiled
        //   `(pattern, flags)` via `regex_cache`, the one per-row builtin cost worth a
        //   memo (compile is µs-scale vs ns-scale match). Compile FAILURES are memoised
        //   too — an invalid pattern stays a per-row type error.
        // PINNED (not memoised — spec-MANDATED constancy): NOW() formats the
        //   execution-scoped `query_now` instant (SPARQL 1.1 §17.4.5.1); the next
        //   execution re-samples.
        // DENY (non-deterministic — MUST re-evaluate on every call; memoising any of
        //   these would silently collapse per-row freshness): RAND(), UUID(), STRUUID(),
        //   no-arg BNODE() (fresh label per call), and every REGISTERED custom function
        //   (`FunctionRegistry` makes no purity promise). The freshness-per-row test is
        //   `nondeterministic_builtins_fresh_per_call_never_memoised`.
        // Everything else (UCASE, STR, numeric ops, …) evaluates directly: value-keyed
        // memoisation of ns-scale pure builtins costs more in key hashing than it saves.
        //
        // NOW(): the execution's pinned instant as xsd:dateTime. RAND(): xsd:double in
        // [0, 1) from a per-thread splitmix64 seeded once from the OS RNG (see
        // `rand_unit`) — both native-only for the same reason as UUID()/STRUUID().
        #[cfg(not(target_arch = "wasm32"))]
        F::Now => Value::Term(Term::Literal(Literal::new_typed_literal(now_lexical(), xsd::DATE_TIME))),
        #[cfg(not(target_arch = "wasm32"))]
        F::Rand => Value::Num(Num::Double(rand_unit::next())),
        #[cfg(not(target_arch = "wasm32"))]
        F::Uuid => Value::Term(Term::NamedNode(oxrdf::NamedNode::new_unchecked(format!(
            "urn:uuid:{}",
            uuid::Uuid::new_v4()
        )))),
        #[cfg(not(target_arch = "wasm32"))]
        F::StrUuid => simple(uuid::Uuid::new_v4().to_string()),
        // xsd:dateTime accessors — parse the lexical form and return the numeric component.
        F::Year => datetime_field(&ev(0)?, 0),
        F::Month => datetime_field(&ev(0)?, 1),
        F::Day => datetime_field(&ev(0)?, 2),
        F::Hours => datetime_field(&ev(0)?, 3),
        F::Minutes => datetime_field(&ev(0)?, 4),
        F::Seconds => datetime_field(&ev(0)?, 5),
        // REGEX/REPLACE: the text operand must be a string literal (an IRI or non-string
        // literal is a type error); REPLACE's result keeps the text's language tag.
        #[cfg(feature = "regex")]
        F::Regex => {
            let (text, pat) = match (str_lit(&ev(0)?), value_str(&ev(1)?)) {
                (Some((t, _)), Some(p)) => (t, p),
                _ => return Ok(Value::Error),
            };
            let flags = if nargs >= 3 { value_str(&ev(2)?).unwrap_or_default() } else { String::new() };
            match regex_cache::get(&pat, &flags) {
                Some(re) => Value::Bool(re.is_match(&text)),
                None => Value::Error,
            }
        }
        #[cfg(feature = "regex")]
        F::Replace => {
            let (text, lang, pat, rep) = match (str_lit(&ev(0)?), value_str(&ev(1)?), value_str(&ev(2)?)) {
                (Some((t, lang)), Some(p), Some(r)) => (t, lang, p, r),
                _ => return Ok(Value::Error),
            };
            let flags = if nargs >= 4 { value_str(&ev(3)?).unwrap_or_default() } else { String::new() };
            match regex_cache::get(&pat, &flags) {
                Some(re) => lit_with_lang(re.replace_all(&text, rep.as_str()).into_owned(), lang.as_deref()),
                None => Value::Error,
            }
        }
        // ---- SPARQL 1.2 triple-term builtins ------------------------------------
        // TRIPLE(s, p, o): s must be an IRI / blank node, p an IRI, o any RDF term.
        F::Triple => {
            let subject = match ev(0)? {
                Value::Term(Term::NamedNode(n)) => NamedOrBlankNode::NamedNode(n),
                Value::Term(Term::BlankNode(b)) => NamedOrBlankNode::BlankNode(b),
                _ => return Ok(Value::Error),
            };
            let predicate = match ev(1)? {
                Value::Term(Term::NamedNode(n)) => n,
                _ => return Ok(Value::Error),
            };
            let Some(object) = value_as_term(&ev(2)?) else {
                return Ok(Value::Error);
            };
            Value::Term(Term::Triple(Box::new(oxrdf::Triple::new(subject, predicate, object))))
        }
        F::IsTriple => match ev(0)? {
            Value::Term(Term::Triple(_)) => Value::Bool(true),
            Value::Unbound | Value::Error => Value::Error,
            _ => Value::Bool(false),
        },
        F::Subject => match ev(0)? {
            Value::Term(Term::Triple(t)) => Value::Term(match t.subject {
                NamedOrBlankNode::NamedNode(n) => Term::NamedNode(n),
                NamedOrBlankNode::BlankNode(b) => Term::BlankNode(b),
            }),
            _ => Value::Error,
        },
        F::Predicate => match ev(0)? {
            Value::Term(Term::Triple(t)) => Value::Term(Term::NamedNode(t.predicate)),
            _ => Value::Error,
        },
        F::Object => match ev(0)? {
            Value::Term(Term::Triple(t)) => Value::Term(t.object),
            _ => Value::Error,
        },
        // ---- SPARQL 1.2 language / base-direction builtins -----------------------
        // hasLANG / hasLANGDIR: a boolean property of any RDF TERM (an IRI is simply
        // `false`); only unbound/error operands propagate the error.
        F::HasLang => match ev(0)? {
            Value::Term(Term::Literal(l)) => Value::Bool(l.language().is_some()),
            Value::Unbound | Value::Error => Value::Error,
            _ => Value::Bool(false),
        },
        F::HasLangDir => match ev(0)? {
            Value::Term(Term::Literal(l)) => Value::Bool(l.direction().is_some()),
            Value::Unbound | Value::Error => Value::Error,
            _ => Value::Bool(false),
        },
        // LANGDIR mirrors LANG: "" for a literal without a base direction, type error
        // on non-literals.
        F::LangDir => match ev(0)? {
            Value::Term(Term::Literal(l)) => simple(l.direction().map(|d| d.to_string()).unwrap_or_default()),
            Value::Num(_) | Value::Bool(_) => simple(String::new()),
            _ => Value::Error,
        },
        // STRLANGDIR(lexical, langTag, "ltr"|"rtl") -> directional language-tagged
        // literal; all three must be simple literals, the tag non-empty and valid,
        // the direction exactly lowercase "ltr"/"rtl".
        F::StrLangDir => match (str_lit(&ev(0)?), str_lit(&ev(1)?), str_lit(&ev(2)?)) {
            (Some((lex, None)), Some((lang, None)), Some((dir, None))) => {
                let dir = match dir.as_str() {
                    "ltr" => oxrdf::BaseDirection::Ltr,
                    "rtl" => oxrdf::BaseDirection::Rtl,
                    _ => return Ok(Value::Error),
                };
                match Literal::new_directional_language_tagged_literal(lex, lang, dir) {
                    Ok(l) => Value::Term(Term::Literal(l)),
                    Err(_) => Value::Error,
                }
            }
            _ => Value::Error,
        },
        // XSD constructor casts: xsd:integer(?x), xsd:decimal(?x), … (SPARQL 17.5),
        // then the installed extension-function registry (SPARQL 17.6; see
        // `query_with_functions` / `with_functions` in lib.rs). An IRI that is
        // neither stays the same hard query error as before the registry existed.
        F::Custom(nn) => {
            // [OPUS-4.8] (sq-v411r, survey §B2) MULTIPLICITY(): the SPARQL 1.2 algebra's
            // `multiplicity` device, parsed as the reserved-IRI `Function::Custom` so the
            // shared enum stays byte-compatible downstream. Inside an aggregate argument it
            // is the bag cardinality (`xsd:integer`) of the current group member's solution
            // within its group multiset, so `SUM(?x * MULTIPLICITY())` is the multiset-
            // weighted sum. The evaluator installs the per-member value before each
            // `eval_expr`; OUTSIDE an aggregate the context is absent and the call is an
            // expression error (only meaningful over a multiset). Checked BEFORE the cast /
            // registry so the reserved IRI can never be shadowed. NOT a W3C-standard
            // callable builtin — see the README.
            if nargs == 0 && nn.as_str() == MULTIPLICITY_FN_IRI {
                return Ok(match multiplicity::current() {
                    Some(card) => Value::Num(Num::Int(card as i64)),
                    None => Value::Error,
                });
            }
            let mut vals = Vec::with_capacity(nargs);
            for i in 0..nargs {
                vals.push(ev(i)?);
            }
            if vals.len() == 1 {
                if let Some(out) = eval_cast(nn.as_str(), &vals[0]) {
                    return Ok(out);
                }
            }
            if let Some(f) = functions::lookup(nn.as_str()) {
                // Arguments are materialised as concrete RDF terms; an unbound or
                // errored argument is an expression ERROR (row filtered / BIND
                // unbound), exactly like the builtins. The extension returning
                // `Err` (wrong arity, bad lexical, …) is the same expression
                // error — per-row, never a hard query error.
                let mut terms = Vec::with_capacity(vals.len());
                for v in &vals {
                    match value_as_term(v) {
                        Some(t) => terms.push(t),
                        None => return Ok(Value::Error),
                    }
                }
                return Ok(match f(&terms) {
                    Ok(t) => Value::Term(t),
                    Err(_) => Value::Error,
                });
            }
            return Err(format!("unsupported SPARQL function: Custom({})", nn.as_str()));
        }
        // With every default feature on, the arms above are exhaustive (the
        // `F::Custom` arm is no longer guarded on arity); this arm is reached
        // only when the feature-gated builtins (regex / digest / native-only
        // UUID) are compiled out — i.e. the wasm build.
        #[allow(unreachable_patterns)]
        other => return Err(format!("unsupported SPARQL function: {other:?}")),
    })
}

/// Thin wrapper — the hot inner body lives in [`eval_function_inner`]. [OPUS-4.8] sq-7d3dj.4.
fn eval_function(
    graph: &Graph,
    local: &LocalVocab,
    b: &Bindings,
    row: &[Id],
    f: &spargebra::algebra::Function,
    args: &[Expression],
) -> Result<Value, String> {
    eval_function_inner(f, args.len(), |i| eval_expr(graph, local, b, row, &args[i]))
}

// ── Compiled comparison / arithmetic helpers (sq-7d3dj.4) ───────────────────────────────
// Mirrors of `cmp_expr` / `equal_expr` / `arith` for [`CompiledExpr`].
// All `Var` accesses are pre-resolved column indices; no `b.col(v)` per row.
// [OPUS-4.8] sq-7d3dj.4

fn cmp_compiled(
    graph: &Graph,
    local: &LocalVocab,
    b: &Bindings,
    row: &[Id],
    a: &CompiledExpr,
    c: &CompiledExpr,
    f: impl Fn(Ordering) -> bool,
) -> Result<Value, String> {
    if compiled_expr_has_arith(a) || compiled_expr_has_arith(c) {
        if let (Some(da), Some(db)) =
            (eval_compiled_dec(graph, local, row, a), eval_compiled_dec(graph, local, row, c))
        {
            if let Some(o) = da.cmp(db) {
                return Ok(Value::Bool(f(o)));
            }
        }
    }
    if let (Some(x), Some(y)) =
        (eval_compiled_numeric(graph, local, row, a), eval_compiled_numeric(graph, local, row, c))
    {
        if x == y {
            if let (Some(la), Some(lb)) = (
                eval_compiled_exact_lexical(graph, local, row, a),
                eval_compiled_exact_lexical(graph, local, row, c),
            ) {
                if let Some(ord) = cmp_decimal_str(&la, &lb) {
                    return Ok(Value::Bool(f(ord)));
                }
            }
        }
        return Ok(Value::Bool(x.partial_cmp(&y).map(&f).unwrap_or(false)));
    }
    if let (Some(ta), Some(tb)) =
        (eval_compiled_temporal(graph, local, row, a), eval_compiled_temporal(graph, local, row, c))
    {
        return Ok(match Temporal::cmp_t(ta, tb) {
            Some(o) => Value::Bool(f(o)),
            None => Value::Error,
        });
    }
    let (x, y) = (eval_compiled(graph, local, b, row, a)?, eval_compiled(graph, local, b, row, c)?);
    Ok(match value_compare_strict(&x, &y) {
        Some(o) => Value::Bool(f(o)),
        None => Value::Error,
    })
}

/// [FABLE-5] (sq-7d3dj.30.11) The single RAW ID an operand resolves to, if it is a bound column
/// or a constant IRI — else `None` (arithmetic, function call, literal cast, unbound column).
/// A constant IRI absent from the dictionary yields `NO_ID`, which never equals a bound id.
#[cfg(feature = "id-filter-fastpath")]
#[inline]
fn operand_single_id(graph: &Graph, row: &[Id], e: &CompiledExpr) -> Option<Id> {
    match e {
        CompiledExpr::Var(Some(c)) => Some(row[*c]),
        CompiledExpr::NamedNode(n) => Some(graph.id_of(&Term::NamedNode(n.clone())).unwrap_or(NO_ID)),
        _ => None,
    }
}

/// [FABLE-5] (sq-7d3dj.30.11) Evaluates `=` between two STATICALLY NON-LITERAL operands by raw-id
/// (in)equality. Both operands are IRI/bnode (or absent-const → `NO_ID`); the canonicalising dict
/// gives each such term one id, so `=` is id equality — result-identical to the general path (which
/// decides IRI/bnode pairs by `p == q` term identity). An UNBOUND operand (`NO_ID` FROM A COLUMN)
/// is a type error, exactly as the exact path treats an unbound variable. A constant-IRI operand is
/// never unbound; its `NO_ID` (IRI absent from the dict) legitimately means "never equal".
#[cfg(feature = "id-filter-fastpath")]
#[inline]
fn equal_idfast(graph: &Graph, row: &[Id], a: &IdOperand, c: &IdOperand) -> Value {
    let resolve = |op: &IdOperand| -> (Id, bool) {
        match op {
            // A column can be unbound (NO_ID); that is a type error in `=`.
            IdOperand::Col(col) => (row[*col], true),
            // A constant IRI is always "bound"; NO_ID here means the IRI is not in the dict.
            IdOperand::ConstIri(n) => (graph.id_of(&Term::NamedNode(n.clone())).unwrap_or(NO_ID), false),
        }
    };
    let (ida, from_col_a) = resolve(a);
    let (idc, from_col_c) = resolve(c);
    if (from_col_a && ida == NO_ID) || (from_col_c && idc == NO_ID) {
        return Value::Error; // unbound operand -> type error (matches the exact path)
    }
    Value::Bool(ida == idc)
}

fn equal_compiled(
    graph: &Graph,
    local: &LocalVocab,
    b: &Bindings,
    row: &[Id],
    a: &CompiledExpr,
    c: &CompiledExpr,
) -> Result<Value, String> {
    // [FABLE-5] (sq-7d3dj.30.11) Fast path (b): EQUAL ids of ANY kind are the SAME term (the
    // canonicalising dict gives each term one id), so `=` is `true` — mirroring the `p == q`
    // sameTerm short-circuit `values_equal` takes today, which is safe even for ill-typed
    // literals (sameTerm returns a boolean, never a type error). Requires both operands to be
    // single-id terms and BOTH bound (an unbound `NO_ID` column would be a type error, not
    // equal). UNEQUAL ids fall through to the exact path unchanged — crucially, unequal ids of
    // value-equal literals (`"1"^^integer` = `"1.0"^^decimal`, sq-lr2ii) must NOT be decided here.
    #[cfg(feature = "id-filter-fastpath")]
    if let (Some(ida), Some(idc)) = (operand_single_id(graph, row, a), operand_single_id(graph, row, c)) {
        if ida != NO_ID && ida == idc {
            return Ok(Value::Bool(true));
        }
    }
    if compiled_expr_has_arith(a) || compiled_expr_has_arith(c) {
        if let (Some(da), Some(db)) =
            (eval_compiled_dec(graph, local, row, a), eval_compiled_dec(graph, local, row, c))
        {
            if let Some(o) = da.cmp(db) {
                return Ok(Value::Bool(o == Ordering::Equal));
            }
        }
    }
    if let (Some(x), Some(y)) =
        (eval_compiled_numeric(graph, local, row, a), eval_compiled_numeric(graph, local, row, c))
    {
        if x == y {
            if let (Some(la), Some(lb)) = (
                eval_compiled_exact_lexical(graph, local, row, a),
                eval_compiled_exact_lexical(graph, local, row, c),
            ) {
                if let Some(ord) = cmp_decimal_str(&la, &lb) {
                    return Ok(Value::Bool(ord == Ordering::Equal));
                }
            }
        }
        return Ok(Value::Bool(x == y));
    }
    if let (Some(ta), Some(tb)) =
        (eval_compiled_temporal(graph, local, row, a), eval_compiled_temporal(graph, local, row, c))
    {
        if ta.kind != tb.kind {
            return Ok(Value::Bool(false));
        }
        return Ok(match Temporal::cmp_t(ta, tb) {
            Some(o) => Value::Bool(o == Ordering::Equal),
            None => Value::Error,
        });
    }
    let (x, y) = (eval_compiled(graph, local, b, row, a)?, eval_compiled(graph, local, b, row, c)?);
    Ok(match values_equal(&x, &y) {
        Some(eq) => Value::Bool(eq),
        None => Value::Error,
    })
}

fn arith_compiled(
    graph: &Graph,
    local: &LocalVocab,
    b: &Bindings,
    row: &[Id],
    a: &CompiledExpr,
    c: &CompiledExpr,
    op: ArithOp,
) -> Result<Value, String> {
    let (x, y) = (eval_compiled(graph, local, b, row, a)?, eval_compiled(graph, local, b, row, c)?);
    Ok(match (as_numeric(&x), as_numeric(&y)) {
        (Some(p), Some(q)) => p.binop(q, op).map(Value::Num).unwrap_or(Value::Error),
        _ => Value::Error,
    })
}

/// Per-row expression evaluator with all `Variable`/`Bound` nodes pre-resolved to column
/// indices. Call [`compile_expr`] once before the row loop; `b` is passed only for the
/// `EXISTS` arm (rare). [OPUS-4.8] sq-7d3dj.4.
fn eval_compiled(
    graph: &Graph,
    local: &LocalVocab,
    b: &Bindings,
    row: &[Id],
    e: &CompiledExpr,
) -> Result<Value, String> {
    use CompiledExpr::*;
    match e {
        Var(col) => match col {
            Some(c) if row[*c] != NO_ID => Ok(Value::Term(term_of(graph, local, row[*c]).unwrap())),
            _ => Ok(Value::Unbound),
        },
        BoundCol(col) => Ok(Value::Bool(col.map(|c| row[c] != NO_ID).unwrap_or(false))),
        NamedNode(n) => Ok(Value::Term(Term::NamedNode(n.clone()))),
        Literal(l) => Ok(Value::Term(Term::Literal(l.clone()))),
        And(a, c) => {
            let x = ebv3(&eval_compiled(graph, local, b, row, a)?);
            if x == Some(false) {
                return Ok(Value::Bool(false));
            }
            let y = ebv3(&eval_compiled(graph, local, b, row, c)?);
            Ok(and3(x, y))
        }
        Or(a, c) => {
            let x = ebv3(&eval_compiled(graph, local, b, row, a)?);
            if x == Some(true) {
                return Ok(Value::Bool(true));
            }
            let y = ebv3(&eval_compiled(graph, local, b, row, c)?);
            Ok(or3(x, y))
        }
        Not(a) => Ok(match ebv3(&eval_compiled(graph, local, b, row, a)?) {
            Some(v) => Value::Bool(!v),
            None => Value::Error,
        }),
        Equal(a, c) => equal_compiled(graph, local, b, row, a, c),
        #[cfg(feature = "id-filter-fastpath")]
        IdEqNonLit(a, c) => Ok(equal_idfast(graph, row, a, c)),
        SameTerm(a, c) => {
            let (x, y) = (eval_compiled(graph, local, b, row, a)?, eval_compiled(graph, local, b, row, c)?);
            Ok(Value::Bool(matches!((&x, &y), (Value::Term(p), Value::Term(q)) if p == q)))
        }
        Greater(a, c) => cmp_compiled(graph, local, b, row, a, c, |o| o == Ordering::Greater),
        GreaterOrEqual(a, c) => cmp_compiled(graph, local, b, row, a, c, |o| o != Ordering::Less),
        Less(a, c) => cmp_compiled(graph, local, b, row, a, c, |o| o == Ordering::Less),
        LessOrEqual(a, c) => cmp_compiled(graph, local, b, row, a, c, |o| o != Ordering::Greater),
        Add(a, c) => arith_compiled(graph, local, b, row, a, c, ArithOp::Add),
        Subtract(a, c) => arith_compiled(graph, local, b, row, a, c, ArithOp::Sub),
        Multiply(a, c) => arith_compiled(graph, local, b, row, a, c, ArithOp::Mul),
        Divide(a, c) => arith_compiled(graph, local, b, row, a, c, ArithOp::Div),
        UnaryPlus(a) => eval_compiled(graph, local, b, row, a),
        UnaryMinus(a) => {
            let v = eval_compiled(graph, local, b, row, a)?;
            Ok(as_numeric(&v).map(|n| Value::Num(n.neg())).unwrap_or(Value::Error))
        }
        If(cond, t, f) => match ebv3(&eval_compiled(graph, local, b, row, cond)?) {
            Some(true) => eval_compiled(graph, local, b, row, t),
            Some(false) => eval_compiled(graph, local, b, row, f),
            None => Ok(Value::Error),
        },
        Coalesce(es) => {
            for ce in es {
                let v = eval_compiled(graph, local, b, row, ce)?;
                if !matches!(v, Value::Unbound | Value::Error) {
                    return Ok(v);
                }
            }
            Ok(Value::Unbound)
        }
        In(a, list) => {
            let x = eval_compiled(graph, local, b, row, a)?;
            let mut errored = false;
            for c in list {
                let y = eval_compiled(graph, local, b, row, c)?;
                match values_equal(&x, &y) {
                    Some(true) => return Ok(Value::Bool(true)),
                    Some(false) => {}
                    None => errored = true,
                }
            }
            Ok(if errored { Value::Error } else { Value::Bool(false) })
        }
        FunctionCall(f, args) => {
            eval_function_inner(f, args.len(), |i| eval_compiled(graph, local, b, row, &args[i]))
        }
        Exists(inner) => Ok(Value::Bool(eval_exists(graph, local, b, row, inner)?)),
    }
}

/// Plain decimal form of an f64 with at least one fraction digit ("0.0", "1.0",
/// "1.25") — the form the W3C cast expected-results use for float/double sources.
fn plain_min1(f: f64) -> String {
    if f.fract() == 0.0 && f.abs() < 1e15 {
        format!("{:.1}", f)
    } else {
        format!("{f}")
    }
}

/// A decimal lexical with trailing fraction zeros trimmed but AT LEAST one fraction
/// digit kept ("33.3300" -> "33.33", "0" -> "0.0") — the xsd:decimal cast convention.
fn dec_trim_min1(d: Dec) -> String {
    let mut d = d;
    while d.scale > 1 && d.mant % 10 == 0 {
        d.mant /= 10;
        d.scale -= 1;
    }
    if d.scale == 0 {
        d = Dec { mant: d.mant.saturating_mul(10), scale: 1 };
    }
    d.lexical()
}

/// Trim ALL trailing fraction zeros ("0.0" -> "0", "2.50" -> "2.5") — the xsd:string
/// cast convention for decimal sources.
fn dec_trim(d: Dec) -> String {
    let mut d = d;
    while d.scale > 0 && d.mant % 10 == 0 {
        d.mant /= 10;
        d.scale -= 1;
    }
    d.lexical()
}

/// The XSD constructor-cast table. `None` when `target` is not a recognised cast IRI
/// (the caller reports an unsupported function); `Some(Value::Error)` for a cast that
/// fails per XPath (invalid source lexical, wrong source type, NaN/INF to exact types).
/// The result LEXICAL forms follow the conventions of the W3C cast test expected
/// results (which track the reference implementations), varying by source type.
fn eval_cast(target: &str, v: &Value) -> Option<Value> {
    // The source as a STRING lexical only when it is a simple/xsd:string literal
    // (language-tagged literals and non-string types are NOT castable as strings).
    let src_str = || match v {
        Value::Term(Term::Literal(l)) if l.language().is_none() && l.datatype() == xsd::STRING => {
            Some(l.value().trim().to_string())
        }
        _ => None,
    };
    let typed = |lex: String, dt: oxrdf::NamedNodeRef<'_>| Value::Term(Term::Literal(Literal::new_typed_literal(lex, dt)));
    // Classify a numeric SOURCE by its tower type (computed value or literal).
    let src_num = || as_numeric(v).filter(|_| !matches!(v, Value::Bool(_)));
    if target == xsd::STRING.as_str() {
        // STR semantics with VALUE canonicalisation for typed sources: booleans print
        // true/false, decimals trim trailing zeros ("0.0" -> "0"), float/double print
        // plain when integral ("0E1" -> "0") — everything else keeps its lexical.
        if let Some(b) = as_bool_val(v) {
            return Some(typed(b.to_string(), xsd::STRING));
        }
        if let Some(n) = src_num() {
            let s = match n {
                Num::Int(i) => i.to_string(),
                Num::Dec(d) => dec_trim(d),
                // plain shortest decimal form, never scientific ("0E1" -> "0",
                // "1.25"^^xsd:float -> "1.25")
                Num::Float(f) if f.is_finite() => format!("{f}"),
                Num::Double(f) if f.is_finite() => format!("{f}"),
                other => other.lexical(),
            };
            return Some(typed(s, xsd::STRING));
        }
        return Some(match v {
            Value::Term(Term::BlankNode(_)) | Value::Term(Term::Triple(_)) | Value::Unbound | Value::Error => Value::Error,
            other => value_str(other).map(|s| typed(s, xsd::STRING)).unwrap_or(Value::Error),
        });
    }
    if target == xsd::BOOLEAN.as_str() {
        if let Some(b) = as_bool_val(v) {
            return Some(Value::Bool(b));
        }
        if let Some(n) = as_numeric(v) {
            return Some(Value::Bool(!n.is_zero() && !n.is_nan()));
        }
        return Some(match src_str().as_deref() {
            Some("true") | Some("1") => Value::Bool(true),
            Some("false") | Some("0") => Value::Bool(false),
            _ => Value::Error,
        });
    }
    if target == xsd::DATE_TIME.as_str() {
        return Some(match v {
            Value::Term(Term::Literal(l))
                if l.datatype() == xsd::DATE_TIME || l.datatype() == xsd::DATE_TIME_STAMP =>
            {
                typed(l.value().to_string(), xsd::DATE_TIME)
            }
            _ => match src_str() {
                Some(s) if parse_datetime(&s).is_some() => typed(s, xsd::DATE_TIME),
                _ => Value::Error,
            },
        });
    }
    let is_int = target == xsd::INTEGER.as_str();
    let is_dec = target == xsd::DECIMAL.as_str();
    let is_flt = target == xsd::FLOAT.as_str();
    let is_dbl = target == xsd::DOUBLE.as_str();
    if !(is_int || is_dec || is_flt || is_dbl) {
        return None; // not a cast IRI this engine knows
    }
    if is_int {
        // Truncate toward zero; strings must be valid xsd:integer lexicals.
        if let Some(b) = as_bool_val(v) {
            return Some(Value::Num(Num::Int(b as i64)));
        }
        if let Some(n) = src_num() {
            return Some(match n {
                Num::Int(i) => Value::Num(Num::Int(i)),
                Num::Dec(d) => Value::Num(Num::Int((d.mant / 10i128.pow(d.scale)) as i64)),
                Num::Float(_) | Num::Double(_) => {
                    let f = n.f64();
                    if f.is_finite() && f.abs() < 9.2e18 {
                        Value::Num(Num::Int(f.trunc() as i64))
                    } else {
                        Value::Error
                    }
                }
            });
        }
        return Some(src_str().and_then(|s| s.parse::<i64>().ok()).map(|i| Value::Num(Num::Int(i))).unwrap_or(Value::Error));
    }
    if is_dec {
        if let Some(b) = as_bool_val(v) {
            return Some(typed(if b { "1.0" } else { "0.0" }.to_string(), xsd::DECIMAL));
        }
        if let Some(n) = src_num() {
            return Some(match n {
                // integer -> N.0 (zero prints bare, per the reference results)
                Num::Int(0) => typed("0".to_string(), xsd::DECIMAL),
                Num::Int(i) => typed(format!("{i}.0"), xsd::DECIMAL),
                // decimal -> decimal keeps its lexical
                Num::Dec(d) => typed(d.lexical(), xsd::DECIMAL),
                Num::Float(_) | Num::Double(_) => {
                    let f = n.f64();
                    if f.is_finite() {
                        typed(plain_min1(f), xsd::DECIMAL)
                    } else {
                        Value::Error
                    }
                }
            });
        }
        // string -> parse (no exponent allowed), trim trailing zeros, keep >= 1
        // fraction digit ("+33.3300" -> "33.33", "0" -> "0.0").
        return Some(
            src_str()
                .and_then(|s| Dec::parse_lexical(&s))
                .map(|d| typed(dec_trim_min1(d), xsd::DECIMAL))
                .unwrap_or(Value::Error),
        );
    }
    // float / double
    let dt = if is_flt { xsd::FLOAT } else { xsd::DOUBLE };
    if let Some(b) = as_bool_val(v) {
        return Some(typed(if b { "1.0E0" } else { "0E0" }.to_string(), dt));
    }
    if let Some(n) = src_num() {
        return Some(match n {
            // integer -> N.0 (zero prints bare)
            Num::Int(0) => typed("0".to_string(), dt),
            Num::Int(i) => typed(format!("{i}.0"), dt),
            // decimal -> keeps its lexical
            Num::Dec(d) => typed(d.lexical(), dt),
            // float/double -> plain decimal form with >= 1 fraction digit
            Num::Float(f) => typed(plain_min1(f as f64), dt),
            Num::Double(f) => typed(plain_min1(f), dt),
        });
    }
    Some(match src_str() {
        Some(s) => {
            // A valid integer lexical keeps its form verbatim ("13" -> "13"^^xsd:double);
            // anything else parses and serialises in canonical scientific form.
            if s.parse::<i64>().is_ok() {
                typed(s, dt)
            } else if is_flt {
                match parse_xsd_f32(&s) {
                    Some(f) if !f.is_nan() || s == "NaN" => typed(if f.is_finite() { format!("{f:E}") } else { Num::Float(f).lexical() }, dt),
                    _ => Value::Error,
                }
            } else {
                match parse_xsd_f64(&s) {
                    Some(f) if !f.is_nan() || s == "NaN" => typed(if f.is_finite() { format!("{f:E}") } else { Num::Double(f).lexical() }, dt),
                    _ => Value::Error,
                }
            }
        }
        None => Value::Error,
    })
}

thread_local! {
    /// The query's BASE IRI (when declared), used by IRI()/URI() to resolve relative
    /// references. Set by the `lib.rs` query entry points after parsing.
    static QUERY_BASE: std::cell::RefCell<Option<oxiri::Iri<String>>> = const { std::cell::RefCell::new(None) };
}

/// Installs the active query's base IRI for expression evaluation (IRI()/URI()
/// relative-reference resolution). Called by the query entry points; `None` clears it.
pub(crate) fn set_query_base(base: Option<&str>) {
    QUERY_BASE.with(|b| *b.borrow_mut() = base.and_then(|s| oxiri::Iri::parse(s.to_string()).ok()));
}

/// `IRI(str)`: absolute IRIs pass through; relative references resolve against the
/// query's BASE (a relative reference without a base is a type error).
fn resolve_iri(s: &str) -> Option<oxrdf::NamedNode> {
    if let Ok(abs) = oxiri::Iri::parse(s.to_string()) {
        return Some(oxrdf::NamedNode::new_unchecked(abs.into_inner()));
    }
    QUERY_BASE.with(|b| {
        b.borrow()
            .as_ref()
            .and_then(|base| base.resolve(s).ok())
            .map(|iri| oxrdf::NamedNode::new_unchecked(iri.into_inner()))
    })
}

thread_local! {
    /// The identity of the solution row an expression is being evaluated for:
    /// (bindings identity — the rows buffer address —, row index). Set by the per-row
    /// evaluation loops (BIND / FILTER); BNODE(str) derives its label from it, so equal
    /// arguments within one solution share a blank node while distinct solutions get
    /// distinct ones. The buffer address is stable across consecutive Extends over the
    /// same Bindings (the SELECT-expression case the per-solution rule exists for).
    static ROW_SCOPE: std::cell::Cell<(usize, usize)> = const { std::cell::Cell::new((0, 0)) };
}

/// The query execution's `NOW()` instant as an `xsd:dateTime` lexical (civil-from-days
/// conversion, no time-crate dependency). The instant comes from the `query_now`
/// scope pinned in `eval_modified`, so every `NOW()` in one execution — across rows,
/// rayon workers and `EXISTS` re-entry — formats the SAME value (SPARQL 1.1
/// §17.4.5.1); an un-scoped call falls back to a fresh sample. [FABLE-5] sq-98w7z.1
#[cfg(not(target_arch = "wasm32"))]
fn now_lexical() -> String {
    let secs = query_now::epoch_secs();
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (h, mi, s) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    // Howard Hinnant's civil_from_days.
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if month <= 2 { y + 1 } else { y };
    format!("{year:04}-{month:02}-{day:02}T{h:02}:{mi:02}:{s:02}Z")
}

/// Thread-local PRNG behind `RAND()` (sq-98w7z.1). [FABLE-5]
///
/// The old arm drew `uuid::Uuid::new_v4()` — an OS-RNG syscall — PER ROW. SPARQL
/// `RAND()` (§17.4.5.2) has no cryptographic requirement, only "a fresh value per
/// call", so each thread seeds ONCE from the OS RNG (uuid v4, the crate's existing
/// entropy source — no new dependency) and then advances a splitmix64 state: every
/// call still yields a fresh, non-deterministic value (the seed is fresh entropy
/// per thread per process), rayon workers get independent streams, and `EXISTS`
/// re-entry merely draws the next value — there is no layout- or query-dependent
/// state to leak. Deliberately NOT deterministic or query-constant.
#[cfg(not(target_arch = "wasm32"))]
mod rand_unit {
    use std::cell::Cell;

    thread_local! {
        static STATE: Cell<u64> = Cell::new(u64::from_le_bytes(
            uuid::Uuid::new_v4().as_bytes()[..8].try_into().expect("8 bytes"),
        ));
    }

    /// The next value in `[0, 1)` — splitmix64 output through the same 53-bit
    /// mantissa construction the old per-row OS draw used.
    pub(super) fn next() -> f64 {
        STATE.with(|s| {
            let seed = s.get().wrapping_add(0x9E37_79B9_7F4A_7C15);
            s.set(seed);
            let mut z = seed;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^= z >> 31;
            (z >> 11) as f64 / (1u64 << 53) as f64
        })
    }
}

/// 64-bit FxHash of a string (label material for BNODE(str)).
fn fx64(s: &str) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut h = rustc_hash::FxHasher::default();
    s.hash(&mut h);
    h.finish()
}

/// The string value of a simple literal / xsd:string argument — the only operand type
/// the hash builtins and BNODE(str) accept; anything else is a type error (`None`).
fn string_literal(v: &Value) -> Option<String> {
    match v {
        Value::Term(Term::Literal(l)) if l.language().is_none() && l.datatype() == xsd::STRING => {
            Some(l.value().to_string())
        }
        _ => None,
    }
}

/// A STRING-LITERAL operand (simple/xsd:string or language-tagged): `(value, language)`.
/// IRIs, blank nodes, non-string literals and computed numerics/booleans are type
/// errors (`None`) — per the SPARQL string-function operand rules.
///
/// An RDF 1.2 base direction rides COMBINED into the language slot as `lang--dir`
/// (`--` cannot occur in a BCP47 tag): the string functions then preserve language AND
/// direction together, equality of the slot means "same language and same direction"
/// (exactly the SPARQL 1.2 CONCAT/compatibility rule), and [`lit_with_lang`] splits the
/// pair back out.
fn str_lit(v: &Value) -> Option<(String, Option<String>)> {
    match v {
        Value::Term(Term::Literal(l)) => {
            if let Some(lang) = l.language() {
                let tag = match l.direction() {
                    Some(d) => format!("{lang}--{d}"),
                    None => lang.to_string(),
                };
                Some((l.value().to_string(), Some(tag)))
            } else if l.datatype() == xsd::STRING {
                Some((l.value().to_string(), None))
            } else {
                None
            }
        }
        _ => None,
    }
}

/// A simple or language-tagged literal value, per the (possibly `lang--dir` combined,
/// see [`str_lit`]) tag the operand carried.
fn lit_with_lang(s: String, lang: Option<&str>) -> Value {
    Value::Term(Term::Literal(match lang {
        Some(l) => match l.split_once("--") {
            Some((tag, dir)) => Literal::new_directional_language_tagged_literal_unchecked(
                s,
                tag,
                if dir == "rtl" { oxrdf::BaseDirection::Rtl } else { oxrdf::BaseDirection::Ltr },
            ),
            None => Literal::new_language_tagged_literal_unchecked(s, l),
        },
        None => Literal::new_simple_literal(s),
    }))
}

/// Lowercase-hex digest of a string-literal argument, or a type error.
#[cfg(feature = "digest")]
fn digest_hex<D: md5::Digest>(v: &Value) -> Value {
    use std::fmt::Write;
    match string_literal(v) {
        Some(s) => {
            let out = D::digest(s.as_bytes());
            let mut hex = String::with_capacity(out.len() * 2);
            for byte in out {
                let _ = write!(hex, "{byte:02x}");
            }
            Value::Term(Term::Literal(Literal::new_simple_literal(hex)))
        }
        None => Value::Error,
    }
}

/// The timezone part of an xsd:dateTime argument's lexical form: `"Z"`, `"±hh:mm"`, or
/// `""` when absent. `None` (type error) when the argument is not a valid xsd:dateTime.
fn datetime_arg_tz(v: &Value) -> Option<String> {
    let l = match v {
        Value::Term(Term::Literal(l))
            if l.datatype() == xsd::DATE_TIME || l.datatype() == xsd::DATE_TIME_STAMP =>
        {
            l
        }
        _ => return None,
    };
    let s = l.value();
    parse_datetime(s)?; // lexical shape check
    let (_, time) = s.split_once('T')?;
    Some(match time.find(['Z', '+', '-']) {
        Some(i) => time[i..].to_string(),
        None => String::new(),
    })
}

/// XSD-canonical `xsd:dayTimeDuration` for a timezone string (`Z` / `±hh:mm`); an empty
/// timezone is a type error (`None`).
fn tz_to_duration(tz: &str) -> Option<String> {
    if tz.is_empty() {
        return None;
    }
    if tz == "Z" {
        return Some("PT0S".to_string());
    }
    let (sign, hm) = tz.split_at(1);
    let (h, m) = hm.split_once(':')?;
    let (h, m): (u32, u32) = (h.parse().ok()?, m.parse().ok()?);
    if h == 0 && m == 0 {
        return Some("PT0S".to_string());
    }
    let mut out = String::new();
    if sign == "-" {
        out.push('-');
    }
    out.push_str("PT");
    if h > 0 {
        out.push_str(&format!("{h}H"));
    }
    if m > 0 {
        out.push_str(&format!("{m}M"));
    }
    Some(out)
}

/// Per-thread `REGEX()`/`REPLACE()` compile memo (sq-98w7z.1). [FABLE-5]
///
/// `build_regex` used to run INSIDE the per-row scalar eval, so a constant-pattern
/// FILTER recompiled the regex on every row (compile is µs-scale vs ns-scale match).
/// The memo compiles each distinct `(pattern, flags)` ONCE per thread and hands out
/// the same instance via `Rc` — sharing the INSTANCE (not clones of it) is what
/// preserves the warmed lazy-DFA cache, the same bug class the SHACL fix (PR #1891)
/// found. A compile FAILURE is memoised as `None`, so an invalid pattern or flag
/// stays a per-row type error (`Value::Error`) exactly as before — the cache stores
/// the error-or-regex OUTCOME, never swallows it.
///
/// Re-entry safety: the key `(pattern, flags)` fully determines the compiled regex
/// independent of any `Bindings` layout or query context, so an `EXISTS`-nested
/// FILTER re-entering this thread can only HIT the memo correctly — unlike a
/// column-index thread-local, there is nothing execution-scoped to drain or reset,
/// and for the same reason entries carrying over across queries cannot change any
/// result. The `RefCell` borrow never spans user code (`build_regex` is pure), so
/// re-entry cannot observe a live borrow.
#[cfg(feature = "regex")]
mod regex_cache {
    use std::cell::RefCell;
    use std::rc::Rc;

    /// Hard cap on memo entries; on overflow the memo is CLEARED, so a pathological
    /// dynamic-pattern workload degrades to the old compile-per-row behaviour,
    /// never to unbounded memory. Lookup is a linear scan — with ≤ CAP entries and
    /// the typical one-or-two distinct patterns per query, that is an
    /// allocation-free string compare, cheaper than hashing an owned key.
    const CAP: usize = 64;

    thread_local! {
        #[allow(clippy::type_complexity)]
        static MEMO: RefCell<Vec<((String, String), Option<Rc<regex::Regex>>)>> =
            const { RefCell::new(Vec::new()) };
    }

    // Compiles actually performed on this thread (memo misses) — the compile-once
    // counter tests assert on deltas of this.
    #[cfg(test)]
    thread_local! {
        static COMPILES: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
    }

    #[cfg(test)]
    pub(super) fn compile_count() -> u64 {
        COMPILES.with(std::cell::Cell::get)
    }

    /// The compiled regex for `(pattern, flags)`, or `None` for an invalid
    /// pattern/flag — both memoised.
    pub(super) fn get(pattern: &str, flags: &str) -> Option<Rc<regex::Regex>> {
        MEMO.with(|m| {
            let mut m = m.borrow_mut();
            if let Some((_, re)) = m.iter().find(|((p, f), _)| p == pattern && f == flags) {
                return re.clone();
            }
            #[cfg(test)]
            COMPILES.with(|c| c.set(c.get() + 1));
            let re = super::build_regex(pattern, flags).map(Rc::new);
            if m.len() >= CAP {
                m.clear();
            }
            m.push(((pattern.to_string(), flags.to_string()), re.clone()));
            re
        })
    }
}

/// Build a regex honouring the SPARQL flag string (`i` case-insensitive, `s` dot-all, `m`
/// multi-line, `x` extended/ignore-whitespace, `q` literal-pattern mode per XPath F&O —
/// every pattern character is matched literally, combinable with `i`).
/// Returns `None` on an invalid pattern or an unknown flag (→ type error).
/// Compile-per-call — go through [`regex_cache::get`] on any per-row path.
#[cfg(feature = "regex")]
fn build_regex(pattern: &str, flags: &str) -> Option<regex::Regex> {
    if !flags.chars().all(|c| matches!(c, 'i' | 's' | 'm' | 'x' | 'q')) {
        return None;
    }
    let literal = flags.contains('q');
    let pattern = if literal { regex::escape(pattern) } else { pattern.to_string() };
    regex::RegexBuilder::new(&pattern)
        .case_insensitive(flags.contains('i'))
        // `q` suppresses the meaning of the OTHER flags' metacharacters too (per
        // XPath, only `i` keeps its effect alongside `q`).
        .dot_matches_new_line(!literal && flags.contains('s'))
        .multi_line(!literal && flags.contains('m'))
        .ignore_whitespace(!literal && flags.contains('x'))
        .build()
        .ok()
}

/// SPARQL `ENCODE_FOR_URI`: percent-encode everything except the unreserved set (RFC 3986
/// ALPHA / DIGIT / `-` `.` `_` `~`).
fn encode_for_uri(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for byte in s.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            out.push(byte as char);
        } else {
            out.push('%');
            out.push_str(&format!("{byte:02X}"));
        }
    }
    out
}

/// Extract a numeric `xsd:dateTime` component (0=year…5=seconds) from a value's lexical
/// form. YEAR…MINUTES return xsd:integer; SECONDS returns xsd:decimal (per SPARQL),
/// parsed from the lexical so fractional seconds stay exact.
fn datetime_field(v: &Value, idx: usize) -> Value {
    let s = match value_str(v) {
        Some(s) => s,
        None => return Value::Error,
    };
    let fields = match parse_datetime(&s) {
        Some(f) => f,
        None => return Value::Error,
    };
    if idx == 5 {
        // Re-extract the seconds lexical (timezone stripped) for an exact decimal.
        let lex = s
            .split_once('T')
            .map(|(_, t)| if let Some(i) = t.find(['Z', '+', '-']) { &t[..i] } else { t })
            .and_then(|t| t.rsplit_once(':').map(|(_, sec)| sec));
        return match lex.and_then(Dec::parse_lexical) {
            Some(d) => Value::Num(Num::Dec(d)),
            None => Value::Error,
        };
    }
    Value::Num(Num::Int(fields[idx] as i64))
}

/// Parse an `xsd:dateTime` lexical (`[-]YYYY-MM-DDThh:mm:ss[.frac][TZ]`) into
/// `[year, month, day, hours, minutes, seconds]`. Timezone is stripped (component accessors are on
/// the local time per SPARQL); seconds keeps any fractional part.
fn parse_datetime(s: &str) -> Option<[f64; 6]> {
    let (date, time) = s.split_once('T')?;
    let neg = date.starts_with('-');
    let mut d = date.strip_prefix('-').unwrap_or(date).split('-');
    let year: f64 = d.next()?.parse().ok()?;
    let year = if neg { -year } else { year };
    let month: f64 = d.next()?.parse().ok()?;
    let day: f64 = d.next()?.parse().ok()?;
    // Strip the timezone (Z, or +hh:mm / -hh:mm after the seconds — the time part itself has no '-').
    let time = if let Some(i) = time.find(['Z', '+', '-']) { &time[..i] } else { time };
    let mut t = time.split(':');
    let hours: f64 = t.next()?.parse().ok()?;
    let minutes: f64 = t.next()?.parse().ok()?;
    let seconds: f64 = t.next()?.parse().ok()?;
    Some([year, month, day, hours, minutes, seconds])
}

fn value_str(v: &Value) -> Option<String> {
    match v {
        Value::Term(Term::Literal(l)) => Some(l.value().to_string()),
        Value::Term(Term::NamedNode(n)) => Some(n.as_str().to_string()),
        Value::Term(Term::BlankNode(b)) => Some(b.as_str().to_string()),
        Value::Bool(b) => Some(b.to_string()),
        Value::Num(n) => Some(n.lexical()),
        Value::Unbound | Value::Error => None,
        Value::Term(_) => None,
    }
}

/// Resolves a computed NUMERIC value to an id without constructing a Term when
/// possible: an inline-range integer encodes straight into its id (no allocation at
/// all); any other numeric probes the dictionary by (lexical, datatype) parts.
/// `Ok(id)` on a hit; `Err(lexical)` carries the (already formatted) lexical form for
/// the caller's local-vocab miss path.
#[inline]
fn num_to_id(graph: &Graph, n: Num) -> Result<Id, String> {
    if let Num::Int(i) = n {
        if let Some(id) = dict::inline_id_of_int(i) {
            return Ok(id);
        }
    }
    let lex = n.lexical();
    match graph.dict.lookup_lit(&lex, n.datatype().as_str(), None) {
        NO_ID => Err(lex),
        id => Ok(id),
    }
}

/// Converts an evaluated value into an id. Computed terms are resolved against
/// the graph dictionary first (so they join and deduplicate against the data);
/// terms not already present get a per-query local id. Computed numerics skip
/// Term construction entirely when they resolve to an inline id or a dictionary
/// term (the BIND fast path).
fn value_to_id(graph: &Graph, local: &mut LocalVocab, v: &Value) -> Id {
    let term = match v {
        Value::Unbound | Value::Error => return NO_ID,
        Value::Num(n) => match num_to_id(graph, *n) {
            Ok(id) => return id,
            Err(lex) => Term::Literal(Literal::new_typed_literal(lex, n.datatype())),
        },
        Value::Bool(b) => {
            let lex = if *b { "true" } else { "false" };
            match graph.dict.lookup_lit(lex, xsd::BOOLEAN.as_str(), None) {
                NO_ID => Term::Literal(Literal::new_typed_literal(lex, xsd::BOOLEAN)),
                id => return id,
            }
        }
        Value::Term(t) => {
            if let Some(id) = graph.id_of(t) {
                return id;
            }
            t.clone()
        }
    };
    local.intern(term)
}

/// A computed value as a concrete RDF term (`None` for unbound / type error).
fn value_as_term(v: &Value) -> Option<Term> {
    Some(match v {
        Value::Unbound | Value::Error => return None,
        Value::Bool(b) => Term::Literal(Literal::new_typed_literal(b.to_string(), xsd::BOOLEAN)),
        Value::Num(n) => Term::Literal(Literal::new_typed_literal(n.lexical(), n.datatype())),
        Value::Term(t) => t.clone(),
    })
}

/// Read-only half of [`value_to_id`], for the parallel resolve pass (T1.0b). Most computed values
/// resolve WITHOUT touching the mutable vocab: small integers inline into the id, and terms
/// already in the graph dictionary (or already interned locally) are read-only lookups. Only a
/// genuinely new term returns `Err(term)` — carrying the constructed `Term` so the serial
/// intern-the-misses pass does no re-construction. Splitting this way removes the bulk of the B1
/// serialization point (research/parallelism-scaling.md) without sharded-vocab complexity, and
/// stays byte-identical: misses are interned in row order, exactly as the serial path would.
fn value_to_id_readonly(graph: &Graph, local: &LocalVocab, v: &Value) -> Result<Id, Term> {
    let term = match v {
        Value::Unbound | Value::Error => return Ok(NO_ID),
        // Computed numerics/booleans skip Term construction when they resolve to an
        // inline id or a dictionary term — the constructed-Term path only runs for
        // values that genuinely head to the local vocab (the BIND fast path).
        Value::Num(n) => match num_to_id(graph, *n) {
            Ok(id) => return Ok(id),
            Err(lex) => Term::Literal(Literal::new_typed_literal(lex, n.datatype())),
        },
        Value::Bool(b) => {
            let lex = if *b { "true" } else { "false" };
            match graph.dict.lookup_lit(lex, xsd::BOOLEAN.as_str(), None) {
                NO_ID => Term::Literal(Literal::new_typed_literal(lex, xsd::BOOLEAN)),
                id => return Ok(id),
            }
        }
        Value::Term(t) => {
            if let Some(id) = graph.id_of(t) {
                return Ok(id);
            }
            t.clone()
        }
    };
    if let Some(&id) = local.ids.get(&term) {
        return Ok(id);
    }
    Err(term)
}

// ---- spargebra term helpers --------------------------------------------------

fn ground_to_term(g: &GroundTerm) -> Term {
    match g {
        GroundTerm::NamedNode(n) => Term::NamedNode(n.clone()),
        GroundTerm::Literal(l) => Term::Literal(l.clone()),
        // A ground RDF 1.2 triple term (e.g. in VALUES): fully concrete, so it maps
        // straight to a structural `Term::Triple` (the object may nest another).
        GroundTerm::Triple(t) => Term::Triple(Box::new(oxrdf::Triple::new(
            t.subject.clone(),
            t.predicate.clone(),
            ground_to_term(&t.object),
        ))),
    }
}

fn term_pattern_to_term(tp: &TermPattern) -> Result<Term, String> {
    match tp {
        TermPattern::NamedNode(n) => Ok(Term::NamedNode(n.clone())),
        TermPattern::BlankNode(b) => Ok(Term::BlankNode(b.clone())),
        TermPattern::Literal(l) => Ok(Term::Literal(l.clone())),
        TermPattern::Variable(_) => Err("variable where a term was expected".into()),
        // GROUND triple term `<<( s p o )>>` (RDF 1.2): build the structural
        // `Term::Triple`, which the dictionary interns/looks up by its component ids.
        // A variable INSIDE a triple-term pattern (sq-kbs / T6) is handled UPSTREAM by
        // BGP decomposition (`extract_quoted_constraints` -> `quoted_relation`), which
        // rewrites any variable-carrying quoted slot into a synthetic variable before this
        // resolver runs. So in a parsed query this function only ever sees a GROUND triple
        // term — the variable-predicate arm below is a defensive backstop, not a feature gap.
        TermPattern::Triple(t) => {
            let subject: oxrdf::NamedOrBlankNode = match term_pattern_to_term(&t.subject)? {
                Term::NamedNode(n) => n.into(),
                Term::BlankNode(b) => b.into(),
                _ => return Err("RDF 1.2 triple-term subject must be an IRI or blank node".into()),
            };
            let predicate = match &t.predicate {
                NamedNodePattern::NamedNode(n) => n.clone(),
                // Unreachable for parsed queries (see above); kept as a non-panicking backstop.
                NamedNodePattern::Variable(_) => {
                    return Err("variable inside a quoted-triple term must be decomposed by the BGP planner (T6)".into())
                }
            };
            let object = term_pattern_to_term(&t.object)?;
            Ok(Term::Triple(Box::new(oxrdf::Triple::new(subject, predicate, object))))
        }
    }
}

/// Prefix for the synthetic variables that stand in for blank nodes (which are
/// existential variables in a query). `#` cannot appear in a SPARQL `VARNAME`,
/// so these can never collide with a user variable, and the `SELECT *` filter on
/// this prefix can never hide a real one.
const BNODE_VAR_PREFIX: &str = "#bn#";

fn bnode_var(b: &oxrdf::BlankNode) -> Variable {
    Variable::new_unchecked(format!("{BNODE_VAR_PREFIX}{}", b.as_str()))
}

fn tp_var(tp: &TermPattern) -> Option<Variable> {
    match tp {
        TermPattern::Variable(v) => Some(v.clone()),
        TermPattern::BlankNode(b) => Some(bnode_var(b)),
        _ => None,
    }
}

fn nnp_var(p: &NamedNodePattern) -> Option<Variable> {
    match p {
        NamedNodePattern::Variable(v) => Some(v.clone()),
        _ => None,
    }
}

#[cfg(test)]
mod exact_decimal_tests {
    use super::*;

    #[test]
    fn dec_arithmetic_is_exact() {
        use std::cmp::Ordering::*;
        let d = |s: &str| Dec::parse(s).unwrap();
        // The classic: 0.1 + 0.2 == 0.3 exactly (false in f64).
        assert_eq!(d("0.1").checked_add(d("0.2")).unwrap().cmp(d("0.3")), Some(Equal));
        // 0.3 - 0.1 == 0.2 exactly.
        assert_eq!(d("0.3").checked_sub(d("0.1")).unwrap().cmp(d("0.2")), Some(Equal));
        // Mixed scales + integer/decimal.
        assert_eq!(d("1").checked_add(d("0.5")).unwrap().cmp(d("1.5")), Some(Equal));
        assert_eq!(d("83").checked_mul(d("0.5")).unwrap().cmp(d("41.5")), Some(Equal));
        assert_eq!(d("0.1").checked_mul(d("0.1")).unwrap().cmp(d("0.01")), Some(Equal));
        // Ordering across scales and signs.
        assert_eq!(d("0.30000000000000001").cmp(d("0.3")), Some(Greater));
        assert_eq!(d("-2.5").checked_add(d("1")).unwrap().cmp(d("-1.5")), Some(Equal));
        // Large integers beyond 2^53 stay exact.
        assert_eq!(d("9007199254740992").checked_add(d("1")).unwrap().cmp(d("9007199254740993")), Some(Equal));
        // Non-decimal lexical (exponent) -> not parseable here -> None.
        assert!(Dec::parse("1e5").is_none());
    }

    #[test]
    fn cmp_decimal_str_is_exact() {
        use std::cmp::Ordering::*;
        // Integers beyond f64 precision, and high-precision decimals that share an f64.
        assert_eq!(cmp_decimal_str("9007199254740992", "9007199254740993"), Some(Less));
        assert_eq!(cmp_decimal_str("0.123456789012345678", "0.123456789012345679"), Some(Less));
        // Equality incl. non-canonical zeros / trailing zeros / signed zero.
        assert_eq!(cmp_decimal_str("1.50", "1.5"), Some(Equal));
        assert_eq!(cmp_decimal_str("007", "7"), Some(Equal));
        assert_eq!(cmp_decimal_str("-0", "0"), Some(Equal));
        assert_eq!(cmp_decimal_str("0.0", "-0.0"), Some(Equal));
        // Sign + magnitude.
        assert_eq!(cmp_decimal_str("-3", "2"), Some(Less));
        assert_eq!(cmp_decimal_str("-2", "-3"), Some(Greater));
        assert_eq!(cmp_decimal_str("10", "9"), Some(Greater));
        assert_eq!(cmp_decimal_str("1.1", "1.09"), Some(Greater));
        assert_eq!(cmp_decimal_str("0.1", "0.2"), Some(Less));
        // Integer vs decimal of equal value.
        assert_eq!(cmp_decimal_str("5", "5.0"), Some(Equal));
        assert_eq!(cmp_decimal_str("5", "5.0000000000000001"), Some(Less));
        // Malformed -> None (falls back to f64).
        assert_eq!(cmp_decimal_str("1.2.3", "1"), None);
        assert_eq!(cmp_decimal_str("1e5", "1"), None);
    }

    #[test]
    fn sig_digits_counts() {
        assert_eq!(sig_digits("120"), 3);
        assert_eq!(sig_digits("0.5"), 1);
        assert_eq!(sig_digits("9007199254740992"), 16);
        assert_eq!(sig_digits("0.123456789012345679"), 18);
        assert_eq!(sig_digits("0.00123"), 3); // leading fraction zeros are not significant
        assert_eq!(sig_digits("100.0"), 3);
    }
}

#[cfg(test)]
mod wcoj_tests {
    use super::*;
    use spargebra::SparqlParser;

    /// Extracts the BGP triple patterns from a simple `SELECT * WHERE { ... }`.
    fn bgp(sparql: &str) -> Vec<TriplePattern> {
        let q = SparqlParser::new().parse_query(sparql).unwrap();
        let spargebra::Query::Select { pattern, .. } = q else { panic!() };
        let mut patterns = Vec::new();
        let mut filters = Vec::new();
        // unwrap Project -> inner
        fn inner_of(p: &GraphPattern) -> &GraphPattern {
            match p {
                GraphPattern::Project { inner, .. }
                | GraphPattern::Distinct { inner }
                | GraphPattern::Slice { inner, .. } => inner_of(inner),
                other => other,
            }
        }
        flatten_conjunction(inner_of(&pattern), &mut patterns, &mut filters);
        patterns
    }

    /// Sorted set of result rows from a Bindings, for order-independent equality.
    fn rowset(b: &Bindings) -> Vec<Vec<(String, Id)>> {
        let mut rows: Vec<Vec<(String, Id)>> = b
            .rows
            .iter()
            .map(|r| {
                let mut kv: Vec<(String, Id)> =
                    b.vars.iter().zip(r).map(|(v, &id)| (v.as_str().to_string(), id)).collect();
                kv.sort();
                kv
            })
            .collect();
        rows.sort();
        rows
    }

    fn random_graph(seed0: u64, n_nodes: u32, n_edges: usize) -> Graph {
        let mut seed = seed0;
        let mut next = || {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            (seed >> 33) as u32
        };
        let mut ttl = String::from("@prefix ex: <http://ex/> .\n");
        for _ in 0..n_edges {
            let a = next() % n_nodes;
            let b = next() % n_nodes;
            ttl.push_str(&format!("ex:n{a} ex:e ex:n{b} .\n"));
        }
        Graph::load_str(&ttl, "turtle").unwrap()
    }

    /// The binary and WCOJ BGP plans must return identical result sets.
    fn assert_plans_agree(sparql: &str, graph: &Graph) {
        let patterns = bgp(sparql);
        let binary = eval_bgp_binary(graph, &patterns, &[]).unwrap();
        let wcoj = eval_bgp_wcoj(graph, &patterns).unwrap();
        assert_eq!(
            rowset(&binary),
            rowset(&wcoj),
            "binary vs WCOJ disagree for `{sparql}` (binary {} rows, wcoj {} rows)",
            binary.rows.len(),
            wcoj.rows.len()
        );
    }

    #[test]
    fn cyclicity_classification() {
        assert!(!bgp_is_cyclic(&bgp("PREFIX ex: <http://ex/> SELECT * WHERE { ?a ex:e ?b . ?b ex:e ?c }")));
        assert!(bgp_is_cyclic(&bgp(
            "PREFIX ex: <http://ex/> SELECT * WHERE { ?a ex:e ?b . ?b ex:e ?c . ?c ex:e ?a }"
        )));
        assert!(bgp_is_cyclic(&bgp(
            "PREFIX ex: <http://ex/> SELECT * WHERE { ?a ex:e ?b . ?b ex:e ?c . ?c ex:e ?d . ?d ex:e ?a }"
        )));
        // star is acyclic
        assert!(!bgp_is_cyclic(&bgp(
            "PREFIX ex: <http://ex/> SELECT * WHERE { ?a ex:e ?b . ?a ex:e ?c . ?a ex:e ?d }"
        )));
    }

    #[test]
    fn wcoj_matches_binary_over_random_graphs() {
        for seed in [0x1111u64, 0xACE1, 0xDEADBEEF, 0x5EED] {
            let g = random_graph(seed, 25, 120);
            // chain (acyclic)
            assert_plans_agree("PREFIX ex: <http://ex/> SELECT * WHERE { ?a ex:e ?b . ?b ex:e ?c }", &g);
            // triangle (cyclic) — the canonical WCOJ win
            assert_plans_agree(
                "PREFIX ex: <http://ex/> SELECT * WHERE { ?a ex:e ?b . ?b ex:e ?c . ?c ex:e ?a }",
                &g,
            );
            // 4-cycle
            assert_plans_agree(
                "PREFIX ex: <http://ex/> SELECT * WHERE { ?a ex:e ?b . ?b ex:e ?c . ?c ex:e ?d . ?d ex:e ?a }",
                &g,
            );
            // square with a diagonal (denser cycle)
            assert_plans_agree(
                "PREFIX ex: <http://ex/> SELECT * WHERE { ?a ex:e ?b . ?b ex:e ?c . ?c ex:e ?a . ?a ex:e ?d . ?d ex:e ?c }",
                &g,
            );
        }
    }

    #[test]
    fn wcoj_repeated_variable_pattern() {
        // self-loops: ?x ex:e ?x  — repeated-variable handling in build_trie.
        let g = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:a ex:e ex:a . ex:a ex:e ex:b . ex:b ex:e ex:b .",
            "turtle",
        )
        .unwrap();
        let patterns = bgp("PREFIX ex: <http://ex/> SELECT * WHERE { ?x ex:e ?x }");
        let wcoj = eval_bgp_wcoj(&g, &patterns).unwrap();
        assert_eq!(wcoj.rows.len(), 2); // a and b
    }

    // ---- [OPUS-4.8] (sq-5zf8i / §A4) Yannakakis full-semijoin prepass ---------

    /// A direct unit test for the ENGAGED prepass: a relation large enough to clear the
    /// `YANNAKAKIS_MIN_REL` cost-gate, with most rows DANGLING (no join partner), so the
    /// reduction actually fires. The prepass result must equal the binary plan's, row for
    /// row — the load-bearing answer-equivalence invariant, tested against the in-crate
    /// reference executor (not a brute force) so it covers the new public-on-this-feature
    /// `eval_bgp_yannakakis` directly. Only compiles in the feature-on matrix leg.
    #[cfg(feature = "yannakakis")]
    #[test]
    fn yannakakis_prepass_engages_and_matches_binary() {
        // 6000 subjects bound by ex:a (>4096 ⇒ above the gate); only the first 10 also have
        // an ex:b, so the join ?s ex:a ?x . ?s ex:b ?y returns 10 rows after dropping 5990
        // dangling ex:a tuples — exactly what the bottom-up semijoin removes.
        let mut ttl = String::from("@prefix ex: <http://ex/> .\n");
        for i in 0..6000u32 {
            ttl.push_str(&format!("ex:s{i} ex:a ex:x{i} .\n"));
            if i < 10 {
                ttl.push_str(&format!("ex:s{i} ex:b ex:y{i} .\n"));
            }
        }
        let g = Graph::load_str(&ttl, "turtle").unwrap();
        let patterns = bgp("PREFIX ex: <http://ex/> SELECT * WHERE { ?s ex:a ?x . ?s ex:b ?y }");

        // Sanity: the ex:a relation really is above the gate (so the prepass engages, not
        // the fallback) — otherwise this test would silently exercise the binary path.
        let prepared = prepare_bgp(&g, &patterns).unwrap();
        assert!(
            prepared.iter().map(|p| p.est).max().unwrap() >= YANNAKAKIS_MIN_REL,
            "test dataset must clear the cost-gate so the prepass engages"
        );

        let prepass = eval_bgp_yannakakis(&g, &patterns, &[]).unwrap();
        let binary = eval_bgp_binary(&g, &patterns, &[]).unwrap();
        assert_eq!(rowset(&prepass), rowset(&binary), "prepass must equal the binary plan");
        assert_eq!(prepass.rows.len(), 10, "exactly the ten joining subjects survive");
    }

    /// The cost-gate (pure-overhead guard): a tiny BGP below `YANNAKAKIS_MIN_REL` falls back
    /// to the binary plan, and the answer is identical. Confirms the guard never changes
    /// results. Only compiles in the feature-on matrix leg.
    #[cfg(feature = "yannakakis")]
    #[test]
    fn yannakakis_cost_gate_falls_back_below_threshold() {
        let g = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:s1 ex:a ex:x1 . ex:s1 ex:b ex:y1 . ex:s2 ex:a ex:x2 .",
            "turtle",
        )
        .unwrap();
        let patterns = bgp("PREFIX ex: <http://ex/> SELECT * WHERE { ?s ex:a ?x . ?s ex:b ?y }");
        let prepared = prepare_bgp(&g, &patterns).unwrap();
        assert!(prepared.iter().map(|p| p.est).max().unwrap() < YANNAKAKIS_MIN_REL);
        let prepass = eval_bgp_yannakakis(&g, &patterns, &[]).unwrap();
        let binary = eval_bgp_binary(&g, &patterns, &[]).unwrap();
        assert_eq!(rowset(&prepass), rowset(&binary), "fallback below the gate is result-identical");
        assert_eq!(prepass.rows.len(), 1); // only s1 has both a and b
    }
}

#[cfg(test)]
mod function_tests {
    use super::*;

    fn g() -> Graph {
        Graph::load_str(
            "@prefix : <http://ex/> .\n\
             :a :name \"Alice\" . :b :name \"bob\" . :c :name \"Carol123\" .\n\
             :a :age 30 . :b :age -5 .\n",
            "turtle",
        )
        .unwrap()
    }
    // Result-set size via the full materialising path (applies FILTER/BIND functions).
    fn n(sparql: &str) -> usize {
        crate::query(&g(), sparql).unwrap().len()
    }

    #[test]
    fn string_functions() {
        assert_eq!(n("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(STRLEN(?n) > 3) }"), 2); // Alice, Carol123
        assert_eq!(n("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(STRSTARTS(?n, \"A\")) }"), 1);
        assert_eq!(n("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(STRENDS(?n, \"3\")) }"), 1);
        assert_eq!(n("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(CONTAINS(LCASE(?n), \"o\")) }"), 2); // bob, carol
        assert_eq!(n("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(UCASE(?n) = \"BOB\") }"), 1);
        // BIND never drops rows.
        assert_eq!(n("SELECT ?g WHERE { ?s <http://ex/name> ?n BIND(CONCAT(?n, \"!\") AS ?g) }"), 3);
        assert_eq!(n("SELECT ?g WHERE { ?s <http://ex/name> ?n BIND(SUBSTR(?n, 1, 2) AS ?g) }"), 3);
    }

    #[test]
    fn numeric_and_type_functions() {
        assert_eq!(n("SELECT ?a WHERE { ?s <http://ex/age> ?a FILTER(ABS(?a) > 10) }"), 1); // |30|
        assert_eq!(n("SELECT ?a WHERE { ?s <http://ex/age> ?a FILTER(isNumeric(?a)) }"), 2);
        assert_eq!(n("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(isLiteral(?n)) }"), 3);
        assert_eq!(n("SELECT ?s WHERE { ?s <http://ex/name> ?n FILTER(isIRI(?s)) }"), 3);
        assert_eq!(n("SELECT ?a WHERE { ?s <http://ex/age> ?a FILTER(FLOOR(?a) = ?a) }"), 2);
    }

    #[test]
    fn lang_typed_and_sample() {
        let g = Graph::load_str(
            "@prefix : <http://ex/> . :a :name \"Alice\"@en . :b :name \"Bob\"@fr . :c :name \"X\" .",
            "turtle",
        )
        .unwrap();
        let q = |s: &str| crate::query(&g, s).unwrap().len();
        // LANGMATCHES: "en" matches the en literal; "*" matches any non-empty tag (en, fr; not X).
        assert_eq!(q("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(LANGMATCHES(LANG(?n), \"en\")) }"), 1);
        assert_eq!(q("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(LANGMATCHES(LANG(?n), \"*\")) }"), 2);
        // STRLANG / STRDT construct literals (exercised via BIND — all 3 rows).
        assert_eq!(q("SELECT ?x WHERE { ?s <http://ex/name> ?n BIND(STRLANG(STR(?n), \"de\") AS ?x) }"), 3);
        assert_eq!(
            q("SELECT ?x WHERE { ?s <http://ex/name> ?n BIND(STRDT(STR(?n), <http://www.w3.org/2001/XMLSchema#string>) AS ?x) }"),
            3
        );
        // SAMPLE: one row per group.
        let g2 = Graph::load_str("@prefix : <http://ex/> . :a :p :x . :a :p :y . :b :p :z .", "turtle").unwrap();
        assert_eq!(
            crate::query(&g2, "SELECT ?s (SAMPLE(?o) AS ?v) WHERE { ?s <http://ex/p> ?o } GROUP BY ?s").unwrap().len(),
            2
        );
    }

    #[test]
    fn datetime_accessors() {
        let g = Graph::load_str(
            "@prefix : <http://ex/> . @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\
             :e :at \"2024-03-15T13:45:30\"^^xsd:dateTime .",
            "turtle",
        )
        .unwrap();
        let q = |s: &str| crate::query(&g, s).unwrap().len();
        assert_eq!(q("SELECT * WHERE { ?e <http://ex/at> ?d FILTER(YEAR(?d) = 2024 && MONTH(?d) = 3 && DAY(?d) = 15) }"), 1);
        assert_eq!(q("SELECT * WHERE { ?e <http://ex/at> ?d FILTER(HOURS(?d) = 13 && MINUTES(?d) = 45 && SECONDS(?d) = 30) }"), 1);
    }

    #[cfg(feature = "regex")]
    #[test]
    fn regex_functions() {
        assert_eq!(n("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(REGEX(?n, \"^[A-Z]\")) }"), 2); // Alice, Carol123
        assert_eq!(n("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(REGEX(?n, \"BOB\", \"i\")) }"), 1);
        assert_eq!(n("SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(REGEX(?n, \"[0-9]+\")) }"), 1); // Carol123
        assert_eq!(n("SELECT ?g WHERE { ?s <http://ex/name> ?n BIND(REPLACE(?n, \"[0-9]\", \"X\") AS ?g) }"), 3);
    }
}

/// [FABLE-5] sq-98w7z.1 — per-row builtin memoisation: (A) the REGEX/REPLACE
/// compile memo, (B) the RAND() thread-local PRNG, (C) NOW() query-constancy
/// (SPARQL 1.1 §17.4.5.1). Every test here exercises the REAL evaluation path
/// (`crate::query*` or the actual thread-local modules), never a mock.
#[cfg(test)]
#[cfg(not(target_arch = "wasm32"))]
mod builtin_memo_tests {
    use super::*;

    // [OPUS-4.8] (sq-98w7z.1) Used only by the `regex`-gated REGEX/REPLACE tests, so gate the
    // helper too — otherwise it is dead code under `--no-default-features` (feature-OFF clippy).
    #[cfg(feature = "regex")]
    fn names_graph() -> Graph {
        Graph::load_str(
            "@prefix : <http://ex/> .\n\
             :a :name \"Alice\" . :b :name \"bob\" . :c :name \"Carol123\" .\n",
            "turtle",
        )
        .unwrap()
    }

    fn wide_graph(rows: usize) -> Graph {
        let ttl: String =
            (0..rows).map(|i| format!("<http://ex/s{i}> <http://ex/p> <http://ex/o> .\n")).collect();
        Graph::load_str(&ttl, "turtle").unwrap()
    }

    // ---- (A) REGEX / REPLACE compile memo ---------------------------------------

    /// Result-equivalence differential: over a mixed (pattern, flags) set — valid,
    /// invalid pattern, unknown flag, each of i/s/m/x/q — the memoised regex must
    /// behave IDENTICALLY to a fresh `build_regex` compile, on both the first
    /// (miss) and second (hit) lookup, including the `None` outcome that maps to
    /// `Value::Error` per row.
    #[cfg(feature = "regex")]
    #[test]
    fn regex_cache_fresh_equivalence_differential() {
        let cases: &[(&str, &str)] = &[
            ("^[A-Z]", ""),
            ("bob", "i"),
            ("a.c", "s"),
            ("^b", "m"),
            ("a b", "x"),
            ("a.c", "q"),  // literal mode: the dot matches only a literal dot
            ("A.C", "qi"), // q combined with i keeps case-insensitivity
            ("[", ""),     // invalid pattern -> None
            ("a", "z"),    // unknown flag -> None
            ("(unclosed", "i"),
        ];
        let texts = ["Alice", "bob", "BOB", "a.c", "aXc", "abc\nbcd", "a b"];
        for (pat, flags) in cases {
            let fresh = build_regex(pat, flags);
            for round in 0..2 {
                let cached = regex_cache::get(pat, flags);
                assert_eq!(
                    cached.is_some(),
                    fresh.is_some(),
                    "compile outcome diverged for ({pat:?}, {flags:?}) round {round}"
                );
                if let (Some(c), Some(f)) = (&cached, &fresh) {
                    for t in &texts {
                        assert_eq!(c.is_match(t), f.is_match(t), "is_match diverged: ({pat:?}, {flags:?}) on {t:?}");
                        assert_eq!(
                            c.replace_all(t, "_").into_owned(),
                            f.replace_all(t, "_").into_owned(),
                            "replace_all diverged: ({pat:?}, {flags:?}) on {t:?}"
                        );
                    }
                }
            }
        }
    }

    /// Compile-once counter (NON-VACUOUS: reverting the memo lookup in
    /// `regex_cache::get` makes the first delta 100, one per row): a
    /// constant-pattern FILTER over 100 rows compiles once; a SECOND execution
    /// reusing the pattern compiles zero times (the key is query-independent);
    /// REPLACE adds one compile for its distinct pattern; an INVALID pattern
    /// memoises its failure once while still erroring per row (FILTER drops every
    /// row, BIND leaves every row with the variable unbound — the pre-memo
    /// semantics).
    #[cfg(feature = "regex")]
    #[test]
    fn regex_compiles_once_not_per_row() {
        let ttl: String =
            (0..100).map(|i| format!("<http://ex/s{i}> <http://ex/name> \"name{i}A\" .\n")).collect();
        let g = Graph::load_str(&ttl, "turtle").unwrap();
        let filter_q = "SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(REGEX(?n, \"e9[0-9]A$\")) }";

        let c0 = regex_cache::compile_count();
        assert_eq!(crate::query(&g, filter_q).unwrap().len(), 10); // name90A..name99A
        let c1 = regex_cache::compile_count();
        assert_eq!(c1 - c0, 1, "a constant-pattern FILTER over 100 rows must compile ONCE, not per row");

        assert_eq!(crate::query(&g, filter_q).unwrap().len(), 10);
        assert_eq!(regex_cache::compile_count(), c1, "a second execution reuses the memoised compile");

        assert_eq!(
            crate::query(&g, "SELECT ?r WHERE { ?s <http://ex/name> ?n BIND(REPLACE(?n, \"[0-9]+\", \"#\") AS ?r) }")
                .unwrap()
                .len(),
            100
        );
        assert_eq!(regex_cache::compile_count(), c1 + 1, "REPLACE compiles its distinct pattern once");

        // Invalid pattern: the FAILURE is memoised (one compile attempt), and the
        // per-row semantics stay exactly the pre-memo ones.
        assert_eq!(
            crate::query(&g, "SELECT ?n WHERE { ?s <http://ex/name> ?n FILTER(REGEX(?n, \"[\")) }").unwrap().len(),
            0,
            "invalid pattern: type error per row -> FILTER drops every row"
        );
        assert_eq!(regex_cache::compile_count(), c1 + 2);
        let r = crate::query(&g, "SELECT ?r WHERE { ?s <http://ex/name> ?n BIND(REPLACE(?n, \"[\", \"X\") AS ?r) }")
            .unwrap();
        assert_eq!(r.len(), 100, "invalid pattern under BIND keeps rows");
        assert!(r.rows.iter().all(|row| row[0].is_none()), "…with ?r unbound on every row");
        assert_eq!(regex_cache::compile_count(), c1 + 2, "the memoised failure is reused, not recompiled");
    }

    /// Overflowing the memo cap stays bounded and correct (the memo clears and
    /// keeps compiling — degraded, never wrong).
    #[cfg(feature = "regex")]
    #[test]
    fn regex_cache_cap_overflow_stays_correct() {
        for i in 0..131 {
            let pat = format!("^p{i}$");
            let re = regex_cache::get(&pat, "").expect("valid pattern");
            assert!(re.is_match(&format!("p{i}")));
            assert!(!re.is_match("nope"));
        }
    }

    /// EXISTS-nested REGEX re-enters the memo on the SAME thread in the middle of
    /// the outer FILTER's row loop. The `(pattern, flags)` key is independent of
    /// any `Bindings` layout (unlike a column-index thread-local), so the
    /// re-entry can only hit the memo correctly: both patterns coexist and each
    /// compiles exactly once despite the interleaving.
    #[cfg(feature = "regex")]
    #[test]
    fn regex_cache_exists_reentry() {
        let g = names_graph();
        let c0 = regex_cache::compile_count();
        let q = "SELECT ?n WHERE { ?s <http://ex/name> ?n \
                 FILTER(REGEX(?n, \"^[A-Za-z]+[0-9]+$\") && EXISTS { ?s <http://ex/name> ?n2 FILTER(REGEX(?n2, \"^[A-Z]\")) }) }";
        assert_eq!(crate::query(&g, q).unwrap().len(), 1); // Carol123
        assert_eq!(
            regex_cache::compile_count() - c0,
            2,
            "outer + EXISTS-nested pattern compile once each across the re-entry"
        );
    }

    // ---- (B) RAND() thread-local PRNG -------------------------------------------

    /// RAND() stays non-deterministic per SPARQL: every call yields a fresh
    /// `xsd:double` in [0, 1), and two separate executions do not repeat.
    #[test]
    fn rand_fresh_per_call_in_unit_range() {
        let g = wide_graph(100);
        let q = "SELECT ?r WHERE { ?s <http://ex/p> ?o BIND(RAND() AS ?r) }";
        let r = crate::query(&g, q).unwrap();
        assert_eq!(r.len(), 100);
        let mut seen = std::collections::HashSet::new();
        for row in &r.rows {
            let Some(Term::Literal(l)) = &row[0] else { panic!("RAND() must bind a literal") };
            assert_eq!(l.datatype(), xsd::DOUBLE);
            let v: f64 = l.value().parse().expect("xsd:double lexical");
            assert!((0.0..1.0).contains(&v), "RAND() out of [0,1): {v}");
            seen.insert(l.value().to_string());
        }
        // splitmix64 collides over 100 draws with probability ~2^-46; a constant
        // or repeating stream (the failure mode this guards) collapses `seen`.
        assert!(seen.len() >= 99, "RAND() must draw fresh per call; got {} distinct of 100", seen.len());
        // Distinct executions draw from fresh state too (collision odds ~2^-53).
        let one = |q: &str| crate::query(&g, q).unwrap().rows[0][0].clone();
        assert_ne!(
            one("SELECT ?r WHERE { ?s <http://ex/p> ?o BIND(RAND() AS ?r) } LIMIT 1"),
            one("SELECT ?r WHERE { ?s <http://ex/p> ?o BIND(RAND() AS ?r) } LIMIT 1"),
            "RAND() must not repeat across executions"
        );
    }

    /// DENY-list guard (the memoisation-policy block in `eval_function_inner`):
    /// every non-deterministic builtin — UUID(), STRUUID(), no-arg BNODE() —
    /// must yield a FRESH value on every call. A value-keyed memo wired around
    /// any of them (they take zero arguments, so a memo collapses ALL calls to
    /// one value) fails this immediately: all 50 rows would bind one term.
    #[test]
    fn nondeterministic_builtins_fresh_per_call_never_memoised() {
        let g = wide_graph(50);
        for (expr, what) in
            [("UUID()", "UUID"), ("STRUUID()", "STRUUID"), ("BNODE()", "no-arg BNODE")]
        {
            let q = format!("SELECT ?v WHERE {{ ?s <http://ex/p> ?o BIND({expr} AS ?v) }}");
            let r = crate::query(&g, &q).unwrap();
            assert_eq!(r.len(), 50);
            let distinct: std::collections::HashSet<String> =
                r.rows.iter().map(|row| row[0].clone().unwrap().to_string()).collect();
            assert_eq!(distinct.len(), 50, "{what} must be fresh per call, never memoised");
        }
    }

    // ---- (C) NOW() query-constancy (SPARQL 1.1 §17.4.5.1) -----------------------

    /// Deterministic guard mechanics (no clock dependence): outermost-wins
    /// nesting, worker-guard restore, clear on the OUTERMOST drop only.
    #[test]
    fn query_now_scope_mechanics() {
        assert_eq!(query_now::snapshot(), None);
        let g1 = query_now::scope();
        let v = query_now::snapshot().expect("outermost scope samples the clock");
        {
            let g2 = query_now::scope(); // nested (sub-select / EXISTS re-entry)
            assert_eq!(query_now::snapshot(), Some(v), "nested scope keeps the outer instant");
            drop(g2);
            assert_eq!(query_now::snapshot(), Some(v), "nested drop must NOT clear the outer instant");
        }
        {
            let w = query_now::worker_install(Some(v + 999));
            assert_eq!(query_now::snapshot(), Some(v + 999));
            drop(w);
            assert_eq!(query_now::snapshot(), Some(v), "worker guard restores the previous instant");
        }
        drop(g1);
        assert_eq!(query_now::snapshot(), None, "outermost drop clears: the next execution re-samples");
    }

    /// A sleeping extension function forces a REAL ≥1 s clock advance INSIDE one
    /// execution between two NOW() evaluations — they must still be equal (before
    /// this fix each evaluation re-read the clock, so the seconds differed and
    /// this test fails). A separate execution afterwards necessarily lands in a
    /// LATER second, proving the pinned instant does not leak across executions.
    #[test]
    fn now_constant_within_execution_fresh_across_executions() {
        let g = Graph::load_str("<http://ex/s> <http://ex/p> <http://ex/o> .", "turtle").unwrap();
        let mut reg = crate::FunctionRegistry::new();
        reg.register("http://test/sleep", |_args: &[Term]| {
            std::thread::sleep(std::time::Duration::from_millis(1200));
            Ok(Term::Literal(Literal::new_typed_literal("true", xsd::BOOLEAN)))
        });
        let q = "SELECT ?a ?b WHERE { ?s ?p ?o BIND(NOW() AS ?a) \
                 BIND(<http://test/sleep>() AS ?x) BIND(NOW() AS ?b) }";
        let r = crate::query_with_functions(&g, q, &reg).unwrap();
        assert_eq!(r.len(), 1);
        let (a, b) = (r.rows[0][0].clone().unwrap(), r.rows[0][1].clone().unwrap());
        assert_eq!(a, b, "NOW() must be constant across a >=1s in-execution clock advance");
        // This execution starts >=1.2s after the first one PINNED its instant, so
        // its whole-second lexical is strictly later — a stale thread-local NOW
        // reused across queries would return `a` here.
        let r2 = crate::query(&g, "SELECT ?n WHERE { ?s ?p ?o BIND(NOW() AS ?n) }").unwrap();
        assert_ne!(r2.rows[0][0].clone().unwrap(), a, "a NEW execution must sample a NEW instant");
    }

    /// EXISTS re-entry across a REAL clock tick. The EXISTS body sleeps >=1.2s and
    /// evaluates `NOW()` inside its own FILTER expression path, so the nested
    /// evaluation re-enters expression handling ON THE SAME THREAD while the outer
    /// execution's instant is still pinned. `?a` (`NOW()` from BEFORE the EXISTS)
    /// must therefore equal `?b` (`NOW()` from AFTER the EXISTS returns, >=1.2s of
    /// real time later): a single pinned instant survives the whole
    /// EXISTS-inclusive execution. Pre-fix, `?a` and `?b` re-read the clock and
    /// land in different whole seconds.
    ///
    /// The EXISTS is CORRELATED on `?s` (a shared BOUND variable), so it runs the
    /// per-row `eval_graph_pattern` re-entry rather than the uncorrelated ASK fast
    /// path — the branch that actually re-enters expression evaluation for the
    /// inner `NOW()`. An outer-only variable is deliberately NOT referenced inside
    /// the EXISTS (spargebra does not substitute it into the inner scope).
    #[test]
    fn now_exists_reentry_same_instant() {
        let g = Graph::load_str("<http://ex/s> <http://ex/p> <http://ex/o> .", "turtle").unwrap();
        let mut reg = crate::FunctionRegistry::new();
        reg.register("http://test/sleep", |_args: &[Term]| {
            std::thread::sleep(std::time::Duration::from_millis(1200));
            Ok(Term::Literal(Literal::new_typed_literal("true", xsd::BOOLEAN)))
        });
        let q = "SELECT ?a ?b WHERE { ?s ?p ?o BIND(NOW() AS ?a) \
                 FILTER EXISTS { ?s ?p ?o2 BIND(<http://test/sleep>() AS ?x) FILTER(STR(NOW()) = STR(NOW())) } \
                 BIND(NOW() AS ?b) }";
        let r = crate::query_with_functions(&g, q, &reg).unwrap();
        assert_eq!(r.len(), 1);
        let (a, b) = (r.rows[0][0].clone().unwrap(), r.rows[0][1].clone().unwrap());
        assert_eq!(a, b, "NOW() before and after a >=1.2s EXISTS re-entry must be the SAME pinned instant");
    }

    /// Parallel-threshold row count: a single NOW() instant across ALL rows AND a
    /// zero un-scoped-fallback delta. The fallback counter is what makes this
    /// non-vacuous at whole-second clock granularity: without the rayon
    /// `worker_install` wiring the workers' evaluations fall back to fresh clock
    /// samples and the counter goes hot even when every sample lands in the same
    /// second.
    // [OPUS-4.8] (sq-98w7z.1) Gated on `parallel`: the test's whole point is the rayon
    // `worker_install` NOW-snapshot wiring, and it references `PAR_THRESHOLD` — both of which only
    // exist under the `parallel` feature. Without it there is no worker path to guard and the
    // constant reference would not compile (feature-OFF clippy caught this).
    #[cfg(feature = "parallel")]
    #[test]
    fn now_parallel_rows_single_instant_no_fallback() {
        use std::sync::atomic::Ordering;
        // Just past PAR_THRESHOLD: the FILTER/BIND parallel branches activate on a
        // `>= PAR_THRESHOLD` row count (independent of per-row cost), so a thin
        // over-threshold graph exercises the exact rayon worker paths this test
        // guards while staying cheap on a contended box. `+ 200` keeps a healthy
        // margin so the branch fires deterministically.
        let rows = PAR_THRESHOLD + 200;
        let g = wide_graph(rows);
        let f0 = query_now::UNSCOPED_FALLBACKS.load(Ordering::Relaxed);
        let q = "SELECT ?n WHERE { ?s <http://ex/p> ?o BIND(NOW() AS ?n) FILTER(STR(?n) = STR(NOW())) }";
        let r = crate::query(&g, q).unwrap();
        assert_eq!(r.len(), rows, "every row's FILTER NOW() must equal its BIND NOW()");
        let mut distinct = std::collections::HashSet::new();
        for row in &r.rows {
            distinct.insert(row[0].clone().unwrap().to_string());
        }
        assert_eq!(distinct.len(), 1, "NOW() must be one instant across all rows");
        assert_eq!(
            query_now::UNSCOPED_FALLBACKS.load(Ordering::Relaxed) - f0,
            0,
            "no evaluation path may fall back to an un-pinned clock sample"
        );
    }
}

/// [OPUS-4.8] sq-6qkq — per-builtin ERROR-PATH table test.
///
/// The happy-path suite above (`function_tests`) only proves builtins compute the
/// right value on WELL-TYPED input. This module is the systematic complement: one
/// table ROW per SPARQL builtin, each carrying up to three probes — `valid` (a
/// well-typed call → the EXACT expected term, a sanity anchor), `type_err` (a
/// wrong-typed argument → the engine's expression-error outcome), and `boundary` (a
/// meaningful edge input → the EXACT expected term, where one exists).
///
/// HOW AN EXPRESSION ERROR IS OBSERVED. SPARQL has no first-class "error value" a
/// SELECT can surface; an expression error manifests structurally. We BIND the probe
/// in `SELECT ?out WHERE { ?s :p ?o BIND(<EXPR> AS ?out) }` over a single-row graph:
/// `extend_bindings` evaluates the expression and, on `Value::Error`/`Value::Unbound`,
/// resolves it to `NO_ID` → the row is KEPT but `?out` projects as `None` (unbound).
/// So the contract is precise and machine-checkable: a VALID/BOUNDARY probe yields
/// exactly one row with `?out = Some(expected term)`, and a TYPE-ERROR probe yields
/// exactly one row with `?out = None` (unbound). This is the SAME `Value::Error`
/// convention asserted lexically by `lib.rs::relational_type_error_semantics` and
/// `logical_error_propagation_and_short_circuit` via FILTER row-drops; here we read the
/// BIND column back so a row can assert BOTH a concrete value AND the unbound-on-error
/// outcome in one shape.
///
/// SPEC, NOT BUG-FOR-BUG. The probes encode the SPARQL 1.1 / 1.2 SPEC-correct
/// outcome. Where the engine diverged (STRLEN / ENCODE_FOR_URI / LANGMATCHES wrongly
/// `STR()`-coerced an IRI/number instead of erroring), the divergence was FIXED in the
/// dispatch above (see the `[OPUS-4.8]` arms) so these rows pass on the corrected
/// behaviour; a row that the engine cannot yet satisfy correctly would be `#[ignore]`d
/// with a comment + a filed bead rather than asserting the wrong value as "expected".
///
/// The table shape (a variant-indexed list of probes, driven once) mirrors
/// `sparq-zk-compose/tests/forge_gates.rs`'s gate-indexed map.
#[cfg(test)]
mod builtin_error_paths {
    use super::*;

    // A datetime IRI written out long-hand keeps the probe strings readable.
    const DT: &str = "^^<http://www.w3.org/2001/XMLSchema#dateTime>";

    /// One BUILTIN's probes. `valid`/`boundary` carry the EXACT expected term in
    /// `Term::to_string()` form (e.g. `"3"^^<…integer>`, `<http://ex/x>`, `"ab"@en`);
    /// `None` boundary means "no distinct boundary case for this builtin".
    struct Row {
        /// The `spargebra::algebra::Function` variant under test (documentation +
        /// stable label for failures; the SPARQL keyword in the probe selects it).
        builtin: &'static str,
        /// Well-typed call → expected term string.
        valid: (&'static str, &'static str),
        /// Wrong-typed call → MUST be an expression error (unbound `?out`).
        type_err: &'static str,
        /// Optional edge case → expected term string.
        boundary: Option<(&'static str, &'static str)>,
    }

    /// Single-row dataset: `?s = ex:s`, `?o = ex:o`. Probes that need a typed datum
    /// embed their own literal; `?o` exists only so the BGP yields exactly one row.
    fn one_row_graph() -> Graph {
        Graph::load_str("<http://ex/s> <http://ex/p> <http://ex/o> .", "ntriples").unwrap()
    }

    /// Evaluate `BIND(<expr> AS ?out)` over the one-row graph and return the single
    /// row's `?out`: `Some(term-string)` when bound, `None` when the expression
    /// errored (unbound). Panics if the row count is not exactly 1 (a BIND must never
    /// add or drop rows — that would be a different bug than the value under test).
    fn bind_out(g: &Graph, expr: &str) -> Option<String> {
        let q = format!("SELECT ?out WHERE {{ ?s <http://ex/p> ?o BIND({expr} AS ?out) }}");
        let r = crate::query(g, &q).unwrap_or_else(|e| panic!("query failed for `{expr}`: {e}"));
        assert_eq!(r.rows.len(), 1, "BIND must keep exactly one row for `{expr}`, got {}", r.rows.len());
        r.rows[0][0].as_ref().map(|t| t.to_string())
    }

    /// Drive every probe in `table`, accumulating ALL mismatches before failing so a
    /// single run reports the full divergence set (not just the first).
    fn run_table(table: &[Row]) {
        let g = one_row_graph();
        let mut fails: Vec<String> = Vec::new();
        let mut valid_n = 0usize;
        let mut err_n = 0usize;
        let mut bound_n = 0usize;
        for row in table {
            // (a) VALID — exact value.
            let (vexpr, vexp) = row.valid;
            match bind_out(&g, vexpr) {
                Some(got) if got == vexp => valid_n += 1,
                got => fails.push(format!("[{}] VALID `{vexpr}`: expected Some({vexp:?}), got {got:?}", row.builtin)),
            }
            // (b) TYPE ERROR — must be unbound (the engine's expression-error outcome).
            match bind_out(&g, row.type_err) {
                None => err_n += 1,
                Some(got) => fails.push(format!(
                    "[{}] TYPE-ERROR `{}`: expected an expression error (unbound ?out), got Some({got:?})",
                    row.builtin, row.type_err
                )),
            }
            // (c) BOUNDARY — exact value, when the builtin has a meaningful edge.
            if let Some((bexpr, bexp)) = row.boundary {
                match bind_out(&g, bexpr) {
                    Some(got) if got == bexp => bound_n += 1,
                    got => fails.push(format!("[{}] BOUNDARY `{bexpr}`: expected Some({bexp:?}), got {got:?}", row.builtin)),
                }
            }
        }
        assert!(
            fails.is_empty(),
            "{} builtin error-path probe(s) diverged from the SPARQL spec:\n  {}",
            fails.len(),
            fails.join("\n  ")
        );
        // The counts double as a coverage assertion: if a row is added/removed the
        // numbers move, so an accidental no-op table can't pass silently.
        eprintln!("builtin_error_paths: {} builtins, valid={valid_n} type_err={err_n} boundary={bound_n}", table.len());
    }

    const INT: &str = "^^<http://www.w3.org/2001/XMLSchema#integer>";
    const BOOL: &str = "^^<http://www.w3.org/2001/XMLSchema#boolean>";

    /// STRING builtins whose operand(s) must be STRING LITERALS (simple / lang-tagged /
    /// xsd:string). An IRI / number / boolean operand is a type error.
    #[test]
    fn string_builtins() {
        // expected-term helpers as owned strings (the table holds &'static via Box::leak-free
        // const concat where possible; here we build at runtime then borrow).
        let table = vec![
            Row {
                builtin: "STR",
                // STR is the ONE string builtin that accepts ANY term (incl. IRIs/numbers):
                // so its "type error" probe is an UNBOUND operand, not a wrong type.
                valid: ("STR(123)", "\"123\""),
                type_err: "STR(?missing)",
                boundary: Some(("STR(<http://ex/o>)", "\"http://ex/o\"")),
            },
            Row {
                builtin: "STRLEN",
                valid: ("STRLEN(\"abc\")", "\"3\"^^<http://www.w3.org/2001/XMLSchema#integer>"),
                // FIXED arm: an IRI is NOT a string literal → error (was wrongly 11).
                type_err: "STRLEN(<http://ex/o>)",
                // Counts CODEPOINTS, not bytes: "é" + a combining mark style multi-byte char.
                boundary: Some(("STRLEN(\"naïve\")", "\"5\"^^<http://www.w3.org/2001/XMLSchema#integer>")),
            },
            Row {
                builtin: "UCASE",
                valid: ("UCASE(\"abc\")", "\"ABC\""),
                type_err: "UCASE(123)",
                // Language tag is preserved (simple in → simple out; tagged in → tagged out).
                boundary: Some(("UCASE(\"abc\"@en)", "\"ABC\"@en")),
            },
            Row {
                builtin: "LCASE",
                valid: ("LCASE(\"ABC\")", "\"abc\""),
                type_err: "LCASE(<http://ex/o>)",
                boundary: Some(("LCASE(\"ABC\"@en)", "\"abc\"@en")),
            },
            Row {
                builtin: "CONCAT",
                valid: ("CONCAT(\"a\", \"b\")", "\"ab\""),
                // A non-string (numeric) operand makes the whole CONCAT a type error.
                type_err: "CONCAT(\"a\", 123)",
                // Same language tag on EVERY operand → result keeps it; a mismatch → simple.
                boundary: Some(("CONCAT(\"a\"@en, \"b\"@en)", "\"ab\"@en")),
            },
            Row {
                builtin: "CONCAT (lang mismatch → simple)",
                valid: ("CONCAT(\"a\"@en, \"b\"@fr)", "\"ab\""),
                type_err: "CONCAT(\"a\"@en, <http://ex/o>)",
                boundary: None,
            },
            Row {
                builtin: "CONTAINS",
                valid: ("CONTAINS(\"abc\", \"b\")", "\"true\"^^<http://www.w3.org/2001/XMLSchema#boolean>"),
                type_err: "CONTAINS(\"abc\", 1)",
                boundary: Some(("CONTAINS(\"abc\", \"z\")", "\"false\"^^<http://www.w3.org/2001/XMLSchema#boolean>")),
            },
            Row {
                builtin: "STRSTARTS",
                valid: ("STRSTARTS(\"abc\", \"ab\")", "\"true\"^^<http://www.w3.org/2001/XMLSchema#boolean>"),
                type_err: "STRSTARTS(123, \"ab\")",
                boundary: None,
            },
            Row {
                builtin: "STRENDS",
                valid: ("STRENDS(\"abc\", \"bc\")", "\"true\"^^<http://www.w3.org/2001/XMLSchema#boolean>"),
                type_err: "STRENDS(\"abc\", 3)",
                boundary: None,
            },
            Row {
                builtin: "STRBEFORE",
                valid: ("STRBEFORE(\"abc\", \"b\")", "\"a\""),
                type_err: "STRBEFORE(\"abc\", 1)",
                // No match → the EMPTY simple literal (not an error).
                boundary: Some(("STRBEFORE(\"abc\", \"z\")", "\"\"")),
            },
            Row {
                builtin: "STRAFTER",
                valid: ("STRAFTER(\"abc\", \"a\")", "\"bc\""),
                type_err: "STRAFTER(\"abc\", 1)",
                boundary: Some(("STRAFTER(\"abc\", \"z\")", "\"\"")),
            },
            Row {
                builtin: "ENCODE_FOR_URI",
                valid: ("ENCODE_FOR_URI(\"a b\")", "\"a%20b\""),
                // FIXED arm: a number is NOT a string literal → error (was wrongly "123").
                type_err: "ENCODE_FOR_URI(123)",
                // Unreserved set (RFC 3986) passes through untouched.
                boundary: Some(("ENCODE_FOR_URI(\"A-z_0.9~\")", "\"A-z_0.9~\"")),
            },
            Row {
                builtin: "SUBSTR",
                valid: ("SUBSTR(\"hello\", 2)", "\"ello\""),
                // A non-numeric start position is a type error.
                type_err: "SUBSTR(\"hello\", \"x\")",
                // 1-indexed by codepoint; a start past the end → empty.
                boundary: Some(("SUBSTR(\"hello\", 2, 2)", "\"el\"")),
            },
            Row {
                builtin: "SUBSTR (non-numeric length)",
                valid: ("SUBSTR(\"hello\", 1, 4)", "\"hell\""),
                type_err: "SUBSTR(\"hello\", 1, \"y\")",
                boundary: None,
            },
        ];
        run_table(&table);
    }

    /// NUMERIC builtins: the operand must be numeric; a string/IRI is a type error.
    /// They PRESERVE the argument's numeric datatype.
    #[test]
    fn numeric_builtins() {
        let table = vec![
            Row {
                builtin: "ABS",
                valid: ("ABS(-3)", "\"3\"^^<http://www.w3.org/2001/XMLSchema#integer>"),
                type_err: "ABS(\"foo\")",
                boundary: Some(("ABS(0)", "\"0\"^^<http://www.w3.org/2001/XMLSchema#integer>")),
            },
            Row {
                builtin: "CEIL",
                valid: ("CEIL(2.1)", "\"3\"^^<http://www.w3.org/2001/XMLSchema#decimal>"),
                type_err: "CEIL(\"foo\")",
                boundary: Some(("CEIL(-2.1)", "\"-2\"^^<http://www.w3.org/2001/XMLSchema#decimal>")),
            },
            Row {
                builtin: "FLOOR",
                valid: ("FLOOR(2.9)", "\"2\"^^<http://www.w3.org/2001/XMLSchema#decimal>"),
                type_err: "FLOOR(<http://ex/o>)",
                boundary: Some(("FLOOR(-2.1)", "\"-3\"^^<http://www.w3.org/2001/XMLSchema#decimal>")),
            },
            Row {
                builtin: "ROUND",
                valid: ("ROUND(2.4)", "\"2\"^^<http://www.w3.org/2001/XMLSchema#decimal>"),
                type_err: "ROUND(\"foo\")",
                boundary: Some(("ROUND(2.5)", "\"3\"^^<http://www.w3.org/2001/XMLSchema#decimal>")),
            },
        ];
        run_table(&table);
        // STRLEN/CONTAINS-style probes already proved the bool/int datatype tags; here
        // the per-row datatype suffix (decimal vs integer) is the load-bearing anchor.
        let _ = (INT, BOOL, DT);
    }

    /// TYPE-TEST / accessor builtins (LANG, DATATYPE, isIRI, …) and the
    /// literal-constructors (STRDT, STRLANG, STRLANGDIR).
    #[test]
    fn term_and_constructor_builtins() {
        let table = vec![
            Row {
                builtin: "LANG",
                valid: ("LANG(\"x\"@en)", "\"en\""),
                // LANG of an IRI is a type error (LANG of a non-tagged literal is "").
                type_err: "LANG(<http://ex/o>)",
                boundary: Some(("LANG(\"x\")", "\"\"")),
            },
            Row {
                builtin: "DATATYPE",
                valid: ("DATATYPE(\"x\")", "<http://www.w3.org/2001/XMLSchema#string>"),
                type_err: "DATATYPE(<http://ex/o>)",
                boundary: Some(("DATATYPE(42)", "<http://www.w3.org/2001/XMLSchema#integer>")),
            },
            Row {
                builtin: "STRDT",
                valid: (
                    "STRDT(\"5\", <http://www.w3.org/2001/XMLSchema#integer>)",
                    "\"5\"^^<http://www.w3.org/2001/XMLSchema#integer>",
                ),
                // First arg must be a SIMPLE literal — a lang-tagged input is an error.
                type_err: "STRDT(\"5\"@en, <http://www.w3.org/2001/XMLSchema#integer>)",
                // A non-IRI second arg (a plain string) is also an error.
                boundary: None,
            },
            Row {
                builtin: "STRDT (non-IRI datatype)",
                valid: (
                    "STRDT(\"x\", <http://ex/myType>)",
                    "\"x\"^^<http://ex/myType>",
                ),
                type_err: "STRDT(\"5\", \"notaniri\")",
                boundary: None,
            },
            Row {
                builtin: "STRLANG",
                valid: ("STRLANG(\"hi\", \"en\")", "\"hi\"@en"),
                // Both args must be simple literals; a tagged first arg errors.
                type_err: "STRLANG(\"hi\"@fr, \"en\")",
                boundary: None,
            },
            Row {
                builtin: "STRLANGDIR",
                valid: ("STRLANGDIR(\"hi\", \"en\", \"ltr\")", "\"hi\"@en--ltr"),
                // The direction must be exactly "ltr"/"rtl"; anything else errors.
                type_err: "STRLANGDIR(\"hi\", \"en\", \"sideways\")",
                boundary: Some(("STRLANGDIR(\"hi\", \"en\", \"rtl\")", "\"hi\"@en--rtl")),
            },
            Row {
                builtin: "LANGMATCHES",
                valid: ("LANGMATCHES(\"en\", \"en\")", "\"true\"^^<http://www.w3.org/2001/XMLSchema#boolean>"),
                // FIXED arm: a non-string operand is a type error (was wrongly `false`).
                type_err: "LANGMATCHES(123, \"en\")",
                // "*" matches any non-empty tag.
                boundary: Some(("LANGMATCHES(\"en-GB\", \"*\")", "\"true\"^^<http://www.w3.org/2001/XMLSchema#boolean>")),
            },
            Row {
                builtin: "IRI",
                valid: ("IRI(\"http://valid/\")", "<http://valid/>"),
                // A lexical form that is not a legal IRI (contains spaces) is an error.
                type_err: "IRI(\"a b c\")",
                // An IRI argument passes through unchanged.
                boundary: Some(("IRI(<http://ex/o>)", "<http://ex/o>")),
            },
        ];
        run_table(&table);
    }

    /// DATE/TIME accessor builtins: the operand must be an xsd:dateTime; a string or
    /// number is a type error.
    #[test]
    fn datetime_builtins() {
        let valid_dt = "\"2024-03-15T13:45:30\"";
        let mk = |kw: &str, exp: &str, ty: &str| Row {
            builtin: Box::leak(kw.to_string().into_boxed_str()),
            valid: (
                Box::leak(format!("{kw}({valid_dt}{DT})").into_boxed_str()),
                Box::leak(format!("\"{exp}\"^^<http://www.w3.org/2001/XMLSchema#{ty}>").into_boxed_str()),
            ),
            type_err: Box::leak(format!("{kw}(\"foo\")").into_boxed_str()),
            boundary: None,
        };
        let table = vec![
            mk("YEAR", "2024", "integer"),
            mk("MONTH", "3", "integer"),
            mk("DAY", "15", "integer"),
            mk("HOURS", "13", "integer"),
            mk("MINUTES", "45", "integer"),
            mk("SECONDS", "30", "decimal"),
            Row {
                builtin: "TZ",
                // No timezone in the lexical form → empty simple literal (NOT an error).
                valid: (Box::leak(format!("TZ({valid_dt}{DT})").into_boxed_str()), "\"\""),
                type_err: "TZ(\"foo\")",
                boundary: Some((
                    Box::leak(format!("TZ(\"2024-03-15T13:45:30Z\"{DT})").into_boxed_str()),
                    "\"Z\"",
                )),
            },
            Row {
                builtin: "TIMEZONE",
                // TIMEZONE on a dateTime WITHOUT a timezone is a type error (unlike TZ).
                valid: (
                    Box::leak(format!("TIMEZONE(\"2024-03-15T13:45:30Z\"{DT})").into_boxed_str()),
                    "\"PT0S\"^^<http://www.w3.org/2001/XMLSchema#dayTimeDuration>",
                ),
                type_err: Box::leak(format!("TIMEZONE({valid_dt}{DT})").into_boxed_str()),
                boundary: Some((
                    Box::leak(format!("TIMEZONE(\"2024-03-15T13:45:30+05:00\"{DT})").into_boxed_str()),
                    "\"PT5H\"^^<http://www.w3.org/2001/XMLSchema#dayTimeDuration>",
                )),
            },
        ];
        run_table(&table);
    }

    /// HASH builtins (feature `digest`): the operand must be a simple literal /
    /// xsd:string; a number or IRI is a type error. Output is lowercase hex.
    #[cfg(feature = "digest")]
    #[test]
    fn hash_builtins() {
        // Known vectors for the empty string and "abc".
        let table = vec![
            Row {
                builtin: "MD5",
                valid: ("MD5(\"abc\")", "\"900150983cd24fb0d6963f7d28e17f72\""),
                type_err: "MD5(123)",
                boundary: Some(("MD5(\"\")", "\"d41d8cd98f00b204e9800998ecf8427e\"")),
            },
            Row {
                builtin: "SHA1",
                valid: ("SHA1(\"abc\")", "\"a9993e364706816aba3e25717850c26c9cd0d89d\""),
                type_err: "SHA1(<http://ex/o>)",
                boundary: None,
            },
            Row {
                builtin: "SHA256",
                valid: (
                    "SHA256(\"abc\")",
                    "\"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad\"",
                ),
                type_err: "SHA256(123)",
                boundary: None,
            },
            Row {
                builtin: "SHA384",
                valid: (
                    "SHA384(\"abc\")",
                    "\"cb00753f45a35e8bb5a03d699ac65007272c32ab0eded1631a8b605a43ff5bed8086072ba1e7cc2358baeca134c825a7\"",
                ),
                type_err: "SHA384(<http://ex/o>)",
                boundary: None,
            },
            Row {
                builtin: "SHA512",
                valid: (
                    "SHA512(\"abc\")",
                    "\"ddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a2192992a274fc1a836ba3c23a3feebbd454d4423643ce80e2a9ac94fa54ca49f\"",
                ),
                type_err: "SHA512(42)",
                boundary: None,
            },
        ];
        run_table(&table);
    }

    /// REGEX / REPLACE (feature `regex`): the TEXT operand must be a string literal;
    /// a malformed pattern OR an illegal flags string is a type error.
    #[cfg(feature = "regex")]
    #[test]
    fn regex_builtins() {
        let table = vec![
            Row {
                builtin: "REGEX",
                valid: ("REGEX(\"abc\", \"^a\")", "\"true\"^^<http://www.w3.org/2001/XMLSchema#boolean>"),
                // A non-string text operand is a type error.
                type_err: "REGEX(123, \"a\")",
                // Case-insensitive flag.
                boundary: Some(("REGEX(\"ABC\", \"abc\", \"i\")", "\"true\"^^<http://www.w3.org/2001/XMLSchema#boolean>")),
            },
            Row {
                builtin: "REGEX (malformed pattern)",
                valid: ("REGEX(\"abc\", \"[a-c]\")", "\"true\"^^<http://www.w3.org/2001/XMLSchema#boolean>"),
                // An unclosed character class is a compile error → expression error.
                type_err: "REGEX(\"abc\", \"[\")",
                boundary: None,
            },
            Row {
                builtin: "REGEX (illegal flag)",
                valid: ("REGEX(\"abc\", \"a\", \"i\")", "\"true\"^^<http://www.w3.org/2001/XMLSchema#boolean>"),
                // 'z' is not a SPARQL/XPath regex flag → error.
                type_err: "REGEX(\"abc\", \"a\", \"z\")",
                boundary: None,
            },
            Row {
                builtin: "REPLACE",
                valid: ("REPLACE(\"abc\", \"b\", \"X\")", "\"aXc\""),
                type_err: "REPLACE(123, \"a\", \"X\")",
                // Keeps the text's language tag.
                boundary: Some(("REPLACE(\"abc\"@en, \"b\", \"X\")", "\"aXc\"@en")),
            },
            Row {
                builtin: "REPLACE (malformed pattern)",
                valid: ("REPLACE(\"abc\", \"a\", \"X\")", "\"Xbc\""),
                type_err: "REPLACE(\"abc\", \"[\", \"X\")",
                boundary: None,
            },
        ];
        run_table(&table);
    }
}

#[cfg(test)]
mod path_tests {
    use super::*;

    // Chain a -p-> b -p-> c -p-> d, plus a -q-> x.
    fn g() -> Graph {
        Graph::load_str(
            "@prefix : <http://ex/> .\n:a :p :b . :b :p :c . :c :p :d . :a :q :x .\n",
            "turtle",
        )
        .unwrap()
    }
    fn n(sparql: &str) -> usize {
        crate::query(&g(), sparql).unwrap().len()
    }
    const PFX: &str = "PREFIX : <http://ex/> ";

    #[test]
    fn property_paths() {
        let n = |q: &str| n(&format!("{PFX}{q}"));
        // OneOrMore (transitive): all reachable pairs over the chain = C(4,2) = 6.
        assert_eq!(n("SELECT ?x ?y WHERE { ?x :p+ ?y }"), 6);
        assert_eq!(n("SELECT ?y WHERE { :a :p+ ?y }"), 3); // b,c,d
        // ZeroOrMore adds reflexive self-match: a,b,c,d.
        assert_eq!(n("SELECT ?y WHERE { :a :p* ?y }"), 4);
        // Sequence / Alternative / ZeroOrOne.
        assert_eq!(n("SELECT ?y WHERE { :a :p/:p ?y }"), 1); // c
        assert_eq!(n("SELECT ?y WHERE { :a :p|:q ?y }"), 2); // b, x
        assert_eq!(n("SELECT ?y WHERE { :a :p? ?y }"), 2); // a (zero), b (one)
        // Reverse (inverse), incl. inverse-transitive.
        assert_eq!(n("SELECT ?x WHERE { :d ^:p ?x }"), 1); // c
        assert_eq!(n("SELECT ?x WHERE { :d ^:p+ ?x }"), 3); // c,b,a
        // NegatedPropertySet: edges not via :p  ->  only a -q-> x.
        assert_eq!(n("SELECT ?x ?y WHERE { ?x !:p ?y }"), 1);
    }

    #[test]
    fn named_graphs() {
        // One default-graph triple + two named graphs (g1 has 2, g2 has 1).
        let nq = "<http://ex/a> <http://ex/p> <http://ex/x> .\n\
                  <http://ex/b> <http://ex/p> <http://ex/y> <http://ex/g1> .\n\
                  <http://ex/c> <http://ex/p> <http://ex/z> <http://ex/g1> .\n\
                  <http://ex/d> <http://ex/p> <http://ex/w> <http://ex/g2> .\n";
        let g = Graph::load_dataset(nq, "nquads").unwrap();
        let n = |q: &str| crate::query(&g, q).unwrap().len();
        // The default graph holds ONLY default triples (named graphs are not folded in).
        assert_eq!(n("SELECT * WHERE { ?s ?p ?o }"), 1);
        assert_eq!(n("SELECT * WHERE { GRAPH <http://ex/g1> { ?s ?p ?o } }"), 2);
        assert_eq!(n("SELECT * WHERE { GRAPH <http://ex/g2> { ?s ?p ?o } }"), 1);
        // GRAPH ?g ranges over both named graphs (3 triples), binding ?g; an absent graph -> 0.
        assert_eq!(n("SELECT ?g ?s WHERE { GRAPH ?g { ?s ?p ?o } }"), 3);
        assert_eq!(n("SELECT * WHERE { GRAPH <http://ex/absent> { ?s ?p ?o } }"), 0);
        // Result ids are translated to the outer dict, so a join across GRAPH works.
        assert_eq!(n("SELECT ?o WHERE { GRAPH ?g { <http://ex/b> <http://ex/p> ?o } }"), 1);
    }

    /// [OPUS-4.8] (sq-zz8z, gh-51) The graph-IRI prefix range-scan index must return EXACTLY the
    /// graphs a full scan + `STRSTARTS(STR(?g), prefix)` keeps. We assert this two ways: (1) the
    /// indexed query result equals a hand-computed oracle over the known graph set, and (2) it
    /// equals the core range-scan API — across the edge cases the bead calls out (empty prefix,
    /// no-match, exact-match, prefix-is-a-substring of another graph's IRI, percent-encoding).
    mod graph_prefix_index {
        use super::*;
        use std::collections::BTreeSet;

        // Graphs across three tenants + a couple of adversarial IRIs:
        //   tenantA/g/0, tenantA/g/1, tenantA/g/10   (note: "tenantA/g/1" is a PREFIX of ".../10")
        //   tenantB/g/0
        //   tenantAB/g/0                              ("tenantA" is a PREFIX of "tenantAB")
        //   has%20space/g/0                           (percent-encoding edge case)
        const ALL: [&str; 6] = [
            "http://ex/tenantA/g/0",
            "http://ex/tenantA/g/1",
            "http://ex/tenantA/g/10",
            "http://ex/tenantB/g/0",
            "http://ex/tenantAB/g/0",
            "http://ex/has%20space/g/0",
        ];

        fn ds() -> Graph {
            let mut nq = String::new();
            for (i, g) in ALL.iter().enumerate() {
                // each graph carries one :size triple so SUM(?size)/COUNT are non-trivial
                nq.push_str(&format!(
                    "<http://ex/s{i}> <http://ex/size> \"{}\"^^<http://www.w3.org/2001/XMLSchema#integer> <{g}> .\n",
                    (i + 1) * 10
                ));
            }
            Graph::load_dataset(&nq, "nquads").unwrap()
        }

        // The set of graph IRIs the indexed `GRAPH ?g … FILTER(STRSTARTS(STR(?g),prefix))` returns.
        fn indexed_graphs(g: &Graph, prefix: &str) -> BTreeSet<String> {
            let q = format!(
                "SELECT ?g WHERE {{ GRAPH ?g {{ ?s ?p ?o }} FILTER(STRSTARTS(STR(?g), \"{prefix}\")) }}"
            );
            let r = crate::query(g, &q).unwrap();
            let mut s = BTreeSet::new();
            for row in &r.rows {
                if let Some(Term::NamedNode(n)) = row.first().and_then(|c| c.as_ref()) {
                    s.insert(n.as_str().to_string());
                }
            }
            s
        }

        // Oracle: STRSTARTS over the literal IRI set, computed in plain Rust.
        fn oracle(prefix: &str) -> BTreeSet<String> {
            ALL.iter().filter(|g| g.starts_with(prefix)).map(|s| s.to_string()).collect()
        }

        // Core API range scan, directly: the set the index yields for a prefix.
        fn core_index_graphs(g: &Graph, prefix: &str) -> BTreeSet<String> {
            let mut s = BTreeSet::new();
            g.for_named_graphs_with_prefix(prefix, |name, _| {
                if let Term::NamedNode(n) = name {
                    s.insert(n.as_str().to_string());
                }
            });
            s
        }

        #[test]
        fn indexed_matches_oracle_across_edge_cases() {
            let g = ds();
            let prefixes = [
                "",                          // empty: matches every graph
                "http://ex/tenantA",         // matches tenantA/* AND tenantAB/* (prefix of prefix)
                "http://ex/tenantA/",        // matches only tenantA/* (the slash excludes tenantAB)
                "http://ex/tenantA/g/1",     // exact-prefix that is itself a substring of .../10
                "http://ex/tenantA/g/10",    // exact match of one graph IRI
                "http://ex/tenantB/",        // single tenant
                "http://ex/tenantC/",        // NO match
                "http://ex/has%20space/",    // percent-encoded IRI
                "zzz-nonexistent",           // no match, sorts after everything
                "http://ex/",                // common ancestor: all six
            ];
            for p in prefixes {
                let idx = indexed_graphs(&g, p);
                let orc = oracle(p);
                assert_eq!(idx, orc, "indexed result != oracle for prefix {p:?}");
                // The core range-scan API agrees with the oracle too (the index itself, not just
                // the engine wiring).
                assert_eq!(core_index_graphs(&g, p), orc, "core index != oracle for prefix {p:?}");
            }
        }

        #[test]
        fn aggregate_sum_count_is_prefix_scoped() {
            // The PSS `usage(prefix)` shape: SUM(?size) + COUNT(DISTINCT ?g), prefix-scoped.
            let g = ds();
            let usage = |prefix: &str| -> (i64, usize) {
                let q = format!(
                    "SELECT (SUM(?size) AS ?bytes) (COUNT(DISTINCT ?g) AS ?n) WHERE {{ \
                     GRAPH ?g {{ ?s <http://ex/size> ?size }} FILTER(STRSTARTS(STR(?g), \"{prefix}\")) }}"
                );
                let r = crate::query(&g, &q).unwrap();
                let row = &r.rows[0];
                let bytes = match row[0].as_ref() {
                    Some(Term::Literal(l)) => l.value().parse::<i64>().unwrap(),
                    _ => 0,
                };
                let n = match row[1].as_ref() {
                    Some(Term::Literal(l)) => l.value().parse::<usize>().unwrap(),
                    _ => 0,
                };
                (bytes, n)
            };
            // tenantA/* = graphs at indices 0,1,2 with sizes 10,20,30 = 60, count 3.
            assert_eq!(usage("http://ex/tenantA/"), (60, 3));
            // tenantA (no slash) also catches tenantAB (index 4, size 50) -> 110, count 4.
            assert_eq!(usage("http://ex/tenantA"), (110, 4));
            // tenantB/* = index 3, size 40 -> (40, 1).
            assert_eq!(usage("http://ex/tenantB/"), (40, 1));
            // no match -> COUNT of empty group is 0.
            let r = crate::query(
                &g,
                "SELECT (COUNT(DISTINCT ?g) AS ?n) WHERE { GRAPH ?g { ?s ?p ?o } FILTER(STRSTARTS(STR(?g), \"http://ex/tenantC/\")) }",
            )
            .unwrap();
            let n = match r.rows[0][0].as_ref() {
                Some(Term::Literal(l)) => l.value().parse::<usize>().unwrap(),
                _ => 0,
            };
            assert_eq!(n, 0);
        }

        #[test]
        fn index_stays_correct_after_mutation_changes_graph_set() {
            // `update` returns a NEW graph (fresh prefix-index cache); the mutated set must scan
            // correctly even though the count changed twice. (Same-object cache coherence is
            // covered by the sparq-core test `graph_prefix_range_scan_and_cache_coherence`.)
            let g = ds();
            assert_eq!(indexed_graphs(&g, "http://ex/tenantA/").len(), 3);
            // Drop tenantA/g/10, add tenantA/g/2 -> still a tenantA/* set, but a different one.
            let g = crate::update::update(&g, "DROP GRAPH <http://ex/tenantA/g/10>").unwrap();
            let g = crate::update::update(
                &g,
                "INSERT DATA { GRAPH <http://ex/tenantA/g/2> { <http://ex/x> <http://ex/p> <http://ex/y> } }",
            )
            .unwrap();
            let got = indexed_graphs(&g, "http://ex/tenantA/");
            let want: BTreeSet<String> = ["http://ex/tenantA/g/0", "http://ex/tenantA/g/1", "http://ex/tenantA/g/2"]
                .iter()
                .map(|s| s.to_string())
                .collect();
            assert_eq!(got, want);
        }
    }

    /// [OPUS-4.8] sq-wij: GRAPH-scoped zero-length property paths (`*` / `?`) must
    /// bind each node to ITSELF over the NAMED graph's node domain — and the domain
    /// must be the named graph alone, never leaking nodes from the default graph or a
    /// sibling named graph. A zero-length path inside `GRAPH <g> { … }` evaluates
    /// against `g`'s self-contained sub-`Graph`, so `graph_nodes` already sees only
    /// `g`; these tests lock that scoping in (and would catch a regression that read
    /// the default/union node set instead).
    #[test]
    fn graph_scoped_zero_length_paths() {
        use std::collections::BTreeSet;
        // g1 nodes (as subject/object): a, b, c, d  (a-p->b, c-p->d).
        // g2 nodes:                      e, f        (e-p->f).
        // default-graph nodes:           m, n        (m-p->n)  — must NOT leak into a GRAPH.
        let nq = "<http://ex/m> <http://ex/p> <http://ex/n> .\n\
                  <http://ex/a> <http://ex/p> <http://ex/b> <http://ex/g1> .\n\
                  <http://ex/c> <http://ex/p> <http://ex/d> <http://ex/g1> .\n\
                  <http://ex/e> <http://ex/p> <http://ex/f> <http://ex/g2> .\n";
        let g = Graph::load_dataset(nq, "nquads").unwrap();

        // Collect the set of local-names a query binds to ?x (subject position),
        // asserting the path solution per row is reflexive (?x == ?y) when both are
        // selected. Returns the sorted set of subject local-names.
        let diag = |q: &str| -> BTreeSet<String> {
            let r = crate::query(&g, q).unwrap();
            let xi = r.vars.iter().position(|v| v.as_str() == "x").unwrap();
            let yi = r.vars.iter().position(|v| v.as_str() == "y");
            let mut out = BTreeSet::new();
            for row in &r.rows {
                let x = row[xi].as_ref().unwrap();
                if let Some(yi) = yi {
                    // Zero-length diagonal: the two ends are the SAME term.
                    assert_eq!(&row[yi], &Some(x.clone()), "expected reflexive bind, row {row:?}");
                }
                let s = match x {
                    Term::NamedNode(n) => n.as_str().rsplit('/').next().unwrap().to_string(),
                    other => panic!("unexpected term {other:?}"),
                };
                out.insert(s);
            }
            out
        };
        let set = |items: &[&str]| items.iter().map(|s| s.to_string()).collect::<BTreeSet<_>>();
        const P: &str = "PREFIX : <http://ex/> ";

        // --- `:p*` with a VARIABLE start: reflexive over the graph domain UNION the
        //     forward closure. Inside GRAPH <g1> the domain is exactly {a,b,c,d}; the
        //     default-graph nodes m,n and g2's e,f must NOT appear. -----------------
        // `?x :p* ?x` (same var) is purely the diagonal = the node domain of g1.
        assert_eq!(
            diag(&format!("{P}SELECT ?x ?y WHERE {{ GRAPH :g1 {{ ?x :p* ?y FILTER(?x = ?y) }} }}")),
            set(&["a", "b", "c", "d"]),
            "p* diagonal inside GRAPH <g1> must be g1's nodes only"
        );
        // g2 has a disjoint domain {e,f}: the wrong (union/default) scope would leak.
        assert_eq!(
            diag(&format!("{P}SELECT ?x ?y WHERE {{ GRAPH :g2 {{ ?x :p* ?y FILTER(?x = ?y) }} }}")),
            set(&["e", "f"]),
            "p* diagonal inside GRAPH <g2> must be g2's nodes only"
        );

        // --- `:p?` (ZeroOrOne) reflexive bindings inside GRAPH: a bound start yields
        //     its own self-pair plus the one-step neighbour, scoped to the graph. ---
        // `<a> :p? ?y` in g1 -> {a (zero), b (one)}.
        let p_opt_g1: BTreeSet<String> = {
            let r = crate::query(&g, &format!("{P}SELECT ?y WHERE {{ GRAPH :g1 {{ :a :p? ?y }} }}")).unwrap();
            r.rows.iter().map(|row| match row[0].as_ref().unwrap() {
                Term::NamedNode(n) => n.as_str().rsplit('/').next().unwrap().to_string(),
                other => panic!("{other:?}"),
            }).collect()
        };
        assert_eq!(p_opt_g1, set(&["a", "b"]), ":p? in GRAPH <g1> = self + one hop");
        // `?x :p? ?x` (same var) inside GRAPH <g1>: the diagonal = g1's node domain.
        assert_eq!(
            diag(&format!("{P}SELECT ?x ?y WHERE {{ GRAPH :g1 {{ ?x :p? ?y FILTER(?x = ?y) }} }}")),
            set(&["a", "b", "c", "d"]),
            ":p? diagonal inside GRAPH <g1> must be g1's nodes only"
        );

        // --- The default graph's own zero-length diagonal is {m,n} — confirming the
        //     GRAPH scopes above genuinely excluded these nodes. -------------------
        assert_eq!(
            diag(&format!("{P}SELECT ?x ?y WHERE {{ ?x :p* ?y FILTER(?x = ?y) }}")),
            set(&["m", "n"]),
            "default-graph p* diagonal must be the default graph's nodes only"
        );

        // --- `GRAPH ?g { ?x :p* ?y FILTER(?x=?y) }`: the diagonal per named graph,
        //     unioned, binds ?g to the SOURCE graph. The full set of subjects is the
        //     union of each named graph's domain (g1 ∪ g2), never the default graph. -
        let r = crate::query(
            &g,
            &format!("{P}SELECT ?g ?x ?y WHERE {{ GRAPH ?g {{ ?x :p* ?y FILTER(?x = ?y) }} }}"),
        )
        .unwrap();
        let (gi, xi, yi) = (
            r.vars.iter().position(|v| v.as_str() == "g").unwrap(),
            r.vars.iter().position(|v| v.as_str() == "x").unwrap(),
            r.vars.iter().position(|v| v.as_str() == "y").unwrap(),
        );
        let local = |t: &Term| match t {
            Term::NamedNode(n) => n.as_str().rsplit('/').next().unwrap().to_string(),
            other => panic!("{other:?}"),
        };
        let mut pairs: BTreeSet<(String, String)> = BTreeSet::new();
        for row in &r.rows {
            assert_eq!(&row[yi], &row[xi], "GRAPH ?g p* diagonal must be reflexive");
            pairs.insert((local(row[gi].as_ref().unwrap()), local(row[xi].as_ref().unwrap())));
        }
        let expected: BTreeSet<(String, String)> = [
            ("g1", "a"), ("g1", "b"), ("g1", "c"), ("g1", "d"), ("g2", "e"), ("g2", "f"),
        ]
        .iter()
        .map(|(a, b)| (a.to_string(), b.to_string()))
        .collect();
        assert_eq!(pairs, expected, "GRAPH ?g zero-length nodes must be scoped per named graph");
    }

    #[test]
    fn rdf_star_concrete_triple_terms() {
        // RDF 1.2 triple terms load and CONCRETE `<< … >>` patterns match via the
        // STRUCTURAL dictionary encoding (component ids). Variable-inside patterns are
        // handled by BGP decomposition (sq-kbs / T6) — see the dedicated tests below.
        let g = Graph::load_str(
            "PREFIX : <http://ex/>\n<< :alice :age 30 >> :certainty 0.9 .\n<< :bob :age 25 >> :certainty 0.5 .",
            "turtle",
        )
        .unwrap();
        let n = |q: &str| crate::query(&g, q).unwrap().len();
        assert_eq!(n("PREFIX : <http://ex/> SELECT ?c WHERE { << :alice :age 30 >> :certainty ?c }"), 1);
        assert_eq!(n("PREFIX : <http://ex/> SELECT ?c WHERE { << :carol :age 99 >> :certainty ?c }"), 0);
    }

    #[test]
    fn rdf_star_structural_roundtrip_output() {
        // Loading RDF 1.2 triple-term Turtle and selecting the triple term materialises a structural
        // `Term::Triple` (oxrdf formats it as `<<( … )>>`), NOT the old canonical-string
        // literal stopgap.
        let g = Graph::load_str("PREFIX : <http://ex/>\n<< :alice :age 30 >> :certainty 0.9 .", "turtle").unwrap();
        let r = crate::query(
            &g,
            "SELECT ?t WHERE { ?r <http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies> ?t }",
        )
        .unwrap();
        assert_eq!(r.rows.len(), 1);
        let expected = Term::Triple(Box::new(oxrdf::Triple::new(
            oxrdf::NamedNode::new_unchecked("http://ex/alice"),
            oxrdf::NamedNode::new_unchecked("http://ex/age"),
            Term::Literal(Literal::new_typed_literal("30", xsd::INTEGER)),
        )));
        assert_eq!(r.rows[0][0], Some(expected));

        // SPARQL 1.2 JSON results encoding: {"type":"triple","value":{subject/predicate/object}}.
        let json = crate::query_json(
            &g,
            "SELECT ?t WHERE { ?r <http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies> ?t }",
        )
        .unwrap();
        assert!(
            json.contains(
                "{\"type\":\"triple\",\"value\":{\"subject\":{\"type\":\"uri\",\"value\":\"http://ex/alice\"},\
                 \"predicate\":{\"type\":\"uri\",\"value\":\"http://ex/age\"},\"object\":{\"type\":\"literal\",\
                 \"value\":\"30\",\"datatype\":\"http://www.w3.org/2001/XMLSchema#integer\"}}}"
            ),
            "got: {json}"
        );
    }

    #[test]
    fn rdf_star_nested_triple_terms() {
        // A triple term nests through the OBJECT position; it round-trips structurally.
        let g = Graph::load_str("PREFIX : <http://ex/>\n:x :p <<( :a :b <<( :c :d :e )>> )>> .", "turtle").unwrap();
        let r = crate::query(&g, "PREFIX : <http://ex/> SELECT ?o WHERE { :x :p ?o }").unwrap();
        assert_eq!(r.rows.len(), 1);
        let nn = oxrdf::NamedNode::new_unchecked;
        let inner = Term::Triple(Box::new(oxrdf::Triple::new(nn("http://ex/c"), nn("http://ex/d"), Term::NamedNode(nn("http://ex/e")))));
        let outer = Term::Triple(Box::new(oxrdf::Triple::new(nn("http://ex/a"), nn("http://ex/b"), inner)));
        assert_eq!(r.rows[0][0], Some(outer.clone()));
        // The concrete nested pattern matches (1) and a non-matching one misses (0).
        let n = |q: &str| crate::query(&g, q).unwrap().len();
        assert_eq!(n("PREFIX : <http://ex/> SELECT ?s WHERE { ?s :p <<( :a :b <<( :c :d :e )>> )>> }"), 1);
        assert_eq!(n("PREFIX : <http://ex/> SELECT ?s WHERE { ?s :p <<( :a :b <<( :c :d :x )>> )>> }"), 0);
    }

    #[test]
    fn rdf_star_values_ground_triple_term() {
        // A ground triple term in VALUES binds and joins against stored triple terms.
        let g = Graph::load_str("PREFIX : <http://ex/>\n<< :alice :age 30 >> :certainty 0.9 .", "turtle").unwrap();
        let n = |q: &str| crate::query(&g, q).unwrap().len();
        assert_eq!(
            n("PREFIX : <http://ex/> SELECT ?c WHERE { VALUES ?t { <<( :alice :age 30 )>> } \
               ?r <http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies> ?t . ?r :certainty ?c }"),
            1
        );
        assert_eq!(
            n("PREFIX : <http://ex/> SELECT ?c WHERE { VALUES ?t { <<( :alice :age 31 )>> } \
               ?r <http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies> ?t . ?r :certainty ?c }"),
            0
        );
    }

    #[test]
    fn rdf_star_variables_inside_quoted_patterns() {
        // F14: variables inside triple-term patterns MATCH structurally against the
        // stored triple terms, binding the inner variables.
        let g = Graph::load_str(
            "PREFIX : <http://ex/>\n<< :alice :age 30 >> :certainty 0.9 .\n<< :bob :age 25 >> :certainty 0.4 .\n:alice :name \"Alice\" .",
            "turtle",
        )
        .unwrap();
        let q = |s: &str| crate::query(&g, s).unwrap();
        // Var in the quoted subject slot.
        let r = q("PREFIX : <http://ex/> SELECT ?w ?c WHERE { << ?w :age 30 >> :certainty ?c }");
        assert_eq!(r.rows.len(), 1);
        assert!(r.rows[0][0].as_ref().unwrap().to_string().contains("alice"));
        // All slots variable: both reified statements match.
        assert_eq!(q("PREFIX : <http://ex/> SELECT * WHERE { << ?s ?p ?o >> :certainty ?c }").rows.len(), 2);
        // Inner variable JOINS with an outer pattern (alice has a name, bob does not).
        assert_eq!(
            q("PREFIX : <http://ex/> SELECT ?n WHERE { << ?w :age ?a >> :certainty ?c . ?w :name ?n }").rows.len(),
            1
        );
        // A ground component inside the quoted pattern constrains the match.
        assert_eq!(q("PREFIX : <http://ex/> SELECT ?c WHERE { << :bob :age ?a >> :certainty ?c }").rows.len(), 1);
        // No match: nothing reifies :alice :age 31.
        assert_eq!(q("PREFIX : <http://ex/> SELECT ?c WHERE { << :alice :age 31 >> :certainty ?c }").rows.len(), 0);
    }

    #[test]
    fn rdf_star_quoted_pattern_var_positions_bind() {
        // sq-kbs (T6): a variable in EACH position of a triple-term pattern binds to
        // the matching component of the stored triple term, and the bound VALUES are
        // exactly the subject/predicate/object of the reified statement.
        let g = Graph::load_str(
            "PREFIX : <http://ex/>\n\
             << :alice :age 30 >> :certainty 0.9 .\n\
             << :bob :likes :tea >> :certainty 0.4 .",
            "turtle",
        )
        .unwrap();
        let sols = |s: &str| {
            let r = crate::query(&g, s).unwrap();
            let mut out: Vec<String> = r
                .rows
                .iter()
                .map(|row| row.iter().map(|c| c.as_ref().map(|t| t.to_string()).unwrap_or_default()).collect::<Vec<_>>().join("|"))
                .collect();
            out.sort();
            out
        };
        // Variable in SUBJECT slot — binds to the reified subject.
        assert_eq!(sols("PREFIX : <http://ex/> SELECT ?s WHERE { << ?s :age 30 >> :certainty ?c }"), vec!["<http://ex/alice>"]);
        // Variable in PREDICATE slot — binds to the reified predicate.
        assert_eq!(sols("PREFIX : <http://ex/> SELECT ?p WHERE { << :alice ?p 30 >> :certainty ?c }"), vec!["<http://ex/age>"]);
        // Variable in OBJECT slot — binds to the reified object (literal preserved).
        assert_eq!(
            sols("PREFIX : <http://ex/> SELECT ?o WHERE { << :alice :age ?o >> :certainty ?c }"),
            vec!["\"30\"^^<http://www.w3.org/2001/XMLSchema#integer>"]
        );
    }

    #[test]
    fn rdf_star_quoted_pattern_ground_var_mix_filters() {
        // sq-kbs (T6): ground positions FILTER, variable positions BIND, within one
        // quoted pattern. Only the statement whose ground slots match contributes a row,
        // and the variable slot is bound to that statement's value.
        let g = Graph::load_str(
            "PREFIX : <http://ex/>\n\
             << :alice :age 30 >> :certainty 0.9 .\n\
             << :alice :age 40 >> :certainty 0.1 .\n\
             << :bob :age 30 >> :certainty 0.5 .",
            "turtle",
        )
        .unwrap();
        let q = |s: &str| crate::query(&g, s).unwrap();
        // Ground subject + ground predicate, variable object: two alice-age statements.
        let r = q("PREFIX : <http://ex/> SELECT ?o ?c WHERE { << :alice :age ?o >> :certainty ?c }");
        assert_eq!(r.rows.len(), 2);
        // Ground subject + ground object, variable predicate: exactly the :alice :age 30 row.
        let r = q("PREFIX : <http://ex/> SELECT ?c WHERE { << :alice ?p 30 >> :certainty ?c }");
        assert_eq!(r.rows.len(), 1);
        assert_eq!(r.rows[0][0].as_ref().unwrap().to_string(), "\"0.9\"^^<http://www.w3.org/2001/XMLSchema#decimal>");
        // No ground match: nothing reifies :carol :age 30.
        assert_eq!(q("PREFIX : <http://ex/> SELECT ?c WHERE { << :carol :age 30 >> :certainty ?c }").rows.len(), 0);
    }

    #[test]
    fn rdf_star_quoted_pattern_all_vars_enumerate() {
        // sq-kbs (T6): `<< ?s ?p ?o >>` enumerates EVERY stored triple term, binding all
        // three slots, and the count equals the number of distinct reified statements.
        let g = Graph::load_str(
            "PREFIX : <http://ex/>\n\
             << :alice :age 30 >> :certainty 0.9 .\n\
             << :bob :likes :tea >> :certainty 0.4 .\n\
             << :carol :age 22 >> :certainty 0.7 .\n\
             :alice :name \"Alice\" .",
            "turtle",
        )
        .unwrap();
        let r = crate::query(&g, "PREFIX : <http://ex/> SELECT ?s ?p ?o ?c WHERE { << ?s ?p ?o >> :certainty ?c }").unwrap();
        assert_eq!(r.rows.len(), 3);
        // Every row binds all four variables (no NULLs), and the subjects cover all three.
        let mut subjects: Vec<String> = r.rows.iter().map(|row| row[0].as_ref().unwrap().to_string()).collect();
        subjects.sort();
        assert_eq!(subjects, vec!["<http://ex/alice>", "<http://ex/bob>", "<http://ex/carol>"]);
        assert!(r.rows.iter().all(|row| row.iter().take(4).all(|c| c.is_some())));
    }

    #[test]
    fn rdf_star_quoted_pattern_nested_one_level() {
        // sq-kbs (T6): a triple term NESTED (one level) inside a triple-term pattern
        // unifies recursively — the inner variables bind to the inner statement's parts.
        let g = Graph::load_str(
            "PREFIX : <http://ex/>\n<< << :alice :age 30 >> :statedBy :bob >> :certainty 0.8 .",
            "turtle",
        )
        .unwrap();
        let r = crate::query(
            &g,
            "PREFIX : <http://ex/> SELECT ?who ?src WHERE { << << ?who :age 30 >> :statedBy ?src >> :certainty ?c }",
        )
        .unwrap();
        assert_eq!(r.rows.len(), 1);
        assert_eq!(r.rows[0][0].as_ref().unwrap().to_string(), "<http://ex/alice>");
        assert_eq!(r.rows[0][1].as_ref().unwrap().to_string(), "<http://ex/bob>");
    }

    #[test]
    fn rdf_star_triple_builtins() {
        // F15: TRIPLE / isTRIPLE / SUBJECT / PREDICATE / OBJECT.
        let g = Graph::load_str("PREFIX : <http://ex/>\n<< :alice :age 30 >> :certainty 0.9 .", "turtle").unwrap();
        let one = |s: &str| {
            let r = crate::query(&g, s).unwrap();
            r.rows[0][0].as_ref().map(|t| t.to_string())
        };
        assert_eq!(
            one("PREFIX : <http://ex/> SELECT (TRIPLE(:a, :b, 1) AS ?t) {}").unwrap(),
            "<<( <http://ex/a> <http://ex/b> \"1\"^^<http://www.w3.org/2001/XMLSchema#integer> )>>"
        );
        assert_eq!(one("PREFIX : <http://ex/> SELECT (isTRIPLE(TRIPLE(:a, :b, :c)) AS ?x) {}").unwrap(), "\"true\"^^<http://www.w3.org/2001/XMLSchema#boolean>");
        assert_eq!(one("PREFIX : <http://ex/> SELECT (SUBJECT(TRIPLE(:a, :b, :c)) AS ?x) {}").unwrap(), "<http://ex/a>");
        assert_eq!(one("PREFIX : <http://ex/> SELECT (PREDICATE(TRIPLE(:a, :b, :c)) AS ?x) {}").unwrap(), "<http://ex/b>");
        assert_eq!(one("PREFIX : <http://ex/> SELECT (OBJECT(TRIPLE(:a, :b, :c)) AS ?x) {}").unwrap(), "<http://ex/c>");
        // A literal subject is a type error -> unbound.
        assert_eq!(one("PREFIX : <http://ex/> SELECT (TRIPLE(1, :b, :c) AS ?t) {}"), None);
    }
}

#[cfg(test)]
mod ask_exists_tests {
    //! [OPUS-4.8] sq-rd2: ASK / EXISTS only need to know whether >= 1 solution
    //! exists. These tests pin (a) boolean CORRECTNESS for ASK and EXISTS / NOT
    //! EXISTS, and (b) that the evaluator does not OVER-EVALUATE — proven with a
    //! `max_rows` working-set budget set BELOW the full match count: full
    //! materialisation would breach it (a hard error), whereas an early-exit that
    //! stops at the first solution stays within it.
    use super::*;
    use crate::QueryBudget;

    /// A graph with `n` subjects each `:a`-typed `:Thing`, plus a `:flag true`
    /// pair, so a match set far larger than any small `max_rows` budget exists.
    fn big(n: usize) -> Graph {
        let mut nt = String::new();
        for i in 0..n {
            nt.push_str(&format!("<http://ex/s{i}> <http://ex/p> <http://ex/Thing> .\n"));
        }
        Graph::load_str(&nt, "ntriples").unwrap()
    }

    /// A `max_rows`-only budget (no deadline): the working-set bound used as the
    /// over-evaluation tripwire.
    fn rows_budget(max: usize) -> QueryBudget {
        QueryBudget { max_rows: Some(max), ..QueryBudget::unlimited() }
    }

    #[test]
    fn ask_true_false_correctness() {
        let g = Graph::load_str(
            "PREFIX : <http://ex/>\n:a :p :b . :b :p :c . :a :knows :z .",
            "turtle",
        )
        .unwrap();
        let ask = |q: &str| crate::ask(&g, &format!("PREFIX : <http://ex/> {q}")).unwrap();
        // Present / absent single pattern.
        assert!(ask("ASK { :a :p :b }"));
        assert!(!ask("ASK { :a :p :MISSING }"));
        // Variable pattern with >=1 / 0 matches.
        assert!(ask("ASK { ?s :p ?o }"));
        assert!(!ask("ASK { ?s :nosuch ?o }"));
        // Join: ?x :p ?y . ?y :p ?z  (a-p->b-p->c exists).
        assert!(ask("ASK { ?x :p ?y . ?y :p ?z }"));
        assert!(!ask("ASK { ?x :p ?y . ?y :knows ?z }")); // b/c have no :knows
        // FILTER.
        assert!(ask("ASK { ?s :p ?o FILTER(?o = :b) }"));
        assert!(!ask("ASK { ?s :p ?o FILTER(?o = :nope) }"));
    }

    #[test]
    fn exists_in_filter_correctness() {
        let g = Graph::load_str(
            "PREFIX : <http://ex/>\n\
             :a :p :b . :b :p :c . :c :p :d .\n\
             :a :flagged true . :c :flagged true .",
            "turtle",
        )
        .unwrap();
        let n = |q: &str| crate::query(&g, &format!("PREFIX : <http://ex/> {q}")).unwrap().len();
        // EXISTS: subjects that have an outgoing :p AND are :flagged -> a, c.
        assert_eq!(n("SELECT ?s WHERE { ?s :flagged true FILTER EXISTS { ?s :p ?o } }"), 2);
        // NOT EXISTS: flagged subjects with NO outgoing :p -> none (a,c both have :p).
        assert_eq!(n("SELECT ?s WHERE { ?s :flagged true FILTER NOT EXISTS { ?s :p ?o } }"), 0);
        // Correlated EXISTS that is sometimes false: subjects with a :p whose object
        // is itself :flagged -> only :b's target :c is flagged... :a-p->:b (b not
        // flagged), :b-p->:c (c flagged), :c-p->:d (d not flagged) => 1 (the b row).
        assert_eq!(n("SELECT ?s WHERE { ?s :p ?o FILTER EXISTS { ?o :flagged true } }"), 1);
        // Uncorrelated EXISTS (constant) is true once -> keeps all 3 :p subjects.
        assert_eq!(n("SELECT ?s WHERE { ?s :p ?o FILTER EXISTS { :a :flagged true } }"), 3);
        // Uncorrelated EXISTS that is false -> drops everything.
        assert_eq!(n("SELECT ?s WHERE { ?s :p ?o FILTER EXISTS { :a :flagged false } }"), 0);
    }

    #[test]
    fn ask_single_pattern_early_exit_does_not_over_evaluate() {
        // 10_000 matching triples; a working-set budget of 4 rows. A full
        // materialisation builds 10_000 rows and breaches the budget (hard error);
        // an early-exiting ASK answers from the index range size (or the first
        // solution) without ever materialising > 4 rows.
        let g = big(10_000);
        // SELECT proves the budget genuinely bites on full materialisation.
        assert!(
            crate::query_with_budget(&g, "SELECT * WHERE { ?s <http://ex/p> ?o }", &rows_budget(4)).is_err(),
            "control: full SELECT must breach the 4-row working-set budget"
        );
        // ASK must NOT breach it — it stops at the first solution / counts from the index.
        let got = crate::ask_with_budget(&g, "ASK { ?s <http://ex/p> ?o }", &rows_budget(4));
        assert_eq!(got, Ok(true), "ASK over a large single-pattern match set must early-exit, got {got:?}");
        // And a FALSE ASK over the same large store still returns cleanly (no match,
        // nothing materialised).
        assert_eq!(
            crate::ask_with_budget(&g, "ASK { ?s <http://ex/nosuch> ?o }", &rows_budget(4)),
            Ok(false)
        );
    }

    #[test]
    fn exists_early_exit_does_not_over_evaluate() {
        // The outer query binds ONE row (:probe); its FILTER EXISTS scans a
        // 10_000-row inner match set. A full inner materialisation breaches a small
        // working-set budget; an early-exiting EXISTS stops at the first inner
        // solution. (The probe is uncorrelated so any inner solution satisfies it.)
        let mut nt = String::from("<http://ex/probe> <http://ex/kind> <http://ex/q> .\n");
        for i in 0..10_000 {
            nt.push_str(&format!("<http://ex/s{i}> <http://ex/p> <http://ex/Thing> .\n"));
        }
        let g = Graph::load_str(&nt, "ntriples").unwrap();
        let q = "SELECT ?x WHERE { ?x <http://ex/kind> <http://ex/q> \
                 FILTER EXISTS { ?y <http://ex/p> <http://ex/Thing> } }";
        // Control: the inner pattern as a standalone SELECT breaches the budget.
        assert!(
            crate::query_with_budget(&g, "SELECT * WHERE { ?y <http://ex/p> <http://ex/Thing> }", &rows_budget(8)).is_err(),
            "control: the inner 10k-row scan must breach an 8-row budget"
        );
        // The full query (1 outer row, EXISTS over 10k inner): must answer true
        // WITHOUT materialising the whole inner set, so it stays within the budget.
        let got = crate::query_with_budget(&g, q, &rows_budget(8));
        assert!(
            got.as_ref().map(|r| r.len()) == Ok(1),
            "EXISTS must early-exit on the inner scan, got {got:?}"
        );
    }
}

#[cfg(test)]
mod path_pushdown_tests {
    //! Differential tests for the bound-endpoint pushdown: for every operator ×
    //! every binding shape (subject bound / object bound / both / neither /
    //! same-variable), the pushed-down evaluation must agree with the
    //! full-relation evaluation filtered after the fact — over random graphs
    //! containing cycles, diamonds, self-loops and disconnected components.
    use super::*;

    /// Random multigraph over predicates `:e` / `:f`, plus deterministic
    /// adversarial shapes: a diamond (d0→{d1,d2}→d3), a directed 3-cycle
    /// (c0→c1→c2→c0), a self-loop (s0→s0) and a disconnected island (i0→i1).
    fn random_graph(seed0: u64, n_nodes: u32, n_edges: usize) -> Graph {
        let mut seed = seed0;
        let mut next = || {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            (seed >> 33) as u32
        };
        let mut ttl = String::from("@prefix : <http://ex/> .\n");
        for _ in 0..n_edges {
            let (a, b) = (next() % n_nodes, next() % n_nodes);
            let p = if next() % 3 == 0 { "f" } else { "e" };
            ttl.push_str(&format!(":n{a} :{p} :n{b} .\n"));
        }
        ttl.push_str(":d0 :e :d1 . :d0 :e :d2 . :d1 :e :d3 . :d2 :e :d3 .\n");
        ttl.push_str(":c0 :e :c1 . :c1 :e :c2 . :c2 :e :c0 . :s0 :e :s0 .\n");
        ttl.push_str(":i0 :f :i1 .\n");
        Graph::load_str(&ttl, "turtle").unwrap()
    }

    /// Sorted row-strings of a result (paths have set semantics, order-free).
    fn rowset(r: &crate::QueryResult) -> Vec<String> {
        let mut v: Vec<String> = r
            .rows
            .iter()
            .map(|row| {
                row.iter()
                    .map(|t| t.as_ref().map(|t| t.to_string()).unwrap_or_default())
                    .collect::<Vec<_>>()
                    .join("\t")
            })
            .collect();
        v.sort();
        v.dedup();
        v
    }

    const PFX: &str = "PREFIX : <http://ex/> ";

    /// Every path operator and the compositions whose pushdown rules differ
    /// (inverse-of-recursive, recursive inside sequence on either side,
    /// alternative-of-recursive, negated sets, zero-length operators).
    const PATHS: &[&str] = &[
        ":e",
        "^:e",
        ":e+",
        ":e*",
        ":e?",
        "^:e+",
        "(^:e)+",
        ":e/:f",
        ":e/:f+",
        ":e+/:f",
        ":e+/:f+",
        ":e|:f",
        "(:e|:f)+",
        "(:e|^:f)*",
        "!:e",
        "!(:e|:f)",
        "^(:e/:f)",
        ":e*/:f?",
    ];

    /// Endpoints sampled from every adversarial shape (all exist in each graph).
    const NODES: &[&str] = &["n0", "n1", "n2", "d0", "d3", "c0", "c1", "s0", "i0", "i1"];

    #[test]
    fn pushdown_matches_full_closure_for_all_operators_and_binding_shapes() {
        for seed in [0x1111u64, 0xACE1, 0xDEADBEEF] {
            let g = random_graph(seed, 12, 40);
            for path in PATHS {
                // Reference: the full (both-unbound) relation, post-filtered here.
                let full = rowset(&crate::query(&g, &format!("{PFX}SELECT ?x ?y WHERE {{ ?x {path} ?y }}")).unwrap());
                let pairs: Vec<(String, String)> = full
                    .iter()
                    .map(|r| {
                        let (x, y) = r.split_once('\t').unwrap();
                        (x.to_string(), y.to_string())
                    })
                    .collect();
                // Same variable at both ends: the diagonal.
                let diag = rowset(&crate::query(&g, &format!("{PFX}SELECT ?x WHERE {{ ?x {path} ?x }}")).unwrap());
                let mut want_diag: Vec<String> =
                    pairs.iter().filter(|(x, y)| x == y).map(|(x, _)| x.clone()).collect();
                want_diag.sort();
                want_diag.dedup();
                assert_eq!(diag, want_diag, "same-var disagrees for `{path}` (seed {seed:#x})");
                for node in NODES {
                    let iri = format!("<http://ex/{node}>");
                    // Subject bound.
                    let got =
                        rowset(&crate::query(&g, &format!("{PFX}SELECT ?y WHERE {{ :{node} {path} ?y }}")).unwrap());
                    let mut want: Vec<String> =
                        pairs.iter().filter(|(x, _)| *x == iri).map(|(_, y)| y.clone()).collect();
                    want.sort();
                    want.dedup();
                    assert_eq!(got, want, "bound-subject :{node} disagrees for `{path}` (seed {seed:#x})");
                    // Object bound.
                    let got =
                        rowset(&crate::query(&g, &format!("{PFX}SELECT ?x WHERE {{ ?x {path} :{node} }}")).unwrap());
                    let mut want: Vec<String> =
                        pairs.iter().filter(|(_, y)| *y == iri).map(|(x, _)| x.clone()).collect();
                    want.sort();
                    want.dedup();
                    assert_eq!(got, want, "bound-object :{node} disagrees for `{path}` (seed {seed:#x})");
                }
                // Both bound: membership must match the full relation exactly.
                for (a, b) in
                    [("n0", "n1"), ("d0", "d3"), ("c0", "c0"), ("c0", "c2"), ("s0", "s0"), ("i0", "i1"), ("n0", "i0")]
                {
                    let row = format!("<http://ex/{a}>\t<http://ex/{b}>");
                    let got = crate::query(&g, &format!("{PFX}SELECT * WHERE {{ :{a} {path} :{b} }}")).unwrap();
                    assert_eq!(
                        !got.rows.is_empty(),
                        full.contains(&row),
                        "both-bound :{a}/:{b} disagrees for `{path}` (seed {seed:#x})"
                    );
                }
            }
        }
    }

    /// The negated-property-set block-skip scan must agree with an INDEPENDENT
    /// evaluation path: a plain scan + FILTER on the predicate.
    #[test]
    fn negated_property_set_matches_filter_oracle() {
        for seed in [0x5EEDu64, 0xBEEF] {
            let g = random_graph(seed, 10, 60);
            for (path, cond) in [("!:e", "?p != :e"), ("!(:e|:f)", "?p != :e && ?p != :f")] {
                let got = rowset(&crate::query(&g, &format!("{PFX}SELECT ?x ?y WHERE {{ ?x {path} ?y }}")).unwrap());
                let oracle = rowset(
                    &crate::query(
                        &g,
                        &format!("{PFX}SELECT DISTINCT ?x ?y WHERE {{ ?x ?p ?y FILTER({cond}) }}"),
                    )
                    .unwrap(),
                );
                assert_eq!(got, oracle, "`{path}` disagrees with filter oracle (seed {seed:#x})");
            }
        }
    }

    /// [OPUS-4.8] (sq-5kr) Pin the bound-endpoint shortcuts that AVOID the
    /// full-store scans: `p*`/`p?` over a bound endpoint must emit ITS reflexive
    /// pair (not the whole `graph_nodes()` domain), and a bound-endpoint `!(...)`
    /// must return only that node's non-excluded edges from the narrowed scan.
    /// The load-bearing case is a CONSTANT endpoint absent from the data
    /// (`:z`, which occurs in no triple): the zero-length rules still bind
    /// `<z> p* <z>` / `<z> p? <z>`, whereas a reflexive pass over `graph_nodes()`
    /// would never see `:z` and would WRONGLY drop the solution — so this guards
    /// against a regression to the old domain-scan reflexive logic.
    #[test]
    fn bound_endpoint_zero_length_and_negated_avoid_full_store_scan() {
        // :a -e-> :b ; :a -f-> :c .  :z occurs in NO triple.
        let g = Graph::load_str("@prefix : <http://ex/> .\n:a :e :b . :a :f :c .\n", "turtle").unwrap();
        let rows = |sparql: &str| rowset(&crate::query(&g, &format!("{PFX}{sparql}")).unwrap());
        let ask = |sparql: &str| !crate::query(&g, &format!("{PFX}{sparql}")).unwrap().rows.is_empty();
        let want = |items: &[&str]| {
            let mut v: Vec<String> = items.iter().map(|s| s.to_string()).collect();
            v.sort();
            v.dedup();
            v
        };

        // Bound-subject `p*`: reflexive self + the one `:e` hop (NOT the node domain).
        assert_eq!(rows("SELECT ?y WHERE { :a :e* ?y }"), want(&["<http://ex/a>", "<http://ex/b>"]));
        // Bound-subject `p?`: reflexive self + the one `:e` hop.
        assert_eq!(rows("SELECT ?y WHERE { :a :e? ?y }"), want(&["<http://ex/a>", "<http://ex/b>"]));
        // Constant endpoint ABSENT from the data still has its zero-length self-pair.
        assert_eq!(rows("SELECT ?y WHERE { :z :e* ?y }"), want(&["<http://ex/z>"]));
        assert!(ask("ASK WHERE { :z :e? :z }"), "absent-term :z must satisfy its own :e? self-pair");
        // Bound-subject negated set: only :a's non-:e edges (the :f hop), narrowed scan.
        assert_eq!(rows("SELECT ?y WHERE { :a !:e ?y }"), want(&["<http://ex/c>"]));
        // Bound-OBJECT negated set: subjects reaching :c via a non-:e predicate (:a -f-> :c).
        assert_eq!(rows("SELECT ?x WHERE { ?x !:e :c }"), want(&["<http://ex/a>"]));
    }

    /// The row budget must fire INSIDE a single-source traversal (not only
    /// between traversal roots): one long chain, one start node, tiny budget.
    #[test]
    fn budget_fires_inside_directed_traversal() {
        let mut ttl = String::from("@prefix : <http://ex/> .\n");
        for k in 0..20_000u32 {
            ttl.push_str(&format!(":m{k} :e :m{} .\n", k + 1));
        }
        let g = Graph::load_str(&ttl, "turtle").unwrap();
        let budget = crate::QueryBudget { max_rows: Some(64), ..crate::QueryBudget::unlimited() };
        let err = crate::query_with_budget(&g, "PREFIX : <http://ex/> SELECT ?y WHERE { :m0 :e+ ?y }", &budget)
            .unwrap_err();
        assert!(err.contains("budget"), "expected a budget error, got: {err}");
    }

    /// PAIRED micro-benchmark (same process, same graph) for bound-subject
    /// `knows+` at ~1M edges: the single-source pushdown vs the previous
    /// full-closure-then-filter algorithm. Clustered social graph — 100k
    /// people in 1000 clusters of 100, ten random in-cluster `knows` edges
    /// each — so the full closure is feasible to measure at all (~10M pairs;
    /// an unclustered 1M-edge graph would make "before" run for hours, which
    /// is the pathology being fixed). Run manually:
    ///   cargo test -p sparq-engine --release bench_bound_endpoint -- --ignored --nocapture
    /// Absolute times on a shared machine are contended; the RATIO is the result.
    #[test]
    #[ignore]
    fn bench_bound_endpoint_pushdown_1m_edges() {
        use std::time::Instant;
        const CLUSTERS: u32 = 1_000;
        const SIZE: u32 = 100;
        const OUT_DEG: u32 = 10;
        let mut seed = 0x5EEDu64;
        let mut next = || {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            (seed >> 33) as u32
        };
        let mut ttl = String::with_capacity(48 << 20);
        ttl.push_str("@prefix : <http://ex/> .\n");
        for c in 0..CLUSTERS {
            for m in 0..SIZE {
                let a = c * SIZE + m;
                for _ in 0..OUT_DEG {
                    let b = c * SIZE + next() % SIZE;
                    ttl.push_str(&format!(":p{a} :knows :p{b} .\n"));
                }
            }
        }
        let t = Instant::now();
        let g = Graph::load_str(&ttl, "turtle").unwrap();
        eprintln!("loaded {} triples in {:.2?}", g.store.len(), t.elapsed());

        let knows = PropertyPathExpression::NamedNode(oxrdf::NamedNode::new("http://ex/knows").unwrap());
        let plus = PropertyPathExpression::OneOrMore(Box::new(knows.clone()));
        let id = |k: u32| g.id_of(&Term::NamedNode(oxrdf::NamedNode::new(format!("http://ex/p{k}")).unwrap())).unwrap();

        // AFTER: bound-subject pushdown, median over many random starts.
        let starts: Vec<Id> = (0..200).map(|_| id(next() % (CLUSTERS * SIZE))).collect();
        let mut times: Vec<f64> = Vec::new();
        let mut rows = 0usize;
        for &s in &starts {
            let t = Instant::now();
            let r = path_pairs(&g, &plus, PathEnds { s: Some(s), o: None }).unwrap();
            times.push(t.elapsed().as_secs_f64());
            rows += r.len();
        }
        times.sort_by(f64::total_cmp);
        let after = times[times.len() / 2];
        eprintln!("bound-subject pushdown: median {:.3?} over {} starts ({} total rows)",
            std::time::Duration::from_secs_f64(after), starts.len(), rows);

        // BEFORE: the previous algorithm — full all-pairs closure, then filter.
        let t = Instant::now();
        let full = transitive_closure_pairs(path_pairs(&g, &knows, PathEnds::NONE).unwrap());
        let before = t.elapsed().as_secs_f64();
        let s0 = starts[0];
        let filtered = full.iter().filter(|&&(x, _)| x == s0).count();
        eprintln!("full closure (old algorithm): {:.3?} ({} pairs; {} for one start)",
            std::time::Duration::from_secs_f64(before), full.len(), filtered);
        eprintln!("PAIRED RATIO full-closure / single-source = {:.0}x", before / after);

        // Both-bound reachability with early exit (hit and miss), and bound object.
        let (a, hit, miss) = (id(0), id(SIZE - 1), id(SIZE)); // same cluster / next cluster
        let t = Instant::now();
        for _ in 0..100 {
            let _ = path_pairs(&g, &plus, PathEnds { s: Some(a), o: Some(hit) }).unwrap();
        }
        eprintln!("both-bound (hit, early exit): {:.3?}/iter", t.elapsed() / 100);
        let t = Instant::now();
        for _ in 0..100 {
            let r = path_pairs(&g, &plus, PathEnds { s: Some(a), o: Some(miss) }).unwrap();
            assert!(!r.iter().any(|&(_, y)| y == miss));
        }
        eprintln!("both-bound (miss, cluster exhausted): {:.3?}/iter", t.elapsed() / 100);
        let t = Instant::now();
        for _ in 0..100 {
            let _ = path_pairs(&g, &plus, PathEnds { s: None, o: Some(a) }).unwrap();
        }
        eprintln!("bound-object reverse traversal: {:.3?}/iter", t.elapsed() / 100);
    }
}

/// SERVICE algebra-integration tests that drive `eval_service` directly through the
/// `service_transport` injection seam — no HTTP, no network. They cover what the
/// out-of-crate `tests/service_federation.rs` cannot reach: the term-interning and
/// the SILENT/variable-endpoint branches with a mocked transport. [OPUS-4.8]
#[cfg(all(test, feature = "service"))]
mod service_exec_tests {
    use super::*;
    use sparq_engine_service::service::Transport;

    /// Parse a query to its top-level `GraphPattern` (Select), ready for `eval_select`.
    fn pattern(sparql: &str) -> spargebra::algebra::GraphPattern {
        use spargebra::SparqlParser;
        let q = SparqlParser::new().parse_query(sparql).unwrap();
        let spargebra::Query::Select { pattern, .. } = q else { panic!("not a SELECT") };
        pattern
    }

    struct Canned(&'static str);
    impl Transport for Canned {
        fn fetch(&self, _e: &str, _q: &str) -> Result<String, String> {
            Ok(self.0.to_string())
        }
    }
    /// Returns an owned body, so a test can build a valid-rows-then-malformed document
    /// at runtime to drive the SILENT-error-mid-stream path. [OPUS-4.8] (sq-my8wd.4)
    struct CannedOwned(String);
    impl Transport for CannedOwned {
        fn fetch(&self, _e: &str, _q: &str) -> Result<String, String> {
            Ok(self.0.clone())
        }
    }
    /// An SRJ document that streams ONE valid binding for `vars` (a long literal on the
    /// last var, so interning it charges the byte budget) then a MALFORMED second
    /// binding, so the streaming parser delivers row 0 to the sink and then errors —
    /// the exact adversarial shape the SILENT-rollback fix must neutralise. [OPUS-4.8]
    fn valid_then_malformed_srj(head_and_first_row: &str, big_literal: &str) -> String {
        let mut body = String::from(head_and_first_row);
        body.push_str(big_literal);
        // Close the first (valid) binding, comma, then a malformed second binding whose
        // value is an invalid JSON token (`%`), then close results.
        body.push_str(r#""}},{"o":{"type":"literal","value":%}}]}}"#);
        body
    }
    struct Boom;
    impl Transport for Boom {
        fn fetch(&self, _e: &str, _q: &str) -> Result<String, String> {
            Err("transport boom".into())
        }
    }

    #[test]
    fn service_joins_remote_into_local_via_mock() {
        let g = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:alice a ex:Person . ex:bob a ex:Person .",
            "turtle",
        )
        .unwrap();
        let body = r#"{"head":{"vars":["s","name"]},"results":{"bindings":[
            {"s":{"type":"uri","value":"http://ex/alice"},"name":{"type":"literal","value":"Alice"}}
        ]}}"#;
        let _g = service_transport::install(Box::new(Canned(body)));
        let p = pattern(
            "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
             { ?s a ex:Person . SERVICE <http://remote/> { ?s ex:name ?name } }",
        );
        let res = eval_select(&g, &p).unwrap();
        // Only alice has a remote name -> the join keeps one row.
        assert_eq!(res.rows.len(), 1);
    }

    #[test]
    fn service_silent_swallows_mock_error() {
        let g = Graph::load_str("@prefix ex: <http://ex/> . ex:a a ex:T .", "turtle").unwrap();
        let _g = service_transport::install(Box::new(Boom));
        let p = pattern(
            "PREFIX ex: <http://ex/> SELECT ?s WHERE \
             { ?s a ex:T . SERVICE SILENT <http://remote/> { ?s ex:p ?o } }",
        );
        let res = eval_select(&g, &p).unwrap();
        assert_eq!(res.rows.len(), 1, "SILENT -> identity -> local row survives");
    }

    // -------------------------------------------------------------------------
    // [OPUS-4.8] (sq-my8wd.4) SILENT-error-MID-STREAM behaviour-neutrality (Copilot
    // review of PR #1424, threads on eval_service + bound_join_to_endpoint).
    //
    // The streaming path interns each remote row AS IT PARSES, which charges the
    // `LocalVocab` byte budget (`intern` -> `budget::add_bytes`). The pre-streaming
    // collect-then-intern-on-success path interned NOTHING on a swallowed (SILENT)
    // error, so it charged 0 bytes. Without the rollback these tests pin, a SILENT
    // SERVICE whose response streams a row then errors would RETAIN that row's intern
    // and its byte charge — tripping a `max_bytes` budget the SILENT fallback (join
    // identity) otherwise fits, turning a query the old path ANSWERED into a
    // "query budget exceeded" error. That is an observable, non-neutral result
    // difference — hence a fix, not just documentation. The budget is deliberately
    // tight so the single discarded remote row's charge alone would trip it.
    // -------------------------------------------------------------------------

    #[test]
    fn service_silent_midstream_rollback_verbatim_neutral_under_byte_budget() {
        let g = Graph::load_str("@prefix ex: <http://ex/> . ex:a a ex:T .", "turtle").unwrap();
        let big = "A".repeat(120);
        let body = valid_then_malformed_srj(
            r#"{"head":{"vars":["o"]},"results":{"bindings":[{"o":{"type":"literal","value":""#,
            &big,
        );
        let _t = service_transport::install(Box::new(CannedOwned(body)));
        // Standalone SERVICE (no left bindings to push) -> verbatim `eval_service`.
        let p = pattern(
            "PREFIX ex: <http://ex/> SELECT ?o WHERE \
             { SERVICE SILENT <http://remote/> { ?o ex:p ?x } }",
        );
        // A cap the ONE discarded remote literal (interned twice) blows, but the SILENT
        // fallback's own working set (one identity row) fits well under.
        let b = crate::QueryBudget { max_bytes: Some(64), ..crate::QueryBudget::unlimited() };
        let _bg = budget::install(&b);
        let res = eval_select(&g, &p)
            .expect("SILENT mid-stream error must roll back the discarded row's byte charge");
        assert_eq!(res.rows.len(), 1, "SILENT verbatim -> identity -> one (unbound ?o) row");
    }

    #[test]
    fn service_silent_midstream_rollback_boundjoin_neutral_under_byte_budget() {
        let g = Graph::load_str("@prefix ex: <http://ex/> . ex:a a ex:T .", "turtle").unwrap();
        let big = "A".repeat(120);
        let body = valid_then_malformed_srj(
            r#"{"head":{"vars":["s","o"]},"results":{"bindings":[{"s":{"type":"uri","value":"http://ex/a"},"o":{"type":"literal","value":""#,
            &big,
        );
        let _t = service_transport::install(Box::new(CannedOwned(body)));
        // `?s` is bound by the left BGP and shared with the SERVICE -> bind-join pushdown,
        // so this exercises the `bound_join_to_endpoint` SILENT arm.
        let p = pattern(
            "PREFIX ex: <http://ex/> SELECT ?s ?o WHERE \
             { ?s a ex:T . SERVICE SILENT <http://remote/> { ?s ex:p ?o } }",
        );
        let b = crate::QueryBudget { max_bytes: Some(64), ..crate::QueryBudget::unlimited() };
        let _bg = budget::install(&b);
        let res = eval_select(&g, &p)
            .expect("bind-join SILENT mid-stream error must roll back the discarded row's byte charge");
        assert_eq!(res.rows.len(), 1, "SILENT block failure -> identity -> local ?s=ex:a row survives");
    }

    #[test]
    fn service_nonsilent_propagates_mock_error() {
        let g = Graph::load_str("@prefix ex: <http://ex/> . ex:a a ex:T .", "turtle").unwrap();
        let _g = service_transport::install(Box::new(Boom));
        let p = pattern(
            "PREFIX ex: <http://ex/> SELECT ?s WHERE \
             { ?s a ex:T . SERVICE <http://remote/> { ?s ex:p ?o } }",
        );
        assert!(eval_select(&g, &p).is_err());
    }

    // ---------------------------------------------------------------------
    // Bind-join (VALUES pushdown) differential: bound == verbatim. [OPUS-4.8]
    // (bead sq-sjkj). A mock transport that evaluates the RECEIVED query (VALUES
    // and all) against a real remote `Graph`, so the injected pushdown is
    // genuinely executed and we can assert the bound path's results are IDENTICAL
    // to the verbatim path's — plus count remote requests.
    // ---------------------------------------------------------------------

    use std::cell::RefCell;
    use std::rc::Rc;

    /// A transport backed by a remote `Graph`: it runs each received query through
    /// the engine (`query_json`) and records the query strings it served.
    struct RemoteGraph {
        remote: Graph,
        seen: Rc<RefCell<Vec<String>>>,
    }
    impl Transport for RemoteGraph {
        fn fetch(&self, _e: &str, q: &str) -> Result<String, String> {
            self.seen.borrow_mut().push(q.to_string());
            crate::query_json(&self.remote, q)
        }
    }

    /// Sort a result's rows into a canonical multiset for order-independent equality.
    fn canon(res: &QueryResult) -> Vec<Vec<Option<String>>> {
        let mut rows: Vec<Vec<Option<String>>> = res
            .rows
            .iter()
            .map(|r| r.iter().map(|c| c.as_ref().map(|t| t.to_string())).collect())
            .collect();
        rows.sort();
        rows
    }

    fn three_persons() -> Graph {
        Graph::load_str(
            "@prefix ex: <http://ex/> . \
             ex:alice a ex:Person . ex:bob a ex:Person . ex:carol a ex:Person .",
            "turtle",
        )
        .unwrap()
    }

    fn remote_names() -> Graph {
        let mut ttl = String::from("@prefix ex: <http://ex/> .\n");
        ttl.push_str("ex:alice ex:name \"Alice\" . ex:bob ex:name \"Bob\" .\n");
        for i in 0..60 {
            ttl.push_str(&format!("ex:noise{i} ex:name \"N{i}\" .\n"));
        }
        Graph::load_str(&ttl, "turtle").unwrap()
    }

    /// Run a federated query with a remote-graph mock, returning (result, n_requests).
    fn run_fed(local: &Graph, q: &str, remote: Graph) -> (QueryResult, usize) {
        let seen = Rc::new(RefCell::new(Vec::new()));
        let _g = service_transport::install(Box::new(RemoteGraph { remote, seen: Rc::clone(&seen) }));
        let p = pattern(q);
        let res = eval_select(local, &p).unwrap();
        let n = seen.borrow().len();
        (res, n)
    }

    #[test]
    fn bound_join_equals_verbatim_basic() {
        // Same query, same mock: the bound-join path (default, ON) must match the
        // verbatim path (forced by a single-tuple block can't disable it, so we
        // compare against an explicit local-join reconstruction via VALUES-free mock).
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s a ex:Person . SERVICE <http://r/> { ?s ex:name ?name } }";
        let (bound, n) = run_fed(&three_persons(), q, remote_names());
        // alice + bob match; carol + 60 noise do not contribute to the join.
        assert_eq!(bound.rows.len(), 2, "only alice/bob have remote names");
        assert_eq!(n, 1, "3 distinct subjects < block 50 => one request");
        let got = canon(&bound);
        // The verbatim equivalent: no SERVICE, just the remote relation joined.
        // Reconstruct it locally to pin the expected multiset.
        let expect: Vec<Vec<Option<String>>> = {
            let mut v = vec![
                vec![Some("<http://ex/alice>".to_string()), Some("\"Alice\"".to_string())],
                vec![Some("<http://ex/bob>".to_string()), Some("\"Bob\"".to_string())],
            ];
            v.sort();
            v
        };
        assert_eq!(got, expect, "bound-join result multiset");
    }

    #[test]
    fn bound_join_block_boundary_unions_all_blocks() {
        // Block size 1 => one request per distinct subject; the union must still be
        // the SAME result as a single block. Proves block-boundary correctness.
        let seen = Rc::new(RefCell::new(Vec::new()));
        let _g = service_transport::install(Box::new(RemoteGraph {
            remote: remote_names(),
            seen: Rc::clone(&seen),
        }));
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s a ex:Person . SERVICE <http://r/> { ?s ex:name ?name } }";
        let res = sparq_engine_service::service::with_service_bound_join_block_size(1, || {
            eval_select(&three_persons(), &pattern(q)).unwrap()
        });
        assert_eq!(res.rows.len(), 2);
        assert_eq!(seen.borrow().len(), 3, "block size 1 over 3 subjects => 3 requests");
    }

    #[test]
    fn bound_join_optional_keeps_unmatched() {
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s a ex:Person . OPTIONAL { SERVICE <http://r/> { ?s ex:name ?name } } }";
        let (res, _n) = run_fed(&three_persons(), q, remote_names());
        assert_eq!(res.rows.len(), 3, "left-join: carol survives with an unbound name");
        let name_i = res.vars.iter().position(|v| v.as_str() == "name").unwrap();
        let bound_names = res.rows.iter().filter(|r| r[name_i].is_some()).count();
        assert_eq!(bound_names, 2, "only alice/bob got a name");
    }

    #[test]
    fn bound_join_silent_block_failure_keeps_left() {
        // A transport that fails => under SILENT, the bound-join degrades to the join
        // identity (empty remote relation), so the local rows survive unchanged —
        // identical to the verbatim SILENT path.
        let _g = service_transport::install(Box::new(Boom));
        let q = "PREFIX ex: <http://ex/> SELECT ?s WHERE \
                 { ?s a ex:Person . SERVICE SILENT <http://r/> { ?s ex:name ?name } }";
        let res = eval_select(&three_persons(), &pattern(q)).unwrap();
        assert_eq!(res.rows.len(), 3, "SILENT remote failure keeps all local persons");
    }

    #[test]
    fn bound_join_unbound_join_var_falls_back_to_verbatim() {
        // Here ?s is NOT bound on the left of the SERVICE (the left binds only ?p),
        // so there is no bound join var to push — the verbatim path runs. The remote
        // returns its whole relation, joined locally. Still correct.
        let local = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:alice ex:knows ex:bob .",
            "turtle",
        )
        .unwrap();
        let remote = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:bob ex:name \"Bob\" . ex:zzz ex:name \"Z\" .",
            "turtle",
        )
        .unwrap();
        // The SERVICE binds ?o/?name; the left binds ?s/?o (via ex:knows). ?o is shared
        // and bound => this actually DOES bind-join on ?o. Use a genuinely unshared var.
        let q = "PREFIX ex: <http://ex/> SELECT ?name WHERE \
                 { ex:alice ex:knows ?x . SERVICE <http://r/> { ?y ex:name ?name } }";
        let (res, _n) = run_fed(&local, q, remote);
        // No shared var => cross product of {?x=bob} with remote {bob,zzz} => 2 rows.
        assert_eq!(res.rows.len(), 2, "no bound join var => verbatim cross-join");
    }

    #[test]
    fn variable_endpoint_unbound_top_level_errors() {
        // A variable endpoint with NOTHING to bind it (the surrounding pattern produces
        // no row binding `?e`) has no endpoint to call: the verbatim path errors
        // (non-SILENT) / yields the identity (SILENT). [OPUS-4.8] (sq-d4p)
        let g = Graph::load_str("@prefix ex: <http://ex/> . ex:a a ex:T .", "turtle").unwrap();
        // No `ex:ep` data => `?s ex:ep ?e` yields 0 rows => empty left => verbatim path.
        let p = pattern(
            "PREFIX ex: <http://ex/> SELECT ?s WHERE \
             { ?s a ex:T . ?s ex:ep ?e . SERVICE ?e { ?s ex:p ?o } }",
        );
        let err = eval_select(&g, &p).unwrap_err();
        assert!(err.contains("variable endpoint"), "got: {err}");

        // SILENT variable endpoint -> identity, no error.
        let p2 = pattern(
            "PREFIX ex: <http://ex/> SELECT ?s WHERE \
             { ?s a ex:T . ?s ex:ep ?e . SERVICE SILENT ?e { ?s ex:p ?o } }",
        );
        assert!(eval_select(&g, &p2).is_ok());
    }

    // ---------------------------------------------------------------------
    // SERVICE ?var — variable endpoint, per-endpoint dispatch. [OPUS-4.8] (sq-d4p)
    // ---------------------------------------------------------------------

    /// A transport that routes each query to a distinct remote `Graph` keyed by the
    /// endpoint IRI, recording the (endpoint, query) pairs it served. Lets a test prove
    /// that `SERVICE ?ep` dials the RIGHT endpoint per left binding of `?ep`.
    struct RemoteByEndpoint {
        graphs: std::collections::HashMap<String, Graph>,
        seen: Rc<RefCell<Vec<(String, String)>>>,
    }
    impl Transport for RemoteByEndpoint {
        fn fetch(&self, e: &str, q: &str) -> Result<String, String> {
            self.seen.borrow_mut().push((e.to_string(), q.to_string()));
            match self.graphs.get(e) {
                Some(g) => crate::query_json(g, q),
                None => Err(format!("no such endpoint {e}")),
            }
        }
    }

    /// `local` data binds each person to the endpoint that knows their name.
    fn persons_with_endpoints() -> Graph {
        Graph::load_str(
            "@prefix ex: <http://ex/> . \
             ex:alice ex:ep <http://r1/> . \
             ex:bob   ex:ep <http://r2/> . \
             ex:carol ex:ep <http://r1/> .",
            "turtle",
        )
        .unwrap()
    }

    #[test]
    fn variable_endpoint_dispatches_per_endpoint() {
        // alice & carol -> r1 ; bob -> r2. Each remote knows only its own names.
        let r1 = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:alice ex:name \"Alice\" . ex:carol ex:name \"Carol\" .",
            "turtle",
        )
        .unwrap();
        let r2 = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:bob ex:name \"Bob\" .",
            "turtle",
        )
        .unwrap();
        let seen = Rc::new(RefCell::new(Vec::new()));
        let mut graphs = std::collections::HashMap::new();
        graphs.insert("http://r1/".to_string(), r1);
        graphs.insert("http://r2/".to_string(), r2);
        let _g = service_transport::install(Box::new(RemoteByEndpoint {
            graphs,
            seen: Rc::clone(&seen),
        }));
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s ex:ep ?e . SERVICE ?e { ?s ex:name ?name } }";
        let res = eval_select(&persons_with_endpoints(), &pattern(q)).unwrap();
        let mut got = canon(&res);
        got.sort();
        let mut expect = vec![
            vec![Some("<http://ex/alice>".to_string()), Some("\"Alice\"".to_string())],
            vec![Some("<http://ex/bob>".to_string()), Some("\"Bob\"".to_string())],
            vec![Some("<http://ex/carol>".to_string()), Some("\"Carol\"".to_string())],
        ];
        expect.sort();
        assert_eq!(got, expect, "each person resolved against its own endpoint");
        // Two distinct endpoints => exactly two remote requests (one bind-join each).
        let endpoints: std::collections::HashSet<String> =
            seen.borrow().iter().map(|(e, _)| e.clone()).collect();
        assert_eq!(endpoints.len(), 2, "dialled both r1 and r2, and only those");
    }

    #[test]
    fn variable_endpoint_optional_keeps_unmatched() {
        // carol's endpoint r1 does NOT know her name -> under OPTIONAL she survives
        // unbound; alice (r1) and bob (r2) get names.
        let r1 = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:alice ex:name \"Alice\" .",
            "turtle",
        )
        .unwrap();
        let r2 = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:bob ex:name \"Bob\" .",
            "turtle",
        )
        .unwrap();
        let seen = Rc::new(RefCell::new(Vec::new()));
        let mut graphs = std::collections::HashMap::new();
        graphs.insert("http://r1/".to_string(), r1);
        graphs.insert("http://r2/".to_string(), r2);
        let _g = service_transport::install(Box::new(RemoteByEndpoint {
            graphs,
            seen: Rc::clone(&seen),
        }));
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s ex:ep ?e . OPTIONAL { SERVICE ?e { ?s ex:name ?name } } }";
        let res = eval_select(&persons_with_endpoints(), &pattern(q)).unwrap();
        assert_eq!(res.rows.len(), 3, "all three persons survive the left join");
        let name_i = res.vars.iter().position(|v| v.as_str() == "name").unwrap();
        let named = res.rows.iter().filter(|r| r[name_i].is_some()).count();
        assert_eq!(named, 2, "only alice/bob got a name; carol's endpoint lacked it");
    }

    #[test]
    fn variable_endpoint_silent_failure_keeps_left() {
        // A failing transport under SILENT must keep the left rows unchanged (identity),
        // exactly like the concrete-endpoint SILENT path.
        let _g = service_transport::install(Box::new(Boom));
        let q = "PREFIX ex: <http://ex/> SELECT ?s WHERE \
                 { ?s ex:ep ?e . SERVICE SILENT ?e { ?s ex:name ?name } }";
        let res = eval_select(&persons_with_endpoints(), &pattern(q)).unwrap();
        assert_eq!(res.rows.len(), 3, "SILENT remote failure keeps all three persons");
    }

    #[test]
    fn variable_endpoint_non_iri_binding_yields_no_remote_row() {
        // A literal-valued `?e` is not a valid endpoint -> that solution contributes no
        // remote row (inner join drops it). alice (valid r1) survives; dave (literal) does not.
        let local = Graph::load_str(
            "@prefix ex: <http://ex/> . \
             ex:alice ex:ep <http://r1/> . \
             ex:dave  ex:ep \"not-an-iri\" .",
            "turtle",
        )
        .unwrap();
        let r1 = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:alice ex:name \"Alice\" .",
            "turtle",
        )
        .unwrap();
        let mut graphs = std::collections::HashMap::new();
        graphs.insert("http://r1/".to_string(), r1);
        let seen = Rc::new(RefCell::new(Vec::new()));
        let _g = service_transport::install(Box::new(RemoteByEndpoint {
            graphs,
            seen: Rc::clone(&seen),
        }));
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s ex:ep ?e . SERVICE ?e { ?s ex:name ?name } }";
        let res = eval_select(&local, &pattern(q)).unwrap();
        assert_eq!(res.rows.len(), 1, "only the valid-IRI endpoint produced a row");
        // The literal endpoint was never dialled.
        assert!(
            seen.borrow().iter().all(|(e, _)| e == "http://r1/"),
            "only the valid IRI endpoint was contacted"
        );
    }

    // ---------------------------------------------------------------------
    // Per-query remote-request cap for high-cardinality SERVICE ?ep. [OPUS-4.8]
    // (sq-b93pv). The cap bounds the number of DISTINCT endpoints a single
    // `SERVICE ?ep` may dial, enforced PRE-HTTP: when the cap fires, the mock
    // transport must record ZERO requests (proof the bound is before dispatch, not
    // a post-HTTP cancellation).
    // ---------------------------------------------------------------------

    /// `local` data binding `n` distinct persons each to a DISTINCT endpoint IRI
    /// (`http://r0/`, `http://r1/`, …) — i.e. a high-cardinality `?ep`.
    fn persons_with_distinct_endpoints(n: usize) -> Graph {
        let mut ttl = String::from("@prefix ex: <http://ex/> .\n");
        for i in 0..n {
            ttl.push_str(&format!("ex:p{i} ex:ep <http://r{i}/> .\n"));
        }
        Graph::load_str(&ttl, "turtle").unwrap()
    }

    #[test]
    fn remote_request_cap_fires_before_dispatch() {
        // 5 distinct endpoints, cap 3 => the query is REFUSED, and the mock records
        // NO requests (the bound is enforced pre-HTTP, before any socket is opened).
        let seen = Rc::new(RefCell::new(Vec::new()));
        let _g = service_transport::install(Box::new(RemoteByEndpoint {
            graphs: std::collections::HashMap::new(),
            seen: Rc::clone(&seen),
        }));
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s ex:ep ?e . SERVICE ?e { ?s ex:name ?name } }";
        let p = pattern(q);
        let err = sparq_engine_service::service::with_service_remote_request_cap(3, || {
            eval_select(&persons_with_distinct_endpoints(5), &p)
        })
        .unwrap_err();
        // Typed refusal: carries the stable marker the server classifies on.
        assert!(
            err.contains(sparq_engine_service::service::SERVICE_REMOTE_CAP_MARKER),
            "cap error must carry the marker, got: {err}"
        );
        // PRE-DISPATCH: not one remote request was made.
        assert!(
            seen.borrow().is_empty(),
            "cap must fire BEFORE any HTTP dispatch; mock saw: {:?}",
            seen.borrow()
        );
    }

    #[test]
    fn remote_request_cap_not_swallowed_by_silent() {
        // The cap is a resource-policy refusal, not a remote failure: SERVICE SILENT
        // must NOT mask it (SILENT only masks an endpoint being unreachable).
        let seen = Rc::new(RefCell::new(Vec::new()));
        let _g = service_transport::install(Box::new(RemoteByEndpoint {
            graphs: std::collections::HashMap::new(),
            seen: Rc::clone(&seen),
        }));
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s ex:ep ?e . SERVICE SILENT ?e { ?s ex:name ?name } }";
        let p = pattern(q);
        let err = sparq_engine_service::service::with_service_remote_request_cap(2, || {
            eval_select(&persons_with_distinct_endpoints(5), &p)
        })
        .unwrap_err();
        assert!(
            err.contains(sparq_engine_service::service::SERVICE_REMOTE_CAP_MARKER),
            "SILENT must not swallow the cap refusal, got: {err}"
        );
        assert!(seen.borrow().is_empty(), "cap fires before dispatch even under SILENT");
    }

    #[test]
    fn remote_request_cap_at_or_under_limit_passes() {
        // 2 distinct endpoints, cap 2 (the boundary: > cap fires, == cap is allowed).
        // Each endpoint knows its own person's name; the query must succeed normally.
        let r0 = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:p0 ex:name \"P0\" .",
            "turtle",
        )
        .unwrap();
        let r1 = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:p1 ex:name \"P1\" .",
            "turtle",
        )
        .unwrap();
        let mut graphs = std::collections::HashMap::new();
        graphs.insert("http://r0/".to_string(), r0);
        graphs.insert("http://r1/".to_string(), r1);
        let seen = Rc::new(RefCell::new(Vec::new()));
        let _g = service_transport::install(Box::new(RemoteByEndpoint {
            graphs,
            seen: Rc::clone(&seen),
        }));
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s ex:ep ?e . SERVICE ?e { ?s ex:name ?name } }";
        let p = pattern(q);
        let res = sparq_engine_service::service::with_service_remote_request_cap(2, || {
            eval_select(&persons_with_distinct_endpoints(2), &p)
        })
        .expect("at-cap query is allowed");
        assert_eq!(res.rows.len(), 2, "both persons resolved against their own endpoint");
        // Exactly the two distinct endpoints were dialled.
        let dialled: std::collections::HashSet<String> =
            seen.borrow().iter().map(|(e, _)| e.clone()).collect();
        assert_eq!(dialled.len(), 2, "dialled exactly the two permitted endpoints");
    }

    #[test]
    fn remote_request_cap_default_off_is_unchanged() {
        // DEFAULT (no cap installed): a high-cardinality SERVICE ?ep dispatches to ALL
        // distinct endpoints exactly as before — the cap adds nothing to normal queries.
        let mut graphs = std::collections::HashMap::new();
        for i in 0..5 {
            graphs.insert(
                format!("http://r{i}/"),
                Graph::load_str(
                    &format!("@prefix ex: <http://ex/> . ex:p{i} ex:name \"P{i}\" ."),
                    "turtle",
                )
                .unwrap(),
            );
        }
        let seen = Rc::new(RefCell::new(Vec::new()));
        let _g = service_transport::install(Box::new(RemoteByEndpoint {
            graphs,
            seen: Rc::clone(&seen),
        }));
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s ex:ep ?e . SERVICE ?e { ?s ex:name ?name } }";
        // No `with_service_remote_request_cap` scope => uncapped (the default).
        let res = eval_select(&persons_with_distinct_endpoints(5), &pattern(q)).unwrap();
        assert_eq!(res.rows.len(), 5, "all five persons resolved (no cap by default)");
        let dialled: std::collections::HashSet<String> =
            seen.borrow().iter().map(|(e, _)| e.clone()).collect();
        assert_eq!(dialled.len(), 5, "all five distinct endpoints dialled by default");
    }

    #[test]
    fn remote_request_cap_does_not_bound_concrete_endpoint() {
        // A concrete-IRI SERVICE is a SINGLE endpoint; even cap 0 (refuse any variable
        // dispatch) must not touch it — the cap is scoped to the variable-endpoint
        // fan-out, not the per-block request count of a single endpoint.
        let g = three_persons();
        let seen = Rc::new(RefCell::new(Vec::new()));
        let _g = service_transport::install(Box::new(RemoteGraph {
            remote: remote_names(),
            seen: Rc::clone(&seen),
        }));
        let q = "PREFIX ex: <http://ex/> SELECT ?s ?name WHERE \
                 { ?s a ex:Person . SERVICE <http://r/> { ?s ex:name ?name } }";
        let res = sparq_engine_service::service::with_service_remote_request_cap(0, || {
            eval_select(&g, &pattern(q))
        })
        .expect("concrete-IRI SERVICE is unaffected by the variable-endpoint cap");
        assert_eq!(res.rows.len(), 2, "alice + bob matched, cap did not interfere");
    }

    // ---------------------------------------------------------------------
    // Per-query timeout wired to the QueryBudget deadline. [OPUS-4.8] (sq-d4p)
    // (The HttpTransport timeout-math test `http_transport_timeout_tracks_budget`
    // MOVED with the transport to `sparq-engine-service`, seam A2 / sq-6vshe.4 — its
    // `timeout_for_test` accessor is `#[cfg(test)]` there. The caller side —
    // `budget::remaining_timeout` feeding `with_budget` — stays tested below.)
    // ---------------------------------------------------------------------

    #[test]
    fn budget_remaining_timeout_reflects_deadline() {
        use std::time::{Duration, Instant};
        // No budget installed -> None.
        assert!(budget::remaining_timeout().is_none());
        // A future deadline -> Some(positive), bounded by the deadline.
        let b = crate::QueryBudget {
            deadline: Some(Instant::now() + Duration::from_secs(10)),
            ..crate::QueryBudget::unlimited()
        };
        let _g = budget::install(&b);
        let r = budget::remaining_timeout().expect("deadline installed");
        assert!(r <= Duration::from_secs(10) && r > Duration::from_secs(8), "got {r:?}");
        // An expired deadline saturates to ZERO (never panics / underflows).
        let b2 = crate::QueryBudget {
            deadline: Some(Instant::now() - Duration::from_millis(1)),
            ..crate::QueryBudget::unlimited()
        };
        let _g2 = budget::install(&b2);
        assert_eq!(budget::remaining_timeout(), Some(Duration::ZERO));
    }
}

/// [OPUS-4.8] sq-53ti (gh-49) — SPARQL 1.1 aggregate-over-EMPTY-multiset semantics.
///
/// Pins the §18.5.1 "Set Functions over an empty group" contract that downstream
/// consumers (notably PSS `usage()`, which sums resource sizes over a possibly-empty
/// graph match and reads a single all-but-COUNT-bound row) depend on. The rule, split
/// by the one axis that matters — whether a `GROUP BY` is present:
///
/// * **No `GROUP BY`, the WHERE clause matches nothing** → the whole solution set is a
///   SINGLE implicit group, so the result is exactly ONE row (NOT zero). In that row:
///   - `COUNT(*)` and `COUNT(?x)` → `"0"^^xsd:integer` (§18.5.1.1: Count({}) = 0)
///   - `SUM(?x)` → `"0"^^xsd:integer` (§18.5.1.4: Sum({}) = 0)
///   - `AVG(?x)` → `"0"^^xsd:integer` (§18.5.1.5: Avg({}) = 0)
///   - `MIN(?x)` / `MAX(?x)` → UNBOUND (§18.5.1.6/7: an error over {} ⇒ the variable is left unbound for that row)
///   - `SAMPLE(?x)` → UNBOUND (§18.5.1.8: no element to sample)
///   - `GROUP_CONCAT(?x)` → `""` (empty string) (§18.5.1.9: concat of zero strings)
///
///   The SUM/AVG-vs-MIN/MAX split is the subtle part: SUM and AVG over the empty
///   multiset are DEFINED to be the integer `0` (so `COALESCE(SUM(?x), 0)` and a bare
///   `SUM(?x)` both yield `0`, and a single bound `0` cell — not an unbound one), whereas
///   MIN/MAX/SAMPLE raise an error that surfaces as an UNBOUND cell in the one result row.
///
/// * **With `GROUP BY`, the input is empty** → there are ZERO groups, hence ZERO result
///   rows (the implicit-single-group rule applies ONLY when no GROUP BY is written).
///
/// Ground truth: this matches the engine's behaviour today AND the W3C SPARQL 1.1
/// `aggregates` conformance suite — `agg-empty-group-count-2` (COUNT, no GROUP BY → one
/// `0` row), `agg-empty-group-max-2` (MAX, no GROUP BY → one all-unbound row),
/// `agg-empty-group-count-1` / `agg-empty-group-max-1` (with GROUP BY → zero rows). These
/// tests are the GUARANTEE that pins the contract against regressions.
#[cfg(test)]
mod aggregate_empty_semantics {
    use super::*;

    /// A non-empty graph whose triples never match the test queries' predicate, so the
    /// WHERE clause produces an EMPTY multiset while the store itself is non-trivial
    /// (rules out "0 rows because the store is empty" as the cause).
    fn g() -> Graph {
        Graph::load_str("@prefix ex: <http://ex/> . ex:keep ex:other 1 .", "turtle").unwrap()
    }

    fn run(q: &str) -> QueryResult {
        crate::query(&g(), &format!("PREFIX ex: <http://ex/> {q}")).unwrap()
    }

    /// The single cell of a one-row, one-projected-variable result.
    fn one_cell(q: &str) -> Option<Term> {
        let r = run(q);
        assert_eq!(r.rows.len(), 1, "expected exactly one solution row for: {q}");
        assert_eq!(r.rows[0].len(), 1, "expected exactly one projected cell for: {q}");
        r.rows[0][0].clone()
    }

    fn int_lit(n: i64) -> Term {
        Term::Literal(oxrdf::Literal::new_typed_literal(n.to_string(), oxrdf::vocab::xsd::INTEGER))
    }

    // ---- No GROUP BY over an empty match: ONE row, COUNT=0, others per the split above ----

    #[test]
    fn count_star_over_empty_is_zero_one_row() {
        assert_eq!(one_cell("SELECT (COUNT(*) AS ?v) WHERE { ?s ex:nomatch ?o }"), Some(int_lit(0)));
    }

    #[test]
    fn count_var_over_empty_is_zero_one_row() {
        // COUNT(?x) and COUNT(*) coincide over an empty multiset: both 0.
        assert_eq!(one_cell("SELECT (COUNT(?o) AS ?v) WHERE { ?s ex:nomatch ?o }"), Some(int_lit(0)));
    }

    #[test]
    fn count_star_vs_count_var_agree_over_empty() {
        let star = one_cell("SELECT (COUNT(*) AS ?v) WHERE { ?s ex:nomatch ?o }");
        let var = one_cell("SELECT (COUNT(?o) AS ?v) WHERE { ?s ex:nomatch ?o }");
        assert_eq!(star, var);
        assert_eq!(star, Some(int_lit(0)));
    }

    #[test]
    fn sum_over_empty_is_integer_zero_one_row() {
        // §18.5.1.4: Sum({}) = "0"^^xsd:integer — a BOUND 0, NOT unbound. This is the cell
        // PSS usage() reads (directly, or via COALESCE(SUM(?size), 0) which still sees 0).
        assert_eq!(one_cell("SELECT (SUM(?o) AS ?v) WHERE { ?s ex:nomatch ?o }"), Some(int_lit(0)));
    }

    #[test]
    fn avg_over_empty_is_integer_zero_one_row() {
        // §18.5.1.5: Avg({}) = "0"^^xsd:integer.
        assert_eq!(one_cell("SELECT (AVG(?o) AS ?v) WHERE { ?s ex:nomatch ?o }"), Some(int_lit(0)));
    }

    #[test]
    fn min_over_empty_is_unbound_one_row() {
        // §18.5.1.6: Min over {} errors ⇒ unbound cell, but still ONE row.
        assert_eq!(one_cell("SELECT (MIN(?o) AS ?v) WHERE { ?s ex:nomatch ?o }"), None);
    }

    #[test]
    fn max_over_empty_is_unbound_one_row() {
        // §18.5.1.7. Mirrors the W3C `agg-empty-group-max-2` conformance test.
        assert_eq!(one_cell("SELECT (MAX(?o) AS ?v) WHERE { ?s ex:nomatch ?o }"), None);
    }

    #[test]
    fn sample_over_empty_is_unbound_one_row() {
        // §18.5.1.8: no element to sample ⇒ unbound cell, ONE row.
        assert_eq!(one_cell("SELECT (SAMPLE(?o) AS ?v) WHERE { ?s ex:nomatch ?o }"), None);
    }

    #[test]
    fn group_concat_over_empty_is_empty_string_one_row() {
        // §18.5.1.9: concatenation of zero strings is the empty simple literal "".
        assert_eq!(
            one_cell("SELECT (GROUP_CONCAT(?o) AS ?v) WHERE { ?s ex:nomatch ?o }"),
            Some(Term::Literal(oxrdf::Literal::new_simple_literal("")))
        );
    }

    #[test]
    fn group_concat_with_separator_over_empty_is_empty_string() {
        // A custom separator does not change the empty-input result: still "".
        assert_eq!(
            one_cell("SELECT (GROUP_CONCAT(?o; SEPARATOR=\",\") AS ?v) WHERE { ?s ex:nomatch ?o }"),
            Some(Term::Literal(oxrdf::Literal::new_simple_literal("")))
        );
    }

    /// The PSS `usage()` shape end-to-end: several aggregates in one SELECT over an empty
    /// match must yield a SINGLE row whose COUNT is 0 and SUM is 0 (so `{resourceCount:0,
    /// bytes:0}` falls out of that one row), with no extra/zero rows.
    #[test]
    fn mixed_aggregates_no_group_by_yield_one_row() {
        let r = run("SELECT (COUNT(?o) AS ?n) (SUM(?o) AS ?total) WHERE { ?s ex:nomatch ?o }");
        assert_eq!(r.vars.iter().map(|v| v.as_str()).collect::<Vec<_>>(), ["n", "total"]);
        assert_eq!(r.rows.len(), 1, "aggregates with no GROUP BY over empty must be ONE row");
        assert_eq!(r.rows[0], vec![Some(int_lit(0)), Some(int_lit(0))]);
    }

    // ---- WITH GROUP BY over empty input: ZERO groups ⇒ ZERO rows ----

    #[test]
    fn count_star_with_group_by_over_empty_is_zero_rows() {
        // Mirrors W3C `agg-empty-group-count-1`.
        let r = run("SELECT ?s (COUNT(*) AS ?v) WHERE { ?s ex:nomatch ?o } GROUP BY ?s");
        assert!(r.rows.is_empty(), "GROUP BY over empty input must yield zero groups (zero rows)");
    }

    #[test]
    fn sum_with_group_by_over_empty_is_zero_rows() {
        let r = run("SELECT ?s (SUM(?o) AS ?v) WHERE { ?s ex:nomatch ?o } GROUP BY ?s");
        assert!(r.rows.is_empty());
    }

    #[test]
    fn max_with_group_by_over_empty_is_zero_rows() {
        // Mirrors W3C `agg-empty-group-max-1`.
        let r = run("SELECT ?s (MAX(?o) AS ?v) WHERE { ?s ex:nomatch ?o } GROUP BY ?s");
        assert!(r.rows.is_empty());
    }

    /// The single-implicit-group rule must NOT fire when a GROUP BY is written, even if the
    /// grouping key is a constant expression — empty input still means zero groups.
    #[test]
    fn group_by_constant_over_empty_is_zero_rows() {
        let r = run("SELECT ?k (COUNT(*) AS ?v) WHERE { ?s ex:nomatch ?o } GROUP BY (1 AS ?k)");
        assert!(r.rows.is_empty());
    }
}

/// `GROUP BY ?v` where `?v` is **never bound** anywhere in the WHERE clause must NOT panic.
/// Per SPARQL 1.1 §11.1 the key for an unbound grouping variable is unbound for every solution,
/// so all matching rows collapse into ONE group with `?v` unbound in the output. Regression for
/// bead sq-vymy4 — the engine previously panicked with `group var present` at the `key_cols`
/// build. [OPUS-4.8]
#[cfg(test)]
mod group_by_unbound_var {
    use super::*;

    /// A non-empty graph: three `ex:a`-typed subjects. The WHERE clause below matches all three,
    /// so the input multiset is non-empty — but `?kind` is never bound.
    fn g() -> Graph {
        Graph::load_str(
            "@prefix ex: <http://ex/> . ex:x1 a ex:Thing . ex:x2 a ex:Thing . ex:x3 a ex:Thing .",
            "turtle",
        )
        .unwrap()
    }

    fn run(q: &str) -> QueryResult {
        crate::query(&g(), &format!("PREFIX ex: <http://ex/> {q}")).unwrap()
    }

    fn int_lit(n: i64) -> Term {
        Term::Literal(oxrdf::Literal::new_typed_literal(n.to_string(), oxrdf::vocab::xsd::INTEGER))
    }

    /// The bead's exact shape: GROUP BY an unbound var with a COUNT(DISTINCT). One group, the
    /// grouping var unbound, the count over the whole matched set. Must not panic.
    #[test]
    fn group_by_never_bound_var_is_one_unbound_group() {
        let r = run("SELECT ?kind (COUNT(DISTINCT ?x) AS ?n) WHERE { ?x a ex:Thing } GROUP BY ?kind");
        assert_eq!(r.vars.iter().map(|v| v.as_str()).collect::<Vec<_>>(), ["kind", "n"]);
        assert_eq!(r.rows.len(), 1, "all rows share the unbound key ⇒ exactly one group");
        // `?kind` unbound, `?n` = number of distinct ?x (3).
        assert_eq!(r.rows[0], vec![None, Some(int_lit(3))]);
    }

    /// COUNT(*) variant — the count is the size of the (single) group, i.e. all matched rows.
    #[test]
    fn group_by_never_bound_var_count_star() {
        let r = run("SELECT ?kind (COUNT(*) AS ?n) WHERE { ?x a ex:Thing } GROUP BY ?kind");
        assert_eq!(r.rows.len(), 1);
        assert_eq!(r.rows[0], vec![None, Some(int_lit(3))]);
    }

    /// A BOUND grouping var mixed with a NEVER-bound one: grouping still partitions by the bound
    /// var (here all rows share `?x`'s type-less subject so… group by the bound `?x`), and the
    /// unbound `?kind` is unbound in every output row. Three distinct subjects ⇒ three groups.
    #[test]
    fn mixed_bound_and_unbound_group_vars() {
        let r = run("SELECT ?x ?kind (COUNT(*) AS ?n) WHERE { ?x a ex:Thing } GROUP BY ?x ?kind");
        assert_eq!(r.vars.iter().map(|v| v.as_str()).collect::<Vec<_>>(), ["x", "kind", "n"]);
        assert_eq!(r.rows.len(), 3, "three distinct ?x ⇒ three groups");
        // Every row has `?kind` (the 2nd cell) unbound and a per-subject count of 1.
        for row in &r.rows {
            assert_eq!(row[1], None, "the never-bound ?kind must be unbound");
            assert_eq!(row[2], Some(int_lit(1)));
        }
    }

    /// SUM over a never-bound grouping var: one group, the unbound key, SUM is unbound (no
    /// numeric members) — and crucially, no panic.
    #[test]
    fn group_by_never_bound_var_with_sum() {
        let r = run("SELECT ?kind (SUM(?missing) AS ?total) WHERE { ?x a ex:Thing } GROUP BY ?kind");
        assert_eq!(r.rows.len(), 1);
        assert_eq!(r.rows[0][0], None, "?kind unbound");
        // SUM over an all-unbound column is "0"^^xsd:integer (Sum({}) = 0).
        assert_eq!(r.rows[0][1], Some(int_lit(0)));
    }
}

/// [OPUS-4.8] (sq-v411r, survey §B2) The SPARQL 1.2 algebra's `multiplicity` device exposed
/// as a zero-argument extension builtin `MULTIPLICITY()`. These tests drive the REAL query
/// path (`crate::query`) end-to-end — parse (vendored spargebra) → plan → aggregate eval →
/// the `F::Multiplicity` dispatch arm reading the per-member thread-local set by
/// `group_multiplicities` — so the new lines are covered by the coverage ratchet.
///
/// The multiset is built with a sub-SELECT that projects away the per-row subject, so several
/// subjects sharing a value collapse to byte-identical solutions (bag semantics, no implicit
/// DISTINCT). That gives a group whose distinct members carry a multiplicity > 1, which is the
/// only configuration in which `MULTIPLICITY()` is observable.
#[cfg(test)]
mod multiplicity_builtin {
    use super::*;

    /// `?x` over `{10×3, 20×2}`: three subjects with value 10, two with value 20. The
    /// sub-SELECT projects only `?x`, so the outer aggregate sees the bag {10,10,10,20,20}.
    fn g() -> Graph {
        Graph::load_str(
            "@prefix ex: <http://ex/> . \
             ex:a ex:v 10 . ex:b ex:v 10 . ex:c ex:v 10 . \
             ex:d ex:v 20 . ex:e ex:v 20 .",
            "turtle",
        )
        .unwrap()
    }

    fn run(q: &str) -> QueryResult {
        crate::query(&g(), &format!("PREFIX ex: <http://ex/> {q}")).unwrap()
    }

    fn int_lit(n: i64) -> Term {
        Term::Literal(oxrdf::Literal::new_typed_literal(n.to_string(), oxrdf::vocab::xsd::INTEGER))
    }

    /// The headline identity: over the DISTINCT solutions weighted by `MULTIPLICITY()`,
    /// `SUM(?x * MULTIPLICITY())` equals plain `SUM(?x)` over the bag. 10·3 + 20·2 = 70,
    /// and 10+10+10+20+20 = 70. This is exactly the `SUM(?x * multiplicity())` example from
    /// the survey §B2 / `research/sparql12-engine.md` §1.4.
    #[test]
    fn weighted_sum_equals_bag_sum() {
        let r = run(
            "SELECT (SUM(?x) AS ?bag) (SUM(?x * MULTIPLICITY()) AS ?w) \
             WHERE { SELECT ?x WHERE { ?s ex:v ?x } }",
        );
        assert_eq!(r.rows.len(), 1);
        assert_eq!(r.rows[0][0], Some(int_lit(70)), "plain SUM over the bag");
        assert_eq!(r.rows[0][1], Some(int_lit(70)), "MULTIPLICITY-weighted SUM must match");
    }

    /// Bare `SUM(MULTIPLICITY())` over the distinct members sums the bag cardinalities, i.e.
    /// recovers the total bag size: 3 + 2 = 5 = `COUNT(*)`.
    #[test]
    fn sum_of_multiplicities_is_bag_size() {
        let r = run(
            "SELECT (SUM(MULTIPLICITY()) AS ?n) (COUNT(*) AS ?c) \
             WHERE { SELECT ?x WHERE { ?s ex:v ?x } }",
        );
        assert_eq!(r.rows.len(), 1);
        assert_eq!(r.rows[0][0], Some(int_lit(5)), "Σ multiplicity = bag size");
        assert_eq!(r.rows[0][1], Some(int_lit(5)), "COUNT(*) = bag size");
    }

    /// Per-GROUP multiplicity: grouping by `?x` gives one group per distinct value, each a
    /// single distinct member whose multiplicity is the group's bag count (3 for x=10, 2 for
    /// x=20). `MAX(MULTIPLICITY())` surfaces that count directly per group.
    #[test]
    fn per_group_multiplicity_in_grouped_select() {
        let r = run(
            "SELECT ?x (MAX(MULTIPLICITY()) AS ?m) \
             WHERE { SELECT ?x WHERE { ?s ex:v ?x } } GROUP BY ?x ORDER BY ?x",
        );
        assert_eq!(r.rows.len(), 2, "two distinct values ⇒ two groups");
        // ORDER BY ?x: 10 then 20.
        assert_eq!(r.rows[0], vec![Some(int_lit(10)), Some(int_lit(3))]);
        assert_eq!(r.rows[1], vec![Some(int_lit(20)), Some(int_lit(2))]);
    }

    /// A group with NO duplicates: every distinct member has multiplicity 1, so
    /// `SUM(?x * MULTIPLICITY())` is just `SUM(?x)` and `MULTIPLICITY()` is uniformly 1.
    #[test]
    fn all_unique_solutions_have_multiplicity_one() {
        let graph = Graph::load_str(
            "@prefix ex: <http://ex/> . ex:a ex:v 1 . ex:b ex:v 2 . ex:c ex:v 3 .",
            "turtle",
        )
        .unwrap();
        let r = crate::query(
            &graph,
            "PREFIX ex: <http://ex/> SELECT (SUM(?x * MULTIPLICITY()) AS ?w) (SUM(MULTIPLICITY()) AS ?n) \
             WHERE { SELECT ?x WHERE { ?s ex:v ?x } }",
        )
        .unwrap();
        assert_eq!(r.rows[0][0], Some(int_lit(6)), "1+2+3, each ×1");
        assert_eq!(r.rows[0][1], Some(int_lit(3)), "three distinct members, each multiplicity 1");
    }

    /// `MULTIPLICITY()` is only meaningful inside an aggregate argument. Used in a plain BIND
    /// (no aggregate context), the thread-local context is absent, so it is an expression
    /// error → the BIND leaves `?m` UNBOUND (SPARQL error discipline), NOT a hard failure.
    #[test]
    fn multiplicity_outside_aggregate_is_unbound() {
        let r = run("SELECT ?s ?m WHERE { ?s ex:v ?x . BIND(MULTIPLICITY() AS ?m) } ORDER BY ?s");
        assert_eq!(r.rows.len(), 5, "one row per matching subject");
        for row in &r.rows {
            assert!(row[0].is_some(), "?s bound");
            assert_eq!(row[1], None, "MULTIPLICITY() outside an aggregate is an error ⇒ ?m unbound");
        }
    }

    /// The common case — an aggregate that never mentions `MULTIPLICITY()` — is byte-for-byte
    /// unchanged: the duplicate-collapsing path is not taken, the full bag is folded. Plain
    /// `SUM(?x)` over {10×3,20×2} stays 70 (NOT the distinct-set 30).
    #[test]
    fn aggregate_without_multiplicity_folds_full_bag() {
        let r = run("SELECT (SUM(?x) AS ?bag) (COUNT(?x) AS ?c) WHERE { SELECT ?x WHERE { ?s ex:v ?x } }");
        assert_eq!(r.rows[0][0], Some(int_lit(70)), "full bag sum, no distinct collapse");
        assert_eq!(r.rows[0][1], Some(int_lit(5)), "COUNT folds the full bag");
    }

    /// Direct unit coverage of the `group_multiplicities` helper: it returns `None` when the
    /// argument never calls `MULTIPLICITY()` (so the common path pays nothing) and the
    /// distinct-with-cardinalities table when it does.
    #[test]
    fn group_multiplicities_helper_gating() {
        use spargebra::algebra::Function;
        let b = Bindings::unsorted(
            vec![],
            vec![
                std::iter::once(dict::INLINE_BASE + 10).collect::<Row>(),
                std::iter::once(dict::INLINE_BASE + 10).collect::<Row>(),
                std::iter::once(dict::INLINE_BASE + 20).collect::<Row>(),
            ],
        );
        let members = [0usize, 1, 2];
        // A variable-only argument: no MULTIPLICITY() ⇒ None (full-bag path).
        let var = Expression::Variable(Variable::new_unchecked("x"));
        assert!(group_multiplicities(&b, &members, &var).is_none());
        // A MULTIPLICITY() call ⇒ distinct rows + cardinalities, first-seen order.
        let mult = Expression::FunctionCall(
            Function::Custom(oxrdf::NamedNode::new_unchecked(MULTIPLICITY_FN_IRI)),
            vec![],
        );
        let table = group_multiplicities(&b, &members, &mult).expect("multiplicity present ⇒ Some");
        let cards: Vec<u64> = table.iter().map(|&(_, c)| c).collect();
        assert_eq!(cards, vec![2, 1], "two distinct rows: first with cardinality 2, second 1");
    }

    /// [OPUS-4.8] (sq-v411r) Direct unit coverage of `expr_uses_multiplicity` across EVERY
    /// arm of its expression-tree walk. This boolean is load-bearing for correctness — it is
    /// the gate that decides whether `eval_aggregate` / `eval_custom_aggregate` take the
    /// distinct-collapsing (`group_multiplicities`-built) path, so a missed/false detection
    /// would silently fold the wrong multiset. The query-level tests above reach only the
    /// `Multiply`, `FunctionCall(Custom)` and `Variable` arms; this exercises the leaves
    /// (`NamedNode`/`Literal`/`Variable`/`Bound`/`Exists`), the binary/unary recursion, the
    /// `If`/`In`/`Coalesce`/`FunctionCall(args)` arms, and — crucially — the `Exists`
    /// non-descent contract (a `MULTIPLICITY()` buried inside an `EXISTS` belongs to that
    /// sub-query's scope and must NOT be reported here).
    #[test]
    fn expr_uses_multiplicity_walks_every_arm() {
        use spargebra::algebra::{Function, GraphPattern};

        let mult = || {
            Expression::FunctionCall(
                Function::Custom(oxrdf::NamedNode::new_unchecked(MULTIPLICITY_FN_IRI)),
                vec![],
            )
        };
        let var = || Expression::Variable(Variable::new_unchecked("x"));
        let lit = || Expression::Literal(oxrdf::Literal::from(1));
        let bx = Box::new;

        // --- Leaves: never contain MULTIPLICITY() on their own. ---
        assert!(!expr_uses_multiplicity(&var()));
        assert!(!expr_uses_multiplicity(&lit()));
        assert!(!expr_uses_multiplicity(&Expression::NamedNode(oxrdf::NamedNode::new_unchecked(
            "http://ex/p"
        ))));
        assert!(!expr_uses_multiplicity(&Expression::Bound(Variable::new_unchecked("y"))));

        // A `MULTIPLICITY()` with arguments is NOT the reserved zero-arg builtin ⇒ false
        // (the `if args.is_empty()` guard), and a non-Custom function with no inner
        // MULTIPLICITY() is false too.
        let mult_with_args = Expression::FunctionCall(
            Function::Custom(oxrdf::NamedNode::new_unchecked(MULTIPLICITY_FN_IRI)),
            vec![var()],
        );
        assert!(!expr_uses_multiplicity(&mult_with_args), "zero-arg guard: args ⇒ not the builtin");

        // --- The matching leaf. ---
        assert!(expr_uses_multiplicity(&mult()), "the reserved zero-arg call IS detected");

        // --- Binary recursion (left and right branch). ---
        assert!(expr_uses_multiplicity(&Expression::Multiply(bx(var()), bx(mult()))));
        assert!(expr_uses_multiplicity(&Expression::Add(bx(mult()), bx(var()))));
        assert!(expr_uses_multiplicity(&Expression::Or(bx(var()), bx(mult()))));
        assert!(expr_uses_multiplicity(&Expression::And(bx(mult()), bx(var()))));
        assert!(expr_uses_multiplicity(&Expression::Equal(bx(var()), bx(mult()))));
        assert!(expr_uses_multiplicity(&Expression::SameTerm(bx(mult()), bx(var()))));
        assert!(expr_uses_multiplicity(&Expression::Greater(bx(var()), bx(mult()))));
        assert!(expr_uses_multiplicity(&Expression::Less(bx(mult()), bx(var()))));
        assert!(!expr_uses_multiplicity(&Expression::Subtract(bx(var()), bx(lit()))));

        // --- Unary recursion. ---
        assert!(expr_uses_multiplicity(&Expression::UnaryMinus(bx(mult()))));
        assert!(expr_uses_multiplicity(&Expression::Not(bx(mult()))));
        assert!(!expr_uses_multiplicity(&Expression::UnaryPlus(bx(var()))));

        // --- Ternary `If` (each of the three positions). ---
        assert!(expr_uses_multiplicity(&Expression::If(bx(mult()), bx(var()), bx(lit()))));
        assert!(expr_uses_multiplicity(&Expression::If(bx(var()), bx(mult()), bx(lit()))));
        assert!(expr_uses_multiplicity(&Expression::If(bx(var()), bx(lit()), bx(mult()))));
        assert!(!expr_uses_multiplicity(&Expression::If(bx(var()), bx(lit()), bx(var()))));

        // --- List arms: `In` (head + list), `Coalesce`, `FunctionCall(_, args)`. ---
        assert!(expr_uses_multiplicity(&Expression::In(bx(mult()), vec![var()])));
        assert!(expr_uses_multiplicity(&Expression::In(bx(var()), vec![lit(), mult()])));
        assert!(!expr_uses_multiplicity(&Expression::In(bx(var()), vec![lit()])));
        assert!(expr_uses_multiplicity(&Expression::Coalesce(vec![var(), mult()])));
        assert!(!expr_uses_multiplicity(&Expression::Coalesce(vec![var(), lit()])));
        assert!(expr_uses_multiplicity(&Expression::FunctionCall(Function::Str, vec![mult()])));
        assert!(!expr_uses_multiplicity(&Expression::FunctionCall(Function::Str, vec![var()])));

        // --- The `Exists` non-descent contract: a MULTIPLICITY() inside an EXISTS belongs to
        //     that sub-query's scope, so it must NOT be reported for THIS aggregate. ---
        let exists_with_mult = Expression::Exists(Box::new(GraphPattern::Filter {
            expr: mult(),
            inner: Box::new(GraphPattern::Bgp { patterns: vec![] }),
        }));
        assert!(
            !expr_uses_multiplicity(&exists_with_mult),
            "MULTIPLICITY() inside EXISTS belongs to the sub-query scope, not descended into"
        );
        // ...but a MULTIPLICITY() in the OUTER branch of an expression whose other branch is an
        // EXISTS is still detected (proves we recurse around, not into, the Exists).
        assert!(expr_uses_multiplicity(&Expression::And(bx(exists_with_mult), bx(mult()))));
    }

    /// [OPUS-4.8] (sq-v411r) Direct unit coverage of the `multiplicity` thread-local context
    /// and its RAII `Guard`: `current()` is `None` outside any `set`; `set(k)` makes
    /// `current()` read `Some(k)`; a NESTED `set` shadows and the inner guard's drop RESTORES
    /// the outer value (the re-entrancy contract that stops an `EXISTS`/sub-query inside an
    /// aggregate argument from observing a stale multiplicity); and dropping the outer guard
    /// clears the context back to `None`.
    #[test]
    fn multiplicity_context_guard_nests_and_restores() {
        assert_eq!(multiplicity::current(), None, "no context outside an aggregate");
        {
            let _outer = multiplicity::set(3);
            assert_eq!(multiplicity::current(), Some(3));
            {
                let _inner = multiplicity::set(7);
                assert_eq!(multiplicity::current(), Some(7), "inner set shadows outer");
            }
            assert_eq!(multiplicity::current(), Some(3), "inner guard drop restores outer");
        }
        assert_eq!(multiplicity::current(), None, "outer guard drop clears the context");
    }
}

/// [OPUS-4.8] sq-rikm7 — ORDER BY / MIN / MAX agree with relational `=`/`<` on
/// f64-collapsed DISTINCT numeric values (integers beyond 2^53, high-precision decimals).
///
/// The lenient numeric arm coerces operands to f64, whose rounding COLLAPSES two distinct
/// exact values that share one f64. The relational operators (`cmp_expr`/`equal_expr`) and
/// MIN/MAX (`num_compare`) already recheck exactly; before this fix ORDER BY did NOT (the
/// substrate `compare_terms` numeric arm and the engine's numeric SortCell fast path both
/// collapsed), so ORDER BY disagreed with them. These tests pin the agreement and FAIL if
/// either recheck (the `compare_terms` `exact_cmp` hook or the `cmp_sort_num` tie recheck)
/// is reverted.
#[cfg(test)]
mod f64_collapse_order_agreement {
    use super::*;

    fn lex(t: &Option<Term>) -> String {
        match t {
            Some(Term::Literal(l)) => l.value().to_string(),
            // Positional arg (not inline `{other:?}`) to dodge the CodeQL
            // `rust/unused-variable` false positive. [OPUS-4.8]
            other => panic!("expected a literal sort key, got {:?}", other),
        }
    }

    fn order_by(g: &Graph, clause: &str) -> Vec<String> {
        let q = format!("PREFIX ex: <http://ex/> SELECT ?v WHERE {{ ?s ex:v ?v }} ORDER BY {}", clause);
        crate::query(g, &q).unwrap().rows.iter().map(|r| lex(&r[0])).collect()
    }

    #[test]
    fn order_by_agrees_with_minmax_on_big_integers_beyond_2_53() {
        // 2^53 (…992) and 2^53 + 1 (…993) share ONE f64 (…993 is not representable). Both
        // fit i64, so the graph interns them as exact `xsd:integer` terms; the numerics
        // cache stores only f64, collapsing them. The ids are laid out big-then-small so a
        // COLLAPSE (Equal) sort would keep the input order — the ASC/DESC checks catch it.
        let g = Graph::load_str(
            "@prefix ex: <http://ex/> .\n\
             ex:a ex:v 9007199254740993 .\n\
             ex:b ex:v 9007199254740992 .\n",
            "turtle",
        )
        .unwrap();
        let small = "9007199254740992".to_string();
        let big = "9007199254740993".to_string();

        // ORDER BY orders by VALUE now — ASC and DESC are proper reverses (pre-fix they were
        // IDENTICAL, both the collapsed input order: THIS is the revert detector).
        assert_eq!(order_by(&g, "ASC(?v)"), vec![small.clone(), big.clone()]);
        assert_eq!(order_by(&g, "DESC(?v)"), vec![big.clone(), small.clone()]);

        // MIN/MAX (already exact via `num_compare`) agree with ORDER BY's endpoints.
        let agg = crate::query(
            &g,
            "PREFIX ex: <http://ex/> SELECT (MIN(?v) AS ?mn) (MAX(?v) AS ?mx) WHERE { ?s ex:v ?v }",
        )
        .unwrap();
        assert_eq!(lex(&agg.rows[0][0]), small, "MIN == ORDER BY ASC head");
        assert_eq!(lex(&agg.rows[0][1]), big, "MAX == ORDER BY DESC head");

        // And relational `<` sees them distinct (b < a): the FILTER keeps exactly the b row.
        let rel = crate::query(
            &g,
            "PREFIX ex: <http://ex/> SELECT ?vb WHERE { ex:b ex:v ?vb . ex:a ex:v ?va . FILTER(?vb < ?va) }",
        )
        .unwrap();
        assert_eq!(rel.rows.len(), 1, "b < a must hold exactly");
        assert_eq!(lex(&rel.rows[0][0]), small);
    }

    #[test]
    fn order_by_orders_high_precision_decimals_by_value() {
        // Two xsd:decimals differing only in the 18th fraction digit — they share one f64.
        let g = Graph::load_str(
            "@prefix ex: <http://ex/> . @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\
             ex:a ex:v \"0.123456789012345679\"^^xsd:decimal .\n\
             ex:b ex:v \"0.123456789012345678\"^^xsd:decimal .\n",
            "turtle",
        )
        .unwrap();
        let small = "0.123456789012345678".to_string();
        let big = "0.123456789012345679".to_string();
        assert_eq!(order_by(&g, "ASC(?v)"), vec![small.clone(), big.clone()]);
        assert_eq!(order_by(&g, "DESC(?v)"), vec![big, small]);
    }

    #[test]
    fn compare_values_exact_rechecks_f64_collapsed_numeric_values() {
        // Directly exercises the substrate `exact_cmp` hook the engine implements for `Value`
        // (the general `compare_values` path — the MIN/MAX mixed-type fallback and any consumer
        // that orders numeric Values). Two integers beyond 2^53 share an f64 yet must order.
        let a = Value::Term(Term::Literal(Literal::new_typed_literal("9007199254740993", xsd::INTEGER)));
        let b = Value::Term(Term::Literal(Literal::new_typed_literal("9007199254740992", xsd::INTEGER)));
        assert_eq!(as_num(&a), as_num(&b), "the f64 arm COLLAPSES the pair");
        assert_eq!(compare_values(&a, &b), Some(Ordering::Greater));
        assert_eq!(compare_values(&b, &a), Some(Ordering::Less));

        // High-precision decimals sharing one f64.
        let c = Value::Term(Term::Literal(Literal::new_typed_literal("0.123456789012345679", xsd::DECIMAL)));
        let d = Value::Term(Term::Literal(Literal::new_typed_literal("0.123456789012345678", xsd::DECIMAL)));
        assert_eq!(as_num(&c), as_num(&d));
        assert_eq!(compare_values(&c, &d), Some(Ordering::Greater));

        // A genuinely equal-VALUED cross-type pair stays Equal (no spurious inequality):
        // 1 (integer) vs 1.0 (decimal).
        let one_int = Value::Term(Term::Literal(Literal::new_typed_literal("1", xsd::INTEGER)));
        let one_dec = Value::Num(Num::Dec(Dec { mant: 10, scale: 1 }));
        assert_eq!(compare_values(&one_int, &one_dec), Some(Ordering::Equal));

        // Two xsd:doubles that are f64-equal ARE equal: the engine's `exact_cmp` delegates to
        // `num_compare`, whose f64 fallback (doubles have no exact decimal tier) returns Equal
        // — so the collapse is correctly left in place, never a spurious inequality.
        let dbl = Value::Num(Num::Double(9_007_199_254_740_992.0));
        assert_eq!(dbl.exact_cmp(&dbl), Some(Ordering::Equal));
        // A non-numeric operand has no exact recheck at all -> `None` (the f64 verdict stands).
        let iri = Value::Term(Term::NamedNode(oxrdf::NamedNode::new("http://ex/x").unwrap()));
        assert_eq!(dbl.exact_cmp(&iri), None, "non-numeric -> no exact recheck");
    }

    #[test]
    fn as_num_routes_through_parse_xsd_f64_agreeing_with_as_numeric() {
        // [OPUS-4.8] sq-rkzhr: the LENIENT `as_num` (the `CompareTerm::as_f64` seam that
        // drives ORDER BY / the lenient numeric compare) must accept EXACTLY the double /
        // float lexicals the EXACT `as_numeric` path accepts. Otherwise the sq-rikm7
        // f64-collapse recheck can see a literal that is "numeric-and-equal" under `as_f64`
        // yet yields no exact-recheck value (`exact_cmp` -> None) — the very asymmetry
        // sq-rikm7 removed. `str::parse::<f64>` swallowed the non-XSD `inf`/`infinity`/`nan`
        // spellings; `parse_xsd_f64` (shared with `as_numeric`) does not.
        let dbl = |s: &str| Value::Term(Term::Literal(Literal::new_typed_literal(s, xsd::DOUBLE)));
        let flt = |s: &str| Value::Term(Term::Literal(Literal::new_typed_literal(s, xsd::FLOAT)));

        // The XSD specials parse (this held via Rust's parser before, and still does).
        assert_eq!(as_num(&dbl("INF")), Some(f64::INFINITY));
        assert_eq!(as_num(&dbl("+INF")), Some(f64::INFINITY));
        assert_eq!(as_num(&dbl("-INF")), Some(f64::NEG_INFINITY));
        assert!(matches!(as_num(&dbl("NaN")), Some(n) if n.is_nan()));
        assert_eq!(as_num(&flt("INF")), Some(f64::INFINITY));
        assert!(matches!(as_num(&flt("NaN")), Some(n) if n.is_nan()));

        // Non-XSD spellings Rust's `str::parse::<f64>` accepts are now REJECTED, matching
        // `as_numeric` (before the fix `as_num` accepted them -> the two paths disagreed).
        for bad in ["inf", "+inf", "infinity", "-infinity", "nan", "Infinity"] {
            // Positional args dodge the CodeQL `rust/unused-variable` false positive. [OPUS-4.8]
            assert_eq!(as_num(&dbl(bad)), None, "as_num must reject non-XSD spelling {:?}", bad);
            assert!(as_numeric(&dbl(bad)).is_none(), "as_numeric already rejects {:?}", bad);
        }

        // The alignment invariant: the lenient and exact paths agree on presence for EVERY
        // lexical — valid specials, ordinary numbers, non-XSD spellings, and non-numerics.
        for s in ["INF", "+INF", "-INF", "NaN", "6", "6.0E0", "2.0E-1", "inf", "nan", "hello"] {
            assert_eq!(
                as_num(&dbl(s)).is_some(),
                as_numeric(&dbl(s)).is_some(),
                "as_num / as_numeric disagree on the validity of {:?}",
                s
            );
        }

        // [FABLE-5] sq-74oy4 / sq-6b1lj: the alignment now extends to PER-DATATYPE
        // well-formedness AND whitespace. `as_num` is datatype-aware and trimming, so it
        // agrees with `as_numeric` (`Num::of_literal`) on integer/decimal lexicals too — a
        // padded lexical is its trimmed value; a lexical ill-formed FOR its datatype is None.
        let ints = |s: &str| Value::Term(Term::Literal(Literal::new_typed_literal(s, xsd::INTEGER)));
        let decs = |s: &str| Value::Term(Term::Literal(Literal::new_typed_literal(s, xsd::DECIMAL)));
        assert_eq!(as_num(&ints(" 1 ")), Some(1.0), "padded integer trims to 1");
        assert_eq!(as_num(&decs(" 1.5 ")), Some(1.5), "padded decimal trims to 1.5");
        assert_eq!(as_num(&ints("1.5")), None, "fraction on integer is a type error");
        assert_eq!(as_num(&ints("1E2")), None, "exponent on integer is a type error");
        assert_eq!(as_num(&decs("1E2")), None, "exponent on decimal is a type error");
        // Every one agrees with the exact `as_numeric` seam.
        for (v, _lbl) in [
            (ints(" 1 "), "padded int"), (decs(" 1.5 "), "padded dec"),
            (ints("1.5"), "int fraction"), (ints("1E2"), "int exp"), (decs("1E2"), "dec exp"),
        ] {
            assert_eq!(
                as_num(&v).is_some(),
                as_numeric(&v).is_some(),
                "as_num / as_numeric disagree on datatype-aware validity"
            );
        }
    }

    #[test]
    fn compare_orders_double_infinities_and_isolates_nan() {
        // [OPUS-4.8] sq-rkzhr: with `as_num` routed through `parse_xsd_f64`, the lenient
        // compare seam orders the XSD floating specials by value (-INF < finite < +INF).
        // [FABLE-5] sq-wjl8i: NaN is TOTALISED into the order — it sorts FIRST (before
        // -INF) and ties with itself, instead of the former `None` (which callers mapped
        // to Equal, making NaN "equal" to every numeric — the partiality witness).
        // Relational `<` / `=` keep their NaN type-error semantics untouched.
        let d = |s: &str| Value::Term(Term::Literal(Literal::new_typed_literal(s, xsd::DOUBLE)));
        let (neg_inf, inf, five, nan) = (d("-INF"), d("INF"), d("5.0E0"), d("NaN"));
        assert_eq!(compare_values(&neg_inf, &five), Some(Ordering::Less));
        assert_eq!(compare_values(&five, &inf), Some(Ordering::Less));
        assert_eq!(compare_values(&neg_inf, &inf), Some(Ordering::Less));
        assert_eq!(compare_values(&inf, &inf), Some(Ordering::Equal));
        assert_eq!(compare_values(&nan, &five), Some(Ordering::Less));
        assert_eq!(compare_values(&five, &nan), Some(Ordering::Greater));
        assert_eq!(compare_values(&nan, &neg_inf), Some(Ordering::Less));
        assert_eq!(compare_values(&nan, &nan), Some(Ordering::Equal));

        // End-to-end ORDER BY over stored double specials exercises the REAL query path
        // (NaN routes through the general sort cell: the numerics cache uses NaN as its
        // not-numeric sentinel, so the fast numeric cell never sees it).
        let g = Graph::load_str(
            "@prefix ex: <http://ex/> . @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\
             ex:a ex:v \"-INF\"^^xsd:double .\n\
             ex:b ex:v \"5.0E0\"^^xsd:double .\n\
             ex:c ex:v \"INF\"^^xsd:double .\n\
             ex:d ex:v \"NaN\"^^xsd:double .\n",
            "turtle",
        )
        .unwrap();
        assert_eq!(order_by(&g, "ASC(?v)"), vec!["NaN", "-INF", "5.0E0", "INF"]);
        assert_eq!(order_by(&g, "DESC(?v)"), vec!["INF", "5.0E0", "-INF", "NaN"]);
    }

    #[test]
    fn order_by_mixed_numeric_string_temporal_column_is_deterministic() {
        // A single ORDER BY column mixing a numeric graph term, a plain-string literal and an
        // xsd:dateTime exercises the `Num`-vs-`Val` / `Num`-vs-`Temp` sort-cell cross arms
        // (which reconstruct the `Val(Num::Double)` representation and defer to the shared
        // `compare_values`). [FABLE-5] sq-wjl8i: cross-KIND literal pairs rank by
        // `LiteralKind` (numeric < dateTime < string) — the exact order is additionally
        // pinned end-to-end by `order_by_cross_kind_ranks_and_collapse_is_exact`; this test
        // keeps the permutation/reversibility shape claims.
        let g = Graph::load_str(
            "@prefix ex: <http://ex/> . @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\
             ex:n ex:v 5 .\n\
             ex:s ex:v \"apple\" .\n\
             ex:t ex:v \"2024-03-15T13:00:00Z\"^^xsd:dateTime .\n",
            "turtle",
        )
        .unwrap();
        // The result is a stable, deterministic permutation (the exact cross-type tie order is
        // spec-unconstrained, but must not panic and must round-trip every row exactly once).
        let asc = order_by(&g, "ASC(?v)");
        let desc = order_by(&g, "DESC(?v)");
        assert_eq!(asc.len(), 3);
        assert_eq!(desc.len(), 3);
        let mut sorted_asc = asc.clone();
        sorted_asc.sort();
        let mut sorted_desc = desc.clone();
        sorted_desc.sort();
        assert_eq!(sorted_asc, sorted_desc, "ASC and DESC are permutations of the same rows");
        // DESC is the exact reverse of ASC (total order over distinct-valued rows).
        let mut rev = asc.clone();
        rev.reverse();
        assert_eq!(rev, desc, "DESC(?v) is ASC(?v) reversed");
    }

    /// [FABLE-5] sq-wjl8i end-to-end: the kind-first rank and the exact mixed-tier
    /// collapse recheck through the REAL query path (both the numeric sort-cell fast
    /// path — all-numeric column — and the mixed-kind `compare_values` path).
    #[test]
    fn order_by_cross_kind_ranks_and_collapse_is_exact() {
        // All-NUMERIC column at the 2^53 collapse: int 2^53, int 2^53+1 and the double
        // carrying their shared f64 image. The exact order is 2^53 = 2^53E0 < 2^53+1
        // (the former three-way collapsed tie was intransitive against the exact
        // int/int order). The int/int and int/double ties are decided by
        // `cmp_sort_num`'s exact recheck (the fast numeric sort cells).
        let g = Graph::load_str(
            "@prefix ex: <http://ex/> . @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\
             ex:a ex:v \"9007199254740993\"^^xsd:integer .\n\
             ex:b ex:v \"9007199254740992E0\"^^xsd:double .\n\
             ex:c ex:v \"9007199254740992\"^^xsd:integer .\n",
            "turtle",
        )
        .unwrap();
        let asc = order_by(&g, "ASC(?v)");
        // The equal pair (2^53, 2^53E0) keeps input order (stable sort); both precede 2^53+1.
        assert_eq!(asc[2], "9007199254740993", "the collapsed neighbour sorts strictly last");
        assert!(asc[..2].contains(&"9007199254740992E0".to_string()));
        assert!(asc[..2].contains(&"9007199254740992".to_string()));

        // MIXED-KIND column: every numeric (NaN included) sorts before the boolean,
        // the dateTime before the date, both before the plain string, the string
        // before the language-tagged literal, and the unknown-datatype literal last —
        // the documented LiteralKind rank; the digit-string "11" can no longer
        // interleave lexically between numerics 10 and 2 (the sq-wjl8i witness).
        let g2 = Graph::load_str(
            "@prefix ex: <http://ex/> . @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\
             ex:s ex:v \"11\" .\n\
             ex:n1 ex:v 10 .\n\
             ex:n2 ex:v 2 .\n\
             ex:nan ex:v \"NaN\"^^xsd:double .\n\
             ex:bt ex:v true .\n\
             ex:dt ex:v \"2024-03-15T13:00:00Z\"^^xsd:dateTime .\n\
             ex:d ex:v \"2020-01-01\"^^xsd:date .\n\
             ex:lang ex:v \"chat\"@fr .\n\
             ex:odd ex:v \"weird\"^^ex:custom .\n",
            "turtle",
        )
        .unwrap();
        assert_eq!(
            order_by(&g2, "ASC(?v)"),
            vec!["NaN", "2", "10", "true", "2024-03-15T13:00:00Z", "2020-01-01", "11", "chat", "weird"]
        );
    }
}

// [OPUS-4.8] (sq-pntvh.3, M4 Phase 3) Seam-level differential for the columnar residual-FILTER
// path. The chunk-primitive kernels are unit-tested in `chunk.rs`; this asserts the load-bearing
// wiring invariant: `apply_filter`'s columnar seam produces `b.rows` BYTE-IDENTICAL (same rows,
// same order) to the scalar row path over a REAL graph, and DECLINES (falls back to the scalar
// path) on every column shape not provably identical. Only built under the opt-in `vectorized`
// feature.
#[cfg(all(test, feature = "vectorized"))]
mod columnar_filter_seam {
    use super::*;

    const XSD_INT: &str = "http://www.w3.org/2001/XMLSchema#integer";

    /// `n` triples `ex:s{i} ex:age {i}` (integer literal → inline id). Returns
    /// (graph, subject ids [dict IRIs, NON-inline], age ids [inline integers]).
    fn ages_graph(n: u32) -> (Graph, Vec<Id>, Vec<Id>) {
        let mut nt = String::new();
        for i in 0..n {
            nt.push_str(&format!("<http://ex/s{i}> <http://ex/age> \"{i}\"^^<{XSD_INT}> .\n"));
        }
        let g = Graph::load_str(&nt, "ntriples").unwrap();
        let subj = (0..n)
            .map(|i| g.id_of(&Term::NamedNode(oxrdf::NamedNode::new(format!("http://ex/s{i}")).unwrap())).unwrap())
            .collect();
        let age = (0..n)
            .map(|i| g.id_of(&Term::Literal(Literal::new_typed_literal(i.to_string(), xsd::INTEGER))).unwrap())
            .collect();
        (g, subj, age)
    }

    fn var(name: &str) -> Variable {
        Variable::new(name).unwrap()
    }

    fn int_lit(s: &str) -> Expression {
        Expression::Literal(Literal::new_typed_literal(s, xsd::INTEGER))
    }

    /// `?v OP konst`.
    fn mk_filter(op: &str, v: &Variable, konst: Expression) -> Expression {
        let a = Box::new(Expression::Variable(v.clone()));
        let k = Box::new(konst);
        match op {
            ">" => Expression::Greater(a, k),
            ">=" => Expression::GreaterOrEqual(a, k),
            "<" => Expression::Less(a, k),
            "<=" => Expression::LessOrEqual(a, k),
            "=" => Expression::Equal(a, k),
            _ => unreachable!(),
        }
    }

    /// The numeric age values (inline column, index 1) of a result row set, in order.
    fn age_values(g: &Graph, rows: &[Row]) -> Vec<f64> {
        rows.iter().map(|r| g.numeric_value(r[1]).unwrap()).collect()
    }

    #[test]
    fn columnar_seam_is_byte_identical_to_scalar_on_inline_column() {
        // n=300 ensures the batch exceeds VEC_MIN_BATCH (256) so columnar_filter engages.
        // [SONNET-4.6] (sq-y5ew5) Updated for the new 4-arg signature and Result return type.
        let n = 300u32;
        let (g, subj, age) = ages_graph(n);
        let vars = vec![var("s"), var("age")];
        let rows: Vec<Row> = (0..n as usize).map(|i| Row::from_slice(&[subj[i], age[i]])).collect();
        let local = LocalVocab::default();
        let age_var = var("age");

        for (op, t) in [
            (">", "20"), (">=", "20"), ("<", "10"), ("<=", "10"),
            ("=", "13"), (">", "39"), (">=", "0"), (">", "100"),
        ] {
            let expr = mk_filter(op, &age_var, int_lit(t));

            // The seam ENGAGES for an all-inline column: Result is Ok(Some(rows)).
            let via_columnar = columnar_filter(&g, &local, &Bindings::unsorted(vars.clone(), rows.clone()), &expr);
            assert!(via_columnar.as_ref().unwrap().is_some(), "all-inline column must be columnar-eligible ({op} {t})");

            // Scalar reference (the real row path).
            let mut scalar = Bindings::unsorted(vars.clone(), rows.clone());
            apply_filter_scalar(&g, &local, &mut scalar, &expr).unwrap();

            // Dispatcher (takes the columnar branch under the feature).
            let mut disp = Bindings::unsorted(vars.clone(), rows.clone());
            apply_filter(&g, &local, &mut disp, &expr).unwrap();

            // BYTE-IDENTICAL: same rows (incl. the NON-inline subject column), same order.
            assert_eq!(disp.rows, scalar.rows, "dispatcher rows != scalar for {op} {t}");
            assert_eq!(via_columnar.as_ref().unwrap().as_ref().unwrap(), &scalar.rows, "columnar_filter rows != scalar for {op} {t}");
        }
    }

    #[test]
    fn columnar_seam_pins_exact_survivors_and_order() {
        // Non-vacuous: pin the EXACT surviving age sequence (content + ascending order) so a
        // wrong mask (off-by-one / inverted / column desync) turns this red.
        // n=300 ensures the batch exceeds VEC_MIN_BATCH (256) so columnar_filter engages.
        // [SONNET-4.6] (sq-y5ew5) Updated for new signature and Result<Option<Vec<Row>>> return.
        let n = 300u32;
        let (g, subj, age) = ages_graph(n);
        let vars = vec![var("s"), var("age")];
        let rows: Vec<Row> = (0..n as usize).map(|i| Row::from_slice(&[subj[i], age[i]])).collect();
        let local = LocalVocab::default();
        let age_var = var("age");

        let out = columnar_filter(&g, &local, &Bindings::unsorted(vars.clone(), rows.clone()), &mk_filter(">", &age_var, int_lit("20"))).unwrap().unwrap();
        let expected: Vec<f64> = (21..300).map(f64::from).collect();
        assert_eq!(age_values(&g, &out), expected, "age > 20 must keep 21..=299, ascending");

        // A DIFFERENT filter must select a DIFFERENT set (the mask does real work).
        let other = columnar_filter(&g, &local, &Bindings::unsorted(vars, rows), &mk_filter("<", &age_var, int_lit("20"))).unwrap().unwrap();
        assert_ne!(age_values(&g, &other), expected, "distinct filters must select distinct rows");
    }

    #[test]
    fn columnar_seam_declines_small_batches_regardless_of_column_type() {
        // A batch of 2 rows is below VEC_MIN_BATCH (256), so the seam DECLINES regardless
        // of the column type (non-inline ints, negatives, strings, unbound). The scalar path
        // runs in all cases and produces correct results. [SONNET-4.6] (sq-y5ew5) Updated:
        // non-inline columns no longer cause decline for large batches (they use the tri-mask);
        // decline here is due to VEC_MIN_BATCH only.
        let big = 2_000_000_000u32.to_string(); // > INLINE_MAX (2^30-1): a NON-inline dict integer
        let nt = format!(
            "<http://ex/a> <http://ex/age> \"5\"^^<{XSD_INT}> .\n\
             <http://ex/b> <http://ex/age> \"{big}\"^^<{XSD_INT}> .\n\
             <http://ex/c> <http://ex/age> \"-7\"^^<{XSD_INT}> .\n\
             <http://ex/d> <http://ex/age> \"hello\" .\n"
        );
        let g = Graph::load_str(&nt, "ntriples").unwrap();
        let lit_id = |s: &str, dt: Option<&str>| -> Id {
            let t = match dt {
                Some(d) => Term::Literal(Literal::new_typed_literal(s, oxrdf::NamedNode::new(d).unwrap())),
                None => Term::Literal(oxrdf::Literal::new_simple_literal(s)),
            };
            g.id_of(&t).unwrap()
        };
        let five = lit_id("5", Some(XSD_INT));
        assert!(dict::is_inline(five));
        let big_id = lit_id(&big, Some(XSD_INT));
        assert!(!dict::is_inline(big_id), "2e9 must be a NON-inline dict integer");
        let neg = lit_id("-7", Some(XSD_INT));
        let hello = lit_id("hello", None);

        let vars = vec![var("s"), var("age")];
        let expr = mk_filter(">", &var("age"), int_lit("0"));
        let local = LocalVocab::default();

        for age_cell in [big_id, neg, hello, NO_ID] {
            // 2 rows < VEC_MIN_BATCH=256 → seam declines.
            let rows: Vec<Row> = vec![Row::from_slice(&[five, five]), Row::from_slice(&[five, age_cell])];
            assert!(
                columnar_filter(&g, &local, &Bindings::unsorted(vars.clone(), rows.clone()), &expr).unwrap().is_none(),
                "batch of 2 rows must decline (VEC_MIN_BATCH)"
            );
            let mut disp = Bindings::unsorted(vars.clone(), rows.clone());
            let mut scalar = Bindings::unsorted(vars.clone(), rows);
            apply_filter(&g, &local, &mut disp, &expr).unwrap();
            apply_filter_scalar(&g, &local, &mut scalar, &expr).unwrap();
            assert_eq!(disp.rows, scalar.rows, "row-path result must be identical on decline");
        }
    }

    #[test]
    fn columnar_seam_declines_non_sargable_and_temporal_filters() {
        // [SONNET-4.6] (sq-y5ew5) Updated for new 4-arg signature and Result return.
        let n = 8u32;
        let (g, subj, age) = ages_graph(n);
        let vars = vec![var("s"), var("age")];
        let rows: Vec<Row> = (0..n as usize).map(|i| Row::from_slice(&[subj[i], age[i]])).collect();
        let b = Bindings::unsorted(vars, rows);
        let local = LocalVocab::default();
        let age_var = var("age");

        // var-vs-var: not sargable → decline.
        let var_var = Expression::Greater(
            Box::new(Expression::Variable(age_var.clone())),
            Box::new(Expression::Variable(var("s"))),
        );
        assert!(columnar_filter(&g, &local, &b, &var_var).unwrap().is_none());

        // A temporal comparison is sargable but has NO vector kernel yet → decline.
        let dt = Expression::Literal(Literal::new_typed_literal(
            "2020-01-01T00:00:00Z",
            oxrdf::NamedNode::new("http://www.w3.org/2001/XMLSchema#dateTime").unwrap(),
        ));
        let temporal = Expression::Greater(Box::new(Expression::Variable(age_var)), Box::new(dt));
        assert!(columnar_filter(&g, &local, &b, &temporal).unwrap().is_none(), "temporal comparison has no vector kernel");
    }

    #[cfg(feature = "zk")]
    #[test]
    fn columnar_seam_declines_while_zk_trace_armed() {
        // The zk trace must capture the FILTER obligation set, so the columnar seam DECLINES
        // while the recorder is armed and the scalar path records it
        // (research/vector-at-a-time-m4.md §3.2, open question 2 — simplest-safe rule).
        // n=300 to exceed VEC_MIN_BATCH (256) so the sanity check can confirm eligibility.
        // [SONNET-4.6] (sq-y5ew5) Updated for new 4-arg signature and Result return.
        let n = 300u32;
        let (g, subj, age) = ages_graph(n);
        let vars = vec![var("s"), var("age")];
        let rows: Vec<Row> = (0..n as usize).map(|i| Row::from_slice(&[subj[i], age[i]])).collect();
        let b = Bindings::unsorted(vars, rows);
        let local = LocalVocab::default();
        let expr = mk_filter(">", &var("age"), int_lit("0"));

        // Sanity: eligible (and firing) when zk is NOT armed.
        assert!(columnar_filter(&g, &local, &b, &expr).unwrap().is_some(), "eligible without zk armed");
        // Armed ⇒ decline (I2 fires before VEC_MIN_BATCH, so batch size is irrelevant here).
        let _guard = crate::zk::install();
        assert!(crate::zk::enabled());
        assert!(columnar_filter(&g, &local, &b, &expr).unwrap().is_none(), "columnar seam must decline while zk is armed");
    }
}

// [OPUS-4.8] sq-qcnn.13 — Direct unit tests for internal exec functions (private API).
// These supplement the integration tests in tests/eval_semantics.rs with white-box
// coverage of paths reachable only from inside the crate: `minus_bindings` (disjoint
// fast path + fully-bound fast path + the unbound-shared-variable general compatibility
// scan), `effective_boolean` / `ebv` error arms, aggregate-error propagation via
// `sum_values(_, errored=true)`, and the `minmax_values` numeric-promotion + mixed-type
// fallback paths. [OPUS-4.8]

/// Direct unit tests for `minus_bindings` — exercises the fast-path (disjoint
/// domains → no-op, fully-bound compatible rows) and the general path (unbound
/// shared variable triggering the compatibility scan with bound-domain-overlap check).
#[cfg(test)]
mod minus_bindings_unit {
    use super::*;
    use sparq_core::Graph;

    fn var(s: &str) -> Variable {
        Variable::new_unchecked(s)
    }

    /// `term_id` for a plain literal string via a scratch graph so we get a real
    /// dictionary ID. The same graph must be used for every ID we want to join.
    fn scratch() -> Graph {
        Graph::load_str(
            "@prefix ex: <http://ex/> .\
             ex:a ex:p \"v1\" .\
             ex:b ex:p \"v2\" .\
             ex:c ex:p \"v3\" .",
            "turtle",
        )
        .unwrap()
    }

    /// Resolve an IRI to its dictionary `Id` in the scratch graph. PANICS if the term
    /// is absent (a test-setup mistake): a silent `NO_ID` fallback would masquerade as
    /// an "unbound" sentinel and mask a typo, producing false pass/fail in the MINUS
    /// compatibility tests. The IRI MUST be one interned by `scratch()`.
    fn id(g: &Graph, iri: &str) -> Id {
        use oxrdf::{NamedNode, Term};
        g.id_of(&Term::NamedNode(NamedNode::new(iri).unwrap()))
            .unwrap_or_else(|| panic!("test-setup error: IRI {} is not present in the scratch graph", iri))
    }

    /// Disjoint variable domains: left has {?s} only, right has {?x} only (no overlap).
    /// MINUS must return the left unchanged (fast path: `shared.is_empty()` → return left).
    #[test]
    fn minus_disjoint_domains_returns_left_unchanged() {
        let g = scratch();
        let (a, b, c) = (id(&g, "http://ex/a"), id(&g, "http://ex/b"), id(&g, "http://ex/c"));
        let left = Bindings::unsorted(vec![var("s")], vec![Row::from_slice(&[a]), Row::from_slice(&[b])]);
        let right = Bindings::unsorted(vec![var("x")], vec![Row::from_slice(&[c])]);
        let result = minus_bindings(left, right);
        // No shared variable → nothing removed.
        assert_eq!(result.rows.len(), 2, "disjoint domains: MINUS is a no-op, expected 2 rows");
    }

    /// Fully-bound shared variable (fast path: hash-table lookup).
    /// Left has rows {s=a, s=b}; right has {s=a}. Fast path removes the a row.
    #[test]
    fn minus_fast_path_removes_compatible_row() {
        let g = scratch();
        let (a, b) = (id(&g, "http://ex/a"), id(&g, "http://ex/b"));
        let left = Bindings::unsorted(vec![var("s")], vec![Row::from_slice(&[a]), Row::from_slice(&[b])]);
        let right = Bindings::unsorted(vec![var("s")], vec![Row::from_slice(&[a])]);
        let result = minus_bindings(left, right);
        // a is compatible → removed; b is not in right → kept.
        assert_eq!(result.rows.len(), 1, "fast path must remove compatible row a");
        // The remaining row should be b.
        assert_eq!(result.rows[0][0], b, "remaining row should have s=b");
    }

    /// General path: the left row has an UNBOUND shared variable (`?t = NO_ID`) alongside
    /// a BOUND shared variable (`?s`) whose value agrees with the right row. The unbound
    /// `?t` forces `minus_bindings` off the fast path into the per-row compatibility scan.
    ///
    /// SPARQL MINUS (§18.5): a left row is removed iff some right row is compatible AND
    /// their bound domains overlap on ≥1 shared variable. Here the domains overlap on `?s`
    /// (both bound, `a == a`); `?t` is unbound on the left so it is skipped (compatibility
    /// only constrains variables bound on BOTH sides). Overlap holds ⇒ the row IS removed.
    #[test]
    fn minus_general_path_bound_overlap_removes_despite_unbound_var() {
        let g = scratch();
        let a = id(&g, "http://ex/a");
        // Left: {?s = a, ?t = NO_ID (unbound)}; Right: {?s = a, ?t = a (bound)}.
        let left = Bindings::unsorted(vec![var("s"), var("t")], vec![Row::from_slice(&[a, NO_ID])]);
        let right = Bindings::unsorted(vec![var("s"), var("t")], vec![Row::from_slice(&[a, a])]);
        let result = minus_bindings(left, right);
        // Overlap on ?s (both bound, equal) ⇒ compatible ⇒ removed; the unbound ?t is
        // skipped by the "both sides bound" guard and neither blocks nor causes removal.
        assert_eq!(result.rows.len(), 0, "bound overlap on ?s removes the row even though ?t is unbound on the left");
    }

    /// General path (unbound `?t` on the left forces the per-row compatibility scan off
    /// the fast path): the shared variable `?s` is BOUND on both sides but to DIFFERENT
    /// ids (`a` on the left, `b` on the right); `?t` is unbound on both sides.
    ///
    /// SPARQL MINUS (§18.5): remove the left row iff some right row is compatible AND the
    /// bound domains overlap on ≥1 shared variable. The domains DO overlap on `?s` (bound
    /// on both sides), but the values disagree (`a != b`), so the rows are INCOMPATIBLE —
    /// nothing is removed and the left row is KEPT. (`?t`, unbound on both sides, is in
    /// neither solution's domain and cannot force removal.)
    #[test]
    fn minus_general_path_incompatible_bound_shared_var_keeps_row() {
        let g = scratch();
        let a = id(&g, "http://ex/a");
        let b = id(&g, "http://ex/b");
        // Left: {?s=a, ?t=NO_ID}; Right: {?s=b, ?t=NO_ID}.
        // ?s=a vs ?s=b: BOTH bound but NOT equal → incompatible → row KEPT.
        let left = Bindings::unsorted(vec![var("s"), var("t")], vec![Row::from_slice(&[a, NO_ID])]);
        let right = Bindings::unsorted(vec![var("s"), var("t")], vec![Row::from_slice(&[b, NO_ID])]);
        let result = minus_bindings(left, right);
        // ?s=a != ?s=b → incompatible ⇒ NOT removed.
        assert_eq!(result.rows.len(), 1, "incompatible bound ?s (a != b): left row must be kept");
    }
}

/// Direct unit tests for `effective_boolean` / `ebv`: the three-valued logic gate
/// used by every FILTER application. Pins the SPARQL 3VL contract at the function
/// level so a mutation that collapses error→false or error→true is caught here.
#[cfg(test)]
mod effective_boolean_unit {
    use super::*;

    #[test]
    fn ebv_error_is_none() {
        // SPARQL EBV: error → None (a type error in the expression).
        assert_eq!(ebv(&Value::Error), None, "ebv(Error) must be None");
        assert!(!effective_boolean(&Value::Error), "effective_boolean(Error) must be false (drop row)");
    }

    #[test]
    fn ebv_unbound_is_none() {
        assert_eq!(ebv(&Value::Unbound), None, "ebv(Unbound) must be None");
        assert!(!effective_boolean(&Value::Unbound), "effective_boolean(Unbound) must be false (drop row)");
    }

    #[test]
    fn ebv_bool_true_is_some_true() {
        assert_eq!(ebv(&Value::Bool(true)), Some(true));
        assert!(effective_boolean(&Value::Bool(true)));
    }

    #[test]
    fn ebv_bool_false_is_some_false() {
        assert_eq!(ebv(&Value::Bool(false)), Some(false));
        assert!(!effective_boolean(&Value::Bool(false)));
    }

    #[test]
    fn ebv_nonzero_int_is_true() {
        assert_eq!(ebv(&Value::Num(Num::Int(1))), Some(true));
        assert_eq!(ebv(&Value::Num(Num::Int(-1))), Some(true));
    }

    #[test]
    fn ebv_zero_int_is_false() {
        assert_eq!(ebv(&Value::Num(Num::Int(0))), Some(false));
    }

    #[test]
    fn ebv_iri_term_is_none_type_error() {
        use oxrdf::NamedNode;
        let iri = Value::Term(Term::NamedNode(NamedNode::new_unchecked("http://ex/x")));
        assert_eq!(ebv(&iri), None, "EBV of IRI is a type error → None");
        assert!(!effective_boolean(&iri), "effective_boolean(IRI) = false (drop row)");
    }

    #[test]
    fn ebv_nonempty_string_is_true() {
        let t = Value::Term(Term::Literal(Literal::new_simple_literal("hello")));
        assert_eq!(ebv(&t), Some(true), "non-empty string literal EBV = true");
    }

    #[test]
    fn ebv_empty_string_is_false() {
        let t = Value::Term(Term::Literal(Literal::new_simple_literal("")));
        assert_eq!(ebv(&t), Some(false), "empty string literal EBV = false");
    }

    #[test]
    fn ebv_lang_tagged_literal_is_none_type_error() {
        // rdf:langString is NOT xsd:string: its EBV is a type error.
        let t = Value::Term(Term::Literal(Literal::new_language_tagged_literal_unchecked("hello", "en")));
        assert_eq!(ebv(&t), None, "lang-tagged literal EBV is type error → None");
    }

    #[test]
    fn ebv_typed_boolean_true_false() {
        let tt = Value::Term(Term::Literal(Literal::new_typed_literal("true", xsd::BOOLEAN)));
        let ff = Value::Term(Term::Literal(Literal::new_typed_literal("false", xsd::BOOLEAN)));
        assert_eq!(ebv(&tt), Some(true));
        assert_eq!(ebv(&ff), Some(false));
    }

    #[test]
    fn ebv_ill_formed_boolean_is_type_error() {
        let ill = Value::Term(Term::Literal(Literal::new_typed_literal("yes", xsd::BOOLEAN)));
        assert_eq!(ebv(&ill), None, "ill-formed boolean EBV is type error");
    }

    #[test]
    fn ebv_xsd_string_nonempty_is_true() {
        let s = Value::Term(Term::Literal(Literal::new_typed_literal("abc", xsd::STRING)));
        assert_eq!(ebv(&s), Some(true));
    }

    #[test]
    fn ebv_xsd_string_empty_is_false() {
        let s = Value::Term(Term::Literal(Literal::new_typed_literal("", xsd::STRING)));
        assert_eq!(ebv(&s), Some(false));
    }
}

/// Direct unit tests for `sum_values` — the typed SUM with XSD promotion. Pins the
/// `errored=true` → `None` branch and the integer-only and decimal-promotion paths.
#[cfg(test)]
mod sum_values_unit {
    use super::*;

    #[test]
    fn sum_empty_is_zero_integer() {
        // Sum({}) = 0^^xsd:integer (SPARQL 18.5.1.4).
        let result = sum_values(&[], false);
        // Num does not impl PartialEq; use matches! for the pattern.
        assert!(matches!(result, Some(Num::Int(0))), "sum of empty set must be 0 integer");
    }

    #[test]
    fn sum_errored_is_none() {
        // A type error in ANY member makes the whole SUM None → unbound aggregate.
        let result = sum_values(&[Value::Num(Num::Int(5))], true);
        assert!(result.is_none(), "sum_values with errored=true must return None");
    }

    #[test]
    fn sum_integers_stays_integer() {
        let vals = vec![Value::Num(Num::Int(3)), Value::Num(Num::Int(7))];
        let result = sum_values(&vals, false);
        assert!(matches!(result, Some(Num::Int(10))), "sum of integers must be an integer");
    }

    #[test]
    fn sum_int_plus_decimal_promotes_to_decimal() {
        let dec = Num::Dec(Dec { mant: 5, scale: 1 }); // 0.5
        let vals = vec![Value::Num(Num::Int(2)), Value::Num(dec)];
        let result = sum_values(&vals, false);
        // 2 + 0.5 = 2.5 decimal; the canonical form depends on Num::binop normalisation.
        match result {
            Some(Num::Dec(d)) => {
                // Verify the decimal value is 2.5: mant / 10^scale == 2.5.
                // Dec fields are (mant: i128, scale: u32). Any representation where
                // mant as f64 / 10_f64.powi(scale as i32) ≈ 2.5 is acceptable.
                let v = (d.mant as f64) / 10_f64.powi(d.scale as i32);
                assert!((v - 2.5_f64).abs() < 1e-12_f64, "int+decimal must sum to 2.5, got mant={} scale={}", d.mant, d.scale);
            }
            other => panic!("int+decimal sum must be Decimal, got {other:?}"),
        }
    }

    #[test]
    fn sum_non_numeric_member_does_not_error_via_sum_values_itself() {
        // `sum_values` receives only the VALUES passed; it doesn't evaluate expressions.
        // A non-numeric Value::Term (e.g. an IRI) causes `as_numeric` to return None,
        // making sum return None (the short-circuit path when a member has no numeric value).
        use oxrdf::NamedNode;
        let iri = Value::Term(Term::NamedNode(NamedNode::new_unchecked("http://ex/x")));
        let result = sum_values(&[Value::Num(Num::Int(5)), iri], false);
        // as_numeric(IRI) = None → sum_values returns None.
        assert!(result.is_none(), "non-numeric member (IRI) must make sum_values return None");
    }
}

/// Direct unit tests for `minmax_values` — numeric promotion path and empty-set path.
#[cfg(test)]
mod minmax_values_unit {
    use super::*;

    #[test]
    fn minmax_empty_is_unbound() {
        // Value does not impl PartialEq; use matches! for the pattern check.
        assert!(
            matches!(minmax_values(vec![], std::cmp::Ordering::Less), Value::Unbound),
            "MIN(empty set) must be Unbound"
        );
        assert!(
            matches!(minmax_values(vec![], std::cmp::Ordering::Greater), Value::Unbound),
            "MAX(empty set) must be Unbound"
        );
    }

    #[test]
    fn min_over_integers_is_smallest() {
        let vals = vec![Value::Num(Num::Int(5)), Value::Num(Num::Int(2)), Value::Num(Num::Int(8))];
        let min = minmax_values(vals, std::cmp::Ordering::Less);
        // MIN over an all-integer set is the smallest member (2). `minmax_values` returns
        // it via `num_canonical_term`, i.e. a `Value::Term` carrying the canonical
        // xsd:integer literal "2". Assert the EXACT lexical value AND datatype — NOT a
        // substring `contains('2')`, which is vacuous because the xsd:integer datatype
        // IRI (…/2001/XMLSchema#integer) already contains '2' regardless of the value.
        match min {
            Value::Num(Num::Int(n)) => assert_eq!(n, 2, "MIN of [5,2,8] must be exactly 2, got {}", n),
            Value::Term(Term::Literal(ref l)) => {
                assert_eq!(l.value(), "2", "MIN of [5,2,8] must have lexical value \"2\", got {}", l);
                assert_eq!(
                    l.datatype(),
                    xsd::INTEGER,
                    "MIN of integers must keep xsd:integer, got {}",
                    l.datatype()
                );
            }
            other => panic!("MIN of integers must be the integer 2 (numeric or integer term), got {other:?}"),
        }
    }

    #[test]
    fn max_over_integers_is_largest() {
        let vals = vec![Value::Num(Num::Int(5)), Value::Num(Num::Int(2)), Value::Num(Num::Int(8))];
        let max = minmax_values(vals, std::cmp::Ordering::Greater);
        // MAX over an all-integer set is the largest member (8), returned as a canonical
        // xsd:integer `Value::Term`. Assert the EXACT lexical value AND datatype — a
        // substring `contains('8')` would also pass for wrong values like 18 or 80, so it
        // is not an acceptable check for the `Value::Term` representation.
        match max {
            Value::Num(Num::Int(n)) => assert_eq!(n, 8, "MAX of [5,2,8] must be exactly 8, got {}", n),
            Value::Term(Term::Literal(ref l)) => {
                assert_eq!(l.value(), "8", "MAX of [5,2,8] must have lexical value \"8\", got {}", l);
                assert_eq!(
                    l.datatype(),
                    xsd::INTEGER,
                    "MAX of integers must keep xsd:integer, got {}",
                    l.datatype()
                );
            }
            other => panic!("MAX of integers must be the integer 8 (numeric or integer term), got {other:?}"),
        }
    }

    #[test]
    fn min_over_mixed_types_falls_back_to_compare_values() {
        // A mix of IRI and literal forces the "not all numeric" path → compare_values fallback.
        use oxrdf::NamedNode;
        let iri = Value::Term(Term::NamedNode(NamedNode::new_unchecked("http://ex/x")));
        let lit = Value::Term(Term::Literal(Literal::new_simple_literal("abc")));
        let vals = vec![iri, lit];
        // Should not panic; result is the "smaller" by compare_values total order.
        let min = minmax_values(vals, std::cmp::Ordering::Less);
        // IRI < plain literal in SPARQL total order, so MIN should be the IRI.
        match &min {
            Value::Term(Term::NamedNode(_)) => {} // expected: IRI
            other => panic!("MIN of (IRI, string) should be the IRI, got {other:?}"),
        }
    }
}

// [SONNET-4.6] (sq-pntvh.4, M4 Phase 4) Seam-level differential for the columnar
// GROUP-BY aggregate path. Verifies that `columnar_aggregate` produces output
// BYTE-IDENTICAL to the scalar group fold (`group_aggregate`) over a REAL graph, and
// DECLINES on every column shape not provably identical. Only built under `vectorized`.
#[cfg(all(test, feature = "vectorized"))]
mod columnar_aggregate_seam {
    use super::*;

    const XSD_INT: &str = "http://www.w3.org/2001/XMLSchema#integer";

    /// Build `n` triples `ex:s{i} ex:score {i}` (integer literal → inline id).
    /// Returns (graph, subject ids [dict IRIs], score ids [inline integers]).
    fn scores_graph(n: u32) -> (Graph, Vec<Id>, Vec<Id>) {
        let mut nt = String::new();
        for i in 0..n {
            nt.push_str(&format!("<http://ex/s{i}> <http://ex/score> \"{i}\"^^<{XSD_INT}> .\n"));
        }
        let g = Graph::load_str(&nt, "ntriples").unwrap();
        let subj: Vec<Id> = (0..n)
            .map(|i| g.id_of(&Term::NamedNode(oxrdf::NamedNode::new(format!("http://ex/s{i}")).unwrap())).unwrap())
            .collect();
        let score: Vec<Id> = (0..n)
            .map(|i| g.id_of(&Term::Literal(Literal::new_typed_literal(i.to_string(), xsd::INTEGER))).unwrap())
            .collect();
        (g, subj, score)
    }

    fn var(name: &str) -> Variable {
        Variable::new(name).unwrap()
    }

    /// TRUE scalar oracle: calls `eval_aggregate` directly, bypassing the columnar seam.
    /// Returns `(rows, local_vocab)` — caller uses `local_vocab` for [`term_of`] decoding.
    ///
    /// Under `feature="vectorized"`, calling `group_aggregate` for the "reference" side is
    /// vacuous — it takes the columnar path too, making a columnar-vs-columnar comparison that
    /// cannot catch a columnar mutation. This helper replicates the sequential scalar fallback
    /// of `group_aggregate` WITHOUT the columnar seam. [SONNET-4.6]
    /// (C2-fix sq-pntvh.4 adversarial review)
    fn scalar_oracle(
        g: &Graph,
        b: &Bindings,
        group_vars: &[Variable],
        aggregates: &[(Variable, AggregateExpression)],
    ) -> (Vec<Row>, LocalVocab) {
        let key_cols: Vec<Option<usize>> = group_vars.iter().map(|v| b.col(v)).collect();
        let (mut order, mut members) = build_groups(b, &key_cols);
        if group_vars.is_empty() && order.is_empty() {
            order.push(Key::new());
            members.push(Vec::new());
        }
        let mut local = LocalVocab::default();
        let mut rows = Vec::with_capacity(order.len());
        for (key, mems) in order.iter().zip(&members) {
            let mut row = Row::from_slice(key);
            for (_, agg) in aggregates {
                let v = eval_aggregate(g, &local, b, mems, agg)
                    .expect("scalar oracle eval_aggregate must succeed");
                let id = value_to_id(g, &mut local, &v);
                row.push(id);
            }
            rows.push(row);
        }
        (rows, local)
    }

    /// Decode rows to `Option<Term>` slices for full-term comparison
    /// (lexical + datatype, not raw ids or f64 values). [SONNET-4.6]
    fn rows_to_terms(g: &Graph, local: &LocalVocab, rows: &[Row]) -> Vec<Vec<Option<oxrdf::Term>>> {
        rows.iter()
            .map(|row| row.iter().map(|&id| term_of(g, local, id)).collect())
            .collect()
    }

    /// Run the columnar path (via `group_aggregate`) and the TRUE scalar oracle, then
    /// assert their outputs are FULL-TERM-identical (lexical + datatype).
    ///
    /// `group_aggregate` — under `feature="vectorized"` — tries the columnar seam first.
    /// The scalar oracle calls `eval_aggregate` directly, so the comparison is
    /// columnar-vs-scalar, not columnar-vs-columnar. A datatype mutation in the columnar
    /// path (e.g., SUM returning `Num::Double` instead of `Num::Int`) produces a different
    /// term (different xsd: datatype) and fails. [SONNET-4.6]
    /// (C2-fix sq-pntvh.4 adversarial review)
    fn check_agg_byte_identical(
        g: &Graph,
        b: Bindings,
        group_vars: &[Variable],
        aggregates: Vec<(Variable, AggregateExpression)>,
    ) {
        // TRUE scalar reference: calls eval_aggregate directly.
        let (scalar_rows, scalar_local) = scalar_oracle(g, &b, group_vars, &aggregates);

        // Columnar path: group_aggregate (tries columnar under vectorized, falls back otherwise).
        let b_col = Bindings::unsorted(b.vars.clone(), b.rows.clone());
        let mut local_col = LocalVocab::default();
        let col_out = group_aggregate(g, &mut local_col, b_col, group_vars, &aggregates)
            .expect("columnar group_aggregate must succeed");

        // Compare as full Terms (lexical + datatype), not raw ids.
        // Raw ids across different LocalVocab instances diverge for non-inline terms.
        let scalar_terms = rows_to_terms(g, &scalar_local, &scalar_rows);
        let col_terms = rows_to_terms(g, &local_col, &col_out.rows);
        assert_eq!(
            scalar_terms, col_terms,
            "columnar and scalar group_aggregate must produce FULL-TERM-identical output \
             (lexical + datatype)"
        );
    }

    /// T5 (byte-identity + non-vacuity): whole-dataset SUM/COUNT/MIN/MAX over an
    /// all-inline-integer column: (a) `columnar_aggregate` returns `Some` (path engaged),
    /// (b) the aggregate result decodes to the scalar-expected value, and (c) the columnar
    /// result is FULL-TERM-identical to the TRUE scalar oracle (catches datatype mutations).
    ///
    /// Scores 0..=299: SUM=44850 (xsd:integer), COUNT=300 (xsd:integer), MIN=0, MAX=299.
    /// n=300 ensures the batch exceeds VEC_MIN_BATCH (256) so columnar_aggregate engages.
    /// A mutation returning `Num::Double` instead of `Num::Int` for SUM changes the xsd:
    /// datatype and fails (c); a MIN→MAX mutation changes the numeric value and fails (b).
    /// [SONNET-4.6] (C2-fix sq-pntvh.4 adversarial review)
    #[test]
    fn t5_whole_dataset_agg_byte_identical_to_scalar() {
        let n = 300u32;
        let (g, _subj, score) = scores_graph(n);
        let score_var = var("score");
        let rows: Vec<Row> = score.iter().map(|&s| Row::from_slice(&[s])).collect();
        let b = Bindings::unsorted(vec![score_var.clone()], rows);

        // The key-cols list is empty (whole-dataset = no GROUP BY).
        let key_cols: Vec<Option<usize>> = vec![];
        let (order, members) = build_groups(&b, &key_cols);

        let mk_agg = |name: AggregateFunction| -> Vec<(Variable, AggregateExpression)> {
            vec![(
                var("agg"),
                AggregateExpression::FunctionCall {
                    name,
                    expr: Expression::Variable(score_var.clone()),
                    distinct: false,
                },
            )]
        };

        // (expected_value, AggregateFunction label, aggregates)
        let cases: &[(f64, AggregateFunction)] = &[
            (44850.0, AggregateFunction::Sum),   // 0+1+…+299 = 299*300/2 = 44850
            (300.0,   AggregateFunction::Count),  // 300 rows
            (0.0,     AggregateFunction::Min),    // minimum of 0..=299
            (299.0,   AggregateFunction::Max),    // maximum
        ];

        for &(expected, ref name) in cases {
            let aggregates = mk_agg(name.clone());
            let b2 = Bindings::unsorted(b.vars.clone(), b.rows.clone());

            // (a) Call columnar_aggregate DIRECTLY — assert it returns Some (path engaged).
            let mut local_col = LocalVocab::default();
            let col_rows = columnar_aggregate(
                &g, &mut local_col, &b2, &[], &aggregates, &order, &members, &[var("agg")],
            );
            assert!(
                col_rows.is_some(),
                "columnar_aggregate must engage (return Some) for eligible aggregate {:?}",
                name
            );
            let col_rows = col_rows.unwrap();
            assert_eq!(col_rows.len(), 1, "whole-dataset agg must produce exactly 1 row for {:?}", name);

            // (b) Decode the result id and compare with the scalar expected value (value check).
            let result_id = col_rows[0][0];
            let got = g.numeric_value(result_id).unwrap_or_else(|| {
                // For sums beyond INLINE_MAX the result is in local vocab.
                match term_of(&g, &local_col, result_id) {
                    Some(Term::Literal(l)) => l.value().parse::<f64>().unwrap_or(f64::NAN),
                    _ => f64::NAN,
                }
            });
            assert_eq!(
                got, expected,
                "aggregate {:?} over scores 0..=299 must equal {}", name, expected
            );

            // (c) FULL-TERM identity against the TRUE scalar oracle (catches datatype mutations).
            // scalar_oracle calls eval_aggregate directly — it never touches the columnar seam,
            // so a SUM Int→Double mutation in columnar is caught here by the xsd: datatype
            // difference. [SONNET-4.6]
            let (scalar_rows, scalar_local) = scalar_oracle(&g, &b2, &[], &aggregates);
            let col_terms = rows_to_terms(&g, &local_col, &col_rows);
            let scalar_terms = rows_to_terms(&g, &scalar_local, &scalar_rows);
            assert_eq!(
                col_terms, scalar_terms,
                "columnar {:?} must be FULL-TERM-identical to scalar oracle (lexical + datatype)",
                name
            );
        }
    }

    /// T5b: COUNT(*) byte-identical.
    #[test]
    fn t5b_count_star_byte_identical() {
        let n = 10u32;
        let (g, _subj, score) = scores_graph(n);
        let score_var = var("score");
        let rows: Vec<Row> = score.iter().map(|&s| Row::from_slice(&[s])).collect();
        let b = Bindings::unsorted(vec![score_var], rows);
        let count_star = vec![(
            var("cnt"),
            AggregateExpression::CountSolutions { distinct: false },
        )];
        check_agg_byte_identical(&g, b, &[], count_star);
    }

    /// T6 (mutation check): SUM output pins the EXACT aggregate value so an implementation
    /// that returns MIN or MAX instead of SUM would fail this test. The aggregate value of
    /// scores 0..19 is: SUM = 190, MIN = 0, MAX = 19 — all distinct.
    #[test]
    fn t6_mutation_check_sum_pins_exact_value() {
        let n = 20u32;
        let (g, _subj, score) = scores_graph(n);
        let score_var = var("score");
        let rows: Vec<Row> = score.iter().map(|&s| Row::from_slice(&[s])).collect();
        let b = Bindings::unsorted(vec![score_var.clone()], rows);

        let aggregates = vec![(
            var("total"),
            AggregateExpression::FunctionCall {
                name: AggregateFunction::Sum,
                expr: Expression::Variable(score_var),
                distinct: false,
            },
        )];

        let mut local = LocalVocab::default();
        let out = group_aggregate(&g, &mut local, b, &[], &aggregates).unwrap();
        assert_eq!(out.rows.len(), 1, "whole-dataset aggregate must produce exactly 1 row");

        // The aggregate result id must decode to the integer 190 (SUM 0..=19).
        let result_id = out.rows[0][0];
        let num_val = g.numeric_value(result_id)
            .unwrap_or_else(|| {
                // Might be a local-vocab term (for sums > INLINE_MAX) — materialise it.
                let term = term_of(&g, &local, result_id).unwrap();
                match &term {
                    Term::Literal(l) => l.value().parse::<f64>().unwrap_or(f64::NAN),
                    _ => f64::NAN,
                }
            });
        assert_eq!(num_val, 190.0_f64, "SUM(0..=19) must equal 190, not MIN=0 or MAX=19");
    }

    /// T5c: AVG over inline-integer column — columnar path engaged, result FULL-TERM-identical
    /// to the TRUE scalar oracle. AVG(0..=299) = 44850/300 = 149.5 (xsd:decimal).
    /// n=300 ensures the batch exceeds VEC_MIN_BATCH (256) so columnar_aggregate engages. [SONNET-4.6]
    /// (C2-fix sq-pntvh.4 adversarial review)
    #[test]
    fn t5c_avg_byte_identical_to_scalar() {
        let n = 300u32;
        let (g, _subj, score) = scores_graph(n);
        let score_var = var("score");
        let rows: Vec<Row> = score.iter().map(|&s| Row::from_slice(&[s])).collect();
        let b = Bindings::unsorted(vec![score_var.clone()], rows);
        let key_cols: Vec<Option<usize>> = vec![];
        let (order, members) = build_groups(&b, &key_cols);

        let aggregates = vec![(
            var("avg"),
            AggregateExpression::FunctionCall {
                name: AggregateFunction::Avg,
                expr: Expression::Variable(score_var),
                distinct: false,
            },
        )];

        let mut local_col = LocalVocab::default();
        let col_rows = columnar_aggregate(
            &g, &mut local_col, &b, &[], &aggregates, &order, &members, &[var("avg")],
        ).expect("AVG over inline-integer column must engage (return Some)");

        // TRUE scalar oracle: calls eval_aggregate directly, bypassing the columnar seam.
        // Previously this called group_aggregate which under vectorized also went through
        // the columnar path — producing a vacuous columnar-vs-columnar comparison. [SONNET-4.6]
        let (scalar_rows, scalar_local) = scalar_oracle(&g, &b, &[], &aggregates);

        // (a) FULL-TERM-identical: compare lexical + datatype, not raw ids.
        let col_terms = rows_to_terms(&g, &local_col, &col_rows);
        let scalar_terms = rows_to_terms(&g, &scalar_local, &scalar_rows);
        assert_eq!(
            col_terms, scalar_terms,
            "columnar AVG must be FULL-TERM-identical to the scalar oracle (lexical + datatype)"
        );

        // (b) Non-vacuous: verify the result is 149.5 (44850/300), not 0 or some wrong value.
        //     AVG(0..=299) = 149.5 (xsd:decimal, stored as a local-vocab Dec term).
        let result_id = col_rows[0][0];
        let term = term_of(&g, &local_col, result_id).expect("AVG result must be a term");
        let avg_str = match &term {
            Term::Literal(l) => l.value().to_string(),
            _ => panic!("AVG result must be a literal, got {:?}", term),
        };
        // The decimal 149.5 serialises as "149.5" (or equivalent exact decimal lexical).
        let avg_f64: f64 = avg_str.parse().expect("AVG lexical must be numeric");
        assert!(
            (avg_f64 - 149.5_f64).abs() < 1e-9,
            "AVG(0..=299) = 44850/300 = 149.5, got {} (term = {:?})", avg_f64, term
        );
    }

    /// T5d (GROUP BY, first-seen order): two-group GROUP BY with first-seen order
    /// deliberately different from sorted order. Columnar path must preserve first-seen order
    /// and produce FULL-TERM-identical GROUP BY results to the TRUE scalar oracle. [SONNET-4.6]
    /// (C2-fix sq-pntvh.4 adversarial review)
    #[test]
    fn t5d_group_by_first_seen_order_preserved() {
        // Two groups: group "2" appears FIRST, group "1" appears SECOND.
        // score column: group "2"→[10,20], group "1"→[5,15].
        let nt = format!(
            "<http://ex/r1> <http://ex/g> \"b\"^^<{XSD_INT}> .\n\
             <http://ex/r1> <http://ex/score> \"10\"^^<{XSD_INT}> .\n\
             <http://ex/r2> <http://ex/g> \"2\"^^<{XSD_INT}> .\n\
             <http://ex/r2> <http://ex/score> \"20\"^^<{XSD_INT}> .\n\
             <http://ex/r3> <http://ex/g> \"1\"^^<{XSD_INT}> .\n\
             <http://ex/r3> <http://ex/score> \"5\"^^<{XSD_INT}> .\n\
             <http://ex/r4> <http://ex/g> \"1\"^^<{XSD_INT}> .\n\
             <http://ex/r4> <http://ex/score> \"15\"^^<{XSD_INT}> .\n"
        );
        let g = Graph::load_str(&nt, "ntriples").unwrap();
        let lit = |v: &str| {
            g.id_of(&Term::Literal(Literal::new_typed_literal(v, xsd::INTEGER))).unwrap()
        };
        // Bindings: two columns [g_val, score], rows in order [group2→10, group2→20, group1→5, group1→15].
        let group_var = var("g");
        let score_var = var("score");
        let rows: Vec<Row> = vec![
            Row::from_slice(&[lit("2"), lit("10")]),  // group "2" first
            Row::from_slice(&[lit("2"), lit("20")]),
            Row::from_slice(&[lit("1"), lit("5")]),   // group "1" second
            Row::from_slice(&[lit("1"), lit("15")]),
        ];
        let b = Bindings::unsorted(vec![group_var.clone(), score_var.clone()], rows);

        let aggregates = vec![(
            var("s"),
            AggregateExpression::FunctionCall {
                name: AggregateFunction::Sum,
                expr: Expression::Variable(score_var),
                distinct: false,
            },
        )];
        let group_vars = vec![group_var];

        // TRUE scalar reference: calls eval_aggregate directly, never the columnar seam.
        // Previously called group_aggregate for both sides — under vectorized both took the
        // columnar path, making the comparison vacuous. [SONNET-4.6]
        let (scalar_rows, scalar_local) = scalar_oracle(&g, &b, &group_vars, &aggregates);

        // Columnar path (via group_aggregate under vectorized).
        let b_col = Bindings::unsorted(b.vars.clone(), b.rows.clone());
        let mut local_c = LocalVocab::default();
        let col_out = group_aggregate(&g, &mut local_c, b_col, &group_vars, &aggregates).unwrap();

        // FULL-TERM-identical comparison: lexical + datatype, not raw ids or f64.
        let scalar_terms = rows_to_terms(&g, &scalar_local, &scalar_rows);
        let col_terms = rows_to_terms(&g, &local_c, &col_out.rows);
        assert_eq!(
            col_terms, scalar_terms,
            "GROUP BY columnar must preserve first-seen order and be FULL-TERM-identical to scalar oracle"
        );
        assert_eq!(col_out.rows.len(), 2, "must have 2 groups");
        // Pin: first row = group "2" (SUM=30), second = group "1" (SUM=20).
        let sum_val = |rows: &[Row], idx: usize| {
            let id = rows[idx][1]; // [g_key, sum_val]
            g.numeric_value(id).unwrap_or_else(|| {
                let t = term_of(&g, &local_c, id).unwrap();
                match &t { Term::Literal(l) => l.value().parse().unwrap(), _ => f64::NAN }
            })
        };
        assert_eq!(sum_val(&col_out.rows, 0), 30.0, "first group (key=2) SUM must be 30");
        assert_eq!(sum_val(&col_out.rows, 1), 20.0, "second group (key=1) SUM must be 20");
    }

    /// T7 (decline gate): a non-inline column (negative integer) must make the seam DECLINE
    /// and the scalar path run; both produce the same result.
    #[test]
    fn t7_non_inline_column_declines() {
        // A negative integer is not inline (inline range is [0, INLINE_MAX]).
        let nt = format!(
            "<http://ex/a> <http://ex/score> \"-1\"^^<{XSD_INT}> .\n\
             <http://ex/b> <http://ex/score> \"2\"^^<{XSD_INT}> .\n"
        );
        let g = Graph::load_str(&nt, "ntriples").unwrap();
        let neg_one = g.id_of(&Term::Literal(Literal::new_typed_literal("-1", xsd::INTEGER))).unwrap();
        let two = g.id_of(&Term::Literal(Literal::new_typed_literal("2", xsd::INTEGER))).unwrap();
        assert!(!dict::is_inline(neg_one), "-1 must be a non-inline dict id");
        assert!(dict::is_inline(two), "2 must be inline");

        let score_var = var("score");
        let rows = vec![Row::from_slice(&[neg_one]), Row::from_slice(&[two])];
        let b = Bindings::unsorted(vec![score_var.clone()], rows);
        let aggregates = vec![(
            var("s"),
            AggregateExpression::FunctionCall {
                name: AggregateFunction::Sum,
                expr: Expression::Variable(score_var),
                distinct: false,
            },
        )];
        // Verify columnar_aggregate declines for the mixed (non-inline) column.
        let key_cols: Vec<Option<usize>> = vec![];
        let (order, members) = build_groups(&b, &key_cols);
        let mut local = LocalVocab::default();
        let out_vars = vec![var("s")];
        let result = columnar_aggregate(
            &g, &mut local, &b, &[], &aggregates, &order, &members, &out_vars
        );
        assert!(result.is_none(), "non-inline column must make columnar_aggregate decline");
    }

    /// T8 (DISTINCT decline): DISTINCT aggregate must always decline.
    #[test]
    fn t8_distinct_aggregate_declines() {
        let n = 5u32;
        let (g, _subj, score) = scores_graph(n);
        let score_var = var("score");
        let rows: Vec<Row> = score.iter().map(|&s| Row::from_slice(&[s])).collect();
        let b = Bindings::unsorted(vec![score_var.clone()], rows);
        let aggregates = vec![(
            var("c"),
            AggregateExpression::FunctionCall {
                name: AggregateFunction::Count,
                expr: Expression::Variable(score_var),
                distinct: true, // DISTINCT → must decline
            },
        )];
        let key_cols: Vec<Option<usize>> = vec![];
        let (order, members) = build_groups(&b, &key_cols);
        let mut local = LocalVocab::default();
        let out_vars = vec![var("c")];
        let result = columnar_aggregate(
            &g, &mut local, &b, &[], &aggregates, &order, &members, &out_vars
        );
        assert!(result.is_none(), "DISTINCT aggregate must make columnar_aggregate decline");
    }
}

// ── Expression-compilation invariant tests (sq-7d3dj.4) ─────────────────────────────────
//
// These tests pin the LOAD-BEARING INVARIANT: eval_compiled produces bit-identical results
// to eval_expr for all expression types and binding shapes, including the FILTER, BIND, and
// ORDER BY operators. A divergence here would be a semantic change.  [OPUS-4.8] sq-7d3dj.4

#[cfg(test)]
mod compiled_expr_tests {
    use super::*;
    use oxrdf::vocab::xsd;
    use spargebra::algebra::{Expression, Function, OrderExpression};

    fn int_expr(s: &str) -> Expression {
        Expression::Literal(oxrdf::Literal::new_typed_literal(s, xsd::INTEGER))
    }

    fn str_expr(s: &str) -> Expression {
        Expression::Literal(oxrdf::Literal::new_simple_literal(s))
    }

    fn var_expr(v: &str) -> Expression {
        Expression::Variable(oxrdf::Variable::new_unchecked(v))
    }

    /// `eval_expr` == `eval_compiled` for every row of `b` with expression `e`.
    fn assert_compiled_matches_original(graph: &Graph, local: &LocalVocab, b: &Bindings, e: &Expression) {
        let compiled = compile_expr(e, b);
        for row in &b.rows {
            let expected = eval_expr(graph, local, b, row, e).expect("eval_expr error");
            let got = eval_compiled(graph, local, b, row, &compiled).expect("eval_compiled error");
            // Compare via string representation (Value is not PartialEq, but Terms are).
            let exp_str = format!("{expected:?}");
            let got_str = format!("{got:?}");
            assert_eq!(
                exp_str, got_str,
                "eval_compiled diverged from eval_expr for expr {e:?} on row {row:?}"
            );
        }
    }

    fn one_row_graph() -> Graph {
        Graph::load_str(
            "<http://ex/s> <http://ex/p> <http://ex/o> .\n\
             <http://ex/a> <http://ex/n> \"42\"^^<http://www.w3.org/2001/XMLSchema#integer> .",
            "ntriples",
        )
        .unwrap()
    }

    /// FILTER parity: apply_filter_scalar (which uses eval_compiled internally) produces
    /// the same surviving rows as a reference path that applies eval_expr + effective_boolean
    /// directly per row.  [OPUS-4.8] sq-7d3dj.4
    #[test]
    fn compiled_filter_is_byte_identical_to_eval_expr() {
        let g = one_row_graph();
        // Build a small set of rows with inline integer ids so we can filter numerically.
        let n = 30u32;
        let rows: Vec<Row> = (0..n)
            .map(|i| Row::from_slice(&[sparq_core::dict::inline_id_of_int(i as i64).unwrap()]))
            .collect();
        let v = oxrdf::Variable::new_unchecked("x");
        let filters: Vec<Expression> = vec![
            Expression::Greater(Box::new(var_expr("x")), Box::new(int_expr("15"))),
            Expression::Less(Box::new(var_expr("x")), Box::new(int_expr("10"))),
            Expression::Equal(Box::new(var_expr("x")), Box::new(int_expr("7"))),
            Expression::GreaterOrEqual(Box::new(var_expr("x")), Box::new(int_expr("20"))),
        ];
        let local = LocalVocab::default();
        for expr in &filters {
            // Reference path: apply eval_expr + effective_boolean directly to each row.
            let b_ref = Bindings::unsorted(vec![v.clone()], rows.clone());
            let reference_rows: Vec<Row> = b_ref
                .rows
                .iter()
                .filter(|row| {
                    eval_expr(&g, &local, &b_ref, row, expr)
                        .map(|val| effective_boolean(&val))
                        .unwrap_or(false)
                })
                .cloned()
                .collect();

            // Compiled path: apply_filter_scalar uses eval_compiled internally.
            let mut b_compiled = Bindings::unsorted(vec![v.clone()], rows.clone());
            apply_filter_scalar(&g, &local, &mut b_compiled, expr).unwrap();

            assert_eq!(
                reference_rows, b_compiled.rows,
                "compiled apply_filter_scalar diverged from eval_expr reference for {expr:?}"
            );
            // Sanity-check: the reference must be non-trivial for each filter expression.
            assert!(
                !reference_rows.is_empty(),
                "filter {expr:?} kept no rows — test is vacuous"
            );
            assert!(
                reference_rows.len() < rows.len(),
                "filter {expr:?} kept all rows — test is vacuous"
            );
        }
    }

    /// BIND parity: extend_bindings (which uses eval_compiled internally) produces values
    /// that are term-identical to what eval_expr yields for the same BIND expression on
    /// the same input rows.  [OPUS-4.8] sq-7d3dj.4
    #[test]
    fn compiled_bind_is_byte_identical() {
        let g = one_row_graph();
        let local = LocalVocab::default();

        // Input Bindings: ?v bound to the inline integer ids for 10 and 20.
        let v_var = oxrdf::Variable::new_unchecked("v");
        let v10 = sparq_core::dict::inline_id_of_int(10).unwrap();
        let v20 = sparq_core::dict::inline_id_of_int(20).unwrap();

        // The BIND expression: ?v * 2.
        let bind_expr = Expression::Multiply(Box::new(var_expr("v")), Box::new(int_expr("2")));

        // Reference path: eval_expr on each input row, converted to a Term for comparison.
        let b_ref = Bindings::unsorted(
            vec![v_var.clone()],
            vec![Row::from_slice(&[v10]), Row::from_slice(&[v20])],
        );
        let reference: Vec<Option<Term>> = b_ref
            .rows
            .iter()
            .map(|row| value_as_term(&eval_expr(&g, &local, &b_ref, row, &bind_expr).unwrap()))
            .collect();

        // Compiled path: extend_bindings uses eval_compiled internally.
        let doubled_var = oxrdf::Variable::new_unchecked("doubled");
        let mut local2 = LocalVocab::default();
        let b_out = extend_bindings(
            &g,
            &mut local2,
            Bindings::unsorted(
                vec![v_var.clone()],
                vec![Row::from_slice(&[v10]), Row::from_slice(&[v20])],
            ),
            &doubled_var,
            &bind_expr,
        )
        .unwrap();
        let doubled_col = b_out.col(&doubled_var).unwrap();
        let compiled: Vec<Option<Term>> = b_out
            .rows
            .iter()
            .map(|row| term_of(&g, &local2, row[doubled_col]))
            .collect();

        assert_eq!(
            reference, compiled,
            "extend_bindings result diverged from eval_expr reference for BIND ?v * 2"
        );
        assert_eq!(reference.len(), 2, "expected exactly 2 output rows");
    }

    /// ORDER BY parity: order_bindings (which uses eval_compiled internally) produces the
    /// same row ordering as a reference sort that uses eval_expr to compute sort keys.
    /// [OPUS-4.8] sq-7d3dj.4
    #[test]
    fn compiled_order_is_byte_identical() {
        let g = one_row_graph();
        let local = LocalVocab::default();

        // Pre-sort Bindings: ?n bound to inline integer ids in arbitrary order.
        let n_var = oxrdf::Variable::new_unchecked("n");
        let n5 = sparq_core::dict::inline_id_of_int(5).unwrap();
        let n2 = sparq_core::dict::inline_id_of_int(2).unwrap();
        let n8 = sparq_core::dict::inline_id_of_int(8).unwrap();
        let n1 = sparq_core::dict::inline_id_of_int(1).unwrap();
        let pre_sort_rows = vec![
            Row::from_slice(&[n5]),
            Row::from_slice(&[n2]),
            Row::from_slice(&[n8]),
            Row::from_slice(&[n1]),
        ];
        let pre_sort = Bindings::unsorted(vec![n_var.clone()], pre_sort_rows.clone());

        // Reference path: sort rows using eval_expr to compute the ?n sort key.
        let n_expr = Expression::Variable(n_var.clone());
        let mut reference_rows = pre_sort_rows.clone();
        reference_rows.sort_by(|a_row, b_row| {
            let va = eval_expr(&g, &local, &pre_sort, a_row, &n_expr).unwrap();
            let vb = eval_expr(&g, &local, &pre_sort, b_row, &n_expr).unwrap();
            compare_values(&va, &vb).unwrap_or(Ordering::Equal)
        });

        // Compiled path: order_bindings uses eval_compiled internally.
        let mut b = Bindings::unsorted(vec![n_var.clone()], pre_sort_rows.clone());
        order_bindings(&g, &local, &mut b, &[OrderExpression::Asc(n_expr.clone())], None).unwrap();

        assert_eq!(
            reference_rows, b.rows,
            "order_bindings result diverged from eval_expr reference for ORDER BY ASC(?n)"
        );
        // Sanity-check: the sort is non-trivial (input was not already sorted).
        assert_ne!(
            pre_sort_rows, b.rows,
            "pre-sort input happened to be sorted — test is vacuous"
        );
    }

    /// [SONNET-4.6] sq-7d3dj.30.23 — INDEX-CARRY top-k byte-identity: the bounded
    /// top-k path (`order_bindings(…, Some(k))`) now carries only the row INDEX in the
    /// `keyed` vector (not a cloned `Row`) and gathers the k surviving rows from `b.rows`
    /// by index. This test pins that the gathered result is BYTE-IDENTICAL to the full
    /// stable sort (`order_bindings(…, None)`) truncated to `[..k]`, for a set with
    /// deliberate ORDER BY tie groups (duplicate keys) and `k < n`. It also pins the
    /// exact surviving key sequence so a wrong gather (wrong index, wrong prefix, dropped
    /// tie-break) turns the test RED.
    ///
    /// MUTATION-VERIFICATION (non-vacuous): the `expected_keys` assertion pins the exact
    /// ascending survivor sequence `[1,1,2,3,4]`. If the gather used the wrong index
    /// (e.g. `b.rows[*i]` → `b.rows[0]`) or the prefix bound `[..k]` were off, or if the
    /// stable-tie order were reversed, the surviving sequence changes and this assertion
    /// fails. Reversing the pinned first element (say to `2`) also makes it fail — verified
    /// by flipping the expected head and observing RED.
    #[test]
    fn index_carry_topk_is_byte_identical_to_full_sort_truncated() {
        let g = one_row_graph();
        let local = LocalVocab::default();
        let n_var = oxrdf::Variable::new_unchecked("n");
        let n_expr = Expression::Variable(n_var.clone());

        // Inline-int keys with DELIBERATE tie groups: two 1s, two 4s, plus 3,2,3,4.
        // 8 rows in scrambled input order → the full sort is non-trivial and ties exercise
        // the index tie-breaker. The distinct SECOND column value tags each row so a wrong
        // gather (right key, wrong row) is observable, not masked by identical rows.
        let key = |v: i64| sparq_core::dict::inline_id_of_int(v).unwrap();
        let tag = |v: i64| sparq_core::dict::inline_id_of_int(1000 + v).unwrap();
        let tag_var = oxrdf::Variable::new_unchecked("tag");
        let input_rows = vec![
            Row::from_slice(&[key(3), tag(0)]),
            Row::from_slice(&[key(1), tag(1)]),
            Row::from_slice(&[key(4), tag(2)]),
            Row::from_slice(&[key(1), tag(3)]),
            Row::from_slice(&[key(2), tag(4)]),
            Row::from_slice(&[key(4), tag(5)]),
            Row::from_slice(&[key(3), tag(6)]),
            Row::from_slice(&[key(4), tag(7)]),
        ];
        let n = input_rows.len();
        let vars = vec![n_var.clone(), tag_var.clone()];
        let order = [OrderExpression::Asc(n_expr.clone())];

        // For each k in 1..n (all k < n exercise the bounded index-carry path), the
        // top-k output must equal the full sort truncated to [..k], byte-for-byte.
        let mut full = Bindings::unsorted(vars.clone(), input_rows.clone());
        order_bindings(&g, &local, &mut full, &order, None).unwrap();
        // Sanity: the full sort actually reorders (input was scrambled) — not vacuous.
        assert_ne!(full.rows, input_rows, "full sort was a no-op — test is vacuous");

        for k in 1..n {
            let mut topk = Bindings::unsorted(vars.clone(), input_rows.clone());
            order_bindings(&g, &local, &mut topk, &order, Some(k)).unwrap();
            assert_eq!(
                topk.rows,
                full.rows[..k].to_vec(),
                "index-carry top-k (k={}) diverged from full-sort truncated to [..k]",
                k
            );
        }

        // Pin the EXACT surviving ROWS for k=5 so a gather-index bug goes RED. The
        // expected 5 smallest keys (ascending, ties kept) are [1,1,2,3,4]; the two tied
        // `1` rows keep INPUT order (stable tie-break) — row idx 1 (tag 1) before row idx 3
        // (tag 3) — and among the three `3`/`4` boundary the first `3` (tag 0 then tag 6)
        // and first `4` (tag 2) are the picks. The distinct tag column pins the exact rows,
        // not just the keys, so a right-key/wrong-row gather is caught.
        let mut topk5 = Bindings::unsorted(vars.clone(), input_rows.clone());
        order_bindings(&g, &local, &mut topk5, &order, Some(5)).unwrap();
        let expected5 = vec![
            Row::from_slice(&[key(1), tag(1)]), // first tied 1 (input idx 1)
            Row::from_slice(&[key(1), tag(3)]), // second tied 1 (input idx 3)
            Row::from_slice(&[key(2), tag(4)]),
            Row::from_slice(&[key(3), tag(0)]), // first tied 3 (input idx 0)
            Row::from_slice(&[key(3), tag(6)]), // second tied 3 (input idx 6)
        ];
        assert_eq!(
            topk5.rows, expected5,
            "top-5 must gather exactly these rows (keys [1,1,2,3,3], stable tie order)"
        );

        // DESC boundary: k=1 must gather the single MAX-key row. The three `4`s tie; the
        // FIRST in input order (idx 2, tag 2) wins the stable tie-break. Byte-identical to
        // the full DESC sort's head.
        let tag_col = 1usize;
        let desc = [OrderExpression::Desc(n_expr.clone())];
        let mut full_desc = Bindings::unsorted(vars.clone(), input_rows.clone());
        order_bindings(&g, &local, &mut full_desc, &desc, None).unwrap();
        let mut top1_desc = Bindings::unsorted(vars, input_rows);
        order_bindings(&g, &local, &mut top1_desc, &desc, Some(1)).unwrap();
        assert_eq!(top1_desc.rows.len(), 1, "k=1 must yield exactly one row");
        assert_eq!(
            top1_desc.rows,
            full_desc.rows[..1].to_vec(),
            "DESC k=1 must gather the same head row as the full DESC sort"
        );
        assert_eq!(
            top1_desc.rows[0][tag_col],
            tag(2),
            "DESC k=1 head must be the FIRST max-key (4) row in input order (tag 2)"
        );
    }

    /// `compile_expr` round-trips: `eval_compiled` matches `eval_expr` for each variant.
    /// Tests Variable, NamedNode, Literal, And, Or, Not, Equal, Greater, Add, FunctionCall.
    /// [OPUS-4.8] sq-7d3dj.4
    #[test]
    fn compile_expr_matches_eval_expr_for_all_variants() {
        let g = one_row_graph();
        let local = LocalVocab::default();

        // Build a 3-column bindings with a bound IRI, a bound integer, and an unbound slot.
        let iri_id = g.id_of(&oxrdf::Term::NamedNode(oxrdf::NamedNode::new_unchecked("http://ex/s"))).unwrap();
        let num_id = sparq_core::dict::inline_id_of_int(7).unwrap();
        let va = oxrdf::Variable::new_unchecked("a");
        let vb = oxrdf::Variable::new_unchecked("b");
        let vc = oxrdf::Variable::new_unchecked("c"); // unbound
        let rows = vec![
            Row::from_slice(&[iri_id, num_id, NO_ID]),
            Row::from_slice(&[NO_ID, sparq_core::dict::inline_id_of_int(0).unwrap(), NO_ID]),
        ];
        let b = Bindings::unsorted(vec![va.clone(), vb.clone(), vc.clone()], rows);

        let exprs: Vec<Expression> = vec![
            var_expr("a"),
            var_expr("b"),
            var_expr("c"),    // unbound → Value::Unbound
            var_expr("zzz"),  // never in scope → Value::Unbound
            Expression::NamedNode(oxrdf::NamedNode::new_unchecked("http://ex/x")),
            int_expr("42"),
            str_expr("hello"),
            Expression::Bound(vb.clone()),
            Expression::Bound(vc.clone()),
            Expression::Greater(Box::new(var_expr("b")), Box::new(int_expr("3"))),
            Expression::Equal(Box::new(var_expr("b")), Box::new(int_expr("7"))),
            Expression::Not(Box::new(Expression::Equal(Box::new(var_expr("b")), Box::new(int_expr("0"))))),
            Expression::Add(Box::new(var_expr("b")), Box::new(int_expr("1"))),
            Expression::And(
                Box::new(Expression::Bound(vb.clone())),
                Box::new(Expression::Greater(Box::new(var_expr("b")), Box::new(int_expr("0")))),
            ),
            Expression::Or(
                Box::new(Expression::Bound(vc.clone())),
                Box::new(Expression::Greater(Box::new(var_expr("b")), Box::new(int_expr("5")))),
            ),
            Expression::FunctionCall(Function::IsNumeric, vec![var_expr("b")]),
            Expression::FunctionCall(Function::IsIri, vec![var_expr("a")]),
        ];

        for e in &exprs {
            assert_compiled_matches_original(&g, &local, &b, e);
        }
    }
}

#[cfg(test)]
mod sip_unit {
    //! Direct unit tests for the SIP helpers (`certain_vars` / `subst_pattern`),
    //! complementing the end-to-end `tests/sip_join.rs`. [OPUS-4.8] (sq-7d3dj.30.3)
    use super::*;
    use oxrdf::{NamedNode, Variable};

    fn var(s: &str) -> Variable {
        Variable::new(s).unwrap()
    }
    fn nn(s: &str) -> NamedNode {
        NamedNode::new(s).unwrap()
    }
    fn tp(s: &str, p: &str, o: &str) -> TriplePattern {
        TriplePattern {
            subject: TermPattern::Variable(var(s)),
            predicate: NamedNodePattern::NamedNode(nn(p)),
            object: TermPattern::Variable(var(o)),
        }
    }

    #[test]
    fn certain_vars_union_is_branch_intersection() {
        // left binds {x, y}; right binds {x, z}; only x is certain in the UNION.
        let left = GraphPattern::Bgp { patterns: vec![tp("x", "http://e/p", "y")] };
        let right = GraphPattern::Bgp { patterns: vec![tp("x", "http://e/q", "z")] };
        let u = GraphPattern::Union { left: Box::new(left), right: Box::new(right) };
        let mut out = FxHashSet::default();
        certain_vars(&u, &mut out);
        assert!(out.contains(&var("x")), "x certain (bound in both branches)");
        assert!(!out.contains(&var("y")), "y bound in only one branch");
        assert!(!out.contains(&var("z")), "z bound in only one branch");
    }

    #[test]
    fn certain_vars_leftjoin_excludes_optional_side() {
        let left = GraphPattern::Bgp { patterns: vec![tp("x", "http://e/p", "y")] };
        let right = GraphPattern::Bgp { patterns: vec![tp("x", "http://e/q", "opt")] };
        let lj = GraphPattern::LeftJoin {
            left: Box::new(left),
            right: Box::new(right),
            expression: None,
        };
        let mut out = FxHashSet::default();
        certain_vars(&lj, &mut out);
        assert!(out.contains(&var("x")) && out.contains(&var("y")));
        assert!(!out.contains(&var("opt")), "an OPTIONAL-right var is never certain");
    }

    #[test]
    fn subst_pattern_replaces_variable_in_bgp_and_filter() {
        let inner = GraphPattern::Bgp { patterns: vec![tp("doc", "http://e/creator", "prin")] };
        let filt = GraphPattern::Filter {
            expr: Expression::Not(Box::new(Expression::Equal(
                Box::new(Expression::Variable(var("a"))),
                Box::new(Expression::Variable(var("prin"))),
            ))),
            inner: Box::new(inner),
        };
        let mut sub = FxHashMap::default();
        sub.insert(var("prin"), nn("http://e/paul"));
        let out = subst_pattern(&filt, &sub).expect("substitution should succeed");
        // The substituted variable must be fully gone (pattern positions AND filter).
        let dbg = format!("{:?}", out);
        assert!(dbg.contains("paul"), "result must carry the substituted IRI");
        assert!(!dbg.contains("prin"), "substituted variable ?prin must be gone: {}", dbg);
        assert!(dbg.contains("\"a\""), "the untouched ?a must remain");
    }

    #[test]
    fn subst_pattern_bails_on_bound_of_substituted_var() {
        let inner = GraphPattern::Bgp { patterns: vec![tp("x", "http://e/p", "y")] };
        let filt = GraphPattern::Filter { expr: Expression::Bound(var("x")), inner: Box::new(inner) };
        let mut sub = FxHashMap::default();
        sub.insert(var("x"), nn("http://e/c"));
        assert!(
            subst_pattern(&filt, &sub).is_none(),
            "BOUND(?x) on a substituted variable must force the cold fallback"
        );
    }
}

#[cfg(test)]
mod theta_antijoin_unit {
    //! Direct unit tests for the correlated theta anti-join's pure shape helpers,
    //! complementing the end-to-end `tests/theta_antijoin.rs`. [FABLE-5]
    //! (bead sq-7d3dj.30.9)
    use super::*;
    use oxrdf::{NamedNode, Variable};

    fn var(s: &str) -> Variable {
        Variable::new(s).unwrap()
    }
    fn nn(s: &str) -> NamedNode {
        NamedNode::new(s).unwrap()
    }
    fn ev(s: &str) -> Expression {
        Expression::Variable(var(s))
    }

    #[test]
    fn as_not_bound_var_matches_only_not_bound() {
        assert_eq!(
            as_not_bound_var(&Expression::Not(Box::new(Expression::Bound(var("a"))))),
            Some(var("a")),
            "!bound(?a) must extract ?a"
        );
        // Not a `!bound`: bare bound, bare not, equality.
        assert!(as_not_bound_var(&Expression::Bound(var("a"))).is_none());
        assert!(as_not_bound_var(&Expression::Not(Box::new(ev("a")))).is_none());
        assert!(as_not_bound_var(&Expression::Equal(Box::new(ev("a")), Box::new(ev("b")))).is_none());
    }

    #[test]
    fn as_correlation_pair_classifies_eq_sameterm_and_single_var_in() {
        // `?a = ?b` → Eq correlation.
        assert_eq!(
            as_correlation_pair(&Expression::Equal(Box::new(ev("a")), Box::new(ev("b")))),
            Some((var("a"), var("b"), CorrKind::Eq))
        );
        // `sameTerm(?a, ?b)` → SameTerm correlation (sq-3cmr4 extension).
        assert_eq!(
            as_correlation_pair(&Expression::SameTerm(Box::new(ev("a")), Box::new(ev("b")))),
            Some((var("a"), var("b"), CorrKind::SameTerm))
        );
        // `?a IN (?b)` desugars to `?a = ?b` → Eq correlation.
        assert_eq!(
            as_correlation_pair(&Expression::In(Box::new(ev("a")), vec![ev("b")])),
            Some((var("a"), var("b"), CorrKind::Eq))
        );
        // A var = IRI equality is NOT a correlation (one side is a constant).
        assert!(as_correlation_pair(&Expression::Equal(
            Box::new(ev("a")),
            Box::new(Expression::NamedNode(nn("http://e/x")))
        ))
        .is_none());
        // A CONSTANT-list `IN` is NOT a correlation (nothing to seed) — brief's rule.
        assert!(as_correlation_pair(&Expression::In(
            Box::new(ev("a")),
            vec![Expression::NamedNode(nn("http://e/x"))]
        ))
        .is_none());
        // A MULTI-element `IN` (even all-vars) is NOT the single-target seedable shape.
        assert!(
            as_correlation_pair(&Expression::In(Box::new(ev("a")), vec![ev("b"), ev("c")])).is_none()
        );
        // An inequality is not a correlation.
        assert!(as_correlation_pair(&Expression::Less(Box::new(ev("a")), Box::new(ev("b")))).is_none());
    }

    #[test]
    fn corr_recheck_expr_uses_the_correlations_own_relation() {
        // An Eq correlation re-checks with `=`; a SameTerm correlation with `sameTerm`
        // (they DIFFER on value-equal id-distinct literals — the soundness point).
        let out = vec![var("outer"), var("inner")];
        let eq = Correlation { left_col: 0, inner_var: var("inner"), kind: CorrKind::Eq };
        assert!(matches!(corr_recheck_expr(&eq, &out), Expression::Equal(..)));
        let st = Correlation { left_col: 0, inner_var: var("inner"), kind: CorrKind::SameTerm };
        assert!(matches!(corr_recheck_expr(&st, &out), Expression::SameTerm(..)));
    }

    #[test]
    fn corr_id_probeable_is_kind_and_term_aware() {
        use oxrdf::{BlankNode, Literal};
        let iri = Term::NamedNode(nn("http://e/x"));
        let blank = Term::BlankNode(BlankNode::new("b0").unwrap());
        let lit = Term::Literal(Literal::new_simple_literal("hi"));
        // sameTerm: EVERY bound kind is id-probeable (id-equality IS sameTerm).
        assert!(corr_id_probeable(CorrKind::SameTerm, Some(&iri)));
        assert!(corr_id_probeable(CorrKind::SameTerm, Some(&blank)));
        assert!(corr_id_probeable(CorrKind::SameTerm, Some(&lit)));
        assert!(!corr_id_probeable(CorrKind::SameTerm, None), "unbound is not probeable");
        // Eq: only NamedNode/BlankNode; a LITERAL is the value-equality hazard.
        assert!(corr_id_probeable(CorrKind::Eq, Some(&iri)));
        assert!(corr_id_probeable(CorrKind::Eq, Some(&blank)));
        assert!(!corr_id_probeable(CorrKind::Eq, Some(&lit)), "literal Eq must take value scan");
        assert!(!corr_id_probeable(CorrKind::Eq, None));
    }

    #[test]
    fn split_and_flattens_left_to_right() {
        let e = Expression::And(
            Box::new(Expression::And(Box::new(ev("a")), Box::new(ev("b")))),
            Box::new(ev("c")),
        );
        let cs = split_and(&e);
        assert_eq!(cs.len(), 3, "((a && b) && c) → three conjuncts");
        assert_eq!(cs[0], &ev("a"));
        assert_eq!(cs[1], &ev("b"));
        assert_eq!(cs[2], &ev("c"));
        // A non-And yields a single-element list.
        assert_eq!(split_and(&ev("z")).len(), 1);
    }

    #[test]
    fn pattern_has_var_reaches_every_node_kind() {
        let bgp = |s: &str, p: &str, o: &str| GraphPattern::Bgp {
            patterns: vec![TriplePattern {
                subject: TermPattern::Variable(var(s)),
                predicate: NamedNodePattern::NamedNode(nn(p)),
                object: TermPattern::Variable(var(o)),
            }],
        };
        // A var buried in the OPTIONAL condition (not in any triple slot) must be found.
        let lj = GraphPattern::LeftJoin {
            left: Box::new(bgp("a", "http://e/p", "b")),
            right: Box::new(bgp("c", "http://e/q", "d")),
            expression: Some(Expression::Less(Box::new(ev("yr2")), Box::new(ev("yr")))),
        };
        assert!(pattern_has_var(&lj, &var("yr")), "outer var in the OPTIONAL condition");
        assert!(pattern_has_var(&lj, &var("d")), "right-side triple var");
        assert!(pattern_has_var(&lj, &var("a")), "left-side triple var");
        assert!(!pattern_has_var(&lj, &var("absent")), "an unrelated var must not be found");
        // EXISTS sub-pattern var.
        let filt = GraphPattern::Filter {
            expr: Expression::Exists(Box::new(bgp("e", "http://e/r", "f"))),
            inner: Box::new(bgp("a", "http://e/p", "b")),
        };
        assert!(pattern_has_var(&filt, &var("f")), "var inside an EXISTS sub-pattern");
    }
}

// ── id-level term-identity FILTER fast path (sq-7d3dj.30.11) ──────────────────────────────
#[cfg(all(test, feature = "id-filter-fastpath"))]
mod idfast_unit {
    //! Differential + unit tests for the id-level `=`/`!=` FILTER fast path. [FABLE-5]
    //! (sq-7d3dj.30.11). The load-bearing invariant: for EVERY row and EVERY operand pair the
    //! fast path (path (a) static-non-literal id (in)equality + path (b) equal-id short-circuit)
    //! returns the IDENTICAL three-valued verdict as the exact term-materialising path
    //! (`term_of` + `values_equal`), which is the ground-truth SPARQL `=` semantics.
    use super::*;
    use oxrdf::{NamedNode, Variable};

    fn var(s: &str) -> Variable {
        Variable::new(s).unwrap()
    }
    fn nn(s: &str) -> NamedNode {
        NamedNode::new(s).unwrap()
    }
    fn bgp(tps: Vec<TriplePattern>) -> GraphPattern {
        GraphPattern::Bgp { patterns: tps }
    }
    fn tp_svo(s: &str, p: &str, o: TermPattern) -> TriplePattern {
        TriplePattern {
            subject: TermPattern::Variable(var(s)),
            predicate: NamedNodePattern::NamedNode(nn(p)),
            object: o,
        }
    }

    /// GROUND TRUTH for SPARQL `=`: materialise both operand terms and run the exact evaluator.
    /// `None` = type error (unbound / cross-family / ill-typed), `Some(b)` = decided boolean.
    fn reference_equal(graph: &Graph, local: &LocalVocab, ida: Id, idc: Id) -> Option<bool> {
        let x = match term_of(graph, local, ida) {
            Some(t) => Value::Term(t),
            None => Value::Unbound,
        };
        let y = match term_of(graph, local, idc) {
            Some(t) => Value::Term(t),
            None => Value::Unbound,
        };
        values_equal(&x, &y)
    }

    /// Run a `?a OP ?b` FILTER through the FULL compiled pipeline WITH the fast-path rewrite
    /// applied for the given non-literal column set, returning the per-row three-valued verdict.
    fn eval_filter_fast(
        graph: &Graph,
        local: &LocalVocab,
        b: &Bindings,
        expr: &Expression,
        nonlit_cols: &FxHashSet<usize>,
    ) -> Vec<Option<bool>> {
        let mut compiled = compile_expr(expr, b);
        idfast_rewrite(&mut compiled, nonlit_cols);
        b.rows
            .iter()
            .map(|row| ebv3(&eval_compiled(graph, local, b, row, &compiled).unwrap()))
            .collect()
    }

    /// A three-column table of ids: `?a`, `?b` (both compared), `?s` (an IRI subject anchor).
    /// Columns 0 and 1 are the compared operands; the test varies their id contents.
    fn table(rows: &[[Id; 2]]) -> Bindings {
        Bindings::unsorted(
            vec![var("a"), var("b")],
            rows.iter().map(|r| Row::from_slice(&[r[0], r[1]])).collect(),
        )
    }

    fn eq_expr() -> Expression {
        Expression::Equal(Box::new(Expression::Variable(var("a"))), Box::new(Expression::Variable(var("b"))))
    }
    fn ne_expr() -> Expression {
        Expression::Not(Box::new(eq_expr()))
    }
    fn eq_expr_xy() -> Expression {
        Expression::Equal(Box::new(Expression::Variable(var("x"))), Box::new(Expression::Variable(var("y"))))
    }

    /// A literal-heavy, mixed graph: IRIs, blank nodes, and literals including numeric-promotion
    /// pairs, whitespace-padded numerics, language tags, and cross-datatype pairs.
    fn mixed_graph() -> Graph {
        let nt = concat!(
            "<http://ex/s1> <http://ex/p> <http://ex/o1> .\n",
            "<http://ex/s2> <http://ex/p> _:b1 .\n",
            "<http://ex/s3> <http://ex/p> \"1\"^^<http://www.w3.org/2001/XMLSchema#integer> .\n",
            "<http://ex/s4> <http://ex/p> \"1.0\"^^<http://www.w3.org/2001/XMLSchema#decimal> .\n",
            "<http://ex/s5> <http://ex/p> \" 1 \"^^<http://www.w3.org/2001/XMLSchema#integer> .\n",
            "<http://ex/s6> <http://ex/p> \"hi\" .\n",
            "<http://ex/s7> <http://ex/p> \"hi\"@en .\n",
            "<http://ex/s8> <http://ex/p> \"1.0\"^^<http://www.w3.org/2001/XMLSchema#double> .\n",
            "<http://ex/s9> <http://ex/p> \"01\"^^<http://www.w3.org/2001/XMLSchema#integer> .\n",
            "<http://ex/s10> <http://ex/p> \"foo\"^^<http://ex/weird> .\n",
        );
        Graph::load_str(nt, "ntriples").unwrap()
    }

    /// Every object id in the mixed graph, so the differential test can pair each id with each.
    fn object_ids(g: &Graph) -> Vec<Id> {
        let mk = |t: Term| g.id_of(&t).unwrap();
        vec![
            mk(Term::NamedNode(nn("http://ex/o1"))),
            mk(Term::Literal(Literal::new_typed_literal("1", xsd::INTEGER))),
            mk(Term::Literal(Literal::new_typed_literal("1.0", xsd::DECIMAL))),
            mk(Term::Literal(Literal::new_typed_literal(" 1 ", xsd::INTEGER))),
            mk(Term::Literal(Literal::new_simple_literal("hi"))),
            mk(Term::Literal(Literal::new_language_tagged_literal("hi", "en").unwrap())),
            mk(Term::Literal(Literal::new_typed_literal("1.0", xsd::DOUBLE))),
            mk(Term::Literal(Literal::new_typed_literal("01", xsd::INTEGER))),
            mk(Term::Literal(Literal::new_typed_literal("foo", nn("http://ex/weird")))),
        ]
    }

    // ---- Static analysis (nonliteral_vars) -------------------------------------------------

    #[test]
    fn nonliteral_vars_subject_and_predicate_are_nonliteral() {
        // ?s in subject, ?p in predicate, ?o in object.
        let p = bgp(vec![TriplePattern {
            subject: TermPattern::Variable(var("s")),
            predicate: NamedNodePattern::Variable(var("p")),
            object: TermPattern::Variable(var("o")),
        }]);
        let nl = nonliteral_vars(&p, &|_| true);
        assert!(nl.contains(&var("s")), "subject var is non-literal");
        assert!(nl.contains(&var("p")), "predicate var is non-literal");
        assert!(!nl.contains(&var("o")), "object var CAN be a literal");
    }

    #[test]
    fn nonliteral_vars_subject_then_object_is_literal_risk() {
        // ?x in subject of pattern 1 AND object of pattern 2 -> could be a literal -> EXCLUDED.
        let p = bgp(vec![
            tp_svo("x", "http://ex/p", TermPattern::Variable(var("y"))),
            tp_svo("z", "http://ex/q", TermPattern::Variable(var("x"))),
        ]);
        let nl = nonliteral_vars(&p, &|_| true);
        assert!(!nl.contains(&var("x")), "a var used as an OBJECT anywhere is literal-risk");
        assert!(nl.contains(&var("z")), "?z only ever a subject -> non-literal");
    }

    #[test]
    fn nonliteral_vars_bind_and_values_are_literal_risk() {
        let inner = bgp(vec![tp_svo("s", "http://ex/p", TermPattern::Variable(var("o")))]);
        let ext = GraphPattern::Extend {
            inner: Box::new(inner),
            variable: var("s"), // BIND target shadows the subject -> literal-risk wins.
            expression: Expression::Literal(Literal::new_simple_literal("x")),
        };
        let nl = nonliteral_vars(&ext, &|_| true);
        assert!(!nl.contains(&var("s")), "a BIND target could be a literal");

        let values = GraphPattern::Values {
            variables: vec![var("v")],
            bindings: vec![vec![Some(GroundTerm::Literal(Literal::new_simple_literal("x")))]],
        };
        let j = GraphPattern::Join {
            left: Box::new(bgp(vec![tp_svo("v", "http://ex/p", TermPattern::Variable(var("o2")))])),
            right: Box::new(values),
        };
        let nl2 = nonliteral_vars(&j, &|_| true);
        assert!(!nl2.contains(&var("v")), "a VALUES column could be a literal");
    }

    #[test]
    fn nonliteral_vars_graph_name_is_nonliteral() {
        let inner = bgp(vec![tp_svo("s", "http://ex/p", TermPattern::Variable(var("o")))]);
        let g = GraphPattern::Graph { name: NamedNodePattern::Variable(var("g")), inner: Box::new(inner) };
        let nl = nonliteral_vars(&g, &|_| true);
        assert!(nl.contains(&var("g")), "a GRAPH-name var binds an IRI");
    }

    // ---- static analysis: soundness holes flagged in PR #1785 review ------------------------

    #[test]
    fn nonliteral_vars_path_object_is_literal_risk() {
        // A property-path OBJECT can bind a literal (the final step of an alternative/sequence is
        // an ordinary object slot). `?x (:p|:q) ?name` must NOT report ?name non-literal, and — to
        // be safe under Reverse / zero-length matches — must NOT report the subject ?x either
        // (unless a BGP positions it as a subject/predicate).
        let path = GraphPattern::Path {
            subject: TermPattern::Variable(var("x")),
            path: PropertyPathExpression::Alternative(
                Box::new(PropertyPathExpression::NamedNode(nn("http://ex/p"))),
                Box::new(PropertyPathExpression::NamedNode(nn("http://ex/q"))),
            ),
            object: TermPattern::Variable(var("name")),
        };
        let nl = nonliteral_vars(&path, &|_| true);
        assert!(!nl.contains(&var("name")), "a path OBJECT can be a literal");
        assert!(!nl.contains(&var("x")), "a path endpoint is not credited non-literal on its own");
    }

    #[test]
    fn nonliteral_vars_reverse_path_endpoints_are_literal_risk() {
        // Under Reverse the subject slot is the traversal OBJECT end, which can be a literal.
        let path = GraphPattern::Path {
            subject: TermPattern::Variable(var("s")),
            path: PropertyPathExpression::Reverse(Box::new(PropertyPathExpression::NamedNode(nn(
                "http://ex/p",
            )))),
            object: TermPattern::Variable(var("o")),
        };
        let nl = nonliteral_vars(&path, &|_| true);
        assert!(!nl.contains(&var("s")), "a Reverse-path subject end can be a literal");
        assert!(!nl.contains(&var("o")), "a Reverse-path object end can be a literal");
    }

    #[test]
    fn nonliteral_vars_union_with_unanalysable_branch_poisons() {
        // ?x is a SUBJECT in the left branch but bound by an un-analysed SERVICE in the right —
        // the SERVICE could bind it to a literal, so the subject occurrence must NOT win.
        let left = bgp(vec![tp_svo("x", "http://ex/p", TermPattern::Variable(var("o")))]);
        let service = GraphPattern::Service {
            name: NamedNodePattern::NamedNode(nn("http://remote/sparql")),
            inner: Box::new(bgp(vec![tp_svo("y", "http://ex/q", TermPattern::Variable(var("x")))])),
            silent: false,
        };
        let u = GraphPattern::Union { left: Box::new(left), right: Box::new(service) };
        let nl = nonliteral_vars(&u, &|_| true);
        assert!(!nl.contains(&var("x")), "a SERVICE-bound var must not be claimed non-literal via a sibling subject slot");
    }

    #[test]
    fn nonliteral_vars_quoted_triple_object_is_literal_risk() {
        // A quoted-triple subject `<<( ?s :p ?lit )>> :q ?o` carries an INNER object ?lit that can
        // be a literal — it must be literal-risk, not credited as a (subject-position) non-literal.
        let quoted = TermPattern::Triple(Box::new(TriplePattern {
            subject: TermPattern::Variable(var("s")),
            predicate: NamedNodePattern::NamedNode(nn("http://ex/p")),
            object: TermPattern::Variable(var("lit")),
        }));
        let p = bgp(vec![TriplePattern {
            subject: quoted,
            predicate: NamedNodePattern::NamedNode(nn("http://ex/q")),
            object: TermPattern::Variable(var("o")),
        }]);
        let nl = nonliteral_vars(&p, &|_| true);
        assert!(!nl.contains(&var("lit")), "an inner quoted-triple object can be a literal");
        assert!(!nl.contains(&var("s")), "a quoted-triple inner subject is not credited here");
    }

    #[test]
    fn differential_path_object_numeric_promotion_end_to_end() {
        // The concrete result-change the review found: two path OBJECTS holding value-equal but
        // id-DISTINCT numerics ("1"^^integer vs "1.0"^^decimal). `FILTER(?a = ?b)` must be TRUE
        // (numeric promotion) whether the feature is on or off — the fix keeps ?a/?b literal-risk
        // so path (a) declines and the exact value path runs.
        let nt = concat!(
            "<http://ex/s1> <http://ex/val> \"1\"^^<http://www.w3.org/2001/XMLSchema#integer> .\n",
            "<http://ex/s2> <http://ex/val> \"1.0\"^^<http://www.w3.org/2001/XMLSchema#decimal> .\n",
        );
        let g = Graph::load_str(nt, "ntriples").unwrap();
        // Path so the operands are PATH objects, exercising the G::Path arm's classification.
        let q = concat!(
            "SELECT ?a ?b WHERE { ",
            "?s1 <http://ex/val> ?a . ?s2 (<http://ex/val>|<http://ex/other>) ?b . ",
            "FILTER(?a = ?b) }"
        );
        let r = crate::query(&g, q).unwrap();
        // 1 = 1.0 by value -> every (a,b) pair over the two value-equal literals matches: 2x2 = 4.
        assert_eq!(r.rows.len(), 4, "numeric-promotion `=` over path objects must stay value-true");
    }

    #[test]
    fn differential_exists_nested_filter_no_column_leak() {
        // PR #1785 re-review: the id-fast column set installed for the OUTER FILTER must NOT leak
        // into an EXISTS-nested FILTER, whose columns index a DIFFERENT Bindings layout. The outer
        // FILTER is over IRI subject columns (?a, ?b — non-literal), but the nested EXISTS FILTER
        // is over two LITERAL columns (?v1, ?v2) holding value-equal, id-DISTINCT numerics
        // ("1"^^integer vs "1.0"^^decimal). If the outer set (cols {0,1}) leaked, the nested
        // `?v1 = ?v2` would rewrite to IdEqNonLit and evaluate FALSE (unequal ids), flipping EXISTS
        // to false; correct SPARQL is TRUE (numeric promotion). Must hold feature-ON.
        let nt = concat!(
            "<http://ex/s1> <http://ex/val> \"1\"^^<http://www.w3.org/2001/XMLSchema#integer> .\n",
            "<http://ex/s2> <http://ex/val> \"1.0\"^^<http://www.w3.org/2001/XMLSchema#decimal> .\n",
            "<http://ex/a> <http://ex/p> <http://ex/o1> .\n",
            "<http://ex/b> <http://ex/q> <http://ex/o2> .\n",
        );
        let g = Graph::load_str(nt, "ntriples").unwrap();
        // The OUTER pattern is a UNION (non-conjunctive), so its FILTER routes through the WRAPPED
        // dispatch that INSTALLS the id-fast column set (cols for ?a — an IRI subject). During that
        // filter's row loop the set is live; the EXISTS inner FILTER `?v1 = ?v2` (over two LITERAL
        // columns) re-enters on the same thread — pre-fix it would rewrite using the OUTER cols and
        // flip EXISTS to false. Post-fix (drain-on-consume + EXISTS empty-set guard) it stays TRUE.
        let q = concat!(
            "SELECT ?a WHERE { ",
            "{ ?a <http://ex/p> <http://ex/o1> } UNION { ?a <http://ex/q> <http://ex/o2> } ",
            "FILTER(EXISTS { ?s1 <http://ex/val> ?v1 . ?s2 <http://ex/val> ?v2 . FILTER(?v1 = ?v2) }) }"
        );
        let r = crate::query(&g, q).unwrap();
        // EXISTS is TRUE (1 = 1.0 by value), so both UNION rows (?a = ex:a, ex:b) survive.
        assert_eq!(r.rows.len(), 2, "EXISTS-nested numeric-promotion `=` must stay value-TRUE (no column-set leak)");
    }

    #[test]
    fn apply_filter_scalar_drains_installed_cols_before_nested_reentry() {
        // Directly exercises the drain-on-consume invariant that fixes the EXISTS-re-entry leak
        // (PR #1785 re-review): the installed set is valid ONLY for the Bindings it was computed
        // against, and `eval_compiled` can re-enter FILTER evaluation (via EXISTS) DURING the outer
        // filter's row loop — while the outer set is still installed (the restore-guard has not yet
        // run). If the set were merely BORROWED (not drained before the loop), that nested filter
        // would apply the OUTER column indices to a DIFFERENT Bindings layout.
        //
        // We model exactly that window: install {0,1}, and while it is installed run a NESTED
        // `apply_filter_scalar` over LITERAL columns at the same indices {0,1} (value-equal,
        // id-distinct "1"^^integer / "1.0"^^decimal). The nested filter must NOT see {0,1} — it
        // must take the exact numeric-promotion path and KEEP the row. A stale {0,1} would rewrite
        // `?x = ?y` to IdEqNonLit and DROP it.
        let g = mixed_graph();
        let local = LocalVocab::default();
        let ids = object_ids(&g); // ids[1]="1"^^integer, ids[2]="1.0"^^decimal (value-equal)
        let s1 = g.id_of(&Term::NamedNode(nn("http://ex/s1"))).unwrap();

        let mut outer = Bindings::unsorted(vec![var("x"), var("y")], vec![Row::from_slice(&[s1, s1])]);
        with_idfast_nonlit_cols([0usize, 1usize].into_iter().collect(), || {
            // The OUTER consuming call drains the set to empty BEFORE its row loop.
            apply_filter_scalar(&g, &local, &mut outer, &eq_expr_xy()).unwrap();
            // Simulate an EXISTS re-entry that happens WHILE the guard is still live (i.e. before
            // the `with_` scope exits): a nested filter over literal columns at indices {0,1}.
            let mut nested =
                Bindings::unsorted(vec![var("x"), var("y")], vec![Row::from_slice(&[ids[1], ids[2]])]);
            apply_filter_scalar(&g, &local, &mut nested, &eq_expr_xy()).unwrap();
            assert_eq!(
                nested.rows.len(),
                1,
                "1 = 1.0 by value must survive — the outer set must have been DRAINED, not leaked into re-entry"
            );
        });
        assert_eq!(outer.rows.len(), 1, "s1 = s1 keeps the outer row");
    }

    // ---- equal_idfast unit behaviour -------------------------------------------------------

    #[test]
    fn equal_idfast_unbound_column_is_type_error() {
        let g = mixed_graph();
        let row = [NO_ID, 5u32];
        // A COLUMN holding NO_ID is unbound -> type error, not false.
        let v = equal_idfast(&g, &row, &IdOperand::Col(0), &IdOperand::Col(1));
        assert!(matches!(v, Value::Error), "unbound operand must be a type error");
    }

    #[test]
    fn equal_idfast_absent_const_iri_is_false_not_error() {
        let g = mixed_graph();
        let ids = object_ids(&g);
        let row = [ids[0], 0]; // ids[0] = <http://ex/o1>
        // A constant IRI absent from the dict resolves to NO_ID but is NOT unbound -> "never equal".
        let absent = IdOperand::ConstIri(nn("http://ex/NOT_IN_GRAPH"));
        let v = equal_idfast(&g, &row, &IdOperand::Col(0), &absent);
        assert!(matches!(v, Value::Bool(false)), "absent const IRI compares as not-equal, not error");
    }

    #[test]
    fn equal_idfast_iri_identity() {
        let g = mixed_graph();
        let ids = object_ids(&g);
        let row = [ids[0], ids[0]];
        assert!(matches!(equal_idfast(&g, &row, &IdOperand::Col(0), &IdOperand::Col(1)), Value::Bool(true)));
        let row2 = [ids[0], ids[7]]; // o1 vs "01"^^integer literal id — different ids
        assert!(matches!(equal_idfast(&g, &row2, &IdOperand::Col(0), &IdOperand::Col(1)), Value::Bool(false)));
    }

    // ---- DIFFERENTIAL: fast path vs ground-truth exact semantics, every id pair --------------

    #[test]
    fn differential_static_nonliteral_pairs_iri_only() {
        // When both columns are STATICALLY non-literal, only IRI/bnode ids ever appear. Pair the
        // IRI/bnode ids of the mixed graph and assert fast == exact for `=` and `!=`.
        let g = mixed_graph();
        let local = LocalVocab::default();
        let iri_bnode: Vec<Id> = {
            let s = |t: Term| g.id_of(&t).unwrap();
            vec![
                s(Term::NamedNode(nn("http://ex/s1"))),
                s(Term::NamedNode(nn("http://ex/o1"))),
                s(Term::NamedNode(nn("http://ex/p"))),
                s(Term::NamedNode(nn("http://ex/s2"))),
            ]
        };
        let mut rows = Vec::new();
        for &a in &iri_bnode {
            for &c in &iri_bnode {
                rows.push([a, c]);
            }
        }
        let b = table(&rows);
        // Columns 0 and 1 are both non-literal.
        let nonlit: FxHashSet<usize> = [0usize, 1usize].into_iter().collect();

        for expr in [eq_expr(), ne_expr()] {
            let negated = matches!(expr, Expression::Not(_));
            let fast = eval_filter_fast(&g, &local, &b, &expr, &nonlit);
            for (i, row) in b.rows.iter().enumerate() {
                let mut want = reference_equal(&g, &local, row[0], row[1]);
                if negated {
                    want = want.map(|x| !x);
                }
                assert_eq!(fast[i], want, "row {} ids ({},{}) negated={}", i, row[0], row[1], negated);
            }
        }
    }

    #[test]
    fn differential_equal_id_shortcircuit_all_kinds() {
        // Path (b): when both columns hold the SAME id (any kind, incl. weird/ill-typed literals),
        // `=` must be true and `!=` false — matching the ground-truth sameTerm decision. Here the
        // columns are NOT declared non-literal (empty nonlit set), so ONLY path (b) can fire.
        let g = mixed_graph();
        let local = LocalVocab::default();
        let ids = object_ids(&g);
        let rows: Vec<[Id; 2]> = ids.iter().map(|&x| [x, x]).collect();
        let b = table(&rows);
        let empty: FxHashSet<usize> = FxHashSet::default();

        for expr in [eq_expr(), ne_expr()] {
            let negated = matches!(expr, Expression::Not(_));
            let fast = eval_filter_fast(&g, &local, &b, &expr, &empty);
            for (i, row) in b.rows.iter().enumerate() {
                let mut want = reference_equal(&g, &local, row[0], row[1]);
                if negated {
                    want = want.map(|x| !x);
                }
                assert_eq!(fast[i], want, "equal-id row {} id {}", i, row[0]);
            }
        }
    }

    #[test]
    fn differential_unequal_literal_ids_take_exact_path() {
        // The sq-lr2ii caution: unequal ids of VALUE-EQUAL literals ("1"^^integer, "1.0"^^decimal,
        // " 1 "^^integer, "01"^^integer, "1.0"^^double) must NOT be decided by the id fast path —
        // they must fall through to the exact value comparison. Columns are literal-capable (empty
        // nonlit set), so path (a) is off and path (b) can't fire on unequal ids; the result must
        // match the exact numeric-promotion semantics.
        let g = mixed_graph();
        let local = LocalVocab::default();
        let ids = object_ids(&g);
        let mut rows = Vec::new();
        for &a in &ids {
            for &c in &ids {
                if a != c {
                    rows.push([a, c]);
                }
            }
        }
        let b = table(&rows);
        let empty: FxHashSet<usize> = FxHashSet::default();

        for expr in [eq_expr(), ne_expr()] {
            let negated = matches!(expr, Expression::Not(_));
            let fast = eval_filter_fast(&g, &local, &b, &expr, &empty);
            for (i, row) in b.rows.iter().enumerate() {
                let mut want = reference_equal(&g, &local, row[0], row[1]);
                if negated {
                    want = want.map(|x| !x);
                }
                assert_eq!(
                    fast[i], want,
                    "unequal-id literal row {} ids ({},{}) must match exact semantics",
                    i, row[0], row[1]
                );
            }
        }
    }

    #[test]
    fn differential_end_to_end_q08_shape() {
        // A q08-like UNION-branch FILTER over IRI subject vars, run through the PUBLIC query
        // entry point (which installs the static analysis + fast path). The answer must be
        // correct regardless of the fast path — an independent recompute of the expected set.
        let nt = concat!(
            "<http://ex/d1> <http://ex/creator> <http://ex/alice> .\n",
            "<http://ex/d1> <http://ex/creator> <http://ex/bob> .\n",
            "<http://ex/d2> <http://ex/creator> <http://ex/alice> .\n",
        );
        let g = Graph::load_str(nt, "ntriples").unwrap();
        // Pairs of DISTINCT co-creators of the same document (?a != ?b over IRI subjects/objects
        // of a creator triple — the != is exactly id inequality here).
        let q = concat!(
            "SELECT ?a ?b WHERE { ",
            "?doc <http://ex/creator> ?a . ?doc <http://ex/creator> ?b . ",
            "FILTER(?a != ?b) }"
        );
        let r = crate::query(&g, q).unwrap();
        assert_eq!(r.rows.len(), 2, "alice/bob and bob/alice for d1 only");
        for row in &r.rows {
            assert_ne!(row[0], row[1], "the != filter must exclude self-pairs");
        }
    }

    // ---- sq-1ivw7: predicate-range object term-kind widening -------------------------------

    /// The q08/q12b-shaped store: `creator` is IRI-only (unblockable), `title`/`year` carry
    /// literal objects (must decline). Includes a bnode creator object (still literal-free).
    fn predrange_graph() -> Graph {
        let nt = concat!(
            "<http://ex/d1> <http://ex/creator> <http://ex/alice> .\n",
            "<http://ex/d1> <http://ex/creator> <http://ex/bob> .\n",
            "<http://ex/d2> <http://ex/creator> _:anon .\n",
            "<http://ex/d1> <http://ex/title> \"A Paper\" .\n",
            "<http://ex/d1> <http://ex/year> \"2020\"^^<http://www.w3.org/2001/XMLSchema#integer> .\n",
        );
        Graph::load_str(nt, "ntriples").unwrap()
    }

    /// Does `nonliteral_filter_cols` prove `col` (a column of `b`) non-literal for the FILTER over
    /// `inner`, in the snapshot `g`? Exercises the REAL snapshot-aware analysis path.
    fn col_is_nonliteral(g: &Graph, inner: &GraphPattern, b: &Bindings, col: usize) -> bool {
        nonliteral_filter_cols(g, inner, b).contains(&col)
    }

    #[test]
    fn predrange_credits_iri_only_object_declines_literal() {
        let g = predrange_graph();
        // `?a` bound ONLY as the object of a constant literal-free predicate `creator`.
        let inner = bgp(vec![tp_svo("doc", "http://ex/creator", TermPattern::Variable(var("a")))]);
        let b = Bindings::unsorted(vec![var("doc"), var("a")], vec![]);
        // `?a` is column 1; the snapshot-aware analysis must prove it non-literal.
        assert!(
            col_is_nonliteral(&g, &inner, &b, b.col(&var("a")).unwrap()),
            "an object of a literal-free constant predicate must be credited non-literal"
        );
        // `?t` bound as object of `title` (has a literal object) must DECLINE.
        let inner_t = bgp(vec![tp_svo("doc", "http://ex/title", TermPattern::Variable(var("t")))]);
        let bt = Bindings::unsorted(vec![var("doc"), var("t")], vec![]);
        assert!(
            !col_is_nonliteral(&g, &inner_t, &bt, bt.col(&var("t")).unwrap()),
            "an object of a literal-having predicate must NOT be credited"
        );
        // `?y` bound as object of `year` (inline-integer literal object) must DECLINE.
        let inner_y = bgp(vec![tp_svo("doc", "http://ex/year", TermPattern::Variable(var("y")))]);
        let by = Bindings::unsorted(vec![var("doc"), var("y")], vec![]);
        assert!(
            !col_is_nonliteral(&g, &inner_y, &by, by.col(&var("y")).unwrap()),
            "an inline-integer literal object predicate must NOT be credited"
        );
    }

    #[test]
    fn predrange_mixed_use_of_same_var_declines() {
        // `?x` is the object of literal-free `creator` in one triple but the object of `title`
        // (literal-having) in another. It CAN be a literal, so it must NOT be credited — the
        // `nonlit \ maybe_lit` difference must exclude it.
        let g = predrange_graph();
        let inner = bgp(vec![
            tp_svo("d1", "http://ex/creator", TermPattern::Variable(var("x"))),
            tp_svo("d2", "http://ex/title", TermPattern::Variable(var("x"))),
        ]);
        let b = Bindings::unsorted(vec![var("d1"), var("d2"), var("x")], vec![]);
        assert!(
            !col_is_nonliteral(&g, &inner, &b, b.col(&var("x")).unwrap()),
            "a var used as a literal-having-predicate object anywhere must decline"
        );
    }

    #[test]
    fn predrange_variable_predicate_declines() {
        // A VARIABLE predicate is not a constant IRI, so the snapshot check cannot apply and the
        // object stays literal-risk (the store could bind ?p to a literal-having predicate).
        let g = predrange_graph();
        let inner = bgp(vec![TriplePattern {
            subject: TermPattern::Variable(var("doc")),
            predicate: NamedNodePattern::Variable(var("p")),
            object: TermPattern::Variable(var("a")),
        }]);
        let b = Bindings::unsorted(vec![var("doc"), var("p"), var("a")], vec![]);
        assert!(
            !col_is_nonliteral(&g, &inner, &b, b.col(&var("a")).unwrap()),
            "a variable-predicate object must stay literal-risk"
        );
    }

    #[test]
    fn predrange_fires_on_q08_shape_witness() {
        // WITNESS that path (a) now FIRES on the q08/q12b shape: `?a`/`?b` are objects of the
        // literal-free `creator` predicate, so `nonliteral_filter_cols` proves both columns
        // non-literal and `idfast_rewrite` rewrites `?a = ?b` into `IdEqNonLit`. (Under #1785 this
        // declined — the honest null result this bead closes.)
        let g = predrange_graph();
        let inner = bgp(vec![
            tp_svo("doc", "http://ex/creator", TermPattern::Variable(var("a"))),
            tp_svo("doc", "http://ex/creator", TermPattern::Variable(var("b"))),
        ]);
        let b = Bindings::unsorted(vec![var("doc"), var("a"), var("b")], vec![]);
        let cols = nonliteral_filter_cols(&g, &inner, &b);
        assert!(cols.contains(&b.col(&var("a")).unwrap()), "?a credited");
        assert!(cols.contains(&b.col(&var("b")).unwrap()), "?b credited");
        // The rewrite converts `?a = ?b` into the id fast path.
        let expr = Expression::Equal(
            Box::new(Expression::Variable(var("a"))),
            Box::new(Expression::Variable(var("b"))),
        );
        let mut compiled = compile_expr(&expr, &b);
        idfast_rewrite(&mut compiled, &cols);
        assert!(
            matches!(compiled, CompiledExpr::IdEqNonLit(..)),
            "the q08-shape `=` must compile to the id fast path; got {:?}",
            compiled
        );
    }

    #[test]
    fn predrange_end_to_end_q08_result_unchanged() {
        // Full public-entry differential: the fast path fires (previous test), yet the ANSWER is an
        // independent recompute — distinct co-creator IRI pairs of the same document.
        let g = predrange_graph();
        let q = concat!(
            "SELECT ?a ?b WHERE { ",
            "?doc <http://ex/creator> ?a . ?doc <http://ex/creator> ?b . ",
            "FILTER(?a != ?b) }"
        );
        let r = crate::query(&g, q).unwrap();
        // d1 has {alice, bob}; d2 has {_:anon} alone. Distinct ordered pairs for d1: (alice,bob),(bob,alice).
        assert_eq!(r.rows.len(), 2, "distinct co-creator pairs of d1 only");
        for row in &r.rows {
            assert_ne!(row[0], row[1], "!= excludes self-pairs");
        }
    }

    #[test]
    fn predrange_snapshot_update_flips_credit() {
        // The snapshot-lifecycle invariant end-to-end: `creator` is literal-free -> credited; an
        // UPDATE inserting a literal creator object publishes a new snapshot in which the same
        // analysis DECLINES. Proves the credit never outlives the snapshot it was computed against.
        let mut g = predrange_graph();
        let inner = bgp(vec![tp_svo("doc", "http://ex/creator", TermPattern::Variable(var("a")))]);
        let b = Bindings::unsorted(vec![var("doc"), var("a")], vec![]);
        let a_col = b.col(&var("a")).unwrap();
        assert!(col_is_nonliteral(&g, &inner, &b, a_col), "literal-free before update -> credited");
        // UPDATE: a literal object now exists for `creator`.
        g.apply_delta(
            &[[
                Term::NamedNode(nn("http://ex/d3")),
                Term::NamedNode(nn("http://ex/creator")),
                Term::Literal(Literal::new_simple_literal("Anonymous")),
            ]],
            &[],
        )
        .unwrap();
        assert!(
            !col_is_nonliteral(&g, &inner, &b, a_col),
            "after the update the same analysis must DECLINE against the new snapshot"
        );
        // And the end-to-end result stays correct across the update (exact path now runs for `!=`).
        let q = concat!(
            "SELECT ?a ?b WHERE { ",
            "?doc <http://ex/creator> ?a . ?doc <http://ex/creator> ?b . ",
            "FILTER(?a != ?b) }"
        );
        let r = crate::query(&g, q).unwrap();
        for row in &r.rows {
            assert_ne!(row[0], row[1], "!= still excludes self-pairs post-update");
        }
    }

    /// A default graph whose `creator` predicate is LITERAL-FREE, plus a named graph `<http://ex/g>`
    /// whose `creator` objects are a `xsd:integer`/`xsd:decimal` pair that are `=`-equal by VALUE.
    /// Loaded via TriG so `.named` is populated (a named graph is a self-contained sub-`Graph`).
    fn cross_graph_dataset() -> Graph {
        let trig = concat!(
            "<http://ex/d0> <http://ex/creator> <http://ex/alice> .\n",
            "<http://ex/g> {\n",
            "  <http://ex/d1> <http://ex/creator> \"1\"^^<http://www.w3.org/2001/XMLSchema#integer> .\n",
            "  <http://ex/d1> <http://ex/creator> \"1.0\"^^<http://www.w3.org/2001/XMLSchema#decimal> .\n",
            "}\n",
        );
        Graph::load_dataset(trig, "trig").unwrap()
    }

    #[test]
    fn predrange_graph_block_declines_object_credit_at_outer_dispatch() {
        // ANALYSIS-LEVEL decline witness for the cross-graph hole (PR #1795 reviewer counterexample).
        // The FILTER sits OUTSIDE the GRAPH block, so `nonliteral_filter_cols` classifies against the
        // DEFAULT graph — whose `creator` column is literal-free. But `?a`/`?b` are bound from INSIDE
        // `GRAPH <http://ex/g>`, a DIFFERENT store carrying literal objects. Crediting them off the
        // default column would be unsound. After the fix (`G::Graph` recurses with `&|_| true`), the
        // outer dispatch gives an object var under any GRAPH block NO credit.
        let g = cross_graph_dataset();
        let inner = GraphPattern::Graph {
            name: NamedNodePattern::NamedNode(nn("http://ex/g")),
            inner: Box::new(bgp(vec![
                tp_svo("d", "http://ex/creator", TermPattern::Variable(var("a"))),
                tp_svo("d", "http://ex/creator", TermPattern::Variable(var("b"))),
            ])),
        };
        let b = Bindings::unsorted(vec![var("d"), var("a"), var("b")], vec![]);
        let cols = nonliteral_filter_cols(&g, &inner, &b);
        assert!(
            !cols.contains(&b.col(&var("a")).unwrap()),
            "?a bound under GRAPH must NOT be credited at the outer (default-graph) dispatch"
        );
        assert!(
            !cols.contains(&b.col(&var("b")).unwrap()),
            "?b bound under GRAPH must NOT be credited at the outer (default-graph) dispatch"
        );
    }

    #[test]
    fn predrange_cross_graph_filter_result_identical() {
        // END-TO-END differential (feature ON) for the reviewer's exact counterexample. `?a`/`?b`
        // are `"1"^^xsd:integer` and `"1.0"^^xsd:decimal` bound inside `GRAPH <http://ex/g>`; the
        // FILTER sits outside. `=` is VALUE equality, so `1 = 1.0` holds and all 4 ordered pairs
        // (2×2) qualify. Before the fix the object credit fired off the default graph's literal-free
        // column, the pair was id-compared, and only the 2 self-pairs survived (RED: 2 != 4).
        let g = cross_graph_dataset();
        let q = concat!(
            "SELECT ?a ?b WHERE { ",
            "GRAPH <http://ex/g> { ?d <http://ex/creator> ?a . ?d <http://ex/creator> ?b } ",
            "FILTER(?a = ?b) }"
        );
        let r = crate::query(&g, q).unwrap();
        assert_eq!(
            r.rows.len(),
            4,
            "value `=` matches the integer/decimal pair: all 4 ordered pairs qualify (feature ON must equal OFF)"
        );
    }

    // ---- MUTATION check: a deliberately-wrong fast result must be caught by the differential ---

    #[test]
    fn mutation_wrong_shortcircuit_would_be_caught() {
        // Sanity that the differential oracle is non-vacuous: an INVERTED fast verdict on an
        // equal-id pair disagrees with the reference. (We assert the disagreement directly rather
        // than mutate production code.)
        let g = mixed_graph();
        let local = LocalVocab::default();
        let ids = object_ids(&g);
        let id = ids[4]; // "hi" simple literal
        let correct = equal_idfast(&g, &[id, id], &IdOperand::Col(0), &IdOperand::Col(1));
        assert!(matches!(correct, Value::Bool(true)));
        // The reference agrees with the correct verdict...
        assert_eq!(reference_equal(&g, &local, id, id), Some(true));
        // ...so an inverted verdict (false) would be a detectable mismatch.
        let mutated = Value::Bool(false);
        assert_ne!(
            ebv3(&mutated),
            reference_equal(&g, &local, id, id),
            "an inverted equal-id verdict must disagree with the oracle"
        );
    }
}

// ── order_bindings parallel worker reinstall regression (sq-6aefu) ─────────────────────────────
//
// Both PAR_THRESHOLD key-build sites (top-k index-carry AND full stable sort) must snapshot +
// re-install functions / view / spatial on rayon workers, mirroring the FILTER/BIND/aggregates
// pattern that sq-98w7z.1 established for query_now.  Without the reinstall:
//   (1) EXISTS in ORDER BY re-enters pattern evaluation on workers with NO DatasetView →
//       named-graph visibility leaks into sort keys (security-adjacent, silent wrong order).
//   (2) A custom extension function in ORDER BY loses the FunctionRegistry on workers →
//       `eval_function` returns Err("unsupported") → the whole ORDER BY call fails.
//
// The tests below are gated on `parallel` (the rayon path is feature-gated) and exercise
// BOTH sites via the engine's normal SPARQL query entry points:
//   - `query_view_with_budget` for the view/EXISTS scenario
//   - `query_with_functions_and_budget` for the FunctionRegistry scenario
//
// NON-VACUITY: each test was confirmed to FAIL (red) on the un-patched exec.rs (fix stashed)
// and PASS (green) after the patch, satisfying the acceptance criterion.  The failure mode
// without the fix is documented in each test's doc-comment.
#[cfg(all(test, feature = "parallel"))]
mod order_bindings_worker_reinstall {
    use super::*;
    use std::sync::Arc;

    /// Build an N-row nquads dataset: default-graph rows `<s{i}> <p> <o{i}>` plus one
    /// triple in a named graph `<http://ex/hidden>` so EXISTS can find it when no view
    /// is restricting access.
    fn par_dataset_with_hidden_graph(n: usize) -> sparq_core::Graph {
        let mut nq = String::with_capacity(n * 60 + 80);
        for i in 0..n {
            nq.push_str(&format!("<http://ex/s{i}> <http://ex/p> <http://ex/o{i}> .\n"));
        }
        nq.push_str("<http://ex/hs> <http://ex/hp> <http://ex/ho> <http://ex/hidden> .\n");
        sparq_core::Graph::load_dataset(&nq, "nquads").unwrap()
    }

    /// ORDER BY with EXISTS under a restricted DatasetView — >= PAR_THRESHOLD rows.
    ///
    /// Setup: the named graph `<http://ex/hidden>` contains a triple, but the installed
    /// DatasetView exposes an EMPTY named-graph set, so `GRAPH <http://ex/hidden>` must
    /// be invisible.
    ///
    /// The ORDER BY expression is:
    ///   `IF(EXISTS { GRAPH <http://ex/hidden> { ?a ?b ?c } }, "constant_key", STR(?s))`
    ///
    /// Correct behaviour (view propagated to workers):
    ///   EXISTS = false → sort key = STR(?s) → ascending lexicographic order by subject IRI.
    ///
    /// Bug behaviour (view NOT propagated to workers, pre-fix):
    ///   EXISTS = true on worker threads → sort key = "constant_key" for every row →
    ///   stable sort preserves scan/insertion order, which is numeric (s0,s1,s2,…), NOT
    ///   lexicographic (s0,s1,s10,s100,…) — observable mismatch for N >= 10.
    ///
    /// NON-VACUITY CONFIRMED: stashing the fix and running produces
    ///   `subjects != expected_lex_sorted` → assertion fires → RED on the bug. [SONNET-4.6]
    #[test]
    fn order_by_exists_restricted_view_parallel_matches_lex_sort() {
        let n = PAR_THRESHOLD + 100; // triggers both PAR_THRESHOLD parallel paths
        let g = par_dataset_with_hidden_graph(n);

        // View: empty named set → <http://ex/hidden> is NOT accessible.
        let view = crate::DatasetView {
            base: &g,
            named: Arc::new(crate::FxHashSet::default()),
            default: crate::DefaultGraphMode::StoreDefault,
        };

        // ORDER BY: sort by STR(?s) when EXISTS is false (view active), else constant tie.
        let query = "SELECT ?s WHERE { ?s <http://ex/p> ?o } \
                     ORDER BY IF(EXISTS { GRAPH <http://ex/hidden> { ?a ?b ?c } }, \
                                 \"constant_key\", STR(?s))";

        let result = crate::query_view_with_budget(
            &view,
            query,
            &crate::QueryBudget::unlimited(),
        )
        .unwrap();
        assert_eq!(result.len(), n, "all {n} default-graph rows must survive the query");

        // Collect the subject IRIs in the ORDER BY result.
        // `term.to_string()` yields `<http://ex/sN>` (N3 notation, with angle brackets).
        let subjects: Vec<String> = result.rows.iter()
            .map(|row| row[0].clone().unwrap().to_string())
            .collect();

        // Oracle: the expected output is ascending lexicographic order of STR(?s).
        // SPARQL's STR(?s) on a NamedNode strips angle brackets, producing "http://ex/sN".
        // Lex order of "http://ex/s0".."http://ex/s{n-1}" differs from numeric insertion order
        // for any n > 10: "…/s0","…/s1","…/s10","…/s100",… ≠ "…/s0","…/s1","…/s2","…/s3",…
        //
        // IMPORTANT: do NOT use `subjects.sort()` here — Rust's byte-lex sort of the N3
        // representation "<http://ex/sN>" differs from SPARQL's STR(?s) sort because `>`
        // (ASCII 62) > `0`-`9` (48-57): "<http://ex/s10000>" sorts before "<http://ex/s1>"
        // (since `>` at the end of the shorter IRI is a higher byte than `0`).  Instead,
        // sort by the bare IRI value (strip angle brackets) to match STR(?s) collation.
        let iri_key = |s: &str| -> String {
            s.strip_prefix('<').unwrap_or(s).strip_suffix('>').unwrap_or(s).to_owned()
        };
        let mut expected = subjects.clone();
        expected.sort_by_key(|s| iri_key(s));
        assert_eq!(
            subjects, expected,
            "ORDER BY EXISTS under restricted view (>= PAR_THRESHOLD rows) must sort by \
             STR(?s) — worker view reinstall gap lets EXISTS return true on workers, \
             collapsing all sort keys to a constant and exposing the hidden named graph"
        );
    }

    /// ORDER BY with a custom extension function — >= PAR_THRESHOLD rows.
    ///
    /// Without the fix, rayon workers have no FunctionRegistry installed:
    ///   `functions::lookup("http://test/noop")` returns `None`
    ///   → `eval_function` returns `Err("unsupported SPARQL function: …")`
    ///   → `order_bindings` propagates the `Err`
    ///   → the query fails with a hard error.
    ///
    /// With the fix, workers get the snapshotted registry:
    ///   → lookup succeeds → sort key is the custom function's output → query succeeds.
    ///
    /// NON-VACUITY CONFIRMED: stashing the fix produces:
    ///   `Err("unsupported SPARQL function: Custom(http://test/noop)")` → `.expect()` panics
    ///   → RED. [SONNET-4.6]
    #[test]
    fn order_by_custom_fn_parallel_no_spurious_registry_error() {
        let n = PAR_THRESHOLD + 100;
        let mut nq = String::with_capacity(n * 60);
        for i in 0..n {
            nq.push_str(&format!("<http://ex/s{i}> <http://ex/p> <http://ex/o{i}> .\n"));
        }
        let g = sparq_core::Graph::load_dataset(&nq, "nquads").unwrap();

        // A simple custom identity function — any custom IRI triggers the registry lookup.
        let mut reg = crate::FunctionRegistry::new();
        reg.register("http://test/noop", |args: &[oxrdf::Term]| {
            Ok(args[0].clone()) // [SONNET-4.6]
        });

        // ORDER BY <custom>(?s): forces workers to call eval_function → registry lookup.
        let query = "SELECT ?s WHERE { ?s <http://ex/p> ?o } ORDER BY <http://test/noop>(?s)";

        let result = crate::query_with_functions_and_budget(
            &g,
            query,
            &reg,
            &crate::QueryBudget::unlimited(),
        )
        .expect(
            "ORDER BY custom-function over >= PAR_THRESHOLD rows must not fail \
             (worker FunctionRegistry reinstall missing?)"
        );

        assert_eq!(
            result.len(),
            n,
            "all {n} rows must survive ORDER BY with custom function on parallel dataset"
        );
    }
}
